pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Exact fit: perfect placement, strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space classes: residuals too small for the minimum item size are wasted.
    // Harmonic class of post_residual via integer division into capacity eighths.
    let eighth = (bin_capacity / 8).max(1);
    let class = (post_residual / eighth) as f64; // 0..=8 harmonic class

    // Penalize the lowest (most unusable) classes, but not exact zero.
    if post_residual > 0 && post_residual < 10 {
        score += 400.0; // dead space below minimum item size
    } else if post_residual > 0 {
        score -= class * 6.0; // reward larger, more reusable residuals
    }

    // Lookahead: reward residuals that can still host the next item (modular match).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 60.0;
        // Bonus if residual is a near-multiple of next item's size (harmonic resonance).
        let r = post_residual % next_item_size.max(1);
        if r == 0 {
            score -= 25.0;
        } else if r < 10 {
            score += 15.0; // leaves a dead sliver after next placement
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Residual cannot host next item: mild penalty scaled by how close it is.
        let gap = (next_item_size - post_residual) as f64;
        score += (gap * 0.8).min(80.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a bin unless current residuals are fragmented.
    if bin_residual == bin_capacity {
