        if item_size as f64 > 0.5 * cap {
            score -= 30.0;
        }
    }

    // Mild preference for bins tighter than the mean (best-fit flavor).
    score += ((bin_residual as f64 - mean_residual) * 0.3).max(0.0);

    // Small penalty per open bin to encourage consolidation when residuals are ample.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
