    let pressure = open_bins_count as f64 / (1.0 + total_items as f64);
    score += 25.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Mean-residual coupling: bins far below mean residual are less attractive.
    score += 0.2 * (mean_residual - post_residual as f64).max(0.0);

    // New-bin candidate handling: prefer it only when no open bin offers a tight fit.
    if bin_residual == bin_capacity {
        // Baseline competitive score; tight fits (score < ~0) beat it, poor fits don't.
        score = 5.0 + 0.1 * item_size as f64;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
    }

    score
}

