pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tighter fit (smaller post_residual) is better.

    // Aggressive 2-step lookahead: if the next item fits exactly into the
    // post-residual, strongly reward this bin (perfect chain).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item fits, but leaves a leftover; reward proportionally
            // to how much space remains for future items.
            let leftover = (post_residual - next_item_size) as f64;
            score -= 30.0 - 0.3 * leftover;
        } else {
            // Next item does NOT fit after this placement: penalize,
            // scaled by how badly it misses.
            let miss = (next_item_size - post_residual) as f64;
            score += 5.0 + 0.4 * miss;
        }
    }

    // Penalize creating tiny unusable dead space (waste fragments).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Perfect fill reward.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Relative-to-mean coupling: bins with residual far below the mean
    // (already tight) are good targets; above-mean residual bins are
    // penalized slightly so we don't fragment large-capacity bins.
    let rel = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 10.0 * rel;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Early in the stream, be more willing to open fresh bins for large
    // items to preserve flexibility; later, consolidate tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: prefer it when the item is large and few bins fit.
        let large_item_bonus = (item_size as f64 / bin_capacity as f64) * 20.0;
        score -= large_item_bonus * (1.0 - progress) + (fitting_bins_count as f64) * 3.0;
        // But penalize opening new bins late in the stream.
        score += 15.0 * progress;
    }

    // Mild penalty per open bin to encourage consolidation overall.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues in (0,10] are dead space.
    let dead = post_residual > 0 && post_residual < 10;
    if dead {
        score += 25.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Does the bin still fit the lookahead item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward residual that stays useful, scaled by how well it
            // matches the next item (tight-but-usable is best).
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 - (slack / 20.0).min(6.0);
        } else {
            // Residual cannot host the next item: penalize by wasted amount.
            score += (next_item_size - post_residual) as f64 * 0.35;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New empty bin candidate: neutral-ish baseline; only attractive when
    // the item is large or open bins are nearly full on average.
    if bin_residual == bin_capacity {
        score = 45.0
            - (item_size as f64 - 50.0) * 0.4
            - mean_residual * 0.15
            - (open_bins_count as f64 * 0.5);
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            score -= 5.0; // new bin can host the pair
        }
    }

    // Late in the stream, prefer consolidating into open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Harmonic modulo bonus: post_residual divisible by common item classes.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // classes (multiples of common small sizes) are rewarded.
    let pr = post_residual;
    if pr > 0 {
        let class_score: f64 = if pr % 10 == 0 {
            -6.0 // perfectly harmonious residual
        } else if pr % 5 == 0 {
            -3.0
        } else if pr % 3 == 0 {
            -1.0
        } else if pr % 2 == 0 {
            0.5
        } else {
            2.0 // odd prime-ish dead space is bad
        };
        score += class_score;

        // Integer-division threshold: residual bucket size
        let bucket = pr / 10; // 0..10 buckets
        score -= bucket as f64 * 0.8;
    } else {
        score -= 12.0; // perfect fill, strongly preferred
    }

    // Lookahead coupling: can next item fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 15.0; // perfect chain
        } else if next_item_size <= pr {
            let slack = pr - next_item_size;
            score -= 4.0 - (slack as f64) * 0.15;
            // harmonic match between next item and residual
            if pr % next_item_size.max(1) == 0 {
                score -= 3.0;
            }
        } else {
            // next item won't fit here: residual becomes dead space risk
            let dead = pr.min(next_item_size - 1);
            score += dead as f64 * 0.05;
        }
    }

    // Tightness reward
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= tightness * 8.0;

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowding = open_bins_count as f64 / (mean_residual / bin_capacity as f64).max(0.05);
        score += 25.0 - crowding * 0.3 - progress * 5.0;
        // prefer new bin if item is large and no tight fit exists
        if item_size >= 70 && fitting_bins_count > 0 {
            let best_possible = fitting_bins_count;
            if best_possible > 1 { score += 5.0; }
        }
    }

    // Mild preference to balance open bins
    score += (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that cannot fit the next item's typical scale.
    if next_item_size > 0 {
        if (post_residual as u32) < next_item_size {
            // Dead space for the lookahead item: penalize proportionally.
            score += 6.0 * (next_item_size - post_residual) as f64;
        } else {
            // Bin can also host the next item: reward chaining.
            score -= 5.0;
        }
    } else {
        // Last item: just fill as much as possible.
        score -= 8.0 * tightness;
    }

    // Last-chance bin bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // With many options, prefer bins that become least wasteful.
        score += 1.5 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Discourage scattering across many open bins when residuals are large.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if (bin_residual as f64) > mean_residual * 1.3 {
        // Large outlier residual: slightly favored early, penalized late.
        if progress < 0.5 {
            score -= 3.0;
        } else {
            score += 4.0 * progress;
        }
    }

    // Prefer filling bins with small residuals as the stream progresses
    // (consolidation pressure over time).
    score -= progress * 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Mild penalty for opening a brand-new bin when decent fits exist.
    if bin_residual == bin_capacity {
        score += 10.0;
        // But allow new bins early in the stream to build diversity.
        score -= 8.0 * (1.0 - progress);
    }

    // Small tie-breaker: prefer bins with residual close to mean (balance).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

