            if reps >= 3 && rem == 0 && fragmentation < 0.3 {
                score -= 14.0 * ((reps as f64).min(5.0) - 2.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // gen 138: lane-diversity open.
        if next_item_size > 0 && fresh_post > 0.0 && fragmentation > 0.45 && remaining_frac > 0.2 {
            let dup = ((fresh_post - mean_residual).abs() / cap) < 0.08;
            if !dup && (fresh_post as u32) >= next_item_size {
                score -= 9.0 * (1.0 - progress) * (0.4 + 0.6 * (fragmentation - 0.45) / 0.55);
            }
        }
        // gen 142: tileable-lane open preference.
        if next_item_size > 1 && remaining_frac > 0.1 && fragmentation < 0.5 {
            let open_can_tile = mean_residual >= next_item_size as f64
                && (mean_residual as u32) % next_item_size == 0;
            if (fresh_post as u32) % next_item_size == 0 && (fresh_post as u32) >= 2 * next_item_size && !open_can_tile {
                score -= 12.0 * (1.0 - progress) * (0.5 + 0.5 * (1.0 - fragmentation));
            }
        }
        // gen 147: slack-aware fresh-bin gate.
        if remaining_frac > 0.08 && fresh_post > 0.0 && next_item_size > 0 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (next_item_size as f64) * 0.5;
            if open_space > 1.3 * est_need && (fresh_post as u32) > next_item_size {
                let surplus = ((open_space - est_need) / (4.0 * cap)).min(1.0);
                score += 18.0 * surplus * (fresh_post / cap) * (1.0 - remaining_frac / 0.08).abs().min(1.0);
            }
        }
        // MUTATION (gen 148): drain-aware open gate — when the fleet's open
        // slack cannot absorb even a modest share of the remaining demand,
        // a fresh bin is genuinely needed; soften the fresh-bin penalty so
        // capacity is added before slack-starvation strands future items.
        if remaining_frac > 0.1 && fresh_post > 0.0 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (mean_residual.max(item_size as f64)) * 0.35;
            if open_space < 0.8 * est_need {
                let deficit = ((0.8 * est_need - open_space) / (0.8 * est_need)).min(1.0);
                score -= 26.0 * deficit * (0.5 + 0.5 * progress);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear coupling: post_residual weighted by smooth progress polynomial
    let w = 0.35 + 0.65 * progress * progress;
    score *= w;

    // Penalize large post_residual quadratically (dead space)
    let pr = post_residual as f64;
    score += 0.004 * pr * pr;

    // Reward tight fits (small post_residual) more strongly later in stream
    score -= 6.0 * (1.0 - progress) * (1.0 - pr / bin_capacity as f64);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // Lookahead: prefer leaving space usable by next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 3.0;
        } else {
            score += 2.0 * (next_item_size as f64 - pr);
        }
    }

    // Penalize bins far from mean residual (keeps bin population homogeneous)
    score += 0.05 * (pr - mean_residual).abs();

    // New-bin candidate: mild penalty so it's chosen only when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 4.0 + 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
