    let poly = x * x * (1.0 - x) * (1.0 - x);
    let coupling = poly * (1.0 + progress * (1.0 - progress) * 4.0);

    let mut score = pr - 12.0 * coupling * cap;

    // Penalize dead space scaled by stream progress (smooth quadratic).
    score += progress * progress * pr * 0.5;

    // Reward tight fits: smooth sigmoid-like term on normalized fill.
    let fill = 1.0 - x;
    score -= 6.0 * fill * fill * fill;

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 15.0 * (1.0 - progress);
    }

