        // Residual cannot host next item: mild penalty scaled by how close it is.
        let gap = (next_item_size - post_residual) as f64;
        score += (gap * 0.8).min(80.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a bin unless current residuals are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap) * open_bins_count as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Prefer new bins early or when open bins are nearly full / fragmented.
        score += 120.0 - 100.0 * fragmentation - 40.0 * (1.0 - progress);
        // If item is large relative to capacity, opening fresh is safer.
        if item_size as f64 > 0.5 * cap {
            score -= 30.0;
        }
    }

    // Mild preference for bins tighter than the mean (best-fit flavor).
    score += ((bin_residual as f64 - mean_residual) * 0.3).max(0.0);

    // Small penalty per open bin to encourage consolidation when residuals are ample.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are the worst outcome.
    // Define "dead zone" as residual too small for even the smallest plausible item.
    let dead_threshold: f64 = 10.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        // Tiny wasted sliver: heavy penalty proportional to how close to zero.
        score += (dead_threshold - post_residual as f64) * 12.0;
    }

    // Reward near-perfect fills strongly (post_residual small but not a sliver).
    if post_residual == 0 {
        score -= 150.0; // perfect fit: ideal
    }

    // Penalize leaving large residual that is still hard to reuse later:
    // mid-range gaps (e.g. 20..40) are awkward; large gaps are fine.
    let pr = post_residual as f64;
    if pr > 15.0 && pr < 45.0 {
        score += (45.0 - pr) * 0.8; // mildly awkward gap
    }

    // Open-bins pressure: when many bins are open, prefer consolidating
    // into existing bins rather than opening new ones.
    score += open_bins_count as f64 * 0.5;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (which costs a fresh bin + leaves this one idle).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: opening a new bin should only win when
    // no existing bin offers a decent fit. Make the empty bin moderately
    // unattractive so tight existing fits beat it.
    if bin_residual == bin_capacity {
        score += 40.0;
        // But if the next item is large and current residual would be badly
        // fragmented, a fresh bin gains appeal.
        if next_item_size as f64 > post_residual as f64 + 25.0 && post_residual > 0 {
            score -= 45.0;
        }
        // Early in the stream, fewer open bins: new bin is cheaper.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 15.0;
    }

    // Lookahead: if next item fits exactly in post_residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 80.0;
    } else if next_item_size > post_residual && next_item_size > 0 && post_residual > 0 {
        // post_residual too small for next item: it becomes dead space for lookahead.
        score += (post_residual as f64) * 1.5;
    }

    // Mild preference to place into bins with low mean residual (tighter bins),
    // keeping roomier bins available for future large items.
    score += (mean_residual - post_residual as f64).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step chain: next item exactly fills post residual -> huge reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 60.0;
    } else if next_item_size > 0 && next_item_size < post_residual {
        // Next item fits here: reward proportionally to how tightly it chains.
        let chain_waste = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - chain_waste / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot follow into this bin: penalize dead space relative to next size.
        let gap = (next_item_size - post_residual) as f64;
        score += 8.0 + 0.5 * gap;
    }

    // Reward leaving residual close to the mean residual of open bins (balanced bins).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Penalize tiny unusable slivers (dead space < 10).
    if post_residual < 10 {
        score += 15.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let poor_fit = if next_item_size > 0 && next_item_size > post_residual { 1.0 } else { 0.0 };
        score += 25.0 - 30.0 * poor_fit + 0.1 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on wasted space.
    let waste = post_residual as f64;
    score += 0.35 * (waste / bin_capacity as f64) * (waste / bin_capacity as f64) * bin_capacity as f64;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 8.0;
    }

    // Lookahead: favor bins whose residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + 0.05 * (post_residual - next_item_size) as f64;
        } else {
            score += 4.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Time horizon: early on, be picky (penalize mediocre fits); late, be greedy.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.5 * (1.0 - progress);

    // Many open bins: encourage consolidation by penalizing spread.
    score += 0.02 * open_bins_count as f64;

    // Mean residual coupling: penalize bins far from the mean residual (fragmentation).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // New-bin candidate: make it attractive only when fits are bad.
    if bin_residual == bin_capacity {
        let bad_fit = post_residual as f64 / bin_capacity as f64;
        score = 25.0 + 30.0 * (1.0 - bad_fit) + 0.5 * open_bins_count as f64;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let norm_pr = pr / cap;

    // Base: post-residual, penalized more heavily as residual grows (dead space)
    let mut score = pr as f64 * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth stream-progress coupling: later in the stream, tighten bins more aggressively
    score += 6.0 * progress * norm_pr * norm_pr;

    // Reward tight fits: subtract bonus proportional to fill fraction, amplified by progress
    score -= 10.0 * fit_ratio * (1.0 + progress);

    // Non-linear waste term: quadratic in post_residual scaled by item size
    score += 0.02 * (pr as f64) * (item_size as f64) / cap;

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - progress);
    }

    // Lookahead: if next item fits into resulting post_residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 * (next_item_size as f64 / cap) * (1.0 + 0.5 * progress);
    } else if next_item_size > 0 {
        // Next item won't fit: penalize leaving a mid-sized gap
        score += 4.0 * (1.0 - (pr / cap - next_item_size as f64 / cap).abs());
    }

    // Prefer bins below mean residual (tighter bins) with smooth coupling
    score += 0.15 * (pr - mean_residual) * (1.0 + progress);

    // New-bin candidate: neutral-to-slightly-high baseline so it's chosen only
    // when no open bin offers a genuinely good fit; more attractive early on
    if bin_residual == bin_capacity && item_size > 0 {
        score = cap * (1.0 + 0.5 * progress) - 4.0 * fit_ratio * cap;
        // Early stream: opening bins is cheap; late stream: discourage
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base: prefer minimal waste, but strongly reward "perfect" residual classes.
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by common size
    // granularities (e.g. 10, 20, 25, 50) are more likely to be reused later.
    let pr = post_residual;
    if pr == 0 {
        score -= 1000.0; // perfect fit: always take it
    } else {
        // Divisibility bonuses (stacked, harmonic ladder)
        if pr % 10 == 0 { score -= 6.0; }
        if pr % 20 == 0 { score -= 4.0; }
        if pr % 25 == 0 { score -= 4.0; }
        if pr % 50 == 0 { score -= 6.0; }

        // Penalize tiny unusable slivers (dead space classes 1..=9)
        if pr < 10 {
            score += (10 - pr) as f64 * 2.0;
        }

        // Coupling: does the next item fit exactly into the post-residual?
        if next_item_size > 0 {
            if next_item_size == pr {
                score -= 200.0; // exact lookahead match
            } else if next_item_size <= pr {
                // next item fits: bonus scaled by how "round" the new residual would be
                let pr2 = pr - next_item_size;
                let mut bonus = 20.0;
                if pr2 % 10 == 0 { bonus += 10.0; }
                if pr2 % 25 == 0 { bonus += 5.0; }
                if pr2 < 10 { bonus -= 15.0; } // would create a sliver
                score -= bonus;
            } else {
                // next item cannot fit here: mild penalty, worse for small pr
                score += ((next_item_size - pr) as f64).min(40.0) * 0.5;
            }
        }

        // Last-chance bin: strongly favor using it to avoid opening a new bin.
        if fitting_bins_count == 1 {
            score -= 15.0;
            if pr >= 10 { score -= 5.0; } // residual still reusable
        }

        // New-bin candidate logic: an empty bin has pr == bin_capacity.
        if bin_residual == bin_capacity {
            // Opening a new bin is only attractive if all open bins would leave
            // badly fragmented residuals and the stream is early/mid.
            let progress = step_index as f64 / (total_items.max(1) as f64);
            let fragmentation = (mean_residual - pr as f64).abs();
            // Empty bin gets a moderate score; make it competitive only when
            // mean residual of open bins is small (poor fits everywhere).
            score = 50.0 + fragmentation * 0.3 + progress * 20.0;
            if next_item_size > 0 && next_item_size <= bin_capacity {
                score -= 5.0;
            }
            // Never open a new bin when a perfect fit exists elsewhere:
            // that bin's score is already ~-1000.
            if pr % 50 == 0 { score -= 3.0; }
        }

        // Prefer filling more-full bins overall: bias by fill fraction.
        let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= fill * 8.0;

        // Spread penalty: if this bin's residual deviates wildly from the mean,
        // placing here homogenizes residuals (good for future flexibility).
        let dev = (mean_residual - pr as f64).abs();
        score -= dev * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps below the minimum item size (1) don't exist,
    // but gaps too small for the *next* item are likely dead weight.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Penalize unusable residual relative to the lookahead item size.
    if next_item_size > 0 && post_residual < next_item_size {
        // This residual is dead space for the known next item.
        score += (next_item_size - post_residual) as f64 * (1.5 + progress);
    }

    // Strong penalty for tiny residual slivers (likely never fillable).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 + (10 - post_residual) as f64 * 3.0;
    }

    // Reward very tight fits (post_residual near zero is actually good if it closes the bin).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Reward good utilization of the bin's current residual (high fill ratio).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 30.0;

    // Open-bin pressure: when many bins are open, discourage opening new ones;
    // the new-bin candidate (residual == capacity) gets penalized proportionally.
    if bin_residual == bin_capacity {
        score += 40.0 + open_bins_count as f64 * 5.0;
        // But if this bin is the last chance, opening a new bin may still be better.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Mild bonus when bin residual deviates favorably from the mean residual
    // (prefer bins with below-average residual to consolidate space).
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // Early in the stream, be slightly more willing to open fresh bins for large items.
    if progress < 0.2 && item_size >= 60 {
        score += 5.0;
    }

    // Lookahead synergy: reward residual that exactly accommodates the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core dead-space penalty: waste grows super-linearly with residual.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * waste_frac * waste_frac;

    // ---- Aggressive 2-step lookahead ----
    if next_item_size > 0 {
        // Perfect chaining: post_residual exactly fits the next item -> big reward.
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item fits, but leftover after that is the real cost.
            let next_left = post_residual - next_item_size;
            let nl_frac = next_left as f64 / bin_capacity as f64;
            score -= 25.0;
            score += 10.0 * nl_frac * nl_frac;
            // Bonus if the two-step chain terminates exactly (item + next == residual).
            if next_left == 0 {
                score -= 20.0;
            }
        } else {
            // Next item will NOT fit in this bin: penalize proportionally to the gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.35 * gap;
        }

        // If next item could have fit in the pre-placement residual but we broke it,
        // penalize destroying a viable slot for the lookahead item.
        if bin_residual >= next_item_size && post_residual < next_item_size {
            score += 15.0;
        }
    }

    // Relative-to-mean coupling: prefer bins whose post residual stays near the
    // open-bin average (keeps future items flexible), penalize outliers.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate (empty bin): make it attractive only when the item is large
    // or no good fits exist; otherwise opening bins is wasteful.
    if bin_residual == bin_capacity {
        // Baseline: an empty bin has post_residual == capacity - item, already scored.
        // Penalize opening a new bin when decent open bins exist.
        if fitting_bins_count > 1 {
            score += 18.0;
        }
        // Large items pack cleanly into fresh bins; small items should reuse bins.
        if item_size >= 60 {
            score -= 10.0;
        } else if item_size <= 30 {
            score += 8.0;
        }
        // Fewer open bins -> cheaper to open another (early stream).
        let prog = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - prog);
    }

    // Mild reward for filling bins tighter than the average open-bin state.
    if (post_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 120.0 * (1.0 - post_residual as f64 / 5.0);
    }

    // Lookahead: residual that can host the next item is valuable.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Dead space relative to the lookahead item.
        score += 0.6 * (next_item_size - post_residual) as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 150.0;
    } else if fitting_bins_count > 1 {
        // Prefer bins that are already quite full among competitors.
        let fill = 1.0 - bin_residual as f64 / bin_capacity as f64;
        score -= 50.0 * fill;
    }

    // Penalize leaving large residual when mean residual is low (bins are tight globally).
    let residual_gap = post_residual as f64 - mean_residual;
    if residual_gap > 0.0 {
        score += 0.3 * residual_gap;
    }

    // Slight preference for consolidating into fewer bins early on.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count > 0 && bin_residual != bin_capacity {
        score -= 10.0 * (1.0 - progress);
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let poor_fit = post_residual as f64 / bin_capacity as f64;
        score += 80.0 * (1.0 - desperation) + 60.0 * poor_fit;
        // Late in the stream, avoid spreading out.
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let prn = pr / cap;

    // Base: penalize wasted post residual, non-linearly
    let mut score = 2.0 * prn + 3.0 * prn * prn;

    // Smooth stream-progress coupling: early on, keep bins tight; later, tolerate spread
    let progress_coupling = (0.5 - progress).abs() * prn * prn * 4.0;
    score += progress_coupling;

    // Reward near-perfect fits with a smooth saturating term
    let tightness = 1.0 - prn;
    score -= 1.5 * tightness * tightness * tightness;

    // Lookahead: if next item fits in post_residual, reward this bin
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let chain = next_item_size as f64 / cap;
        score -= 0.8 * chain * (1.0 - progress);
    } else if next_item_size > 0 {
        score += 0.3 * prn;
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 2.0;
    }

    // Penalize opening a new bin when open bins fit, scaled by progress and crowding
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 1.0 + 2.0 * progress + 0.05 * open_bins_count as f64;
    }

    // Mild normalization against mean residual state
    score += 0.1 * (mean_residual / cap - prn).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Perfect fit: strongly reward closing the bin with zero waste.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward bins that can still accommodate the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + (next_item_size as f64 / 100.0) * 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space: leftover too small for the next item is likely wasted.
        score += 6.0 * (1.0 - post_residual as f64 / 100.0);
    }

    // Harmonic class: residuals on multiples of 10 (capacity-decade grid) tend to
    // compose better with future items; small odd fragments are poor hosts.
    if post_residual > 0 {
        if post_residual % 10 == 0 {
            score -= 3.0;
        } else if post_residual % 5 == 0 {
            score -= 1.5;
        }
        score += (post_residual % 7) as f64 * 0.4;
    }

    // Integer-division threshold: residual in the top quartile of capacity is
    // a flexible host; residual in the bottom quartile is nearly dead.
    let quarter = bin_capacity / 4;
    if post_residual >= quarter {
        score -= 4.0;
    } else if post_residual > 0 {
        score += 3.0;
    }

    // Last-chance bin: if this is the only open bin that fits, use it rather
    // than opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Prefer already-partially-filled bins: reward used capacity.
    if bin_residual != bin_capacity {
        score -= (bin_capacity - bin_residual) as f64 * 0.05;
    }

    // New-bin candidate handling: opening a new bin should lose to any
    // reasonable existing fit, but win when no open bin fits or fits are bad.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 10.0; // no alternative: new bin is fine
        } else {
            score += 35.0 + 15.0 * (1.0 - progress);
            score += mean_residual * 0.15;
            // If the only fitting bins leave huge post-residuals, allow the new bin.
            if post_residual + item_size >= bin_capacity / 2 && fitting_bins_count <= 2 {
                score -= 20.0;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftovers are unusable by future items
    // (min item size 1, but gaps below ~10 rarely help). Penalize them hard.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 6.0; // dead-space penalty
    }
    if post_residual == 0 {
        score -= 40.0; // perfect fit is ideal
    }

    // Reward leaving a gap that can still host a typical item chunk.
    if post_residual >= 10 {
        score -= 5.0;
    }

    // If the lookahead item fits exactly in the resulting residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // Exact match for the next item is near-perfect chaining.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot use this residual: mild penalty for wasted gap.
        score += (post_residual as f64) * 0.15;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure, minus lookahead flexibility.
        score += 30.0 + pressure * 2.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    } else {
        // Reward filling already-open bins, more so under pressure.
        score -= pressure * 0.5;
    }

    // Prefer bins whose residual is close to the item (tight fits).
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += tightness * 10.0;

    // Slight preference for bins below mean residual (filling emptier-ish bins
    // keeps a spread of usable gaps across bins).
    score += (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward exact 2-step lookahead match (post_residual == next_item_size).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 * (1.0 - diff / (bin_capacity as f64)).max(0.0);
        // Perfect match bonus
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize post_residual that is small but not matching next item (dead space)
        if post_residual < next_item_size && post_residual > 0 {
            score += 10.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Relative to mean residual: bins with more room than average get slight preference
    score -= 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize creating tiny unusable residuals
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // New-bin candidate: only attractive when current fit is bad
    if bin_residual == bin_capacity {
        // Base penalty so we prefer existing bins with decent fits
        score = 0.5 * bin_capacity as f64;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
        if fitting_bins_count <= 1 {
            score -= 40.0; // opening new bin is fine when no good alternative
        }
    }

    // Late in stream: consolidate, discourage new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual) with a non-linear term.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Penalize creating unusable dead space: residual too small for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual > 0 && post_residual < 20 {
        score += 8.0;
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0;
        } else if post_residual >= next_item_size {
            score -= 3.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Dead space relative to the known next item.
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded or fit is poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowded = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
        let poor_fit = (post_residual as f64) / bin_capacity as f64; // = 1.0 for empty bin
        // Prefer new bin when existing bins have low mean residual and few alternatives.
        score += 30.0 - 20.0 * crowded - 10.0 * (1.0 - progress);
        if fitting_bins_count <= 1 {
            score -= 20.0; // opening a bin is fine if nothing else fits
        }
        // Late in the stream, avoid spawning bins with tiny leftover potential.
        if progress > 0.8 {
            score += 5.0 * progress;
        }
    } else {
        // Mild preference for filling nearly-full bins to close them out.
        let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= 4.0 * fill_ratio;

        // Spread load when many bins are open with large residuals.
        if mean_residual > 0.5 * bin_capacity as f64 && open_bins_count > 2 {
            score += 2.0;
        }
    }

    // Dynamic time horizon: early on, keep bins balanced; later, prioritize packing density.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.05 * (post_residual as f64 - mean_residual).abs();
    score -= progress * 2.0 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let t = step_index as f64 / total_items.max(1) as f64;
    let fill = 1.0 - pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let progress_warp = 0.5 + 0.5 * (t * std::f64::consts::PI).sin();
    let mut score = pr * (1.0 + 0.6 * progress_warp * fill * fill);

    // Penalize small dead space quadratically (unusable slivers)
    if pr < next_item_size as f64 && next_item_size > 0 {
        score += (next_item_size as f64 - pr) * (1.0 + t);
    }

    // Reward scarce fitting capacity
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - t);
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.05 * open_bins_count as f64 * (1.0 - fill);

    // Prefer bins near mean residual (balance) with smooth term
    score += 0.1 * (pr - mean_residual) * (pr - mean_residual) / cap;

    // New-bin candidate: penalize mildly early, more late unless fill is high
    if bin_residual == bin_capacity {
        score += 8.0 + 20.0 * t - 6.0 * item_size as f64 / cap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Is this the brand-new empty bin candidate?
    let is_new_bin = bin_residual == bin_capacity;

    // Harmonic classes: how "usable" is the leftover space?
    // Residuals divisible by small capacity fractions are more reusable.
    let pr = post_residual;
    let mut usability = 0.0f64;
    if pr == 0 {
        usability = 20.0; // perfect fit: dead space zero
    } else {
        if pr % 10 == 0 { usability += 6.0; }
        if pr % 20 == 0 { usability += 4.0; }
        if pr % 25 == 0 { usability += 3.0; }
        if pr % 50 == 0 { usability += 3.0; }
        // integer-division thresholds: small leftovers are hard to fill
        if pr <= 10 { usability -= 8.0; }
        else if pr <= 25 { usability -= 3.0; }
        else if pr >= 70 { usability += 4.0; }
    }
    score -= usability;

    // Tightness reward: relative fill of the bin
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a bin when open bins exist and fit,
    // but reward it when the current item would leave a bad remainder elsewhere
    // or when the next item pairs better with a fresh bin.
    if is_new_bin {
        let base_penalty = if open_bins_count == 0 { -20.0 } else { 12.0 };
        score += base_penalty;
        // pair lookahead: if next item plus this item nearly fills a bin,
        // opening a fresh bin is attractive
        if next_item_size > 0 {
            let pair = item_size as f64 + next_item_size as f64;
            if pair <= bin_capacity as f64 && pair >= 0.8 * bin_capacity as f64 {
                score -= 14.0;
            }
            // if next item would fit exactly in this bin's post_residual, keep bin open
            if next_item_size == pr && pr > 0 {
                score += 10.0;
            }
        }
        // late in the stream, avoid wasting capacity on new bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress > 0.7 { score += 8.0 * progress; }
    }

    // Spread-aware: prefer bins whose residual deviates favorably from mean
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // Modulo coupling between item size class and post residual:
    // items leaving residuals in the same class as the item size are reusable
    if pr > 0 && item_size % 10 == 0 && pr % (item_size % 50).max(10) == 0 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: extremely strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Near-perfect fit: small dead space is nearly as good.
    if post_residual > 0 && post_residual <= 5 {
        score -= 300.0;
    }

    // 2-step lookahead: reward when the next item exactly fills the new residual.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size < post_residual {
            let two_step_waste = (post_residual - next_item_size) as f64;
            // MUTATION: scale two-step reward by next item's relative size —
            // a big next item consuming most of the residual is a stronger chain.
            let rel = next_item_size as f64 / post_residual as f64;
            score -= (100.0 - 1.5 * two_step_waste).max(0.0) * (0.5 + rel);
        } else {
            // MUTATION: penalize dead-space creation scaled by how many
            // alternatives exist; with many fitting bins, poor fits are
            // less forgivable.
            let alt_pressure = 1.0 + 0.15 * fitting_bins_count as f64;
            score += 0.8 * (next_item_size - post_residual) as f64 * alt_pressure;
        }
    }

    // MUTATION: residual-to-capacity ratio coupling — a large residual on a
    // small-capacity context (or tight global packing) matters differently.
    let dev = post_residual as f64 - mean_residual;
    if dev < 0.0 {
        score += 0.4 * dev;
    } else {
        score += 0.7 * dev;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 250.0;
    }

    // MUTATION: small-fitting-bins pressure — when several bins fit the item,
    // reward picking the tightest (post_residual small) more aggressively so
    // loose placements don't win by tie-breaking noise.
    if fitting_bins_count > 2 && post_residual > 0 {
        score += 0.25 * post_residual as f64;
    }

    let progress = step_index as f64 / (total_items.max(1) as f64);

    // New-bin candidate handling.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let mut new_bin_penalty = 400.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            new_bin_penalty += 150.0;
        }
        if fitting_bins_count == 0 {
            new_bin_penalty -= 350.0;
        }
        // MUTATION: when the item nearly fills a fresh bin, opening a new bin
        // is actually great — big items waste less in empty space.
        if item_size > bin_capacity / 2 {
            new_bin_penalty -= 120.0;
        }
        if post_residual > 60 {
            new_bin_penalty += 0.5 * (post_residual as f64 - 60.0);
        }
        // MUTATION: late in the stream, opening bins is cheaper to penalize
        // (fewer future chances to consolidate); front-load the penalty.
        score += new_bin_penalty * (1.0 - 0.45 * progress);
    } else {
        // MUTATION: strengthen the consolidation reward when many bins are
        // open — prefer tightening existing bins over spreading.
        score -= 0.2 * open_bins_count as f64;
        if open_bins_count > 8 {
            score -= 0.15 * (open_bins_count - 8) as f64;
        }
    }

    // Progress-based tie-breaking.
    score += 0.3 * post_residual as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
