    // 3-item lookahead hint: if next item fills residual AND the item after
    // would be favored, boost the chain reward (approximated via residual size).
    if next_item_size > 0 && post_residual == next_item_size && post_residual >= 40 {
        score -= 100.0; // large chained perfect fits are especially valuable
    }

    // Compare residual against the mean residual across open bins.
    let dev = post_residual as f64 - mean_residual;
    if dev < 0.0 {
        score += 0.45 * dev;
    } else {
        score += 0.75 * dev;
    }

    // Last-chance bonus: only fitting bin -> strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 300.0;
    } else if fitting_bins_count == 2 {
        score -= 80.0; // mild preference to keep alternatives open
    }

    // New-bin candidate handling.
    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if is_new_bin {
        let mut new_bin_penalty = 420.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            new_bin_penalty += 180.0; // fresh bin can host the next item too
        }
        if fitting_bins_count == 0 {
            new_bin_penalty -= 420.0;
        } else {
            // If open bins would waste a lot, opening fresh is cheaper.
            // Estimate best existing waste via post_residual spread: when the
            // item barely fits anywhere (post_residual small everywhere) the
            // fitting_bins_count signal already covers it; otherwise penalize.
            let min_waste_elsewhere = if post_residual < bin_capacity {
                // item placed in an open bin leaves this much dead space
                post_residual as f64
            } else {
                0.0
            };
            if min_waste_elsewhere > 45.0 {
                new_bin_penalty -= 0.9 * (min_waste_elsewhere - 45.0);
            }
        }
        if item_size > 70 {
            new_bin_penalty -= 120.0; // huge items belong in fresh bins
        }
        if post_residual > 60 {
            new_bin_penalty += 0.5 * (post_residual as f64 - 60.0);
        }
        score += new_bin_penalty * (1.0 - 0.35 * progress);
    } else {
        // Reward using existing bins, but cap the effect so it doesn't
        // dominate residual quality late when many bins are open.
        let open_bonus = 0.25 * (open_bins_count.min(12) as f64);
        score -= open_bonus;
    }

    // Progress-based conservatism: late in the stream, penalize residual more.
    score += 0.35 * post_residual as f64 * progress;

    // Early-stream exploration: slightly prefer compact residuals early to
    // build dense bins that pay off later.
    if progress < 0.3 {
        score -= 0.15 * (bin_capacity - post_residual) as f64 * (0.3 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let t = step_index as f64 / total_items.max(1) as f64;
    let fill = 1.0 - pr / cap;

    // Perfect and near-perfect fits: strong rewards (borrowed from best)
    if pr == 0.0 {
        return -1000.0;
    }
    if pr <= 5.0 {
        return -300.0 + pr;
    }

    // Smooth polynomial coupling of post_residual with stream progress
    let progress_warp = 0.5 + 0.5 * (t * std::f64::consts::PI).sin();
    let mut score = pr * (1.0 + 0.6 * progress_warp * fill * fill);

    // Two-step lookahead: chain reward when next item exactly fills residual
    let nis = next_item_size as f64;
    if nis > 0.0 {
        if nis == pr {
            score -= 800.0;
        } else if nis < pr {
            let two_step_waste = pr - nis;
            score -= 100.0 - 1.5 * two_step_waste;
        } else {
            // dead space created relative to next item
            score += (nis - pr) * (0.8 + 0.6 * t);
        }
    }

    // Reward scarce fitting capacity
    if fitting_bins_count == 1 {
        score -= 250.0;
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.05 * open_bins_count as f64 * (1.0 - fill);

    // Asymmetric deviation from mean residual (compact packing preference)
    let dev = pr - mean_residual;
    if dev < 0.0 {
        score += 0.4 * dev;
    } else {
        score += 0.7 * dev;
    }

    // New-bin candidate: penalize opening a new bin strongly, but relax
    // when nothing fits well among open bins or stream is ending.
    if bin_residual == bin_capacity {
        let mut new_bin_penalty = 400.0;
        if nis > 0.0 && pr >= nis {
            new_bin_penalty += 150.0; // fresh bin can host next item too
        }
        if fitting_bins_count == 0 {
            new_bin_penalty -= 350.0;
        }
        if pr > 60.0 {
            new_bin_penalty += 0.5 * (pr - 60.0);
        }
        score += new_bin_penalty * (1.0 - 0.3 * t);
    } else {
        score -= 0.2 * open_bins_count as f64;
    }

    // Late-stream conservatism: residuals matter more near the end
    score += 0.3 * pr * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: dominant reward to close bins completely.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Near-perfect fit: tiny dead space is nearly as good.
    if post_residual > 0 && post_residual <= 5 {
        score -= 300.0;
    }

    // Core dead-space penalty: waste grows super-linearly with residual.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * waste_frac * waste_frac;

    // ---- Aggressive 2-step lookahead ----
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 800.0; // exact chain: next item finishes this bin
        } else if post_residual >= next_item_size {
            let next_left = post_residual - next_item_size;
            let nl_frac = next_left as f64 / bin_capacity as f64;
            score -= 100.0 - 1.5 * next_left as f64;
            score += 10.0 * nl_frac * nl_frac;
            if next_left == 0 {
                score -= 20.0;
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 0.8 * gap;
        }

        // Penalize destroying a viable slot for the lookahead item.
        if bin_residual >= next_item_size && post_residual < next_item_size {
            score += 25.0;
        }
    }

    // Relative-to-mean coupling: asymmetric; below-average residual rewarded,
    // above-average residual penalized harder (compact packing preference).
    let dev = post_residual as f64 - mean_residual;
    if dev < 0.0 {
        score += 0.4 * dev;
    } else {
        score += 0.7 * dev;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_penalty = 400.0;
        // Fresh bin can host the next item too.
        if next_item_size > 0 && post_residual >= next_item_size {
            new_bin_penalty += 150.0;
        }
        // No alternative: opening a bin is mandatory.
        if fitting_bins_count == 0 {
            new_bin_penalty -= 350.0;
        }
        // Large items pack cleanly into fresh bins.
        if item_size > 60 {
            new_bin_penalty -= 120.0;
        } else if item_size <= 30 {
            new_bin_penalty += 60.0;
        }
        score += new_bin_penalty * (1.0 - 0.3 * progress);
    } else {
        // Mild reward for using existing bins as they accumulate.
        score -= 0.2 * open_bins_count as f64;
    }

    // Progress-based tie-breaking: late in the stream be more conservative.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.3 * post_residual as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
