pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64;
    if post_residual == 0 { score -= 1000.0; }
    if post_residual > 0 && post_residual <= 6 { score -= 320.0; }
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual { score -= 850.0; }
        else if next_item_size < post_residual {
            let two_step_waste = (post_residual - next_item_size) as f64;
            score -= 110.0 - 1.4 * two_step_waste;
        } else {
            score += 0.9 * (next_item_size - post_residual) as f64;
        }
    }
    // Penalize bins whose residual sits in an awkward "dead zone" that few
    // future items can fill: residual in (6, 15] is hard to pack.
    if post_residual > 6 && post_residual <= 15 { score += 40.0; }
    // Prefer compacting into bins with many competitors only when the fit
    // is tight; when several bins fit, favor the one closest to exact fill.
    if fitting_bins_count > 1 && post_residual > 0 {
        score += 12.0 * (fitting_bins_count as f64).min(5.0);
    }
    // Mild global pressure: when mean residual across open bins is high,
    // encourage filling existing bins rather than opening new ones.
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize when existing bins look roomy
        score += 60.0 + mean_residual.clamp(0.0, 200.0) * 0.5;
    } else {
        score -= mean_residual.clamp(0.0, 200.0) * 0.05;
    }
    // Early stream: be slightly greedy to build dense bins early.
    if step_index < total_items / 10 { score += 3.0; }
    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64;
