    // With several candidates, prefer the tightest relative fit.
    if fitting_bins_count > 1 && post_residual > 0 {
        let tightness = post_residual as f64 / bin_capacity as f64;
        score += 10.0 * (fitting_bins_count as f64).min(5.0) * (1.0 - tightness);
    }
    // New-bin candidate: penalize when open bins still have usable space,
    // scaled by how roomy the fleet is on average.
    if bin_residual == bin_capacity {
        score += 60.0 + mean_residual.clamp(0.0, 200.0) * 0.6;
    } else {
        score -= mean_residual.clamp(0.0, 200.0) * 0.05;
    }
    // Early stream: build dense bins early.
    if step_index < total_items / 10 { score += 3.0; }
    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fill is always best.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Near-perfect fills: reward tighter window than parent (<=4), scaled by item size.
    if post_residual > 0 && post_residual <= 4 {
        score -= 280.0 + 2.0 * (4 - post_residual) as f64;
    }

    // Lookahead coupling with next item.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 850.0;
        } else if next_item_size < post_residual {
            let two_step_waste = (post_residual - next_item_size) as f64;
            // Reward only small two-step wastes; large gaps are dead space.
            if two_step_waste <= 10.0 {
                score -= 110.0 - 2.0 * two_step_waste;
            } else {
                score -= 90.0 - 0.3 * two_step_waste;
            }
        } else {
            // Penalize residuals too small for the next item, scaled by how badly it misses.
            let miss = (next_item_size - post_residual) as f64;
            score += 0.9 * miss;
            if miss > 30.0 {
                score += 0.4 * (miss - 30.0);
            }
        }
    }

    // Two-step lookahead: if next item fits exactly and leaves a residual matching
    // a small window, mildly discourage consuming it unless this bin packs tightly now.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after2 = post_residual - next_item_size;
        if after2 > 0 && after2 <= 6 {
            score -= 40.0;
        }
    }

    // Discourage opening a new bin when decent fits exist among open bins.
    if bin_residual == bin_capacity {
        score += 500.0;
        // But allow a new bin when the item is large and open bins are fragmented.
        if item_size >= bin_capacity / 2 && open_bins_count > 4 {
            score -= 450.0;
        }
    }

    // Mild preference for bins whose residual is close to mean residual (keeps homogeneity).
    if bin_residual < bin_capacity {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;
    // Base: prefer minimal post residual
    if post_residual == 0 {
        score -= 1000.0 ;
    } else if post_residual <= 8 {
        score -= 300.0 + 4.0 * (8 - post_residual) as f64 ;
    }
    // Lookahead coupling with next item
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 900.0 ;
        } else if next_item_size < post_residual {
            let two_step_waste = (post_residual - next_item_size) as f64 ;
            score -= 120.0 - 1.2 * two_step_waste ;
        } else {
            let overshoot = (next_item_size - post_residual) as f64 ;
            score += 0.9 * overshoot ;
            // If the next item cannot fit anywhere after this placement, penalize
            if overshoot > 0.0 && fitting_bins_count <= 1 {
                score += 40.0 ;
            }
        }
    }
    // New-bin candidate handling: make empty bins attractive only when the item
    // leaves a residual that is likely to be reusable (matches common item sizes)
    if bin_residual == bin_capacity {
        let leftover = bin_capacity.saturating_sub(item_size) ;
        score = leftover as f64 + 250.0 ;
        if next_item_size > 0 && leftover >= next_item_size {
            score -= 60.0 ;
        }
        // Late in the stream, avoid opening extra bins
        if total_items > 0 && step_index * 100 > total_items * 85 {
            score += 500.0 ;
        }
    } else {
        // Slight preference for bins with residuals near the mean (keeps pool uniform)
        let dev = (bin_residual as f64 - mean_residual).abs() ;
        score += 0.05 * dev ;
        // Scarce fitting options: reward keeping this bin viable
        if fitting_bins_count <= 2 && post_residual > 0 {
            score -= 25.0 ;
        }
    }
    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64;

