    // Near-perfect fills: reward small leftovers, scaled to how tight the fit is.
    if post_residual > 0 && post_residual <= 8 {
        score -= 320.0 - 12.0 * post_residual as f64;
    }

    // Two-step lookahead: couple next item size with the post-placement residual.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if next_item_size < post_residual {
            let two_step_waste = (post_residual - next_item_size) as f64;
            // Reward only if the leftover after the next item would be tiny.
            let next_post = post_residual - next_item_size;
            if next_post <= 4 {
                score -= 260.0 - 20.0 * next_post as f64;
            } else {
                score -= 100.0 - 1.5 * two_step_waste;
            }
        } else {
            // Penalize residuals too small for the next item, more when many bins compete.
            let gap = (next_item_size - post_residual) as f64;
            let crowd = if fitting_bins_count > 1 { 1.0 } else { 1.4 };
            score += crowd * (0.8 * gap + if gap > 20.0 { 40.0 } else { 0.0 });
        }
    }

    // Discourage opening a new bin when open bins can still host the item well,
    // but allow it when the item is large and fits only marginally elsewhere.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        if fitting_bins_count > 0 && tightness < 0.85 {
            score += 500.0;
        } else {
            score += 60.0 - 40.0 * tightness;
        }
    }

    // Mild global pressure: prefer consolidating into fewer bins as stream progresses.
    score += 0.002 * open_bins_count as f64;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
