    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 800.0 ;
        } else if next_item_size < post_residual {
            let two_step_waste = (post_residual - next_item_size) as f64 ;
            score -= 100.0 - 1.5 * two_step_waste ;
        } else {
            score += 0.8 * (next_item_size - post_residual) as f64 ;
        }
    }

    // New-bin candidate: penalize opening a fresh bin unless it clearly beats
    // the tightest open fit. Empty bin => post_residual == bin_capacity.
    if bin_residual == bin_capacity {
        let tight_open = if fitting_bins_count > 0 {
            mean_residual
        } else {
            bin_capacity as f64
        } ;
        // Opening a new bin is only attractive when the item leaves a small
        // residue in it AND open bins are relatively full (small mean residual).
        let fresh_residue = (bin_capacity - item_size) as f64 ;
        let openness = mean_residual / bin_capacity as f64 ;
        score += 400.0 + fresh_residue * (1.0 + openness) ;
        if item_size as f64 > 0.85 * bin_capacity as f64 {
            // big item: fresh bin is fine, reduce penalty
            score -= 350.0 + 0.3 * item_size as f64 ;
        }
    }

    // Scarcity pressure: when many bins can fit the item, prefer the tightest
    // fit to preserve flexible bins; when only this bin fits, reward it.
    if fitting_bins_count > 1 {
        score += 8.0 * (fitting_bins_count as f64 - 1.0) ;
    } else if fitting_bins_count == 1 && post_residual > 0 {
        score -= 40.0 ;
    }

    // Late-stream refinement: as the stream nears its end, residual waste
    // becomes permanent, so weight post_residual more heavily.
    let progress = step_index as f64 / (total_items.max(1) as f64) ;
    if progress > 0.7 {
        score += 0.35 * progress * post_residual as f64 ;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
