    // Reward tight fits, amplified by progress
    score -= 11.0 * fit_ratio * (1.0 + progress);

    // Exact fit: near-perfect placement
    if post_residual == 0 {
        score -= 950.0;
    } else if post_residual <= 4 {
        // Tiny dead slivers: bin essentially full, reward using them
        score -= 330.0;
    }

    // Dead-space ratio penalty for large unusable gaps, scaled by how unlikely a fill is
    if norm_pr > 0.22 {
        let excess = norm_pr - 0.22;
        let fillable = next_item_size > 0 && (next_item_size as f64) <= pr;
        score += if fillable { 30.0 } else { 70.0 } * excess;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0 * (1.0 - 0.5 * progress);
    }

    // Lookahead: reward residuals that host the next item well
    if next_item_size > 0 && post_residual > 0 {
        let ni = next_item_size as f64;
        if ni == pr {
            score -= 850.0; // perfect two-step match
        } else if ni < pr {
            let waste = pr - ni;
            if waste <= 8.0 {
                score -= 150.0 - 2.0 * waste;
            } else {
                score -= 55.0 - 0.8 * waste;
            }
        } else {
            // Next item cannot follow: penalize proportional overflow
            score += 1.0 * (ni - pr);
        }
    }

    // Prefer bins below mean residual (tighter bins)
    score += 0.14 * (pr - mean_residual).max(0.0);

    // New-bin candidate: keep closed unless fragmentation is severe or item is huge
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap) * open_bins_count as f64;
        let huge_item = fit_ratio > 0.7;
        let next_huge = next_item_size as f64 > 0.5 * cap;
        let tight_stream = fit_ratio > 0.5 && next_item_size as f64 > 0.5 * cap;
        if fragmentation > 0.5 || (huge_item && (next_huge || open_bins_count == 0)) || tight_stream {
            score -= 65.0 - 20.0 * progress;
        } else {
            score += 170.0 + 25.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small residue" classes (0..=10) are nearly perfect; reward them hard.
    let residue_class = post_residual % 25;
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else if residue_class <= 10 {
        score -= 25.0 - 2.0 * residue_class as f64;
    } else {
        // Larger dead space: penalize non-linearly with wasted fraction.
        let waste_frac = post_residual as f64 / bin_capacity as f64;
        score += 20.0 * waste_frac * waste_frac;
    }

    // Integer-division threshold: does the leftover still admit a "useful chunk"?
    // A chunk is defined as >= 20 (typical mid-size item). If the leftover can
    // host another item of the expected next size, reward it.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
            // extra harmony: leftover after hosting next item again in a good class
            let second = post_residual - next_item_size;
            if second % 25 <= 10 {
                score -= 8.0;
            }
        } else {
            score += 6.0; // this bin cannot serve the lookahead item
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin for a marginal fit.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // With many fitting bins, mild penalty for spreading; prefer tight fits.
        score += 1.5 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when the fit would leave a bad residue elsewhere or
    // item is large relative to capacity.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        // Large items (> half) deserve fresh bins; small items should reuse.
        if frac > 0.5 {
            score -= 18.0 + 10.0 * frac;
        } else {
            score += 15.0 - 20.0 * frac;
        }
        // Early in the stream, opening bins is cheap; later, conserve.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Coupling with mean residual: if this bin's post residual is far below
    // the mean, we are compacting well; reward.
    let diff = mean_residual - post_residual as f64;
    score -= 0.15 * diff;

    // Modulo harmony on item size: items in classes {50..=60, 100} pair well
    // with typical residuals; slight reward.
    let item_class = item_size % 50;
    if item_class >= 40 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
