            // Next item cannot follow into this bin: penalize proportional overflow.
            score += 0.9 * (next_item_size - post_residual) as f64;
        }
    }

    // Dead-space ratio term: penalize bins whose post residual is a large fraction
    // of capacity that no plausible item will fill.
    if post_residual > 0 {
        let dead_ratio = post_residual as f64 / cap;
        if dead_ratio > 0.25 {
            score += 70.0 * (dead_ratio - 0.25);
        }
        // Extra pressure on medium residuals nobody can top up efficiently.
        if dead_ratio > 0.15 && dead_ratio <= 0.25 && post_residual < item_size {
            score += 12.0;
