    score -= 25.0 * fill_ratio;

    // Penalty for opening a new bin when open bins could fit, unless it avoids dead space.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 40.0;
        // If the item would leave a small gap in existing bins, new bin is attractive.
        if post_residual >= bin_capacity - item_size {
            score += 0.0; // empty bin post_residual = capacity - item
        }
        if item_size >= 50 {
            score -= 30.0; // large items open fresh bins happily
        }
    }

    // Open bins pressure: with many open bins, prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64).ln().max(0.0) * 3.0 * (1.0 - progress);

