        score -= 12.0 + 1.2 * (22.0 - pr);
    } else if pr <= 32.0 {
        score -= 4.0 + 0.5 * (32.0 - pr);
    }

    // Lookahead: two-step fit quality with next item
    if next > 0.0 && pr > 0.0 {
        if next == pr {
            score -= 850.0;
        } else if next < pr {
            let waste = pr - next;
            if waste <= 8.0 {
                score -= 130.0 - 2.0 * waste;
            } else {
                score -= 70.0 - 0.5 * waste;
            }
            if waste <= 3.0 {
                score -= 45.0;
            }
        } else {
            let miss = next - pr;
            score += 0.9 * miss;
            if miss > 30.0 {
                score += 0.4 * (miss - 30.0);
            }
        }
    }

    // Scarcity boost: reward tight packing when few bins can fit next item
    if next > 0.0 && pr >= next {
        let slack = pr - next;
        let scarcity = 1.0 / fitting_bins_count.max(1) as f64;
        let boost = 30.0 + 20.0 * scarcity;
        score -= boost * (1.0 - slack / cap) * (0.6 + 0.4 * (1.0 - t));
        if fitting_bins_count <= 2 {
            score -= 12.0 * (1.0 - slack / cap);
        }
    }

    // Mild consolidation pressure when many bins are open
    score += 0.05 * open_bins_count as f64 * (1.0 - fill);

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap) * open_bins_count as f64;
        let huge_item = item_size as f64 > 0.7 * cap;
        let remaining_frac = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;
        let fresh_post = cap - item_size as f64;
        let fresh_is_exact = fresh_post <= 4.0;
        if fragmentation > 0.55 || (huge_item && open_bins_count > 4) {
            score -= 60.0 + 40.0 * remaining_frac;
        } else if fresh_is_exact {
            score -= 120.0 + 60.0 * remaining_frac;
        } else {
            score += 400.0 - 80.0 * remaining_frac;
            if fitting_bins_count <= 3 && open_bins_count > 2 {
                score -= 25.0 + 15.0 * remaining_frac;
            }
        }
        let fresh_match = (fresh_post - mean_residual).abs() / cap;
        if fresh_match < 0.05 {
            score -= 70.0 * (1.0 - fresh_match / 0.05);
        }
        if remaining_frac < 0.05 && fresh_post > 0.0 && !fresh_is_exact {
            score += 150.0 * (fresh_post / cap);
        }
        if fresh_post > 0.0 && fresh_post <= 22.0 && !fresh_is_exact {
            score -= 20.0 * (1.0 - fresh_post / 22.0);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for typical future items are wasted.
    // Treat post_residual below a "usefulness threshold" as partially dead.
    let dead_threshold = 30.0f64;
    if (post_residual as f64) < dead_threshold {
        let dead_frac = (dead_threshold - post_residual as f64) / dead_threshold;
        score += 12.0 * dead_frac * dead_frac; // quadratic penalty on unusable gaps
    }

    // Perfect / near-perfect fit reward: subtract to strongly favor tight placements.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin has post_residual = C - item.
    // Prefer keeping the new-bin option only when no open bin fits well.
    if bin_residual == bin_capacity {
        // Mild penalty so open bins with decent fits win; but if open bins
        // would leave tiny dead space, the new bin (large residual) is attractive.
        score += 8.0;
        // Open-bin pressure: many open bins -> discourage opening more.
        score += 2.0 * open_bins_count as f64;
    } else {
        // Reward using existing bins when open bins count is high (bin pressure).
        score -= (open_bins_count as f64).min(10.0) * 0.8;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 10.0 {
                score -= 8.0 * (1.0 - slack / 10.0);
            }
        } else {
            // Next item cannot use this residual: residual likely dead.
            score += 4.0;
        }
    }

    // Mean residual coupling: if this bin's residual is far below mean,
    // closing it out (filling tightly) is good — reward that.
    let residual_gap = mean_residual - post_residual as f64;
    if residual_gap > 0.0 {
        score -= 0.5 * residual_gap.min(50.0);
    }

    // Late-stream tightness: as the stream progresses, prefer tighter fits more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 - 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress factor: later in the stream, be more aggressive about tight packing.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Perfect 2-step lookahead match: post_residual exactly equals next item -> huge reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0 + 40.0 * progress;
    }
    // Next item fits exactly into the remaining space after a near-match: strong reward.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        // Reward decays with slack: prefer bins where next item consumes most of the leftover.
        score -= (50.0 * (1.0 - slack / bin_capacity as f64)) * (0.5 + 0.5 * progress);
    }
    // Dead space: post_residual too small for the next item.
    else if next_item_size > 0 && post_residual < next_item_size {
        // Penalize unusable leftover, worse when very small (fragmentation).
        let frag = post_residual as f64 / next_item_size as f64;
        score += 25.0 * (1.0 - frag) * (0.6 + 0.4 * progress);
    }

    // Reward bins that are already tighter than average (consume dense bins first).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
        if post_residual < 10 {
            score += 15.0; // but avoid creating tiny dead slivers
        }
    }

    // New-bin candidate (empty bin): make it moderately attractive only when
    // the item is large relative to capacity or no good fit exists among open bins.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        // Default: discourage new bins so open bins get filled first.
        score += 20.0;
        // Large items waste less by opening a fresh bin; small items should never open one.
        score -= 40.0 * large_item * large_item;
        // If many bins already open and mean residual is high, opening a new bin
        // is fine (stream is fragmented anyway).
        if open_bins_count > 3 && mean_residual > bin_capacity as f64 * 0.5 {
            score -= 15.0;
        }
    }

    // Small stabilizing tie-breaker: prefer bins with less residual overall, slightly
    // more aggressively as the stream progresses.
    score -= progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let t = step_index as f64 / total_items.max(1) as f64;
    let fill = 1.0 - pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let progress_warp = 0.5 + 0.5 * (t * std::f64::consts::PI).sin();
    let mut score = pr * (1.0 + 0.6 * progress_warp * fill * fill);

    // Strong bonus for exact / near-exact closure (kills slivers)
    if pr == 0.0 {
        score -= 1000.0;
    } else if pr <= 4.0 {
        score -= 250.0 + 2.5 * (4.0 - pr);
    } else if pr <= 10.0 {
        score -= 60.0 + 3.0 * (10.0 - pr);
    } else if pr <= 22.0 {
        score -= 12.0 + 1.2 * (22.0 - pr);
    }

    // Lookahead: two-step fit with next item
    if next_item_size > 0 && pr > 0.0 {
        let ni = next_item_size as f64;
        if (ni - pr).abs() < 0.5 {
            score -= 850.0;
        } else if ni < pr {
            let slack = pr - ni;
            if slack <= 8.0 {
                score -= 130.0 - 2.0 * slack;
            } else {
                score -= 70.0 - 0.5 * slack;
            }
        } else {
            let miss = ni - pr;
            score += 0.9 * miss;
            if miss > 30.0 {
                score += 0.4 * (miss - 30.0);
            }
        }
    }

    // Reward scarce fitting capacity
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - t);
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.05 * open_bins_count as f64 * (1.0 - fill);

    // Prefer bins near mean residual (balance) with smooth term
    score += 0.1 * (pr - mean_residual) * (pr - mean_residual) / cap;

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let fresh_post = cap - item_size as f64;
        let remaining_frac = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;
        let huge_item = item_size as f64 > 0.7 * cap;
        let fragmentation = (mean_residual / cap) * open_bins_count as f64;
        let fresh_exact = fresh_post <= 4.0;

        if fresh_exact {
            score -= 120.0 + 60.0 * remaining_frac;
        } else if (fragmentation > 0.55 || huge_item) && open_bins_count > 4 {
            score -= 60.0 + 40.0 * remaining_frac;
        } else {
            score += 400.0 - 80.0 * remaining_frac;
            if fitting_bins_count <= 3 && open_bins_count > 2 {
                score -= 25.0 + 15.0 * remaining_frac;
            }
        }
        let fresh_match = (fresh_post - mean_residual).abs() / cap;
        if fresh_match < 0.05 {
            score -= 70.0 * (1.0 - fresh_match / 0.05);
        }
        if fresh_post > 0.0 && fresh_post <= 22.0 && !fresh_exact {
            score -= 20.0 * (1.0 - fresh_post / 22.0);
        }
        if remaining_frac < 0.05 && fresh_post > 0.0 && !fresh_exact {
            score += 150.0 * (fresh_post / cap);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * 20.0;

    // Lookahead: if next item fits exactly in the post-residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let slack_after_next = post_residual - next_item_size;
            score -= 15.0 * (1.0 - slack_after_next as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize wasted residual slightly.
            score += 8.0 * fit_ratio;
        }
    } else {
        // Last item: any residual is pure waste; reward tightest packing.
        score += 10.0 * fit_ratio;
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // Global pressure: many open bins with high mean residual -> consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if mean_residual > item_size as f64 * 1.5 && open_bins_count > 1 {
        score -= 10.0 * (mean_residual - item_size as f64) / bin_capacity as f64;
    }

    // Time horizon: early in stream, opening new bins is cheap; later, avoid fragmentation.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and when other bins fit.
        let early = 1.0 - progress;
        score += 25.0 * (1.0 - early) + 5.0;
        if fitting_bins_count > 0 {
            score += 30.0 * progress;
        }
        // But if open bins are all nearly full (low mean residual), new bin is fine.
        if mean_residual < item_size as f64 {
            score -= 40.0;
        }
    }

    // Non-linear coupling: penalize residuals in the awkward zone (just below common item sizes).
    let awkward = (post_residual as f64 / 10.0).sin().abs();
    score += 6.0 * awkward * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
