    // Penalize slivers unusable by next item (parent coupling, tuned)
    if n > 0.0 && pr < n && pr > 0.0 {
        score += (n - pr) * (0.8 + 0.6 * t);
    }

    // Consolidation pressure when many bins open
    score += 0.04 * open_bins_count as f64 * (1.0 - fill);

    // Mild balance toward mean residual
    score += 0.08 * (pr - mean_residual) * (pr - mean_residual) / cap;

    // New-bin candidate logic (adapted from best)
    if bin_residual == bin_capacity {
        let fresh_post = cap - item_size as f64;
        let fresh_exact = fresh_post >= 0.0 && fresh_post <= 4.0;
        let fragmentation = (mean_residual / cap) * open_bins_count as f64;
        let remaining_frac = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;
        let huge = item_size as f64 > 0.7 * cap;

        if fresh_exact {
