pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // ---- Harmonic class of the post residual ----
    // Class 0: perfect fit (post_residual == 0) -> strongest reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Small dead space classes are strongly preferred over large ones.
        // Use integer division thresholds on post_residual (harmonic bands).
        let band = post_residual / 10; // 0..=9 bands
        score += band as f64 * 7.5;

        // Exact "harmonic" residuals that pair well with common item sizes:
        // residuals that are multiples of 10 are reusable slots.
        if post_residual % 10 == 0 {
            score -= 12.0;
        }
        // Residuals that are prime-ish / awkward (not divisible by 2 or 5) are dead space.
        if post_residual % 2 != 0 && post_residual % 5 != 0 {
            score += 9.0;
        }
    }

    // ---- Lookahead coupling (k=2) ----
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // The next item also fits here: reward chaining.
            score -= 25.0 + 0.35 * next_item_size as f64;
            // Perfect chain: next item exactly consumes the rest.
            if next_item_size == post_residual {
                score -= 150.0;
            }
        } else {
            // Next item won't fit here: the leftover becomes dead space.
            // Penalize proportionally to how much is wasted relative to next size.
            let gap = next_item_size - post_residual;
            score += 0.25 * gap as f64;
        }
    }

    // ---- Last-chance logic ----
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        // This is the only open bin that fits: strongly prefer using it
        // over opening a new bin, unless the fit is terrible.
        score -= 60.0 + 0.4 * item_size as f64;
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // A fresh bin should only win when no decent fit exists.
        // Base penalty: prefer filling existing bins in general.
        score += 55.0 + 0.5 * item_size as f64;
        // If absolutely no open bin fits, the new bin must win.
        if fitting_bins_count == 0 {
            score -= 2000.0;
        }
        // Early in the stream, opening bins is cheaper (builds a pool).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 30.0 * (1.0 - progress);
    }

    // ---- Open-bin pool pressure ----
    // Many open bins with high mean residual -> prefer consolidating into
    // the emptiest-fitting bins; penalize when this bin is above mean residual.
    if bin_residual < bin_capacity {
        if (bin_residual as f64) > mean_residual + 1.0 {
            score += 0.3 * (bin_residual as f64 - mean_residual);
        } else {
            score -= 0.15 * (mean_residual - bin_residual as f64);
        }
        // Slight preference for fewer open bins overall.
        score += 0.5 * open_bins_count as f64;
    }

    // ---- Modulo arithmetic coupling between item and capacity ----
    // Items that divide the capacity harmonically pack cleanly.
    if bin_capacity % item_size.max(1) == 0 {
        score -= 6.0;
    }
    // GCD-style harmony: if item size divides the residual exactly (post 0 handled),
    // near-harmonic splits get a small nudge.
    if post_residual > 0 && item_size.max(1) % 10 == 0 && post_residual % 10 == 0 {
        score -= 8.0;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
