pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: heavily reward zero dead space.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Strict dead-space avoidance: residuals that are small but unusable
    // (below a plausible minimum item footprint) are the worst outcome.
    let dead_zone = 10.0f64.min(bin_capacity as f64 * 0.1);
    if post_residual > 0 && (post_residual as f64) < dead_zone {
        score += (dead_zone - post_residual as f64) * 8.0;
    }

    // Moderate waste also penalized non-linearly (quadratic in wasted fraction).
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += waste_frac * waste_frac * 60.0;

    // Lookahead: if the next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size > post_residual {
            // This bin's leftover can't serve the next item: penalize proportionally.
            score += (post_residual as f64 / bin_capacity as f64) * 40.0;
        } else {
            // Next item fits but leaves another gap: mild reward scaled by snugness.
            let snug = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= snug * 30.0;
        }
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: discourage proliferating bins when many are already open.
    // Applied via the new-bin candidate (bin_residual == bin_capacity) and mildly to all.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + progress);
    if bin_residual == bin_capacity {
        score += pressure * 10.0;
        // New bin also absorbs mean residual burden: penalize if existing bins are empty-ish.
        score += mean_residual * 0.3;
    } else {
        score -= pressure * 0.2;
    }

    // Prefer filling bins that are already well-utilized (low residual relative to capacity).
    score += (bin_residual as f64 / bin_capacity as f64) * 15.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: favor bins whose post_residual matches the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect chain: this bin's leftover exactly hosts the next item.
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item still fits here afterwards: mild reward, tighter the better.
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 - slack * 0.15;
        } else {
            // Next item won't fit in the leftover: penalize wasted potential,
            // scaled by how close we came (near-misses are the worst dead space).
            let miss = (next_item_size - post_residual) as f64;
            score += 8.0 + miss * 0.30;
        }
    } else {
        // Last item: pure tight-fit preference.
        score -= 10.0;
    }

    // Relative-to-mean residual shaping: bins already tighter than average
    // are good finishers; bins looser than average should absorb big items.
    let post_f = post_residual as f64;
    if post_f < mean_residual {
        score -= (mean_residual - post_f) * 0.25;
    } else {
        score += (post_f - mean_residual) * 0.15;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // New-bin candidate handling: an empty bin has large post_residual,
    // so it naturally scores high (bad). Allow opening a new bin only when
    // the item is large relative to a typical residual and no good fit exists.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let item_frac = item_size as f64 / bin_capacity as f64;
        // Penalize new bins more as the stream matures and for small items.
        score += 45.0 + 40.0 * (1.0 - item_frac) + 20.0 * progress;
        // But if the next item is huge and this item nearly fills a bin,
        // a fresh bin can be attractive.
        if next_item_size > 0 && item_size >= 70 && next_item_size >= 60 {
            score -= 55.0;
        }
    }

    // Slight penalty for leaving large awkward gaps (dead space 1..=9 is worst).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: prefer bins where the item fills a large fraction of residual.
    if bin_residual > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 12.0 * fill_ratio * fill_ratio;
    }

    // Penalize large dead space after placement, especially small residuals (< next item).
    if post_residual > 0 {
        if next_item_size > 0 && (post_residual as u32) < next_item_size {
            score += 6.0;
        }
        score += 0.05 * (post_residual as f64).sqrt() * (post_residual as f64 / bin_capacity as f64);
    }

    // Lookahead: reward bins whose post-residual exactly fits the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0;
        } else if post_residual > next_item_size {
            score -= 4.0 * (post_residual as f64 - next_item_size as f64).min(20.0) / 20.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Global state: when many bins are open, discourage opening new ones
    // (the new-bin candidate has bin_residual == bin_capacity).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        let open_pressure = (open_bins_count as f64 / 10.0).min(3.0);
        score += 10.0 + 8.0 * open_pressure + 5.0 * progress;
        // But allow new bin if mean residual is small (all bins nearly full).
        score -= 12.0 * (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
    }

    // Mean residual coupling: prefer bins deviating below the mean (consolidate emptier bins).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Time horizon: early on, be slightly exploratory toward tight fits; late, be greedy.
    score -= 5.0 * (1.0 - progress) * (item_size as f64 / bin_capacity as f64);

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 4 {
        score -= 280.0 + 2.5 * (4 - post_residual) as f64;
    } else if post_residual <= 10 {
        score -= 60.0 + 3.0 * (10 - post_residual) as f64;
    } else if post_residual <= 22 {
        score -= 12.0 + 1.2 * (22 - post_residual) as f64;
    } else if post_residual <= 32 {
        score -= 4.0 + 0.5 * (32 - post_residual) as f64;
    }

    // Time-varying weight: early on, keep bins homogeneous; late, pack tight.
    let w = 0.35 + 0.65 * progress * progress;
    score *= w;

    // Lookahead coupling with next item.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 850.0;
        } else if next_item_size < post_residual {
            let two_step_waste = (post_residual - next_item_size) as f64;
            if two_step_waste <= 8.0 {
                score -= 130.0 - 2.0 * two_step_waste;
            } else {
                score -= 70.0 - 0.5 * two_step_waste;
            }
            if two_step_waste <= 3.0 {
                score -= 45.0;
            }
        } else {
            let miss = (next_item_size - post_residual) as f64;
            score += 0.9 * miss;
            if miss > 30.0 {
                score += 0.4 * (miss - 30.0);
            }
        }
    }

    // Two-step lookahead with scarcity weighting on fitting bins.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
        let boost = 30.0 + 20.0 * scarcity;
        score -= boost * (1.0 - slack / cap) * (0.6 + 0.4 * (1.0 - progress));
        if fitting_bins_count <= 2 {
            score -= 12.0 * (1.0 - slack / cap);
        }
    }

    // New-bin candidate logic.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap) * open_bins_count as f64;
        let huge_item = item_size as f64 > 0.7 * cap;
        let remaining = if total_items > step_index { total_items - step_index } else { 1 };
        let remaining_frac = remaining as f64 / total_items.max(1) as f64;
        let fresh_post = cap - item_size as f64;
        let fresh_is_exact = fresh_post <= 4.0 && fresh_post >= 0.0;

        if fragmentation > 0.55 || (huge_item && open_bins_count > 4) {
            score -= 60.0 + 40.0 * remaining_frac;
        } else if fresh_is_exact {
            score -= 120.0 + 60.0 * remaining_frac;
        } else {
            score += 400.0 - 80.0 * remaining_frac;
            if fitting_bins_count <= 3 && open_bins_count > 2 {
                score -= 25.0 + 15.0 * remaining_frac;
            }
        }

        // Prefer a fresh bin whose post-residual matches the mean residual of open bins.
        let fresh_match = (fresh_post - mean_residual).abs() / cap;
        if fresh_match < 0.05 {
            score -= 70.0 * (1.0 - fresh_match / 0.05);
        }

        // Endgame: avoid opening bins that will strand dead space.
        if remaining_frac < 0.05 && fresh_post > 0.0 && !fresh_is_exact {
            score += 150.0 * (fresh_post / cap);
        }

        // Fresh bin leaving a moderate residual is fine if it can host the next item.
        if fresh_post > 0.0 && fresh_post <= 22.0 && !fresh_is_exact {
            score -= 20.0 * (1.0 - fresh_post / 22.0);
        }
    }

    // Mild homogeneity preference for open bins.
    if bin_residual < bin_capacity {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

