    let crowding = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score += 15.0 * crowding * (norm_pr - mean_residual / cap);

    // New-bin candidate handling: make empty bin attractive only when it beats waste
    if bin_residual == bin_capacity {
        let newbin_bias = 20.0 + 60.0 * (1.0 - t) * (item_size as f64 / cap);
        score += newbin_bias;
        if fitting_bins_count <= 1 {
            score -= 50.0;
        }
    }

    score
}

