            score -= 15.0; // next item still fits here
            // harmonic match between next item and post residual
            if post_residual % next_item_size == 0 {
                score -= 10.0;
            }
        } else {
            // next item will NOT fit: penalize small dead residuals harder
            let gap = (next_item_size - post_residual) as f64;
            score += gap.min(30.0) * 0.8;
        }
