    // current bin is large relative to the item (i.e., item is small) or
    // many bins are already open and mean residual is low (fragmentation).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let frag = (mean_residual / bin_capacity as f64).max(0.0);
