    // (keep bin states homogeneous, easier to pack later)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Integer-division threshold: residuals in awkward mid ranges (< next
    // typical size) are dead space; nudge score up
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Perfect fill is always best.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 4 {
        score -= 280.0 + 2.0 * (4 - post_residual) as f64;
    } else if post_residual <= 10 {
        score -= 60.0 + 3.0 * (10 - post_residual) as f64;
    } else if post_residual <= 22 {
        score -= 12.0 + 1.2 * (22 - post_residual) as f64;
    } else if post_residual <= 32 {
        score -= 4.0 + 0.5 * (32 - post_residual) as f64;
    }

    // Down-weight absolute residual late in the stream (keeps early lookahead dominant).
    let w = 0.35 + 0.65 * progress * progress;
    score *= w;

    // Lookahead coupling with next item.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 850.0;
        } else if next_item_size < post_residual {
            let two_step_waste = (post_residual - next_item_size) as f64;
            if two_step_waste <= 10.0 {
                score -= 120.0 - 2.0 * two_step_waste;
            } else {
                score -= 80.0 - 0.4 * two_step_waste;
            }
            if two_step_waste <= 3.0 {
                score -= 40.0;
            }
        } else {
            let miss = (next_item_size - post_residual) as f64;
            score += 0.9 * miss;
            if miss > 30.0 {
                score += 0.4 * (miss - 30.0);
            }
        }
    }

    // Two-step lookahead: reward residuals that stay tight after next item,
    // scaled by scarcity of alternative fits.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
        let boost = 30.0 + 20.0 * scarcity;
        score -= boost * (1.0 - slack / cap) * (0.6 + 0.4 * (1.0 - progress));
        if fitting_bins_count <= 2 {
            score -= 12.0 * (1.0 - slack / cap);
        }
    }

    // New-bin decision: prefer open bins unless fragmented or a large item would fit.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap) * open_bins_count as f64;
        let huge_item = item_size as f64 > 0.7 * cap;
        let remaining = if total_items > step_index { total_items - step_index } else { 1 };
        let remaining_frac = remaining as f64 / total_items.max(1) as f64;
        let fresh_post = cap - item_size as f64;
        let fresh_is_exact = fresh_post <= 4.0 && fresh_post >= 0.0;

        if fragmentation > 0.55 || (huge_item && open_bins_count > 4) {
            score -= 60.0 + 40.0 * remaining_frac;
        } else if fresh_is_exact {
            score -= 120.0 + 60.0 * remaining_frac;
        } else {
            score += 400.0 - 80.0 * remaining_frac;
            if fitting_bins_count <= 3 && open_bins_count > 2 {
                score -= 25.0 + 15.0 * remaining_frac;
            }
        }

        // Fresh bin whose post residual matches mean residual is promising.
        let fresh_match = (fresh_post - mean_residual).abs() / cap;
        if fresh_match < 0.05 {
            score -= 70.0 * (1.0 - fresh_match / 0.05);
        }

        // End of stream: avoid opening fresh bins with dead space.
        if remaining_frac < 0.05 && fresh_post > 0.0 && !fresh_is_exact {
            score += 150.0 * (fresh_post / cap);
        }

        // Fresh bin leaving a small workable residual is fine mid-stream.
        if fresh_post > 0.0 && fresh_post <= 22.0 && !fresh_is_exact {
            score -= 20.0 * (1.0 - fresh_post / 22.0);
        }
    }

    // Mild preference for bins whose residual is close to mean residual.
    if bin_residual < bin_capacity {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

