        score += 60.0 * (11.0 - post_residual as f64);
    }
    // Gaps that cannot fit the smallest plausible item are dead weight.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Mid-range gaps that cannot fit the lookahead item are likely waste.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Open-bin pressure: discourage spreading when many bins are open.
    score += 0.35 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it attractive only when current bin fits are poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin.
        score += 45.0;
        // Cheaper to open a new bin when existing residuals are large and fragmented.
        score -= 0.15 * mean_residual;
        // Late in the stream, prefer consolidating rather than opening bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
        // If lookahead won't fit anywhere nicely anyway, new bin is fine.
        if next_item_size > 0 && next_item_size > bin_capacity.saturating_sub(mean_residual as u32) {
            score -= 10.0;
        }
    }

    // Mild preference for bins below mean residual (balance fragmentation).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
