            let miss = n - pr;
            score += 0.9 * miss;
            if miss > 30.0 {
                score += 0.4 * (miss - 30.0);
            }
        }
    }

    // Prefer tighter-than-mean bins
    score += 0.15 * (pr - mean_residual) * (1.0 + progress);

