        score -= 900.0;
    } else if post_residual <= 4 {
        score -= 220.0 + 2.5 * (4 - post_residual) as f64;
    } else if post_residual <= 10 {
        score -= 55.0 + 3.0 * (10 - post_residual) as f64;
    } else if post_residual <= 22 {
        score -= 12.0 + 1.2 * (22 - post_residual) as f64;
    } else if post_residual <= 32 {
        score -= 4.0 + 0.5 * (32 - post_residual) as f64;
    } else if post_residual <= 48 {
        score -= 1.0 + 0.15 * (48 - post_residual) as f64;
    }

    // Tightness reward.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
