    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Tiered reward for small post residuals (tight fits).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 4 {
        score -= 250.0 + 2.5 * (4 - post_residual) as f64;
    } else if post_residual <= 10 {
        score -= 60.0 + 3.0 * (10 - post_residual) as f64;
    } else if post_residual <= 22 {
        score -= 12.0 + 1.2 * (22 - post_residual) as f64;
    } else if post_residual <= 48 {
        score -= 1.0 + 0.15 * (48 - post_residual) as f64;
    }

    // Tightness reward.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Open-bin pressure scaled by progress.
    let w = 0.35 + 0.65 * progress * progress;
    score += 0.35 * open_bins_count as f64 * w;

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

