        let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
        score -= (25.0 + 20.0 * scarcity) * (1.0 - slack / cap) * (0.6 + 0.4 * (1.0 - progress));
        if fitting_bins_count <= 2 { score -= 12.0 * (1.0 - slack / cap); }
    }

    // Open-bin pressure scaled by progress.
    score += (0.35 + 0.5 * progress * progress) * open_bins_count as f64;

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let remaining_frac = if total_items > step_index { (total_items - step_index) as f64 / total_items.max(1) as f64 } else { 0.0 };
        let fresh_post = cap - item_size as f64;
        let fragmentation = (mean_residual / cap) * open_bins_count as f64;
        let fresh_is_exact = fresh_post <= 4.0 && fresh_post >= 0.0;
        let huge_item = item_size as f64 > 0.7 * cap;

        if fragmentation > 0.55 || (huge_item && open_bins_count > 4) {
            score -= 60.0 + 40.0 * remaining_frac;
        } else if fresh_is_exact {
            score -= 120.0 + 60.0 * remaining_frac;
        } else {
            score += 380.0 - 80.0 * remaining_frac;
            if fitting_bins_count <= 3 && open_bins_count > 2 {
                score -= 25.0 + 15.0 * remaining_frac;
            }
        }

        // Fresh post matches mean residual shape -> good reuse.
        let fresh_match = (fresh_post - mean_residual).abs() / cap;
        if fresh_match < 0.12 {
            score -= 30.0 * (1.0 - fresh_match / 0.12);
        }

        // Fresh bin exactly hosts next item while open bins cannot.
        if next_item_size > 0 && fresh_post > 0.0 {
            let fresh_exact_next = (fresh_post as u32) == next_item_size;
            let open_can_next = mean_residual >= next_item_size as f64;
            if fresh_exact_next && !open_can_next && fitting_bins_count <= 2 {
                score -= 45.0 * (1.0 - progress);
            }
            if (fresh_post as u32) < next_item_size && mean_residual > next_item_size as f64 {
                score += 18.0 * (1.0 - progress);
            }
        }

        // Late stream: penalize opening non-exact fresh bins.
        if remaining_frac < 0.05 && fresh_post > 0.0 && !fresh_is_exact {
            score += 150.0 * (fresh_post / cap);
        }
        if fresh_post > 0.0 && fresh_post <= 22.0 && !fresh_is_exact {
            score -= 20.0 * (1.0 - fresh_post / 22.0);
        }
    } else {
        // Dead-space ratio penalty for wasteful placements.
        let dead = (bin_residual - item_size) as f64;
        let dead_ratio = dead / cap;
        if dead_ratio > 0.5 && fitting_bins_count > 1 {
            score += 8.0 * (dead_ratio - 0.5) * (1.0 - progress);
        }
        if dead_ratio > 0.35 && fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
            let tight = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score += 5.0 * (dead_ratio - 0.35) * tight * (1.0 - progress);
        }
        // Stranded residual between usable sizes.
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            let stranded = (next_item_size - post_residual) as f64;
            if stranded <= 10.0 {
                let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
                score += (6.0 + 0.8 * (10.0 - stranded)) * scarcity * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        // Chain divisibility: residuals that can host repeated next items.
        if next_item_size > 0 && post_residual > next_item_size {
            let chain = post_residual % next_item_size.max(1);
            if chain == 0 {
                score -= 20.0 * (1.0 - progress);
            } else if chain <= 3 {
                score -= 8.0 * (1.0 - progress);
            }
        }
    }

    // Mild balance preference.
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
