    }

    // Layered near-perfect fill rewards (borrowed tiering, tightened).
    if post_residual > 0 {
        if post_residual <= 4 {
            score -= 280.0 + 2.0 * (4 - post_residual) as f64;
        } else if post_residual <= 10 {
            score -= 60.0 + 3.0 * (10 - post_residual) as f64;
        } else if post_residual <= 22 {
            score -= 12.0 + 1.2 * (22 - post_residual) as f64;
        } else if post_residual <= 32 {
            score -= 4.0 + 0.5 * (32 - post_residual) as f64;
        } else if post_residual <= 48 {
            score -= 1.0 + 0.15 * (48 - post_residual) as f64;
        }
    }

    // Lookahead with next item.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 850.0;
        } else if next_item_size < post_residual {
            let two_step_waste = (post_residual - next_item_size) as f64;
            if two_step_waste <= 10.0 {
                score -= 110.0 - 2.0 * two_step_waste;
            } else {
                score -= 90.0 - 0.3 * two_step_waste;
            }
            if two_step_waste <= 3.0 {
                score -= 45.0;
            }
            // Chain divisibility: residual reusable repeatedly by next item.
            let chain = post_residual % next_item_size.max(1);
            if chain == 0 {
                score -= 20.0 * (1.0 - progress);
            } else if chain <= 3 {
                score -= 8.0 * (1.0 - progress);
            }
        } else {
            let miss = (next_item_size - post_residual) as f64;
            score += 0.9 * miss;
            if miss > 30.0 {
                score += 0.4 * (miss - 30.0);
            }
            // Stranded small residual: too small for next item, weighted by scarcity.
            if miss <= 10.0 {
                let scarcity = 1.0 / fitting_bins_count.max(1) as f64;
                score += (6.0 + 0.8 * (10.0 - miss)) * scarcity * (0.4 + 0.6 * (1.0 - progress));
            }
        }
    }

    // Two-step lookahead: next item fits and leaves tiny remainder.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack > 0.0 && slack <= 6.0 {
            score -= 40.0;
        }
        let scarcity = 1.0 / fitting_bins_count.max(1) as f64;
        score -= (30.0 + 20.0 * scarcity) * (1.0 - slack / cap) * (0.6 + 0.4 * (1.0 - progress));
        if fitting_bins_count <= 2 {
            score -= 12.0 * (1.0 - slack / cap);
        }
        if slack == 0.0 {
            score -= 15.0 * (1.0 - progress);
        }
    }

    // Dead-space sharpening for open bins.
    if bin_residual != bin_capacity {
        let dead = (bin_residual - item_size) as f64;
        let dead_ratio = dead / cap;
        if dead_ratio > 0.5 && fitting_bins_count > 1 {
            score += 8.0 * (dead_ratio - 0.5) * (1.0 - progress);
        }
        if post_residual > 12 && post_residual < 40 && next_item_size > post_residual {
            let orphan = (post_residual as f64 - 12.0) / 28.0;
            let scarcity = 1.0 / fitting_bins_count.max(1) as f64;
            score += 14.0 * orphan * scarcity * (0.5 + 0.5 * (1.0 - progress));
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
            && mean_residual > 0.0 && (mean_residual as u32) >= next_item_size {
            score += 10.0;
        }
    }

    // New-bin decision: discourage unless justified.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap) * open_bins_count as f64;
        let huge_item = item_size as f64 > 0.7 * cap;
        let remaining = if total_items > step_index { total_items - step_index } else { 1 };
        let remaining_frac = remaining as f64 / total_items.max(1) as f64;
        let fresh_post = cap - item_size as f64;
