            }
        }
        if remaining_frac < 0.12 && fresh_post > 0.0 && !fresh_is_exact && mean_residual * open_bins_count as f64 > 3.0 * cap {
            score += 40.0 * (1.0 - remaining_frac / 0.12);
        }
        // When only one open bin can fit and this item would leave a
        // tiny stranded residual there, opening a fresh bin is often better.
        if fitting_bins_count == 1 && fresh_post > 0.0 {
            if next_item_size > 0 {
                let would_strand = bin_capacity.saturating_sub(item_size) < next_item_size;
