}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Layered dead-space rewards (lower post_residual = better), slightly
    // steepened in the mid range to punish mediocre fits harder.
    if post_residual == 0 {
        score -= 980.0;
    } else if post_residual <= 4 {
        score -= 240.0 + 3.5 * (4 - post_residual) as f64;
    } else if post_residual <= 10 {
        score -= 62.0 + 3.8 * (10 - post_residual) as f64;
    } else if post_residual <= 22 {
        score -= 13.0 + 1.6 * (22 - post_residual) as f64;
    } else if post_residual <= 32 {
        score -= 5.0 + 0.7 * (32 - post_residual) as f64;
    } else if post_residual <= 48 {
        score -= 1.2 + 0.2 * (48 - post_residual) as f64;
    } else {
        score -= 1.2 - 0.014 * (post_residual as f64 - 48.0);
    }

    // Progress-scaled weighting: tighten late in the stream.
    let w = 0.33 + 0.67 * progress * progress;
    score *= w;

    // Lookahead coupling with the next item.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 860.0;
        } else if next_item_size < post_residual {
            let two_step_waste = (post_residual - next_item_size) as f64;
            if two_step_waste <= 8.0 {
                score -= 130.0 - 2.2 * two_step_waste;
            } else {
                score -= 70.0 - 0.55 * two_step_waste;
            }
            if two_step_waste <= 3.0 {
                score -= 46.0;
            }
        } else {
            let miss = (next_item_size - post_residual) as f64;
            score += 0.95 * miss;
            if miss > 26.0 {
                score += 0.5 * (miss - 26.0);
            }
        }
    }

    // Slack-based scarcity boost when the next item fits here.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
        let boost = 34.0 + 24.0 * scarcity;
        score -= boost * (1.0 - slack / cap) * (0.6 + 0.4 * (1.0 - progress));
        if fitting_bins_count <= 2 {
            score -= 14.0 * (1.0 - slack / cap);
        }
        if slack == 0.0 {
            score -= 18.0 * (1.0 - progress);
        }
    }

    if bin_residual != bin_capacity {
        let dead = (bin_residual - item_size) as f64;
        let dead_ratio = dead / cap;
        if dead_ratio > 0.5 && fitting_bins_count > 1 {
            score += 10.0 * (dead_ratio - 0.5) * (1.0 - progress);
        }
        // MUTATION: additional graded dead-ratio penalty — bins whose leftover
        // space after this item exceeds half the capacity are prime candidates
        // for better placements elsewhere, especially early in the stream.
        if dead_ratio > 0.6 && fitting_bins_count > 1 {
            score += 9.0 * (dead_ratio - 0.6) * (1.2 - progress);
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
            && mean_residual > 0.0 && (mean_residual as u32) >= next_item_size {
            score += 12.0;
        }
        if post_residual > 12 && post_residual < 40 && next_item_size > post_residual {
            let orphan = (post_residual as f64 - 12.0) / 28.0;
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            score += 16.0 * orphan * scarcity * (0.5 + 0.5 * (1.0 - progress));
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let chain = post_residual % next_item_size.max(1);
            if chain == 0 {
                score -= 24.0 * (1.0 - progress);
            } else if chain <= 3 {
                score -= 10.0 * (1.0 - progress);
            }
        }
        // Stranded residual: too small for next item, weighted by scarcity.
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            let stranded = (next_item_size - post_residual) as f64;
            if stranded <= 10.0 {
                let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
                score += (8.0 + 1.0 * (10.0 - stranded)) * scarcity * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        // Dead-space dominance penalty when tight fits exist elsewhere.
        if dead_ratio > 0.35 && fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score += 7.0 * (dead_ratio - 0.35) * tightness * (1.0 - progress);
        }
        // Penalize leaving a residual awkwardly below the mean open-bin residual.
        if post_residual > 0 && mean_residual > 0.0 {
            let gap = mean_residual - post_residual as f64;
            if gap > 0.0 && gap < 0.15 * cap && fitting_bins_count > 2 {
                score += 4.5 * (gap / (0.15 * cap)) * (1.0 - progress);
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size.max(1) && fitting_bins_count > 2 {
            score -= 6.0 * (1.0 - progress);
        }
        // Strong extra reward for exact fills of nearly-full bins — closing
        // out bins early frees capacity accounting for the whole stream.
        if post_residual == 0 && bin_residual < bin_capacity {
            score -= 40.0 * (1.0 - bin_residual as f64 / cap) * (1.0 - progress);
        }
        // MUTATION: reward near-exact fills too — a residual of 1-3 units is
        // almost as good as closing the bin, but only when it is unlikely any
        // future item (small items exist) could use that sliver.
        if post_residual >= 1 && post_residual <= 3 && bin_residual < bin_capacity {
            score -= 22.0 * (1.0 - bin_residual as f64 / cap) * (1.0 - progress);
        }
    } else {
