        // with the next item even though the current open-bin fits are loose —
        // a two-step lookahead for the new-bin branch.
        if next_item_size > 0 && fresh_post >= next_item_size as f64 {
            let fresh_two_step = fresh_post - next_item_size as f64;
            if fresh_two_step <= 6.0 && fragmentation < 0.55 {
                score -= 14.0 * (1.0 - fresh_two_step / 6.0) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
    }

    score
}

