            score -= 24.0 * (0.5 + 0.5 * (1.0 - progress));
        }
        // MUTATION: discourage opening bins mid-stream when the fresh residual
        // would be large and awkward (just above common item sizes), which
        // seeds future fragmentation.
        if remaining_frac > 0.3 && fresh_post > 40.0 && fresh_post < 0.6 * cap {
            score += 14.0 * (1.0 - progress);
        }
    }

