            let overshoot = post_residual.saturating_sub(next_item_size) as f64;
            if overshoot > 16.0 {
                score += 1.6 * ((overshoot - 16.0) / cap).min(0.25) * 100.0 * 0.01 * (1.0 - progress);
            }
        }
        // MUTATION (gen 38): residual-efficiency term — compare the density
        // achieved here (item fills fraction of the bin) against the mean
        // open-bin density. Placing into a bin where this item yields a
        // HIGH fill fraction preserves large residuals elsewhere for big
        // items; reward high fill, penalize low fill when alternatives exist.
        let fill_frac = item_size as f64 / cap;
        if fitting_bins_count > 1 && progress < 0.9 {
            let mean_fill = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
            let density_gain = fill_frac - mean_fill;
            if density_gain > 0.0 {
                score -= 5.5 * density_gain * (1.0 - progress);
            } else if dead_ratio > 0.45 {
                score += 4.0 * (-density_gain) * dead_ratio * (1.0 - progress);
            }
        }
        // MUTATION (gen 38): pairability check — a leftover residual is only
        // valuable if the next item is plausibly small enough to use it.
        // When post_residual is large but next_item is much larger (wasting
        // most of the gap), discount the leftover-space reward proportionally.
        if post_residual > 0 && next_item_size > post_residual {
            let unusable = (next_item_size - post_residual) as f64 / cap;
            if unusable > 0.1 {
                score += 9.0 * (unusable - 0.1).min(0.3) * (0.6 + 0.4 * (1.0 - progress));
            }
        }
    } else {
