        let dead_frac = post_residual as f64 / cap;
        if dead_frac > 0.3 {
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            score += 26.0 * (dead_frac - 0.3) * (0.6 + 0.8 * scarcity) * (0.4 + 0.6 * (1.0 - progress));
        }
