        // mid-size tail (8..=16) still risks stranding.
        if next_item_size > 0 && post_residual > next_item_size {
            let after_next = (post_residual - next_item_size) as f64;
            if after_next > 8.0 && after_next <= 16.0 && progress < 0.85 {
                let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
                score -= (4.0 + 3.0 * scarcity) * (1.0 - (after_next - 8.0) / 8.0) * (1.0 - progress);
            }
        }
        // Overshoot penalty when fitting options are plentiful.
        if post_residual > 0 && next_item_size > 0 && fitting_bins_count > 3 {
            let overshoot = post_residual.saturating_sub(next_item_size) as f64;
            if overshoot > 16.0 {
                score += 1.6 * ((overshoot - 16.0) / cap).min(0.25) * 100.0 * 0.01 * (1.0 - progress);
            }
        }
        // MUTATION: perfect-fill anticipation — when post_residual equals a
        // common small size band (<= 12) and next item could exactly close
        // some other bin, mildly prefer this bin to keep residuals uniform.
        if post_residual > 0 && post_residual <= 12 && next_item_size > 0 && next_item_size > post_residual && fitting_bins_count > 2 {
            score += 5.0 * (1.0 - post_residual as f64 / 12.0) * (1.0 - progress);
        }
    } else {
