    if post_residual > 0 {
        if post_residual <= 4 {
            score -= 280.0 + 2.5 * (4 - post_residual) as f64;
        } else if post_residual <= 10 {
            score -= 70.0 + 3.4 * (10 - post_residual) as f64;
        } else if post_residual <= 22 {
            score -= 14.0 + 1.5 * (22 - post_residual) as f64;
        } else if post_residual <= 34 {
            score -= 5.0 + 0.7 * (34 - post_residual) as f64;
        } else if post_residual <= 48 {
            score -= 1.2 + 0.22 * (48 - post_residual) as f64;
        } else {
            score -= 1.2 - 0.014 * (post_residual as f64 - 48.0);
        }
    }

    // Progress-scaled tightening late in the stream.
    let w = 0.35 + 0.65 * progress * progress;
    score *= w;

    // Lookahead coupling with next item.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if next_item_size < post_residual {
            let two_step_waste = (post_residual - next_item_size) as f64;
            if two_step_waste <= 8.0 {
                score -= 120.0 - 2.2 * two_step_waste;
            } else {
                score -= 80.0 - 0.5 * two_step_waste;
            }
            if two_step_waste <= 3.0 {
                score -= 40.0;
            }
        } else {
            let miss = (next_item_size - post_residual) as f64;
            score += 0.95 * miss;
            if miss > 28.0 {
                score += 0.45 * (miss - 28.0);
            }
        }
    }

    // Two-step lookahead: residual that can absorb next item plus a small tail.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after2 = post_residual - next_item_size;
        if after2 > 0 && after2 <= 8 {
            score -= (30.0 - 1.2 * after2 as f64) * (0.5 + 0.5 * (1.0 - progress));
        }
        // Chainable residuals absorb repeated small items.
        if after2 > 0 {
            let reps = after2 / next_item_size.max(1);
            if reps >= 2 {
                score -= 3.0 * (reps as f64).min(4.0) * (1.0 - progress);
            }
        }
        // Scarcity boost when few bins can host the next item here.
        let slack = after2 as f64;
        let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
        score -= (30.0 + 24.0 * scarcity) * (1.0 - slack / cap) * (0.6 + 0.4 * (1.0 - progress));
    }

    // Stranded residual: too small for the next item, weighted by scarcity.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && bin_residual < bin_capacity {
        let stranded = (next_item_size - post_residual) as f64;
        if stranded <= 10.0 {
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            score += (8.0 + 1.1 * (10.0 - stranded)) * scarcity * (0.4 + 0.6 * (1.0 - progress));
        }
        // Penalize tiny dead-zone residuals unusable by the next item.
        if post_residual < 6 {
            score += 6.0 * (1.0 - progress);
        }
    }

    // Dead-space dominance penalty when tight fits exist elsewhere.
    if bin_residual < bin_capacity {
        let dead_ratio = (bin_residual - item_size) as f64 / cap;
        if dead_ratio > 0.45 && fitting_bins_count > 1 {
            score += 10.0 * (dead_ratio - 0.45) * (1.0 - progress);
        }
        // Harmony: prefer leaving a post_residual close to the mean residual.
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 1 {
            let harmony = (post_residual as f64 - mean_residual).abs() / cap;
            if harmony < 0.08 {
                score -= 8.0 * (1.0 - harmony / 0.08) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
    }

    // NEW-BIN CANDIDATE branch.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap) * open_bins_count as f64;
        let huge_item = item_size as f64 > 0.7 * cap;
        let remaining = if total_items > step_index { total_items - step_index } else { 1 };
        let remaining_frac = remaining as f64 / total_items.max(1) as f64;
        let fresh_post = cap - item_size as f64;
        let fresh_is_exact = fresh_post <= 4.0;

        if fragmentation > 0.55 || (huge_item && open_bins_count > 4) {
            score -= 60.0 + 46.0 * remaining_frac;
        } else if fresh_is_exact {
            score -= 130.0 + 60.0 * remaining_frac;
        } else {
            score += 420.0 - 80.0 * remaining_frac;
            if fitting_bins_count <= 3 && open_bins_count > 2 {
                score -= 30.0 + 18.0 * remaining_frac;
            }
        }

        let fresh_match = (fresh_post - mean_residual).abs() / cap;
        if fresh_match < 0.05 {
            score -= 70.0 * (1.0 - fresh_match / 0.05);
        }
        if remaining_frac < 0.05 && fresh_post > 0.0 && !fresh_is_exact {
            score += 150.0 * (fresh_post / cap);
        }
        if fresh_post > 0.0 && fresh_post <= 22.0 && !fresh_is_exact {
            score -= 24.0 * (1.0 - fresh_post / 22.0);
        }
        if fresh_post > 0.0 && fresh_match < 0.12 && fragmentation < 0.55 {
            score -= 28.0 * (1.0 - fresh_match / 0.12);
        }
        if next_item_size > 0 && fresh_post > 0.0 {
            let fresh_exact_next = (fresh_post as u32) == next_item_size;
            let open_can_next = mean_residual >= next_item_size as f64;
            if fresh_exact_next && !open_can_next && fitting_bins_count <= 2 {
                score -= 50.0 * (1.0 - progress);
            }
            if (fresh_post as u32) < next_item_size && mean_residual > next_item_size as f64 {
                score += 20.0 * (1.0 - progress);
            }
            // Fresh-bin chain quality: residual hosting next item plus small tail.
            if fresh_post > next_item_size as f64 {
                let after_next = fresh_post - next_item_size as f64;
                if after_next > 0.0 && after_next <= 8.0 && fragmentation < 0.5 {
                    score -= 18.0 * (1.0 - after_next / 8.0) * (0.4 + 0.6 * (1.0 - progress));
                }
            }
        }
        // Avoid stranding large fresh residuals mid-stream when open bins are tight.
        if fresh_post > 0.5 * cap && mean_residual < 0.2 * cap && remaining_frac > 0.3 && open_bins_count > 3 {
            score += 22.0 * (fresh_post / cap - 0.5) * 2.0 * (1.0 - progress);
        }
        // Only one open bin fits and it would strand a tiny residual — prefer fresh.
        if fitting_bins_count == 1 && fresh_post > 0.0 && next_item_size > 0 {
            let stranded_here = bin_capacity.saturating_sub(item_size);
            if stranded_here > 0 && stranded_here < next_item_size && stranded_here <= 8 {
                score -= 30.0 * (1.0 - progress);
            }
        }
    }

    // Mild preference for bins whose residual is close to mean residual.
    if bin_residual < bin_capacity && post_residual > 0 {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.04 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
