        }
        // Avoid stranding large fresh residuals mid-stream when the
        // mean open residual is small — prefer consolidating into existing
        // bins instead of creating another wide-open bin.
        if fresh_post > 0.5 * cap && mean_residual < 0.2 * cap && remaining_frac > 0.3 && open_bins_count > 3 {
