        // prefer new bins whose fresh residual is tiny (near-perfect fill),
        // with a smooth gradient rather than a hard cutoff.
        if remaining_frac < 0.08 && fresh_post > 4.0 {
            let tightness = (fresh_post / cap).min(1.0);
            score += 90.0 * (1.0 - tightness) * (1.0 - remaining_frac / 0.08);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
