        if post_residual > 0 && post_residual % 10 == 0 && post_residual <= 60 && next_item_size > 0 && next_item_size <= post_residual {
            score -= 4.0 * (1.0 - progress) * (1.0 - post_residual as f64 / 120.0);
        }
        // MUTATION: prefer bins whose current residual is a near-multiple of
        // the item, so repeated placements chain cleanly toward zero waste.
        if item_size > 0 && bin_residual >= item_size && bin_residual % item_size <= 2 {
