        // open slack already exceeds the expected need of remaining items.
        if remaining_frac > 0.15 && !fresh_is_exact && fresh_post > 0.35 * cap {
            let expected_need = remaining as f64 * (cap * 0.45);
            if open_capacity > expected_need {
                score += 22.0 * ((open_capacity - expected_need) / expected_need).min(1.0) * (1.0 - progress);
            }
        }
        // MUTATION: fresh-bin scarcity gate — when almost no open bin fits
        // this item, opening a fresh bin is nearly mandatory; drop the
        // penalty so the new-bin branch can win the comparison.
        if fitting_bins_count == 0 && fresh_post > 0.0 {
            score -= 55.0 * (1.0 - fresh_post / cap) * (0.4 + 0.6 * (1.0 - progress));
        }
        // MUTATION: fresh-bin mean-harmony — a fresh residual close to the
        // mean open residual keeps future items interchangeable across bins;
        // reward it beyond the existing fresh_match band.
        if fresh_post > 0.0 && mean_residual > 0.0 && open_bins_count > 2 && fresh_match < 0.25 {
            score -= 14.0 * (1.0 - fresh_match / 0.25) * (0.5 + 0.5 * (1.0 - progress));
