            score += 2.2 * (dead as f64 / cap) * scarcity * comp_slack * (1.0 - progress);
        }
        // MUTATION (gen 42): residual-magnitude tiebreaker — among bins with
        // similar dead ratios, prefer the one whose leftover residual is
        // closest to the mean residual, consolidating usable space.
        if fitting_bins_count > 2 && post_residual > 0 && mean_residual > 0.0 {
            let dev = ((post_residual as f64 - mean_residual).abs() / cap).min(0.4);
            score += 5.0 * dev * (1.0 - progress);
        }
        // MUTATION: exact-fit ladder — when post_residual equals a plausible
        // future item size band boundary (divisible by 10), reward keeping
        // the residual on a "round" value that common streams can reuse.
        if post_residual > 0 && post_residual % 10 == 0 && post_residual <= 60 && next_item_size > 0 && next_item_size <= post_residual {
            score -= 4.0 * (1.0 - progress) * (1.0 - post_residual as f64 / 120.0);
        }
        // MUTATION (gen 43): open-bin scarcity funnel — when the aggregate
        // open-bin space is barely enough for the remaining items, protect
        // bins whose residual can still host a future item by penalizing
        // placements that would strand that residual below next_item_size.
        if next_item_size > 0 && post_residual > 0 && (post_residual as f64) < next_item_size as f64 {
            let agg = mean_residual * open_bins_count as f64;
            let agg_frac = (agg / (2.0 * cap)).min(1.0);
            let stranded_gap = (next_item_size - post_residual) as f64;
            if stranded_gap <= 6.0 && agg_frac > 0.5 {
                score += 9.0 * (1.0 - stranded_gap / 6.0) * agg_frac * (1.0 - progress);
            }
        }
        // MUTATION (gen 43): near-exact residual preservation — when this
        // placement leaves a residual within 2 of the next item's size, give
        // a graded bonus so near-perfect two-step chains win over looser fits.
        if next_item_size > 0 && post_residual > next_item_size {
            let tail_gap = (post_residual - next_item_size) as f64;
            if tail_gap >= 1.0 && tail_gap <= 2.0 {
                score -= 22.0 * (1.0 - tail_gap / 2.0) * (0.6 + 0.4 * (1.0 - progress));
            }
        }
    } else {
        // NEW-BIN CANDIDATE branch.
        let fragmentation = (mean_residual / cap) * open_bins_count as f64;
        let huge_item = item_size as f64 > 0.7 * cap;
        let remaining = if total_items > step_index { total_items - step_index } else { 1 };
        let remaining_frac = remaining as f64 / total_items.max(1) as f64;
        let fresh_post = cap - item_size as f64;
        let fresh_is_exact = fresh_post <= 4.0 && fresh_post >= 0.0;

        if fragmentation > 0.55 || (huge_item && open_bins_count > 4) {
            score -= 66.0 + 46.0 * remaining_frac;
        } else if fresh_is_exact {
            score -= 134.0 + 66.0 * remaining_frac;
        } else {
            score += 400.0 - 82.0 * remaining_frac;
            if fitting_bins_count <= 3 && open_bins_count > 2 {
                score -= 30.0 + 18.0 * remaining_frac;
            }
        }

        let fresh_match = (fresh_post - mean_residual).abs() / cap;
