            score += 20.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        // MUTATION (gen 43): fresh-bin waste guard tightened — when the fresh
        // residual would be unusable by the next item AND open bins hold
        // meaningful aggregate space, raise resistance proportionally to the
        // stranded fraction so the oracle avoids spawning dead bins.
        if next_item_size > 0 && fresh_post > 0.0 && (fresh_post as u32) < next_item_size {
            let agg = mean_residual * open_bins_count as f64;
            if agg > 1.0 * cap {
                let stranded_frac = ((next_item_size - fresh_post as u32) as f64) / next_item_size.max(1) as f64;
