            }
        }
        // MUTATION (gen 43): fresh-bin two-step chain bonus — reward opening
        // a bin whose residual exactly chains next_item then a small tail,
        // but only when fragmentation pressure is moderate.
        if next_item_size > 0 && fresh_post > next_item_size as f64 && fragmentation < 0.45 {
            let after_next = fresh_post - next_item_size as f64;
            if after_next >= 1.0 && after_next <= 3.0 {
                score -= 12.0 * (1.0 - (after_next - 1.0) / 2.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
