            let est_need = (remaining as f64) * (item_size as f64) * 0.35;
            if open_space > est_need {
                score += 55.0 * (1.0 - remaining_frac / 0.15);
            }
        }
        // MUTATION (gen 46): early-stream fresh-bin damping — opening bins
        // very early is cheap, but only when fragmentation is genuinely low;
        // require a slightly higher fragmentation bar before the discount.
        if remaining_frac > 0.6 && fragmentation < 0.25 && fresh_post >= 0.5 * cap {
