}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post_residual as f64;

    // Layered dead-space rewards: strongly prefer small post_residual.
    if post_residual == 0 {
        score -= 900.0;
        if !is_new_bin {
            score -= 40.0 * (1.0 - bin_residual as f64 / cap);
        }
    } else if post_residual <= 4 {
        score -= 240.0 + 4.0 * (4 - post_residual) as f64;
    } else if post_residual <= 10 {
        score -= 60.0 + 3.5 * (10 - post_residual) as f64;
    } else if post_residual <= 22 {
        score -= 13.0 + 1.4 * (22 - post_residual) as f64;
    } else if post_residual <= 40 {
        score -= 4.5 + 0.6 * (40 - post_residual) as f64;
    } else {
        score -= 1.0 - 0.012 * (post_residual as f64 - 40.0);
    }

    // Tight-fit reward.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness;

    // Lookahead coupling with the next item.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 850.0 / fitting_bins_count.max(1) as f64;
        } else if next_item_size < post_residual {
            let two_step_waste = (post_residual - next_item_size) as f64;
            if two_step_waste <= 8.0 {
                score -= 120.0 - 2.2 * two_step_waste;
            } else {
                score -= 65.0 - 0.5 * two_step_waste;
            }
            if two_step_waste <= 3.0 {
                score -= 40.0;
            }
            // Chunkable residuals absorb repeated small items.
            let reps = post_residual / next_item_size;
            if reps >= 2 {
                score -= 4.0 * (reps as f64).min(4.0) * (1.0 - progress);
            }
        } else {
            let miss = (next_item_size - post_residual) as f64;
            let scarcity = 1.0 / fitting_bins_count.max(1) as f64;
            if miss <= 10.0 {
                score += (9.0 + 1.2 * (10.0 - miss)) * scarcity * (0.4 + 0.6 * (1.0 - progress));
            } else {
                score += 0.9 * miss + 0.5 * (miss - 26.0).max(0.0);
            }
        }
    }

    // Open-bin pressure: discourage spreading when many bins are open.
    score += 0.3 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    }

    // Mild preference for bins below mean residual (balance fragmentation).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Dead-ratio gradient with scarcity weighting.
    if !is_new_bin && fitting_bins_count > 1 && post_residual > 0 {
        let dead = (bin_residual - item_size) as f64;
        let dead_ratio = dead / cap;
        if dead_ratio > 0.35 && fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
            let tight = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score += 7.0 * (dead_ratio - 0.35) * tight * (1.0 - progress);
        }
        // Stranded residual too small for next item.
        if next_item_size > 0 && post_residual < next_item_size {
            let scarcity = 1.0 / fitting_bins_count.max(1) as f64;
            score += 6.0 * scarcity * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    if is_new_bin {
        // NEW-BIN CANDIDATE branch.
        let fragmentation = (mean_residual / cap) * open_bins_count as f64;
        let remaining = if total_items > step_index { total_items - step_index } else { 1 };
        let remaining_frac = remaining as f64 / total_items.max(1) as f64;
        let fresh_post = cap - item_size as f64;
        let fresh_is_exact = fresh_post <= 4.0;

        if fragmentation > 0.55 || (item_size as f64 > 0.7 * cap && open_bins_count > 4) {
            score -= 60.0 + 40.0 * remaining_frac;
        } else if fresh_is_exact {
            score -= 130.0 + 60.0 * remaining_frac;
        } else {
            score += 380.0 - 80.0 * remaining_frac;
            if fitting_bins_count <= 3 && open_bins_count > 2 {
                score -= 28.0 + 16.0 * remaining_frac;
            }
        }

        // Fresh-bin reusable-tail bonus.
        if next_item_size > 0 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 2 && fragmentation < 0.5 {
                score -= 7.0 * ((reps as f64).min(4.0) - 1.0) * (0.4 + 0.6 * (1.0 - progress));
                if rem <= 3 {
                    score -= 5.0 * (1.0 - progress);
                }
            }
        }

        // Refuse fresh bins late in the stream when open bins hold enough space.
        if remaining_frac < 0.15 && fresh_post > 0.3 * cap {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = remaining as f64 * item_size as f64 * 0.35;
            if open_space > est_need {
                score += 55.0 * (1.0 - remaining_frac / 0.15);
            }
        }

        // Penalize fresh bin whose leftover can't host next item while open bins can.
        if next_item_size > 0 && (fresh_post as u32) < next_item_size && mean_residual > next_item_size as f64 {
            score += 20.0 * (1.0 - progress);
        }

        // Late-stream consolidation.
        score += 25.0 * progress;
        if remaining_frac < 0.05 && fresh_post > 0.0 && !fresh_is_exact {
            score += 150.0 * (fresh_post / cap);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
