        // can host the next item with room left for a further mid-size item are
        // preferred over near-exact single-use fits when many bins compete.
        if next_item_size > 0 && post_residual > next_item_size && fitting_bins_count > 3 {
            let after = post_residual - next_item_size;
            if after >= 8 && after <= 28 {
                score -= 5.5 * (1.0 - (after as f64 - 8.0).abs() / 10.0).max(0.0) * (1.0 - progress);
            }
        }
