                score += 55.0 * (1.0 - remaining_frac / 0.15);
            }
        }
        // MUTATION (gen 46): extend the fresh-bin refusal window — mid-stream
        // fresh bins with large tails are blocked when aggregate open slack
        // comfortably covers the projected remaining demand.
        if remaining_frac >= 0.15 && remaining_frac < 0.45 && fresh_post > 0.4 * cap && fragmentation < 0.5 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.28;
            if open_space > est_need * 1.6 {
