            let surplus = post_residual as f64 - mean_residual;
            if surplus > 0.0 {
                let scarcity = 1.0 / (fitting_bins_count as f64);
                score -= 2.6 * (surplus / cap).min(0.3) * scarcity * (0.5 + 0.5 * (1.0 - progress));
