    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Perfect fill is always best.
    if post_residual == 0 {
        score -= 1000.0;
        if bin_residual < bin_capacity {
            score -= 40.0 * (1.0 - bin_residual as f64 / cap) * (1.0 - progress);
        }
    }

    // Layered near-perfect fill rewards (borrowed ladder, tightened).
    if post_residual > 0 {
        if post_residual <= 4 {
            score -= 280.0 + 2.0 * (4 - post_residual) as f64;
        } else if post_residual <= 10 {
            score -= 60.0 + 3.2 * (10 - post_residual) as f64;
        } else if post_residual <= 22 {
            score -= 12.0 + 1.4 * (22 - post_residual) as f64;
        } else if post_residual <= 40 {
            score -= 4.0 + 0.5 * (40 - post_residual) as f64;
        } else {
            score -= 1.0 - 0.01 * (post_residual as f64 - 40.0);
        }
    }

    // Lookahead coupling with next item.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 850.0;
            if fitting_bins_count <= 3 {
                score -= 30.0 / fitting_bins_count.max(1) as f64 * (0.5 + 0.5 * (1.0 - progress));
            }
        } else if next_item_size < post_residual {
            let two_step_waste = (post_residual - next_item_size) as f64;
            if two_step_waste <= 10.0 {
                score -= 110.0 - 2.0 * two_step_waste;
            } else {
                score -= 90.0 - 0.3 * two_step_waste;
            }
            if two_step_waste <= 3.0 {
                score -= 45.0 * (1.0 - progress);
            }
        } else {
            let miss = (next_item_size - post_residual) as f64;
            score += 0.9 * miss;
            if miss > 30.0 {
                score += 0.4 * (miss - 30.0);
            }
            // Stranded residual weighted by scarcity.
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            if miss <= 10.0 {
                score += (8.0 + 1.0 * (10.0 - miss)) * scarcity * (0.4 + 0.6 * (1.0 - progress));
            }
        }
    }

    // Two-step lookahead: small tail after next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after2 = post_residual - next_item_size;
        if after2 > 0 && after2 <= 6 {
