        // MUTATION (gen 44, tuned gen 46): residual-magnitude tiebreaker toward mean,
        // scaled by how many bins can host the next item (diverting poor fits away).
        if fitting_bins_count > 2 && post_residual > 0 && mean_residual > 0.0 {
            let dev = ((post_residual as f64 - mean_residual).abs() / cap).min(0.4);
            let divert = 1.0 + 0.5 / (fitting_bins_count.max(1) as f64);
            score += 5.0 * dev * divert * (1.0 - progress);
        }
        // MUTATION (gen 46): keep residuals that remain exactly reusable by the
