        }
        // Fresh-bin residual-magnitude guard.
        if fresh_post > 0.35 * cap && remaining_frac > 0.2 && mean_residual * open_bins_count as f64 > 4.0 * cap && fragmentation < 0.45 {
            score += 20.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        // MUTATION (gen 45, tuned gen 46): refuse fresh bins late in the stream when
        // open bins still hold enough aggregate space for the remaining demand;
        // estimate now includes next-item lookahead for sharper need forecasting.
        if remaining_frac < 0.18 && fresh_post > 0.3 * cap {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64).max(next_item_size as f64) * 0.35;
            if open_space > est_need {
