        // Scarcity-weighted perfect-fit extension.
        if next_item_size > 0 && post_residual == next_item_size && fitting_bins_count <= 3 {
            score -= 30.0 / fitting_bins_count.max(1) as f64 * (0.5 + 0.5 * (1.0 - progress));
        }
        // MUTATION (gen 46): near-exact fit bonus — leaving a residual within 2 of
        // the next item is almost as good as an exact match when bins are scarce.
        if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 2 && fitting_bins_count <= 4 {
            score -= (14.0 - 4.0 * (post_residual - next_item_size) as f64) * (0.5 + 0.5 * (1.0 - progress));
        }
