        }
        // Fresh-bin residual-magnitude guard.
        if fresh_post > 0.35 * cap && remaining_frac > 0.2 && mean_residual * open_bins_count as f64 > 4.0 * cap && fragmentation < 0.45 {
            score += 20.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        // MUTATION (gen 45): refuse fresh bins late in the stream when open
        // bins still hold enough aggregate space for the remaining demand.
        if remaining_frac < 0.15 && fresh_post > 0.3 * cap {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.35;
            if open_space > est_need {
                score += 55.0 * (1.0 - remaining_frac / 0.15);
            }
        }
        // MUTATION (gen 46): fresh-bin residual-band alignment — opening a new
        // bin is more attractive when its leftover lands in the reusable
        // mid-band (12..=0.35*cap), since such residuals stay consumable by
        // typical mid-size items and reduce future dead space.
        if fresh_post >= 12.0 && fresh_post <= 0.35 * cap && remaining_frac > 0.1 {
            let band_center = 0.20 * cap;
            let band_align = 1.0 - ((fresh_post - band_center).abs() / band_center).min(1.0);
            score -= 14.0 * band_align * (0.4 + 0.6 * (1.0 - progress));
        }
        // MUTATION (gen 46): fresh-bin aggregate-slack veto refinement — when
        // open bins hold ample slack relative to the next item too, opening a
        // fresh bin wastes that slack; tighten the refusal.
        if next_item_size > 0 && remaining_frac < 0.3 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (next_item_size as f64) * 0.3;
            if open_space > est_need && fresh_post > 0.5 * cap {
                score += 12.0 * (1.0 - remaining_frac / 0.3);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
