            let scarcity = 1.0 / (fitting_bins_count as f64);
            let comp_slack = (mean_residual / cap).min(1.0);
            score += 7.5 * (dead_ratio - 0.06) * scarcity * comp_slack * (0.5 + 0.5 * (1.0 - progress));
            score += 2.6 * (dead / cap) * scarcity * comp_slack * (1.0 - progress);
        }
        // MUTATION (gen 44, refined gen 46): residual-magnitude tiebreaker toward mean,
        // with a mid-stream emphasis so variance is squeezed before the endgame.
        if fitting_bins_count > 2 && post_residual > 0 && mean_residual > 0.0 {
            let dev = ((post_residual as f64 - mean_residual).abs() / cap).min(0.4);
            score += 5.5 * dev * (1.0 - progress) * (0.7 + 0.6 * (1.0 - progress));
        }
        // MUTATION (gen 46): consolidation bonus — when this bin's post-fit residual
        // is small enough that another open bin's residual could absorb the same
        // item, prefer the tightest fit harder to drain scattered bins.
