            if reachable < 0.5 {
                score += 18.0 * (0.5 - reachable) * (1.0 - progress);
            }
        }
        // Fresh-bin reusable-tail bonus with small-remainder extension.
        if next_item_size > 0 && fresh_post > 0.0 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 2 && fragmentation < 0.5 {
                score -= 7.0 * ((reps as f64).min(4.0) - 1.0) * (0.4 + 0.6 * (1.0 - progress));
                if rem <= 3 {
                    score -= 5.0 * (1.0 - progress);
                }
            }
        }
        // Fresh-bin residual-magnitude guard.
        if fresh_post > 0.35 * cap && remaining_frac > 0.2 && mean_residual * open_bins_count as f64 > 4.0 * cap && fragmentation < 0.45 {
            score += 20.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        // MUTATION (gen 45, refined gen 46): refuse fresh bins late in the stream
        // when open bins still hold enough aggregate space for the remaining
        // demand; threshold loosened to 0.2 and demand estimate sharpened with
        // the next-item lookahead.
        if remaining_frac < 0.2 && fresh_post > 0.25 * cap {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * ((item_size as f64 + next_item_size as f64) * 0.5) * 0.35;
            if open_space > est_need {
                score += 58.0 * (1.0 - remaining_frac / 0.2);
            }
        }
        // MUTATION (gen 46): fresh-bin divisibility probe — opening a new bin is
        // only worthwhile mid-stream if its residual tiles cleanly by the next
        // item; otherwise push the item into existing fragmentation.
        if next_item_size > 0 && fresh_post > 0.0 && remaining_frac > 0.15 && remaining_frac < 0.7 {
            let rem = (fresh_post as u32) % next_item_size;
            if rem > 0 && rem < next_item_size.min(12) {
                score += 14.0 * (1.0 - rem as f64 / 12.0) * (1.0 - progress);
            }
        }
    }

    score
}

