        // fragmentation with abundant slack means a loose fresh bin becomes
        // long-term dead space; penalize proportionally.
        if fresh_post > 0.35 * cap && remaining_frac > 0.2 && open_capacity > 4.0 * cap && fragmentation < 0.45 {
            score += 20.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
