pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual close to 0 is good.
    score -= (1.0 - post_residual as f64 / cap) * 30.0;

    // Harmonic class of the leftover: leftovers in {0} are perfect,
    // small classes (1..=5) are near-perfect, big classes waste space.
    let cls = post_residual % 25;
    score += match cls {
        0 => -20.0,
        1..=5 => -10.0,
        6..=15 => 5.0,
        _ => 12.0,
    };

    // Integer-division threshold: leftover divisible into common item sizes
    // (e.g. 50, 25, 20, 10) is reusable.
    if post_residual > 0 {
        let mut reusable = 0;
        for d in [10u32, 20, 25, 33, 50] {
            if post_residual >= d { reusable += 1; }
        }
        score -= reusable as f64 * 3.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 + (post_residual - next_item_size) as f64 / cap * 10.0;
        } else {
            // Next item won't fit here; leftover is dead space for the future.
            score += (post_residual as f64) * 0.3;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening new bins when open bins have plenty of room.
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 2.0
            + mean_residual * 0.2;
        // But allow a fresh bin if the item is huge relative to mean residual.
        score -= (item_size as f64 / cap) * 20.0;
        // Early in the stream, opening bins is cheap.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 10.0;
    }

    // Slight preference for fuller bins overall.
    score -= (bin_residual - post_residual) as f64 / cap * 5.0;

    score
}

