pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward: post_residual exactly matches the next item (perfect 2-step chain).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Reward closeness of post_residual to next item size (encourage chain fits).
            let diff = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize proportionally to leftover dead space.
            let dead = post_residual as f64;
            score += 0.5 * dead;
        }

        // Penalize if post_residual is a small unusable sliver (< 10) that no item can use.
        if post_residual < 10 {
            score += 15.0;
        }
    } else {
        // Last item: simply minimize wasted space.
        score += 0.2 * post_residual as f64;
    }

    // Relative to mean residual: bins already much tighter than average get priority
    // (pack into the fullest feasible bin), others penalized.
    let rel = (post_residual as f64) - mean_residual;
    score += 0.3 * rel;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate (empty bin): penalize so we only open when open bins are bad fits.
    if bin_residual == bin_capacity {
        score += 35.0;
        // But if no open bin fits (we are the only candidate), cancel the penalty.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Early in the stream, opening bins is cheaper; late, prefer consolidation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Mild preference to keep number of open bins low: more bins -> slightly favor
    // filling existing ones (implicit via above), but add tiny tie-breaker.
    score -= 0.01 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
