        if next_item_size > 0 && fresh_post > 0.0 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 2 && fragmentation < 0.5 {
                score -= 7.0 * ((reps as f64).min(4.0) - 1.0) * (0.4 + 0.6 * (1.0 - progress));
                if rem <= 3 {
                    score -= 5.0 * (1.0 - progress);
                }
            }
        }
        // Fresh-bin residual-magnitude guard.
        if fresh_post > 0.35 * cap && remaining_frac > 0.2 && mean_residual * open_bins_count as f64 > 4.0 * cap && fragmentation < 0.45 {
            score += 20.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        // Refuse fresh bins late in the stream when open bins still hold enough
        // aggregate space for the remaining demand.
        if remaining_frac < 0.15 && fresh_post > 0.3 * cap {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.35;
            if open_space > est_need {
                score += 55.0 * (1.0 - remaining_frac / 0.15);
            }
        }
        // MUTATION (gen 48): fresh-bin waste floor — never open a new bin whose
        // leftover will exceed what the aggregate open slack already offers,
        // unless the fresh leftover is small or the item is huge.
        if fresh_post > 0.25 * cap && !huge_item && open_bins_count > 1 {
            let open_space = mean_residual * open_bins_count as f64;
            if open_space > fresh_post * 1.4 {
                score += 14.0 * (fresh_post / cap - 0.25) * (0.6 + 0.4 * (1.0 - progress));
            }
        }
        // MUTATION (gen 48): mid-stream fresh-bin opening is only worthwhile if
        // the fresh leftover can host the next item or is near-exact; otherwise
        // prefer spreading load across open bins.
        if remaining_frac > 0.15 && remaining_frac < 0.6 && fresh_post > 0.3 * cap
            && next_item_size > 0 && (fresh_post as u32) < next_item_size && fitting_bins_count >= 1 {
            score += 10.0 * (1.0 - progress);
        }
    }

    score
}

