        let per_item_need = cap * 0.5;
        if remaining_frac > 0.25 && open_capacity < per_item_need * open_bins_count.max(1) as f64 * 0.5 {
            score -= 18.0 * (1.0 - progress);
        }
        if next_item_size > 0 && fresh_post > next_item_size as f64 {
            let after_next = fresh_post - next_item_size as f64;
            if after_next > 0.0 && after_next <= 8.0 && fragmentation < 0.5 {
                score -= 20.0 * (1.0 - after_next / 8.0) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        if next_item_size > 0 && fresh_post > 0.0 && (fresh_post as u32) < next_item_size {
            let slack_total = mean_residual * open_bins_count as f64;
            if slack_total > 2.0 * cap {
                score += 26.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && (fresh_post as u32) == next_item_size && fragmentation > 0.3 {
            score -= 44.0 * (0.5 + 0.5 * (1.0 - progress));
        }
        if fresh_post > 0.5 * cap && mean_residual < 0.2 * cap && remaining_frac > 0.3 && open_bins_count > 3 {
            score += 24.0 * (fresh_post / cap - 0.5) * 2.0 * (1.0 - progress);
        }
        if fitting_bins_count <= 1 && fresh_post > 0.45 * cap && next_item_size > 0 {
            let reachable = (next_item_size as f64 / fresh_post).min(1.0);
            if reachable < 0.5 {
                score += 18.0 * (0.5 - reachable) * (1.0 - progress);
            }
        }
        // Fresh-bin reusable-tail bonus with small-remainder extension.
        if next_item_size > 0 && fresh_post > 0.0 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 2 && fragmentation < 0.5 {
                score -= 7.0 * ((reps as f64).min(4.0) - 1.0) * (0.4 + 0.6 * (1.0 - progress));
                if rem <= 3 {
                    score -= 5.0 * (1.0 - progress);
                }
            }
        }
        // Fresh-bin residual-magnitude guard.
        if fresh_post > 0.35 * cap && remaining_frac > 0.2 && mean_residual * open_bins_count as f64 > 4.0 * cap && fragmentation < 0.45 {
            score += 20.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        // Refuse fresh bins late in the stream when open bins still hold
        // enough aggregate space for the remaining demand.
        if remaining_frac < 0.15 && fresh_post > 0.3 * cap {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.35;
            if open_space > est_need {
                score += 55.0 * (1.0 - remaining_frac / 0.15);
            }
        }
        // Gen 49: widen the late-stream refusal band slightly when open bins
        // are exceptionally roomy, catching mid-stream waste earlier.
        if remaining_frac < 0.3 && fresh_post > 0.5 * cap && open_bins_count > 5 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.5;
            if open_space > 2.0 * est_need {
                score += 24.0 * (1.0 - remaining_frac / 0.3);
            }
        }
        // Gen 49: allow fresh bins early when the item is huge and no open bin
        // is even close — avoids fragmenting a large item into a tight home
        // that strands a big dead zone.
        if huge_item && fragmentation < 0.4 && fresh_post > 0.0 && fresh_post < 0.25 * cap && remaining_frac > 0.4 {
            score -= 20.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: shrink score as post_residual approaches 0.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Strong bonus when the item fills the bin completely.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: residual that exactly accommodates the next item is valuable.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 14.0;
        } else if post_residual > next_item_size {
            // Residual large enough for the next item: mildly good.
            score -= 4.0 * (post_residual as f64 / (next_item_size as f64 + 1.0)).min(1.0);
        } else {
            // Dead space too small for the next item: penalize proportionally.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.12 * waste;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Penalize spreading across many open bins when mean residual is already high.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if (bin_residual as f64) < mean_residual {
        score += 3.0 * (1.0 - progress) * (mean_residual - bin_residual as f64) / bin_capacity as f64;
    } else {
        score -= 1.5 * progress * (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    }

    // New-bin candidate (empty bin): only attractive when no open bin fits well.
    if bin_residual == bin_capacity && bin_capacity > 0 {
        let poor_fit = (post_residual as f64) > 0.5 * bin_capacity as f64;
        if fitting_bins_count == 0 || poor_fit {
            score -= 6.0;
        } else {
            // Discourage opening new bins when existing ones suffice.
            score += 8.0 + 0.5 * open_bins_count as f64;
        }
    }

    // Mild preference for fuller bins overall.
    score -= 2.0 * (item_size as f64 / bin_capacity as f64);

    score
}

