pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let size_frac = item_size as f64 / cap;

    // Base: quadratic penalty on post residual (waste), scaled by stream progress
    let mut score = pr * (1.0 + 2.0 * progress * norm_pr);

    // Smooth interaction: large items late in stream favor tight fits
    let tightness = 1.0 - size_frac;
    score += 30.0 * progress * tightness * norm_pr;

    // Penalize bins whose residual deviates from mean residual (fragmentation)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 12.0 * dev * dev * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_pr);
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 8.0 * (1.0 - pr / (pr + nxt)) * (1.0 - progress);
        } else {
            score += 6.0 * (nxt - pr) / cap * progress;
        }
    }

    // Mild penalty for too many open bins
    score += 0.5 * open_bins_count as f64 * norm_pr;

    // New-bin candidate: discourage unless current residuals are all poor
    if bin_residual == bin_capacity {
        let poor_fit = (mean_residual / cap - size_frac).abs();
        score = pr + 20.0 + 40.0 * (1.0 - poor_fit) * progress;
    }

    score
}

