                score -= 7.0 * ((reps as f64).min(4.0) - 1.0) * (0.4 + 0.6 * (1.0 - progress));
                if rem <= 3 {
                    score -= 5.0 * (1.0 - progress);
                }
            }
        }
        // Fresh-bin residual-magnitude guard.
        if fresh_post > 0.35 * cap && remaining_frac > 0.2 && mean_residual * open_bins_count as f64 > 4.0 * cap && fragmentation < 0.45 {
            score += 20.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        // MUTATION (gen 45): refuse fresh bins late in the stream when open
        // bins still hold enough aggregate space for the remaining demand.
        if remaining_frac < 0.15 && fresh_post > 0.3 * cap {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.35;
            if open_space > est_need {
                score += 55.0 * (1.0 - remaining_frac / 0.15);
            }
        }
        // MUTATION (gen 49): fresh-bin exact-next alignment — opening a new bin
        // whose residual exactly matches the next item is highly valuable when
        // no open bin can host the next item, even mid-stream.
        if next_item_size > 0 && (fresh_post as u32) == next_item_size && !open_capacity_geq_next(mean_residual, next_item_size) && fragmentation <= 0.55 {
            score -= 38.0 * (0.6 + 0.4 * (1.0 - progress));
        }
    }

    score
}

#[inline]
fn open_capacity_geq_next(mean_residual: f64, next_item_size: u32) -> bool {
    mean_residual >= next_item_size as f64
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which "modular band" does the leftover fall in?
    // Band 0: post_residual == 0 (perfect fit) -> strong reward.
    // Band 1: post_residual in 1..=10 (dead space, nothing fits) -> strong penalty.
    // Band 2: post_residual in 11..=50 (fits small items) -> mild reward.
    // Band 3: post_residual > 50 (still flexible) -> mild penalty (wasted large space).
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0;
    } else if pr <= 10 {
        score += 45.0;
    } else if pr <= 50 {
        score -= 8.0;
    } else {
        score += 5.0;
    }

    // Integer-division harmonic classes: post_residual / 10 as coarse class.
    let class = pr / 10;
    score -= (class % 3) as f64 * 3.0; // reward every third class slightly

    // Lookahead coupling: does the next item fit in the post-residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 15.0; // chain fit is valuable
            // harmonic bonus if next item exactly divides the leftover
            if next_item_size > 0 && pr % next_item_size == 0 {
                score -= 12.0;
            }
        } else {
            score += 18.0; // next item cannot use this bin's leftover
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: opening a fresh bin is only attractive if all open bins
    // would leave very tight dead space. Base new-bin score anchored at high value.
    if bin_residual == bin_capacity {
        score += 70.0;
        // But early in the stream, a fresh bin is cheap insurance.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 40.0 * (1.0 - progress);
    }

    // Mean-residual coupling: when open bins are already loose, avoid loosening
    // further; when they are tight, prefer spreading.
    if mean_residual > 30.0 {
        score += (mean_residual - 30.0) * 0.4;
    }

    // Penalize bins that are already very loose relative to capacity fraction.
    let residual_fraction = bin_residual as f64 / bin_capacity as f64;
    if residual_fraction > 0.8 && bin_residual != bin_capacity {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

