        if next_item_size > 0 && post_residual == next_item_size && fitting_bins_count <= 3 {
            score -= 30.0 / fitting_bins_count.max(1) as f64 * (0.5 + 0.5 * (1.0 - progress));
        }
        // MUTATION (gen 50): early-stream hoarding guard — when few bins can host
        // the item and the residual left behind would be large, mildly prefer
        // spreading into emptier bins to keep future fits flexible.
