        if next_item_size > 0 && fresh_post > 0.0 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 2 && fragmentation < 0.5 {
                score -= 7.0 * ((reps as f64).min(4.0) - 1.0) * (0.4 + 0.6 * (1.0 - progress));
                if rem <= 3 {
                    score -= 5.0 * (1.0 - progress);
                }
            }
        }
        // Fresh-bin residual-magnitude guard.
        if fresh_post > 0.35 * cap && remaining_frac > 0.2 && mean_residual * open_bins_count as f64 > 4.0 * cap && fragmentation < 0.45 {
            score += 20.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        // MUTATION (gen 50, refined): refuse fresh bins late in the stream when
        // open bins hold enough aggregate space for remaining demand — now
        // estimates need from the observed mean item size trend via mean_residual.
        if remaining_frac < 0.15 && fresh_post > 0.3 * cap {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.35;
            if open_space > est_need {
                score += 55.0 * (1.0 - remaining_frac / 0.15);
            }
        }
        // MUTATION (gen 50): mid-stream fresh-bin guard — opening a bin whose
        // fresh residual strands a large unusable gap is penalized when the
        // next item cannot use it and open slack is abundant.
        if remaining_frac >= 0.15 && remaining_frac < 0.5 && next_item_size > 0
            && fresh_post > 0.0 && (fresh_post as u32) < next_item_size
            && mean_residual * open_bins_count as f64 > 1.5 * cap {
            score += 14.0 * (fresh_post / cap) * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to fit the
    // smallest plausible item (1..100 range) are pure waste.
    let dead_threshold: u32 = 10;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 60.0 * (dead_threshold - post_residual) as f64;
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize residuals that cannot fit the lookahead item (creates
    // fragmentation for the next step), unless next item is unknown.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }
    // Reward residuals that exactly or comfortably fit the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with
    // few open bins, opening a new bin is cheaper so prefer tight fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 / (1.0 + progress);
    score += 0.6 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Coupling with mean residual: avoid making this bin an outlier of waste.
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // Mild penalty for using a fresh bin when open bins exist and fit well.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 12.0 + 2.0 * open_bins_count as f64;
    }

    score
}

