            let two_reps = (fresh_post as u32) / (2 * next_item_size.max(1));
            if two_reps >= 1 && fragmentation < 0.4 {
                score -= 14.0 * (1.0 - remaining_frac.min(0.5) / 0.5) * (0.5 + 0.5 * (1.0 - progress));
