            && (fresh_post as u32) + 5 >= next_item_size && remaining_frac > 0.15 {
            score += 16.0 * (1.0 - (next_item_size - fresh_post as u32) as f64 / 5.0) * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 200.0;
    }
    // Near match: next item fits but leaves awkward gap.
    else if next_item_size > 0 && post_residual > next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        // Penalize gaps that are too small to be useful (dead space) but reward moderate usable gaps.
        if gap < 10.0 {
            score += 30.0 + gap;
        } else {
            score -= 10.0 * (1.0 - gap / bin_capacity as f64);
        }
    }
    // Next item cannot fit here: this bin becomes dead after this placement.
    else if next_item_size > 0 && post_residual < next_item_size {
        score += 40.0 + (next_item_size - post_residual) as f64;
    }

    // Penalize bins whose residual is far below the mean (they are nearly full; waste of tight fit).
    score += 0.5 * (mean_residual - bin_residual as f64).abs();

    // Last-chance bonus: only one bin fits; strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: only attractive if item is large relative to capacity or no good fits exist.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        score += 120.0 - 80.0 * tightness;
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 180.0; // fresh bin gives perfect lookahead fit
        }
    }

    // Late in the stream: prefer closing bins tightly to reduce total count.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

