    if bin_residual == bin_capacity {
        score += 10.0;
        // But allow new bins early in the stream to build diversity.
        score -= 8.0 * (1.0 - progress);
    }

    // Small tie-breaker: prefer bins with residual close to mean (balance).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

