            score -= 4.0 * (1.0 - progress) * (1.0 - post_residual as f64 / 120.0);
        }
        // Scarcity-weighted perfect-fit extension.
        if next_item_size > 0 && post_residual == next_item_size && fitting_bins_count <= 3 {
            score -= 30.0 / fitting_bins_count.max(1) as f64 * (0.5 + 0.5 * (1.0 - progress));
        }
        // MUTATION (gen 51): mid-band residual conservation — when this bin's
        // post-residual sits in the awkward 31..60 band and the aggregate open
        // slack is already large, prefer tighter bins; conversely, reward
        // leaving residuals that still exceed the next item with margin.
        if post_residual > 30 && post_residual <= 60 && fitting_bins_count > 2 {
            let open_space = mean_residual * open_bins_count as f64;
            if open_space > 2.5 * cap {
                let band = (post_residual as f64 - 30.0) / 30.0;
