    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: post residual, smoothly weighted by stream progress
    let mut score = pr * (0.6 + 0.8 * progress);

    // Non-linear dead-space penalty: cubic growth of small residuals
    score += cap * (1.0 - norm_pr).powi(3) * (1.0 - progress) * 4.0;
    score += cap * norm_pr.powi(2) * (1.0 - norm_pr) * 2.0;

    // Reward tight fits: quadratic bonus when post_residual is small
    let tight = 1.0 - (norm_pr * 2.0).min(1.0);
    score -= tight * tight * 12.0;

    // Coupling with next item: bonus if next item fits the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (pr as u32) >= next_item_size {
            let slack = (pr - nxt) as f64 / cap;
            score -= 6.0 * (1.0 - slack).max(0.0);
        } else {
            let gap = (nxt - pr) / cap;
            score += 8.0 * gap * gap;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 10.0 + 5.0 * progress;
    } else if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64 - 2.0).min(5.0);
    }

    // Mean residual coupling: prefer bins deviating from the mean (keeps diversity)
    let dev = (pr - mean_residual) / cap;
    score += 3.0 * dev * dev * (1.0 - progress);

    // Mild penalty for spreading across many open bins early
    score += (open_bins_count as f64).ln().max(0.0) * (1.0 - progress) * 1.5;

    // Small new-bin tie-breaker: empty bin slightly penalized unless residuals are bad
    if bin_residual == bin_capacity {
        score += 4.0 + 6.0 * (1.0 - norm_item) * (1.0 - progress);
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Perfect fill is always best.
    if post_residual == 0 {
        score -= 1000.0;
        if bin_residual < bin_capacity {
            score -= 45.0 * (1.0 - bin_residual as f64 / cap) * (1.0 - progress);
        }
    }

    // Layered near-perfect fills.
    if post_residual > 0 && post_residual <= 4 {
        score -= 280.0 + 2.0 * (4 - post_residual) as f64;
    } else if post_residual > 4 && post_residual <= 10 {
        score -= 60.0 + 3.4 * (10 - post_residual) as f64;
    } else if post_residual > 10 && post_residual <= 22 {
        score -= 12.0 + 1.4 * (22 - post_residual) as f64;
    } else if post_residual > 22 && post_residual <= 48 {
        score -= 1.0 + 0.2 * (48 - post_residual) as f64;
    }

    // Progress-scaled tightening.
    let w = 0.35 + 0.65 * progress * progress;
    score *= w;

    // Lookahead coupling with next item.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 880.0;
            if fitting_bins_count <= 3 {
                score -= 30.0 / fitting_bins_count.max(1) as f64 * (0.5 + 0.5 * (1.0 - progress));
            }
        } else if next_item_size < post_residual {
            let two_step_waste = (post_residual - next_item_size) as f64;
            if two_step_waste <= 10.0 {
                score -= 110.0 - 2.0 * two_step_waste;
                if two_step_waste <= 3.0 {
                    score -= 45.0;
                }
            } else {
                score -= 90.0 - 0.3 * two_step_waste;
            }
        } else {
            let miss = (next_item_size - post_residual) as f64;
            score += 0.9 * miss;
            if miss > 30.0 {
                score += 0.4 * (miss - 30.0);
            }
            // Stranded residual weighted by scarcity.
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            if miss <= 10.0 {
                score += (8.0 + 1.0 * (10.0 - miss)) * scarcity * (0.4 + 0.6 * (1.0 - progress));
            }
        }
    }

    // Two-step lookahead: exact next fit leaving small tail.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after2 = post_residual - next_item_size;
        if after2 > 0 && after2 <= 6 {
            score -= 40.0 * (1.0 - after2 as f64 / 7.0) * (0.5 + 0.5 * (1.0 - progress));
        }
        // Chunkable residual absorbs repeated small items.
        if after2 > 6 {
            let reps = post_residual / next_item_size.max(1);
            if reps >= 2 && post_residual <= 40 {
                score -= 3.5 * ((reps as f64).min(4.0) - 1.0) * (1.0 - progress);
            }
        }
    }

    // Dead-space penalty when tight fits exist elsewhere.
    if bin_residual != bin_capacity && fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
        let dead_ratio = (bin_residual - item_size) as f64 / cap;
        if dead_ratio > 0.35 {
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score += 8.0 * (dead_ratio - 0.35) * tightness * (1.0 - progress);
        }
    }

    // Residual-vs-mean harmony tiebreaker.
    if fitting_bins_count > 2 && post_residual > 0 && mean_residual > 0.0 {
        let dev = ((post_residual as f64 - mean_residual).abs() / cap).min(0.4);
        score += 5.0 * dev * (1.0 - progress);
    }

    // NEW-BIN CANDIDATE branch.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap) * open_bins_count as f64;
        let remaining = if total_items > step_index { total_items - step_index } else { 1 };
        let remaining_frac = remaining as f64 / total_items.max(1) as f64;
        let fresh_post = cap - item_size as f64;
        let fresh_is_exact = fresh_post <= 4.0;

        if fragmentation > 0.55 || (item_size as f64 > 0.7 * cap && open_bins_count > 4) {
            score -= 60.0 + 40.0 * remaining_frac;
        } else if fresh_is_exact {
            score -= 130.0 + 60.0 * remaining_frac;
        } else {
            score += 500.0 - 80.0 * remaining_frac;
            if fitting_bins_count <= 3 && open_bins_count > 2 {
                score -= 28.0 + 18.0 * remaining_frac;
            }
        }

        // Refuse fresh bins late when open space suffices.
        if remaining_frac < 0.15 && fresh_post > 0.3 * cap {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.35;
            if open_space > est_need {
                score += 55.0 * (1.0 - remaining_frac / 0.15);
            }
        }
        // Fresh-bin chain bonus.
        if next_item_size > 0 && fresh_post > next_item_size as f64 {
            let chain_post = fresh_post - next_item_size as f64;
            if chain_post <= 4.0 {
                score -= 34.0 * (1.0 - chain_post / 4.0) * (0.5 + 0.5 * (1.0 - progress));
            } else if chain_post <= 10.0 {
                score -= 9.0 * (1.0 - (chain_post - 4.0) / 6.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // Fresh-bin reusable-tail bonus.
        if next_item_size > 0 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 2 && fragmentation < 0.5 {
                score -= 7.0 * ((reps as f64).min(4.0) - 1.0) * (0.4 + 0.6 * (1.0 - progress));
                if rem <= 3 {
                    score -= 5.0 * (1.0 - progress);
                }
            }
        }
    } else {
        // Mild preference for bins whose residual is close to mean residual.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into
    // "usable" residue classes via integer division on capacity fractions.
    let post = post_residual as f64;
    let post_class = (post_residual / (bin_capacity / 4)) as f64; // 0..4 classes
    score -= post_class * 3.0; // reward bins whose leftover falls in a coarser class

    // Dead-space penalty: leftovers too small for typical items are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    if post_residual == 0 {
        score -= 40.0; // perfect fill is excellent
    }

    // Harmonic coupling with next item: can the lookahead item also fit?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // leftover still usable by the next item: strong reward,
            // scaled by how harmonically the two leftovers align (gcd-like mod check)
            let align = (post_residual % next_item_size.max(1)) as f64;
            score -= 20.0 - align * 0.3;
        } else if next_item_size <= bin_residual && next_item_size > post_residual {
            // this placement destroys the only slot for the lookahead item
            score += 15.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current bins
    // are crowded (harmonic fraction of open bins vs items).
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 / (total_items.max(1) as f64).sqrt();
        score += 35.0 - 20.0 * crowding.min(1.0);
        // If mean residual is large, open bins can absorb the item; discourage new bin.
        score += mean_residual * 0.4;
    }

    // Prefer tighter fits: residual before placement close to item size.
    score += (bin_residual as f64 - item_size as f64) * 0.15;

    // Phase of stream: later in the stream, be greedier about filling.
    let phase = step_index as f64 / total_items.max(1) as f64;
    score -= phase * 8.0 * (1.0 - post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;
    let pr = post_residual as f64;

    // Layered dead-space rewards (lower post_residual = better).
    if post_residual == 0 {
        score -= 980.0;
    } else if post_residual <= 4 {
        score -= 250.0 + 4.2 * (4 - post_residual) as f64;
    } else if post_residual <= 10 {
        score -= 64.0 + 3.6 * (10 - post_residual) as f64;
    } else if post_residual <= 22 {
        score -= 13.5 + 1.5 * (22 - post_residual) as f64;
    } else if post_residual <= 32 {
        score -= 5.0 + 0.7 * (32 - post_residual) as f64;
    } else if post_residual <= 48 {
        score -= 1.2 + 0.22 * (48 - post_residual) as f64;
    } else {
        score -= 1.2 - 0.014 * (pr - 48.0);
    }

    // Progress-scaled weighting: tighten late in the stream.
    let w = 0.33 + 0.67 * progress * progress;
    score *= w;

    // Lookahead coupling with the next item.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if next_item_size < post_residual {
            let two_step_waste = (post_residual - next_item_size) as f64;
            if two_step_waste <= 8.0 {
                score -= 135.0 - 2.3 * two_step_waste;
            } else {
                score -= 72.0 - 0.58 * two_step_waste;
            }
            if two_step_waste <= 3.0 {
                score -= 48.0;
            }
        } else {
            let miss = (next_item_size - post_residual) as f64;
            score += 0.95 * miss;
            if miss > 26.0 {
                score += 0.55 * (miss - 26.0);
            }
        }
    }

    // Slack-based scarcity boost when the next item fits here.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
        let boost = 36.0 + 26.0 * scarcity;
        score -= boost * (1.0 - slack / cap) * (0.6 + 0.4 * (1.0 - progress));
        if fitting_bins_count <= 2 {
            score -= 15.0 * (1.0 - slack / cap);
        }
        if slack == 0.0 {
            score -= 20.0 * (1.0 - progress);
        }
    }

    // MUTATION (gen 51): scarcity-weighted perfect-fit extension.
    if next_item_size > 0 && post_residual == next_item_size && fitting_bins_count <= 3 {
        score -= 30.0 / fitting_bins_count.max(1) as f64 * (0.5 + 0.5 * (1.0 - progress));
    }

    // MUTATION (gen 51): dead-ratio gradient with aggregate open slack.
    if bin_residual != bin_capacity {
        let dead = (bin_residual - item_size) as f64;
        let dead_ratio = dead / cap;
        if fitting_bins_count > 1 && dead_ratio > 0.08 && post_residual > 0 {
            let scarcity = 1.0 / (fitting_bins_count as f64);
            let comp_slack = (mean_residual / cap).min(1.0);
            score += 6.5 * (dead_ratio - 0.08) * scarcity * comp_slack * (0.5 + 0.5 * (1.0 - progress));
            score += 2.2 * (dead / cap) * scarcity * comp_slack * (1.0 - progress);
        }
        // Residual-magnitude tiebreaker toward mean.
        if fitting_bins_count > 2 && post_residual > 0 && mean_residual > 0.0 {
            let dev = ((pr - mean_residual).abs() / cap).min(0.4);
            score += 5.0 * dev * (1.0 - progress);
        }
        // Stranded residual: too small for next item, weighted by scarcity.
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            let stranded = (next_item_size - post_residual) as f64;
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            if stranded <= 10.0 {
                score += (8.5 + 1.1 * (10.0 - stranded)) * scarcity * (0.4 + 0.6 * (1.0 - progress));
            } else {
                let proximity = 1.0 - (stranded - 10.0).min(cap) / cap;
                score += 3.2 * proximity * scarcity * (1.0 - progress);
            }
        }
        // Two-step lookahead.
        if next_item_size > 0 && post_residual > next_item_size {
            let after_next = (post_residual - next_item_size) as f64;
            if after_next > 0.0 && after_next <= 12.0 {
                score -= (14.0 - 0.9 * after_next) * (0.5 + 0.5 * (1.0 - progress));
            }
            let chain = post_residual % next_item_size.max(1);
            if chain == 0 {
                score -= 26.0 * (1.0 - progress);
            } else if chain <= 3 {
                score -= 11.0 * (1.0 - progress);
            }
        }
        // Chunkable residuals absorb repeated small items.
        if post_residual > 6 && post_residual <= 30 && next_item_size > 0 && next_item_size <= post_residual {
            let reps = post_residual / next_item_size.max(1);
            if reps >= 2 {
                score -= 3.5 * (reps as f64).min(4.0) * (1.0 - progress);
            }
        }
        // Exact fills of nearly-full bins.
        if post_residual == 0 && bin_residual < bin_capacity {
            score -= 42.0 * (1.0 - bin_residual as f64 / cap) * (1.0 - progress);
        }
        // Mean-harmony bonus.
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 1 {
            let harmony = (pr - mean_residual).abs() / cap;
            if harmony < 0.08 {
                score -= 9.0 * (1.0 - harmony / 0.08) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
    } else {
        // NEW-BIN CANDIDATE branch.
        let fragmentation = (mean_residual / cap) * open_bins_count as f64;
        let huge_item = item_size as f64 > 0.7 * cap;
        let remaining = if total_items > step_index { total_items - step_index } else { 1 };
        let remaining_frac = remaining as f64 / total_items.max(1) as f64;
        let fresh_post = cap - item_size as f64;
        let fresh_is_exact = fresh_post <= 4.0 && fresh_post >= 0.0;

        if fragmentation > 0.55 || (huge_item && open_bins_count > 4) {
            score -= 66.0 + 46.0 * remaining_frac;
        } else if fresh_is_exact {
            score -= 134.0 + 66.0 * remaining_frac;
        } else {
            score += 400.0 - 82.0 * remaining_frac;
            if fitting_bins_count <= 3 && open_bins_count > 2 {
                score -= 30.0 + 18.0 * remaining_frac;
            }
        }

        let fresh_match = (fresh_post - mean_residual).abs() / cap;
        if fresh_match < 0.05 {
            score -= 76.0 * (1.0 - fresh_match / 0.05);
        }
        if remaining_frac < 0.05 && fresh_post > 0.0 && !fresh_is_exact {
            score += 160.0 * (fresh_post / cap);
        }
        if fresh_post > 0.0 && fresh_post <= 22.0 && !fresh_is_exact {
            score -= 26.0 * (1.0 - fresh_post / 22.0);
        }
        if fresh_post > 22.0 && fresh_post <= 40.0 && fragmentation < 0.35 {
