            }
        }
        if next_item_size > 0 && fresh_post > next_item_size as f64 {
            let after_next = fresh_post - next_item_size as f64;
            if after_next > 0.0 && after_next <= 8.0 && fragmentation < 0.5 {
                score -= 20.0 * (1.0 - after_next / 8.0) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        if next_item_size > 0 && fresh_post > 0.0 && (fresh_post as u32) < next_item_size {
            let slack_total = mean_residual * open_bins_count as f64;
            if slack_total > 2.0 * cap {
                score += 26.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && (fresh_post as u32) == next_item_size && fragmentation > 0.3 {
            score -= 44.0 * (0.5 + 0.5 * (1.0 - progress));
        }
        // Fresh-bin reusable-tail bonus.
        if next_item_size > 0 && fresh_post > 0.0 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 2 && fragmentation < 0.5 {
                score -= 7.0 * ((reps as f64).min(4.0) - 1.0) * (0.4 + 0.6 * (1.0 - progress));
                if rem <= 3 {
                    score -= 5.0 * (1.0 - progress);
                }
            }
        }
        // Fresh-bin residual-magnitude guard.
        if fresh_post > 0.35 * cap && remaining_frac > 0.2 && mean_residual * open_bins_count as f64 > 4.0 * cap && fragmentation < 0.45 {
            score += 20.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftovers are almost unusable.
    let pr = post_residual as f64;
    if post_residual > 0 {
        if post_residual <= 10 {
            // worst kind of waste: small gap nothing can use
            score += (11.0 - pr) * 12.0;
        } else if post_residual <= 20 {
            score += (21.0 - pr) * 3.0;
        } else if post_residual <= 35 {
            score += (36.0 - pr) * 0.8;
        } else {
            // large leftovers are valuable; reward them
            score -= (pr - 35.0) * 0.6;
        }
    } else {
        // perfect fit
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        if slack <= 10.0 {
            score -= 25.0;
        } else {
            score -= 8.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 && post_residual <= 10 {
        // residual unusable for the next item too -> extra penalty
        score += 15.0;
    }

    // Open-bin pressure: prefer spreading into existing bins when few are open;
    // discourage hoarding when many bins are open but underused.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (1.0 - progress);
    score += pressure * 0.4;

    // Last-chance bonus: if this is the only bin that can fit the item, use it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: make empty bin unattractive unless the fit is terrible
    // elsewhere; its residual equals capacity so base score is already high,
    // add a mild fixed opening cost scaled by stream progress.
    if bin_residual == bin_capacity {
        score += 30.0 + 20.0 * progress;
    }

    // Mild alignment with mean residual: prefer bins whose residual is near mean
    // (keeps bin set homogeneous), penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
