    // Layered near-perfect fill rewards (borrowed ladder idea, retuned).
    if post_residual > 0 {
        if post_residual <= 4 {
            score -= 300.0 + 3.0 * (4 - post_residual) as f64;
        } else if post_residual <= 10 {
            score -= 60.0 + 3.2 * (10 - post_residual) as f64;
        } else if post_residual <= 22 {
            score -= 12.0 + 1.4 * (22 - post_residual) as f64;
        } else if post_residual <= 36 {
            score -= 4.0 + 0.55 * (36 - post_residual) as f64;
        } else {
            score -= 0.8 - 0.012 * (post_residual as f64 - 36.0);
        }
    }

