            score -= 25.0 * chain_use * chain_use;
        } else {
            // next item cannot fit here; penalize leaving large unusable-looking gaps
            // that are neither 0 nor comfortably large relative to mean residual.
            let gap = post_residual as f64;
            if gap > 0.0 && gap < mean_residual.max(1.0) {
                score += 6.0 * (1.0 - gap / mean_residual.max(1.0));
            }
            // dead space below typical smallest item is bad
            if gap < 10.0 {
                score += 8.0 * (10.0 - gap);
            }
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than the average residual.
    score -= 3.0 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only open a new bin when this item is large
    // and no existing bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Base penalty keeps new bins from being opened casually.
        let mut new_bin_score = 25.0;
        // If the item is huge relative to capacity and post_residual is tiny,
        // opening fresh is attractive.
        if item_size as f64 > 0.8 * bin_capacity as f64 {
            new_bin_score -= 15.0;
        }
        // If next item is large and this bin's post_residual is small,
        // a fresh bin can host the chain.
        if next_item_size > 0 && post_residual < next_item_size && item_size as f64 > 0.6 * bin_capacity as f64 {
            new_bin_score -= 20.0;
        }
        // More open bins -> prefer consolidating, penalize new bins more.
        new_bin_score += 0.5 * open_bins_count as f64;
        // Late in the stream, avoid leaving many open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_score += 10.0 * progress;
        score = new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Layered dead-space rewards (lower post_residual = better).
    if post_residual == 0 {
        score -= 980.0;
    } else if post_residual <= 4 {
        score -= 250.0 + 4.2 * (4 - post_residual) as f64;
    } else if post_residual <= 10 {
        score -= 64.0 + 3.6 * (10 - post_residual) as f64;
    } else if post_residual <= 22 {
        score -= 13.5 + 1.5 * (22 - post_residual) as f64;
    } else if post_residual <= 32 {
        score -= 5.0 + 0.7 * (32 - post_residual) as f64;
    } else if post_residual <= 48 {
        score -= 1.2 + 0.22 * (48 - post_residual) as f64;
    } else {
        score -= 1.2 - 0.014 * (post_residual as f64 - 48.0);
    }

    // Progress-scaled weighting: tighten late in the stream.
    let w = 0.33 + 0.67 * progress * progress;
    score *= w;

    // Lookahead coupling with the next item.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if next_item_size < post_residual {
            let two_step_waste = (post_residual - next_item_size) as f64;
            if two_step_waste <= 8.0 {
                score -= 135.0 - 2.3 * two_step_waste;
            } else {
                score -= 72.0 - 0.58 * two_step_waste;
            }
            if two_step_waste <= 3.0 {
                score -= 48.0;
            }
        } else {
            let miss = (next_item_size - post_residual) as f64;
            score += 0.95 * miss;
            if miss > 26.0 {
                score += 0.55 * (miss - 26.0);
            }
        }
    }

    // Slack-based scarcity boost when the next item fits here.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
        let boost = 36.0 + 26.0 * scarcity;
        score -= boost * (1.0 - slack / cap) * (0.6 + 0.4 * (1.0 - progress));
        if fitting_bins_count <= 2 {
            score -= 15.0 * (1.0 - slack / cap);
        }
        if slack == 0.0 {
            score -= 20.0 * (1.0 - progress);
        }
    }

    if bin_residual != bin_capacity {
        let dead = (bin_residual - item_size) as f64;
        let dead_ratio = dead / cap;
        if dead_ratio > 0.5 && fitting_bins_count > 1 {
            score += 10.5 * (dead_ratio - 0.5) * (1.0 - progress);
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
            && mean_residual > 0.0 && (mean_residual as u32) >= next_item_size {
            score += 12.0;
        }
        if post_residual > 12 && post_residual < 40 && next_item_size > post_residual {
            let orphan = (post_residual as f64 - 12.0) / 28.0;
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            score += 17.0 * orphan * scarcity * (0.5 + 0.5 * (1.0 - progress));
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let chain = post_residual % next_item_size.max(1);
            if chain == 0 {
                score -= 26.0 * (1.0 - progress);
            } else if chain <= 3 {
                score -= 11.0 * (1.0 - progress);
            }
        }
        // Stranded residual: too small for next item, weighted by scarcity.
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            let stranded = (next_item_size - post_residual) as f64;
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            if stranded <= 10.0 {
                score += (8.5 + 1.1 * (10.0 - stranded)) * scarcity * (0.4 + 0.6 * (1.0 - progress));
            } else {
                let proximity = 1.0 - (stranded - 10.0).min(cap) / cap;
                score += 3.2 * proximity * scarcity * (1.0 - progress);
            }
        }
        // Dead-space dominance penalty when tight fits exist elsewhere.
        if dead_ratio > 0.35 && fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score += 7.5 * (dead_ratio - 0.35) * tightness * (1.0 - progress);
        }
        // Penalize leaving a residual awkwardly below the mean open-bin residual.
        if post_residual > 0 && mean_residual > 0.0 {
            let gap = mean_residual - post_residual as f64;
            if gap > 0.0 && gap < 0.15 * cap && fitting_bins_count > 2 {
                score += 4.8 * (gap / (0.15 * cap)) * (1.0 - progress);
            }
