    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // 2-step lookahead: reward when next item exactly fills post_residual
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64).max(0.0);
        } else {
            // next item cannot fit here; dead space likely
            score += 8.0;
        }
    }

    // Penalize large post_residual relative to mean residual (wasteful)
    score += 0.3 * (post_residual as f64 - mean_residual).max(0.0);

    // Last chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: penalize slightly unless current bin fit is poor
    if bin_residual == bin_capacity {
        score += 10.0;
        // opening a new bin is attractive when no good fit exists
        if post_residual > 0 && next_item_size > 0 && next_item_size > post_residual {
            score -= 12.0;
        }
    }

    // Late in stream: prefer compacting into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Prefer tight fits generally
    score += 2.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

