            score += 20.0 * (progress - 0.8) / 0.2 * (fresh_post / cap);
        }
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Layered dead-space rewards (tighter windows than parent).
    if post_residual == 0 {
        score -= 1000.0;
        if bin_residual < bin_capacity {
            score -= 40.0 * (1.0 - bin_residual as f64 / cap) * (1.0 - progress);
        }
    } else if post_residual <= 4 {
        score -= 270.0 + 4.0 * (4 - post_residual) as f64;
    } else if post_residual <= 12 {
        score -= 60.0 + 3.2 * (12 - post_residual) as f64;
    } else if post_residual <= 24 {
        score -= 12.0 + 1.4 * (24 - post_residual) as f64;
    } else if post_residual <= 40 {
        score -= 4.0 + 0.55 * (40 - post_residual) as f64;
    } else {
        score -= 1.0 - 0.012 * (post_residual as f64 - 40.0);
    }

    // Progress-scaled tightening.
    let w = 0.4 + 0.6 * progress * progress;
    score *= w;

    // Lookahead coupling with next item.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 880.0;
            if fitting_bins_count <= 3 {
                score -= 30.0 / fitting_bins_count.max(1) as f64 * (0.5 + 0.5 * (1.0 - progress));
            }
        } else if next_item_size < post_residual {
            let two_step_waste = (post_residual - next_item_size) as f64;
            if two_step_waste <= 8.0 {
                score -= 120.0 - 2.2 * two_step_waste;
            } else {
                score -= 80.0 - 0.4 * two_step_waste;
            }
            if two_step_waste <= 3.0 {
                score -= 45.0;
            }
            // Chain divisibility: residual absorbs repeated next items.
            let reps = post_residual / next_item_size;
            let rem = post_residual % next_item_size;
            if reps >= 2 {
                score -= 3.5 * ((reps as f64).min(4.0) - 1.0) * (1.0 - progress);
                if rem <= 3 {
                    score -= 6.0 * (1.0 - progress);
                }
            }
        } else {
            let miss = (next_item_size - post_residual) as f64;
            score += 0.95 * miss;
            if miss > 28.0 {
                score += 0.5 * (miss - 28.0);
            }
            // Stranded small residual weighted by scarcity.
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            if miss <= 10.0 {
                score += (8.0 + 1.0 * (10.0 - miss)) * scarcity * (0.4 + 0.6 * (1.0 - progress));
            }
        }
    }

    // Two-step lookahead: reward residuals that stay usable after next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after2 = post_residual - next_item_size;
        if after2 > 0 && after2 <= 6 {
            score -= 45.0 * (1.0 - after2 as f64 / 6.0) * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    // Dead-space dominance penalty when tight fits exist elsewhere.
    if bin_residual < bin_capacity {
        let dead_ratio = (bin_residual - item_size) as f64 / cap;
        if dead_ratio > 0.35 && fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score += 8.0 * (dead_ratio - 0.35) * tightness * (1.0 - progress);
        }
        // Residual-vs-mean harmony bonus.
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 1 {
            let harmony = (post_residual as f64 - mean_residual).abs() / cap;
            if harmony < 0.08 {
                score -= 9.0 * (1.0 - harmony / 0.08) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
    }

    // NEW-BIN CANDIDATE branch.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap) * open_bins_count as f64;
        let huge_item = item_size as f64 > 0.7 * cap;
        let remaining = if total_items > step_index { total_items - step_index } else { 1 };
        let remaining_frac = remaining as f64 / total_items.max(1) as f64;
        let fresh_post = cap - item_size as f64;
        let fresh_is_exact = fresh_post <= 4.0;

        if fragmentation > 0.55 || (huge_item && open_bins_count > 4) {
            score -= 60.0 + 45.0 * remaining_frac;
        } else if fresh_is_exact {
            score -= 130.0 + 60.0 * remaining_frac;
        } else {
            score += 450.0 - 80.0 * remaining_frac;
            if fitting_bins_count <= 3 && open_bins_count > 2 {
                score -= 35.0 + 20.0 * remaining_frac;
            }
        }

        // Fresh-bin reusable-tail bonus.
        if next_item_size > 0 && fresh_post > 0.0 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 2 && fragmentation < 0.5 {
                score -= 7.0 * ((reps as f64).min(4.0) - 1.0) * (0.4 + 0.6 * (1.0 - progress));
                if rem <= 3 {
                    score -= 5.0 * (1.0 - progress);
                }
            }
            let chain_post = fresh_post - next_item_size as f64;
            if chain_post > 0.0 && chain_post <= 4.0 {
                score -= 30.0 * (1.0 - chain_post / 4.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }

        // Refuse fresh bins late when open bins hold enough aggregate space.
        if remaining_frac < 0.15 && fresh_post > 0.3 * cap {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.35;
            if open_space > est_need {
                score += 55.0 * (1.0 - remaining_frac / 0.15);
            }
        }

        // Fresh residual matching mean harmony.
        let fresh_match = (fresh_post - mean_residual).abs() / cap;
        if fresh_post > 0.0 && fresh_match < 0.06 && fragmentation < 0.55 {
            score -= 30.0 * (1.0 - fresh_match / 0.06);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 12.0;
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Tight-fit reward: fraction of bin consumed by this item.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 25.0;

    // Lookahead: reward if the next item also fits into the post residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
    }
    // Penalize if next item is small and would be stranded by a mid-size gap.
    if next_item_size > 0 && next_item_size <= post_residual && post_residual - next_item_size < 10 && post_residual != next_item_size {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open,
    // but encourage consolidation when few are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 1.5 * (0.5 + progress);

    // Mean residual coupling: prefer bins whose residual deviates favorably
    // from the mean (smaller residual = tighter bin).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: make an empty bin moderately attractive only when
    // the item is large and would leave a big residual elsewhere, otherwise
    // keep it slightly unattractive to promote consolidation.
    if bin_residual == bin_capacity {
        let large_item_bonus = if item_size > bin_capacity / 2 { -10.0 } else { 0.0 };
        score += 20.0 + large_item_bonus - post_residual as f64 * 0.2;
    }

    score
}

