    // Penalize dead space that is too small for typical items.
    if post_residual > 0 {
        let dead = post_residual as f64;
        if dead < item_size as f64 && dead < next_item_size as f64 {
            score += 12.0 * (1.0 - dead / 50.0).max(0.0);
        }
    }

