    if bin_residual == bin_capacity {
        let crowding = (mean_residual / cap).min(1.0);
        let base = 30.0 + 45.0 * crowding;
        let late = 1.0 + 0.5 * (step_index as f64 / (total_items as f64).max(1.0));
        let fit_pressure = if fitting_bins_count <= 1 { -20.0 } else { 0.0 };
        score += base * late + fit_pressure;
        // Opening a bin is fine if item is huge and residuals are fragmented.
        if item_size as f64 > mean_residual {
            score -= 22.0;
