    if open_bins_count > 8 && bin_residual != bin_capacity {
        score -= 1.5;
    }

    // Small time-dependent tie-breaker noise-free jitter via deterministic coupling.
    let t = step_index as f64 / (total_items as f64).max(1.0);
    score += 0.5 * ((t * 6.283).sin()) * (bin_residual as f64 / cap);

    score
}

