        // MUTATION (gen 56): mid-gap filler bonus — when post_residual sits
        // just below the next item, reward placements that leave a residual
        // exactly reachable by common small-item sizes (<= 8), turning
        // near-miss residuals into two-step exact fills.
        if post_residual > 0 && next_item_size > post_residual && post_residual <= 8 {
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            score -= 10.0 * (1.0 - post_residual as f64 / 8.0) * scarcity * (0.4 + 0.6 * (1.0 - progress));
