        if remaining_frac >= 0.15 && remaining_frac < 0.45 && fresh_post > 0.4 * cap && fragmentation > 0.4 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.45;
            if open_space > est_need {
                score += 28.0 * (1.0 - remaining_frac / 0.45);
            }
        }
        // MUTATION (gen 56): deep-mid guard extension — tighten the
        // fragmentation threshold of the mid-stream refusal so bins with
        // moderately fragmented open slack are also protected from premature
        // fresh-bin opens, directly targeting the residual-variance waste.
        if remaining_frac >= 0.15 && remaining_frac < 0.55 && fresh_post > 0.35 * cap && fragmentation > 0.30 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.50;
            if open_space > est_need {
                score += 16.0 * (1.0 - remaining_frac / 0.55);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
