    // Layered near-perfect fill rewards (borrowed tightening from best).
    if post_residual > 0 && post_residual <= 4 {
        score -= 280.0 + 3.0 * (4 - post_residual) as f64;
    } else if post_residual > 4 && post_residual <= 10 {
        score -= 70.0 + 3.2 * (10 - post_residual) as f64;
    } else if post_residual > 10 && post_residual <= 24 {
        score -= 14.0 + 1.4 * (24 - post_residual) as f64;
    } else if post_residual > 24 && post_residual <= 40 {
        score -= 4.5 + 0.6 * (40 - post_residual) as f64;
    }

    // Progress-scaled tightening.
    let w = 0.4 + 0.6 * progress * progress;
    score *= w;

    // Lookahead coupling with next item.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if next_item_size < post_residual {
            let two_step_waste = (post_residual - next_item_size) as f64;
            if two_step_waste <= 8.0 {
                score -= 120.0 - 2.2 * two_step_waste;
            } else {
                score -= 85.0 - 0.4 * two_step_waste;
            }
            if two_step_waste <= 3.0 {
                score -= 45.0;
            }
        } else {
            let miss = (next_item_size - post_residual) as f64;
            score += 0.95 * miss;
            if miss > 28.0 {
                score += 0.45 * (miss - 28.0);
            }
        }
    }

    // Two-step lookahead: discourage consuming residuals whose tail stays usable.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after2 = post_residual - next_item_size;
        if after2 > 0 && after2 <= 6 {
            score -= 45.0 * (1.0 - progress);
        }
    }

    // Scarcity-weighted slack bonus when the next item fits here.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
        score -= (30.0 + 24.0 * scarcity) * (1.0 - slack / cap) * (0.6 + 0.4 * (1.0 - progress));
        if slack == 0.0 {
            score -= 18.0 * (1.0 - progress);
        }
    }

    // Dead-space penalty when large residual would be stranded.
    if bin_residual != bin_capacity {
        let dead = (bin_residual - item_size) as f64;
        let dead_ratio = dead / cap;
