        // MUTATION (gen 57): consolidation gradient — extend the fill-level
        // momentum with a smooth term that prefers the smallest resulting
        // residual among fitting bins, sharpening compaction without
        // disturbing the layered dead-space ladder.
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 1 {
            let rel = post_residual as f64 / (mean_residual + 1.0);
            if rel < 0.75 {
                score -= 2.6 * (0.75 - rel) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // MUTATION (gen 57): residual-band alignment — reward placements
        // whose post residual sits near a multiple of the next item size
        // (a future exact-fill opportunity), reinforcing the chain term
        // with a graded version for slightly-off multiples.
        if post_residual > 0 && next_item_size > 0 && post_residual > next_item_size {
            let chain = (post_residual % next_item_size.max(1)) as f64;
            if chain > 3.0 && chain <= 8.0 {
