        // leave a residual close to the *remaining* reusable space scale, so
        // open-bin residuals cluster together and later items can still use
        // them. Directly targets the diagnosed residual-variance weakness.
        if post_residual > 0 && mean_residual > 0.0 && open_bins_count > 2 {
            let dev = (post_residual as f64 - mean_residual).abs() / cap;
            let late = 0.4 + 0.6 * progress;
            if dev < 0.2 {
                score -= 5.5 * (1.0 - dev / 0.2) * late;
            } else if dev < 0.45 {
                score += 3.0 * (dev - 0.2) * late;
            }
