        // leftover residual is exactly reusable by a typical (mean-sized)
        // upcoming item even if not by the immediate next item, preserving
        // mid-size residuals instead of fragmenting them.
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
