pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let x = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let poly = x * x * (1.0 - x) * (1.0 - x);
    let coupling = poly * (1.0 + progress * (1.0 - progress) * 4.0);

    let mut score = pr - 12.0 * coupling * cap;

    // Penalize dead space scaled by stream progress (smooth quadratic).
    score += progress * progress * pr * 0.5;

    // Reward tight fits: smooth sigmoid-like term on normalized fill.
    let fill = 1.0 - x;
    score -= 6.0 * fill * fill * fill;

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 15.0 * (1.0 - progress);
    }

    // Lookahead coupling: penalize if next item can't use the post residual.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let unusable = (nx - pr).max(0.0) / cap;
        score += 10.0 * unusable * unusable;
        // Reward if next item fits exactly in the post residual.
        if nx <= pr {
            score -= 5.0 * (1.0 - (pr - nx) / cap);
        }
