        // Stranded residual too small for the next item.
        if next_item_size > 0 && post_residual < next_item_size {
            let stranded = (next_item_size - post_residual) as f64;
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            if stranded <= 10.0 {
                score += (8.0 + 1.0 * (10.0 - stranded)) * scarcity * (0.4 + 0.6 * (1.0 - progress));
