pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // (below the minimum plausible item size) are heavily penalized.
    let dead_threshold = 12.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }

    // Non-linear penalty on unusable gap relative to bin capacity.
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    score += (post / cap).powi(3) * 40.0;

    // Reward tight fits (small post_residual relative to item size).
    let item = item_size as f64;
    if item > 0.0 {
        score -= (item / (post + 1.0)) * 2.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly reward this placement; penalize if post residual is awkward
    // relative to the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 8.0 * (1.0 - (post - nxt).abs() / cap);
        } else {
            score += (nxt - post) * 0.5;
        }
    }

    // Open bins pressure: with many open bins, prefer consolidating into
    // existing bins; with few open bins, opening a new one is cheaper.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bonus: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: make it moderately attractive only when the item
    // is large or mean residual across open bins is small.
    if bin_residual == bin_capacity {
        let pressure = (mean_residual / cap).max(0.0);
        score = item * 0.9 + 5.0 - (1.0 - pressure.min(1.0)) * 15.0;
        if open_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Slight stream-progression term: early on, keep flexibility; later,
    // tighten packing aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (post / cap) * progress * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
