        // enough aggregate space for the remaining demand.
        if remaining_frac < 0.15 && fresh_post > 0.3 * cap {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.35;
            if open_space > est_need {
                score += 55.0 * (1.0 - remaining_frac / 0.15);
            }
        }
        // MUTATION (gen 55, widened gen 60): mid-stream fresh-bin guard —
        // refuse spurious opens whenever aggregate open slack plausibly
        // covers remaining demand, cutting residual-variance waste.
        if remaining_frac >= 0.15 && remaining_frac < 0.55 && fresh_post > 0.35 * cap && fragmentation > 0.35 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.45;
            if open_space > est_need {
                score += 34.0 * (1.0 - remaining_frac / 0.55);
            }
        }
        // MUTATION (gen 60): fresh-bin divisibility shaping — prefer opening
        // a bin whose fresh residual decomposes cleanly into the next item.
        if next_item_size > 1 && fresh_post > next_item_size as f64 {
            let rem = (fresh_post as u32) % next_item_size;
            if rem == 0 {
                score -= 6.0 * (0.4 + 0.6 * (1.0 - progress));
            } else if rem > next_item_size / 2 {
                score += 2.5 * (rem as f64 / next_item_size as f64) * (1.0 - progress);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward if the next item fits the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Perfect 2-chain: next item exactly fills remaining space
            let slack_after_next = post_residual as f64 - next_item_size as f64;
            score -= 40.0 - slack_after_next * 0.3; // tighter chain = bigger reward
        } else if next_item_size <= bin_residual {
            // Next item fits only if we DON'T place here; penalize blocking the chain
            score += 15.0;
        }
    } else {
        // Last item: just minimize waste
        score -= 10.0;
    }

    // Reward tight fits relative to mean residual across open bins
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 0.4;
    } else {
        score += (post_residual as f64 - mean_residual) * 0.2;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when decent open bins exist
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64;
        score += 5.0 + pressure * 0.5;
        // But if nothing else fits well (high mean residual waste), new bin is fine
        if mean_residual < item_size as f64 * 0.5 {
            score -= 12.0;
        }
    }

    // Mild progression term: late in stream, prefer consolidating into existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 6.0;
    }

    // Penalize leaving dead space that no realistic item (min size 1) can use
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // small unusable sliver
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
