pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: strongly discount bins whose post-residual is small.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 40.0 * tightness * tightness;

    // Penalize post-residuals that are small-but-unusable for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item exactly fills the post-residual,
    // this is a perfect chain — reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 15.0 * (post_residual as f64 - next_item_size as f64).min(10.0) / 10.0;
        } else {
            // Next item cannot use this residual: penalize leaving medium dead space.
            let dead = post_residual as f64;
            if dead >= 10.0 && dead < next_item_size as f64 {
                score += 0.3 * dead;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: opening a bin is only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = (mean_residual / cap - 0.5).max(0.0);
        score += 55.0 + 30.0 * progress - 40.0 * pressure;
        if fitting_bins_count == 0 {
            score -= 70.0; // no alternative: new bin is fine
