    } else {
        // Slight preference for bins with residual close to mean (keep balance).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.15 * dev;
    }

    // Prefer filling bins when many are open (consolidation pressure).
    score -= 0.5 * (open_bins_count as f64).ln().max(0.0) * tightness;

    score
}

