        }
        if post_residual > 12 && post_residual < 40 && next_item_size > post_residual {
            let orphan = (post_residual as f64 - 12.0) / 28.0;
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            score += 17.0 * orphan * scarcity * (0.5 + 0.5 * (1.0 - progress));
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let chain = post_residual % next_item_size.max(1);
            if chain == 0 {
                score -= 26.0 * (1.0 - progress);
            } else if chain <= 3 {
                score -= 11.0 * (1.0 - progress);
            }
        }
        // Stranded residual: too small for next item, weighted by scarcity.
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            let stranded = (next_item_size - post_residual) as f64;
            if stranded <= 10.0 {
                let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
                score += (8.5 + 1.1 * (10.0 - stranded)) * scarcity * (0.4 + 0.6 * (1.0 - progress));
            } else {
                let proximity = 1.0 - (stranded - 10.0).min(bin_capacity) as f64 / cap;
                let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
                score += 3.2 * proximity * scarcity * (1.0 - progress);
            }
        }
        // Dead-space dominance penalty when tight fits exist elsewhere.
        if dead_ratio > 0.35 && fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score += 7.5 * (dead_ratio - 0.35) * tightness * (1.0 - progress);
        }
        // Penalize leaving a residual awkwardly below the mean open-bin residual.
        if post_residual > 0 && mean_residual > 0.0 {
            let gap = mean_residual - post_residual as f64;
            if gap > 0.0 && gap < 0.15 * cap && fitting_bins_count > 2 {
                score += 4.8 * (gap / (0.15 * cap)) * (1.0 - progress);
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size.max(1) && fitting_bins_count > 2 {
            score -= 6.5 * (1.0 - progress);
        }
        // Strong extra reward for exact fills of nearly-full bins.
        if post_residual == 0 && bin_residual < bin_capacity {
            score -= 42.0 * (1.0 - bin_residual as f64 / cap) * (1.0 - progress);
        }
        // Residual-vs-mean harmony.
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 1 {
            let harmony = (post_residual as f64 - mean_residual).abs() / cap;
            if harmony < 0.08 {
                score -= 9.0 * (1.0 - harmony / 0.08) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // Chunkable residuals absorb repeated small items.
        if post_residual > 6 && post_residual <= 30 && next_item_size > 0 && next_item_size <= post_residual {
            let reps = post_residual / next_item_size.max(1);
            if reps >= 2 {
                score -= 3.5 * (reps as f64).min(4.0) * (1.0 - progress);
            }
        }
        // Two-step lookahead — reward leaving a residual that can exactly
        // absorb next_item followed by another small item.
        if next_item_size > 0 && post_residual > next_item_size {
            let after_next = post_residual - next_item_size;
            if after_next > 0 && after_next <= 12 {
                let tail = after_next as f64;
                score -= (14.0 - 0.9 * tail) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // Penalize tiny dead-zone residuals unusable by the next item.
        if post_residual > 0 && post_residual < 6 && next_item_size > post_residual {
            score += 6.0 * (1.0 - progress);
        }
        // Three-step horizon — residuals that can absorb next_item plus a
        // mid-size tail remain valuable when bins are scarce.
        if next_item_size > 0 && post_residual > next_item_size {
            let after_next = (post_residual - next_item_size) as f64;
            if after_next > 8.0 && after_next <= 16.0 && progress < 0.85 {
                let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
                score -= (4.0 + 3.0 * scarcity) * (1.0 - (after_next - 8.0) / 8.0) * (1.0 - progress);
            }
        }
        // Overshoot spreading refinement.
        if post_residual > 0 && next_item_size > 0 && fitting_bins_count > 3 {
            let overshoot = post_residual.saturating_sub(next_item_size) as f64;
            if overshoot > 16.0 {
                score += 1.6 * ((overshoot - 16.0) / cap).min(0.25) * 100.0 * 0.01 * (1.0 - progress);
            }
        }
        // Dead-ratio gradient tightened: absolute dead space punished alongside ratio.
        if fitting_bins_count > 1 && dead_ratio > 0.08 && post_residual > 0 {
            let scarcity = 1.0 / (fitting_bins_count as f64);
            let comp_slack = (mean_residual / cap).min(1.0);
            score += 6.5 * (dead_ratio - 0.08) * scarcity * comp_slack * (0.5 + 0.5 * (1.0 - progress));
            score += 2.2 * (dead / cap) * scarcity * comp_slack * (1.0 - progress);
        }
        // Residual-magnitude tiebreaker: among similar dead ratios, prefer
        // the residual closest to the mean, consolidating usable space.
        if fitting_bins_count > 2 && post_residual > 0 && mean_residual > 0.0 {
            let dev = ((post_residual as f64 - mean_residual).abs() / cap).min(0.4);
            score += 5.0 * dev * (1.0 - progress);
        }
        // Exact-fit ladder — round residuals are reusable by common sizes.
        if post_residual > 0 && post_residual % 10 == 0 && post_residual <= 60 && next_item_size > 0 && next_item_size <= post_residual {
            score -= 4.0 * (1.0 - progress) * (1.0 - post_residual as f64 / 120.0);
        }
        // Triple-fill planning — post_residual hosts next_item plus a small
        // companion; reward when bins are scarce.
        if next_item_size > 0 && post_residual > next_item_size && fitting_bins_count <= 3 {
            let tail = post_residual - next_item_size;
            if tail >= 1 && tail <= 12 {
                score -= 9.0 * (1.0 - tail as f64 / 12.0) * (1.0 - progress);
            }
        }
        // Protect the unique best fit for next_item when many bins are open.
        if next_item_size > 0 && post_residual == next_item_size && open_bins_count > 5 {
            score -= 14.0 * (0.4 + 0.6 * (1.0 - progress));
        }
        // Mid-band residual discount — 16..=28 residuals are highly reusable.
        if post_residual >= 16 && post_residual <= 28 && progress < 0.7 && fitting_bins_count > 1 {
            score -= 7.0 * (1.0 - (post_residual - 16) as f64 / 12.0) * (0.5 + 0.5 * progress);
        }
        // Dead-space compaction coupling — reward consolidation near the mean.
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 1 {
            let match_mean = 1.0 - ((post_residual as f64 - mean_residual).abs() / cap);
            if match_mean > 0.9 {
                score -= 5.0 * (match_mean - 0.9) * 10.0 * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // Waste-avoidance gradient — penalize dead space beyond next item's need.
        if next_item_size > 0 && post_residual > next_item_size && fitting_bins_count > 1 {
            let excess = (post_residual - next_item_size) as f64;
            if excess > 12.0 {
                score += 1.8 * ((excess - 12.0) / cap).min(0.3) * 100.0 * 0.01 * (1.0 - progress) * (fitting_bins_count as f64).min(4.0);
            }
        }
        // Tight-fit scarcity escalation.
        if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 4 {
            let gap_after = (post_residual - next_item_size) as f64;
            let urgency = (4.0 - fitting_bins_count as f64) / 3.0;
            score -= 10.0 * urgency * (1.0 - gap_after / cap) * (0.5 + 0.5 * (1.0 - progress));
        }
        // Mean-residual drain coupling.
        if post_residual > 0 && mean_residual > 0.0 && open_bins_count > 3 {
            let below = mean_residual - post_residual as f64;
            if below > 0.25 * cap && progress < 0.75 {
                score += 6.0 * (below / cap) * (1.0 - progress);
            }
        }
        // Squeeze-escalation ladder — preserve "next-item-shaped" pockets.
        if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 6 {
            let tail = post_residual - next_item_size;
            let urgency = (6.0 - fitting_bins_count as f64) / 5.0;
            if tail == 0 {
                score -= 22.0 * urgency * (1.0 - progress);
            } else if tail <= 2 {
                score -= 9.0 * urgency * (1.0 - tail as f64 / 2.0) * (1.0 - progress);
            }
        }
        // Stranded-pair avoidance — don't consume a bin that would strand a
        // residual smaller than next_item when the mean residual could host it.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size
            && mean_residual > 0.0 && (mean_residual as u32) >= next_item_size && fitting_bins_count > 1 {
            score += 7.0 * (1.0 - progress);
        }
        // MUTATION (gen 60): waste-density term — penalize placements whose
        // leftover residual is unusable by the next item and by the mean
        // open slack, pushing residual space toward reusable magnitudes.
        if post_residual > 0 && next_item_size > 0 && fitting_bins_count > 1 {
            let usable = next_item_size <= post_residual
                || (mean_residual as u32) >= next_item_size;
            if !usable {
                let waste_frac = post_residual as f64 / cap;
                let late = 0.35 + 0.65 * progress;
                score += 9.0 * waste_frac * late;
            }
        }
        // MUTATION (gen 60): fill-level momentum — reward placing into bins
        // whose residual is already small relative to mean, consolidating
        // near-full bins to free up larger residuals elsewhere.
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 2 {
            let rel = post_residual as f64 / (mean_residual + 1.0);
            if rel < 0.5 {
                score -= 6.0 * (1.0 - rel / 0.5) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        // MUTATION (gen 60): scarcity-weighted perfect-fit extension — when
        // few bins can host the next item, an exact post-residual match is
        // disproportionately valuable; combine fine-grained fitting with
        // lookahead anticipation.
        if next_item_size > 0 && post_residual == next_item_size && fitting_bins_count <= 3 {
            score -= 30.0 / fitting_bins_count.max(1) as f64 * (0.5 + 0.5 * (1.0 - progress));
        }
    } else {
        // NEW-BIN CANDIDATE branch.
        let fragmentation = (mean_residual / cap) * open_bins_count as f64;
        let huge_item = item_size as f64 > 0.7 * cap;
        let remaining = if total_items > step_index { total_items - step_index } else { 1 };
        let remaining_frac = remaining as f64 / total_items.max(1) as f64;
        let fresh_post = cap - item_size as f64;
        let fresh_is_exact = fresh_post <= 4.0 && fresh_post >= 0.0;

        if fragmentation > 0.55 || (huge_item && open_bins_count > 4) {
            score -= 66.0 + 46.0 * remaining_frac;
        } else if fresh_is_exact {
            score -= 134.0 + 66.0 * remaining_frac;
        } else {
            score += 400.0 - 82.0 * remaining_frac;
            if fitting_bins_count <= 3 && open_bins_count > 2 {
                score -= 30.0 + 18.0 * remaining_frac;
            }
        }

        let fresh_match = (fresh_post - mean_residual).abs() / cap;
        if fresh_match < 0.05 {
            score -= 76.0 * (1.0 - fresh_match / 0.05);
        }
        if remaining_frac < 0.05 && fresh_post > 0.0 && !fresh_is_exact {
            score += 160.0 * (fresh_post / cap);
        }
        if fresh_post > 0.0 && fresh_post <= 22.0 && !fresh_is_exact {
            score -= 26.0 * (1.0 - fresh_post / 22.0);
        }
        if fresh_post > 22.0 && fresh_post <= 40.0 && fragmentation < 0.35 {
            score -= 12.5 * (1.0 - (fresh_post - 22.0) / 18.0);
        }
        if fresh_post > 0.0 && fresh_match < 0.12 && fragmentation < 0.55 {
            score -= 30.0 * (1.0 - fresh_match / 0.12);
        }
        if next_item_size > 0 && fresh_post > 0.0 {
            let fresh_exact_next = (fresh_post as u32) == next_item_size;
            let open_can_next = mean_residual >= next_item_size as f64;
            if fresh_exact_next && !open_can_next && fitting_bins_count <= 2 {
                score -= 52.0 * (1.0 - progress);
            }
            if (fresh_post as u32) < next_item_size && mean_residual > next_item_size as f64 {
                score += 21.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && fresh_post > next_item_size as f64 {
            let chain_post = fresh_post - next_item_size as f64;
            if chain_post <= 4.0 {
                score -= 34.0 * (1.0 - chain_post / 4.0) * (0.5 + 0.5 * (1.0 - progress));
            } else if chain_post <= 10.0 {
                score -= 9.5 * (1.0 - (chain_post - 4.0) / 6.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        if remaining_frac < 0.12 && fresh_post > 0.0 && !fresh_is_exact && mean_residual * open_bins_count as f64 > 3.0 * cap {
            score += 42.0 * (1.0 - remaining_frac / 0.12);
        }
        // When only one open bin can fit and this item would leave a tiny
        // stranded residual there, opening a fresh bin is often better.
        if fitting_bins_count == 1 && fresh_post > 0.0 && next_item_size > 0 {
            let stranded_here = bin_capacity.saturating_sub(item_size);
            let would_strand = stranded_here < next_item_size;
            if would_strand && stranded_here > 0 && stranded_here <= 8 {
                score -= 32.0 * (1.0 - progress);
            }
        }
        // Open bins collectively nearly exhausted → keep density high.
        let open_capacity = mean_residual * open_bins_count as f64;
        let per_item_need = cap * 0.5;
        if remaining_frac > 0.25 && open_capacity < per_item_need * open_bins_count.max(1) as f64 * 0.5 {
            score -= 18.0 * (1.0 - progress);
        }
        // Fresh-bin chain quality.
        if next_item_size > 0 && fresh_post > next_item_size as f64 {
            let after_next = fresh_post - next_item_size as f64;
            if after_next > 0.0 && after_next <= 8.0 && fragmentation < 0.5 {
                score -= 20.0 * (1.0 - after_next / 8.0) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        // Avoid fresh bins whose residual is smaller than next_item when
        // open bins collectively have plenty of slack.
        if next_item_size > 0 && fresh_post > 0.0 && (fresh_post as u32) < next_item_size {
            let slack_total = mean_residual * open_bins_count as f64;
            if slack_total > 2.0 * cap {
                score += 26.0 * (1.0 - progress);
            }
        }
        // Fresh-bin exact-next bonus when fragmentation is moderate.
        if next_item_size > 0 && (fresh_post as u32) == next_item_size && fragmentation > 0.3 {
            score -= 44.0 * (0.5 + 0.5 * (1.0 - progress));
        }
        // Refuse very loose fresh bins when mean residual is tiny but many
        // bins are open — consolidation beats expansion.
        if fresh_post > 0.5 * cap && mean_residual < 0.2 * cap && remaining_frac > 0.3 && open_bins_count > 3 {
            score += 24.0 * (fresh_post / cap - 0.5) * 2.0 * (1.0 - progress);
        }
        // Single-fit guard.
        if fitting_bins_count <= 1 && fresh_post > 0.45 * cap && next_item_size > 0 {
            let reachable = (next_item_size as f64 / fresh_post).min(1.0);
            if reachable < 0.5 {
                score += 18.0 * (0.5 - reachable) * (1.0 - progress);
            }
        }
        // Fresh-bin reusable-tail bonus — residual a multiple of next_item.
        if next_item_size > 0 && fresh_post > 0.0 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 2 && fragmentation < 0.5 {
                score -= 7.0 * ((reps as f64).min(4.0) - 1.0) * (0.4 + 0.6 * (1.0 - progress));
                if rem <= 3 {
                    score -= 5.0 * (1.0 - progress);
                }
            }
        }
        // Fresh-bin two-item plan.
        if next_item_size > 0 && fitting_bins_count <= 2 && fresh_post > next_item_size as f64 {
            let tail = fresh_post - next_item_size as f64;
            if tail > 0.0 && tail <= 6.0 {
                score -= 28.0 * (1.0 - tail / 6.0) * (1.0 - progress);
            }
        }
        // Late-stream consolidation — prefer filling existing bins near the
        // end unless the fresh fit is near-exact.
        if progress > 0.8 && !fresh_is_exact && fresh_post > 8.0 && fitting_bins_count >= 1 {
            score += 20.0 * (progress - 0.8) / 0.2 * (fresh_post / cap);
        }
        // Aggregate-slack conservation — refuse a loose fresh bin when total
        // open slack already exceeds the expected need of remaining items.
        if remaining_frac > 0.15 && !fresh_is_exact && fresh_post > 0.35 * cap {
            let expected_need = remaining as f64 * (cap * 0.45);
            if open_capacity > expected_need {
                score += 22.0 * ((open_capacity - expected_need) / expected_need).min(1.0) * (1.0 - progress);
            }
        }
        // Fresh-bin scarcity gate.
        if fitting_bins_count == 0 && fresh_post > 0.0 {
            score -= 55.0 * (1.0 - fresh_post / cap) * (0.4 + 0.6 * (1.0 - progress));
        }
        // Fresh-bin mean-harmony.
        if fresh_post > 0.0 && mean_residual > 0.0 && open_bins_count > 2 && fresh_match < 0.25 {
            score -= 14.0 * (1.0 - fresh_match / 0.25) * (0.5 + 0.5 * (1.0 - progress));
        }
        // Fresh-bin dead-space cap — refuse to open a fresh bin whose
        // residual exceeds the largest observed mean slack by a wide margin
        // while aggregate slack still covers several items.
        if fresh_post > 0.55 * cap && open_capacity > 3.0 * cap && remaining_frac > 0.2 {
            score += 30.0 * (fresh_post / cap - 0.55) * remaining_frac * (1.0 - progress);
        }
        // MUTATION (gen 60): mid-stream fresh-bin guard — extend the refusal
        // band into the middle of the stream when aggregate open slack can
        // plausibly absorb the remaining demand, cutting spurious bin opens.
        if remaining_frac >= 0.15 && remaining_frac < 0.45 && fresh_post > 0.4 * cap && fragmentation > 0.4 {
            let est_need = (remaining as f64) * (item_size as f64) * 0.45;
            if open_capacity > est_need {
                score += 28.0 * (1.0 - remaining_frac / 0.45);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let norm_pr = pr / bin_capacity as f64;

    // Tight fit reward: strongest early, decaying with smooth polynomial in progress
    let tightness = 1.0 - norm_pr;
    score -= 30.0 * tightness * tightness * (1.0 - 0.5 * progress);

    // Non-linear coupling of post_residual with progress: small residuals get
    // relatively better late in the stream (bin consolidation pressure)
    let coupling = norm_pr * (1.0 - norm_pr);
    score += 12.0 * coupling * (0.5 + progress);

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: penalize if post_residual cannot fit the next item (dead space),
    // reward if next item exactly fits the post-residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (pr + 0.5) < nxt {
            score += 8.0 * (1.0 - progress) * (nxt - pr) / bin_capacity as f64;
        } else if (pr - nxt).abs() < 0.5 {
            score -= 15.0;
        } else {
            score -= 4.0 * (1.0 - (pr - nxt) / bin_capacity as f64);
        }
    }

    // Last chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when good fits exist
    // or late in the stream; relax slightly when many bins are open and residual
    // mean is high (fragmentation)
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / bin_capacity as f64 - 0.5).clamp(0.0, 1.0);
        score += 18.0 + 10.0 * (1.0 - progress) - 6.0 * fragmentation;
    } else {
        // Slight preference for bins below mean residual (balance residuals)
        score += 3.0 * ((pr - mean_residual) / bin_capacity as f64).clamp(-1.0, 1.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Layered dead-space rewards (lower post_residual = better).
    if post_residual == 0 {
        score -= 980.0;
    } else if post_residual <= 4 {
        score -= 250.0 + 4.2 * (4 - post_residual) as f64;
    } else if post_residual <= 10 {
        score -= 64.0 + 3.6 * (10 - post_residual) as f64;
    } else if post_residual <= 22 {
        score -= 13.5 + 1.5 * (22 - post_residual) as f64;
    } else if post_residual <= 32 {
        score -= 5.0 + 0.7 * (32 - post_residual) as f64;
    } else if post_residual <= 48 {
        score -= 1.2 + 0.22 * (48 - post_residual) as f64;
    } else {
        score -= 1.2 - 0.014 * (post_residual as f64 - 48.0);
    }

    // Progress-scaled weighting: tighten late in the stream.
    let w = 0.33 + 0.67 * progress * progress;
    score *= w;

    // Lookahead coupling with the next item.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if next_item_size < post_residual {
            let two_step_waste = (post_residual - next_item_size) as f64;
            if two_step_waste <= 8.0 {
                score -= 135.0 - 2.3 * two_step_waste;
            } else {
                score -= 72.0 - 0.58 * two_step_waste;
            }
            if two_step_waste <= 3.0 {
                score -= 48.0;
            }
        } else {
            let miss = (next_item_size - post_residual) as f64;
            score += 0.95 * miss;
            if miss > 26.0 {
                score += 0.55 * (miss - 26.0);
            }
        }
    }

    // Slack-based scarcity boost when the next item fits here.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
        let boost = 36.0 + 26.0 * scarcity;
        score -= boost * (1.0 - slack / cap) * (0.6 + 0.4 * (1.0 - progress));
        if fitting_bins_count <= 2 {
            score -= 15.0 * (1.0 - slack / cap);
        }
        if slack == 0.0 {
            score -= 20.0 * (1.0 - progress);
        }
    }

    if bin_residual != bin_capacity {
        let dead = (bin_residual - item_size) as f64;
        let dead_ratio = dead / cap;
        if dead_ratio > 0.5 && fitting_bins_count > 1 {
            score += 10.5 * (dead_ratio - 0.5) * (1.0 - progress);
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
            && mean_residual > 0.0 && (mean_residual as u32) >= next_item_size {
            score += 12.0;
        }
        if post_residual > 12 && post_residual < 40 && next_item_size > post_residual {
            let orphan = (post_residual as f64 - 12.0) / 28.0;
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            score += 17.0 * orphan * scarcity * (0.5 + 0.5 * (1.0 - progress));
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let chain = post_residual % next_item_size.max(1);
            if chain == 0 {
                score -= 26.0 * (1.0 - progress);
            } else if chain <= 3 {
                score -= 11.0 * (1.0 - progress);
            }
        }
        // Stranded residual: too small for next item, weighted by scarcity.
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            let stranded = (next_item_size - post_residual) as f64;
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            if stranded <= 10.0 {
                score += (8.5 + 1.1 * (10.0 - stranded)) * scarcity * (0.4 + 0.6 * (1.0 - progress));
            } else {
                let proximity = 1.0 - (stranded - 10.0).min(cap) / cap;
                score += 3.2 * proximity * scarcity * (1.0 - progress);
            }
        }
        // Dead-space dominance penalty when tight fits exist elsewhere.
        if dead_ratio > 0.35 && fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score += 7.5 * (dead_ratio - 0.35) * tightness * (1.0 - progress);
        }
        // Penalize leaving a residual awkwardly below the mean open-bin residual.
        if post_residual > 0 && mean_residual > 0.0 {
            let gap = mean_residual - post_residual as f64;
            if gap > 0.0 && gap < 0.15 * cap && fitting_bins_count > 2 {
                score += 4.8 * (gap / (0.15 * cap)) * (1.0 - progress);
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size.max(1) && fitting_bins_count > 2 {
            score -= 6.5 * (1.0 - progress);
        }
        // Strong extra reward for exact fills of nearly-full bins.
        if post_residual == 0 && bin_residual < bin_capacity {
            score -= 42.0 * (1.0 - bin_residual as f64 / cap) * (1.0 - progress);
        }
        // Residual-vs-mean harmony.
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 1 {
            let harmony = (post_residual as f64 - mean_residual).abs() / cap;
            if harmony < 0.08 {
                score -= 9.0 * (1.0 - harmony / 0.08) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // Chunkable residuals absorb repeated small items.
        if post_residual > 6 && post_residual <= 30 && next_item_size > 0 && next_item_size <= post_residual {
            let reps = post_residual / next_item_size.max(1);
            if reps >= 2 {
                score -= 3.5 * (reps as f64).min(4.0) * (1.0 - progress);
            }
        }
        // Two-step lookahead.
        if next_item_size > 0 && post_residual > next_item_size {
            let after_next = post_residual - next_item_size;
            if after_next > 0 && after_next <= 12 {
                let tail = after_next as f64;
                score -= (14.0 - 0.9 * tail) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // Penalize tiny dead-zone residuals unusable by the next item.
        if post_residual > 0 && post_residual < 6 && next_item_size > post_residual {
            score += 6.0 * (1.0 - progress);
        }
        // Three-step horizon.
        if next_item_size > 0 && post_residual > next_item_size {
            let after_next = (post_residual - next_item_size) as f64;
            if after_next > 8.0 && after_next <= 16.0 && progress < 0.85 {
                let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
                score -= (4.0 + 3.0 * scarcity) * (1.0 - (after_next - 8.0) / 8.0) * (1.0 - progress);
            }
        }
        // Overshoot spreading refinement.
        if post_residual > 0 && next_item_size > 0 && fitting_bins_count > 3 {
            let overshoot = post_residual.saturating_sub(next_item_size) as f64;
            if overshoot > 16.0 {
                score += 1.6 * ((overshoot - 16.0) / cap).min(0.25) * (1.0 - progress);
            }
        }
        // Dead-ratio gradient with residual-magnitude term, scaled by aggregate open slack.
        if fitting_bins_count > 1 && dead_ratio > 0.08 && post_residual > 0 {
            let scarcity = 1.0 / (fitting_bins_count as f64);
            let comp_slack = (mean_residual / cap).min(1.0);
            score += 6.5 * (dead_ratio - 0.08) * scarcity * comp_slack * (0.5 + 0.5 * (1.0 - progress));
            score += 2.2 * (dead / cap) * scarcity * comp_slack * (1.0 - progress);
        }
        // Residual-magnitude tiebreaker toward mean.
        if fitting_bins_count > 2 && post_residual > 0 && mean_residual > 0.0 {
            let dev = ((post_residual as f64 - mean_residual).abs() / cap).min(0.4);
            score += 5.0 * dev * (1.0 - progress);
        }
        // Exact-fit ladder on round residuals.
        if post_residual > 0 && post_residual % 10 == 0 && post_residual <= 60 && next_item_size > 0 && next_item_size <= post_residual {
            score -= 4.0 * (1.0 - progress) * (1.0 - post_residual as f64 / 120.0);
        }
        // Scarcity-weighted perfect-fit extension.
        if next_item_size > 0 && post_residual == next_item_size && fitting_bins_count <= 3 {
            score -= 30.0 / fitting_bins_count.max(1) as f64 * (0.5 + 0.5 * (1.0 - progress));
        }
        // MUTATION (gen 55, refined gen 60): waste-density term — penalize
        // placements whose leftover residual is unusable relative to the
        // remaining stream demand, with a smooth gradient instead of a
        // hard cutoff so mid-range residuals get graded pressure.
        if post_residual > 0 && next_item_size > 0 && fitting_bins_count > 1 {
            let usable = next_item_size <= post_residual
                || (mean_residual as u32) >= next_item_size;
            if !usable {
                let waste_frac = post_residual as f64 / cap;
                let late = 0.35 + 0.65 * progress;
                score += 11.0 * waste_frac * late;
                // Extra pressure when the stranded gap is small-but-annoying
                // (residual just misses the next item by a few units).
                let miss_by = (next_item_size - post_residual.min(next_item_size)) as f64;
                if miss_by > 0.0 && miss_by <= 12.0 {
                    score += (5.0 - 0.25 * miss_by) * late;
                }
            }
        }
        // MUTATION (gen 55, refined gen 60): fill-level momentum — reward
        // consolidating near-full bins; extend the band slightly and add a
        // scarcity coupling so it fires harder when alternatives are few.
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 2 {
            let rel = post_residual as f64 / (mean_residual + 1.0);
            if rel < 0.55 {
                let scarcity = 1.0 / (fitting_bins_count as f64);
                score -= (6.0 + 8.0 * scarcity) * (1.0 - rel / 0.55) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        // MUTATION (gen 60): residual-uniformity pull — when many bins are
        // open, prefer placements that drive post_residual toward the value
        // most likely to absorb future items (the mean residual), reducing
        // residual variance and the trailing dead-space.
        if fitting_bins_count > 4 && post_residual > 0 && mean_residual > 0.0 {
            let target = mean_residual.max(1.0);
            let dev = ((post_residual as f64 - target) / target).abs().min(1.0);
            score += 3.0 * dev * (0.3 + 0.7 * progress);
        }
    } else {
        // NEW-BIN CANDIDATE branch.
        let fragmentation = (mean_residual / cap) * open_bins_count as f64;
        let huge_item = item_size as f64 > 0.7 * cap;
        let remaining = if total_items > step_index { total_items - step_index } else { 1 };
        let remaining_frac = remaining as f64 / total_items.max(1) as f64;
        let fresh_post = cap - item_size as f64;
        let fresh_is_exact = fresh_post <= 4.0 && fresh_post >= 0.0;

        if fragmentation > 0.55 || (huge_item && open_bins_count > 4) {
            score -= 66.0 + 46.0 * remaining_frac;
        } else if fresh_is_exact {
            score -= 134.0 + 66.0 * remaining_frac;
        } else {
            score += 400.0 - 82.0 * remaining_frac;
            if fitting_bins_count <= 3 && open_bins_count > 2 {
                score -= 30.0 + 18.0 * remaining_frac;
            }
        }

        let fresh_match = (fresh_post - mean_residual).abs() / cap;
        if fresh_match < 0.05 {
            score -= 76.0 * (1.0 - fresh_match / 0.05);
        }
        if remaining_frac < 0.05 && fresh_post > 0.0 && !fresh_is_exact {
            score += 160.0 * (fresh_post / cap);
        }
        if fresh_post > 0.0 && fresh_post <= 22.0 && !fresh_is_exact {
            score -= 26.0 * (1.0 - fresh_post / 22.0);
        }
        if fresh_post > 22.0 && fresh_post <= 40.0 && fragmentation < 0.35 {
            score -= 12.5 * (1.0 - (fresh_post - 22.0) / 18.0);
        }
        if fresh_post > 0.0 && fresh_match < 0.12 && fragmentation < 0.55 {
            score -= 30.0 * (1.0 - fresh_match / 0.12);
        }
        if next_item_size > 0 && fresh_post > 0.0 {
            let fresh_exact_next = (fresh_post as u32) == next_item_size;
            let open_can_next = mean_residual >= next_item_size as f64;
            if fresh_exact_next && !open_can_next && fitting_bins_count <= 2 {
                score -= 52.0 * (1.0 - progress);
            }
            if (fresh_post as u32) < next_item_size && mean_residual > next_item_size as f64 {
                score += 21.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && fresh_post > next_item_size as f64 {
            let chain_post = fresh_post - next_item_size as f64;
            if chain_post <= 4.0 {
                score -= 34.0 * (1.0 - chain_post / 4.0) * (0.5 + 0.5 * (1.0 - progress));
            } else if chain_post <= 10.0 {
                score -= 9.5 * (1.0 - (chain_post - 4.0) / 6.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        if remaining_frac < 0.12 && fresh_post > 0.0 && !fresh_is_exact && mean_residual * open_bins_count as f64 > 3.0 * cap {
            score += 42.0 * (1.0 - remaining_frac / 0.12);
        }
        if fitting_bins_count == 1 && fresh_post > 0.0 && next_item_size > 0 {
            let stranded_here = bin_capacity.saturating_sub(item_size);
            let would_strand = stranded_here < next_item_size;
            if would_strand && stranded_here > 0 && stranded_here <= 8 {
                score -= 32.0 * (1.0 - progress);
            }
        }
        let open_capacity = mean_residual * open_bins_count as f64;
        let per_item_need = cap * 0.5;
        if remaining_frac > 0.25 && open_capacity < per_item_need * open_bins_count.max(1) as f64 * 0.5 {
            score -= 18.0 * (1.0 - progress);
        }
        if next_item_size > 0 && fresh_post > next_item_size as f64 {
            let after_next = fresh_post - next_item_size as f64;
            if after_next > 0.0 && after_next <= 8.0 && fragmentation < 0.5 {
                score -= 20.0 * (1.0 - after_next / 8.0) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        if next_item_size > 0 && fresh_post > 0.0 && (fresh_post as u32) < next_item_size {
            let slack_total = mean_residual * open_bins_count as f64;
            if slack_total > 2.0 * cap {
                score += 26.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && (fresh_post as u32) == next_item_size && fragmentation > 0.3 {
            score -= 44.0 * (0.5 + 0.5 * (1.0 - progress));
        }
        if fresh_post > 0.5 * cap && mean_residual < 0.2 * cap && remaining_frac > 0.3 && open_bins_count > 3 {
            score += 24.0 * (fresh_post / cap - 0.5) * 2.0 * (1.0 - progress);
        }
        if fitting_bins_count <= 1 && fresh_post > 0.45 * cap && next_item_size > 0 {
            let reachable = (next_item_size as f64 / fresh_post).min(1.0);
            if reachable < 0.5 {
                score += 18.0 * (0.5 - reachable) * (1.0 - progress);
            }
        }
        // Fresh-bin reusable-tail bonus with small-remainder extension.
        if next_item_size > 0 && fresh_post > 0.0 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 2 && fragmentation < 0.5 {
                score -= 7.0 * ((reps as f64).min(4.0) - 1.0) * (0.4 + 0.6 * (1.0 - progress));
                if rem <= 3 {
                    score -= 5.0 * (1.0 - progress);
                }
            }
        }
        // Fresh-bin residual-magnitude guard.
        if fresh_post > 0.35 * cap && remaining_frac > 0.2 && mean_residual * open_bins_count as f64 > 4.0 * cap && fragmentation < 0.45 {
            score += 20.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        // Refuse fresh bins late in the stream when open bins still hold
        // enough aggregate space for the remaining demand.
        if remaining_frac < 0.15 && fresh_post > 0.3 * cap {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.35;
            if open_space > est_need {
                score += 55.0 * (1.0 - remaining_frac / 0.15);
            }
        }
        // MUTATION (gen 55, refined gen 60): mid-stream fresh-bin guard —
        // widen the refusal band and tighten the slack threshold so the
        // guard fires slightly earlier, cutting spurious bin opens.
        if remaining_frac >= 0.15 && remaining_frac < 0.5 && fresh_post > 0.4 * cap && fragmentation > 0.35 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.5;
            if open_space > est_need {
                score += 32.0 * (1.0 - remaining_frac / 0.5);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Layered dead-space rewards (lower post_residual = better).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 4 {
        score -= 280.0 + 4.0 * (4 - post_residual) as f64;
    } else if post_residual <= 10 {
        score -= 60.0 + 3.4 * (10 - post_residual) as f64;
    } else if post_residual <= 22 {
        score -= 13.0 + 1.5 * (22 - post_residual) as f64;
    } else if post_residual <= 32 {
        score -= 5.0 + 0.7 * (32 - post_residual) as f64;
    } else if post_residual <= 48 {
        score -= 1.2 + 0.22 * (48 - post_residual) as f64;
    } else {
        score -= 1.2 - 0.014 * (post_residual as f64 - 48.0);
    }

    // Progress-scaled weighting: tighten late in the stream.
    let w = 0.35 + 0.65 * progress * progress;
    score *= w;

    // Lookahead coupling with the next item.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
            if fitting_bins_count <= 3 {
                score -= 30.0 / fitting_bins_count.max(1) as f64 * (0.5 + 0.5 * (1.0 - progress));
            }
        } else if next_item_size < post_residual {
            let two_step_waste = (post_residual - next_item_size) as f64;
            if two_step_waste <= 8.0 {
                score -= 120.0 - 2.2 * two_step_waste;
            } else {
                score -= 85.0 - 0.4 * two_step_waste;
            }
            if two_step_waste <= 3.0 {
                score -= 45.0;
            }
        } else {
            let miss = (next_item_size - post_residual) as f64;
            score += 0.9 * miss;
            if miss > 28.0 {
                score += 0.45 * (miss - 28.0);
            }
            // Stranded residual weighted by scarcity of alternative fits.
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            if miss <= 10.0 {
                score += (8.0 + 1.0 * (10.0 - miss)) * scarcity * (0.4 + 0.6 * (1.0 - progress));
            }
        }
    }

    // Two-step lookahead: small tails after consuming next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after2 = post_residual - next_item_size;
        if after2 > 0 && after2 <= 8 {
            score -= (36.0 - 2.0 * after2 as f64) * (0.5 + 0.5 * (1.0 - progress));
        }
        // Chainable residual: divisible by next item means repeated absorption.
        if after2 > 0 {
            let chain = after2 % next_item_size.max(1);
            if chain == 0 {
                score -= 24.0 * (1.0 - progress);
            } else if chain <= 3 {
                score -= 10.0 * (1.0 - progress);
            }
        }
    }

    // Chunkable residuals absorb repeated small items.
    if post_residual > 6 && post_residual <= 30 && next_item_size > 0 && next_item_size <= post_residual {
        let reps = post_residual / next_item_size.max(1);
        if reps >= 2 {
            score -= 3.5 * ((reps as f64).min(4.0)) * (1.0 - progress);
        }
    }

    // Waste-density term: penalize unusable residuals relative to stream demand.
    if post_residual > 0 && next_item_size > 0 && fitting_bins_count > 1 {
        let usable = next_item_size <= post_residual || (mean_residual as u32) >= next_item_size;
        if !usable {
            let waste_frac = post_residual as f64 / cap;
            let late = 0.35 + 0.65 * progress;
            score += 9.0 * waste_frac * late;
        }
    }

    // Fill-level momentum: consolidate near-full bins.
    if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 2 {
        let rel = post_residual as f64 / (mean_residual + 1.0);
        if rel < 0.5 {
            score -= 6.0 * (1.0 - rel / 0.5) * (0.4 + 0.6 * (1.0 - progress));
        }
    }

    // Discourage opening a new bin when decent fits exist among open bins.
    if bin_residual == bin_capacity {
        let remaining = if total_items > step_index { total_items - step_index } else { 1 };
        let remaining_frac = remaining as f64 / total_items.max(1) as f64;
        let fresh_post = cap - item_size as f64;
        let fragmentation = (mean_residual / cap) * open_bins_count as f64;
        let huge_item = item_size as f64 > 0.7 * cap;
        let fresh_is_exact = fresh_post <= 4.0;

        if fragmentation > 0.55 || (huge_item && open_bins_count > 4) {
            score -= 66.0 + 46.0 * remaining_frac;
        } else if fresh_is_exact {
            score -= 134.0 + 66.0 * remaining_frac;
        } else {
            score += 420.0 - 80.0 * remaining_frac;
            if fitting_bins_count <= 3 && open_bins_count > 2 {
                score -= 30.0 + 18.0 * remaining_frac;
            }
        }

        // Fresh-bin residual that matches the mean open residual is attractive.
        let fresh_match = (fresh_post - mean_residual).abs() / cap;
        if fresh_match < 0.05 {
            score -= 70.0 * (1.0 - fresh_match / 0.05);
        }
        if remaining_frac < 0.05 && fresh_post > 0.0 && !fresh_is_exact {
            score += 160.0 * (fresh_post / cap);
        }
        if fresh_post > 0.0 && fresh_post <= 22.0 && !fresh_is_exact {
            score -= 26.0 * (1.0 - fresh_post / 22.0);
        }
        if fresh_post > 22.0 && fresh_post <= 40.0 && fragmentation < 0.35 {
            score -= 12.5 * (1.0 - (fresh_post - 22.0) / 18.0);
        }
        if fresh_post > 0.0 && fresh_match < 0.12 && fragmentation < 0.55 {
            score -= 30.0 * (1.0 - fresh_match / 0.12);
        }
        // Lookahead on fresh bin.
        if next_item_size > 0 && fresh_post > 0.0 {
            if (fresh_post as u32) == next_item_size && !((mean_residual as u32) >= next_item_size) && fitting_bins_count <= 2 {
                score -= 52.0 * (1.0 - progress);
            }
            if (fresh_post as u32) < next_item_size && mean_residual > next_item_size as f64 {
                score += 21.0 * (1.0 - progress);
            }
            let chain_post = fresh_post - next_item_size as f64;
            if chain_post > 0.0 && chain_post <= 4.0 {
                score -= 32.0 * (1.0 - chain_post / 4.0) * (0.5 + 0.5 * (1.0 - progress));
            } else if chain_post > 4.0 && chain_post <= 10.0 {
                score -= 9.0 * (1.0 - (chain_post - 4.0) / 6.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // Refuse fresh bins late when open slack can absorb remaining demand.
        if remaining_frac < 0.15 && fresh_post > 0.3 * cap {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.35;
            if open_space > est_need {
                score += 55.0 * (1.0 - remaining_frac / 0.15);
            }
        }
        // Mid-stream fresh-bin guard.
        if remaining_frac >= 0.15 && remaining_frac < 0.45 && fresh_post > 0.4 * cap && fragmentation > 0.4 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.45;
            if open_space > est_need {
                score += 28.0 * (1.0 - remaining_frac / 0.45);
            }
        }
        // Fresh-bin reusable-tail bonus.
        if next_item_size > 0 && fresh_post > 0.0 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 2 && fragmentation < 0.5 {
                score -= 7.0 * ((reps as f64).min(4.0) - 1.0) * (0.4 + 0.6 * (1.0 - progress));
                if rem <= 3 {
                    score -= 5.0 * (1.0 - progress);
                }
            }
        }
    }

    // Mild preference for bins whose residual is close to mean residual (keeps homogeneity).
    if bin_residual < bin_capacity {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
        // Residual-vs-mean harmony bonus.
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 1 {
            let harmony = (post_residual as f64 - mean_residual).abs() / cap;
            if harmony < 0.08 {
                score -= 8.0 * (1.0 - harmony / 0.08) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // Exact fills of nearly-full bins get extra reward.
        if post_residual == 0 {
            score -= 40.0 * (1.0 - bin_residual as f64 / cap) * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post-fit residual (quarters of capacity) ---
    let quarter = (bin_capacity / 4).max(1);
    let residual_class = (post_residual / quarter) as f64; // 0..4 integer division tier
    // Dead-space penalty grows super-linearly with the harmonic class,
    // but tiny residuals (class 0) are pure wins.
    score += 12.0 * residual_class * residual_class;

    // --- Perfect / near-perfect fit rewards ---
    if post_residual == 0 {
        score -= 40.0; // exact closure
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // --- Lookahead coupling: does the next item fit the post residual? ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Chain potential: reward proportionally to how well next item nests
            let nest = post_residual as f64 - next_item_size as f64;
            score -= 8.0 * (1.0 - nest / bin_capacity as f64);
        } else {
            // Next item cannot use the leftover: leftover is likely dead space
            score += 10.0 + 0.15 * post_residual as f64;
        }
    }

    // --- Last-chance bin: strongly prefer using the only fitting bin ---
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // --- New-bin candidate logic ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when no open bin fits well:
        // if several bins fit, opening a new one wastes consolidation potential.
        if fitting_bins_count >= 1 {
            score += 30.0 + 10.0 * (fitting_bins_count as f64);
        } else {
            score += 5.0;
        }
        // Early in the stream, spreading out is cheaper than fragmenting later
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 15.0 * (1.0 - progress);
    }

    // --- Mean-residual pressure: avoid dumping into bins far from the mean
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // --- Mid-stream consolidation: fewer open bins is better late ---
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 3.0 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Layered dead-space ladder (lower post_residual = better).
    if post_residual == 0 {
        score -= 980.0;
    } else if post_residual <= 4 {
        score -= 250.0 + 4.2 * (4 - post_residual) as f64;
    } else if post_residual <= 10 {
        score -= 64.0 + 3.6 * (10 - post_residual) as f64;
    } else if post_residual <= 22 {
        score -= 13.5 + 1.5 * (22 - post_residual) as f64;
    } else if post_residual <= 32 {
        score -= 5.0 + 0.7 * (32 - post_residual) as f64;
    } else if post_residual <= 48 {
        score -= 1.2 + 0.22 * (48 - post_residual) as f64;
    } else {
        score -= 1.2 - 0.014 * (post_residual as f64 - 48.0);
    }

    // Progress-scaled weighting: tighten late in the stream.
    let w = 0.33 + 0.67 * progress * progress;
    score *= w;

    // Lookahead coupling with the next item.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if next_item_size < post_residual {
            let two_step_waste = (post_residual - next_item_size) as f64;
            if two_step_waste <= 8.0 {
                score -= 135.0 - 2.3 * two_step_waste;
            } else {
                score -= 72.0 - 0.58 * two_step_waste;
            }
            if two_step_waste <= 3.0 {
                score -= 48.0;
            }
        } else {
            let miss = (next_item_size - post_residual) as f64;
            score += 0.95 * miss;
            if miss > 26.0 {
                score += 0.55 * (miss - 26.0);
            }
        }
    }

    // Slack-based scarcity boost when the next item fits here.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
        let boost = 36.0 + 26.0 * scarcity;
        score -= boost * (1.0 - slack / cap) * (0.6 + 0.4 * (1.0 - progress));
        if fitting_bins_count <= 2 {
            score -= 15.0 * (1.0 - slack / cap);
        }
        if slack == 0.0 {
            score -= 20.0 * (1.0 - progress);
        }
    }

    if bin_residual != bin_capacity {
        let dead = (bin_residual - item_size) as f64;
        let dead_ratio = dead / cap;
        if dead_ratio > 0.5 && fitting_bins_count > 1 {
            score += 10.5 * (dead_ratio - 0.5) * (1.0 - progress);
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
            && mean_residual > 0.0 && (mean_residual as u32) >= next_item_size {
            score += 12.0;
        }
        if post_residual > 12 && post_residual < 40 && next_item_size > post_residual {
            let orphan = (post_residual as f64 - 12.0) / 28.0;
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            score += 17.0 * orphan * scarcity * (0.5 + 0.5 * (1.0 - progress));
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let chain = post_residual % next_item_size.max(1);
            if chain == 0 {
                score -= 26.0 * (1.0 - progress);
            } else if chain <= 3 {
                score -= 11.0 * (1.0 - progress);
            }
        }
        // Stranded residual: too small for next item, weighted by scarcity.
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            let stranded = (next_item_size - post_residual) as f64;
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            if stranded <= 10.0 {
                score += (8.5 + 1.1 * (10.0 - stranded)) * scarcity * (0.4 + 0.6 * (1.0 - progress));
            } else {
                let proximity = 1.0 - (stranded - 10.0).min(cap) / cap;
                score += 3.2 * proximity * scarcity * (1.0 - progress);
            }
        }
        // Dead-space dominance penalty when tight fits exist elsewhere.
        if dead_ratio > 0.35 && fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score += 7.5 * (dead_ratio - 0.35) * tightness * (1.0 - progress);
        }
        // Penalize leaving a residual awkwardly below the mean open-bin residual.
        if post_residual > 0 && mean_residual > 0.0 {
            let gap = mean_residual - post_residual as f64;
            if gap > 0.0 && gap < 0.15 * cap && fitting_bins_count > 2 {
                score += 4.8 * (gap / (0.15 * cap)) * (1.0 - progress);
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size.max(1) && fitting_bins_count > 2 {
            score -= 6.5 * (1.0 - progress);
        }
        // Strong extra reward for exact fills of nearly-full bins.
        if post_residual == 0 && bin_residual < bin_capacity {
            score -= 42.0 * (1.0 - bin_residual as f64 / cap) * (1.0 - progress);
        }
        // Residual-vs-mean harmony.
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 1 {
            let harmony = (post_residual as f64 - mean_residual).abs() / cap;
            if harmony < 0.08 {
                score -= 9.0 * (1.0 - harmony / 0.08) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // Chunkable residuals absorb repeated small items.
        if post_residual > 6 && post_residual <= 30 && next_item_size > 0 && next_item_size <= post_residual {
            let reps = post_residual / next_item_size.max(1);
            if reps >= 2 {
                score -= 3.5 * (reps as f64).min(4.0) * (1.0 - progress);
            }
        }
        // Two-step lookahead.
        if next_item_size > 0 && post_residual > next_item_size {
            let after_next = post_residual - next_item_size;
            if after_next > 0 && after_next <= 12 {
                let tail = after_next as f64;
                score -= (14.0 - 0.9 * tail) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // Penalize tiny dead-zone residuals unusable by the next item.
        if post_residual > 0 && post_residual < 6 && next_item_size > post_residual {
            score += 6.0 * (1.0 - progress);
        }
        // Three-step horizon.
        if next_item_size > 0 && post_residual > next_item_size {
            let after_next = (post_residual - next_item_size) as f64;
            if after_next > 8.0 && after_next <= 16.0 && progress < 0.85 {
                let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
                score -= (4.0 + 3.0 * scarcity) * (1.0 - (after_next - 8.0) / 8.0) * (1.0 - progress);
            }
        }
        // Overshoot spreading refinement.
        if post_residual > 0 && next_item_size > 0 && fitting_bins_count > 3 {
            let overshoot = post_residual.saturating_sub(next_item_size) as f64;
            if overshoot > 16.0 {
                score += 1.6 * ((overshoot - 16.0) / cap).min(0.25) * (1.0 - progress);
            }
        }
        // Dead-ratio gradient with residual-magnitude term, scaled by aggregate open slack.
        if fitting_bins_count > 1 && dead_ratio > 0.08 && post_residual > 0 {
            let scarcity = 1.0 / (fitting_bins_count as f64);
            let comp_slack = (mean_residual / cap).min(1.0);
            score += 6.5 * (dead_ratio - 0.08) * scarcity * comp_slack * (0.5 + 0.5 * (1.0 - progress));
            score += 2.2 * (dead / cap) * scarcity * comp_slack * (1.0 - progress);
        }
        // Residual-magnitude tiebreaker toward mean.
        if fitting_bins_count > 2 && post_residual > 0 && mean_residual > 0.0 {
            let dev = ((post_residual as f64 - mean_residual).abs() / cap).min(0.4);
            score += 5.0 * dev * (1.0 - progress);
        }
        // Exact-fit ladder on round residuals.
        if post_residual > 0 && post_residual % 10 == 0 && post_residual <= 60 && next_item_size > 0 && next_item_size <= post_residual {
            score -= 4.0 * (1.0 - progress) * (1.0 - post_residual as f64 / 120.0);
        }
        // Scarcity-weighted perfect-fit extension.
        if next_item_size > 0 && post_residual == next_item_size && fitting_bins_count <= 3 {
            score -= 30.0 / fitting_bins_count.max(1) as f64 * (0.5 + 0.5 * (1.0 - progress));
        }
        // MUTATION (gen 55, refined gen 61): waste-density term — penalize
        // placements whose leftover residual is unusable relative to stream
        // demand; strengthen mid-stream so residual space consolidates into
        // reusable magnitudes before the tail.
        if post_residual > 0 && next_item_size > 0 && fitting_bins_count > 1 {
            let usable = next_item_size <= post_residual
                || (mean_residual as u32) >= next_item_size;
            if !usable {
                let waste_frac = post_residual as f64 / cap;
                let late = 0.25 + 0.75 * progress;
                score += 11.5 * waste_frac * late;
            }
        }
        // MUTATION (gen 55, refined gen 61): fill-level momentum — reward
        // consolidating near-full bins; slightly wider band to pull more
        // residual mass into few bins and reduce residual variance.
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 2 {
            let rel = post_residual as f64 / (mean_residual + 1.0);
            if rel < 0.55 {
                score -= 7.0 * (1.0 - rel / 0.55) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        // MUTATION (gen 61): residual-variance damper — when this placement
        // would leave a residual far above the mean while abundant small
        // space exists elsewhere, prefer spreading the load evenly so
        // aggregate open slack stays usable for large late items.
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 2 && next_item_size > 0 {
            let dev_up = post_residual as f64 - mean_residual;
            if dev_up > 0.18 * cap && mean_residual >= next_item_size as f64 {
                score += 5.5 * ((dev_up / cap) - 0.18).min(0.3) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // MUTATION (gen 61): pair-completion bonus — reward placements that
        // leave exactly room for the next item plus a small item, i.e. a
        // two-item chain finish, which directly removes dead space.
        if next_item_size > 0 && post_residual > next_item_size {
            let tail = post_residual - next_item_size;
            if tail >= 1 && tail <= 14 {
                score -= (10.0 - 0.45 * tail as f64) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
    } else {
        // NEW-BIN CANDIDATE branch.
        let fragmentation = (mean_residual / cap) * open_bins_count as f64;
        let huge_item = item_size as f64 > 0.7 * cap;
        let remaining = if total_items > step_index { total_items - step_index } else { 1 };
        let remaining_frac = remaining as f64 / total_items.max(1) as f64;
        let fresh_post = cap - item_size as f64;
        let fresh_is_exact = fresh_post <= 4.0 && fresh_post >= 0.0;

        if fragmentation > 0.55 || (huge_item && open_bins_count > 4) {
            score -= 66.0 + 46.0 * remaining_frac;
        } else if fresh_is_exact {
            score -= 134.0 + 66.0 * remaining_frac;
        } else {
            score += 400.0 - 82.0 * remaining_frac;
            if fitting_bins_count <= 3 && open_bins_count > 2 {
                score -= 30.0 + 18.0 * remaining_frac;
            }
        }

        let fresh_match = (fresh_post - mean_residual).abs() / cap;
        if fresh_match < 0.05 {
            score -= 76.0 * (1.0 - fresh_match / 0.05);
        }
        if remaining_frac < 0.05 && fresh_post > 0.0 && !fresh_is_exact {
            score += 160.0 * (fresh_post / cap);
        }
        if fresh_post > 0.0 && fresh_post <= 22.0 && !fresh_is_exact {
            score -= 26.0 * (1.0 - fresh_post / 22.0);
        }
        if fresh_post > 22.0 && fresh_post <= 40.0 && fragmentation < 0.35 {
            score -= 12.5 * (1.0 - (fresh_post - 22.0) / 18.0);
        }
        if fresh_post > 0.0 && fresh_match < 0.12 && fragmentation < 0.55 {
            score -= 30.0 * (1.0 - fresh_match / 0.12);
        }
        if next_item_size > 0 && fresh_post > 0.0 {
            let fresh_exact_next = (fresh_post as u32) == next_item_size;
            let open_can_next = mean_residual >= next_item_size as f64;
            if fresh_exact_next && !open_can_next && fitting_bins_count <= 2 {
                score -= 52.0 * (1.0 - progress);
            }
            if (fresh_post as u32) < next_item_size && mean_residual > next_item_size as f64 {
                score += 21.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && fresh_post > next_item_size as f64 {
            let chain_post = fresh_post - next_item_size as f64;
            if chain_post <= 4.0 {
                score -= 34.0 * (1.0 - chain_post / 4.0) * (0.5 + 0.5 * (1.0 - progress));
            } else if chain_post <= 10.0 {
                score -= 9.5 * (1.0 - (chain_post - 4.0) / 6.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        if remaining_frac < 0.12 && fresh_post > 0.0 && !fresh_is_exact && mean_residual * open_bins_count as f64 > 3.0 * cap {
            score += 42.0 * (1.0 - remaining_frac / 0.12);
        }
        if fitting_bins_count == 1 && fresh_post > 0.0 && next_item_size > 0 {
            let stranded_here = bin_capacity.saturating_sub(item_size);
            let would_strand = stranded_here < next_item_size;
            if would_strand && stranded_here > 0 && stranded_here <= 8 {
                score -= 32.0 * (1.0 - progress);
            }
        }
        let open_capacity = mean_residual * open_bins_count as f64;
        let per_item_need = cap * 0.5;
        if remaining_frac > 0.25 && open_capacity < per_item_need * open_bins_count.max(1) as f64 * 0.5 {
            score -= 18.0 * (1.0 - progress);
        }
        if next_item_size > 0 && fresh_post > next_item_size as f64 {
            let after_next = fresh_post - next_item_size as f64;
            if after_next > 0.0 && after_next <= 8.0 && fragmentation < 0.5 {
                score -= 20.0 * (1.0 - after_next / 8.0) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        if next_item_size > 0 && fresh_post > 0.0 && (fresh_post as u32) < next_item_size {
            let slack_total = mean_residual * open_bins_count as f64;
            if slack_total > 2.0 * cap {
                score += 26.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && (fresh_post as u32) == next_item_size && fragmentation > 0.3 {
            score -= 44.0 * (0.5 + 0.5 * (1.0 - progress));
        }
        if fresh_post > 0.5 * cap && mean_residual < 0.2 * cap && remaining_frac > 0.3 && open_bins_count > 3 {
            score += 24.0 * (fresh_post / cap - 0.5) * 2.0 * (1.0 - progress);
        }
        if fitting_bins_count <= 1 && fresh_post > 0.45 * cap && next_item_size > 0 {
            let reachable = (next_item_size as f64 / fresh_post).min(1.0);
            if reachable < 0.5 {
                score += 18.0 * (0.5 - reachable) * (1.0 - progress);
            }
        }
        // Fresh-bin reusable-tail bonus with small-remainder extension.
        if next_item_size > 0 && fresh_post > 0.0 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 2 && fragmentation < 0.5 {
                score -= 7.0 * ((reps as f64).min(4.0) - 1.0) * (0.4 + 0.6 * (1.0 - progress));
                if rem <= 3 {
                    score -= 5.0 * (1.0 - progress);
                }
            }
        }
        // Fresh-bin residual-magnitude guard.
        if fresh_post > 0.35 * cap && remaining_frac > 0.2 && mean_residual * open_bins_count as f64 > 4.0 * cap && fragmentation < 0.45 {
            score += 20.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        // Refuse fresh bins late in the stream when open bins still hold
        // enough aggregate space for the remaining demand.
        if remaining_frac < 0.15 && fresh_post > 0.3 * cap {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.35;
            if open_space > est_need {
                score += 55.0 * (1.0 - remaining_frac / 0.15);
            }
        }
        // MUTATION (gen 55, tuned gen 61): mid-stream fresh-bin guard —
        // widen the refusal band and lower the need estimate so spurious
        // opens are suppressed further into the stream.
        if remaining_frac >= 0.15 && remaining_frac < 0.50 && fresh_post > 0.38 * cap && fragmentation > 0.35 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.40;
            if open_space > est_need {
                score += 32.0 * (1.0 - remaining_frac / 0.50);
            }
        }
        // MUTATION (gen 61): fresh-bin consolidation bonus — when aggregate
        // open slack is small relative to remaining demand, opening a bin
        // whose fresh residual can chain with the next item is valuable;
        // reward it to avoid future forced opens with stranded space.
        if next_item_size > 0 && fresh_post > next_item_size as f64 && remaining_frac > 0.3 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (next_item_size as f64) * 0.5;
            if open_space < est_need {
                let chain_tail = fresh_post - next_item_size as f64;
                if chain_tail <= 10.0 {
                    score -= 14.0 * (1.0 - chain_tail / 10.0) * (1.0 - progress);
                }
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=10) are heavily penalized
    if post_residual > 0 && post_residual <= 10 {
        score += 40.0 * (1.0 + (10 - post_residual) as f64 / 10.0);
    } else if post_residual > 10 && post_residual < 20 {
        // medium-dead zone: mildly penalized since few items fit
        score += 6.0;
    } else if post_residual == 0 {
        // perfect fit: strong reward
        score -= 30.0;
    }

    // Reward tight fits relative to residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill_ratio;

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 5.0;
        } else {
            // next item cannot use this residual: penalize proportional dead space
            score += 3.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: discourage spreading across many bins
    score += 0.8 * open_bins_count as f64;

    // Mean residual coupling: prefer bins whose residual is near the mean (balanced usage)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / 8.0;
        score += 12.0 + 10.0 * pressure;
        if fitting_bins_count == 0 {
            score -= 50.0; // nothing fits anywhere: must open new bin
        }
    }

    // Late-stream consolidation: prefer filling existing bins as stream ends
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Layered dead-space rewards (lower post_residual = better).
    if post_residual == 0 {
        score -= 980.0;
    } else if post_residual <= 2 {
        score -= 620.0 + 40.0 * (2 - post_residual) as f64;
    } else if post_residual <= 4 {
        score -= 260.0 + 6.0 * (4 - post_residual) as f64;
    } else if post_residual <= 10 {
        score -= 64.0 + 3.8 * (10 - post_residual) as f64;
    } else if post_residual <= 22 {
        score -= 13.5 + 1.6 * (22 - post_residual) as f64;
    } else if post_residual <= 32 {
        score -= 5.0 + 0.75 * (32 - post_residual) as f64;
    } else if post_residual <= 48 {
        score -= 1.2 + 0.24 * (48 - post_residual) as f64;
    } else {
        score -= 1.2 - 0.015 * (post_residual as f64 - 48.0);
    }

    // Progress-scaled weighting: tighten late in the stream.
    let w = 0.33 + 0.67 * progress * progress;
    score *= w;

    // Lookahead coupling with the next item.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if next_item_size < post_residual {
            let two_step_waste = (post_residual - next_item_size) as f64;
            if two_step_waste <= 8.0 {
                score -= 138.0 - 2.3 * two_step_waste;
            } else {
                score -= 74.0 - 0.6 * two_step_waste;
            }
            if two_step_waste <= 3.0 {
                score -= 50.0;
            }
        } else {
            let miss = (next_item_size - post_residual) as f64;
            score += 0.95 * miss;
            if miss > 26.0 {
                score += 0.55 * (miss - 26.0);
            }
        }
    }

    // Slack-based scarcity boost when the next item fits here.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
        let boost = 36.0 + 26.0 * scarcity;
        score -= boost * (1.0 - slack / cap) * (0.6 + 0.4 * (1.0 - progress));
        if fitting_bins_count <= 2 {
            score -= 15.0 * (1.0 - slack / cap);
        }
        if slack == 0.0 {
            score -= 20.0 * (1.0 - progress);
        }
    }

    if bin_residual != bin_capacity {
        let dead = (bin_residual - item_size) as f64;
        let dead_ratio = dead / cap;
        if dead_ratio > 0.5 && fitting_bins_count > 1 {
            score += 10.5 * (dead_ratio - 0.5) * (1.0 - progress);
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
            && mean_residual > 0.0 && (mean_residual as u32) >= next_item_size {
            score += 12.0;
        }
        if post_residual > 12 && post_residual < 40 && next_item_size > post_residual {
            let orphan = (post_residual as f64 - 12.0) / 28.0;
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            score += 17.0 * orphan * scarcity * (0.5 + 0.5 * (1.0 - progress));
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let chain = post_residual % next_item_size.max(1);
            if chain == 0 {
                score -= 26.0 * (1.0 - progress);
            } else if chain <= 3 {
                score -= 11.0 * (1.0 - progress);
            }
        }
        // Stranded residual: too small for next item, weighted by scarcity.
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            let stranded = (next_item_size - post_residual) as f64;
            if stranded <= 10.0 {
                let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
                score += (8.5 + 1.1 * (10.0 - stranded)) * scarcity * (0.4 + 0.6 * (1.0 - progress));
            } else {
                let proximity = 1.0 - (stranded - 10.0).min(bin_capacity) as f64 / cap;
                let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
                score += 3.2 * proximity * scarcity * (1.0 - progress);
            }
        }
        // Dead-space dominance penalty when tight fits exist elsewhere.
        if dead_ratio > 0.35 && fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score += 7.5 * (dead_ratio - 0.35) * tightness * (1.0 - progress);
        }
        // Penalize leaving a residual awkwardly below the mean open-bin residual.
        if post_residual > 0 && mean_residual > 0.0 {
            let gap = mean_residual - post_residual as f64;
            if gap > 0.0 && gap < 0.15 * cap && fitting_bins_count > 2 {
                score += 4.8 * (gap / (0.15 * cap)) * (1.0 - progress);
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size.max(1) && fitting_bins_count > 2 {
            score -= 6.5 * (1.0 - progress);
        }
        // Strong extra reward for exact fills of nearly-full bins.
        if post_residual == 0 && bin_residual < bin_capacity {
            score -= 42.0 * (1.0 - bin_residual as f64 / cap) * (1.0 - progress);
        }
        // Residual-vs-mean harmony.
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 1 {
            let harmony = (post_residual as f64 - mean_residual).abs() / cap;
            if harmony < 0.08 {
                score -= 9.0 * (1.0 - harmony / 0.08) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // Chunkable residuals absorb repeated small items.
        if post_residual > 6 && post_residual <= 30 && next_item_size > 0 && next_item_size <= post_residual {
            let reps = post_residual / next_item_size.max(1);
            if reps >= 2 {
                score -= 3.5 * (reps as f64).min(4.0) * (1.0 - progress);
            }
        }
        // Two-step lookahead — reward leaving a residual that can exactly
        // absorb next_item followed by another small item.
        if next_item_size > 0 && post_residual > next_item_size {
            let after_next = post_residual - next_item_size;
            if after_next > 0 && after_next <= 12 {
                let tail = after_next as f64;
                score -= (14.0 - 0.9 * tail) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // Penalize tiny dead-zone residuals unusable by the next item.
        if post_residual > 0 && post_residual < 6 && next_item_size > post_residual {
            score += 6.0 * (1.0 - progress);
        }
        // Three-step horizon — residuals that can absorb next_item plus a
        // mid-size tail remain valuable when bins are scarce.
        if next_item_size > 0 && post_residual > next_item_size {
            let after_next = (post_residual - next_item_size) as f64;
            if after_next > 8.0 && after_next <= 16.0 && progress < 0.85 {
                let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
                score -= (4.0 + 3.0 * scarcity) * (1.0 - (after_next - 8.0) / 8.0) * (1.0 - progress);
            }
        }
        // Overshoot spreading refinement.
        if post_residual > 0 && next_item_size > 0 && fitting_bins_count > 3 {
            let overshoot = post_residual.saturating_sub(next_item_size) as f64;
            if overshoot > 16.0 {
                score += 1.6 * ((overshoot - 16.0) / cap).min(0.25) * 100.0 * 0.01 * (1.0 - progress);
            }
        }
        // Dead-ratio gradient tightened: absolute dead space punished
        // alongside ratio.
        if fitting_bins_count > 1 && dead_ratio > 0.08 && post_residual > 0 {
            let scarcity = 1.0 / (fitting_bins_count as f64);
            let comp_slack = (mean_residual / cap).min(1.0);
            score += 6.5 * (dead_ratio - 0.08) * scarcity * comp_slack * (0.5 + 0.5 * (1.0 - progress));
            score += 2.2 * (dead / cap) * scarcity * comp_slack * (1.0 - progress);
        }
        // Residual-magnitude tiebreaker: among similar dead ratios, prefer
        // the residual closest to the mean, consolidating usable space.
        if fitting_bins_count > 2 && post_residual > 0 && mean_residual > 0.0 {
            let dev = ((post_residual as f64 - mean_residual).abs() / cap).min(0.4);
            score += 5.0 * dev * (1.0 - progress);
        }
        // Exact-fit ladder — round residuals are reusable by common sizes.
        if post_residual > 0 && post_residual % 10 == 0 && post_residual <= 60 && next_item_size > 0 && next_item_size <= post_residual {
            score -= 4.0 * (1.0 - progress) * (1.0 - post_residual as f64 / 120.0);
        }
        // Triple-fill planning — post_residual hosts next_item plus a small
        // companion; reward when bins are scarce.
        if next_item_size > 0 && post_residual > next_item_size && fitting_bins_count <= 3 {
            let tail = post_residual - next_item_size;
            if tail >= 1 && tail <= 12 {
                score -= 9.0 * (1.0 - tail as f64 / 12.0) * (1.0 - progress);
            }
        }
        // Protect the unique best fit for next_item when many bins are open.
        if next_item_size > 0 && post_residual == next_item_size && open_bins_count > 5 {
            score -= 14.0 * (0.4 + 0.6 * (1.0 - progress));
        }
        // Mid-band residual discount — 16..=28 residuals are highly reusable.
        if post_residual >= 16 && post_residual <= 28 && progress < 0.7 && fitting_bins_count > 1 {
            score -= 7.0 * (1.0 - (post_residual - 16) as f64 / 12.0) * (0.5 + 0.5 * progress);
        }
        // Dead-space compaction coupling — reward consolidation near the mean.
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 1 {
            let match_mean = 1.0 - ((post_residual as f64 - mean_residual).abs() / cap);
            if match_mean > 0.9 {
                score -= 5.0 * (match_mean - 0.9) * 10.0 * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // Waste-avoidance gradient — penalize dead space beyond next item's need.
        if next_item_size > 0 && post_residual > next_item_size && fitting_bins_count > 1 {
            let excess = (post_residual - next_item_size) as f64;
            if excess > 12.0 {
                score += 1.8 * ((excess - 12.0) / cap).min(0.3) * 100.0 * 0.01 * (1.0 - progress) * (fitting_bins_count as f64).min(4.0);
            }
        }
        // Tight-fit scarcity escalation.
        if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 4 {
            let gap_after = (post_residual - next_item_size) as f64;
            let urgency = (4.0 - fitting_bins_count as f64) / 3.0;
            score -= 10.0 * urgency * (1.0 - gap_after / cap) * (0.5 + 0.5 * (1.0 - progress));
        }
        // Mean-residual drain coupling.
        if post_residual > 0 && mean_residual > 0.0 && open_bins_count > 3 {
            let below = mean_residual - post_residual as f64;
            if below > 0.25 * cap && progress < 0.75 {
                score += 6.0 * (below / cap) * (1.0 - progress);
            }
        }
        // Squeeze-escalation ladder — when very few bins fit the next item,
        // escalate the reward for bins whose post residual matches the next
        // item exactly or leaves a tiny tail.
        if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 6 {
            let tail = post_residual - next_item_size;
            let urgency = (6.0 - fitting_bins_count as f64) / 5.0;
            if tail == 0 {
                score -= 22.0 * urgency * (1.0 - progress);
            } else if tail <= 2 {
                score -= 9.0 * urgency * (1.0 - tail as f64 / 2.0) * (1.0 - progress);
            }
        }
        // Stranded-pair avoidance — if placing here strands a residual
        // smaller than next_item while another bin's post residual would
        // exactly host next_item, penalize.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size
            && mean_residual > 0.0 && (mean_residual as u32) >= next_item_size && fitting_bins_count > 1 {
            score += 7.0 * (1.0 - progress);
        }
        // COMBINED MUTATION (gen 61) A: scarcity-weighted perfect-fit
        // extension — preserve next-item-shaped pockets when bins are scarce.
        if next_item_size > 0 && post_residual == next_item_size && fitting_bins_count <= 3 {
            score -= 30.0 / fitting_bins_count.max(1) as f64 * (0.5 + 0.5 * (1.0 - progress));
        }
        // COMBINED MUTATION (gen 61) B: waste-density term — penalize
        // placements whose leftover residual is unusable relative to the
        // remaining stream demand, pushing residual space toward reusable
        // magnitudes.
        if post_residual > 0 && next_item_size > 0 && fitting_bins_count > 1 {
            let usable = next_item_size <= post_residual
                || (mean_residual as u32) >= next_item_size;
            if !usable {
                let waste_frac = post_residual as f64 / cap;
                let late = 0.35 + 0.65 * progress;
                score += 9.0 * waste_frac * late;
            }
        }
        // COMBINED MUTATION (gen 61) C: fill-level momentum — reward placing
        // into bins whose residual is already small relative to mean,
        // consolidating near-full bins to free larger residuals elsewhere.
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 2 {
            let rel = post_residual as f64 / (mean_residual + 1.0);
            if rel < 0.5 {
                score -= 6.0 * (1.0 - rel / 0.5) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
    } else {
        // NEW-BIN CANDIDATE branch.
        let fragmentation = (mean_residual / cap) * open_bins_count as f64;
        let huge_item = item_size as f64 > 0.7 * cap;
        let remaining = if total_items > step_index { total_items - step_index } else { 1 };
        let remaining_frac = remaining as f64 / total_items.max(1) as f64;
        let fresh_post = cap - item_size as f64;
        let fresh_is_exact = fresh_post <= 4.0 && fresh_post >= 0.0;

        if fragmentation > 0.55 || (huge_item && open_bins_count > 4) {
            score -= 66.0 + 46.0 * remaining_frac;
        } else if fresh_is_exact {
            score -= 134.0 + 66.0 * remaining_frac;
        } else {
            score += 400.0 - 82.0 * remaining_frac;
            if fitting_bins_count <= 3 && open_bins_count > 2 {
                score -= 30.0 + 18.0 * remaining_frac;
            }
        }

        let fresh_match = (fresh_post - mean_residual).abs() / cap;
        if fresh_match < 0.05 {
            score -= 76.0 * (1.0 - fresh_match / 0.05);
        }
        if remaining_frac < 0.05 && fresh_post > 0.0 && !fresh_is_exact {
            score += 160.0 * (fresh_post / cap);
        }
        if fresh_post > 0.0 && fresh_post <= 22.0 && !fresh_is_exact {
            score -= 26.0 * (1.0 - fresh_post / 22.0);
        }
        if fresh_post > 22.0 && fresh_post <= 40.0 && fragmentation < 0.35 {
            score -= 12.5 * (1.0 - (fresh_post - 22.0) / 18.0);
        }
        if fresh_post > 0.0 && fresh_match < 0.12 && fragmentation < 0.55 {
            score -= 30.0 * (1.0 - fresh_match / 0.12);
        }
        if next_item_size > 0 && fresh_post > 0.0 {
            let fresh_exact_next = (fresh_post as u32) == next_item_size;
            let open_can_next = mean_residual >= next_item_size as f64;
            if fresh_exact_next && !open_can_next && fitting_bins_count <= 2 {
                score -= 52.0 * (1.0 - progress);
            }
            if (fresh_post as u32) < next_item_size && mean_residual > next_item_size as f64 {
                score += 21.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && fresh_post > next_item_size as f64 {
            let chain_post = fresh_post - next_item_size as f64;
            if chain_post <= 4.0 {
                score -= 34.0 * (1.0 - chain_post / 4.0) * (0.5 + 0.5 * (1.0 - progress));
            } else if chain_post <= 10.0 {
                score -= 9.5 * (1.0 - (chain_post - 4.0) / 6.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        if remaining_frac < 0.12 && fresh_post > 0.0 && !fresh_is_exact && mean_residual * open_bins_count as f64 > 3.0 * cap {
            score += 42.0 * (1.0 - remaining_frac / 0.12);
        }
        // When only one open bin can fit and this item would leave a tiny
        // stranded residual there, opening a fresh bin is often better.
        if fitting_bins_count == 1 && fresh_post > 0.0 && next_item_size > 0 {
            let stranded_here = bin_capacity.saturating_sub(item_size);
            let would_strand = stranded_here < next_item_size;
            if would_strand && stranded_here > 0 && stranded_here <= 8 {
                score -= 32.0 * (1.0 - progress);
            }
        }
        // Open bins collectively nearly exhausted → keep density high.
        let open_capacity = mean_residual * open_bins_count as f64;
        let per_item_need = cap * 0.5;
        if remaining_frac > 0.25 && open_capacity < per_item_need * open_bins_count.max(1) as f64 * 0.5 {
            score -= 18.0 * (1.0 - progress);
        }
        // Fresh-bin chain quality.
        if next_item_size > 0 && fresh_post > next_item_size as f64 {
            let after_next = fresh_post - next_item_size as f64;
            if after_next > 0.0 && after_next <= 8.0 && fragmentation < 0.5 {
                score -= 20.0 * (1.0 - after_next / 8.0) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        // Avoid fresh bins whose residual is smaller than next_item when
        // open bins collectively have plenty of slack.
        if next_item_size > 0 && fresh_post > 0.0 && (fresh_post as u32) < next_item_size {
            let slack_total = mean_residual * open_bins_count as f64;
            if slack_total > 2.0 * cap {
                score += 26.0 * (1.0 - progress);
            }
        }
        // Fresh-bin exact-next bonus when fragmentation is moderate.
        if next_item_size > 0 && (fresh_post as u32) == next_item_size && fragmentation > 0.3 {
            score -= 44.0 * (0.5 + 0.5 * (1.0 - progress));
        }
        // Refuse very loose fresh bins when mean residual is tiny but many
        // bins are open — consolidation beats expansion.
        if fresh_post > 0.5 * cap && mean_residual < 0.2 * cap && remaining_frac > 0.3 && open_bins_count > 3 {
            score += 24.0 * (fresh_post / cap - 0.5) * 2.0 * (1.0 - progress);
        }
        // Single-fit guard.
        if fitting_bins_count <= 1 && fresh_post > 0.45 * cap && next_item_size > 0 {
            let reachable = (next_item_size as f64 / fresh_post).min(1.0);
            if reachable < 0.5 {
                score += 18.0 * (0.5 - reachable) * (1.0 - progress);
            }
        }
        // Fresh-bin reusable-tail bonus — residual a multiple of next_item.
        if next_item_size > 0 && fresh_post > 0.0 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 2 && fragmentation < 0.5 {
                score -= 7.0 * ((reps as f64).min(4.0) - 1.0) * (0.4 + 0.6 * (1.0 - progress));
                if rem <= 3 {
                    score -= 5.0 * (1.0 - progress);
                }
            }
        }
        // Fresh-bin two-item plan.
        if next_item_size > 0 && fitting_bins_count <= 2 && fresh_post > next_item_size as f64 {
            let tail = fresh_post - next_item_size as f64;
            if tail > 0.0 && tail <= 6.0 {
                score -= 28.0 * (1.0 - tail / 6.0) * (1.0 - progress);
            }
        }
        // Late-stream consolidation — prefer filling existing bins near the
        // end unless the fresh fit is near-exact.
        if progress > 0.8 && !fresh_is_exact && fresh_post > 8.0 && fitting_bins_count >= 1 {
            score += 20.0 * (progress - 0.8) / 0.2 * (fresh_post / cap);
        }
        // Aggregate-slack conservation — refuse a loose fresh bin when total
        // open slack already exceeds the expected need of remaining items.
        if remaining_frac > 0.15 && !fresh_is_exact && fresh_post > 0.35 * cap {
            let expected_need = remaining as f64 * (cap * 0.45);
            if open_capacity > expected_need {
                score += 22.0 * ((open_capacity - expected_need) / expected_need).min(1.0) * (1.0 - progress);
            }
        }
        // Fresh-bin scarcity gate.
        if fitting_bins_count == 0 && fresh_post > 0.0 {
            score -= 55.0 * (1.0 - fresh_post / cap) * (0.4 + 0.6 * (1.0 - progress));
        }
        // Fresh-bin mean-harmony.
        if fresh_post > 0.0 && mean_residual > 0.0 && open_bins_count > 2 && fresh_match < 0.25 {
            score -= 14.0 * (1.0 - fresh_match / 0.25) * (0.5 + 0.5 * (1.0 - progress));
        }
        // Fresh-bin dead-space cap — refuse a fresh bin whose residual
        // exceeds the largest observed mean slack by a wide margin while
        // aggregate slack still covers several items.
        if fresh_post > 0.55 * cap && open_capacity > 3.0 * cap && remaining_frac > 0.2 {
            score += 30.0 * (fresh_post / cap - 0.55) * remaining_frac * (1.0 - progress);
        }
        // COMBINED MUTATION (gen 61) D: mid-stream fresh-bin guard — extend
        // the refusal band into the middle of the stream when aggregate open
        // slack can plausibly absorb the remaining demand, cutting spurious
        // bin opens that cause residual-variance waste.
        if remaining_frac >= 0.15 && remaining_frac < 0.45 && fresh_post > 0.4 * cap && fragmentation > 0.4 {
            let est_need = (remaining as f64) * (item_size as f64) * 0.45;
            if open_capacity > est_need {
                score += 28.0 * (1.0 - remaining_frac / 0.45);
            }
        }
        // COMBINED MUTATION (gen 61) E: late-stream fresh-bin refusal —
        // refuse fresh bins near the end when open bins still hold enough
        // aggregate space for the remaining demand.
        if remaining_frac < 0.15 && fresh_post > 0.3 * cap {
            let est_need = (remaining as f64) * (item_size as f64) * 0.35;
            if open_capacity > est_need {
                score += 55.0 * (1.0 - remaining_frac / 0.15);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- 2-step lookahead: perfect match with the next item is gold ---
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Reward exact match strongly; decay reward as mismatch grows.
        let match_bonus = 40.0 * (-diff / 20.0).exp();
        score -= match_bonus;

        // Penalize residuals that are too small for the next item but nonzero:
        // they become dead space unless exactly zero.
        if post_residual > 0 && (post_residual as i64 - next_item_size as i64) < 0 {
            score += 15.0;
        }
    }

    // --- Dead-space shaping: tiny nonzero residuals are wasted capacity ---
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - post_residual as f64 / 10.0);
    }
    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 30.0;
    }

    // --- Relative-to-mean coupling: prefer bins that tighten the spread ---
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // --- Last-chance bonus: if this is the only fitting bin, avoid opening a new bin ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // --- New-bin candidate handling: only attractive early or when open bins are crowded ---
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 / (mean_residual / bin_capacity as f64).max(0.5);
        let new_bin_penalty = 18.0 + 10.0 * (1.0 - progress);
        score += new_bin_penalty + 0.05 * crowding;
    }

    // Mild late-stream tightening: waste matters more as the stream ends.
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64 ;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 } ;
    let mut score = post_residual as f64 ;

    // Layered dead-space rewards (lower post_residual = better).
    if post_residual == 0 {
        score -= 1000.0 ;
    } else if post_residual <= 4 {
        score -= 250.0 + 4.0 * (4 - post_residual) as f64 ;
    } else if post_residual <= 10 {
        score -= 62.0 + 3.4 * (10 - post_residual) as f64 ;
    } else if post_residual <= 22 {
        score -= 13.0 + 1.4 * (22 - post_residual) as f64 ;
    } else if post_residual <= 32 {
        score -= 4.5 + 0.6 * (32 - post_residual) as f64 ;
    } else if post_residual <= 48 {
        score -= 1.2 + 0.2 * (48 - post_residual) as f64 ;
    }

    let w = 0.33 + 0.67 * progress * progress ;
    score *= w ;

    // Lookahead coupling with the next item.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 880.0 ;
        } else if next_item_size < post_residual {
            let two_step_waste = (post_residual - next_item_size) as f64 ;
            if two_step_waste <= 8.0 {
                score -= 132.0 - 2.2 * two_step_waste ;
            } else {
                score -= 70.0 - 0.55 * two_step_waste ;
            }
            if two_step_waste <= 3.0 {
                score -= 46.0 ;
            }
        } else {
            let miss = (next_item_size - post_residual) as f64 ;
            score += 0.9 * miss ;
            if miss > 28.0 {
                score += 0.5 * (miss - 28.0) ;
            }
        }
    }

    // Slack-based scarcity boost when the next item fits here.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64 ;
        let scarcity = 1.0 / (fitting_bins_count . max (1) as f64) ;
        let boost = 34.0 + 24.0 * scarcity ;
        score -= boost * (1.0 - slack / cap) * (0.6 + 0.4 * (1.0 - progress)) ;
        if fitting_bins_count <= 2 {
            score -= 14.0 * (1.0 - slack / cap) ;
        }
        if slack == 0.0 {
            score -= 18.0 * (1.0 - progress) ;
        }
    }

    if bin_residual != bin_capacity {
        let dead = (bin_residual - item_size) as f64 ;
        let dead_ratio = dead / cap ;
        if dead_ratio > 0.5 && fitting_bins_count > 1 {
            score += 10.0 * (dead_ratio - 0.5) * (1.0 - progress) ;
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
            && mean_residual > 0.0 && (mean_residual as u32) >= next_item_size {
            score += 12.0 ;
        }
        if post_residual > 12 && post_residual < 40 && next_item_size > post_residual {
            let orphan = (post_residual as f64 - 12.0) / 28.0 ;
            let scarcity = 1.0 / (fitting_bins_count . max (1) as f64) ;
            score += 16.0 * orphan * scarcity * (0.5 + 0.5 * (1.0 - progress)) ;
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let chain = post_residual % next_item_size . max (1) ;
            if chain == 0 {
                score -= 25.0 * (1.0 - progress) ;
            } else if chain <= 3 {
                score -= 10.0 * (1.0 - progress) ;
            }
        }
        // Stranded residual: too small for next item, weighted by scarcity.
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            let stranded = (next_item_size - post_residual) as f64 ;
            let scarcity = 1.0 / (fitting_bins_count . max (1) as f64) ;
            if stranded <= 10.0 {
                score += (8.0 + 1.0 * (10.0 - stranded)) * scarcity * (0.4 + 0.6 * (1.0 - progress)) ;
            } else {
                let proximity = 1.0 - (stranded - 10.0) . min (cap) / cap ;
                score += 3.0 * proximity * scarcity * (1.0 - progress) ;
            }
        }
        // Dead-space dominance penalty when tight fits exist elsewhere.
        if dead_ratio > 0.35 && fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / cap ;
            score += 7.0 * (dead_ratio - 0.35) * tightness * (1.0 - progress) ;
        }
        // Penalize leaving a residual awkwardly below the mean open-bin residual.
        if post_residual > 0 && mean_residual > 0.0 {
            let gap = mean_residual - post_residual as f64 ;
            if gap > 0.0 && gap < 0.15 * cap && fitting_bins_count > 2 {
                score += 4.5 * (gap / (0.15 * cap)) * (1.0 - progress) ;
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size . max (1) && fitting_bins_count > 2 {
            score -= 6.0 * (1.0 - progress) ;
        }
        // Strong extra reward for exact fills of nearly-full bins.
        if post_residual == 0 && bin_residual < bin_capacity {
            score -= 42.0 * (1.0 - bin_residual as f64 / cap) * (1.0 - progress) ;
        }
        // Residual-vs-mean harmony.
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 1 {
            let harmony = (post_residual as f64 - mean_residual) . abs () / cap ;
            if harmony < 0.08 {
                score -= 9.0 * (1.0 - harmony / 0.08) * (0.5 + 0.5 * (1.0 - progress)) ;
            }
        }
        // Chunkable residuals absorb repeated small items.
        if post_residual > 6 && post_residual <= 30 && next_item_size > 0 && next_item_size <= post_residual {
            let reps = post_residual / next_item_size . max (1) ;
            if reps >= 2 {
                score -= 3.5 * (reps as f64) . min (4.0) * (1.0 - progress) ;
            }
        }
        // Two-step lookahead.
        if next_item_size > 0 && post_residual > next_item_size {
            let after_next = post_residual - next_item_size ;
            if after_next > 0 && after_next <= 12 {
                let tail = after_next as f64 ;
                score -= (14.0 - 0.9 * tail) * (0.5 + 0.5 * (1.0 - progress)) ;
            }
        }
        // Penalize tiny dead-zone residuals unusable by the next item.
        if post_residual > 0 && post_residual < 6 && next_item_size > post_residual {
            score += 6.0 * (1.0 - progress) ;
        }
        // Three-step horizon.
        if next_item_size > 0 && post_residual > next_item_size {
            let after_next = (post_residual - next_item_size) as f64 ;
            if after_next > 8.0 && after_next <= 16.0 && progress < 0.85 {
                let scarcity = 1.0 / (fitting_bins_count . max (1) as f64) ;
                score -= (4.0 + 3.0 * scarcity) * (1.0 - (after_next - 8.0) / 8.0) * (1.0 - progress) ;
            }
        }
        // Overshoot spreading refinement.
        if post_residual > 0 && next_item_size > 0 && fitting_bins_count > 3 {
            let overshoot = post_residual . saturating_sub (next_item_size) as f64 ;
            if overshoot > 16.0 {
                score += 1.6 * ((overshoot - 16.0) / cap) . min (0.25) * (1.0 - progress) ;
            }
        }
        // Dead-ratio gradient with residual-magnitude term, scaled by aggregate open slack.
        if fitting_bins_count > 1 && dead_ratio > 0.08 && post_residual > 0 {
            let scarcity = 1.0 / (fitting_bins_count as f64) ;
            let comp_slack = (mean_residual / cap) . min (1.0) ;
            score += 6.5 * (dead_ratio - 0.08) * scarcity * comp_slack * (0.5 + 0.5 * (1.0 - progress)) ;
            score += 2.2 * (dead / cap) * scarcity * comp_slack * (1.0 - progress) ;
        }
        // Residual-magnitude tiebreaker toward mean.
        if fitting_bins_count > 2 && post_residual > 0 && mean_residual > 0.0 {
            let dev = ((post_residual as f64 - mean_residual) . abs () / cap) . min (0.4) ;
            score += 5.0 * dev * (1.0 - progress) ;
        }
        // Exact-fit ladder on round residuals.
        if post_residual > 0 && post_residual % 10 == 0 && post_residual <= 60 && next_item_size > 0 && next_item_size <= post_residual {
            score -= 4.0 * (1.0 - progress) * (1.0 - post_residual as f64 / 120.0) ;
        }
        // Scarcity-weighted perfect-fit extension.
        if next_item_size > 0 && post_residual == next_item_size && fitting_bins_count <= 3 {
            score -= 30.0 / fitting_bins_count . max (1) as f64 * (0.5 + 0.5 * (1.0 - progress)) ;
        }
        // Waste-density term: penalize placements whose leftover residual is
        // unusable relative to the remaining stream demand.
        if post_residual > 0 && next_item_size > 0 && fitting_bins_count > 1 {
            let usable = next_item_size <= post_residual
                || (mean_residual as u32) >= next_item_size ;
            if ! usable {
                let waste_frac = post_residual as f64 / cap ;
                let late = 0.35 + 0.65 * progress ;
                score += 9.0 * waste_frac * late ;
            }
        }
        // Fill-level momentum: consolidate near-full bins.
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 2 {
            let rel = post_residual as f64 / (mean_residual + 1.0) ;
            if rel < 0.5 {
                score -= 6.0 * (1.0 - rel / 0.5) * (0.4 + 0.6 * (1.0 - progress)) ;
            }
        }
    } else {
        // NEW-BIN CANDIDATE branch.
        let fragmentation = (mean_residual / cap) * open_bins_count as f64 ;
        let huge_item = item_size as f64 > 0.7 * cap ;
        let remaining = if total_items > step_index { total_items - step_index } else { 1 } ;
        let remaining_frac = remaining as f64 / total_items . max (1) as f64 ;
        let fresh_post = cap - item_size as f64 ;
        let fresh_is_exact = fresh_post <= 4.0 && fresh_post >= 0.0 ;

        if fragmentation > 0.55 || (huge_item && open_bins_count > 4) {
            score -= 64.0 + 44.0 * remaining_frac ;
        } else if fresh_is_exact {
            score -= 128.0 + 64.0 * remaining_frac ;
        } else {
            score += 400.0 - 80.0 * remaining_frac ;
            if fitting_bins_count <= 3 && open_bins_count > 2 {
                score -= 28.0 + 16.0 * remaining_frac ;
            }
        }

        let fresh_match = (fresh_post - mean_residual) . abs () / cap ;
        if fresh_match < 0.05 {
            score -= 74.0 * (1.0 - fresh_match / 0.05) ;
        }
        if remaining_frac < 0.05 && fresh_post > 0.0 && ! fresh_is_exact {
            score += 155.0 * (fresh_post / cap) ;
        }
        if fresh_post > 0.0 && fresh_post <= 22.0 && ! fresh_is_exact {
            score -= 24.0 * (1.0 - fresh_post / 22.0) ;
        }
        if fresh_post > 22.0 && fresh_post <= 40.0 && fragmentation < 0.35 {
            score -= 12.0 * (1.0 - (fresh_post - 22.0) / 18.0) ;
        }
        if fresh_post > 0.0 && fresh_match < 0.12 && fragmentation < 0.55 {
            score -= 28.0 * (1.0 - fresh_match / 0.12) ;
        }
        if next_item_size > 0 && fresh_post > 0.0 {
            let fresh_exact_next = (fresh_post as u32) == next_item_size ;
            let open_can_next = mean_residual >= next_item_size as f64 ;
            if fresh_exact_next && ! open_can_next && fitting_bins_count <= 2 {
                score -= 50.0 * (1.0 - progress) ;
            }
            if (fresh_post as u32) < next_item_size && mean_residual > next_item_size as f64 {
                score += 20.0 * (1.0 - progress) ;
            }
        }
        if next_item_size > 0 && fresh_post > next_item_size as f64 {
            let chain_post = fresh_post - next_item_size as f64 ;
            if chain_post <= 4.0 {
                score -= 33.0 * (1.0 - chain_post / 4.0) * (0.5 + 0.5 * (1.0 - progress)) ;
            } else if chain_post <= 10.0 {
                score -= 9.0 * (1.0 - (chain_post - 4.0) / 6.0) * (0.5 + 0.5 * (1.0 - progress)) ;
            }
        }
        if remaining_frac < 0.12 && fresh_post > 0.0 && ! fresh_is_exact && mean_residual * open_bins_count as f64 > 3.0 * cap {
            score += 40.0 * (1.0 - remaining_frac / 0.12) ;
        }
        if fitting_bins_count == 1 && fresh_post > 0.0 && next_item_size > 0 {
            let stranded_here = bin_capacity . saturating_sub (item_size) ;
            let would_strand = stranded_here < next_item_size ;
            if would_strand && stranded_here > 0 && stranded_here <= 8 {
                score -= 30.0 * (1.0 - progress) ;
            }
        }
        let open_capacity = mean_residual * open_bins_count as f64 ;
        let per_item_need = cap * 0.5 ;
        if remaining_frac > 0.25 && open_capacity < per_item_need * open_bins_count . max (1) as f64 * 0.5 {
            score -= 18.0 * (1.0 - progress) ;
        }
        if next_item_size > 0 && fresh_post > next_item_size as f64 {
            let after_next = fresh_post - next_item_size as f64 ;
            if after_next > 0.0 && after_next <= 8.0 && fragmentation < 0.5 {
                score -= 20.0 * (1.0 - after_next / 8.0) * (0.4 + 0.6 * (1.0 - progress)) ;
            }
        }
        if next_item_size > 0 && fresh_post > 0.0 && (fresh_post as u32) < next_item_size {
            let slack_total = mean_residual * open_bins_count as f64 ;
            if slack_total > 2.0 * cap {
                score += 26.0 * (1.0 - progress) ;
            }
        }
        if next_item_size > 0 && (fresh_post as u32) == next_item_size && fragmentation > 0.3 {
            score -= 44.0 * (0.5 + 0.5 * (1.0 - progress)) ;
        }
        if fresh_post > 0.5 * cap && mean_residual < 0.2 * cap && remaining_frac > 0.3 && open_bins_count > 3 {
            score += 24.0 * (fresh_post / cap - 0.5) * 2.0 * (1.0 - progress) ;
        }
        if fitting_bins_count <= 1 && fresh_post > 0.45 * cap && next_item_size > 0 {
            let reachable = (next_item_size as f64 / fresh_post) . min (1.0) ;
            if reachable < 0.5 {
                score += 18.0 * (0.5 - reachable) * (1.0 - progress) ;
            }
        }
        // Fresh-bin reusable-tail bonus with small-remainder extension.
        if next_item_size > 0 && fresh_post > 0.0 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size ;
            let rem = (fresh_post as u32) % next_item_size ;
            if reps >= 2 && fragmentation < 0.5 {
                score -= 7.0 * ((reps as f64) . min (4.0) - 1.0) * (0.4 + 0.6 * (1.0 - progress)) ;
                if rem <= 3 {
                    score -= 5.0 * (1.0 - progress) ;
                }
            }
        }
        // Fresh-bin residual-magnitude guard.
        if fresh_post > 0.35 * cap && remaining_frac > 0.2 && mean_residual * open_bins_count as f64 > 4.0 * cap && fragmentation < 0.45 {
            score += 20.0 * (fresh_post / cap - 0.35) * (1.0 - progress) ;
        }
        // Refuse fresh bins late in the stream when open bins still hold
        // enough aggregate space for the remaining demand.
        if remaining_frac < 0.15 && fresh_post > 0.3 * cap {
            let open_space = mean_residual * open_bins_count as f64 ;
            let est_need = (remaining as f64) * (item_size as f64) * 0.35 ;
            if open_space > est_need {
                score += 55.0 * (1.0 - remaining_frac / 0.15) ;
            }
        }
        // Mid-stream fresh-bin guard: refuse spurious opens when aggregate
        // open slack can plausibly absorb remaining demand.
        if remaining_frac >= 0.15 && remaining_frac < 0.45 && fresh_post > 0.4 * cap && fragmentation > 0.4 {
            let open_space = mean_residual * open_bins_count as f64 ;
            let est_need = (remaining as f64) * (item_size as f64) * 0.45 ;
            if open_space > est_need {
                score += 28.0 * (1.0 - remaining_frac / 0.45) ;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Layered dead-space rewards (lower post_residual = better).
    if post_residual == 0 {
        score -= 980.0;
    } else if post_residual <= 4 {
        score -= 250.0 + 4.2 * (4 - post_residual) as f64;
    } else if post_residual <= 10 {
        score -= 64.0 + 3.6 * (10 - post_residual) as f64;
    } else if post_residual <= 22 {
        score -= 13.5 + 1.5 * (22 - post_residual) as f64;
