        }
        // Dead-ratio gradient with residual-magnitude term, scaled by aggregate open slack.
        if fitting_bins_count > 1 && dead_ratio > 0.08 && post_residual > 0 {
            let scarcity = 1.0 / (fitting_bins_count as f64);
            let comp_slack = (mean_residual / cap).min(1.0);
            score += 6.5 * (dead_ratio - 0.08) * scarcity * comp_slack * (0.5 + 0.5 * (1.0 - progress));
            score += 2.2 * (dead / cap) * scarcity * comp_slack * (1.0 - progress);
        }
        // Residual-magnitude tiebreaker toward mean.
        if fitting_bins_count > 2 && post_residual > 0 && mean_residual > 0.0 {
            let dev = ((post_residual as f64 - mean_residual).abs() / cap).min(0.4);
            score += 5.0 * dev * (1.0 - progress);
        }
        // Exact-fit ladder on round residuals.
        if post_residual > 0 && post_residual % 10 == 0 && post_residual <= 60 && next_item_size > 0 && next_item_size <= post_residual {
            score -= 4.0 * (1.0 - progress) * (1.0 - post_residual as f64 / 120.0);
        }
        // Scarcity-weighted perfect-fit extension.
        if next_item_size > 0 && post_residual == next_item_size && fitting_bins_count <= 3 {
            score -= 30.0 / fitting_bins_count.max(1) as f64 * (0.5 + 0.5 * (1.0 - progress));
        }
        // Waste-density term: penalize placements whose leftover residual is
        // unusable relative to remaining stream demand.
        if post_residual > 0 && next_item_size > 0 && fitting_bins_count > 1 {
            let usable = next_item_size <= post_residual
                || (mean_residual as u32) >= next_item_size;
            if !usable {
                let waste_frac = post_residual as f64 / cap;
                let late = 0.35 + 0.65 * progress;
                score += 9.0 * waste_frac * late;
            }
        }
        // Fill-level momentum: consolidate near-full bins.
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 2 {
            let rel = post_residual as f64 / (mean_residual + 1.0);
            if rel < 0.5 {
                score -= 6.0 * (1.0 - rel / 0.5) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
    } else {
        // NEW-BIN CANDIDATE branch.
        let fragmentation = (mean_residual / cap) * open_bins_count as f64;
        let huge_item = item_size as f64 > 0.7 * cap;
        let remaining = if total_items > step_index { total_items - step_index } else { 1 };
        let remaining_frac = remaining as f64 / total_items.max(1) as f64;
        let fresh_post = cap - item_size as f64;
        let fresh_is_exact = fresh_post <= 4.0 && fresh_post >= 0.0;

        if fragmentation > 0.55 || (huge_item && open_bins_count > 4) {
            score -= 66.0 + 46.0 * remaining_frac;
        } else if fresh_is_exact {
            score -= 134.0 + 66.0 * remaining_frac;
        } else {
            score += 400.0 - 82.0 * remaining_frac;
            if fitting_bins_count <= 3 && open_bins_count > 2 {
                score -= 30.0 + 18.0 * remaining_frac;
            }
        }

        let fresh_match = (fresh_post - mean_residual).abs() / cap;
        if fresh_match < 0.05 {
            score -= 76.0 * (1.0 - fresh_match / 0.05);
        }
        if remaining_frac < 0.05 && fresh_post > 0.0 && !fresh_is_exact {
            score += 160.0 * (fresh_post / cap);
        }
        if fresh_post > 0.0 && fresh_post <= 22.0 && !fresh_is_exact {
            score -= 26.0 * (1.0 - fresh_post / 22.0);
        }
        if fresh_post > 22.0 && fresh_post <= 40.0 && fragmentation < 0.35 {
            score -= 12.5 * (1.0 - (fresh_post - 22.0) / 18.0);
        }
        if fresh_post > 0.0 && fresh_match < 0.12 && fragmentation < 0.55 {
            score -= 30.0 * (1.0 - fresh_match / 0.12);
        }
        if next_item_size > 0 && fresh_post > 0.0 {
            let fresh_exact_next = (fresh_post as u32) == next_item_size;
            let open_can_next = mean_residual >= next_item_size as f64;
            if fresh_exact_next && !open_can_next && fitting_bins_count <= 2 {
                score -= 52.0 * (1.0 - progress);
            }
            if (fresh_post as u32) < next_item_size && mean_residual > next_item_size as f64 {
                score += 21.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && fresh_post > next_item_size as f64 {
            let chain_post = fresh_post - next_item_size as f64;
            if chain_post <= 4.0 {
                score -= 34.0 * (1.0 - chain_post / 4.0) * (0.5 + 0.5 * (1.0 - progress));
            } else if chain_post <= 10.0 {
                score -= 9.5 * (1.0 - (chain_post - 4.0) / 6.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        if remaining_frac < 0.12 && fresh_post > 0.0 && !fresh_is_exact && mean_residual * open_bins_count as f64 > 3.0 * cap {
            score += 42.0 * (1.0 - remaining_frac / 0.12);
        }
        if fitting_bins_count == 1 && fresh_post > 0.0 && next_item_size > 0 {
            let stranded_here = bin_capacity.saturating_sub(item_size);
            let would_strand = stranded_here < next_item_size;
            if would_strand && stranded_here > 0 && stranded_here <= 8 {
                score -= 32.0 * (1.0 - progress);
            }
        }
        let open_capacity = mean_residual * open_bins_count as f64;
        let per_item_need = cap * 0.5;
        if remaining_frac > 0.25 && open_capacity < per_item_need * open_bins_count.max(1) as f64 * 0.5 {
            score -= 18.0 * (1.0 - progress);
        }
        if next_item_size > 0 && fresh_post > next_item_size as f64 {
            let after_next = fresh_post - next_item_size as f64;
            if after_next > 0.0 && after_next <= 8.0 && fragmentation < 0.5 {
                score -= 20.0 * (1.0 - after_next / 8.0) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        if next_item_size > 0 && fresh_post > 0.0 && (fresh_post as u32) < next_item_size {
            let slack_total = mean_residual * open_bins_count as f64;
            if slack_total > 2.0 * cap {
                score += 26.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && (fresh_post as u32) == next_item_size && fragmentation > 0.3 {
            score -= 44.0 * (0.5 + 0.5 * (1.0 - progress));
        }
        if fresh_post > 0.5 * cap && mean_residual < 0.2 * cap && remaining_frac > 0.3 && open_bins_count > 3 {
            score += 24.0 * (fresh_post / cap - 0.5) * 2.0 * (1.0 - progress);
        }
        if fitting_bins_count <= 1 && fresh_post > 0.45 * cap && next_item_size > 0 {
            let reachable = (next_item_size as f64 / fresh_post).min(1.0);
            if reachable < 0.5 {
                score += 18.0 * (0.5 - reachable) * (1.0 - progress);
            }
        }
        // Fresh-bin reusable-tail bonus with small-remainder extension.
        if next_item_size > 0 && fresh_post > 0.0 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 2 && fragmentation < 0.5 {
                score -= 7.0 * ((reps as f64).min(4.0) - 1.0) * (0.4 + 0.6 * (1.0 - progress));
                if rem <= 3 {
                    score -= 5.0 * (1.0 - progress);
                }
            }
        }
        // Fresh-bin residual-magnitude guard.
        if fresh_post > 0.35 * cap && remaining_frac > 0.2 && mean_residual * open_bins_count as f64 > 4.0 * cap && fragmentation < 0.45 {
            score += 20.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        // Refuse fresh bins late in the stream when open bins still hold
        // enough aggregate space for the remaining demand.
        if remaining_frac < 0.15 && fresh_post > 0.3 * cap {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.35;
            if open_space > est_need {
                score += 55.0 * (1.0 - remaining_frac / 0.15);
            }
        }
        // Mid-stream fresh-bin guard: extend refusal band into mid-stream
        // when aggregate open slack can plausibly absorb remaining demand.
        if remaining_frac >= 0.15 && remaining_frac < 0.45 && fresh_post > 0.4 * cap && fragmentation > 0.4 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.45;
            if open_space > est_need {
                score += 28.0 * (1.0 - remaining_frac / 0.45);
            }
        }
        // MUTATION (gen 62): hard late-stream fresh-bin veto — near the end,
        // never open a new bin unless it fills near-exactly, since leftover
        // fresh-bin space is pure waste.
        if remaining_frac < 0.06 && !fresh_is_exact && fragmentation < 0.7 {
            score += 90.0 * (1.0 - remaining_frac / 0.06);
        }
        // MUTATION (gen 62): big-item rescue — when a huge item barely misses
        // fitting any open bin, opening a fresh bin avoids stranding a whole
        // large item's worth of dead space in an open bin.
        if item_size as f64 > 0.85 * cap && fitting_bins_count <= 2 {
            score -= 55.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Dead-space penalty: residuals too small to hold any future item are wasted ---
    // Treat residuals below a plausible minimum item size as near-worthless.
    let min_item = 1u32;
    if post_residual < min_item.max(item_size / 8) {
        score += 25.0; // unusable sliver
    } else if post_residual <= 12 {
        score += 8.0 * (1.0 - (post_residual as f64) / 12.0);
    }

    // --- Tight-fit reward: exact or near-exact fills are excellent ---
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual as f64 <= (item_size as f64) * 0.15 {
        score -= 20.0;
    }

    // --- Lookahead (k=2): reward bins whose leftover can host the next item ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item nests perfectly: reward proportionally to how snug
            let snug = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 15.0 + 10.0 * snug;
        } else {
            // next item won't fit here; mildly penalize large leftovers that
            // will strand the next item anyway
            score += 3.0;
        }
    }

    // --- Last-chance bonus: if this is the ONLY bin that fits, strongly prefer it ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // --- New-bin candidate handling: opening a bin is usually worse than reusing ---
    if bin_residual == bin_capacity {
        // Base penalty: prefer existing bins unless they fit badly.
        score += 45.0;
        // But large items open bins more gracefully (less fragmentation risk):
        score -= (item_size as f64) * 0.25;
        // Early in the stream, having few bins, opening is cheaper.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
        // If open bins are heavily fragmented (high mean residual spread), opening is fine.
        if open_bins_count > 0 && mean_residual > 40.0 {
            score -= 8.0;
        }
    } else {
        // --- Prefer filling bins that are already relatively empty (consolidation) ---
        // Bins with large residual relative to mean are good consolidation targets.
        if mean_residual > 0.0 {
            let rel = (bin_residual as f64) / mean_residual;
            if rel > 1.2 {
                score -= 6.0 * (rel - 1.2).min(1.5);
            } else if rel < 0.7 {
                score += 6.0 * (0.7 - rel).min(1.5);
            }
        }
        // Slight preference to keep the number of open bins from exploding.
        score += (open_bins_count as f64).ln().max(0.0) * 1.5;
    }

    // --- Time horizon coupling: late in the stream, waste is less recoverable ---
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * (post_residual as f64) * 0.15;

    // --- Small deterministic tie-breaker to avoid oscillation between equals ---
    score += ((bin_residual as f64) * 0.001).sin() * 0.05;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Perfect fill is always best.
    if post_residual == 0 {
        score -= 1000.0;
        if bin_residual < bin_capacity {
            score -= 45.0 * (1.0 - bin_residual as f64 / cap) * (1.0 - progress);
        }
    }

    // Near-perfect fills: tighter window, scaled by item size.
    if post_residual > 0 && post_residual <= 4 {
        score -= 280.0 + 2.0 * (4 - post_residual) as f64;
    }

    // Layered dead-space rewards (borrowed gradient idea).
    if post_residual > 4 && post_residual <= 10 {
        score -= 60.0 + 3.4 * (10 - post_residual) as f64;
    } else if post_residual > 10 && post_residual <= 22 {
        score -= 12.0 + 1.4 * (22 - post_residual) as f64;
    } else if post_residual > 22 && post_residual <= 32 {
        score -= 4.5 + 0.7 * (32 - post_residual) as f64;
    }

    // Lookahead coupling with next item.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 850.0;
            if fitting_bins_count <= 3 {
                score -= 30.0 / fitting_bins_count.max(1) as f64;
            }
        } else if next_item_size < post_residual {
            let two_step_waste = (post_residual - next_item_size) as f64;
            if two_step_waste <= 10.0 {
                score -= 110.0 - 2.0 * two_step_waste;
            } else {
                score -= 90.0 - 0.3 * two_step_waste;
            }
            if two_step_waste <= 3.0 {
                score -= 45.0 * (1.0 - progress);
            }
        } else {
            let miss = (next_item_size - post_residual) as f64;
            score += 0.9 * miss;
            if miss > 30.0 {
                score += 0.4 * (miss - 30.0);
            }
            // Stranded-residual scarcity penalty.
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            if miss <= 10.0 {
                score += (8.0 + 1.0 * (10.0 - miss)) * scarcity * (0.4 + 0.6 * (1.0 - progress));
            }
        }
    }

    // Two-step lookahead: small tail after next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after2 = post_residual - next_item_size;
        if after2 > 0 && after2 <= 6 {
            score -= 40.0;
        }
        // Chunkable residuals absorb repeated small items.
        if after2 > 0 {
            let reps = post_residual / next_item_size.max(1);
            if reps >= 2 && post_residual <= 30 {
                score -= 3.5 * ((reps as f64).min(4.0) - 1.0) * (1.0 - progress);
            }
        }
    }

    // Dead-space dominance penalty when tight fits exist elsewhere.
    if bin_residual < bin_capacity {
        let dead = (bin_residual - item_size) as f64;
        let dead_ratio = dead / cap;
        if dead_ratio > 0.5 && fitting_bins_count > 1 {
            score += 10.0 * (dead_ratio - 0.5) * (1.0 - progress);
        }
        if dead_ratio > 0.35 && fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score += 7.0 * (dead_ratio - 0.35) * tightness * (1.0 - progress);
        }
        // Waste-density term: unusable leftover relative to demand.
        if post_residual > 0 && next_item_size > 0 && fitting_bins_count > 1 {
            let usable = next_item_size <= post_residual || (mean_residual as u32) >= next_item_size;
            if !usable {
                let waste_frac = post_residual as f64 / cap;
                let late = 0.35 + 0.65 * progress;
                score += 9.0 * waste_frac * late;
            }
        }
        // Fill-level momentum: consolidate near-full bins.
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 2 {
            let rel = post_residual as f64 / (mean_residual + 1.0);
            if rel < 0.5 {
                score -= 6.0 * (1.0 - rel / 0.5) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
    }

    // Discourage opening a new bin when decent fits exist among open bins.
    if bin_residual == bin_capacity {
        let remaining = if total_items > step_index { total_items - step_index } else { 1 };
        let remaining_frac = remaining as f64 / total_items.max(1) as f64;
        let fresh_post = cap - item_size as f64;
        let fragmentation = (mean_residual / cap) * open_bins_count as f64;
        let huge_item = item_size as f64 > 0.7 * cap;
        let fresh_is_exact = fresh_post <= 4.0 && fresh_post >= 0.0;

        if fragmentation > 0.55 || (huge_item && open_bins_count > 4) {
            score -= 60.0 + 40.0 * remaining_frac;
        } else if fresh_is_exact {
            score -= 130.0 + 60.0 * remaining_frac;
        } else {
            score += 500.0 - 80.0 * remaining_frac;
            if item_size >= bin_capacity / 2 && open_bins_count > 4 {
                score -= 450.0;
            }
        }

        // Fresh-bin match to mean residual.
        let fresh_match = (fresh_post - mean_residual).abs() / cap;
        if fresh_match < 0.05 {
            score -= 70.0 * (1.0 - fresh_match / 0.05);
        }
        // Refuse fresh bins late when open space can absorb demand.
        if remaining_frac < 0.15 && fresh_post > 0.3 * cap {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.35;
            if open_space > est_need {
                score += 55.0 * (1.0 - remaining_frac / 0.15);
            }
        }
        // Mid-stream fresh-bin guard.
        if remaining_frac >= 0.15 && remaining_frac < 0.45 && fresh_post > 0.4 * cap && fragmentation > 0.4 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.45;
            if open_space > est_need {
                score += 28.0 * (1.0 - remaining_frac / 0.45);
            }
        }
        // Fresh-bin chain lookahead.
        if next_item_size > 0 && fresh_post > next_item_size as f64 {
            let chain_post = fresh_post - next_item_size as f64;
            if chain_post <= 4.0 {
                score -= 32.0 * (1.0 - chain_post / 4.0) * (0.5 + 0.5 * (1.0 - progress));
            } else if chain_post <= 10.0 {
                score -= 9.0 * (1.0 - (chain_post - 4.0) / 6.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        if next_item_size > 0 && (fresh_post as u32) == next_item_size && fragmentation > 0.3 {
            score -= 40.0 * (0.5 + 0.5 * (1.0 - progress));
        }
        // Fresh-bin reusable-tail bonus.
        if next_item_size > 0 && fresh_post > 0.0 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 2 && fragmentation < 0.5 {
                score -= 7.0 * ((reps as f64).min(4.0) - 1.0) * (0.4 + 0.6 * (1.0 - progress));
                if rem <= 3 {
                    score -= 5.0 * (1.0 - progress);
                }
            }
        }
    }

    // Mild preference for bins whose residual is close to mean residual.
    if bin_residual < bin_capacity {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Base: prefer small post-residual, with non-linear sharpening
    let mut score = pr * (1.0 + 2.0 * x * x);

    // Smooth polynomial coupling of residual with stream progress:
    // early on, leave room (favor larger residuals slightly); late, pack tightly.
    let coupling = x * (1.0 - x) * 4.0; // peak at x=0.5, zero at 0/1
    score += coupling * (1.0 - progress) * 10.0;
    score -= coupling * progress * 8.0;

    // Penalize dead space that can't fit the lookahead item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr < ni {
            score += (ni - pr) * (0.5 + progress);
        } else {
            // reward bins that still fit the next item, smoothly
            score -= 3.0 * (1.0 - (pr - ni) / cap);
        }
    } else {
        // last item: pack as tightly as possible
        score += x * x * 5.0;
    }

    // Last-chance bin bonus: avoid opening a new bin when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 6.0 * (0.5 + 0.5 * progress);
    }

    // Mild pressure from number of open bins: fewer open bins preferred when residuals small
    score += (open_bins_count as f64).ln() * x * 2.0;

    // Encourage bins with residual near the mean (balanced packing), smooth term
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * 4.0 * (1.0 - progress);

    // New-bin candidate: neutral-ish baseline, opened only when it truly wins
    if bin_residual == bin_capacity {
        score += 2.0 + 4.0 * progress + x * 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Layered dead-space rewards (lower post_residual = better).
    if post_residual == 0 {
        score -= 980.0;
    } else if post_residual <= 4 {
        score -= 250.0 + 4.2 * (4 - post_residual) as f64;
    } else if post_residual <= 10 {
        score -= 64.0 + 3.6 * (10 - post_residual) as f64;
    } else if post_residual <= 22 {
        score -= 13.5 + 1.5 * (22 - post_residual) as f64;
    } else if post_residual <= 32 {
        score -= 5.0 + 0.7 * (32 - post_residual) as f64;
    } else if post_residual <= 48 {
        score -= 1.2 + 0.22 * (48 - post_residual) as f64;
    } else {
        score -= 1.2 - 0.014 * (post_residual as f64 - 48.0);
    }

    // Progress-scaled weighting: tighten late in the stream.
    let w = 0.33 + 0.67 * progress * progress;
    score *= w;

    // Lookahead coupling with the next item.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if next_item_size < post_residual {
            let two_step_waste = (post_residual - next_item_size) as f64;
            if two_step_waste <= 8.0 {
                score -= 135.0 - 2.3 * two_step_waste;
            } else {
                score -= 72.0 - 0.58 * two_step_waste;
            }
            if two_step_waste <= 3.0 {
                score -= 48.0;
            }
        } else {
            let miss = (next_item_size - post_residual) as f64;
            score += 0.95 * miss;
            if miss > 26.0 {
                score += 0.55 * (miss - 26.0);
            }
        }
    }

    // Slack-based scarcity boost when the next item fits here.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
        let boost = 36.0 + 26.0 * scarcity;
        score -= boost * (1.0 - slack / cap) * (0.6 + 0.4 * (1.0 - progress));
        if fitting_bins_count <= 2 {
            score -= 15.0 * (1.0 - slack / cap);
        }
        if slack == 0.0 {
            score -= 20.0 * (1.0 - progress);
        }
    }

    if bin_residual != bin_capacity {
        let dead = (bin_residual - item_size) as f64;
        let dead_ratio = dead / cap;
        if dead_ratio > 0.5 && fitting_bins_count > 1 {
            score += 10.5 * (dead_ratio - 0.5) * (1.0 - progress);
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
            && mean_residual > 0.0 && (mean_residual as u32) >= next_item_size {
            score += 12.0;
        }
        if post_residual > 12 && post_residual < 40 && next_item_size > post_residual {
            let orphan = (post_residual as f64 - 12.0) / 28.0;
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            score += 17.0 * orphan * scarcity * (0.5 + 0.5 * (1.0 - progress));
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let chain = post_residual % next_item_size.max(1);
            if chain == 0 {
                score -= 26.0 * (1.0 - progress);
            } else if chain <= 3 {
                score -= 11.0 * (1.0 - progress);
            }
        }
        // Stranded residual: too small for next item, weighted by scarcity.
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            let stranded = (next_item_size - post_residual) as f64;
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            if stranded <= 10.0 {
                score += (8.5 + 1.1 * (10.0 - stranded)) * scarcity * (0.4 + 0.6 * (1.0 - progress));
            } else {
                let proximity = 1.0 - (stranded - 10.0).min(cap) / cap;
                score += 3.2 * proximity * scarcity * (1.0 - progress);
            }
        }
        // Dead-space dominance penalty when tight fits exist elsewhere.
        if dead_ratio > 0.35 && fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score += 7.5 * (dead_ratio - 0.35) * tightness * (1.0 - progress);
        }
        // Penalize leaving a residual awkwardly below the mean open-bin residual.
        if post_residual > 0 && mean_residual > 0.0 {
            let gap = mean_residual - post_residual as f64;
            if gap > 0.0 && gap < 0.15 * cap && fitting_bins_count > 2 {
                score += 4.8 * (gap / (0.15 * cap)) * (1.0 - progress);
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size.max(1) && fitting_bins_count > 2 {
            score -= 6.5 * (1.0 - progress);
        }
        // Strong extra reward for exact fills of nearly-full bins.
        if post_residual == 0 && bin_residual < bin_capacity {
            score -= 42.0 * (1.0 - bin_residual as f64 / cap) * (1.0 - progress);
        }
        // Residual-vs-mean harmony.
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 1 {
            let harmony = (post_residual as f64 - mean_residual).abs() / cap;
            if harmony < 0.08 {
                score -= 9.0 * (1.0 - harmony / 0.08) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // Chunkable residuals absorb repeated small items.
        if post_residual > 6 && post_residual <= 30 && next_item_size > 0 && next_item_size <= post_residual {
            let reps = post_residual / next_item_size.max(1);
            if reps >= 2 {
                score -= 3.5 * (reps as f64).min(4.0) * (1.0 - progress);
            }
        }
        // Two-step lookahead.
        if next_item_size > 0 && post_residual > next_item_size {
            let after_next = post_residual - next_item_size;
            if after_next > 0 && after_next <= 12 {
                let tail = after_next as f64;
                score -= (14.0 - 0.9 * tail) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // Penalize tiny dead-zone residuals unusable by the next item.
        if post_residual > 0 && post_residual < 6 && next_item_size > post_residual {
            score += 6.0 * (1.0 - progress);
        }
        // Three-step horizon.
        if next_item_size > 0 && post_residual > next_item_size {
            let after_next = (post_residual - next_item_size) as f64;
            if after_next > 8.0 && after_next <= 16.0 && progress < 0.85 {
                let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
                score -= (4.0 + 3.0 * scarcity) * (1.0 - (after_next - 8.0) / 8.0) * (1.0 - progress);
            }
        }
        // Overshoot spreading refinement.
        if post_residual > 0 && next_item_size > 0 && fitting_bins_count > 3 {
            let overshoot = post_residual.saturating_sub(next_item_size) as f64;
            if overshoot > 16.0 {
                score += 1.6 * ((overshoot - 16.0) / cap).min(0.25) * (1.0 - progress);
            }
        }
        // Dead-ratio gradient with residual-magnitude term, scaled by aggregate open slack.
        if fitting_bins_count > 1 && dead_ratio > 0.08 && post_residual > 0 {
            let scarcity = 1.0 / (fitting_bins_count as f64);
            let comp_slack = (mean_residual / cap).min(1.0);
            score += 6.5 * (dead_ratio - 0.08) * scarcity * comp_slack * (0.5 + 0.5 * (1.0 - progress));
            score += 2.2 * (dead / cap) * scarcity * comp_slack * (1.0 - progress);
        }
        // Residual-magnitude tiebreaker toward mean.
        if fitting_bins_count > 2 && post_residual > 0 && mean_residual > 0.0 {
            let dev = ((post_residual as f64 - mean_residual).abs() / cap).min(0.4);
            score += 5.0 * dev * (1.0 - progress);
        }
        // Exact-fit ladder on round residuals.
        if post_residual > 0 && post_residual % 10 == 0 && post_residual <= 60 && next_item_size > 0 && next_item_size <= post_residual {
            score -= 4.0 * (1.0 - progress) * (1.0 - post_residual as f64 / 120.0);
        }
        // Scarcity-weighted perfect-fit extension.
        if next_item_size > 0 && post_residual == next_item_size && fitting_bins_count <= 3 {
            score -= 30.0 / fitting_bins_count.max(1) as f64 * (0.5 + 0.5 * (1.0 - progress));
        }
        // Waste-density term — penalize placements whose leftover residual is
        // unusable relative to the remaining stream demand.
        if post_residual > 0 && next_item_size > 0 && fitting_bins_count > 1 {
            let usable = next_item_size <= post_residual
                || (mean_residual as u32) >= next_item_size;
            if !usable {
                let waste_frac = post_residual as f64 / cap;
                let late = 0.35 + 0.65 * progress;
                score += 9.0 * waste_frac * late;
            }
        }
        // Fill-level momentum — consolidate near-full bins.
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 2 {
            let rel = post_residual as f64 / (mean_residual + 1.0);
            if rel < 0.5 {
                score -= 6.0 * (1.0 - rel / 0.5) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        // MUTATION (gen 62): residual-variance damper — steer post_residual
        // toward the mean open residual more strongly mid-stream, reducing
        // the observed residual-variance waste while keeping exact fills
        // dominant.
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 3 && progress > 0.15 {
            let dev = (post_residual as f64 - mean_residual) / cap;
            if dev > 0.12 && dev < 0.45 {
                score += 3.8 * (dev - 0.12) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // MUTATION (gen 62): complementary-fit bonus — when the residual left
        // here plus the mean slack elsewhere can absorb the next item
        // exactly, prefer this placement slightly over spreading.
        if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count > 2 {
            let after = post_residual - next_item_size;
            if after > 0 && after <= 6 && progress < 0.7 {
                score -= 7.5 * (1.0 - after as f64 / 6.0) * (1.0 - progress);
            }
        }
    } else {
        // NEW-BIN CANDIDATE branch.
        let fragmentation = (mean_residual / cap) * open_bins_count as f64;
        let huge_item = item_size as f64 > 0.7 * cap;
        let remaining = if total_items > step_index { total_items - step_index } else { 1 };
        let remaining_frac = remaining as f64 / total_items.max(1) as f64;
        let fresh_post = cap - item_size as f64;
        let fresh_is_exact = fresh_post <= 4.0 && fresh_post >= 0.0;

        if fragmentation > 0.55 || (huge_item && open_bins_count > 4) {
            score -= 66.0 + 46.0 * remaining_frac;
        } else if fresh_is_exact {
            score -= 134.0 + 66.0 * remaining_frac;
        } else {
            score += 400.0 - 82.0 * remaining_frac;
            if fitting_bins_count <= 3 && open_bins_count > 2 {
                score -= 30.0 + 18.0 * remaining_frac;
            }
        }

        let fresh_match = (fresh_post - mean_residual).abs() / cap;
        if fresh_match < 0.05 {
            score -= 76.0 * (1.0 - fresh_match / 0.05);
        }
        if remaining_frac < 0.05 && fresh_post > 0.0 && !fresh_is_exact {
            score += 160.0 * (fresh_post / cap);
        }
        if fresh_post > 0.0 && fresh_post <= 22.0 && !fresh_is_exact {
            score -= 26.0 * (1.0 - fresh_post / 22.0);
        }
        if fresh_post > 22.0 && fresh_post <= 40.0 && fragmentation < 0.35 {
            score -= 12.5 * (1.0 - (fresh_post - 22.0) / 18.0);
        }
        if fresh_post > 0.0 && fresh_match < 0.12 && fragmentation < 0.55 {
            score -= 30.0 * (1.0 - fresh_match / 0.12);
        }
        if next_item_size > 0 && fresh_post > 0.0 {
            let fresh_exact_next = (fresh_post as u32) == next_item_size;
            let open_can_next = mean_residual >= next_item_size as f64;
            if fresh_exact_next && !open_can_next && fitting_bins_count <= 2 {
                score -= 52.0 * (1.0 - progress);
            }
            if (fresh_post as u32) < next_item_size && mean_residual > next_item_size as f64 {
                score += 21.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && fresh_post > next_item_size as f64 {
            let chain_post = fresh_post - next_item_size as f64;
            if chain_post <= 4.0 {
                score -= 34.0 * (1.0 - chain_post / 4.0) * (0.5 + 0.5 * (1.0 - progress));
            } else if chain_post <= 10.0 {
                score -= 9.5 * (1.0 - (chain_post - 4.0) / 6.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        if remaining_frac < 0.12 && fresh_post > 0.0 && !fresh_is_exact && mean_residual * open_bins_count as f64 > 3.0 * cap {
            score += 42.0 * (1.0 - remaining_frac / 0.12);
        }
        if fitting_bins_count == 1 && fresh_post > 0.0 && next_item_size > 0 {
            let stranded_here = bin_capacity.saturating_sub(item_size);
            let would_strand = stranded_here < next_item_size;
            if would_strand && stranded_here > 0 && stranded_here <= 8 {
                score -= 32.0 * (1.0 - progress);
            }
        }
        let open_capacity = mean_residual * open_bins_count as f64;
        let per_item_need = cap * 0.5;
        if remaining_frac > 0.25 && open_capacity < per_item_need * open_bins_count.max(1) as f64 * 0.5 {
            score -= 18.0 * (1.0 - progress);
        }
        if next_item_size > 0 && fresh_post > next_item_size as f64 {
            let after_next = fresh_post - next_item_size as f64;
            if after_next > 0.0 && after_next <= 8.0 && fragmentation < 0.5 {
                score -= 20.0 * (1.0 - after_next / 8.0) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        if next_item_size > 0 && fresh_post > 0.0 && (fresh_post as u32) < next_item_size {
            let slack_total = mean_residual * open_bins_count as f64;
            if slack_total > 2.0 * cap {
                score += 26.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && (fresh_post as u32) == next_item_size && fragmentation > 0.3 {
            score -= 44.0 * (0.5 + 0.5 * (1.0 - progress));
        }
        if fresh_post > 0.5 * cap && mean_residual < 0.2 * cap && remaining_frac > 0.3 && open_bins_count > 3 {
            score += 24.0 * (fresh_post / cap - 0.5) * 2.0 * (1.0 - progress);
        }
        if fitting_bins_count <= 1 && fresh_post > 0.45 * cap && next_item_size > 0 {
            let reachable = (next_item_size as f64 / fresh_post).min(1.0);
            if reachable < 0.5 {
                score += 18.0 * (0.5 - reachable) * (1.0 - progress);
            }
        }
        // Fresh-bin reusable-tail bonus with small-remainder extension.
        if next_item_size > 0 && fresh_post > 0.0 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 2 && fragmentation < 0.5 {
                score -= 7.0 * ((reps as f64).min(4.0) - 1.0) * (0.4 + 0.6 * (1.0 - progress));
                if rem <= 3 {
                    score -= 5.0 * (1.0 - progress);
                }
            }
        }
        // Fresh-bin residual-magnitude guard.
        if fresh_post > 0.35 * cap && remaining_frac > 0.2 && mean_residual * open_bins_count as f64 > 4.0 * cap && fragmentation < 0.45 {
            score += 20.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        // Refuse fresh bins late in the stream when open bins still hold
        // enough aggregate space for the remaining demand.
        if remaining_frac < 0.15 && fresh_post > 0.3 * cap {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.35;
            if open_space > est_need {
                score += 55.0 * (1.0 - remaining_frac / 0.15);
            }
        }
        // Mid-stream fresh-bin guard — extend refusal into the middle of the
        // stream when aggregate open slack can plausibly absorb demand.
        if remaining_frac >= 0.15 && remaining_frac < 0.45 && fresh_post > 0.4 * cap && fragmentation > 0.4 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.45;
            if open_space > est_need {
                score += 28.0 * (1.0 - remaining_frac / 0.45);
            }
        }
        // MUTATION (gen 62): deep-slack refusal — when aggregate open slack is
        // very large relative to remaining demand, refuse fresh bins even
        // earlier, tightening residual-space usage toward the optimum.
        if remaining_frac >= 0.05 && remaining_frac < 0.6 && fresh_post > 0.3 * cap {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.6;
            if open_space > 2.5 * est_need {
                score += 16.0 * (1.0 - remaining_frac / 0.6) * (fresh_post / cap - 0.3);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into
    // "usable" residue classes (multiples of small sizes) are preferred.
    let pr = post_residual;
    if pr > 0 {
        // Dead-space penalty: leftover that no typical item can use.
        // Items are 1..=100 unknown; treat leftovers < 10 as near-dead.
        if pr < 10 {
            score += 40.0;
        }
        // Reward leftovers that are "harmonic": divisible by common small sizes
        let harmonic = (pr % 10 == 0) as f64 * 6.0
            + (pr % 5 == 0) as f64 * 3.0
            + (pr % 25 == 0) as f64 * 4.0
            + (pr % 20 == 0) as f64 * 3.0;
        score -= harmonic;
        // Fractional capacity classes: encourage exact quarter/half fills
        let frac = (bin_capacity - pr) as f64 / bin_capacity as f64;
        if (frac * 4.0).round() as u32 * 25 == bin_capacity - pr {
            score -= 5.0;
        }
    } else {
        // Perfect fit: strong reward
        score -= 60.0;
    }

    // Integer-division threshold classes on post_residual
    let class = pr / 10; // 0..10 coarse class
    // Mid-sized leftovers (class 2..5) are the most reusable
    if (2..=5).contains(&class) {
        score -= 4.0;
    } else if class >= 7 {
        // Large leftover means we picked a too-empty bin; mild penalty
        score += 2.0;
    }

    // Lookahead coupling: if next item fits the post residual exactly,
    // this bin becomes a great chain candidate.
    if next_item_size > 0 {
        if next_item_size == pr && pr > 0 {
            score -= 30.0;
        } else if next_item_size <= pr && pr > 0 {
            // partial compatibility reward, stronger for tighter fits
            score -= 8.0 * (next_item_size as f64 / pr as f64);
        } else {
            // next item won't fit here: slight penalty if this bin would
            // then be stranded with small leftover
            if pr < 15 {
                score += 6.0;
            }
        }
    }

    // Last-chance logic: if this is the only bin that fits, prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: neutral score so we only open new bins
    // when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin; tuned against typical open-bin scores.
        score = 25.0 + (open_bins_count as f64).sqrt() * 2.0;
        // If many bins already fit the item, opening new is clearly worse.
        if fitting_bins_count > 0 {
            score += 15.0 * fitting_bins_count as f64;
        }
        // Late in stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // If next item is large, a fresh bin is more attractive.
        if next_item_size > 50 {
            score -= 10.0;
        }
    }

    // Mild tie-break toward consolidating: prefer bins below mean residual
    // (fuller bins) to keep emptier bins flexible.
    if (bin_residual as f64) < mean_residual {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Layered dead-space rewards (lower post_residual = better).
    if post_residual == 0 {
        score -= 980.0;
    } else if post_residual <= 2 {
        score -= 620.0 + 40.0 * (2 - post_residual) as f64;
    } else if post_residual <= 4 {
        score -= 260.0 + 6.0 * (4 - post_residual) as f64;
    } else if post_residual <= 10 {
        score -= 64.0 + 3.8 * (10 - post_residual) as f64;
    } else if post_residual <= 22 {
        score -= 13.5 + 1.6 * (22 - post_residual) as f64;
    } else if post_residual <= 32 {
        score -= 5.0 + 0.75 * (32 - post_residual) as f64;
    } else if post_residual <= 48 {
        score -= 1.2 + 0.24 * (48 - post_residual) as f64;
    } else {
        score -= 1.2 - 0.015 * (post_residual as f64 - 48.0);
    }

    // Progress-scaled weighting: tighten late in the stream.
    let w = 0.33 + 0.67 * progress * progress;
    score *= w;

    // Lookahead coupling with the next item.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if next_item_size < post_residual {
            let two_step_waste = (post_residual - next_item_size) as f64;
            if two_step_waste <= 8.0 {
                score -= 138.0 - 2.3 * two_step_waste;
            } else {
                score -= 74.0 - 0.6 * two_step_waste;
            }
            if two_step_waste <= 3.0 {
                score -= 50.0;
            }
        } else {
            let miss = (next_item_size - post_residual) as f64;
            score += 0.95 * miss;
            if miss > 26.0 {
                score += 0.55 * (miss - 26.0);
            }
        }
    }

    // Slack-based scarcity boost when the next item fits here.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
        let boost = 36.0 + 26.0 * scarcity;
        score -= boost * (1.0 - slack / cap) * (0.6 + 0.4 * (1.0 - progress));
        if fitting_bins_count <= 2 {
            score -= 15.0 * (1.0 - slack / cap);
        }
        if slack == 0.0 {
            score -= 20.0 * (1.0 - progress);
        }
    }

    if bin_residual != bin_capacity {
        let dead = (bin_residual - item_size) as f64;
        let dead_ratio = dead / cap;
        if dead_ratio > 0.5 && fitting_bins_count > 1 {
            score += 10.5 * (dead_ratio - 0.5) * (1.0 - progress);
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
            && mean_residual > 0.0 && (mean_residual as u32) >= next_item_size {
            score += 12.0;
        }
        if post_residual > 12 && post_residual < 40 && next_item_size > post_residual {
            let orphan = (post_residual as f64 - 12.0) / 28.0;
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            score += 17.0 * orphan * scarcity * (0.5 + 0.5 * (1.0 - progress));
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let chain = post_residual % next_item_size.max(1);
            if chain == 0 {
                score -= 26.0 * (1.0 - progress);
            } else if chain <= 3 {
                score -= 11.0 * (1.0 - progress);
            }
        }
        // Stranded residual: too small for next item, weighted by scarcity.
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            let stranded = (next_item_size - post_residual) as f64;
            if stranded <= 10.0 {
                let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
                score += (8.5 + 1.1 * (10.0 - stranded)) * scarcity * (0.4 + 0.6 * (1.0 - progress));
            } else {
                let proximity = 1.0 - (stranded - 10.0).min(bin_capacity) as f64 / cap;
                let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
                score += 3.2 * proximity * scarcity * (1.0 - progress);
            }
        }
        // Dead-space dominance penalty when tight fits exist elsewhere.
        if dead_ratio > 0.35 && fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score += 7.5 * (dead_ratio - 0.35) * tightness * (1.0 - progress);
        }
        // Penalize leaving a residual awkwardly below the mean open-bin residual.
        if post_residual > 0 && mean_residual > 0.0 {
            let gap = mean_residual - post_residual as f64;
            if gap > 0.0 && gap < 0.15 * cap && fitting_bins_count > 2 {
                score += 4.8 * (gap / (0.15 * cap)) * (1.0 - progress);
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size.max(1) && fitting_bins_count > 2 {
            score -= 6.5 * (1.0 - progress);
        }
        // Strong extra reward for exact fills of nearly-full bins.
        if post_residual == 0 && bin_residual < bin_capacity {
            score -= 42.0 * (1.0 - bin_residual as f64 / cap) * (1.0 - progress);
        }
        // Residual-vs-mean harmony.
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 1 {
            let harmony = (post_residual as f64 - mean_residual).abs() / cap;
            if harmony < 0.08 {
                score -= 9.0 * (1.0 - harmony / 0.08) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // Chunkable residuals absorb repeated small items.
        if post_residual > 6 && post_residual <= 30 && next_item_size > 0 && next_item_size <= post_residual {
            let reps = post_residual / next_item_size.max(1);
            if reps >= 2 {
                score -= 3.5 * (reps as f64).min(4.0) * (1.0 - progress);
            }
        }
        // Two-step lookahead — reward leaving a residual that can exactly
        // absorb next_item followed by another small item.
        if next_item_size > 0 && post_residual > next_item_size {
            let after_next = post_residual - next_item_size;
            if after_next > 0 && after_next <= 12 {
                let tail = after_next as f64;
                score -= (14.0 - 0.9 * tail) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // Penalize tiny dead-zone residuals unusable by the next item.
        if post_residual > 0 && post_residual < 6 && next_item_size > post_residual {
            score += 6.0 * (1.0 - progress);
        }
        // Three-step horizon — residuals that can absorb next_item plus a
        // mid-size tail remain valuable when bins are scarce.
        if next_item_size > 0 && post_residual > next_item_size {
            let after_next = (post_residual - next_item_size) as f64;
            if after_next > 8.0 && after_next <= 16.0 && progress < 0.85 {
                let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
                score -= (4.0 + 3.0 * scarcity) * (1.0 - (after_next - 8.0) / 8.0) * (1.0 - progress);
            }
        }
        // Overshoot spreading refinement.
        if post_residual > 0 && next_item_size > 0 && fitting_bins_count > 3 {
            let overshoot = post_residual.saturating_sub(next_item_size) as f64;
            if overshoot > 16.0 {
                score += 1.6 * ((overshoot - 16.0) / cap).min(0.25) * 100.0 * 0.01 * (1.0 - progress);
            }
        }
        // Dead-ratio gradient tightened: absolute dead space punished alongside ratio.
        if fitting_bins_count > 1 && dead_ratio > 0.08 && post_residual > 0 {
            let scarcity = 1.0 / (fitting_bins_count as f64);
            let comp_slack = (mean_residual / cap).min(1.0);
            score += 6.5 * (dead_ratio - 0.08) * scarcity * comp_slack * (0.5 + 0.5 * (1.0 - progress));
            score += 2.2 * (dead / cap) * scarcity * comp_slack * (1.0 - progress);
        }
        // Residual-magnitude tiebreaker: among similar dead ratios, prefer
        // the residual closest to the mean, consolidating usable space.
        if fitting_bins_count > 2 && post_residual > 0 && mean_residual > 0.0 {
            let dev = ((post_residual as f64 - mean_residual).abs() / cap).min(0.4);
            score += 5.0 * dev * (1.0 - progress);
        }
        // Exact-fit ladder — round residuals are reusable by common sizes.
        if post_residual > 0 && post_residual % 10 == 0 && post_residual <= 60 && next_item_size > 0 && next_item_size <= post_residual {
            score -= 4.0 * (1.0 - progress) * (1.0 - post_residual as f64 / 120.0);
        }
        // Triple-fill planning — post_residual hosts next_item plus a small
        // companion; reward when bins are scarce.
        if next_item_size > 0 && post_residual > next_item_size && fitting_bins_count <= 3 {
            let tail = post_residual - next_item_size;
            if tail >= 1 && tail <= 12 {
                score -= 9.0 * (1.0 - tail as f64 / 12.0) * (1.0 - progress);
            }
        }
        // Protect the unique best fit for next_item when many bins are open.
        if next_item_size > 0 && post_residual == next_item_size && open_bins_count > 5 {
            score -= 14.0 * (0.4 + 0.6 * (1.0 - progress));
        }
        // Mid-band residual discount — 16..=28 residuals are highly reusable.
        if post_residual >= 16 && post_residual <= 28 && progress < 0.7 && fitting_bins_count > 1 {
            score -= 7.0 * (1.0 - (post_residual - 16) as f64 / 12.0) * (0.5 + 0.5 * progress);
        }
        // Dead-space compaction coupling — reward consolidation near the mean.
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 1 {
            let match_mean = 1.0 - ((post_residual as f64 - mean_residual).abs() / cap);
            if match_mean > 0.9 {
                score -= 5.0 * (match_mean - 0.9) * 10.0 * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // Waste-avoidance gradient — penalize dead space beyond next item's need.
        if next_item_size > 0 && post_residual > next_item_size && fitting_bins_count > 1 {
            let excess = (post_residual - next_item_size) as f64;
            if excess > 12.0 {
                score += 1.8 * ((excess - 12.0) / cap).min(0.3) * 100.0 * 0.01 * (1.0 - progress) * (fitting_bins_count as f64).min(4.0);
            }
        }
        // Tight-fit scarcity escalation.
        if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 4 {
            let gap_after = (post_residual - next_item_size) as f64;
            let urgency = (4.0 - fitting_bins_count as f64) / 3.0;
            score -= 10.0 * urgency * (1.0 - gap_after / cap) * (0.5 + 0.5 * (1.0 - progress));
        }
        // Mean-residual drain coupling.
        if post_residual > 0 && mean_residual > 0.0 && open_bins_count > 3 {
            let below = mean_residual - post_residual as f64;
            if below > 0.25 * cap && progress < 0.75 {
                score += 6.0 * (below / cap) * (1.0 - progress);
            }
        }
        // Squeeze-escalation ladder — when very few bins fit the next item,
        // escalate the reward for bins whose post residual matches the next
        // item exactly or leaves a tiny tail, preserving scarce
        // "next-item-shaped" pockets for the lookahead.
        if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 6 {
            let tail = post_residual - next_item_size;
            let urgency = (6.0 - fitting_bins_count as f64) / 5.0;
            if tail == 0 {
                score -= 22.0 * urgency * (1.0 - progress);
            } else if tail <= 2 {
                score -= 9.0 * urgency * (1.0 - tail as f64 / 2.0) * (1.0 - progress);
            }
        }
        // Stranded-pair avoidance — if placing here strands a residual smaller
        // than next_item while another bin's post residual would exactly host
        // next_item, penalize so the exact-host bin is not consumed.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size
            && mean_residual > 0.0 && (mean_residual as u32) >= next_item_size && fitting_bins_count > 1 {
            score += 7.0 * (1.0 - progress);
        }
        // MUTATION (gen 62): waste-density term — penalize placements whose
        // leftover residual is unusable relative to the remaining stream
        // demand, pushing residual space toward reusable magnitudes.
        if post_residual > 0 && next_item_size > 0 && fitting_bins_count > 1 {
            let usable = next_item_size <= post_residual
                || (mean_residual as u32) >= next_item_size;
            if !usable {
                let waste_frac = post_residual as f64 / cap;
                let late = 0.35 + 0.65 * progress;
                score += 9.0 * waste_frac * late;
            }
        }
        // MUTATION (gen 62): fill-level momentum — reward placing into bins
        // whose residual is already small relative to mean, consolidating
        // near-full bins to free up larger residuals elsewhere.
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 2 {
            let rel = post_residual as f64 / (mean_residual + 1.0);
            if rel < 0.5 {
                score -= 6.0 * (1.0 - rel / 0.5) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        // MUTATION (gen 62): scarcity-weighted perfect-fit extension —
        // reserve exact next-item pockets when bins are scarce.
        if next_item_size > 0 && post_residual == next_item_size && fitting_bins_count <= 3 {
            score -= 30.0 / fitting_bins_count.max(1) as f64 * (0.5 + 0.5 * (1.0 - progress));
        }
    } else {
        // NEW-BIN CANDIDATE branch.
        let fragmentation = (mean_residual / cap) * open_bins_count as f64;
        let huge_item = item_size as f64 > 0.7 * cap;
        let remaining = if total_items > step_index { total_items - step_index } else { 1 };
        let remaining_frac = remaining as f64 / total_items.max(1) as f64;
        let fresh_post = cap - item_size as f64;
        let fresh_is_exact = fresh_post <= 4.0 && fresh_post >= 0.0;

        if fragmentation > 0.55 || (huge_item && open_bins_count > 4) {
            score -= 66.0 + 46.0 * remaining_frac;
        } else if fresh_is_exact {
            score -= 134.0 + 66.0 * remaining_frac;
        } else {
            score += 400.0 - 82.0 * remaining_frac;
            if fitting_bins_count <= 3 && open_bins_count > 2 {
                score -= 30.0 + 18.0 * remaining_frac;
            }
        }

        let fresh_match = (fresh_post - mean_residual).abs() / cap;
        if fresh_match < 0.05 {
            score -= 76.0 * (1.0 - fresh_match / 0.05);
        }
        if remaining_frac < 0.05 && fresh_post > 0.0 && !fresh_is_exact {
            score += 160.0 * (fresh_post / cap);
        }
        if fresh_post > 0.0 && fresh_post <= 22.0 && !fresh_is_exact {
            score -= 26.0 * (1.0 - fresh_post / 22.0);
        }
        if fresh_post > 22.0 && fresh_post <= 40.0 && fragmentation < 0.35 {
            score -= 12.5 * (1.0 - (fresh_post - 22.0) / 18.0);
        }
        if fresh_post > 0.0 && fresh_match < 0.12 && fragmentation < 0.55 {
            score -= 30.0 * (1.0 - fresh_match / 0.12);
        }
        if next_item_size > 0 && fresh_post > 0.0 {
            let fresh_exact_next = (fresh_post as u32) == next_item_size;
            let open_can_next = mean_residual >= next_item_size as f64;
            if fresh_exact_next && !open_can_next && fitting_bins_count <= 2 {
                score -= 52.0 * (1.0 - progress);
            }
            if (fresh_post as u32) < next_item_size && mean_residual > next_item_size as f64 {
                score += 21.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && fresh_post > next_item_size as f64 {
            let chain_post = fresh_post - next_item_size as f64;
            if chain_post <= 4.0 {
                score -= 34.0 * (1.0 - chain_post / 4.0) * (0.5 + 0.5 * (1.0 - progress));
            } else if chain_post <= 10.0 {
                score -= 9.5 * (1.0 - (chain_post - 4.0) / 6.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        if remaining_frac < 0.12 && fresh_post > 0.0 && !fresh_is_exact && mean_residual * open_bins_count as f64 > 3.0 * cap {
            score += 42.0 * (1.0 - remaining_frac / 0.12);
        }
        // When only one open bin can fit and this item would leave a tiny
        // stranded residual there, opening a fresh bin is often better.
        if fitting_bins_count == 1 && fresh_post > 0.0 && next_item_size > 0 {
            let stranded_here = bin_capacity.saturating_sub(item_size);
            let would_strand = stranded_here < next_item_size;
            if would_strand && stranded_here > 0 && stranded_here <= 8 {
                score -= 32.0 * (1.0 - progress);
            }
        }
        // Open bins collectively nearly exhausted → keep density high.
        let open_capacity = mean_residual * open_bins_count as f64;
        let per_item_need = cap * 0.5;
        if remaining_frac > 0.25 && open_capacity < per_item_need * open_bins_count.max(1) as f64 * 0.5 {
            score -= 18.0 * (1.0 - progress);
        }
        // Fresh-bin chain quality.
        if next_item_size > 0 && fresh_post > next_item_size as f64 {
            let after_next = fresh_post - next_item_size as f64;
            if after_next > 0.0 && after_next <= 8.0 && fragmentation < 0.5 {
                score -= 20.0 * (1.0 - after_next / 8.0) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        // Avoid fresh bins whose residual is smaller than next_item when
        // open bins collectively have plenty of slack.
        if next_item_size > 0 && fresh_post > 0.0 && (fresh_post as u32) < next_item_size {
            let slack_total = mean_residual * open_bins_count as f64;
            if slack_total > 2.0 * cap {
                score += 26.0 * (1.0 - progress);
            }
        }
        // Fresh-bin exact-next bonus when fragmentation is moderate.
        if next_item_size > 0 && (fresh_post as u32) == next_item_size && fragmentation > 0.3 {
            score -= 44.0 * (0.5 + 0.5 * (1.0 - progress));
        }
        // Refuse very loose fresh bins when mean residual is tiny but many
        // bins are open — consolidation beats expansion.
        if fresh_post > 0.5 * cap && mean_residual < 0.2 * cap && remaining_frac > 0.3 && open_bins_count > 3 {
            score += 24.0 * (fresh_post / cap - 0.5) * 2.0 * (1.0 - progress);
        }
        // Single-fit guard.
        if fitting_bins_count <= 1 && fresh_post > 0.45 * cap && next_item_size > 0 {
            let reachable = (next_item_size as f64 / fresh_post).min(1.0);
            if reachable < 0.5 {
                score += 18.0 * (0.5 - reachable) * (1.0 - progress);
            }
        }
        // Fresh-bin reusable-tail bonus — residual a multiple of next_item.
        if next_item_size > 0 && fresh_post > 0.0 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 2 && fragmentation < 0.5 {
                score -= 7.0 * ((reps as f64).min(4.0) - 1.0) * (0.4 + 0.6 * (1.0 - progress));
                if rem <= 3 {
                    score -= 5.0 * (1.0 - progress);
                }
            }
        }
        // Fresh-bin two-item plan.
        if next_item_size > 0 && fitting_bins_count <= 2 && fresh_post > next_item_size as f64 {
            let tail = fresh_post - next_item_size as f64;
            if tail > 0.0 && tail <= 6.0 {
                score -= 28.0 * (1.0 - tail / 6.0) * (1.0 - progress);
            }
        }
        // Late-stream consolidation — prefer filling existing bins near the
        // end unless the fresh fit is near-exact.
        if progress > 0.8 && !fresh_is_exact && fresh_post > 8.0 && fitting_bins_count >= 1 {
            score += 20.0 * (progress - 0.8) / 0.2 * (fresh_post / cap);
        }
        // Aggregate-slack conservation — refuse a loose fresh bin when total
        // open slack already exceeds the expected need of remaining items.
        if remaining_frac > 0.15 && !fresh_is_exact && fresh_post > 0.35 * cap {
            let expected_need = remaining as f64 * (cap * 0.45);
            if open_capacity > expected_need {
                score += 22.0 * ((open_capacity - expected_need) / expected_need).min(1.0) * (1.0 - progress);
            }
        }
        // Fresh-bin scarcity gate.
        if fitting_bins_count == 0 && fresh_post > 0.0 {
            score -= 55.0 * (1.0 - fresh_post / cap) * (0.4 + 0.6 * (1.0 - progress));
        }
        // Fresh-bin mean-harmony.
        if fresh_post > 0.0 && mean_residual > 0.0 && open_bins_count > 2 && fresh_match < 0.25 {
            score -= 14.0 * (1.0 - fresh_match / 0.25) * (0.5 + 0.5 * (1.0 - progress));
        }
        // Fresh-bin dead-space cap — refuse to open a fresh bin whose residual
        // exceeds the largest observed mean slack by a wide margin while
        // aggregate slack still covers several items.
        if fresh_post > 0.55 * cap && open_capacity > 3.0 * cap && remaining_frac > 0.2 {
            score += 30.0 * (fresh_post / cap - 0.55) * remaining_frac * (1.0 - progress);
        }
        // MUTATION (gen 62): mid-stream fresh-bin guard — extend the refusal
        // band into the middle of the stream when aggregate open slack can
        // plausibly absorb the remaining demand, cutting spurious bin opens.
        if remaining_frac >= 0.15 && remaining_frac < 0.45 && fresh_post > 0.4 * cap && fragmentation > 0.4 {
            let est_need = (remaining as f64) * (item_size as f64) * 0.45;
            if open_capacity > est_need {
                score += 28.0 * (1.0 - remaining_frac / 0.45);
            }
        }
        // MUTATION (gen 62): late-stream fresh refusal — refuse fresh bins
        // with large residuals near the end when open slack suffices.
        if remaining_frac < 0.15 && fresh_post > 0.3 * cap {
            let est_need = (remaining as f64) * (item_size as f64) * 0.35;
            if open_capacity > est_need {
                score += 55.0 * (1.0 - remaining_frac / 0.15);
            }
        }
        // MUTATION (gen 62): fresh-bin residual-magnitude guard.
        if fresh_post > 0.35 * cap && remaining_frac > 0.2 && open_capacity > 4.0 * cap && fragmentation < 0.45 {
            score += 20.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Layered dead-space rewards (borrowed concept: finer residual ladder).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 4 {
        score -= 280.0 + 4.0 * (4 - post_residual) as f64;
    } else if post_residual <= 10 {
        score -= 60.0 + 3.2 * (10 - post_residual) as f64;
    } else if post_residual <= 22 {
        score -= 12.0 + 1.4 * (22 - post_residual) as f64;
    } else if post_residual <= 40 {
        score -= 3.5 + 0.6 * (40 - post_residual) as f64;
    }

    // Progress-scaled weighting: tighten late in the stream.
    let w = 0.35 + 0.65 * progress * progress;
    score *= w;

    // Lookahead coupling with next item.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 880.0;
        } else if next_item_size < post_residual {
            let two_step_waste = (post_residual - next_item_size) as f64;
            if two_step_waste <= 10.0 {
                score -= 120.0 - 2.2 * two_step_waste;
            } else {
                score -= 85.0 - 0.4 * two_step_waste;
            }
            if two_step_waste <= 3.0 {
                score -= 40.0;
            }
        } else {
            let miss = (next_item_size - post_residual) as f64;
            score += 0.9 * miss;
            if miss > 28.0 {
                score += 0.45 * (miss - 28.0);
            }
        }
    }

    // Two-step lookahead: small tail after next item is valuable.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after2 = post_residual - next_item_size;
        if after2 > 0 && after2 <= 6 {
            score -= 45.0 * (1.0 - after2 as f64 / 6.0) * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    // Scarcity-weighted perfect-fit extension.
    if next_item_size > 0 && post_residual == next_item_size && fitting_bins_count <= 3 {
        score -= 28.0 / fitting_bins_count.max(1) as f64 * (0.5 + 0.5 * (1.0 - progress));
    }

    // Stranded residual: too small for next item, weighted by scarcity.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && bin_residual != bin_capacity {
        let stranded = (next_item_size - post_residual) as f64;
        let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
        if stranded <= 10.0 {
            score += (8.0 + 1.0 * (10.0 - stranded)) * scarcity * (0.4 + 0.6 * (1.0 - progress));
        } else {
            let proximity = 1.0 - (stranded - 10.0).min(cap) / cap;
            score += 3.0 * proximity * scarcity * (1.0 - progress);
        }
    }

    // Chunkable residuals absorb repeated small items.
    if post_residual > 6 && post_residual <= 30 && next_item_size > 0 && next_item_size <= post_residual {
        let reps = post_residual / next_item_size.max(1);
        if reps >= 2 {
            score -= 3.5 * (reps as f64).min(4.0) * (1.0 - progress);
        }
    }

    // Waste-density term: penalize unusable leftovers late.
    if post_residual > 0 && next_item_size > 0 && fitting_bins_count > 1
        && next_item_size > post_residual && (mean_residual as u32) < next_item_size {
        let waste_frac = post_residual as f64 / cap;
        score += 9.0 * waste_frac * (0.35 + 0.65 * progress);
    }

    // Fill-level momentum: consolidate near-full bins.
    if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 2 {
        let rel = post_residual as f64 / (mean_residual + 1.0);
        if rel < 0.5 {
            score -= 6.0 * (1.0 - rel / 0.5) * (0.4 + 0.6 * (1.0 - progress));
        }
    }

    // Dead-space dominance penalty when tight fits exist elsewhere.
    if bin_residual != bin_capacity {
        let dead = (bin_residual - item_size) as f64;
        let dead_ratio = dead / cap;
        if dead_ratio > 0.35 && fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score += 7.5 * (dead_ratio - 0.35) * tightness * (1.0 - progress);
        }
    }

    // NEW-BIN CANDIDATE handling.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap) * open_bins_count as f64;
        let remaining = if total_items > step_index { total_items - step_index } else { 1 };
        let remaining_frac = remaining as f64 / total_items.max(1) as f64;
        let fresh_post = cap - item_size as f64;
        let fresh_is_exact = fresh_post <= 4.0;

        if fragmentation > 0.55 || (item_size as f64 > 0.7 * cap && open_bins_count > 4) {
            score -= 60.0 + 40.0 * remaining_frac;
        } else if fresh_is_exact {
            score -= 130.0 + 60.0 * remaining_frac;
        } else {
            score += 500.0 - 80.0 * remaining_frac;
            if fitting_bins_count <= 3 && open_bins_count > 2 {
                score -= 30.0 + 18.0 * remaining_frac;
            }
        }

        // Refuse fresh bins late when open space can absorb remaining demand.
        if remaining_frac < 0.15 && fresh_post > 0.3 * cap {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.35;
            if open_space > est_need {
                score += 55.0 * (1.0 - remaining_frac / 0.15);
            }
        }
        // Mid-stream fresh-bin guard.
        if remaining_frac >= 0.15 && remaining_frac < 0.45 && fresh_post > 0.4 * cap && fragmentation > 0.4 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.45;
            if open_space > est_need {
                score += 28.0 * (1.0 - remaining_frac / 0.45);
            }
        }
        // Fresh-bin chain lookahead.
        if next_item_size > 0 && fresh_post > next_item_size as f64 {
            let chain_post = fresh_post - next_item_size as f64;
            if chain_post <= 4.0 {
                score -= 30.0 * (1.0 - chain_post / 4.0) * (0.5 + 0.5 * (1.0 - progress));
            } else if chain_post <= 10.0 {
                score -= 9.0 * (1.0 - (chain_post - 4.0) / 6.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // Fresh-bin reusable-tail bonus.
        if next_item_size > 0 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 2 && fragmentation < 0.5 {
                score -= 7.0 * ((reps as f64).min(4.0) - 1.0) * (0.4 + 0.6 * (1.0 - progress));
                if rem <= 3 {
                    score -= 5.0 * (1.0 - progress);
                }
            }
        }
    } else {
        // Mild preference for bins whose residual is close to mean residual.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
        // Residual-vs-mean harmony.
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 1 {
            let harmony = (post_residual as f64 - mean_residual).abs() / cap;
            if harmony < 0.08 {
                score -= 8.0 * (1.0 - harmony / 0.08) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps that nothing (min size 1..100) can use
    // are the worst outcome. Penalize very small nonzero residuals hard.
    if post_residual > 0 {
        if post_residual < 10 {
            // Unusable dead space below the smallest plausible item
            score += 40.0;
        } else if post_residual < 20 {
            score += 18.0;
        } else if post_residual < 35 {
            score += 6.0;
        }
    }

    // Reward tight fits (small post_residual relative to item size)
    let tightness = item_size as f64 / (bin_residual as f64).max(1.0);
    score -= 12.0 * tightness;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open
    let progress = step_index as f64 / total_items.max(1) as f64;
    let bin_pressure = open_bins_count as f64 / (1.0 + progress * 10.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize progressively; allow only if it avoids bad fits
        score += 30.0 + 2.0 * bin_pressure;
        // But if no existing bin fits well (post_residual would be tiny), new bin is fine
        if post_residual == bin_capacity {
            // base case handled by pressure term
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // If next item is large and would be stranded by this placement, penalize
    if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Mean residual coupling: prefer bins with residual close to item size
    let diff = (bin_residual as f64 - item_size as f64 - mean_residual).abs();
    score += 0.05 * diff;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Layered dead-space rewards (lower post_residual = better).
    if post_residual == 0 {
        score -= 980.0;
    } else if post_residual <= 2 {
