        // MUTATION (gen 63): residual-variance compaction — when the aggregate
        // open slack comfortably exceeds remaining demand, mildly prefer the
        // placement that minimizes post-placement residual magnitude itself,
        // driving dead space toward zero and cutting residual variance.
        if post_residual > 0 && fitting_bins_count > 1 {
            let open_space = mean_residual * open_bins_count as f64;
            let remaining = if total_items > step_index { total_items - step_index } else { 1 };
            let est_need = (remaining as f64) * (item_size as f64) * 0.4;
            if open_space > est_need {
