                score -= 5.5 * tight * (0.5 + 0.5 * progress);
            }
        }
        // MUTATION (gen 63): pair-completion lookahead — reward residuals that
        // can be exactly split by the next item plus a small tail item, a
        // common pattern in long streams.
        if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 4 {
