        if fresh_post > 0.35 * cap && remaining_frac > 0.2 && mean_residual * open_bins_count as f64 > 4.0 * cap && fragmentation < 0.45 {
            score += 20.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        // Refuse fresh bins late in the stream when open bins still hold
        // enough aggregate space for the remaining demand.
        if remaining_frac < 0.15 && fresh_post > 0.3 * cap {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.35;
            if open_space > est_need {
                score += 55.0 * (1.0 - remaining_frac / 0.15);
            }
        }
        // MUTATION (gen 55, tuned gen 63): mid-stream fresh-bin guard — extend
        // the refusal band further into the stream when aggregate open slack
        // can plausibly absorb remaining demand.
        if remaining_frac >= 0.15 && remaining_frac < 0.5 && fresh_post > 0.4 * cap && fragmentation > 0.4 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.5;
            if open_space > est_need {
                score += 32.0 * (1.0 - remaining_frac / 0.5);
            }
        }
        // MUTATION (gen 63): fresh-bin exact-chunk bonus — opening a fresh bin
        // whose residual is an exact multiple of the next item size is a
        // high-value investment; reward it more aggressively when open bins
        // are already fragmented.
        if next_item_size > 0 && fresh_post > 0.0 && (fresh_post as u32) % next_item_size == 0 && fragmentation > 0.45 && remaining_frac > 0.2 {
            score -= 16.0 * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (post_residual small is good).
    let tight = (post_residual as f64) / (bin_capacity as f64);
    score += tight * tight * 40.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Dead-space penalty: residual after placement too small for any item (min size 1..100 unknown,
    // use item_size as proxy for typical small size).
    if post_residual > 0 && post_residual < item_size.min(20) {
        score += 15.0;
    }

    // Lookahead: reward bins whose post_residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 8.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when good open options exist, unless residuals are fragmented.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize mildly early, more when many bins are open with slack.
        let mut nb = 20.0 + 0.3 * open_bins_count as f64;
        if mean_residual > item_size as f64 + next_item_size as f64 {
            nb += 10.0; // open bins could host both current and next items
        }
        // Late in the stream, avoid proliferating bins.
        nb += 15.0 * progress;
        score += nb;
    } else {
        // Reusing an open bin: slight reward scaled by bin's slack vs mean residual.
        let rel = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * rel;
        score -= 5.0 * (1.0 - progress); // early on, consolidation is cheap
    }

    // Encourage balancing residuals toward mean to avoid many tiny slivers.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.03 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
