        }
        // Fill-level momentum: consolidate near-full bins.
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 2 {
            let rel = post_residual as f64 / (mean_residual + 1.0);
            if rel < 0.5 {
                score -= 6.0 * (1.0 - rel / 0.5) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        // MUTATION (gen 63): residual-variance dampener — prefer placements
        // that pull post_residual toward the open-bin mean, homogenizing
        // residual space so later items find a fitting home instead of
        // forcing a new bin. Extends the harmony band and adds a gentle
        // quadratic pull across the whole range.
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 1 {
            let dev = (post_residual as f64 - mean_residual).abs() / cap;
            if dev < 0.14 {
                score -= 5.5 * (1.0 - dev / 0.14) * (0.6 + 0.4 * (1.0 - progress));
