        let rel = post_residual as f64 / (mean_residual + 1.0);
        if rel < 0.5 {
            score -= 6.0 * (1.0 - rel / 0.5) * (0.4 + 0.6 * (1.0 - progress));
        }
    }

    // Residual-vs-mean harmony.
    if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 1 {
        let harmony = (post_residual as f64 - mean_residual).abs() / cap;
        if harmony < 0.08 {
            score -= 8.0 * (1.0 - harmony / 0.08) * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    // Dead-ratio gradient with residual-magnitude term.
    if bin_residual < bin_capacity {
        let dead = (bin_residual - item_size) as f64;
        let dead_ratio = dead / cap;
        if fitting_bins_count > 1 && dead_ratio > 0.08 && post_residual > 0 {
            let scarcity = 1.0 / (fitting_bins_count as f64);
            let comp_slack = (mean_residual / cap).min(1.0);
            score += 6.0 * (dead_ratio - 0.08) * scarcity * comp_slack * (0.5 + 0.5 * (1.0 - progress));
            score += 2.0 * (dead / cap) * scarcity * comp_slack * (1.0 - progress);
        }
        // Extra reward for exact fills of nearly-full bins.
        if post_residual == 0 {
            score -= 40.0 * (1.0 - bin_residual as f64 / cap) * (1.0 - progress);
        }
    }

    // ----- NEW-BIN CANDIDATE branch -----
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap) * open_bins_count as f64;
        let huge_item = item_size as f64 > 0.7 * cap;
        let remaining = if total_items > step_index { total_items - step_index } else { 1 };
        let remaining_frac = remaining as f64 / total_items.max(1) as f64;
        let fresh_post = cap - item_size as f64;
        let fresh_is_exact = fresh_post <= 4.0;

        if fragmentation > 0.55 || (huge_item && open_bins_count > 4) {
            score -= 60.0 + 46.0 * remaining_frac;
        } else if fresh_is_exact {
            score -= 140.0 + 66.0 * remaining_frac;
        } else {
            score += 420.0 - 80.0 * remaining_frac;
            if fitting_bins_count <= 3 && open_bins_count > 2 {
                score -= 28.0 + 18.0 * remaining_frac;
            }
        }

        // Fresh-bin reusable-tail bonus with small-remainder extension.
        if next_item_size > 0 && fresh_post > 0.0 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 2 && fragmentation < 0.5 {
                score -= 7.0 * ((reps as f64).min(4.0) - 1.0) * (0.4 + 0.6 * (1.0 - progress));
                if rem <= 3 {
                    score -= 5.0 * (1.0 - progress);
                }
            }
        }

        // Refuse fresh bins late when open bins hold enough aggregate space.
        if remaining_frac < 0.15 && fresh_post > 0.3 * cap {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.35;
            if open_space > est_need {
                score += 55.0 * (1.0 - remaining_frac / 0.15);
            }
        }

        // Mid-stream fresh-bin guard.
        if remaining_frac >= 0.15 && remaining_frac < 0.45 && fresh_post > 0.4 * cap && fragmentation > 0.4 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.45;
            if open_space > est_need {
                score += 28.0 * (1.0 - remaining_frac / 0.45);
            }
        }

        // Fresh-bin chain lookahead.
        if next_item_size > 0 && fresh_post > next_item_size as f64 {
            let chain_post = fresh_post - next_item_size as f64;
            if chain_post <= 4.0 {
                score -= 32.0 * (1.0 - chain_post / 4.0) * (0.5 + 0.5 * (1.0 - progress));
            } else if chain_post <= 10.0 {
                score -= 9.0 * (1.0 - (chain_post - 4.0) / 6.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }

        // Fresh match to mean residual.
        let fresh_match = (fresh_post - mean_residual).abs() / cap;
        if fresh_match < 0.05 {
            score -= 70.0 * (1.0 - fresh_match / 0.05);
        }

        // Late-stream refusal when fresh residual is large.
        if remaining_frac < 0.05 && fresh_post > 0.0 && !fresh_is_exact {
            score += 150.0 * (fresh_post / cap);
        }

        // Next-item exact fit in a fresh bin when open bins cannot host it.
        if next_item_size > 0 && (fresh_post as u32) == next_item_size && !{
            let open_can = mean_residual >= next_item_size as f64;
            open_can
        } && fitting_bins_count <= 2 {
            score -= 50.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let fit = item_size as f64 / cap;

    // Base: post residual, mildly damped by progress (early stream: waste tolerated less)
    let mut score = pr * (1.0 + 0.5 * progress);

    // Non-linear polynomial coupling: quadratic + cubic shaping of normalized post residual
    let q = norm_pr * norm_pr;
    let c = q * norm_pr;
    score += 40.0 * q * (0.5 + 0.5 * progress) - 25.0 * c * (1.0 - progress);

    // Interaction between fit ratio and post residual (smooth cross term)
    score += 30.0 * fit * norm_pr * (1.0 - norm_pr) * 4.0;

    // Last-chance bin bonus: subtract to favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 60.0;
    } else if fitting_bins_count > 1 {
        score += 8.0 * ((fitting_bins_count - 1) as f64).ln();
    }

    // Lookahead: penalize if next item fits well in post residual (reserve), reward otherwise
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let snug = 1.0 - (pr - nx) / cap;
            score += 20.0 * snug * snug;
        } else {
            score -= 10.0 * (nx - pr) / cap;
        }
    }

    // Mean residual deviation: prefer bins close to mean residual (smooth penalty)
    let dev = (pr as f64 - mean_residual) / cap;
    score += 15.0 * dev * dev;

    // New-bin candidate: penalize slightly more early, less late (allow overflow late)
    if bin_residual == bin_capacity {
        score += 50.0 * (1.0 - 0.6 * progress) + 10.0 * (open_bins_count as f64).ln();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
