        if remaining_frac >= 0.15 && remaining_frac < 0.45 && fresh_post > 0.4 * cap && fragmentation > 0.4 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.45;
            if open_space > est_need {
                score += 28.0 * (1.0 - remaining_frac / 0.45);
            }
        }
        // MUTATION (gen 64): fresh-bin tail-fit tightening — when the fresh
        // residual after the next item would be a stranded sliver that no
        // open bin's mean residual can absorb, add a small penalty to prefer
        // reusing open space instead of creating new dead space.
        if next_item_size > 0 && fresh_post > next_item_size as f64 {
            let after_next = (fresh_post - next_item_size as f64) as u32;
            if after_next > 0 && after_next < next_item_size && after_next < 10
                && mean_residual < next_item_size as f64 && remaining_frac > 0.1 {
                score += 14.0 * (1.0 - after_next as f64 / 10.0) * (1.0 - progress);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual into
    // capacity-fraction buckets and reward/punish each class.
    let frac = post_residual as f64 / cap_f; // 0..1
    let class = (frac * 8.0).floor() as i32; // 8 harmonic classes

    match class {
        0 => score -= 30.0,                    // near-perfect fill
        1 => score -= 12.0,                    // small useful gap
        2 => score += 5.0,                     // awkward ~25-37% gap
        3 => score += 10.0,                    // dead-space prone
        4 => score += 3.0,                     // half-cap: reusable
        5 => score -= 2.0,
        6 => score -= 6.0,
        _ => score -= 8.0,                     // mostly-empty bin
    }

    // Modulo arithmetic: gaps that exactly fit common future item classes
    // (multiples of 10) are more valuable.
    let gap_mod = post_residual % 10;
    if gap_mod == 0 {
        score -= 6.0;
    } else if gap_mod >= 7 {
        score += 4.0; // sliver, hard to reuse
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 15.0 - (slack as f64).min(15.0) * 0.5;
        }
        // Next item would leave this bin useless anyway -> mild penalty
        if next_item_size > post_residual && post_residual < 10 {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin gets a baseline penalty so we
    // prefer existing bins unless their residuals are truly bad.
    if bin_residual == bin_capacity {
        score = cap_f * 0.9 + open_bins_count as f64 * 0.5;
        // Early in stream, opening bins is cheap; late, prefer consolidation.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 20.0;
        // If many bins are open and residuals are large, discourage new bin.
        if mean_residual > cap_f * 0.5 {
            score += 10.0;
        }
        // Big item with no good home: allow new bin.
        if item_size > 60 {
            score -= 15.0;
        }
    }

    // Slight preference for tighter (fuller) bins overall.
    score += (bin_residual as f64 - post_residual as f64) * -0.05;
    score += (mean_residual - post_residual as f64).abs() * 0.02;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Perfect fill.
    if post_residual == 0 {
        score -= 1000.0;
        if bin_residual < bin_capacity {
            score -= 40.0 * (1.0 - bin_residual as f64 / cap) * (1.0 - progress);
        }
    }

    // Layered tight-fill rewards.
    if post_residual > 0 && post_residual <= 4 {
        score -= 280.0 + 2.0 * (4 - post_residual) as f64;
    } else if post_residual <= 10 {
        score -= 60.0 + 3.2 * (10 - post_residual) as f64;
    } else if post_residual <= 22 {
        score -= 12.0 + 1.4 * (22 - post_residual) as f64;
    } else if post_residual <= 48 {
        score -= 1.0 + 0.2 * (48 - post_residual) as f64;
    }

    // Progress-scaled weighting: tighten late in the stream.
    let w = 0.35 + 0.65 * progress * progress;
    score *= w;

    // Lookahead coupling with next item.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 880.0;
            if fitting_bins_count <= 3 {
                score -= 30.0 / fitting_bins_count.max(1) as f64 * (0.5 + 0.5 * (1.0 - progress));
            }
        } else if next_item_size < post_residual {
            let two_step_waste = (post_residual - next_item_size) as f64;
            if two_step_waste <= 10.0 {
                score -= 110.0 - 2.0 * two_step_waste;
            } else {
                score -= 90.0 - 0.3 * two_step_waste;
            }
            if two_step_waste <= 3.0 {
                score -= 45.0 * (1.0 - progress);
            }
        } else {
            let miss = (next_item_size - post_residual) as f64;
            score += 0.9 * miss;
            if miss > 30.0 {
                score += 0.4 * (miss - 30.0);
            }
            // Stranded residual weighted by scarcity.
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            if miss <= 10.0 {
                score += (8.0 + 1.0 * (10.0 - miss)) * scarcity * (0.4 + 0.6 * (1.0 - progress));
            }
        }
    }

    // Two-step lookahead.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after2 = post_residual - next_item_size;
        if after2 > 0 && after2 <= 6 {
            score -= 40.0 * (0.5 + 0.5 * (1.0 - progress));
        } else if after2 > 6 && after2 <= 14 {
            score -= (12.0 - 0.8 * (after2 as f64 - 6.0)) * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    // Scarcity boost when next item fits here and few bins can take it.
    if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 2 {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - slack / cap);
    }

    // Dead-space dominance penalty when tight fits exist elsewhere.
    if bin_residual != bin_capacity {
        let dead = (bin_residual - item_size) as f64;
        let dead_ratio = dead / cap;
        if dead_ratio > 0.5 && fitting_bins_count > 1 {
            score += 10.0 * (dead_ratio - 0.5) * (1.0 - progress);
        }
        // Chunkable residuals absorb repeated small items.
        if post_residual > 6 && post_residual <= 30 && next_item_size > 0 && next_item_size <= post_residual {
            let reps = post_residual / next_item_size.max(1);
            if reps >= 2 {
                score -= 3.5 * (reps as f64).min(4.0) * (1.0 - progress);
            }
        }
        // Residual-magnitude tiebreaker toward mean.
        if fitting_bins_count > 2 && mean_residual > 0.0 {
            let dev = ((post_residual as f64 - mean_residual).abs() / cap).min(0.4);
            score += 4.5 * dev * (1.0 - progress);
        }
        // Waste-density term: penalize unusable leftovers.
        if post_residual > 0 && next_item_size > 0 && fitting_bins_count > 1
            && next_item_size > post_residual && (mean_residual as u32) < next_item_size {
            let waste_frac = post_residual as f64 / cap;
            let late = 0.35 + 0.65 * progress;
            score += 9.0 * waste_frac * late;
        }
    }

    // NEW-BIN CANDIDATE branch.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap) * open_bins_count as f64;
        let huge_item = item_size as f64 > 0.7 * cap;
        let remaining = if total_items > step_index { total_items - step_index } else { 1 };
        let remaining_frac = remaining as f64 / total_items.max(1) as f64;
        let fresh_post = cap - item_size as f64;
        let fresh_is_exact = fresh_post <= 4.0;

        if fragmentation > 0.55 || (huge_item && open_bins_count > 4) {
            score -= 60.0 + 45.0 * remaining_frac;
        } else if fresh_is_exact {
            score -= 130.0 + 60.0 * remaining_frac;
        } else {
            score += 500.0 - 80.0 * remaining_frac;
            if fitting_bins_count <= 3 && open_bins_count > 2 {
                score -= 28.0 + 18.0 * remaining_frac;
            }
        }

        // Fresh-bin chain lookahead.
        if next_item_size > 0 && fresh_post > next_item_size as f64 {
            let chain_post = fresh_post - next_item_size as f64;
            if chain_post <= 4.0 {
                score -= 30.0 * (1.0 - chain_post / 4.0) * (0.5 + 0.5 * (1.0 - progress));
            } else if chain_post <= 10.0 {
                score -= 9.0 * (1.0 - (chain_post - 4.0) / 6.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // Refuse fresh bins late when open slack suffices.
        if remaining_frac < 0.15 && fresh_post > 0.3 * cap {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.35;
            if open_space > est_need {
                score += 55.0 * (1.0 - remaining_frac / 0.15);
            }
        }
        // Mid-stream fresh-bin guard.
        if remaining_frac >= 0.15 && remaining_frac < 0.45 && fresh_post > 0.4 * cap && fragmentation > 0.4 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.45;
            if open_space > est_need {
                score += 28.0 * (1.0 - remaining_frac / 0.45);
            }
        }
        // Fresh-bin reusable-tail bonus.
        if next_item_size > 0 && fresh_post > 0.0 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 2 && fragmentation < 0.5 {
                score -= 7.0 * ((reps as f64).min(4.0) - 1.0) * (0.4 + 0.6 * (1.0 - progress));
                if rem <= 3 {
                    score -= 5.0 * (1.0 - progress);
                }
            }
        }
        // Fresh bin matching mean residual keeps homogeneity.
        if mean_residual > 0.0 {
            let fresh_match = (fresh_post - mean_residual).abs() / cap;
            if fresh_match < 0.05 {
                score -= 60.0 * (1.0 - fresh_match / 0.05);
            }
        }
    } else {
        // Mild preference for bins whose residual is close to mean residual.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let mut score = post_residual as f64;

    // Reward tight fills: larger items consuming more of the bin get a bonus.
    score -= (item_size as f64 / bin_capacity as f64) * 12.0;

    // Strict dead-space avoidance: if the leftover gap is smaller than the
    // next item, that space is likely unusable -> heavy penalty.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 18.0 + 0.4 * next_item_size as f64;
    }

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Mild pressure from the number of open bins: with many open bins,
    // prefer consolidation into existing bins.
    score += 0.08 * open_bins_count as f64;

    // Bias toward bins whose residual is below the mean (filling emptier-
    // than-average bins last keeps large gaps available).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    // Penalize opening a brand-new bin, more so early in the stream when
    // consolidation matters most.
    if bin_residual == bin_capacity {
        score += 22.0 + 8.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
