            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * (1.0 + 2.0 * progress * norm_pr - progress * (1.0 - norm_pr));

    let mut score = pr + 30.0 * poly;

    // Penalize dead space more when few bins can fit the item
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else {
        score += 5.0 * (fitting_bins_count as f64).ln();
    }

    // Lookahead: reward leaving space close to next item size
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score += 0.3 * gap;
        if gap < 1.0 {
            score -= 10.0;
        }
    }

    // Mild preference for tighter bins relative to mean residual
    score += 0.5 * (pr - mean_residual);

    // Slight new-bin penalty that fades with progress
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - progress);
    }

    score
}

