            let dev = ((post_residual as f64 - target).abs() / cap).min(0.5);
            score += 2.4 * dev * (progress - 0.25);
        }
        // MUTATION (gen 66): pair-completion horizon — when the residual after
        // placing the next item can itself absorb a second copy of the next
        // item (or another known-size item), the bin supports a clean two-tile
        // chain; reward this to convert leftover dead space into useful space.
        if post_residual > 0 && next_item_size > 1 && fitting_bins_count > 1 {
            let after_next = post_residual as i64 - next_item_size as i64;
            if after_next > 0 {
                let an = after_next as u32;
                if an >= 2 * next_item_size {
