        // the residual distribution tight (low variance), so reward it beyond
        // the existing 0.12 band with a smooth decay tail.
        if fresh_post > 0.0 && fresh_match >= 0.12 && fresh_match < 0.30 && fragmentation < 0.5 {
            score -= 10.0 * (1.0 - (fresh_match - 0.12) / 0.18) * (0.5 + 0.5 * (1.0 - progress));
        }
        // MUTATION (gen 66): demand-aware fresh refusal — if the aggregate open
        // slack already exceeds the total remaining demand by a wide margin,
        // refuse any non-exact fresh bin regardless of stream position.
        if fresh_post > 0.0 && !fresh_is_exact && open_capacity > 1.6 * (remaining as f64) * (item_size as f64).max(1.0) as f64 {
            score += 34.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
