        if remaining_frac >= 0.45 && remaining_frac < 0.5 && fresh_post > 0.45 * cap && fragmentation > 0.5 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.55;
            if open_space > est_need {
                score += 22.0 * (1.0 - remaining_frac / 0.5);
            }
        }
        // MUTATION (gen 67): residual-complement fresh-bin check — when the
        // fresh bin's post residual complements the aggregate open slack to
        // nearly tile the next item, opening is cheap; reward exact pairing.
        if next_item_size > 0 && fresh_post > 0.0 && fitting_bins_count >= 1 {
            let combo = fresh_post + mean_residual;
            let over = combo - next_item_size as f64;
            if over >= 0.0 && over <= 5.0 && fragmentation < 0.5 {
                score -= 14.0 * (1.0 - over / 5.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
