        }
        // MUTATION (gen 67): residual-divisibility consolidation — exact
        // multiples of next_item tile to zero waste; reward scaled by scarcity.
        if post_residual > 0 && next_item_size > 1 && next_item_size <= post_residual {
            let reps = post_residual / next_item_size;
            let rem = post_residual % next_item_size;
            if reps >= 1 && rem == 0 {
                let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
                score -= (5.0 + 6.0 * scarcity) * (reps as f64).min(3.0) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        // MUTATION (gen 67): variance-damping tiebreak — mildly prefer post
        // residuals near the midpoint of mean and half-capacity after 25%.
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 1 && progress > 0.25 {
            let target = 0.5 * (mean_residual + 0.5 * cap);
            let dev = ((post_residual as f64 - target).abs() / cap).min(0.5);
            score += 2.4 * dev * (progress - 0.25);
        }
        // MUTATION (gen 67): dead-space lookahead squeeze — when this
        // placement strands a residual that neither next_item nor the mean
        // open slack can absorb, penalize proportionally to the stranded
        // magnitude, steering items toward bins that keep residual usable.
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
            && (mean_residual as u32) < next_item_size && fitting_bins_count > 1 {
            let stranded = (next_item_size - post_residual) as f64;
            score += (3.0 + 0.4 * stranded.min(20.0)) * (0.5 + 0.5 * progress);
