}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Perfect fill is always best.
    if post_residual == 0 {
        score -= 1000.0;
        if bin_residual < bin_capacity {
            score -= 40.0 * (1.0 - bin_residual as f64 / cap) * (1.0 - progress);
        }
    }

    // Layered near-perfect fill rewards (combined fine-grained fitting).
    else if post_residual <= 4 {
        score -= 280.0 + 3.0 * (4 - post_residual) as f64;
    } else if post_residual <= 10 {
        score -= 60.0 + 3.2 * (10 - post_residual) as f64;
    } else if post_residual <= 22 {
        score -= 12.0 + 1.4 * (22 - post_residual) as f64;
    } else if post_residual <= 36 {
        score -= 4.0 + 0.6 * (36 - post_residual) as f64;
    }

    // Lookahead coupling with next item.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 880.0;
            if fitting_bins_count <= 3 {
                score -= 30.0 / fitting_bins_count.max(1) as f64;
            }
        } else if next_item_size < post_residual {
            let two_step_waste = (post_residual - next_item_size) as f64;
            if two_step_waste <= 8.0 {
                score -= 120.0 - 2.2 * two_step_waste;
            } else {
                score -= 85.0 - 0.4 * two_step_waste;
            }
            if two_step_waste <= 3.0 {
                score -= 45.0;
            }
        } else {
            let miss = (next_item_size - post_residual) as f64;
            score += 0.95 * miss;
            if miss > 28.0 {
                score += 0.45 * (miss - 28.0);
            }
        }
    }

    // Two-step lookahead: small tail after next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after2 = post_residual - next_item_size;
        if after2 > 0 && after2 <= 8 {
            score -= (40.0 - 2.5 * after2 as f64) * (0.5 + 0.5 * (1.0 - progress));
        }
        // Tiling: residual divisible by next item -> zero-waste chain.
        let rem = post_residual % next_item_size.max(1);
        if rem == 0 {
            let reps = post_residual / next_item_size;
            score -= (6.0 + 5.0 / fitting_bins_count.max(1) as f64) * (reps as f64).min(3.0) * (0.4 + 0.6 * (1.0 - progress));
        }
    }

    // Stranded residual: too small for next item, weighted by scarcity.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let stranded = (next_item_size - post_residual) as f64;
        let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
        if stranded <= 10.0 {
            score += (9.0 + 1.0 * (10.0 - stranded)) * scarcity * (0.4 + 0.6 * (1.0 - progress));
        } else {
            score += 3.0 * scarcity * (1.0 - progress);
        }
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap) * open_bins_count as f64;
        let fresh_post = cap - item_size as f64;
        let remaining_frac = if total_items > 0 {
            (total_items.saturating_sub(step_index)) as f64 / total_items as f64
        } else { 0.0 };

        let huge_item = item_size as f64 > 0.7 * cap;
        if fragmentation > 0.55 || (huge_item && open_bins_count > 4) {
            score -= 60.0 + 40.0 * remaining_frac;
        } else if fresh_post <= 4.0 {
            score -= 130.0 + 60.0 * remaining_frac;
        } else {
            score += 500.0 - 80.0 * remaining_frac;
            if fitting_bins_count <= 2 && open_bins_count > 2 {
                score -= 35.0 + 20.0 * remaining_frac;
            }
        }

        // Fresh bin matching next item exactly.
        if next_item_size > 0 && (fresh_post as u32) == next_item_size && fragmentation > 0.3 {
            score -= 45.0 * (0.5 + 0.5 * (1.0 - progress));
        }
        // Fresh bin would strand small unusable space.
        if next_item_size > 0 && (fresh_post as u32) < next_item_size && fresh_post > 0.0 {
            if mean_residual * open_bins_count as f64 > 2.0 * cap {
                score += 28.0 * (1.0 - progress);
            }
        }
        // Refuse fresh bins late when open slack dominates.
        if remaining_frac < 0.15 && fresh_post > 0.3 * cap {
            let open_space = mean_residual * open_bins_count as f64;
            let remaining = total_items.saturating_sub(step_index) as f64;
            let est_need = remaining * (item_size as f64) * 0.35;
            if open_space > est_need {
                score += 55.0 * (1.0 - remaining_frac / 0.15);
            }
        }
        // Mid-stream fresh-bin guard.
        if remaining_frac >= 0.15 && remaining_frac < 0.45 && fresh_post > 0.4 * cap && fragmentation > 0.4 {
            let open_space = mean_residual * open_bins_count as f64;
            let remaining = total_items.saturating_sub(step_index) as f64;
            let est_need = remaining * (item_size as f64) * 0.45;
            if open_space > est_need {
                score += 28.0 * (1.0 - remaining_frac / 0.45);
            }
        }
    }

    // Mild preference for bins whose residual is close to mean residual.
    if bin_residual < bin_capacity {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
        // Dead-space penalty when tight fits exist elsewhere.
        let dead_ratio = (bin_residual - item_size) as f64 / cap;
        if dead_ratio > 0.4 && fitting_bins_count > 2 {
            score += 8.0 * (dead_ratio - 0.4) * (1.0 - progress);
        }
    }

    // Progress-scaled tightening late in the stream.
    let w = 0.5 + 0.5 * progress * progress;
    score *= 0.6 + 0.4 * w;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    if post_residual == 0 {
        score -= 980.0;
    } else if post_residual <= 4 {
        score -= 250.0 + 4.2 * (4 - post_residual) as f64;
    } else if post_residual <= 10 {
        score -= 64.0 + 3.6 * (10 - post_residual) as f64;
    } else if post_residual <= 22 {
        score -= 13.5 + 1.5 * (22 - post_residual) as f64;
    } else if post_residual <= 32 {
        score -= 5.0 + 0.7 * (32 - post_residual) as f64;
    } else if post_residual <= 48 {
        score -= 1.2 + 0.22 * (48 - post_residual) as f64;
    } else {
        score -= 1.2 - 0.014 * (post_residual as f64 - 48.0);
    }

    let w = 0.33 + 0.67 * progress * progress;
    score *= w;

    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if next_item_size < post_residual {
            let two_step_waste = (post_residual - next_item_size) as f64;
            if two_step_waste <= 8.0 {
                score -= 135.0 - 2.3 * two_step_waste;
            } else {
                score -= 72.0 - 0.58 * two_step_waste;
            }
            if two_step_waste <= 3.0 {
                score -= 48.0;
            }
        } else {
            let miss = (next_item_size - post_residual) as f64;
            score += 0.95 * miss;
            if miss > 26.0 {
                score += 0.55 * (miss - 26.0);
            }
        }
    }

    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
        let boost = 36.0 + 26.0 * scarcity;
        score -= boost * (1.0 - slack / cap) * (0.6 + 0.4 * (1.0 - progress));
        if fitting_bins_count <= 2 {
            score -= 15.0 * (1.0 - slack / cap);
        }
        if slack == 0.0 {
            score -= 20.0 * (1.0 - progress);
        }
    }

    if bin_residual != bin_capacity {
        let dead = (bin_residual - item_size) as f64;
        let dead_ratio = dead / cap;
        if dead_ratio > 0.5 && fitting_bins_count > 1 {
            score += 10.5 * (dead_ratio - 0.5) * (1.0 - progress);
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
            && mean_residual > 0.0 && (mean_residual as u32) >= next_item_size {
            score += 12.0;
        }
        if post_residual > 12 && post_residual < 40 && next_item_size > post_residual {
            let orphan = (post_residual as f64 - 12.0) / 28.0;
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            score += 17.0 * orphan * scarcity * (0.5 + 0.5 * (1.0 - progress));
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let chain = post_residual % next_item_size.max(1);
            if chain == 0 {
                score -= 26.0 * (1.0 - progress);
            } else if chain <= 3 {
                score -= 11.0 * (1.0 - progress);
            }
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            let stranded = (next_item_size - post_residual) as f64;
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            if stranded <= 10.0 {
                score += (8.5 + 1.1 * (10.0 - stranded)) * scarcity * (0.4 + 0.6 * (1.0 - progress));
            } else {
                let proximity = 1.0 - (stranded - 10.0).min(cap) / cap;
                score += 3.2 * proximity * scarcity * (1.0 - progress);
            }
        }
        if dead_ratio > 0.35 && fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score += 7.5 * (dead_ratio - 0.35) * tightness * (1.0 - progress);
        }
        if post_residual > 0 && mean_residual > 0.0 {
            let gap = mean_residual - post_residual as f64;
            if gap > 0.0 && gap < 0.15 * cap && fitting_bins_count > 2 {
                score += 4.8 * (gap / (0.15 * cap)) * (1.0 - progress);
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size.max(1) && fitting_bins_count > 2 {
