            } else if chain <= 3 {
                score -= 11.0 * (1.0 - progress);
            }
        }
        // Stranded residual: too small for next item, weighted by scarcity.
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            let stranded = (next_item_size - post_residual) as f64;
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            if stranded <= 10.0 {
                score += (8.5 + 1.1 * (10.0 - stranded)) * scarcity * (0.4 + 0.6 * (1.0 - progress));
            } else {
                let proximity = 1.0 - (stranded - 10.0).min(bin_capacity) as f64 / cap;
