        // MUTATION (gen 65): residual-divisibility consolidation — when the
        // post placement residual is an exact multiple of the next item size,
        // the bin can be tiled to zero waste; reward that more when few bins
        // fit, reinforcing the momentum direction.
        if post_residual > 0 && next_item_size > 1 && next_item_size <= post_residual {
            let reps = post_residual / next_item_size;
            let rem = post_residual % next_item_size;
            if reps >= 1 && rem == 0 {
                let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
                score -= (5.0 + 6.0 * scarcity) * ((reps as f64).min(3.0)) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        // MUTATION (gen 65): variance-damping tiebreak — mildly prefer
        // post residuals near the geometric midpoint of mean and capacity,
        // reducing residual variance that causes late-stream dead space.
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 1 && progress > 0.25 {
            let target = 0.5 * (mean_residual + 0.5 * cap);
            let dev = ((post_residual as f64 - target).abs() / cap).min(0.5);
            score += 2.4 * dev * (progress - 0.25);
        }
        // MUTATION (gen 68): near-miss dead-band penalty — residuals that
        // barely fail to fit the next item (miss by a small margin) are the
        // most damaging kind of dead space; penalize proportionally to how
        // close the miss is, weighted by aggregate open slack, so placements
        // that shave a bin just below the next item's size are avoided.
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            let miss = (next_item_size - post_residual) as f64;
            if miss <= 12.0 && miss > 0.0 {
                let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
                let comp_slack = (mean_residual / cap).min(1.0);
                score += (14.0 - 0.8 * miss) * scarcity * comp_slack * (0.45 + 0.55 * progress);
            }
        }
        // MUTATION (gen 68): half-capacity residual trap — residuals lingering
        // in the awkward 0.35–0.6 band of capacity tend to strand as dead
        // space late in the stream; add a mild penalty when the next item
        // cannot tile into them and aggregate slack exists elsewhere.
        if post_residual > 0
            && next_item_size > 0
            && fitting_bins_count > 1
            && (post_residual as f64) > 0.35 * cap
            && (post_residual as f64) < 0.6 * cap
        {
            let tileable = post_residual % next_item_size.max(1) == 0;
            if !tileable {
                let band_mid = 0.475 * cap;
                let depth = 1.0 - ((post_residual as f64 - band_mid).abs() / (0.125 * cap)).min(1.0);
                score += 5.5 * depth * (0.5 + 0.5 * progress);
