pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    let dead = post_residual as f64;

    // Penalize small but awkward leftovers (dead space that few future items can use).
    if dead > 0.0 && dead < 10.0 {
        score += (10.0 - dead) * 2.5;
    } else if dead >= 10.0 && dead < 20.0 {
        score += (20.0 - dead) * 0.6;
    }

    // Reward tight fits (high fill ratio).
    score -= fit_ratio * 12.0;

    // Lookahead: if next item can use this bin's leftover, reward; if leftover is
    // useless for the next item, penalize slightly.
    if next_item_size > 0 {
        if (post_residual as f64) >= next_item_size as f64 {
            score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            score += 4.0;
        }
        // Perfect chain: item + next fill bin nearly exactly.
        if item_size + next_item_size == bin_residual {
            score -= 15.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 10.0;
    }

    // New-bin candidate handling.
    if is_new_bin {
        // Opening a new bin is fine early or when existing fits are poor.
        let poor_fit = fit_ratio < 0.55 && dead > 25.0;
        if fitting_bins_count > 1 && !poor_fit {
            score += 30.0 + 10.0 * (1.0 - progress);
        } else {
            score -= 8.0 * progress;
        }
        // Many open bins with slack: prefer reusing them.
        if mean_residual > 30.0 && open_bins_count > 2 {
            score += 12.0;
        }
    }

    // Late stream: consolidate aggressively, avoid sprawl.
    if progress > 0.7 && !is_new_bin {
        score -= 3.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
    }

    // Mild preference for bins below mean residual (balance + big-slot preservation).
    if (bin_residual as f64) > mean_residual && !is_new_bin {
        score += 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
