    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Base: post-residual, with non-linear polynomial coupling to stream progress.
    let mut score = pr * (1.0 + 0.5 * progress * (1.0 - x)) + 40.0 * x * x * (1.0 - progress);

    // Reward tight fits: small post-residual gets a smooth cubic discount.
    score -= 30.0 * (1.0 - x) * (1.0 - x) * (1.0 - x) * (0.5 + 0.5 * progress);

    // Penalize dead space relative to mean residual (smooth quadratic coupling).
    let dead = (x * cap - mean_residual) / cap;
    score += 15.0 * dead * dead;

    // Last-chance bin: smooth bonus scaled by progress.
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - progress) + 6.0;
