        // Mid-stream fresh-bin guard — extend refusal into mid-stream when
        // aggregate open slack can plausibly absorb the remaining demand.
        if remaining_frac >= 0.15 && remaining_frac < 0.45 && fresh_post > 0.4 * cap && fragmentation > 0.4 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.45;
            if open_space > est_need {
                score += 28.0 * (1.0 - remaining_frac / 0.45);
            }
        }
        // Tiling-aware fresh-bin bonus — a new bin whose post residual is an
        // exact multiple of the next item size becomes a consolidation anchor.
        if next_item_size > 1 && fresh_post > 0.0 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 2 && rem == 0 && fragmentation < 0.4 {
                score -= 10.0 * ((reps as f64).min(4.0) - 1.0) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        // Extended mid-late refusal band.
        if remaining_frac >= 0.45 && remaining_frac < 0.5 && fresh_post > 0.45 * cap && fragmentation > 0.5 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.55;
            if open_space > est_need {
                score += 22.0 * (1.0 - remaining_frac / 0.5);
            }
        }
        // MUTATION (gen 70): late-stream hard refusal — when open slack
        // comfortably covers remaining demand in the final quarter, block
        // new-bin opens almost entirely to squeeze the tail waste.
        if remaining_frac < 0.25 && fresh_post > 0.2 * cap {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.6;
            if open_space > est_need * 1.2 {
                score += 90.0 * (1.0 - remaining_frac / 0.25);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: bins whose post_residual falls into
    // "small residue" classes are near-perfectly packed; reward them strongly.
    let residue_class = post_residual % 10;
    if post_residual == 0 {
        score -= 500.0; // perfect fit: best possible outcome
    } else if residue_class == 0 {
        score -= 120.0; // residue is a clean multiple of 10: highly reusable
    } else if residue_class <= 3 {
        score += 60.0 * (4 - residue_class) as f64; // tiny dead space, nearly unusable
    } else if residue_class <= 6 {
        score -= 30.0; // medium residue class, decent reusability
    } else {
        score -= 70.0; // large residue class (7..9): very reusable
    }

    // Integer-division threshold on post_residual: how many "typical" small
    // items (size ~20) could still fit? More slots => better bin.
    let slots = post_residual / 20;
    score -= 25.0 * slots as f64;

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // this placement chains perfectly; reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size <= post_residual {
            score -= 40.0;
            // harmonic match: next item's residue class aligns with leftover
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 60.0;
            }
        } else {
            // next item cannot use this bin's leftover: penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: opening a fresh bin is only attractive when the item
    // is large relative to capacity or open-bin residuals are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - post_residual as f64).abs();
        let large_item = (item_size as f64 / bin_capacity as f64) > 0.6;
        if large_item && fragmentation > 15.0 {
            score -= 100.0; // big item + fragmented bins: fresh bin is fine
        } else {
            score += 80.0 + 60.0 * (1.0 - progress); // early stream: reuse open bins
        }
    }

    // Mild preference for bins already below mean residual (consolidate waste).
    if (bin_residual as f64) < mean_residual {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Layered dead-space rewards (lower post_residual = better).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 4 {
