    } else {
        score -= 1.2 - 0.014 * (post_residual as f64 - 48.0);
    }

    // Progress-scaled tightening.
    let w = 0.33 + 0.67 * progress * progress;
    score *= w;

    // Lookahead coupling with next item.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 8.0 {
                score -= 135.0 - 2.3 * slack;
            } else {
                score -= 72.0 - 0.58 * slack;
            }
            if slack <= 3.0 {
                score -= 48.0;
            }
            // Tiling: residual divisible by next item => zero-waste chain.
            let reps = post_residual / next_item_size;
            if post_residual % next_item_size == 0 && reps >= 1 {
                let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
                score -= (5.0 + 6.0 * scarcity) * (reps.min(3) as f64) * (0.4 + 0.6 * (1.0 - progress));
            }
        } else {
            let miss = (next_item_size - post_residual) as f64;
            score += 0.95 * miss;
            if miss > 26.0 {
                score += 0.55 * (miss - 26.0);
            }
            // Stranded residual weighted by scarcity.
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            if miss <= 10.0 {
                score += (8.5 + 1.1 * (10.0 - miss)) * scarcity * (0.4 + 0.6 * (1.0 - progress));
            }
        }
    }

    // Two-step exact fill.
    if next_item_size > 0 {
        let two_step = item_size + next_item_size;
        if two_step == bin_capacity {
            score -= 800.0;
        } else if two_step <= bin_capacity && bin_capacity - two_step <= 10 {
            score -= 200.0;
        }
    }

    // Mean-residual harmony.
    score += 0.5 * (post_residual as f64 - mean_residual);
    if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 1 {
        let harmony = (post_residual as f64 - mean_residual).abs() / cap;
        if harmony < 0.08 {
            score -= 9.0 * (1.0 - harmony / 0.08) * (0.5 + 0.5 * (1.0 - progress));
        }
