            let reachable = (next_item_size as f64 / fresh_post).min(1.0);
            if reachable < 0.5 {
                score += 18.0 * (0.5 - reachable) * (1.0 - progress);
            }
        }
        if next_item_size > 0 && fresh_post > 0.0 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 2 && fragmentation < 0.5 {
                score -= 7.0 * ((reps as f64).min(4.0) - 1.0) * (0.4 + 0.6 * (1.0 - progress));
                if rem <= 3 {
                    score -= 5.0 * (1.0 - progress);
                }
            }
        }
        if fresh_post > 0.35 * cap && remaining_frac > 0.2 && mean_residual * open_bins_count as f64 > 4.0 * cap && fragmentation < 0.45 {
            score += 20.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        if remaining_frac < 0.15 && fresh_post > 0.3 * cap {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.35;
            if open_space > est_need {
                score += 55.0 * (1.0 - remaining_frac / 0.15);
            }
        }
        // Gen-55 mid-stream fresh-bin guard.
        if remaining_frac >= 0.15 && remaining_frac < 0.45 && fresh_post > 0.4 * cap && fragmentation > 0.4 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.45;
            if open_space > est_need {
                score += 28.0 * (1.0 - remaining_frac / 0.45);
            }
        }
        // Gen-65 tiling-aware fresh-bin bonus.
        if next_item_size > 1 && fresh_post > 0.0 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 2 && rem == 0 && fragmentation < 0.4 {
                score -= 10.0 * ((reps as f64).min(4.0) - 1.0) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        // Gen-65 tightened mid-stream guard band.
        if remaining_frac >= 0.45 && remaining_frac < 0.5 && fresh_post > 0.45 * cap && fragmentation > 0.5 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.55;
            if open_space > est_need {
                score += 22.0 * (1.0 - remaining_frac / 0.5);
            }
        }
        // MUTATION (gen 71): fresh-bin orphan-band guard — refuse opening a
        // new bin whose post residual would strand a sub-0.35*next tail after
        // one more item, unless fragmentation is high (then the fresh bin is
        // still the better anchor). Mirrors the open-bin orphan-band penalty.
        if next_item_size > 0 && fresh_post > 0.0 && (fresh_post as u32) >= next_item_size {
            let fp = fresh_post as u32;
            let n = next_item_size;
            let tail = fp - n;
            if fp < 2 * n && tail > 0 && tail * 100 < 35 * n && fragmentation < 0.5 && remaining_frac > 0.1 {
                score += 14.0 * (1.0 - tail as f64 / (0.35 * n as f64)) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic penalty on wasted space ratio.
    let waste_ratio = post_residual as f64 / cap;
    score += 20.0 * waste_ratio * waste_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Lookahead: reward if next item fits the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 * (next_item_size as f64 / cap);
        } else {
            // Dead space penalty scaled by how unusable the leftover is.
            let gap = next_item_size as f64 - post_residual as f64;
            score += 0.35 * gap;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Slight penalty when many alternatives exist, to keep flexibility.
        score += 1.5 * (fitting_bins_count as f64 - 1.0);
    }

    // Prefer bins with below-average residual (fill emptier-ish bins first,
    // keep high-residual bins flexible for large items).
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Time horizon: early in stream, be conservative about opening new bins;
    // late in stream, prefer tighter packing.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (1.0 - waste_ratio);

    // New-bin candidate: penalize opening a new bin unless the item fits
    // poorly in existing bins (large item or no good alternative).
    if bin_residual == bin_capacity {
        let base_penalty = 18.0 + 0.15 * open_bins_count as f64;
        let relief = if item_size > 60 { 14.0 } else { 0.0 };
        let fit_relief = if fitting_bins_count == 0 { 20.0 } else { 0.0 };
        score += base_penalty - relief - fit_relief;
    }

    // Mild preference for keeping the count of open bins low.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
