        // residuals near the midpoint of mean residual and half capacity,
        // reducing residual variance that causes late-stream dead space.
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 1 && progress > 0.25 {
            let target = 0.5 * (mean_residual + 0.5 * cap);
            let dev = ((post_residual as f64 - target).abs() / cap).min(0.5);
            score += 2.4 * dev * (progress - 0.25);
        }
        // MUTATION (gen 74): two-item exact-chain lookahead — when placing
        // here leaves exactly enough room for next_item AND a small tail,
        // and few bins can host next_item, lock in the chain.
