        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer tight fits (small post_residual), with non-linear emphasis
    let mut score = post * (1.0 + 0.8 * (post / cap) * (post / cap));

    // Penalize creating dead space that no plausible item could use
    let waste = post / cap;
    score += 25.0 * waste * waste * (1.0 - progress);

    // Lookahead coupling: reward if next item fits the post_residual well
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_ratio = nxt / post.max(1.0);
        if fit_ratio <= 1.0 {
            // Perfect-ish follow-up fit: strong reward
            score -= 30.0 * (1.0 - fit_ratio) * (1.0 - progress * 0.5);
        } else {
            // Next item won't fit: mild penalty proportional to leftover gap
            score += 8.0 * (fit_ratio - 1.0).min(1.0) * (post / cap);
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when nothing fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Penalize opening a new bin, more so when other bins fit and stream is late
        let penalty = 35.0 + 40.0 * progress + 5.0 * (fitting_bins_count as f64);
        score += penalty;
        // But reward slightly if current item is huge (poor fit anywhere)
        score -= (item / cap) * 20.0;
    } else {
        // Reward using existing bins, especially when many bins are open
        score -= 5.0 + 0.5 * (open_bins_count as f64).ln().max(0.0);
    }

    // Mean-residual alignment: prefer bins whose residual is near the mean (balance)
    let dev = (post - mean_residual).abs();
    score += 3.0 * (dev / cap) * (1.0 - progress);

    // Smooth progress interaction: tighten packing as stream progresses
    score *= 1.0 + 0.15 * progress * (post / cap);

    score
}

