                let band = 1.0 - remaining_frac / 0.5;
                score += 14.0 * band * (fresh_post / cap - 0.3).min(0.5);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo-10 classes map to "usability" tiers.
    let cls = post_residual % 10;
    let class_penalty = match cls {
        0 => -6.0,               // perfect decade residual: highly reusable
        1 | 2 => 2.0,            // sliver residuals: nearly dead space
        3..=6 => 0.0,            // mid-range, average utility
        7 | 8 => -1.5,           // can host small items well
        _ => 3.0,                // residual 9: worst dead space class
    };
    score += class_penalty;

    // Integer-division thresholds: how many "small items" (size <= 10) still fit.
    let small_slots = post_residual / 10;
    score -= 2.0 * small_slots as f64;

    // Lookahead coupling: harmonic class match between post_residual and next item.
    if next_item_size > 0 {
        let gap = post_residual as i64 - next_item_size as i64;
        if gap == 0 {
            score -= 8.0; // perfect fit for the next item
        } else if gap > 0 && (gap as u32) < 10 {
            score -= 3.0; // next item fits with tiny waste
        } else if gap < 0 && (-(gap) as u32) <= 10 {
            score += 4.0; // near-miss wastes the bin for lookahead
        }
        // modulo harmony: post_residual and next_item_size share a residue class
        if post_residual % 10 == next_item_size % 10 && post_residual >= next_item_size {
            score -= 2.5;
        }
    }

    // Last-chance bonus: only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 7.0;
    }

    // Penalize fragmenting a large residual when many bins are open.
    if post_residual > 0 && post_residual < 10 {
        score += 5.0 * (open_bins_count as f64).sqrt();
    }

    // Progress-scaled tightness reward: later in stream, favor tight fits more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - post_residual as f64 / bin_capacity as f64) * (4.0 + 4.0 * progress);

    // Alignment with mean residual: prefer bins close to the mean (balanced packing).
    score += 0.15 * (post_residual as f64 - mean_residual).abs();

    // New-bin candidate: only attractive when current item leaves awkward residue
    // or when open bins are nearly full on average.
    if bin_residual == bin_capacity {
        let awkward = (item_size % 10 != 0) as i32 as f64;
        let crowded = (mean_residual < 15.0) as i32 as f64;
        score = 60.0 + 10.0 * awkward - 8.0 * crowded - 6.0 * progress
            + if next_item_size > 0 && next_item_size >= bin_capacity { -12.0 } else { 0.0 };
    }

    score
}

