        if fitting_bins_count == 1 && !fresh_is_exact {
            score += 90.0 * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: hard penalty when post_residual falls into
    // an "unusable gap" (too small for typical future items, but nonzero).
    if post_residual > 0 {
        // Gap threshold: gaps below ~1/3 of capacity are likely dead space.
        let dead_threshold = bin_capacity as f64 / 3.0;
        if (post_residual as f64) < dead_threshold {
            // Non-linear blow-up of penalty as gap shrinks toward zero.
            let tightness = 1.0 - (post_residual as f64) / dead_threshold;
            score += 60.0 * tightness * tightness;
        }
        // Perfect fit is heavily rewarded.
        if post_residual == 0 {
            score -= 40.0;
        }
    }

    // Reward leaving room for the lookahead item (k=2 lookahead).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            // Post residual can't host next item: mild penalty scaled by how close we are.
            score += 6.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Open-bin pressure: penalize using bins when many are already open,
    // encouraging consolidation into fewer bins when possible.
    score += 2.0 * open_bins_count as f64;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: neutral-ish baseline so it's chosen only when
    // all open bins have poor fits (their dead-space penalties dominate).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, reduced when few bins are open
        // (early stream) or when mean residual across open bins is large
        // (existing bins are fragmented anyway).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_score = 45.0 + 20.0 * progress;
        // If open bins are highly fragmented (large mean residual relative to item),
        // opening fresh is less costly.
        if mean_residual > item_size as f64 {
            new_bin_score -= 8.0;
        }
        // Slight preference for new bin when the item would leave a tiny gap elsewhere.
        score = new_bin_score + (post_residual as f64 - bin_capacity as f64) * 0.0;
        // Keep full-capacity residual scoring neutral for the new bin.
        score += 0.0;
    }

    // Small nudge: prefer bins whose residual is close to item size (tight fit)
    let tight_fit = 1.0 - ((bin_residual - item_size) as f64 / bin_capacity as f64);
    score -= 5.0 * tight_fit * tight_fit;

    score
}

