            score += 16.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong penalty for creating dead space that no plausible item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // 2-step lookahead: reward a perfect chain (next item exactly fills post_residual).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size <= post_residual {
            // Reward fit, scaled by how tightly the chain packs.
            score -= 40.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize proportional to the leftover gap.
            score += 0.35 * (next_item_size - post_residual) as f64;
        }
    }

    // Compare residual against mean residual across open bins: prefer using
    // bins that are already tighter than average (avoid fragmenting many bins).
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: mild penalty so we prefer reusing open bins unless
    // the lookahead above makes a fresh bin genuinely better.
    if bin_residual == bin_capacity {
        score += 15.0;
        // Opening a new bin is more attractive early in the stream when many
        // items remain to be packed (future flexibility).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
        // Discard hoarding: too many open bins relative to remaining items.
        if open_bins_count as f64 > (total_items - step_index) as f64 {
            score += 30.0;
        }
    }

    // Prefer filling larger items into tighter bins (perfect-fit affinity).
    score -= 0.1 * item_size as f64 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
