        if remaining_frac >= 0.45 && remaining_frac < 0.5 && fresh_post > 0.45 * cap && fragmentation > 0.5 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.55;
            if open_space > est_need {
                score += 22.0 * (1.0 - remaining_frac / 0.5);
            }
        }
        // MUTATION (gen 76): demand-aware fresh-bin refusal — compare the
        // aggregate open slack against a size-weighted estimate of the
        // remaining demand using the mean item footprint implied by the
        // next item, rather than the current item only; refuse opens when
        // slack comfortably covers the projected need across the whole
        // stream, further cutting variance-driven spurious opens.
        if remaining_frac >= 0.05 && fresh_post > 0.3 * cap && next_item_size > 0 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (next_item_size as f64) * 0.42;
            if open_space > 1.25 * est_need {
                score += 30.0 * (1.0 - remaining_frac) * (fresh_post / cap - 0.3);
            }
        }
        // MUTATION (gen 76): fresh-bin dead-space cap — when the fresh bin
        // would leave a large residual that the next item cannot use and
        // open bins are not fragmented, opening here creates pure dead
        // space; penalize proportionally to the unusable magnitude.
        if fresh_post > 0.35 * cap && next_item_size > 0 && (fresh_post as u32) < next_item_size && fragmentation < 0.4 && remaining_frac > 0.15 {
            score += 16.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        // MUTATION (gen 77): fresh-bin tiling depth bonus — when the fresh
        // residual tiles the next item with zero remainder and at least two
        // repetitions, this bin is a guaranteed zero-waste chain; deepen the
        // existing tiling bonus when open slack is scarce, so such opens
        // happen exactly when they eliminate future dead space.
        if next_item_size > 1 && fresh_post > 0.0 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 2 && rem == 0 {
                let open_space = mean_residual * open_bins_count as f64;
                let scarcity = 1.0 / (1.0 + open_space / cap);
                score -= 8.0 * ((reps as f64).min(4.0) - 1.0) * scarcity * (0.5 + 0.5 * (1.0 - progress));
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor placements that leave little waste.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Lookahead: reward if the next item can also fit in the resulting residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_quality = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 18.0 * chain_quality;
    }
    // Penalize residuals that are too small for the known next item (dead space).
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += 8.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Among many candidates, prefer the ones that fit well (handled above), slight penalty to spread.
        score += 3.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: bin_residual == bin_capacity means an empty bin.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Opening a new bin is attractive when few bins fit the item or the item is large
        // (would leave a large awkward residual in existing bins).
        let large_item_pressure = item_size as f64 / bin_capacity as f64;
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 1.0 / (1.0 + fitting_bins_count as f64) };
        let early = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let open_bonus = (open_bins_count as f64).ln().max(0.0);
        let new_bin_bias = 30.0 - 25.0 * scarcity - 20.0 * large_item_pressure - 5.0 * early + open_bonus;
        score += new_bin_bias;
    }

    // Global state coupling: if mean residual is high, encourage consolidating into fuller bins
    // (a bin whose post_residual is well below mean residual is a good consolidation target).
    let gap = mean_residual - post_residual as f64;
    if gap > 0.0 {
        score -= 4.0 * gap / bin_capacity as f64;
    } else {
        score += 4.0 * (-gap) / bin_capacity as f64;
    }

    score
}

