        // it converts dead space into scheduled capacity; deepen the exact
        // tiling reward and extend it to fragmentation < 0.5.
        if next_item_size > 1 && fresh_post > 0.0 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 2 && rem == 0 && fragmentation < 0.5 {
                score -= 14.0 * ((reps as f64).min(4.0) - 1.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // MUTATION (gen 78): large-item fresh-bin necessity — when the item
        // barely exceeds what any open bin can hold (mean residual below
        // item size and no fitting bins), opening a fresh bin is mandatory
