            }
        }
        // MUTATION (gen 78): residual-window sharpening — when the leftover
        // residual sits in the awkward mid-band (just above next_item_size
        // but too large to be consumed by tiling), penalize it in proportion
        // to the wasted span, cutting the residual variance that causes
        // fragmented dead space late in the stream.
