        if next_item_size > 1 && fresh_post > 0.0 && (fresh_post as u32) >= next_item_size && remaining_frac > 0.2 {
            let rem = (fresh_post as u32) % next_item_size;
            let reps = (fresh_post as u32) / next_item_size;
            if rem <= 2 && reps >= 1 && fragmentation < 0.5 {
                score -= 8.0 * (1.0 - rem as f64 / 2.0) * (1.0 - remaining_frac) * ((reps as f64).min(3.0));
            }
