        // the diagnosed dead-space weakness by converting opens into
        // guaranteed-complete fills.
        if next_item_size > 1 && fresh_post > 0.0 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if rem == 0 && reps >= 1 && reps <= 4 && fragmentation < 0.55 {
                score -= 8.0 * (reps as f64) * (1.0 - remaining_frac) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
