    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: quadratic waste with stream-progress sharpening
    let mut score = norm_pr * norm_pr * (1.0 + 2.0 * progress) * cap * 0.5 + pr * 0.01;

    // Smooth progress-coupled interaction: waste penalized more as stream advances
    let coupling = (progress * std::f64::consts::PI).sin().abs();
    score += norm_pr * coupling * cap * 0.05;

    // Reward tight fits (small post_residual) increasingly over time
    score -= (1.0 - norm_pr).powi(3) * (1.0 + progress) * 5.0;

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + 5.0 * progress;
    }

    // New-bin candidate: penalize unless the item fits poorly everywhere else
    if bin_residual == bin_capacity {
        let poor_fit = (item_size as f64 / cap) < 0.5;
        let lookahead_bad = next_item_size > 0 && (next_item_size as f64) > pr;
        score += 8.0;
        if poor_fit { score -= 3.0; }
        if lookahead_bad { score -= 2.0; }
