    // Lookahead synergy: prefer leaving residual close to next item size
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score += (gap / cap) * 3.0;
    }

    // Mild pressure against bin sprawl early on
    score += (open_bins_count as f64).ln().max(0.0) * (1.0 - progress) * 0.3;

    // Mean-residual alignment bonus
    score -= (mean_residual - pr).abs() * 0.02;

    score
}

