        // MUTATION (gen 80): fresh-bin mean-harmony bonus — when the fresh
        // residual lands very close to the current mean residual, the new
        // bin can later be consolidated with the existing pool; deepen the
        // existing fresh_match direction with a mid-band reward.
        if fresh_post > 0.0 && fresh_match < 0.2 && fragmentation >= 0.2 && remaining_frac > 0.1 {
            score -= 14.0 * (1.0 - fresh_match / 0.2) * (0.4 + 0.6 * (1.0 - progress));
        }
        // MUTATION (gen 80): tiling-deepened refusal — when the fresh
        // residual is neither tileable by the next item nor close to the
        // mean, and open slack dominates projected demand, add a mild
        // extra push against opening, complementing the demand-aware
        // refusal band with a magnitude-proportional term.
        if next_item_size > 0 && fresh_post > 0.25 * cap && remaining_frac > 0.2 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (next_item_size as f64) * 0.5;
            let tileable = (fresh_post as u32) % next_item_size == 0;
            if open_space > est_need && !tileable {
                score += 10.0 * (fresh_post / cap - 0.25) * (1.0 - remaining_frac);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let res = post_residual as f64;
    let mut score = res;

    // Reward tight packing (large filled fraction of the bin).
    score -= (cap - res) / cap * 20.0;

    // Perfect fit: strongest reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Dead-space penalty: residual too small to plausibly hold another item.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead coupling: strongly favor bins whose residual can host the next item.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0 + next_item_size as f64 * 0.1;
    } else if next_item_size > 0 {
        // Next item cannot follow into this bin: mild penalty scaled by wasted potential.
        score += 3.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // New-bin candidate (empty bin): penalize so we only open when fits are poor.
    if bin_residual == bin_capacity {
        score += 25.0 - res * 0.05;
        // But if the item is huge relative to capacity, a fresh bin is natural.
        if item_size as f64 > 0.8 * cap {
            score -= 15.0;
        }
    }

    // Harmonic class logic: modulo classes on post_residual.
    // Residuals in friendly classes (multiples of 25) are more reusable.
    let class = post_residual % 25;
    if class == 0 {
        score -= 4.0;
    } else if class <= 5 {
        score += 2.0;
    }
    // Integer-division tier of residual: coarse capacity fractions.
    let tier = post_residual / 25; // 0..4
    score += tier as f64 * 1.5;

    // Prefer consolidating into bins when many bins are already open.
    score += open_bins_count as f64 * 0.3;

    // Slight drift with stream progression: later items favor tighter fits more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    // Mean-residual anchoring: bins far below mean residual are "lonely" space.
    score += (mean_residual - res).max(0.0) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
