pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward bins whose residual is "shaped" for the next item (lookahead k=2).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.15 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // gap that cannot host the next item: mild penalty scaled by gap uselessness
        score += 0.3 * (next_item_size as f64 - post_residual as f64).min(30.0);
    }

    // Open-bin pressure: with many open bins, prefer packing into existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).sqrt() * (2.0 + 6.0 * progress);
    if bin_residual != bin_capacity {
        score -= pressure;
    } else {
        // New-bin candidate: penalize proportionally to open-bin pressure,
        // but relax if this item fits poorly everywhere else.
        let mut new_bin_penalty = pressure;
        if fitting_bins_count == 0 || (fitting_bins_count == 1 && post_residual < 10) {
            new_bin_penalty *= 0.2;
        }
        score += new_bin_penalty;
    }

    // Prefer bins tighter than average (waste consolidation).
    score += 0.25 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Mild reward for filling large items into large-residual bins.
    score -= 0.05 * item_size as f64 * (bin_residual as f64 / bin_capacity as f64);

    score
}

