pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Penalize leftovers that are too small for the next item (dead space risk).
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Reward leftovers slightly larger than next item (good chain fit).
    if next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= slack.max(0.0).min(20.0) * 0.3;
    }

    // Compare against mean residual: prefer bins tighter than average.
    score += (mean_residual - post_residual as f64) * 0.2;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: only attractive when no good fit exists
    // (post_residual == capacity - item is "clean" but costs a bin).
    if bin_residual == bin_capacity {
        score += 120.0 + open_bins_count as f64 * 2.0;
    }

    // Early in stream: be conservative with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Layered dead-space avoidance: sharper gradient than parent, borrowed
    // from the leading heuristic's tier structure but re-weighted.
    if post_residual == 0 {
        score -= 420.0;
    } else if post_residual <= 4 {
        score -= 90.0 + 8.0 * (4 - post_residual) as f64;
    } else if post_residual <= 10 {
        score -= 24.0 + 4.2 * (10 - post_residual) as f64;
    } else if post_residual <= 22 {
        score -= 6.0 + 1.5 * (22 - post_residual) as f64;
    } else if post_residual <= 48 {
        score -= 1.5 + 0.22 * (48 - post_residual) as f64;
    } else {
        score += 0.25 * (post_residual as f64 - 48.0).sqrt();
    }

    // Lookahead: exact next-item match is a near-perfect two-step fill.
