        }
        if next_item_size > 0 && fresh_post > 0.0 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 2 && fragmentation < 0.5 {
                score -= 7.0 * ((reps as f64).min(4.0) - 1.0) * (0.4 + 0.6 * (1.0 - progress));
                if rem <= 3 {
                    score -= 5.0 * (1.0 - progress);
                }
            }
        }
        if fresh_post > 0.35 * cap && remaining_frac > 0.2 && mean_residual * open_bins_count as f64 > 4.0 * cap && fragmentation < 0.45 {
            score += 20.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        if remaining_frac < 0.15 && fresh_post > 0.3 * cap {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.35;
            if open_space > est_need {
                score += 55.0 * (1.0 - remaining_frac / 0.15);
            }
        }
        if remaining_frac >= 0.15 && remaining_frac < 0.45 && fresh_post > 0.4 * cap && fragmentation > 0.4 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.45;
            if open_space > est_need {
                score += 28.0 * (1.0 - remaining_frac / 0.45);
            }
        }
        if next_item_size > 1 && fresh_post > 0.0 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 2 && rem == 0 && fragmentation < 0.4 {
                score -= 10.0 * ((reps as f64).min(4.0) - 1.0) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        if remaining_frac >= 0.45 && remaining_frac < 0.5 && fresh_post > 0.45 * cap && fragmentation > 0.5 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.55;
            if open_space > est_need {
                score += 22.0 * (1.0 - remaining_frac / 0.5);
            }
        }
        // gen 76: demand-aware fresh-bin refusal.
        if remaining_frac >= 0.05 && fresh_post > 0.3 * cap && next_item_size > 0 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (next_item_size as f64) * 0.42;
            if open_space > 1.15 * est_need {
                score += 30.0 * (1.0 - remaining_frac) * (fresh_post / cap - 0.3);
            }
        }
        // gen 76: fresh-bin dead-space cap.
        if fresh_post > 0.35 * cap && next_item_size > 0 && (fresh_post as u32) < next_item_size && fragmentation < 0.4 && remaining_frac > 0.15 {
            score += 16.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        // gen 81: tileability-aware open.
        if next_item_size > 1 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 3 && rem == 0 && fragmentation < 0.3 {
                score -= 14.0 * ((reps as f64).min(5.0) - 2.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // MUTATION (gen 82): harvest-aware open — when the aggregate open
        // slack is already tight against remaining demand, a fresh bin whose
        // post-residual can absorb the next item (or an exact chain of it)
        // preserves harvestable slack; reward it more sharply mid-stream,
        // while keeping the late-stream refusal logic intact.
        if remaining_frac >= 0.1 && remaining_frac < 0.6 && next_item_size > 0 && fresh_post > 0.0 {
            let open_space = mean_residual * open_bins_count as f64;
            let remaining_f = remaining as f64;
            let est_need = remaining_f * next_item_size as f64 * 0.45;
            if open_space < 0.9 * est_need && (fresh_post as u32) >= next_item_size {
                score -= 10.0 * (0.9 - open_space / est_need.max(1.0)) * (fresh_post / cap) * (1.0 - progress);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap; // normalized post residual in [0,1]

    // Base: prefer small post residual, with smooth non-linear shaping.
    // Quadratic + cubic terms penalize large dead space super-linearly.
    let mut score = norm_pr * norm_pr * (1.0 + norm_pr) * cap;

    // Smooth coupling with stream progress: early on, be slightly tolerant of
    // residual space (more stream left to fill bins); late, penalize hard.
    let progress_coupling = 1.0 - 0.5 * (progress * std::f64::consts::PI).sin();
    score *= progress_coupling;

    // Interaction: post residual vs mean residual — prefer bins whose post
    // residual deviates smoothly below the mean (tightening the bin set).
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev - 6.0 * dev * (1.0 - progress);

    // Lookahead term: reward smooth alignment of post residual with next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt) / cap;
        // Smooth reward when post residual can host the next item exactly-ish.
        score -= 12.0 * (-40.0 * gap * gap).exp();
        // Extra smooth reward for near-perfect two-item packing.
        score -= 15.0 * (-80.0 * gap * gap).exp();
    } else {
        // Last item: drive post residual to zero smoothly.
        score += 20.0 * norm_pr;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // (smoothly scaled by how well it fits).
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_pr).max(0.0);
    }

    // Mild penalty for many open bins, encouraging consolidation as stream grows.
    score += 0.05 * open_bins_count as f64 * (1.0 + progress);

    // Slight preference for fuller bins overall (tightness reward).
    score -= 4.0 * (1.0 - norm_pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
