        if fresh_post > 0.0 && mean_residual > 0.0 && remaining_frac > 0.1 {
            let above = fresh_post - mean_residual;
            if above > 0.0 && above < 0.18 * cap {
                score -= 14.0 * (1.0 - above / (0.18 * cap)) * (1.0 - progress);
            }
        }
    }

    score
}

