        // gen 81: dead-space compaction gradient (gen 83: sharpen the
        // fraction weighting so near-zero leftovers are punished hardest
        // and widen the slack trigger to 1.6x cap).
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
            && fitting_bins_count > 1 {
            let open_space = mean_residual * open_bins_count as f64;
            if open_space > 1.6 * cap {
                let frac = post_residual as f64 / next_item_size as f64;
                score += 12.5 * (1.0 - frac) * (1.0 - frac) * (0.5 + 0.5 * progress);
            }
        }
        // gen 81: consolidation pull (gen 83: extend earlier to progress
        // > 0.35 with a ramp, further tightening residual spread).
        if post_residual > 0 && fitting_bins_count > 2 && progress > 0.35 {
            let fill = 1.0 - post_residual as f64 / cap;
            score -= 5.0 * fill * (progress - 0.35);
        }
        // MUTATION (gen 83): two-step tiling lookahead — when placing here
        // leaves a residual that exactly fits next_item_size twice with no
        // remainder, this bin absorbs three consecutive items perfectly;
        // reward scaled by scarcity of fitting bins.
        if next_item_size > 1 && post_residual > 0
            && post_residual == 2 * next_item_size && fitting_bins_count <= 3 {
            score -= 8.0 * (1.0 / fitting_bins_count.max(1) as f64) * (0.5 + 0.5 * (1.0 - progress));
        }
    } else {
        let fragmentation = (mean_residual / cap) * open_bins_count as f64;
        let huge_item = item_size as f64 > 0.7 * cap;
        let remaining = if total_items > step_index { total_items - step_index } else { 1 };
        let remaining_frac = remaining as f64 / total_items.max(1) as f64;
        let fresh_post = cap - item_size as f64;
        let fresh_is_exact = fresh_post <= 4.0 && fresh_post >= 0.0;

        if fragmentation > 0.55 || (huge_item && open_bins_count > 4) {
