            }
        }
        // Overshoot spreading refinement.
        if post_residual > 0 && next_item_size > 0 && fitting_bins_count > 3 {
            let overshoot = post_residual.saturating_sub(next_item_size) as f64;
            if overshoot > 16.0 {
                score += 1.6 * ((overshoot - 16.0) / cap).min(0.25) * 100.0 * 0.01 * (1.0 - progress);
            }
        }
        // Dead-ratio gradient tightened: absolute dead space punished alongside ratio.
        if fitting_bins_count > 1 && dead_ratio > 0.08 && post_residual > 0 {
            let scarcity = 1.0 / (fitting_bins_count as f64);
            let comp_slack = (mean_residual / cap).min(1.0);
            score += 6.5 * (dead_ratio - 0.08) * scarcity * comp_slack * (0.5 + 0.5 * (1.0 - progress));
            score += 2.2 * (dead / cap) * scarcity * comp_slack * (1.0 - progress);
        }
        // Residual-magnitude tiebreaker: prefer the residual closest to the mean.
        if fitting_bins_count > 2 && post_residual > 0 && mean_residual > 0.0 {
            let dev = ((post_residual as f64 - mean_residual).abs() / cap).min(0.4);
            score += 5.0 * dev * (1.0 - progress);
        }
        // Exact-fit ladder — round residuals are reusable by common sizes.
        if post_residual > 0 && post_residual % 10 == 0 && post_residual <= 60 && next_item_size > 0 && next_item_size <= post_residual {
            score -= 4.0 * (1.0 - progress) * (1.0 - post_residual as f64 / 120.0);
        }
        // Triple-fill planning — post_residual hosts next_item plus a small
        // companion; reward when bins are scarce.
        if next_item_size > 0 && post_residual > next_item_size && fitting_bins_count <= 3 {
            let tail = post_residual - next_item_size;
            if tail >= 1 && tail <= 12 {
                score -= 9.0 * (1.0 - tail as f64 / 12.0) * (1.0 - progress);
            }
        }
        // Protect the unique best fit for next_item when many bins are open.
        if next_item_size > 0 && post_residual == next_item_size && open_bins_count > 5 {
            score -= 14.0 * (0.4 + 0.6 * (1.0 - progress));
        }
        // Mid-band residual discount — 16..=28 residuals are highly reusable.
        if post_residual >= 16 && post_residual <= 28 && progress < 0.7 && fitting_bins_count > 1 {
            score -= 7.0 * (1.0 - (post_residual - 16) as f64 / 12.0) * (0.5 + 0.5 * progress);
        }
        // Dead-space compaction coupling — reward consolidation near the mean.
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 1 {
            let match_mean = 1.0 - ((post_residual as f64 - mean_residual).abs() / cap);
            if match_mean > 0.9 {
                score -= 5.0 * (match_mean - 0.9) * 10.0 * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // Waste-avoidance gradient — penalize dead space beyond next item's need.
        if next_item_size > 0 && post_residual > next_item_size && fitting_bins_count > 1 {
            let excess = (post_residual - next_item_size) as f64;
            if excess > 12.0 {
                score += 1.8 * ((excess - 12.0) / cap).min(0.3) * 100.0 * 0.01 * (1.0 - progress) * (fitting_bins_count as f64).min(4.0);
            }
        }
        // Tight-fit scarcity escalation.
        if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 4 {
            let gap_after = (post_residual - next_item_size) as f64;
            let urgency = (4.0 - fitting_bins_count as f64) / 3.0;
            score -= 10.0 * urgency * (1.0 - gap_after / cap) * (0.5 + 0.5 * (1.0 - progress));
        }
        // Mean-residual drain coupling.
        if post_residual > 0 && mean_residual > 0.0 && open_bins_count > 3 {
            let below = mean_residual - post_residual as f64;
            if below > 0.25 * cap && progress < 0.75 {
                score += 6.0 * (below / cap) * (1.0 - progress);
            }
        }
        // Squeeze-escalation ladder — preserve scarce "next-item-shaped" pockets.
        if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 6 {
            let tail = post_residual - next_item_size;
            let urgency = (6.0 - fitting_bins_count as f64) / 5.0;
            if tail == 0 {
                score -= 22.0 * urgency * (1.0 - progress);
            } else if tail <= 2 {
                score -= 9.0 * urgency * (1.0 - tail as f64 / 2.0) * (1.0 - progress);
            }
        }
        // Stranded-pair avoidance — don't consume the exact-host bin.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size
            && mean_residual > 0.0 && (mean_residual as u32) >= next_item_size && fitting_bins_count > 1 {
            score += 7.0 * (1.0 - progress);
        }
        // gen 63: waste-density term.
        if post_residual > 0 && next_item_size > 0 && fitting_bins_count > 1 {
            let usable = next_item_size <= post_residual
                || (mean_residual as u32) >= next_item_size;
            if !usable {
                let waste_frac = post_residual as f64 / cap;
                let late = 0.35 + 0.65 * progress;
                score += 9.0 * waste_frac * late;
            }
        }
        // gen 63: fill-level momentum.
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 2 {
            let rel = post_residual as f64 / (mean_residual + 1.0);
            if rel < 0.5 {
                score -= 6.0 * (1.0 - rel / 0.5) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        // gen 63: scarcity-weighted perfect-fit extension.
        if next_item_size > 0 && post_residual == next_item_size && fitting_bins_count <= 3 {
            score -= 30.0 / fitting_bins_count.max(1) as f64 * (0.5 + 0.5 * (1.0 - progress));
        }
        // gen 63: residual-variance dampener for the awkward 33..=47 band.
        if post_residual > 33 && post_residual < 47 && next_item_size > 0
            && next_item_size < post_residual && fitting_bins_count > 2 {
            score += 5.5 * (1.0 - progress);
        }
        // gen 83: tileable residual bonus — when post_residual is an exact
        // multiple of the next item, the bin becomes a tiling lane.
        if next_item_size > 1 && post_residual > 0 && post_residual >= next_item_size {
            let reps = post_residual / next_item_size;
            let rem = post_residual % next_item_size;
            if reps >= 1 && rem == 0 {
                let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
                score -= (5.0 + 6.0 * scarcity) * (reps as f64).min(3.0) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        // gen 83: late-stream target-deviation pull.
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 1 && progress > 0.25 {
            let target = 0.5 * (mean_residual + 0.5 * cap);
            let dev = ((post_residual as f64 - target).abs() / cap).min(0.5);
            score += 2.4 * dev * (progress - 0.25);
        }
        // gen 83: near-full chain extension.
        if post_residual > 0 && next_item_size > 0 && post_residual > next_item_size {
            let after_next = post_residual - next_item_size;
            if after_next > 0 && after_next < 6 && progress > 0.35 {
                score -= 11.0 * (1.0 - after_next as f64 / 6.0) * (progress - 0.35);
            }
        }
        // gen 83: unique-fit tightness bonus.
        if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count == 1 && bin_residual != bin_capacity {
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score -= 14.0 * (1.0 - progress) * (0.6 + 0.4 * tightness);
        }
        // gen 83: dead-space compaction gradient.
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
            && fitting_bins_count > 1 {
            let open_space = mean_residual * open_bins_count as f64;
            if open_space > 2.0 * cap {
                let frac = post_residual as f64 / next_item_size as f64;
                score += 10.0 * (1.0 - frac) * (0.5 + 0.5 * progress);
            }
        }
        // gen 83: consolidation pull.
        if post_residual > 0 && fitting_bins_count > 2 && progress > 0.5 {
            let fill = 1.0 - post_residual as f64 / cap;
            score -= 5.0 * fill * (progress - 0.5);
        }
        // MUTATION (gen 84): fine-grained residual fitting — reward placements
        // whose post-residual stays within a small absolute window of the next
        // item size, combining tight packing with lookahead anticipation.
        if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 4 {
            let proximity = 1.0 - (post_residual - next_item_size) as f64 / 4.0;
            score -= 8.0 * proximity * (0.4 + 0.6 * (1.0 - progress));
        }
        // MUTATION (gen 84): residual-variance dampener — late in the stream,
        // penalize post-residuals that deviate strongly from the mean open
        // residual, shrinking the spread of leftover space across bins.
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 2 && progress > 0.4 {
            let dev = ((post_residual as f64 - mean_residual).abs() / cap).min(0.5);
            score += 3.6 * dev * (progress - 0.4);
        }
        // MUTATION (gen 84): dead-space ratio penalty for very loose bins —
        // bins whose residual stays above 55% of capacity after placement
        // are flagged unless they can host the next item tightly.
        if post_residual > 0 && (post_residual as f64) > 0.55 * cap
            && next_item_size > 0 && (post_residual as u32) >= next_item_size
            && (post_residual - next_item_size) > 20 && fitting_bins_count > 1 {
            score += 6.0 * (post_residual as f64 / cap - 0.55) * (1.0 - progress);
        }
    } else {
        // NEW-BIN CANDIDATE branch.
        let fragmentation = (mean_residual / cap) * open_bins_count as f64;
        let huge_item = item_size as f64 > 0.7 * cap;
        let remaining = if total_items > step_index { total_items - step_index } else { 1 };
        let remaining_frac = remaining as f64 / total_items.max(1) as f64;
        let fresh_post = cap - item_size as f64;
        let fresh_is_exact = fresh_post <= 4.0 && fresh_post >= 0.0;

        if fragmentation > 0.55 || (huge_item && open_bins_count > 4) {
            score -= 66.0 + 46.0 * remaining_frac;
        } else if fresh_is_exact {
            score -= 134.0 + 66.0 * remaining_frac;
        } else {
            score += 400.0 - 82.0 * remaining_frac;
            if fitting_bins_count <= 3 && open_bins_count > 2 {
                score -= 30.0 + 18.0 * remaining_frac;
            }
        }

        let fresh_match = (fresh_post - mean_residual).abs() / cap;
        if fresh_match < 0.05 {
            score -= 76.0 * (1.0 - fresh_match / 0.05);
        }
        if remaining_frac < 0.05 && fresh_post > 0.0 && !fresh_is_exact {
            score += 160.0 * (fresh_post / cap);
        }
        if fresh_post > 0.0 && fresh_post <= 22.0 && !fresh_is_exact {
            score -= 26.0 * (1.0 - fresh_post / 22.0);
        }
        if fresh_post > 22.0 && fresh_post <= 40.0 && fragmentation < 0.35 {
            score -= 12.5 * (1.0 - (fresh_post - 22.0) / 18.0);
        }
        if fresh_post > 0.0 && fresh_match < 0.12 && fragmentation < 0.55 {
            score -= 30.0 * (1.0 - fresh_match / 0.12);
        }
        if next_item_size > 0 && fresh_post > 0.0 {
            let fresh_exact_next = (fresh_post as u32) == next_item_size;
            let open_can_next = mean_residual >= next_item_size as f64;
            if fresh_exact_next && !open_can_next && fitting_bins_count <= 2 {
                score -= 52.0 * (1.0 - progress);
            }
            if (fresh_post as u32) < next_item_size && mean_residual > next_item_size as f64 {
                score += 21.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && fresh_post > next_item_size as f64 {
            let chain_post = fresh_post - next_item_size as f64;
            if chain_post <= 4.0 {
                score -= 34.0 * (1.0 - chain_post / 4.0) * (0.5 + 0.5 * (1.0 - progress));
            } else if chain_post <= 10.0 {
                score -= 9.5 * (1.0 - (chain_post - 4.0) / 6.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        if remaining_frac < 0.12 && fresh_post > 0.0 && !fresh_is_exact && mean_residual * open_bins_count as f64 > 3.0 * cap {
            score += 42.0 * (1.0 - remaining_frac / 0.12);
        }
        // When only one open bin can fit and this item would leave a tiny
        // stranded residual there, opening a fresh bin is often better.
        if fitting_bins_count == 1 && fresh_post > 0.0 && next_item_size > 0 {
            let stranded_here = bin_capacity.saturating_sub(item_size);
            let would_strand = stranded_here < next_item_size;
            if would_strand && stranded_here > 0 && stranded_here <= 8 {
                score -= 32.0 * (1.0 - progress);
            }
        }
        // Open bins collectively nearly exhausted → keep density high.
        let open_capacity = mean_residual * open_bins_count as f64;
        let per_item_need = cap * 0.5;
        if remaining_frac > 0.25 && open_capacity < per_item_need * open_bins_count.max(1) as f64 * 0.5 {
            score -= 18.0 * (1.0 - progress);
        }
        // Fresh-bin chain quality.
        if next_item_size > 0 && fresh_post > next_item_size as f64 {
            let after_next = fresh_post - next_item_size as f64;
            if after_next > 0.0 && after_next <= 8.0 && fragmentation < 0.5 {
                score -= 20.0 * (1.0 - after_next / 8.0) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        // Avoid fresh bins whose residual is smaller than next_item when
        // open bins collectively have plenty of slack.
        if next_item_size > 0 && fresh_post > 0.0 && (fresh_post as u32) < next_item_size {
            let slack_total = mean_residual * open_bins_count as f64;
            if slack_total > 2.0 * cap {
                score += 26.0 * (1.0 - progress);
            }
        }
        // Fresh-bin exact-next bonus when fragmentation is moderate.
        if next_item_size > 0 && (fresh_post as u32) == next_item_size && fragmentation > 0.3 {
            score -= 44.0 * (0.5 + 0.5 * (1.0 - progress));
        }
        // Refuse very loose fresh bins when mean residual is tiny but many
        // bins are open — consolidation beats expansion.
        if fresh_post > 0.5 * cap && mean_residual < 0.2 * cap && remaining_frac > 0.3 && open_bins_count > 3 {
            score += 24.0 * (fresh_post / cap - 0.5) * 2.0 * (1.0 - progress);
        }
        // Single-fit guard.
        if fitting_bins_count <= 1 && fresh_post > 0.45 * cap && next_item_size > 0 {
            let reachable = (next_item_size as f64 / fresh_post).min(1.0);
            if reachable < 0.5 {
                score += 18.0 * (0.5 - reachable) * (1.0 - progress);
            }
        }
        // Fresh-bin reusable-tail bonus — residual a multiple of next_item.
        if next_item_size > 0 && fresh_post > 0.0 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 2 && fragmentation < 0.5 {
                score -= 7.0 * ((reps as f64).min(4.0) - 1.0) * (0.4 + 0.6 * (1.0 - progress));
                if rem <= 3 {
                    score -= 5.0 * (1.0 - progress);
                }
            }
        }
        // Fresh-bin two-item plan.
        if next_item_size > 0 && fitting_bins_count <= 2 && fresh_post > next_item_size as f64 {
            let tail = fresh_post - next_item_size as f64;
            if tail > 0.0 && tail <= 6.0 {
                score -= 28.0 * (1.0 - tail / 6.0) * (1.0 - progress);
            }
        }
        // Late-stream consolidation — prefer filling existing bins near the
        // end unless the fresh fit is near-exact.
        if progress > 0.8 && !fresh_is_exact && fresh_post > 8.0 && fitting_bins_count >= 1 {
            score += 20.0 * (progress - 0.8) / 0.2 * (fresh_post / cap);
        }
        // Aggregate-slack conservation — refuse a loose fresh bin when total
        // open slack already exceeds the expected need of remaining items.
        if remaining_frac > 0.15 && !fresh_is_exact && fresh_post > 0.35 * cap {
            let expected_need = remaining as f64 * (cap * 0.45);
            if open_capacity > expected_need {
                score += 22.0 * ((open_capacity - expected_need) / expected_need).min(1.0) * (1.0 - progress);
            }
        }
        // Fresh-bin scarcity gate.
        if fitting_bins_count == 0 && fresh_post > 0.0 {
            score -= 55.0 * (1.0 - fresh_post / cap) * (0.4 + 0.6 * (1.0 - progress));
        }
        // Fresh-bin mean-harmony.
        if fresh_post > 0.0 && mean_residual > 0.0 && open_bins_count > 2 && fresh_match < 0.25 {
            score -= 14.0 * (1.0 - fresh_match / 0.25) * (0.5 + 0.5 * (1.0 - progress));
        }
        // Fresh-bin dead-space cap — refuse long-term dead-space fresh bins.
        if fresh_post > 0.55 * cap && open_capacity > 3.0 * cap && remaining_frac > 0.2 {
            score += 30.0 * (fresh_post / cap - 0.55) * remaining_frac * (1.0 - progress);
        }
        // gen 63: mid-stream fresh-bin guard.
        if remaining_frac >= 0.15 && remaining_frac < 0.45 && fresh_post > 0.4 * cap && fragmentation > 0.4 {
            let est_need = (remaining as f64) * (item_size as f64) * 0.45;
            if open_capacity > est_need {
                score += 28.0 * (1.0 - remaining_frac / 0.45);
            }
        }
        // gen 63: late-stream refusal.
        if remaining_frac < 0.15 && fresh_post > 0.3 * cap {
            let est_need = (remaining as f64) * (item_size as f64) * 0.35;
            if open_capacity > est_need {
                score += 55.0 * (1.0 - remaining_frac / 0.15);
            }
        }
        // gen 63: fresh-bin residual-magnitude guard.
        if fresh_post > 0.35 * cap && remaining_frac > 0.2 && open_capacity > 4.0 * cap && fragmentation < 0.45 {
            score += 20.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        // gen 83: demand-aware fresh-bin refusal.
        if remaining_frac >= 0.05 && fresh_post > 0.3 * cap && next_item_size > 0 {
            let est_need = (remaining as f64) * (next_item_size as f64) * 0.42;
            if open_capacity > 1.15 * est_need {
                score += 30.0 * (1.0 - remaining_frac) * (fresh_post / cap - 0.3);
            }
        }
        // gen 83: fresh-bin dead-space cap.
        if fresh_post > 0.35 * cap && next_item_size > 0 && (fresh_post as u32) < next_item_size && fragmentation < 0.4 && remaining_frac > 0.15 {
            score += 16.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        // gen 83: tileability-aware open.
        if next_item_size > 1 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 3 && rem == 0 && fragmentation < 0.3 {
                score -= 14.0 * ((reps as f64).min(5.0) - 2.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // MUTATION (gen 84): fresh-bin lookahead chain quality — prefer a
        // fresh bin whose post-residual tightly hosts the next item with a
        // small tail, combining fine-grained fitting with two-step planning.
        if next_item_size > 0 && fresh_post > next_item_size as f64 {
            let tail = fresh_post - next_item_size as f64;
            if tail > 0.0 && tail <= 4.0 && fitting_bins_count > 1 {
                score -= 10.0 * (1.0 - tail / 4.0) * (1.0 - progress);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Layered dead-space rewards (lower post_residual = better).
    if post_residual == 0 {
        score -= 980.0;
    } else if post_residual <= 4 {
        score -= 250.0 + 4.2 * (4 - post_residual) as f64;
    } else if post_residual <= 10 {
        score -= 64.0 + 3.6 * (10 - post_residual) as f64;
    } else if post_residual <= 22 {
        score -= 13.5 + 1.5 * (22 - post_residual) as f64;
    } else if post_residual <= 32 {
        score -= 5.0 + 0.7 * (32 - post_residual) as f64;
    } else if post_residual <= 48 {
        score -= 1.2 + 0.22 * (48 - post_residual) as f64;
    } else {
        score -= 1.2 - 0.014 * (post_residual as f64 - 48.0);
    }

    let w = 0.33 + 0.67 * progress * progress;
    score *= w;

    // Lookahead coupling with the next item.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if next_item_size < post_residual {
            let two_step_waste = (post_residual - next_item_size) as f64;
            if two_step_waste <= 8.0 {
                score -= 135.0 - 2.3 * two_step_waste;
            } else {
                score -= 72.0 - 0.58 * two_step_waste;
            }
            if two_step_waste <= 3.0 {
                score -= 48.0;
            }
        } else {
            let miss = (next_item_size - post_residual) as f64;
            score += 0.95 * miss;
            if miss > 26.0 {
                score += 0.55 * (miss - 26.0);
            }
        }
    }

    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
        let boost = 36.0 + 26.0 * scarcity;
        score -= boost * (1.0 - slack / cap) * (0.6 + 0.4 * (1.0 - progress));
        if fitting_bins_count <= 2 {
            score -= 15.0 * (1.0 - slack / cap);
        }
        if slack == 0.0 {
            score -= 20.0 * (1.0 - progress);
        }
    }

    if bin_residual != bin_capacity {
        let dead = (bin_residual - item_size) as f64;
        let dead_ratio = dead / cap;
        if dead_ratio > 0.5 && fitting_bins_count > 1 {
            score += 10.5 * (dead_ratio - 0.5) * (1.0 - progress);
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
            && mean_residual > 0.0 && (mean_residual as u32) >= next_item_size {
            score += 12.0;
        }
        if post_residual > 12 && post_residual < 40 && next_item_size > post_residual {
            let orphan = (post_residual as f64 - 12.0) / 28.0;
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            score += 17.0 * orphan * scarcity * (0.5 + 0.5 * (1.0 - progress));
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let chain = post_residual % next_item_size.max(1);
            if chain == 0 {
                score -= 26.0 * (1.0 - progress);
            } else if chain <= 3 {
                score -= 11.0 * (1.0 - progress);
            }
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            let stranded = (next_item_size - post_residual) as f64;
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            if stranded <= 10.0 {
                score += (8.5 + 1.1 * (10.0 - stranded)) * scarcity * (0.4 + 0.6 * (1.0 - progress));
            } else {
                let proximity = 1.0 - (stranded - 10.0).min(cap) / cap;
                score += 3.2 * proximity * scarcity * (1.0 - progress);
            }
        }
        if dead_ratio > 0.35 && fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score += 7.5 * (dead_ratio - 0.35) * tightness * (1.0 - progress);
        }
        if post_residual > 0 && mean_residual > 0.0 {
            let gap = mean_residual - post_residual as f64;
            if gap > 0.0 && gap < 0.15 * cap && fitting_bins_count > 2 {
                score += 4.8 * (gap / (0.15 * cap)) * (1.0 - progress);
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size.max(1) && fitting_bins_count > 2 {
            score -= 6.5 * (1.0 - progress);
        }
        if post_residual == 0 && bin_residual < bin_capacity {
            score -= 42.0 * (1.0 - bin_residual as f64 / cap) * (1.0 - progress);
        }
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 1 {
            let harmony = (post_residual as f64 - mean_residual).abs() / cap;
            if harmony < 0.08 {
                score -= 9.0 * (1.0 - harmony / 0.08) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        if post_residual > 6 && post_residual <= 30 && next_item_size > 0 && next_item_size <= post_residual {
            let reps = post_residual / next_item_size.max(1);
            if reps >= 2 {
                score -= 3.5 * (reps as f64).min(4.0) * (1.0 - progress);
            }
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let after_next = post_residual - next_item_size;
            if after_next > 0 && after_next <= 12 {
                let tail = after_next as f64;
                score -= (14.0 - 0.9 * tail) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        if post_residual > 0 && post_residual < 6 && next_item_size > post_residual {
            score += 6.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let after_next = (post_residual - next_item_size) as f64;
            if after_next > 8.0 && after_next <= 16.0 && progress < 0.85 {
                let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
                score -= (4.0 + 3.0 * scarcity) * (1.0 - (after_next - 8.0) / 8.0) * (1.0 - progress);
            }
        }
        if post_residual > 0 && next_item_size > 0 && fitting_bins_count > 3 {
            let overshoot = post_residual.saturating_sub(next_item_size) as f64;
            if overshoot > 16.0 {
                score += 1.6 * ((overshoot - 16.0) / cap).min(0.25) * (1.0 - progress);
            }
        }
        if fitting_bins_count > 1 && dead_ratio > 0.08 && post_residual > 0 {
            let scarcity = 1.0 / (fitting_bins_count as f64);
            let comp_slack = (mean_residual / cap).min(1.0);
            score += 6.5 * (dead_ratio - 0.08) * scarcity * comp_slack * (0.5 + 0.5 * (1.0 - progress));
            score += 2.2 * (dead / cap) * scarcity * comp_slack * (1.0 - progress);
        }
        if fitting_bins_count > 2 && post_residual > 0 && mean_residual > 0.0 {
            let dev = ((post_residual as f64 - mean_residual).abs() / cap).min(0.4);
            score += 5.0 * dev * (1.0 - progress);
        }
        if post_residual > 0 && post_residual % 10 == 0 && post_residual <= 60 && next_item_size > 0 && next_item_size <= post_residual {
            score -= 4.0 * (1.0 - progress) * (1.0 - post_residual as f64 / 120.0);
        }
        if next_item_size > 0 && post_residual == next_item_size && fitting_bins_count <= 3 {
            score -= 30.0 / fitting_bins_count.max(1) as f64 * (0.5 + 0.5 * (1.0 - progress));
        }
        if post_residual > 0 && next_item_size > 0 && fitting_bins_count > 1 {
            let usable = next_item_size <= post_residual
                || (mean_residual as u32) >= next_item_size;
            if !usable {
                let waste_frac = post_residual as f64 / cap;
                let late = 0.35 + 0.65 * progress;
                score += 9.0 * waste_frac * late;
            }
        }
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 2 {
            let rel = post_residual as f64 / (mean_residual + 1.0);
            if rel < 0.5 {
                score -= 6.0 * (1.0 - rel / 0.5) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        if post_residual > 0 && next_item_size > 1 && next_item_size <= post_residual {
            let reps = post_residual / next_item_size;
            let rem = post_residual % next_item_size;
            if reps >= 1 && rem == 0 {
                let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
                score -= (5.0 + 6.0 * scarcity) * ((reps as f64).min(3.0)) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 1 && progress > 0.25 {
            let target = 0.5 * (mean_residual + 0.5 * cap);
            let dev = ((post_residual as f64 - target).abs() / cap).min(0.5);
            score += 2.4 * dev * (progress - 0.25);
        }
        // gen 76: near-full chain extension.
        if post_residual > 0 && next_item_size > 0 && post_residual > next_item_size {
            let after_next = post_residual - next_item_size;
            if after_next > 0 && after_next < 6 && progress > 0.35 {
                score -= 11.0 * (1.0 - after_next as f64 / 6.0) * (progress - 0.35);
            }
        }
        // gen 76: usable-residual scarcity bonus for the lone fitting bin.
        if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count == 1 && bin_residual != bin_capacity {
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score -= 14.0 * (1.0 - progress) * (0.6 + 0.4 * tightness);
        }
        // gen 81: dead-space compaction gradient (gen 84: deepen and widen
        // the aggregate-slack threshold so residual variance shrinks further).
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
            && fitting_bins_count > 1 {
            let open_space = mean_residual * open_bins_count as f64;
            if open_space > 1.7 * cap {
                let frac = post_residual as f64 / next_item_size as f64;
                score += 12.5 * (1.0 - frac) * (0.5 + 0.5 * progress);
            }
        }
        // gen 81: consolidation pull (gen 84: extend earlier, weight with
        // closeness-to-full so near-closed bins are strongly preferred).
        if post_residual > 0 && fitting_bins_count > 2 && progress > 0.4 {
            let fill = 1.0 - post_residual as f64 / cap;
            score -= 6.5 * fill * fill * (progress - 0.4);
        }
        // MUTATION (gen 84): residual-band harmonizer — when this placement
        // lands the bin's post-residual within a tight band around the
        // fleet mean, the leftover is likely reusable by the stream's
        // typical sizes; reward it to compress residual spread.
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 1 {
            let rel_dev = (post_residual as f64 - mean_residual).abs() / mean_residual;
            if rel_dev < 0.15 && post_residual as f64 > 0.2 * cap {
                score -= 8.0 * (1.0 - rel_dev / 0.15) * (0.3 + 0.7 * progress);
            }
        }
        // MUTATION (gen 84): exact-fill runway — reward placements whose
        // post-residual equals the sum of plausible small-item combinations
        // (next item plus a small tail), effectively planning a two-item close.
        if post_residual > next_item_size && next_item_size > 0 {
            let tail = post_residual - next_item_size;
            if tail >= 1 && tail <= 5 && progress > 0.3 {
                score -= 9.0 * (1.0 - tail as f64 / 5.0) * progress;
            }
        }
    } else {
        let fragmentation = (mean_residual / cap) * open_bins_count as f64;
        let huge_item = item_size as f64 > 0.7 * cap;
        let remaining = if total_items > step_index { total_items - step_index } else { 1 };
        let remaining_frac = remaining as f64 / total_items.max(1) as f64;
        let fresh_post = cap - item_size as f64;
        let fresh_is_exact = fresh_post <= 4.0 && fresh_post >= 0.0;

        if fragmentation > 0.55 || (huge_item && open_bins_count > 4) {
            score -= 66.0 + 46.0 * remaining_frac;
        } else if fresh_is_exact {
            score -= 134.0 + 66.0 * remaining_frac;
        } else {
            score += 400.0 - 82.0 * remaining_frac;
            if fitting_bins_count <= 3 && open_bins_count > 2 {
                score -= 30.0 + 18.0 * remaining_frac;
            }
        }

        let fresh_match = (fresh_post - mean_residual).abs() / cap;
        if fresh_match < 0.05 {
            score -= 76.0 * (1.0 - fresh_match / 0.05);
        }
        if remaining_frac < 0.05 && fresh_post > 0.0 && !fresh_is_exact {
            score += 160.0 * (fresh_post / cap);
        }
        if fresh_post > 0.0 && fresh_post <= 22.0 && !fresh_is_exact {
            score -= 26.0 * (1.0 - fresh_post / 22.0);
        }
        if fresh_post > 22.0 && fresh_post <= 40.0 && fragmentation < 0.35 {
            score -= 12.5 * (1.0 - (fresh_post - 22.0) / 18.0);
        }
        if fresh_post > 0.0 && fresh_match < 0.12 && fragmentation < 0.55 {
            score -= 30.0 * (1.0 - fresh_match / 0.12);
        }
        if next_item_size > 0 && fresh_post > 0.0 {
            let fresh_exact_next = (fresh_post as u32) == next_item_size;
            let open_can_next = mean_residual >= next_item_size as f64;
            if fresh_exact_next && !open_can_next && fitting_bins_count <= 2 {
                score -= 52.0 * (1.0 - progress);
            }
            if (fresh_post as u32) < next_item_size && mean_residual > next_item_size as f64 {
                score += 21.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && fresh_post > next_item_size as f64 {
            let chain_post = fresh_post - next_item_size as f64;
            if chain_post <= 4.0 {
                score -= 34.0 * (1.0 - chain_post / 4.0) * (0.5 + 0.5 * (1.0 - progress));
            } else if chain_post <= 10.0 {
                score -= 9.5 * (1.0 - (chain_post - 4.0) / 6.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        if remaining_frac < 0.12 && fresh_post > 0.0 && !fresh_is_exact && mean_residual * open_bins_count as f64 > 3.0 * cap {
            score += 42.0 * (1.0 - remaining_frac / 0.12);
        }
        if fitting_bins_count == 1 && fresh_post > 0.0 && next_item_size > 0 {
            let stranded_here = bin_capacity.saturating_sub(item_size);
            let would_strand = stranded_here < next_item_size;
            if would_strand && stranded_here > 0 && stranded_here <= 8 {
                score -= 32.0 * (1.0 - progress);
            }
        }
        let open_capacity = mean_residual * open_bins_count as f64;
        let per_item_need = cap * 0.5;
        if remaining_frac > 0.25 && open_capacity < per_item_need * open_bins_count.max(1) as f64 * 0.5 {
            score -= 18.0 * (1.0 - progress);
        }
        if next_item_size > 0 && fresh_post > next_item_size as f64 {
            let after_next = fresh_post - next_item_size as f64;
            if after_next > 0.0 && after_next <= 8.0 && fragmentation < 0.5 {
                score -= 20.0 * (1.0 - after_next / 8.0) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        if next_item_size > 0 && fresh_post > 0.0 && (fresh_post as u32) < next_item_size {
            let slack_total = mean_residual * open_bins_count as f64;
            if slack_total > 2.0 * cap {
                score += 26.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && (fresh_post as u32) == next_item_size && fragmentation > 0.3 {
            score -= 44.0 * (0.5 + 0.5 * (1.0 - progress));
        }
        if fresh_post > 0.5 * cap && mean_residual < 0.2 * cap && remaining_frac > 0.3 && open_bins_count > 3 {
            score += 24.0 * (fresh_post / cap - 0.5) * 2.0 * (1.0 - progress);
        }
        if fitting_bins_count <= 1 && fresh_post > 0.45 * cap && next_item_size > 0 {
            let reachable = (next_item_size as f64 / fresh_post).min(1.0);
            if reachable < 0.5 {
                score += 18.0 * (0.5 - reachable) * (1.0 - progress);
            }
        }
        if next_item_size > 0 && fresh_post > 0.0 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 2 && fragmentation < 0.5 {
                score -= 7.0 * ((reps as f64).min(4.0) - 1.0) * (0.4 + 0.6 * (1.0 - progress));
                if rem <= 3 {
                    score -= 5.0 * (1.0 - progress);
                }
            }
        }
        if fresh_post > 0.35 * cap && remaining_frac > 0.2 && mean_residual * open_bins_count as f64 > 4.0 * cap && fragmentation < 0.45 {
            score += 20.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        if remaining_frac < 0.15 && fresh_post > 0.3 * cap {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.35;
            if open_space > est_need {
                score += 55.0 * (1.0 - remaining_frac / 0.15);
            }
        }
        if remaining_frac >= 0.15 && remaining_frac < 0.45 && fresh_post > 0.4 * cap && fragmentation > 0.4 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.45;
            if open_space > est_need {
                score += 28.0 * (1.0 - remaining_frac / 0.45);
            }
        }
        if next_item_size > 1 && fresh_post > 0.0 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 2 && rem == 0 && fragmentation < 0.4 {
                score -= 10.0 * ((reps as f64).min(4.0) - 1.0) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        if remaining_frac >= 0.45 && remaining_frac < 0.5 && fresh_post > 0.45 * cap && fragmentation > 0.5 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.55;
            if open_space > est_need {
                score += 22.0 * (1.0 - remaining_frac / 0.5);
            }
        }
        // gen 76: demand-aware fresh-bin refusal.
        if remaining_frac >= 0.05 && fresh_post > 0.3 * cap && next_item_size > 0 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (next_item_size as f64) * 0.42;
            if open_space > 1.15 * est_need {
                score += 30.0 * (1.0 - remaining_frac) * (fresh_post / cap - 0.3);
            }
        }
        // gen 76: fresh-bin dead-space cap.
        if fresh_post > 0.35 * cap && next_item_size > 0 && (fresh_post as u32) < next_item_size && fragmentation < 0.4 && remaining_frac > 0.15 {
            score += 16.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        // gen 81: tileability-aware open.
        if next_item_size > 1 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 3 && rem == 0 && fragmentation < 0.3 {
                score -= 14.0 * ((reps as f64).min(5.0) - 2.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // MUTATION (gen 84): mean-anchored fresh open — prefer opening a new
        // bin whose fresh post-residual sits near the fleet's mean residual
        // so the resulting pool of leftovers stays homogeneous and reusable.
        if fresh_post > 0.0 && mean_residual > 0.0 && remaining_frac > 0.1 {
            let rel_gap = (fresh_post - mean_residual).abs() / mean_residual;
            if rel_gap < 0.2 && fragmentation < 0.5 {
                score -= 11.0 * (1.0 - rel_gap / 0.2) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Layered dead-space rewards (lower post_residual = better).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 4 {
        score -= 260.0 + 4.4 * (4 - post_residual) as f64;
    } else if post_residual <= 10 {
        score -= 70.0 + 3.8 * (10 - post_residual) as f64;
    } else if post_residual <= 22 {
        score -= 14.0 + 1.6 * (22 - post_residual) as f64;
    } else if post_residual <= 32 {
        score -= 5.0 + 0.75 * (32 - post_residual) as f64;
    } else if post_residual <= 48 {
        score -= 1.2 + 0.24 * (48 - post_residual) as f64;
    } else {
        score -= 1.2 - 0.015 * (post_residual as f64 - 48.0);
    }

    // Progress-scaled weighting: tighten late in the stream.
    let w = 0.33 + 0.67 * progress * progress;
    score *= w;

    // Lookahead coupling with the next item.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 920.0;
        } else if next_item_size < post_residual {
            let two_step_waste = (post_residual - next_item_size) as f64;
            if two_step_waste <= 8.0 {
                score -= 140.0 - 2.3 * two_step_waste;
            } else {
                score -= 74.0 - 0.6 * two_step_waste;
            }
            if two_step_waste <= 3.0 {
                score -= 50.0;
            }
        } else {
            let miss = (next_item_size - post_residual) as f64;
            score += 0.95 * miss;
            if miss > 26.0 {
                score += 0.55 * (miss - 26.0);
            }
        }
        // Two-step exact-fill of the whole bin.
        let two_step = item_size + next_item_size;
        if two_step == bin_capacity {
            score -= 800.0;
        } else if two_step <= bin_capacity && bin_capacity - two_step <= 10 {
            score -= 200.0;
        }
        // MUTATION (gen 84): three-step chain bonus — if the residual after
        // the next item still tiles with a further placement, favor it.
        if next_item_size < post_residual {
            let after_next = post_residual - next_item_size;
            if after_next >= next_item_size {
                let tail = after_next % next_item_size;
                if tail == 0 {
                    score -= 34.0 * (1.0 - progress);
                } else if tail <= 4 {
                    score -= 14.0 * (1.0 - tail as f64 / 4.0) * (1.0 - progress);
                }
            }
        }
    }

    // Slack-based scarcity boost when the next item fits here.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
        let boost = 38.0 + 28.0 * scarcity;
        score -= boost * (1.0 - slack / cap) * (0.6 + 0.4 * (1.0 - progress));
        if fitting_bins_count <= 2 {
            score -= 16.0 * (1.0 - slack / cap);
        }
        if slack == 0.0 {
            score -= 22.0 * (1.0 - progress);
        }
    }

    // Mean-residual harmony: prefer residuals near the mean, penalize
    // wasteful outliers.
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Stranded-residual scarcity penalty.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let stranded = (next_item_size - post_residual) as f64;
        let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
        if stranded <= 10.0 {
            score += (9.0 + 1.2 * (10.0 - stranded)) * scarcity * (0.4 + 0.6 * (1.0 - progress));
        } else {
            let proximity = 1.0 - (stranded - 10.0).min(cap) / cap;
            score += 3.4 * proximity * scarcity * (1.0 - progress);
        }
    }

    // Tiling/divisibility consolidation.
    if post_residual > 0 && next_item_size > 1 && next_item_size <= post_residual {
        let reps = post_residual / next_item_size;
        let rem = post_residual % next_item_size;
        if reps >= 1 && rem == 0 {
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            score -= (5.5 + 6.5 * scarcity) * (reps as f64).min(3.0) * (0.4 + 0.6 * (1.0 - progress));
        }
    }

    // Fill-level momentum.
    if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 2 {
        let rel = post_residual as f64 / (mean_residual + 1.0);
        if rel < 0.5 {
            score -= 6.5 * (1.0 - rel / 0.5) * (0.4 + 0.6 * (1.0 - progress));
        }
    }

    // Dead-ratio gradient scaled by aggregate open slack.
    if bin_residual != bin_capacity && fitting_bins_count > 1 && post_residual > 0 {
        let dead = (bin_residual - item_size) as f64;
        let dead_ratio = dead / cap;
        let scarcity = 1.0 / (fitting_bins_count as f64);
        let comp_slack = (mean_residual / cap).min(1.0);
        if dead_ratio > 0.08 {
            score += 6.5 * (dead_ratio - 0.08) * scarcity * comp_slack * (0.5 + 0.5 * (1.0 - progress));
        }
        if dead_ratio > 0.5 {
            score += 10.5 * (dead_ratio - 0.5) * (1.0 - progress);
        }
        if next_item_size > 0 {
            let usable = next_item_size <= post_residual || (mean_residual as u32) >= next_item_size;
            if !usable {
                score += 9.5 * (post_residual as f64 / cap) * (0.35 + 0.65 * progress);
            }
        }
        // MUTATION (gen 84): stranded-with-large-open-slack penalty — leaving
        // a residual below the next item while aggregate slack elsewhere is
        // ample is pure waste; scale by the slack cushion.
        if next_item_size > 0 && post_residual < next_item_size {
            let open_space = mean_residual * open_bins_count as f64;
            if open_space > 2.0 * cap {
                let frac = post_residual as f64 / next_item_size as f64;
                score += 11.0 * (1.0 - frac) * (0.5 + 0.5 * progress);
            }
        }
    }

    // Last chance bin: if this is the only fitting bin, prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 160.0;
    }

    // Unique-fit lookahead bonus.
    if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 - progress);
    }

    // Penalize creating small unusable dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 120.0;
    }

    // Early stream: keep flexibility; late stream: consolidate.
    score -= (1.0 - progress) * 20.0;

    // Slight preference for filling fuller bins when many bins are open.
    score += 0.1 * open_bins_count as f64 * (post_residual as f64 / cap);

    if bin_residual == bin_capacity {
        // NEW-BIN CANDIDATE branch.
        let fragmentation = (mean_residual / cap) * open_bins_count as f64;
        let huge_item = item_size as f64 > 0.7 * cap;
        let remaining = if total_items > step_index { total_items - step_index } else { 1 };
        let remaining_frac = remaining as f64 / total_items.max(1) as f64;
        let fresh_post = cap - item_size as f64;
        let fresh_is_exact = fresh_post <= 4.0 && fresh_post >= 0.0;

        if fragmentation > 0.55 || (huge_item && open_bins_count > 4) {
            score -= 66.0 + 46.0 * remaining_frac;
        } else if fresh_is_exact {
            score -= 134.0 + 66.0 * remaining_frac;
        } else {
            score += 400.0 - 82.0 * remaining_frac;
            if fitting_bins_count <= 3 && open_bins_count > 2 {
                score -= 30.0 + 18.0 * remaining_frac;
            }
        }

        let fresh_match = (fresh_post - mean_residual).abs() / cap;
        if fresh_match < 0.05 {
            score -= 76.0 * (1.0 - fresh_match / 0.05);
        }
        if remaining_frac < 0.05 && fresh_post > 0.0 && !fresh_is_exact {
            score += 160.0 * (fresh_post / cap);
        }
        if fresh_post > 0.0 && fresh_post <= 22.0 && !fresh_is_exact {
            score -= 26.0 * (1.0 - fresh_post / 22.0);
        }
        if fresh_post > 22.0 && fresh_post <= 40.0 && fragmentation < 0.35 {
            score -= 12.5 * (1.0 - (fresh_post - 22.0) / 18.0);
        }
        if fresh_post > 0.0 && fresh_match < 0.12 && fragmentation < 0.55 {
            score -= 30.0 * (1.0 - fresh_match / 0.12);
        }
        if next_item_size > 0 && fresh_post > 0.0 {
            let fresh_exact_next = (fresh_post as u32) == next_item_size;
            let open_can_next = mean_residual >= next_item_size as f64;
            if fresh_exact_next && !open_can_next && fitting_bins_count <= 2 {
                score -= 52.0 * (1.0 - progress);
            }
            if (fresh_post as u32) < next_item_size && mean_residual > next_item_size as f64 {
                score += 21.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && fresh_post > next_item_size as f64 {
            let chain_post = fresh_post - next_item_size as f64;
            if chain_post <= 4.0 {
                score -= 34.0 * (1.0 - chain_post / 4.0) * (0.5 + 0.5 * (1.0 - progress));
            } else if chain_post <= 10.0 {
                score -= 9.5 * (1.0 - (chain_post - 4.0) / 6.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        if remaining_frac < 0.12 && fresh_post > 0.0 && !fresh_is_exact && mean_residual * open_bins_count as f64 > 3.0 * cap {
            score += 42.0 * (1.0 - remaining_frac / 0.12);
        }
        // Refuse fresh bins late when open slack covers projected demand.
        if remaining_frac < 0.15 && fresh_post > 0.3 * cap {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.35;
            if open_space > est_need {
                score += 55.0 * (1.0 - remaining_frac / 0.15);
            }
        }
        // Mid-stream refusal band.
        if remaining_frac >= 0.15 && remaining_frac < 0.45 && fresh_post > 0.4 * cap && fragmentation > 0.4 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.45;
            if open_space > est_need {
                score += 28.0 * (1.0 - remaining_frac / 0.45);
            }
        }
        // Demand-aware fresh-bin refusal using next-item footprint.
        if remaining_frac >= 0.05 && fresh_post > 0.3 * cap && next_item_size > 0 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (next_item_size as f64) * 0.42;
            if open_space > 1.15 * est_need {
                score += 32.0 * (1.0 - remaining_frac) * (fresh_post / cap - 0.3);
            }
        }
        // Fresh-bin dead-space cap.
        if fresh_post > 0.35 * cap && next_item_size > 0 && (fresh_post as u32) < next_item_size && fragmentation < 0.4 && remaining_frac > 0.15 {
            score += 17.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        // Tiling-aware fresh-bin bonus.
        if next_item_size > 1 && fresh_post > 0.0 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 3 && rem == 0 && fragmentation < 0.3 {
                score -= 14.0 * ((reps as f64).min(5.0) - 2.0) * (0.5 + 0.5 * (1.0 - progress));
            } else if reps >= 2 && rem == 0 && fragmentation < 0.4 {
                score -= 10.0 * ((reps as f64).min(4.0) - 1.0) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        // Fresh-bin residual-magnitude guard.
        if fresh_post > 0.35 * cap && remaining_frac > 0.2 && mean_residual * open_bins_count as f64 > 4.0 * cap && fragmentation < 0.45 {
            score += 20.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        // MUTATION (gen 84): near-exact fresh residual bonus — when the fresh
        // bin's post-residual is small but usable (6..=14) and few bins can
        // host the next item, opening a dedicated lane beats scattering.
        if fresh_post >= 6.0 && fresh_post <= 14.0 && fitting_bins_count <= 3 && fragmentation < 0.5 {
            score -= 22.0 * (1.0 - (fresh_post - 6.0) / 8.0) * (0.5 + 0.5 * (1.0 - progress));
        }
        // MUTATION (gen 84): late-stream fresh-bin hard refusal — once the
        // remaining stream is small and open slack exceeds 2x the fresh
        // leftover, never open a new bin.
        if remaining_frac < 0.08 && fresh_post > 0.0 && !fresh_is_exact {
            let open_space = mean_residual * open_bins_count as f64;
            if open_space > 2.0 * cap {
                score += 90.0 * (1.0 - remaining_frac / 0.08);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Layered dead-space rewards (lower post_residual = better).
    if post_residual == 0 {
        score -= 980.0;
    } else if post_residual <= 4 {
        score -= 250.0 + 4.2 * (4 - post_residual) as f64;
    } else if post_residual <= 10 {
        score -= 64.0 + 3.6 * (10 - post_residual) as f64;
    } else if post_residual <= 22 {
        score -= 13.5 + 1.5 * (22 - post_residual) as f64;
    } else if post_residual <= 32 {
        score -= 5.0 + 0.7 * (32 - post_residual) as f64;
    } else if post_residual <= 48 {
        score -= 1.2 + 0.22 * (48 - post_residual) as f64;
    } else {
        score -= 1.2 - 0.014 * (post_residual as f64 - 48.0);
    }

    let w = 0.33 + 0.67 * progress * progress;
    score *= w;

    // Lookahead coupling with the next item.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if next_item_size < post_residual {
            let two_step_waste = (post_residual - next_item_size) as f64;
            if two_step_waste <= 8.0 {
                score -= 135.0 - 2.3 * two_step_waste;
            } else {
                score -= 72.0 - 0.58 * two_step_waste;
            }
            if two_step_waste <= 3.0 {
                score -= 48.0;
            }
