        // post-residual lands within a narrow band around the mean open
        // residual, reward it: bins whose leftovers stay mutually reusable
        // for medium items waste less aggregate dead space than bins whose
        // leftovers scatter across incompatible sizes.
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 1 {
            let band = (post_residual as f64 - mean_residual).abs();
            if band < 0.05 * cap {
                score -= 7.5 * (1.0 - band / (0.05 * cap)) * (0.3 + 0.7 * progress);
