        }
        if dead_ratio > 0.35 && fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score += 7.5 * (dead_ratio - 0.35) * tightness * (1.0 - progress);
        }
        if post_residual > 0 && mean_residual > 0.0 {
            let gap = mean_residual - post_residual as f64;
            if gap > 0.0 && gap < 0.15 * cap && fitting_bins_count > 2 {
                score += 4.8 * (gap / (0.15 * cap)) * (1.0 - progress);
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size.max(1) && fitting_bins_count > 2 {
            score -= 6.5 * (1.0 - progress);
        }
        if post_residual == 0 && bin_residual < bin_capacity {
            score -= 42.0 * (1.0 - bin_residual as f64 / cap) * (1.0 - progress);
        }
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 1 {
            let harmony = (post_residual as f64 - mean_residual).abs() / cap;
            if harmony < 0.08 {
                score -= 9.0 * (1.0 - harmony / 0.08) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        if post_residual > 6 && post_residual <= 30 && next_item_size > 0 && next_item_size <= post_residual {
            let reps = post_residual / next_item_size.max(1);
            if reps >= 2 {
                score -= 3.5 * (reps as f64).min(4.0) * (1.0 - progress);
            }
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let after_next = post_residual - next_item_size;
            if after_next > 0 && after_next <= 12 {
                let tail = after_next as f64;
                score -= (14.0 - 0.9 * tail) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        if post_residual > 0 && post_residual < 6 && next_item_size > post_residual {
            score += 6.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let after_next = (post_residual - next_item_size) as f64;
            if after_next > 8.0 && after_next <= 16.0 && progress < 0.85 {
                let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
                score -= (4.0 + 3.0 * scarcity) * (1.0 - (after_next - 8.0) / 8.0) * (1.0 - progress);
            }
        }
        if post_residual > 0 && next_item_size > 0 && fitting_bins_count > 3 {
            let overshoot = post_residual.saturating_sub(next_item_size) as f64;
            if overshoot > 16.0 {
                score += 1.6 * ((overshoot - 16.0) / cap).min(0.25) * (1.0 - progress);
            }
        }
        if fitting_bins_count > 1 && dead_ratio > 0.08 && post_residual > 0 {
            let scarcity = 1.0 / (fitting_bins_count as f64);
            let comp_slack = (mean_residual / cap).min(1.0);
            score += 6.5 * (dead_ratio - 0.08) * scarcity * comp_slack * (0.5 + 0.5 * (1.0 - progress));
            score += 2.2 * (dead / cap) * scarcity * comp_slack * (1.0 - progress);
        }
        if fitting_bins_count > 2 && post_residual > 0 && mean_residual > 0.0 {
            let dev = ((post_residual as f64 - mean_residual).abs() / cap).min(0.4);
            score += 5.0 * dev * (1.0 - progress);
        }
        if post_residual > 0 && post_residual % 10 == 0 && post_residual <= 60 && next_item_size > 0 && next_item_size <= post_residual {
            score -= 4.0 * (1.0 - progress) * (1.0 - post_residual as f64 / 120.0);
        }
        if next_item_size > 0 && post_residual == next_item_size && fitting_bins_count <= 3 {
            score -= 30.0 / fitting_bins_count.max(1) as f64 * (0.5 + 0.5 * (1.0 - progress));
        }
        if post_residual > 0 && next_item_size > 0 && fitting_bins_count > 1 {
            let usable = next_item_size <= post_residual
                || (mean_residual as u32) >= next_item_size;
            if !usable {
                let waste_frac = post_residual as f64 / cap;
                let late = 0.35 + 0.65 * progress;
                score += 9.0 * waste_frac * late;
            }
        }
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 2 {
            let rel = post_residual as f64 / (mean_residual + 1.0);
            if rel < 0.5 {
                score -= 6.0 * (1.0 - rel / 0.5) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        if post_residual > 0 && next_item_size > 1 && next_item_size <= post_residual {
            let reps = post_residual / next_item_size;
            let rem = post_residual % next_item_size;
            if reps >= 1 && rem == 0 {
                let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
                score -= (5.0 + 6.0 * scarcity) * ((reps as f64).min(3.0)) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 1 && progress > 0.25 {
            let target = 0.5 * (mean_residual + 0.5 * cap);
            let dev = ((post_residual as f64 - target).abs() / cap).min(0.5);
            score += 2.4 * dev * (progress - 0.25);
        }
        // near-full chain extension (widened window, earlier activation).
        if post_residual > 0 && next_item_size > 0 && post_residual > next_item_size {
            let after_next = post_residual - next_item_size;
            if after_next > 0 && after_next < 6 && progress > 0.35 {
                score -= 11.0 * (1.0 - after_next as f64 / 6.0) * (progress - 0.35);
            }
        }
        // usable-residual scarcity bonus for single-lane tight reuse.
        if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count == 1 && bin_residual != bin_capacity {
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score -= 14.0 * (1.0 - progress) * (0.6 + 0.4 * tightness);
        }
        // gen 81: dead-space compaction gradient (refined gen 87: lower the
        // open-space trigger from 2.0x to 1.6x cap and steepen the penalty so
        // stranded slivers are punished as soon as aggregate slack is ample).
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
            && fitting_bins_count > 1 {
            let open_space = mean_residual * open_bins_count as f64;
            if open_space > 1.6 * cap {
                let frac = post_residual as f64 / next_item_size as f64;
                score += 13.0 * (1.0 - frac) * (0.5 + 0.5 * progress);
            }
        }
        // gen 81: consolidation pull (refined gen 87: start earlier at
        // progress > 0.4 and scale with how close the bin gets to full).
        if post_residual > 0 && fitting_bins_count > 2 && progress > 0.4 {
            let fill = 1.0 - post_residual as f64 / cap;
            score -= 6.0 * fill * (progress - 0.4);
        }
        // MUTATION (gen 87): residual-variance damper — when this placement
        // leaves a residual far above the stream's mean residual while other
        // bins still hold usable slack, the oversized leftover fragments the
        // residual distribution; penalize the excess so spread shrinks.
        if post_residual > 0 && fitting_bins_count > 2 && next_item_size > 0 {
            let excess = post_residual as f64 - mean_residual;
            if excess > 0.12 * cap && mean_residual * open_bins_count as f64 > cap {
                let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
                score += 8.0 * ((excess / cap).min(0.4)) * scarcity * (0.4 + 0.6 * progress);
            }
        }
        // MUTATION (gen 87): exact-landing bonus — when post_residual equals
        // the mean residual of the other open bins (mod small tolerance),
        // this bin becomes interchangeable with the rest of the pool and can
        // absorb future items in any order; reward the homogenization.
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 1 {
            let dev = (post_residual as f64 - mean_residual).abs();
            if dev <= 2.0 {
                score -= 7.0 * (1.0 - dev / 2.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
    } else {
        let fragmentation = (mean_residual / cap) * open_bins_count as f64;
        let huge_item = item_size as f64 > 0.7 * cap;
        let remaining = if total_items > step_index { total_items - step_index } else { 1 };
        let remaining_frac = remaining as f64 / total_items.max(1) as f64;
        let fresh_post = cap - item_size as f64;
        let fresh_is_exact = fresh_post <= 4.0 && fresh_post >= 0.0;

        if fragmentation > 0.55 || (huge_item && open_bins_count > 4) {
            score -= 66.0 + 46.0 * remaining_frac;
        } else if fresh_is_exact {
            score -= 134.0 + 66.0 * remaining_frac;
        } else {
            score += 400.0 - 82.0 * remaining_frac;
            if fitting_bins_count <= 3 && open_bins_count > 2 {
                score -= 30.0 + 18.0 * remaining_frac;
            }
        }

        let fresh_match = (fresh_post - mean_residual).abs() / cap;
        if fresh_match < 0.05 {
            score -= 76.0 * (1.0 - fresh_match / 0.05);
        }
        if remaining_frac < 0.05 && fresh_post > 0.0 && !fresh_is_exact {
            score += 160.0 * (fresh_post / cap);
        }
        if fresh_post > 0.0 && fresh_post <= 22.0 && !fresh_is_exact {
            score -= 26.0 * (1.0 - fresh_post / 22.0);
        }
        if fresh_post > 22.0 && fresh_post <= 40.0 && fragmentation < 0.35 {
            score -= 12.5 * (1.0 - (fresh_post - 22.0) / 18.0);
        }
        if fresh_post > 0.0 && fresh_match < 0.12 && fragmentation < 0.55 {
            score -= 30.0 * (1.0 - fresh_match / 0.12);
        }
        if next_item_size > 0 && fresh_post > 0.0 {
            let fresh_exact_next = (fresh_post as u32) == next_item_size;
            let open_can_next = mean_residual >= next_item_size as f64;
            if fresh_exact_next && !open_can_next && fitting_bins_count <= 2 {
                score -= 52.0 * (1.0 - progress);
            }
            if (fresh_post as u32) < next_item_size && mean_residual > next_item_size as f64 {
                score += 21.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && fresh_post > next_item_size as f64 {
            let chain_post = fresh_post - next_item_size as f64;
            if chain_post <= 4.0 {
                score -= 34.0 * (1.0 - chain_post / 4.0) * (0.5 + 0.5 * (1.0 - progress));
            } else if chain_post <= 10.0 {
                score -= 9.5 * (1.0 - (chain_post - 4.0) / 6.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        if remaining_frac < 0.12 && fresh_post > 0.0 && !fresh_is_exact && mean_residual * open_bins_count as f64 > 3.0 * cap {
            score += 42.0 * (1.0 - remaining_frac / 0.12);
        }
        if fitting_bins_count == 1 && fresh_post > 0.0 && next_item_size > 0 {
            let stranded_here = bin_capacity.saturating_sub(item_size);
            let would_strand = stranded_here < next_item_size;
            if would_strand && stranded_here > 0 && stranded_here <= 8 {
                score -= 32.0 * (1.0 - progress);
            }
        }
        let open_capacity = mean_residual * open_bins_count as f64;
        let per_item_need = cap * 0.5;
        if remaining_frac > 0.25 && open_capacity < per_item_need * open_bins_count.max(1) as f64 * 0.5 {
            score -= 18.0 * (1.0 - progress);
        }
        if next_item_size > 0 && fresh_post > next_item_size as f64 {
            let after_next = fresh_post - next_item_size as f64;
            if after_next > 0.0 && after_next <= 8.0 && fragmentation < 0.5 {
                score -= 20.0 * (1.0 - after_next / 8.0) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        if next_item_size > 0 && fresh_post > 0.0 && (fresh_post as u32) < next_item_size {
            let slack_total = mean_residual * open_bins_count as f64;
            if slack_total > 2.0 * cap {
                score += 26.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && (fresh_post as u32) == next_item_size && fragmentation > 0.3 {
            score -= 44.0 * (0.5 + 0.5 * (1.0 - progress));
        }
        if fresh_post > 0.5 * cap && mean_residual < 0.2 * cap && remaining_frac > 0.3 && open_bins_count > 3 {
            score += 24.0 * (fresh_post / cap - 0.5) * 2.0 * (1.0 - progress);
        }
        if fitting_bins_count <= 1 && fresh_post > 0.45 * cap && next_item_size > 0 {
            let reachable = (next_item_size as f64 / fresh_post).min(1.0);
            if reachable < 0.5 {
                score += 18.0 * (0.5 - reachable) * (1.0 - progress);
            }
        }
        if next_item_size > 0 && fresh_post > 0.0 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 2 && fragmentation < 0.5 {
                score -= 7.0 * ((reps as f64).min(4.0) - 1.0) * (0.4 + 0.6 * (1.0 - progress));
                if rem <= 3 {
                    score -= 5.0 * (1.0 - progress);
                }
            }
        }
        if fresh_post > 0.35 * cap && remaining_frac > 0.2 && mean_residual * open_bins_count as f64 > 4.0 * cap && fragmentation < 0.45 {
            score += 20.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        if remaining_frac < 0.15 && fresh_post > 0.3 * cap {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.35;
            if open_space > est_need {
                score += 55.0 * (1.0 - remaining_frac / 0.15);
            }
        }
        if remaining_frac >= 0.15 && remaining_frac < 0.45 && fresh_post > 0.4 * cap && fragmentation > 0.4 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.45;
            if open_space > est_need {
                score += 28.0 * (1.0 - remaining_frac / 0.45);
            }
        }
        if next_item_size > 1 && fresh_post > 0.0 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 2 && rem == 0 && fragmentation < 0.4 {
                score -= 10.0 * ((reps as f64).min(4.0) - 1.0) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        if remaining_frac >= 0.45 && remaining_frac < 0.5 && fresh_post > 0.45 * cap && fragmentation > 0.5 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.55;
            if open_space > est_need {
                score += 22.0 * (1.0 - remaining_frac / 0.5);
            }
        }
        // demand-aware fresh-bin refusal (cushion 1.15x).
        if remaining_frac >= 0.05 && fresh_post > 0.3 * cap && next_item_size > 0 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (next_item_size as f64) * 0.42;
            if open_space > 1.15 * est_need {
                score += 30.0 * (1.0 - remaining_frac) * (fresh_post / cap - 0.3);
            }
        }
        // fresh-bin dead-space cap.
        if fresh_post > 0.35 * cap && next_item_size > 0 && (fresh_post as u32) < next_item_size && fragmentation < 0.4 && remaining_frac > 0.15 {
            score += 16.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        // tileability-aware open (deepened for low fragmentation).
        if next_item_size > 1 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 3 && rem == 0 && fragmentation < 0.3 {
                score -= 14.0 * ((reps as f64).min(5.0) - 2.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // MUTATION (gen 87): homogeneity-seeking open — prefer a fresh bin
        // whose post-residual lands near the pool's mean residual so all
        // open bins remain interchangeable and residual variance stays low;
        // skip when fragmentation is already high (protect the refusal path).
        if fresh_post > 0.0 && fragmentation < 0.45 && remaining_frac > 0.1 {
            let dev = (fresh_post - mean_residual).abs() / cap;
            if dev < 0.1 {
                score -= 12.0 * (1.0 - dev / 0.1) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: tight fit reward (small post_residual is good)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // 2-step lookahead: reward bins whose post_residual can host the next item exactly-ish
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let next_post = post_residual - next_item_size;
            // Reward chain-fitting: how tight is the two-item packing?
            let chain_tight = 1.0 - (next_post as f64) / (bin_capacity as f64);
            score -= 25.0 * chain_tight;
            // Extra bonus for near-perfect two-item fill
            if next_post <= 5 {
                score -= 15.0;
            }
        } else {
            // Next item cannot follow here: penalize proportionally to wasted gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap;
        }
    }

    // Relative to mean residual: prefer bins with less residual than average (denser bins)
    let dev = (bin_residual as f64) - mean_residual;
    score += 0.10 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let bad_open_bins = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let poor_fit = (item_size as f64) / (bin_capacity as f64);
        score = 100.0 - 55.0 * bad_open_bins - 20.0 * poor_fit;
        // Late in the stream, prefer closing out bins rather than opening new ones
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * (1.0 - progress);
        // Many open bins with slack: discourage opening yet another
        score += 2.0 * (open_bins_count as f64).sqrt();
    }

    // Penalize leaving tiny unusable slivers (< 10, min item size)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Layered compaction rewards (lower post_residual = better).
    if post_residual == 0 {
        score -= 980.0;
    } else if post_residual <= 4 {
        score -= 250.0 + 4.2 * (4 - post_residual) as f64;
    } else if post_residual <= 10 {
        score -= 64.0 + 3.6 * (10 - post_residual) as f64;
    } else if post_residual <= 22 {
        score -= 13.5 + 1.5 * (22 - post_residual) as f64;
    } else if post_residual <= 32 {
        score -= 5.0 + 0.7 * (32 - post_residual) as f64;
    } else if post_residual <= 48 {
        score -= 1.2 + 0.22 * (48 - post_residual) as f64;
    } else {
        score -= 1.2 - 0.014 * (post_residual as f64 - 48.0);
    }

    let w = 0.33 + 0.67 * progress * progress;
    score *= w;

    // Lookahead coupling with the next item.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if next_item_size < post_residual {
            let two_step_waste = (post_residual - next_item_size) as f64;
            if two_step_waste <= 8.0 {
                score -= 135.0 - 2.3 * two_step_waste;
            } else {
                score -= 72.0 - 0.58 * two_step_waste;
            }
            if two_step_waste <= 3.0 {
                score -= 48.0;
            }
        } else {
            let miss = (next_item_size - post_residual) as f64;
            score += 0.95 * miss;
            if miss > 26.0 {
                score += 0.55 * (miss - 26.0);
            }
        }
    }

    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
        let boost = 36.0 + 26.0 * scarcity;
        score -= boost * (1.0 - slack / cap) * (0.6 + 0.4 * (1.0 - progress));
        if fitting_bins_count <= 2 {
            score -= 15.0 * (1.0 - slack / cap);
        }
        if slack == 0.0 {
            score -= 20.0 * (1.0 - progress);
        }
    }

    if bin_residual != bin_capacity {
        let dead = (bin_residual - item_size) as f64;
        let dead_ratio = dead / cap;
        if dead_ratio > 0.5 && fitting_bins_count > 1 {
            score += 10.5 * (dead_ratio - 0.5) * (1.0 - progress);
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
            && mean_residual > 0.0 && (mean_residual as u32) >= next_item_size {
            score += 12.0;
        }
        if post_residual > 12 && post_residual < 40 && next_item_size > post_residual {
            let orphan = (post_residual as f64 - 12.0) / 28.0;
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            score += 17.0 * orphan * scarcity * (0.5 + 0.5 * (1.0 - progress));
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let chain = post_residual % next_item_size.max(1);
            if chain == 0 {
                score -= 26.0 * (1.0 - progress);
            } else if chain <= 3 {
                score -= 11.0 * (1.0 - progress);
            }
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            let stranded = (next_item_size - post_residual) as f64;
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            if stranded <= 10.0 {
                score += (8.5 + 1.1 * (10.0 - stranded)) * scarcity * (0.4 + 0.6 * (1.0 - progress));
            } else {
                let proximity = 1.0 - (stranded - 10.0).min(cap) / cap;
                score += 3.2 * proximity * scarcity * (1.0 - progress);
            }
        }
        if dead_ratio > 0.35 && fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score += 7.5 * (dead_ratio - 0.35) * tightness * (1.0 - progress);
        }
        if post_residual > 0 && mean_residual > 0.0 {
            let gap = mean_residual - post_residual as f64;
            if gap > 0.0 && gap < 0.15 * cap && fitting_bins_count > 2 {
                score += 4.8 * (gap / (0.15 * cap)) * (1.0 - progress);
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size.max(1) && fitting_bins_count > 2 {
            score -= 6.5 * (1.0 - progress);
        }
        if post_residual == 0 && bin_residual < bin_capacity {
            score -= 42.0 * (1.0 - bin_residual as f64 / cap) * (1.0 - progress);
        }
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 1 {
            let harmony = (post_residual as f64 - mean_residual).abs() / cap;
            if harmony < 0.08 {
                score -= 9.0 * (1.0 - harmony / 0.08) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        if post_residual > 6 && post_residual <= 30 && next_item_size > 0 && next_item_size <= post_residual {
            let reps = post_residual / next_item_size.max(1);
            if reps >= 2 {
                score -= 3.5 * (reps as f64).min(4.0) * (1.0 - progress);
            }
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let after_next = post_residual - next_item_size;
            if after_next > 0 && after_next <= 12 {
                let tail = after_next as f64;
                score -= (14.0 - 0.9 * tail) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        if post_residual > 0 && post_residual < 6 && next_item_size > post_residual {
            score += 6.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let after_next = (post_residual - next_item_size) as f64;
            if after_next > 8.0 && after_next <= 16.0 && progress < 0.85 {
                let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
                score -= (4.0 + 3.0 * scarcity) * (1.0 - (after_next - 8.0) / 8.0) * (1.0 - progress);
            }
        }
        if post_residual > 0 && next_item_size > 0 && fitting_bins_count > 3 {
            let overshoot = post_residual.saturating_sub(next_item_size) as f64;
            if overshoot > 16.0 {
                score += 1.6 * ((overshoot - 16.0) / cap).min(0.25) * (1.0 - progress);
            }
        }
        if fitting_bins_count > 1 && dead_ratio > 0.08 && post_residual > 0 {
            let scarcity = 1.0 / (fitting_bins_count as f64);
            let comp_slack = (mean_residual / cap).min(1.0);
            score += 6.5 * (dead_ratio - 0.08) * scarcity * comp_slack * (0.5 + 0.5 * (1.0 - progress));
            score += 2.2 * (dead / cap) * scarcity * comp_slack * (1.0 - progress);
        }
        if fitting_bins_count > 2 && post_residual > 0 && mean_residual > 0.0 {
            let dev = ((post_residual as f64 - mean_residual).abs() / cap).min(0.4);
            score += 5.0 * dev * (1.0 - progress);
        }
        if post_residual > 0 && post_residual % 10 == 0 && post_residual <= 60 && next_item_size > 0 && next_item_size <= post_residual {
            score -= 4.0 * (1.0 - progress) * (1.0 - post_residual as f64 / 120.0);
        }
        if next_item_size > 0 && post_residual == next_item_size && fitting_bins_count <= 3 {
            score -= 30.0 / fitting_bins_count.max(1) as f64 * (0.5 + 0.5 * (1.0 - progress));
        }
        if post_residual > 0 && next_item_size > 0 && fitting_bins_count > 1 {
            let usable = next_item_size <= post_residual
                || (mean_residual as u32) >= next_item_size;
            if !usable {
                let waste_frac = post_residual as f64 / cap;
                let late = 0.35 + 0.65 * progress;
                score += 9.0 * waste_frac * late;
            }
        }
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 2 {
            let rel = post_residual as f64 / (mean_residual + 1.0);
            if rel < 0.5 {
                score -= 6.0 * (1.0 - rel / 0.5) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        if post_residual > 0 && next_item_size > 1 && next_item_size <= post_residual {
            let reps = post_residual / next_item_size;
            let rem = post_residual % next_item_size;
            if reps >= 1 && rem == 0 {
                let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
                score -= (5.0 + 6.0 * scarcity) * ((reps as f64).min(3.0)) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 1 && progress > 0.25 {
            let target = 0.5 * (mean_residual + 0.5 * cap);
            let dev = ((post_residual as f64 - target).abs() / cap).min(0.5);
            score += 2.4 * dev * (progress - 0.25);
        }
        // gen 76: near-full chain extension.
        if post_residual > 0 && next_item_size > 0 && post_residual > next_item_size {
            let after_next = post_residual - next_item_size;
            if after_next > 0 && after_next < 6 && progress > 0.35 {
                score -= 11.0 * (1.0 - after_next as f64 / 6.0) * (progress - 0.35);
            }
        }
        // gen 76: usable-residual scarcity bonus.
        if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count == 1 && bin_residual != bin_capacity {
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score -= 14.0 * (1.0 - progress) * (0.6 + 0.4 * tightness);
        }
        // gen 81: dead-space compaction gradient (refined gen 87: trigger
        // earlier at 1.6x cap and scale with how far the open slack exceeds
        // need, so stranded micro-residuals are punished harder mid-stream).
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
            && fitting_bins_count > 1 {
            let open_space = mean_residual * open_bins_count as f64;
            if open_space > 1.6 * cap {
                let frac = post_residual as f64 / next_item_size as f64;
                let excess = ((open_space / cap - 1.6) / 2.0).min(1.0);
                score += (10.0 + 6.0 * excess) * (1.0 - frac) * (0.5 + 0.5 * progress);
            }
        }
        // gen 81: consolidation pull (refined gen 87: start earlier at 0.4
        // and add a quadratic term so bins closest to full are pulled
        // disproportionately, shrinking residual variance).
        if post_residual > 0 && fitting_bins_count > 2 && progress > 0.4 {
            let fill = 1.0 - post_residual as f64 / cap;
            score -= 5.0 * fill * (progress - 0.4) * (1.0 + 0.8 * fill);
        }
        // MUTATION (gen 87): residual-variance squeeze — when the candidate
        // post-residual sits between the mean residual and the next item
        // size, it is neither reusable now nor aligned with the herd; nudge
        // scores toward post-residuals near the mean to compact the spread.
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 1 && progress > 0.3 {
            let dev = (post_residual as f64 - mean_residual).abs();
            if dev < 0.06 * cap {
                score -= 7.0 * (1.0 - dev / (0.06 * cap)) * (progress - 0.3);
            }
        }
        // MUTATION (gen 87): two-step exact tiling lookahead — reward a
        // placement whose post-residual exactly accommodates the next item
        // AND leaves a remainder that is itself a small tileable residual
        // (post - next <= 10), encouraging chains of near-perfect fills.
        if next_item_size > 0 && post_residual > next_item_size {
            let after_next = post_residual - next_item_size;
            if after_next > 0 && after_next <= 10 && fitting_bins_count <= 4 {
                score -= 8.0 * (1.0 - after_next as f64 / 10.0) * (0.3 + 0.7 * progress);
            }
        }
    } else {
        let fragmentation = (mean_residual / cap) * open_bins_count as f64;
        let huge_item = item_size as f64 > 0.7 * cap;
        let remaining = if total_items > step_index { total_items - step_index } else { 1 };
        let remaining_frac = remaining as f64 / total_items.max(1) as f64;
        let fresh_post = cap - item_size as f64;
        let fresh_is_exact = fresh_post <= 4.0 && fresh_post >= 0.0;

        if fragmentation > 0.55 || (huge_item && open_bins_count > 4) {
            score -= 66.0 + 46.0 * remaining_frac;
        } else if fresh_is_exact {
            score -= 134.0 + 66.0 * remaining_frac;
        } else {
            score += 400.0 - 82.0 * remaining_frac;
            if fitting_bins_count <= 3 && open_bins_count > 2 {
                score -= 30.0 + 18.0 * remaining_frac;
            }
        }

        let fresh_match = (fresh_post - mean_residual).abs() / cap;
        if fresh_match < 0.05 {
            score -= 76.0 * (1.0 - fresh_match / 0.05);
        }
        if remaining_frac < 0.05 && fresh_post > 0.0 && !fresh_is_exact {
            score += 160.0 * (fresh_post / cap);
        }
        if fresh_post > 0.0 && fresh_post <= 22.0 && !fresh_is_exact {
            score -= 26.0 * (1.0 - fresh_post / 22.0);
        }
        if fresh_post > 22.0 && fresh_post <= 40.0 && fragmentation < 0.35 {
            score -= 12.5 * (1.0 - (fresh_post - 22.0) / 18.0);
        }
        if fresh_post > 0.0 && fresh_match < 0.12 && fragmentation < 0.55 {
            score -= 30.0 * (1.0 - fresh_match / 0.12);
        }
        if next_item_size > 0 && fresh_post > 0.0 {
            let fresh_exact_next = (fresh_post as u32) == next_item_size;
            let open_can_next = mean_residual >= next_item_size as f64;
            if fresh_exact_next && !open_can_next && fitting_bins_count <= 2 {
                score -= 52.0 * (1.0 - progress);
            }
            if (fresh_post as u32) < next_item_size && mean_residual > next_item_size as f64 {
                score += 21.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && fresh_post > next_item_size as f64 {
            let chain_post = fresh_post - next_item_size as f64;
            if chain_post <= 4.0 {
                score -= 34.0 * (1.0 - chain_post / 4.0) * (0.5 + 0.5 * (1.0 - progress));
            } else if chain_post <= 10.0 {
                score -= 9.5 * (1.0 - (chain_post - 4.0) / 6.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        if remaining_frac < 0.12 && fresh_post > 0.0 && !fresh_is_exact && mean_residual * open_bins_count as f64 > 3.0 * cap {
            score += 42.0 * (1.0 - remaining_frac / 0.12);
        }
        if fitting_bins_count == 1 && fresh_post > 0.0 && next_item_size > 0 {
            let stranded_here = bin_capacity.saturating_sub(item_size);
            let would_strand = stranded_here < next_item_size;
            if would_strand && stranded_here > 0 && stranded_here <= 8 {
                score -= 32.0 * (1.0 - progress);
            }
        }
        let open_capacity = mean_residual * open_bins_count as f64;
        let per_item_need = cap * 0.5;
        if remaining_frac > 0.25 && open_capacity < per_item_need * open_bins_count.max(1) as f64 * 0.5 {
            score -= 18.0 * (1.0 - progress);
        }
        if next_item_size > 0 && fresh_post > next_item_size as f64 {
            let after_next = fresh_post - next_item_size as f64;
            if after_next > 0.0 && after_next <= 8.0 && fragmentation < 0.5 {
                score -= 20.0 * (1.0 - after_next / 8.0) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        if next_item_size > 0 && fresh_post > 0.0 && (fresh_post as u32) < next_item_size {
            let slack_total = mean_residual * open_bins_count as f64;
            if slack_total > 2.0 * cap {
                score += 26.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && (fresh_post as u32) == next_item_size && fragmentation > 0.3 {
            score -= 44.0 * (0.5 + 0.5 * (1.0 - progress));
        }
        if fresh_post > 0.5 * cap && mean_residual < 0.2 * cap && remaining_frac > 0.3 && open_bins_count > 3 {
            score += 24.0 * (fresh_post / cap - 0.5) * 2.0 * (1.0 - progress);
        }
        if fitting_bins_count <= 1 && fresh_post > 0.45 * cap && next_item_size > 0 {
            let reachable = (next_item_size as f64 / fresh_post).min(1.0);
            if reachable < 0.5 {
                score += 18.0 * (0.5 - reachable) * (1.0 - progress);
            }
        }
        if next_item_size > 0 && fresh_post > 0.0 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 2 && fragmentation < 0.5 {
                score -= 7.0 * ((reps as f64).min(4.0) - 1.0) * (0.4 + 0.6 * (1.0 - progress));
                if rem <= 3 {
                    score -= 5.0 * (1.0 - progress);
                }
            }
        }
        if fresh_post > 0.35 * cap && remaining_frac > 0.2 && mean_residual * open_bins_count as f64 > 4.0 * cap && fragmentation < 0.45 {
            score += 20.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        if remaining_frac < 0.15 && fresh_post > 0.3 * cap {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.35;
            if open_space > est_need {
                score += 55.0 * (1.0 - remaining_frac / 0.15);
            }
        }
        if remaining_frac >= 0.15 && remaining_frac < 0.45 && fresh_post > 0.4 * cap && fragmentation > 0.4 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.45;
            if open_space > est_need {
                score += 28.0 * (1.0 - remaining_frac / 0.45);
            }
        }
        if next_item_size > 1 && fresh_post > 0.0 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 2 && rem == 0 && fragmentation < 0.4 {
                score -= 10.0 * ((reps as f64).min(4.0) - 1.0) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        if remaining_frac >= 0.45 && remaining_frac < 0.5 && fresh_post > 0.45 * cap && fragmentation > 0.5 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.55;
            if open_space > est_need {
                score += 22.0 * (1.0 - remaining_frac / 0.5);
            }
        }
        // gen 76: demand-aware fresh-bin refusal.
        if remaining_frac >= 0.05 && fresh_post > 0.3 * cap && next_item_size > 0 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (next_item_size as f64) * 0.42;
            if open_space > 1.15 * est_need {
                score += 30.0 * (1.0 - remaining_frac) * (fresh_post / cap - 0.3);
            }
        }
        // gen 76: fresh-bin dead-space cap.
        if fresh_post > 0.35 * cap && next_item_size > 0 && (fresh_post as u32) < next_item_size && fragmentation < 0.4 && remaining_frac > 0.15 {
            score += 16.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        // gen 81: tileability-aware open (refined gen 87: relax the
        // fragmentation gate to 0.35 and scale with progress so tiling
        // lanes are opened slightly more eagerly mid-stream).
        if next_item_size > 1 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 3 && rem == 0 && fragmentation < 0.35 {
                score -= (14.0 + 4.0 * progress) * ((reps as f64).min(5.0) - 2.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // MUTATION (gen 87): fresh-bin variance alignment — when the fresh
        // post-residual closely matches the mean open residual, opening
        // creates a homogeneous residual pool that is easier to tile later;
        // reward this modestly when fragmentation is moderate.
        if fresh_post > 0.0 && mean_residual > 0.0 && fragmentation > 0.2 && fragmentation < 0.6 && remaining_frac > 0.1 {
            let align = (fresh_post - mean_residual).abs() / cap;
            if align < 0.08 {
                score -= 10.0 * (1.0 - align / 0.08) * (1.0 - progress);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let item = item_size as f64;
    let post = post_residual as f64;
    let resid = bin_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer small post-residual (best-fit core).
    let mut score = post;

    // Reward near-perfect fills strongly (non-linear).
    if post == 0.0 {
        score -= 50.0;
    } else if post <= 5.0 {
        score -= 12.0 + (5.0 - post) * 2.0;
    } else if post <= 10.0 {
        score -= 6.0;
    }

    // Penalize dead space that is too small for likely future items
    // (typical items 10..80; residual < 10 is pure waste).
    if post > 0.0 && post < 10.0 {
        score += 15.0 * (10.0 - post) / 10.0;
    }

    // Coupling with mean residual: placing into a bin whose residual is far
    // from the mean leaves other bins more homogeneous -> easier future fits.
    let dev = (resid - mean_residual).abs();
    score += 0.15 * dev;

    // Lookahead (k=2): if next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post - nxt).abs() <= 1.0 {
            score -= 20.0;
        } else if post >= nxt && post - nxt < 10.0 {
            score -= 8.0;
        } else if nxt > post && nxt <= mean_residual {
            // next item can go elsewhere; neutral
            score += 0.0;
        } else if nxt > post {
            // next item won't fit here after placement; mild penalty if post becomes waste
            score += 4.0;
        }
    }

    // Last-chance bin: only bin that fits the item -> strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate detection (bin_residual == bin_capacity).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin: grows with number of open bins and progress.
        let mut new_bin_penalty = 25.0 + 2.0 * open_bins_count as f64 + 10.0 * progress;
        // But if this item would leave a large, awkward residual in every existing bin,
        // opening fresh may be better: penalize less when item is large.
        if item >= 0.7 * cap {
            new_bin_penalty -= 20.0;
        }
        // If item fits perfectly into a fresh bin, opening is cheap.
        if post == 0.0 {
            new_bin_penalty -= 15.0;
        }
        // Late in stream, consolidation matters more: harder to open new bins.
        if progress > 0.8 {
            new_bin_penalty += 15.0;
        }
        score += new_bin_penalty.max(0.0);
    } else {
        // Slight preference for tighter existing bins (relative fit quality).
        score += 10.0 * (1.0 - resid / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Layered dead-space rewards (lower post_residual = better).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 4 {
        score -= 260.0 + 4.4 * (4 - post_residual) as f64;
    } else if post_residual <= 10 {
        score -= 70.0 + 3.8 * (10 - post_residual) as f64;
    } else if post_residual <= 22 {
        score -= 14.0 + 1.6 * (22 - post_residual) as f64;
    } else if post_residual <= 32 {
        score -= 5.0 + 0.75 * (32 - post_residual) as f64;
    } else if post_residual <= 48 {
        score -= 1.2 + 0.24 * (48 - post_residual) as f64;
    } else {
        score -= 1.2 - 0.015 * (post_residual as f64 - 48.0);
    }

    // Progress-scaled weighting: tighten late in the stream.
    let w = 0.33 + 0.67 * progress * progress;
    score *= w;

    // Lookahead coupling with the next item.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 920.0;
        } else if next_item_size < post_residual {
            let two_step_waste = (post_residual - next_item_size) as f64;
            if two_step_waste <= 8.0 {
                score -= 140.0 - 2.3 * two_step_waste;
            } else {
                score -= 74.0 - 0.6 * two_step_waste;
            }
            if two_step_waste <= 3.0 {
                score -= 50.0;
            }
        } else {
            let miss = (next_item_size - post_residual) as f64;
            score += 0.95 * miss;
            if miss > 26.0 {
                score += 0.55 * (miss - 26.0);
            }
        }
        // Two-step exact-fill of the whole bin.
        let two_step = item_size + next_item_size;
        if two_step == bin_capacity {
            score -= 800.0;
        } else if two_step <= bin_capacity && bin_capacity - two_step <= 10 {
            score -= 200.0;
        }
    }

    // Slack-based scarcity boost when the next item fits here.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
        let boost = 38.0 + 28.0 * scarcity;
        score -= boost * (1.0 - slack / cap) * (0.6 + 0.4 * (1.0 - progress));
        if fitting_bins_count <= 2 {
            score -= 16.0 * (1.0 - slack / cap);
        }
        if slack == 0.0 {
            score -= 22.0 * (1.0 - progress);
        }
    }

    // Mean-residual harmony: prefer residuals near the mean, penalize
    // wasteful outliers.
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Stranded-residual scarcity penalty with two-step chain check.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let stranded = (next_item_size - post_residual) as f64;
        let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
        if stranded <= 10.0 {
            score += (9.0 + 1.2 * (10.0 - stranded)) * scarcity * (0.4 + 0.6 * (1.0 - progress));
        } else {
            let proximity = 1.0 - (stranded - 10.0).min(cap) / cap;
            score += 3.4 * proximity * scarcity * (1.0 - progress);
        }
        // gen 87: dead-space compaction gradient — when aggregate open slack
        // is large, a leftover that can't hold the next item is pure waste.
        if fitting_bins_count > 1 {
            let open_space = mean_residual * open_bins_count as f64;
            if open_space > 2.0 * cap {
                let frac = post_residual as f64 / next_item_size as f64;
                score += 10.0 * (1.0 - frac) * (0.5 + 0.5 * progress);
            }
        }
    }

    // Tiling/divisibility consolidation.
    if post_residual > 0 && next_item_size > 1 && next_item_size <= post_residual {
        let reps = post_residual / next_item_size;
        let rem = post_residual % next_item_size;
        if reps >= 1 && rem == 0 {
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            score -= (5.5 + 6.5 * scarcity) * (reps as f64).min(3.0) * (0.4 + 0.6 * (1.0 - progress));
        }
        // gen 87: near-multiple chain — leftover remainder after tiling is
        // small enough to be absorbed later.
        if reps >= 2 && rem <= 3 {
            score -= 6.0 * (1.0 - progress);
        }
    }

    // Fill-level momentum — reduce residual variance.
    if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 2 {
        let rel = post_residual as f64 / (mean_residual + 1.0);
        if rel < 0.5 {
            score -= 6.5 * (1.0 - rel / 0.5) * (0.4 + 0.6 * (1.0 - progress));
        }
        // gen 87: harmony bonus — residuals close to the mean keep the
        // spread tight, easing downstream fits.
        let harmony = (post_residual as f64 - mean_residual).abs() / cap;
        if harmony < 0.08 {
            score -= 7.0 * (1.0 - harmony / 0.08) * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    // Dead-ratio gradient scaled by aggregate open slack.
    if bin_residual != bin_capacity && fitting_bins_count > 1 && post_residual > 0 {
        let dead = (bin_residual - item_size) as f64;
        let dead_ratio = dead / cap;
        let scarcity = 1.0 / (fitting_bins_count as f64);
        let comp_slack = (mean_residual / cap).min(1.0);
        if dead_ratio > 0.08 {
            score += 6.5 * (dead_ratio - 0.08) * scarcity * comp_slack * (0.5 + 0.5 * (1.0 - progress));
            score += 2.2 * (dead / cap) * scarcity * comp_slack * (1.0 - progress);
        }
        if dead_ratio > 0.5 {
            score += 10.5 * (dead_ratio - 0.5) * (1.0 - progress);
        }
        // gen 87: half-empty-bin lookahead penalty — avoid burying large
        // residual bins with tiny items when the next item is also small.
        if dead_ratio > 0.35 && fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score += 7.5 * (dead_ratio - 0.35) * tightness * (1.0 - progress);
        }
        if next_item_size > 0 {
            let usable = next_item_size <= post_residual || (mean_residual as u32) >= next_item_size;
            if !usable {
                score += 9.5 * (post_residual as f64 / cap) * (0.35 + 0.65 * progress);
            }
        }
    }

    // Last chance bin: if this is the only fitting bin, prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 160.0;
    }

    // Unique-fit lookahead bonus.
    if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count == 1 && bin_residual != bin_capacity {
        let tightness = 1.0 - (post_residual - next_item_size) as f64 / cap;
        score -= 15.0 * (1.0 - progress) * (0.6 + 0.4 * tightness);
    }

    // Penalize creating small unusable dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 120.0;
    }

    // Early stream: keep flexibility; late stream: consolidate.
    score -= (1.0 - progress) * 20.0;

    // Slight preference for filling fuller bins when many bins are open.
    score += 0.1 * open_bins_count as f64 * (post_residual as f64 / cap);

    // Near-full chain extension.
    if post_residual > 0 && next_item_size > 0 && post_residual > next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next > 0 && after_next < 6 && progress > 0.35 {
            score -= 11.0 * (1.0 - after_next as f64 / 6.0) * (progress - 0.35);
        }
        if after_next > 0 && after_next <= 12 {
            let tail = after_next as f64;
            score -= (14.0 - 0.9 * tail) * (0.5 + 0.5 * (1.0 - progress));
        }
        // gen 87: mid-range chain scarcity bonus — an 8-16 leftover that is
        // scarce elsewhere is worth preserving for later small items.
        if after_next > 8 && after_next <= 16 && progress < 0.85 {
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            score -= (4.0 + 3.0 * scarcity) * (1.0 - (after_next as f64 - 8.0) / 8.0) * (1.0 - progress);
        }
        // gen 87: overshoot penalty — large overshoot beyond the next item
        // wastes space when many bins compete.
        if fitting_bins_count > 3 {
            let overshoot = after_next as f64;
            if overshoot > 16.0 {
                score += 1.6 * ((overshoot - 16.0) / cap).min(0.25) * (1.0 - progress);
            }
        }
    }

    // Consolidation pull late in the stream.
    if post_residual > 0 && fitting_bins_count > 2 && progress > 0.5 {
        let fill = 1.0 - post_residual as f64 / cap;
        score -= 5.0 * fill * (progress - 0.5);
    }

    // Orphaned mid-range residual penalty.
    if post_residual > 12 && post_residual < 40 && next_item_size > post_residual {
        let orphan = (post_residual as f64 - 12.0) / 28.0;
        let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
        score += 17.0 * orphan * scarcity * (0.5 + 0.5 * (1.0 - progress));
    }

    if bin_residual == bin_capacity {
        // NEW-BIN CANDIDATE branch.
        let fragmentation = (mean_residual / cap) * open_bins_count as f64;
        let huge_item = item_size as f64 > 0.7 * cap;
        let remaining = if total_items > step_index { total_items - step_index } else { 1 };
        let remaining_frac = remaining as f64 / total_items.max(1) as f64;
        let fresh_post = cap - item_size as f64;
        let fresh_is_exact = fresh_post <= 4.0 && fresh_post >= 0.0;

        if fragmentation > 0.55 || (huge_item && open_bins_count > 4) {
            score -= 66.0 + 46.0 * remaining_frac;
        } else if fresh_is_exact {
            score -= 134.0 + 66.0 * remaining_frac;
        } else {
            score += 400.0 - 82.0 * remaining_frac;
            if fitting_bins_count <= 3 && open_bins_count > 2 {
                score -= 30.0 + 18.0 * remaining_frac;
            }
        }

        let fresh_match = (fresh_post - mean_residual).abs() / cap;
        if fresh_match < 0.05 {
            score -= 76.0 * (1.0 - fresh_match / 0.05);
        }
        if remaining_frac < 0.05 && fresh_post > 0.0 && !fresh_is_exact {
            score += 160.0 * (fresh_post / cap);
        }
        if fresh_post > 0.0 && fresh_post <= 22.0 && !fresh_is_exact {
            score -= 26.0 * (1.0 - fresh_post / 22.0);
        }
        if fresh_post > 22.0 && fresh_post <= 40.0 && fragmentation < 0.35 {
            score -= 12.5 * (1.0 - (fresh_post - 22.0) / 18.0);
        }
        if fresh_post > 0.0 && fresh_match < 0.12 && fragmentation < 0.55 {
            score -= 30.0 * (1.0 - fresh_match / 0.12);
        }
        if next_item_size > 0 && fresh_post > 0.0 {
            let fresh_exact_next = (fresh_post as u32) == next_item_size;
            let open_can_next = mean_residual >= next_item_size as f64;
            if fresh_exact_next && !open_can_next && fitting_bins_count <= 2 {
                score -= 52.0 * (1.0 - progress);
            }
            if (fresh_post as u32) < next_item_size && mean_residual > next_item_size as f64 {
                score += 21.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && fresh_post > next_item_size as f64 {
            let chain_post = fresh_post - next_item_size as f64;
            if chain_post <= 4.0 {
                score -= 34.0 * (1.0 - chain_post / 4.0) * (0.5 + 0.5 * (1.0 - progress));
            } else if chain_post <= 10.0 {
                score -= 9.5 * (1.0 - (chain_post - 4.0) / 6.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        if remaining_frac < 0.12 && fresh_post > 0.0 && !fresh_is_exact && mean_residual * open_bins_count as f64 > 3.0 * cap {
            score += 42.0 * (1.0 - remaining_frac / 0.12);
        }
        // Refuse fresh bins late when open slack covers projected demand.
        if remaining_frac < 0.15 && fresh_post > 0.3 * cap {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.35;
            if open_space > est_need {
                score += 55.0 * (1.0 - remaining_frac / 0.15);
            }
        }
        // Mid-stream refusal band.
        if remaining_frac >= 0.15 && remaining_frac < 0.45 && fresh_post > 0.4 * cap && fragmentation > 0.4 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.45;
            if open_space > est_need {
                score += 28.0 * (1.0 - remaining_frac / 0.45);
            }
        }
        // Demand-aware fresh-bin refusal using next-item footprint.
        if remaining_frac >= 0.05 && fresh_post > 0.3 * cap && next_item_size > 0 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (next_item_size as f64) * 0.42;
            if open_space > 1.15 * est_need {
                score += 32.0 * (1.0 - remaining_frac) * (fresh_post / cap - 0.3);
            }
        }
        // Fresh-bin dead-space cap.
        if fresh_post > 0.35 * cap && next_item_size > 0 && (fresh_post as u32) < next_item_size && fragmentation < 0.4 && remaining_frac > 0.15 {
            score += 17.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        // Tiling-aware fresh-bin bonus.
        if next_item_size > 1 && fresh_post > 0.0 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 2 && rem == 0 && fragmentation < 0.4 {
                score -= 10.0 * ((reps as f64).min(4.0) - 1.0) * (0.4 + 0.6 * (1.0 - progress));
            }
            if reps >= 3 && rem == 0 && fragmentation < 0.3 {
                score -= 14.0 * ((reps as f64).min(5.0) - 2.0) * (0.5 + 0.5 * (1.0 - progress));
            }
            // gen 87: near-tile remnant bonus — small remainder after tiling
            // is easily absorbed, so favor these opens slightly.
            if reps >= 2 && rem > 0 && rem <= 3 && fragmentation < 0.4 {
                score -= 4.0 * (1.0 - progress);
            }
        }
        // Fresh-bin residual-magnitude guard.
        if fresh_post > 0.35 * cap && remaining_frac > 0.2 && mean_residual * open_bins_count as f64 > 4.0 * cap && fragmentation < 0.45 {
            score += 20.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        // Single-fit fresh-bin rescue.
        if fitting_bins_count <= 1 && fresh_post > 0.0 && next_item_size > 0 {
            let stranded_here = bin_capacity.saturating_sub(item_size);
            let would_strand = stranded_here < next_item_size;
            if would_strand && stranded_here > 0 && stranded_here <= 8 {
                score -= 32.0 * (1.0 - progress);
            }
        }
        // gen 87: oversized fresh-bin guard — when open slack is plentiful
        // and the fresh bin would remain more than half empty, refuse it
        // mid-stream to reduce dead space (addresses residual variance).
        if fresh_post > 0.5 * cap && mean_residual < 0.2 * cap && remaining_frac > 0.3 && open_bins_count > 3 {
            score += 24.0 * (fresh_post / cap - 0.5) * 2.0 * (1.0 - progress);
        }
        // gen 87: reachable-next guard — a fresh bin whose leftover can only
        // barely reach the next item's size is a poor open when it is the
        // only fitting candidate.
        if fitting_bins_count <= 1 && fresh_post > 0.45 * cap && next_item_size > 0 {
            let reachable = (next_item_size as f64 / fresh_post).min(1.0);
            if reachable < 0.5 {
                score += 18.0 * (0.5 - reachable) * (1.0 - progress);
            }
        }
        // gen 87: fresh exact-next bonus — opening a bin whose leftover
        // exactly equals the next item is a perfect two-step fill.
        if next_item_size > 0 && (fresh_post as u32) == next_item_size && fragmentation > 0.3 {
            score -= 44.0 * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let remaining_frac = if total_items > step_index { (total_items - step_index) as f64 / total_items.max(1) as f64 } else { 0.0 };
    let open_space = mean_residual * open_bins_count as f64;
    let x = pr / cap;

    // Base: post_residual (lower = better), scaled by progress weight.
    let mut score = pr * (0.33 + 0.67 * progress * progress);

    // Layered dead-space rewards on exact post-residual magnitudes.
    if post_residual == 0 {
        score -= 900.0;
    } else if post_residual <= 4 {
        score -= 230.0 + 4.2 * (4 - post_residual) as f64;
    } else if post_residual <= 10 {
        score -= 60.0 + 3.6 * (10 - post_residual) as f64;
    } else if post_residual <= 22 {
        score -= 12.5 + 1.5 * (22 - post_residual) as f64;
    } else if post_residual <= 32 {
        score -= 4.5 + 0.7 * (32 - post_residual) as f64;
    } else if post_residual <= 48 {
        score -= 1.0 + 0.22 * (48 - post_residual) as f64;
    } else {
        score -= 1.0 - 0.014 * (pr - 48.0);
    }

    // Non-linear polynomial coupling of post_residual with stream progress.
    let poly = x * x * (1.0 - x) * (1.0 - x);
    score -= 8.0 * poly * cap * (1.0 + progress * (1.0 - progress) * 4.0);

    // Lookahead coupling with the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr > 0.0 {
            if nx == pr {
                score -= 850.0;
            } else if nx < pr {
                let waste = pr - nx;
                if waste <= 8.0 {
                    score -= 120.0 - 2.3 * waste;
                } else {
                    score -= 65.0 - 0.58 * waste;
                }
                if waste <= 3.0 {
                    score -= 40.0;
                }
                // Tileability: post residual divisible by next item.
                let reps = post_residual / next_item_size;
                let rem = post_residual % next_item_size;
                if reps >= 2 && rem == 0 {
                    score -= 6.0 * ((reps as f64).min(4.0) - 1.0) * (1.0 - progress);
                }
            } else {
                let miss = nx - pr;
                score += 0.95 * miss;
                if miss > 26.0 {
                    score += 0.55 * (miss - 26.0);
                }
                // Stranded small residual: penalize when aggregate slack is large.
                if fitting_bins_count > 1 && open_space > 2.0 * cap {
                    let frac = pr / nx;
                    score += 9.0 * (1.0 - frac) * (0.5 + 0.5 * progress);
                }
            }
        }
    }

    // Last-chance bonus: favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 15.0 * (1.0 - progress);
        if next_item_size > 0 && post_residual >= next_item_size {
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score -= 14.0 * (1.0 - progress) * (0.6 + 0.4 * tightness);
        }
    }

    // Scarcity boost when few bins can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual > 0 {
        let slack = (post_residual - next_item_size) as f64;
        let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
        score -= (30.0 + 26.0 * scarcity) * (1.0 - slack / cap) * (0.6 + 0.4 * (1.0 - progress));
        if fitting_bins_count <= 2 {
            score -= 15.0 * (1.0 - slack / cap);
        }
    }

    // Late-stream consolidation pull.
    if post_residual > 0 && fitting_bins_count > 2 && progress > 0.5 {
        let fill = 1.0 - pr / cap;
        score -= 5.0 * fill * (progress - 0.5);
    }

    // Mild penalty for proliferating open bins early in the stream.
    score += (open_bins_count as f64).ln() * (1.0 - progress) * 2.0;

    // NEW-BIN CANDIDATE handling: decide whether opening is worthwhile.
    if bin_residual == bin_capacity {
        let fresh_post = cap - item_size as f64;
        let fragmentation = (mean_residual / cap) * open_bins_count.max(1) as f64;
        let huge_item = item_size as f64 > 0.7 * cap;
        let fresh_is_exact = fresh_post <= 4.0 && fresh_post >= 0.0;

        if fragmentation > 0.55 || (huge_item && open_bins_count > 4) {
            score -= 60.0 + 46.0 * remaining_frac;
        } else if fresh_is_exact {
            score -= 130.0 + 66.0 * remaining_frac;
        } else {
            score += 380.0 - 82.0 * remaining_frac;
            if fitting_bins_count <= 3 && open_bins_count > 2 {
                score -= 28.0 + 18.0 * remaining_frac;
            }
        }

        // Demand-aware refusal: don't open when slack elsewhere suffices.
        if remaining_frac >= 0.05 && fresh_post > 0.3 * cap && next_item_size > 0 {
            let est_need = (total_items - step_index) as f64 * next_item_size as f64 * 0.42;
            if open_space > 1.15 * est_need {
                score += 30.0 * (1.0 - remaining_frac) * (fresh_post / cap - 0.3);
            }
        }

        // Tileable fresh bin: exact multiple of next item.
        if next_item_size > 1 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 3 && rem == 0 && fragmentation < 0.3 {
                score -= 14.0 * ((reps as f64).min(5.0) - 2.0) * (0.5 + 0.5 * (1.0 - progress));
            }
            if reps >= 2 && rem <= 3 && fragmentation < 0.5 {
                score -= 7.0 * ((reps as f64).min(4.0) - 1.0) * (0.4 + 0.6 * (1.0 - progress));
            }
        }

        // Fresh bin chain lookahead.
        if next_item_size > 0 && fresh_post > next_item_size as f64 {
            let after_next = fresh_post - next_item_size as f64;
            if after_next <= 4.0 {
                score -= 32.0 * (1.0 - after_next / 4.0) * (0.5 + 0.5 * (1.0 - progress));
            } else if after_next <= 10.0 {
                score -= 9.0 * (1.0 - (after_next - 4.0) / 6.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }

        // Fresh bin dead-space cap.
        if fresh_post > 0.35 * cap && next_item_size > 0 && (fresh_post as u32) < next_item_size && fragmentation < 0.4 && remaining_frac > 0.15 {
            score += 16.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }

        // Match against mean residual.
        let fresh_match = (fresh_post - mean_residual).abs() / cap;
        if fresh_match < 0.05 {
            score -= 70.0 * (1.0 - fresh_match / 0.05);
        }

        // End-of-stream: refuse to open with big dead space.
        if remaining_frac < 0.05 && fresh_post > 0.0 && !fresh_is_exact {
            score += 150.0 * (fresh_post / cap);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let pr_norm = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = pr
        - 4.0 * pr_norm * (1.0 - pr_norm) * cap * (0.5 + 0.5 * progress)
        + (pr_norm * pr_norm) * cap * (1.0 - progress)
        + fit_ratio * pr_norm * cap * 2.0 * (1.0 - progress);

    // Reward tight fits smoothly
    let tightness = 1.0 - pr_norm;
    score -= tightness * tightness * cap * 1.5;

    // Last-chance bin penalty relief
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 + progress);
    }

    // Lookahead: favor bins leaving room for the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 6.0 * (1.0 - (pr - nx) / cap) * (1.0 - progress);
        } else {
            score += 4.0 * (nx - pr) / cap * cap * 0.1;
        }
    }

    // Mild penalty for opening new bins when many bins are open
    if bin_residual == bin_capacity {
        score += 5.0 + 0.5 * open_bins_count as f64 * (1.0 - progress);
        score -= 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
