            let two_step_waste = (post_residual - next_item_size) as f64;
            if two_step_waste <= 8.0 {
                score -= 135.0 - 2.3 * two_step_waste;
            } else {
                score -= 72.0 - 0.58 * two_step_waste;
            }
            if two_step_waste <= 3.0 {
                score -= 48.0;
            }
        } else {
            let miss = (next_item_size - post_residual) as f64;
            score += 0.95 * miss;
            if miss > 26.0 {
                score += 0.55 * (miss - 26.0);
            }
        }
    }

    // Scarcity-weighted tight-fit bonus.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
        let boost = 36.0 + 26.0 * scarcity;
        score -= boost * (1.0 - slack / cap) * (0.6 + 0.4 * (1.0 - progress));
        if fitting_bins_count <= 2 {
            score -= 15.0 * (1.0 - slack / cap);
        }
        if slack == 0.0 {
            score -= 20.0 * (1.0 - progress);
