pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Penalize leaving dead space that the next item could not use well.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0; // dead space for lookahead item
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0; // lookahead fits
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // and no good fit exists (large item in fresh bin is fine).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let base_penalty = 8.0 + 10.0 * (1.0 - item_size as f64 / bin_capacity as f64);
        // Late in stream, prefer closing out open bins instead of new ones.
        score += base_penalty + 6.0 * progress;
        // If many open bins already, discourage opening more.
        score += 0.5 * open_bins_count as f64;
    }

    // Mild preference for bins with residual close to mean (balanced packing),
    // but slightly favor fuller-than-average bins to consolidate.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // Penalize very small residuals that only tiny items could use.
    if post_residual > 0 && post_residual < 10 {
        score += 5.0;
    }

    score
}

