        // packs into existing slack instead of fragmenting.
        if remaining_frac < 0.1 && fresh_post > 0.25 * cap && next_item_size > 0 && (fresh_post as u32) < next_item_size {
            score += 34.0 * (1.0 - remaining_frac / 0.1) * (fresh_post / cap - 0.25) * 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;
    let poly = 1.0 + 0.6 * progress - 0.9 * p2 + 0.5 * p3;

    let mut score = pr * poly;

    // Penalize small unusable residuals more as stream advances
    let dead = if norm_pr > 0.0 { (norm_pr * (1.0 - norm_pr)).sqrt() } else { 0.0 };
    score += (cap - pr) * (1.0 - dead) * (0.3 + 0.7 * progress);

    // Reward tight fits
    score -= (item_size as f64 / cap) * 8.0;

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 5.0;
    }

    // Lookahead: favor leaving room for next item
    let ni = next_item_size as f64;
    if ni > 0.0 {
        let gap = pr - ni;
        if gap >= 0.0 {
            score -= 2.0 * (gap / cap);
        } else {
            score += 1.5 * (-gap / cap) * (0.5 + progress);
        }
    }

    // Slight penalty for bin sprawl
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Layered dead-space rewards (lower post_residual = better).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 4 {
        score -= 260.0 + 4.4 * (4 - post_residual) as f64;
    } else if post_residual <= 10 {
