    // MUTATION (gen 91): mean-harmony bonus — residuals close to the mean
    // keep the slack pool uniform and reusable by future items.
    if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 1 && bin_residual != bin_capacity {
        let harmony = (post_residual as f64 - mean_residual).abs() / cap;
