        // avoids fragmenting scarce space; reward modestly.
        if remaining_frac > 0.25 && open_bins_count > 0 {
            let per_bin_slack = mean_residual;
            if per_bin_slack < 0.5 * cap && fitting_bins_count <= 2 {
                score -= 18.0 * (1.0 - progress);
            }
        }
        // MUTATION (gen 91): stranded fresh leftover with reusable open slack.
        if next_item_size > 0 && fresh_post > 0.0 && (fresh_post as u32) < next_item_size {
            let slack_total = mean_residual * open_bins_count as f64;
            if slack_total > 2.0 * cap {
                score += 26.0 * (1.0 - progress);
            }
        }
        // MUTATION (gen 91): exact-next fresh bonus — a fresh bin whose
        // leftover exactly matches the next item size creates a perfect
        // two-item bin; reward when competition is weak.
        if next_item_size > 0 && (fresh_post as u32) == next_item_size && fragmentation > 0.3 {
            score -= 44.0 * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Base tightness reward: prefer small post_residual (best-fit core).
    score -= 0.35 * (bin_residual as f64 - post_residual as f64);

    // Harmonic class of post_residual: dead space that is a multiple of common
    // item sizes (10..=20 classes) is more reusable, reward it.
    let pr = post_residual;
    if pr > 0 {
        let reusable = (pr % 10 == 0) as f64 + (pr % 20 == 0) as f64 + (pr % 25 == 0) as f64;
        score -= 4.0 * reusable;
    } else {
        // Perfect closure of the bin is ideal.
        score -= 25.0;
    }

    // Integer-division thresholds: classify post_residual into usability bands.
    let band = pr / 25; // 0,1,2,3
    score += match band {
        0 => 0.0,               // nearly full: excellent
        1 => 3.0,               // 25..49 left
        2 => 8.0,               // 50..74 left
        _ => 12.0,              // mostly empty: wasteful placement
    };

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr {
            score -= 6.0 + 0.2 * (next_item_size as f64);
        } else {
            // Next item cannot fit here; penalize more when this bin was the only option.
            score += 2.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: only open a new bin when all open bins fit badly.
    if bin_residual == bin_capacity {
        // Mild penalty so a decent existing fit wins; reduced late in the stream
        // and when mean residual across open bins is small (they are nearly full).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 30.0 + 15.0 * (1.0 - progress) + 0.15 * mean_residual;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative
        }
    }

    // Slight preference to consolidate into fewer bins when many are open.
    score += 0.02 * open_bins_count as f64;

    score
}

