        }
    }

    // MUTATION (gen 92): harmony band — residuals close to the mean keep the
    // residual distribution tight; reward a narrow harmony band.
    if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 1 {
        let harmony = (post_residual as f64 - mean_residual).abs() / cap;
        if harmony < 0.08 {
