        let fill = 1.0 - post_residual as f64 / cap;
        score -= 5.0 * fill * (progress - 0.5);
    }

    // Orphaned mid-range residual penalty.
    if post_residual > 12 && post_residual < 40 && next_item_size > post_residual {
        let orphan = (post_residual as f64 - 12.0) / 28.0;
        let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
        score += 17.0 * orphan * scarcity * (0.5 + 0.5 * (1.0 - progress));
    }

    // MUTATION (gen 92): modulo-chain exactness — a residual that tiles
    // exactly by the next item (chain == 0) is a zero-waste lane; reward
    // it, and mildly reward near-tiles (chain <= 3). Borrowed from the
    // best heuristic to attack the residual-variance weakness.
    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let chain = post_residual % next_item_size.max(1);
        if chain == 0 {
