        } else if chain <= 3 {
            score -= 11.0 * (1.0 - progress);
        }
    }

    // MUTATION (gen 92): dead-space compaction gradient — when the leftover
    // cannot hold the next item but aggregate open slack elsewhere can, the
    // leftover here is pure waste; penalize proportionally.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
        && fitting_bins_count > 1 {
        let open_space = mean_residual * open_bins_count as f64;
        if open_space > 2.0 * cap {
            let frac = post_residual as f64 / next_item_size as f64;
            score += 10.0 * (1.0 - frac) * (0.5 + 0.5 * progress);
        }
    }

    // MUTATION (gen 92): residual-harmony bonus — bins whose post-residual
    // sits close to the mean keep the residual distribution tight, easing
    // future fits; reward closeness only among several candidates.
    if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 1 {
        let harmony = (post_residual as f64 - mean_residual).abs() / cap;
        if harmony < 0.08 {
            score -= 9.0 * (1.0 - harmony / 0.08) * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    // MUTATION (gen 92): tight-reuse bonus — when the post-residual holds
    // the next item with less than one full repetition of slack, several
    // candidates exist, and the bin is already deep, prefer it to squeeze
    // out the last bins.
    if next_item_size > 0 && post_residual >= next_item_size
        && post_residual < 2 * next_item_size.max(1) && fitting_bins_count > 2
        && bin_residual != bin_capacity {
