        if fitting_bins_count <= 1 && fresh_post > 0.0 && next_item_size > 0 {
            let stranded_here = bin_capacity.saturating_sub(item_size);
            let would_strand = stranded_here < next_item_size;
            if would_strand && stranded_here > 0 && stranded_here <= 8 {
                score -= 32.0 * (1.0 - progress);
            }
        }
        // MUTATION (gen 92): fresh-bin chain-after-next — when the fresh
        // bin's leftover after absorbing the next item is itself tileable
        // (exact multiple) or near-zero, the new bin becomes a productive
        // lane rather than scattered slack; deepen the reward.
        if next_item_size > 0 && fresh_post > next_item_size as f64 {
            let after_next = fresh_post - next_item_size as f64;
            if after_next > 0.0 && after_next <= 8.0 && fragmentation < 0.5 {
                score -= 20.0 * (1.0 - after_next / 8.0) * (0.4 + 0.6 * (1.0 - progress));
            } else if next_item_size > 1 && (after_next as u32) % next_item_size == 0 && fragmentation < 0.4 {
                score -= 8.0 * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // MUTATION (gen 92): fresh-bin exact-next celebration — opening a
        // bin whose leftover exactly matches the next item converts the
        // open into a guaranteed zero-waste fill; reward when fragmentation
        // is non-trivial so the lane actually gets used.
        if next_item_size > 0 && (fresh_post as u32) == next_item_size && fragmentation > 0.3 {
            score -= 44.0 * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: penalize wasted residual non-linearly (dead space grows quadratically in relative waste).
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste_ratio * waste_ratio;

    // Perfect-fit reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Tight fit reward: item fills a large fraction of the bin's residual.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill;

    // Lookahead coupling: reward leaving residual that can host the next item exactly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            let gap = (post_residual - next_item_size) as f64;
            score += 0.35 * gap;
        }
        // Penalize residuals that are too small to ever be useful again.
        if post_residual < next_item_size.min(20) {
            score += 8.0;
        }
    } else {
        // Last item: strongly prefer minimizing post residual.
        score += 0.5 * post_residual as f64;
    }

    // Last-chance bin: this is the only bin that fits; strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // the item fits poorly everywhere else and there is slack in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = post_residual as f64 > 30.0; // item is small relative to capacity
        let mut open_bonus = 0.0;
        if poor_fit && open_bins_count > 2 {
            open_bonus -= 15.0 * (open_bins_count as f64).sqrt();
        }
        // Late in the stream, avoid opening new bins that will stay mostly empty.
        open_bonus += 50.0 * progress;
        score += 10.0 + open_bonus;
    }

    // Global-state coupling: when mean residual across open bins is high,
    // prefer bins that reduce the spread (place into bins below the mean).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    score += 0.4 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

