        if dead_ratio > 0.35 && fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score += 7.5 * (dead_ratio - 0.35) * tightness * (1.0 - progress);
        }
        // MUTATION (gen 94): overshoot penalty — residuals far above the
        // next item in many-fitting-bin contexts scatter slack.
        if post_residual > 0 && next_item_size > 0 && fitting_bins_count > 3 {
            let overshoot = post_residual.saturating_sub(next_item_size) as f64;
            if overshoot > 16.0 {
                score += 1.6 * ((overshoot - 16.0) / cap).min(0.25) * (1.0 - progress);
            }
        }
    }

    // Last chance bin: if this is the only fitting bin, prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 160.0;
    }

    // Unique-fit lookahead bonus — when only this bin can also absorb the
    // next item after this placement, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count == 1 && bin_residual != bin_capacity {
        let tightness = 1.0 - (post_residual - next_item_size) as f64 / cap;
        score -= 15.0 * (1.0 - progress) * (0.6 + 0.4 * tightness);
    }

    // Penalize creating small unusable dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 120.0;
    }

    // Early stream: keep flexibility; late stream: consolidate.
    score -= (1.0 - progress) * 20.0;

    // Slight preference for filling fuller bins when many bins are open.
    score += 0.1 * open_bins_count as f64 * (post_residual as f64 / cap);

    // Near-full chain extension — reward placements whose post-residual
    // after the next item is tiny, extended earlier into the stream.
    if post_residual > 0 && next_item_size > 0 && post_residual > next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next > 0 && after_next < 6 && progress > 0.35 {
            score -= 11.0 * (1.0 - after_next as f64 / 6.0) * (progress - 0.35);
        }
        if after_next > 0 && after_next <= 12 {
            let tail = after_next as f64;
            score -= (14.0 - 0.9 * tail) * (0.5 + 0.5 * (1.0 - progress));
        }
        // MUTATION (gen 94): moderate tail lane — after_next in 8..16 also
        // gets a scarcity-scaled bonus so mid-size leftovers are reused.
        if after_next > 8 && after_next <= 16 && progress < 0.85 {
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            score -= (4.0 + 3.0 * scarcity) * (1.0 - (after_next - 8) as f64 / 8.0) * (1.0 - progress);
        }
    }

    // Consolidation pull — late in the stream, prefer the bin whose
    // placement brings it closest to full, tightening residual spread.
    if post_residual > 0 && fitting_bins_count > 2 && progress > 0.5 {
        let fill = 1.0 - post_residual as f64 / cap;
        score -= 5.0 * fill * (progress - 0.5);
    }

    // Orphaned mid-range residual penalty — residuals too small for the
    // next item but too big to ignore are pure waste.
    if post_residual > 12 && post_residual < 40 && next_item_size > post_residual {
        let orphan = (post_residual as f64 - 12.0) / 28.0;
        let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
        score += 17.0 * orphan * scarcity * (0.5 + 0.5 * (1.0 - progress));
    }

    if bin_residual == bin_capacity {
        // NEW-BIN CANDIDATE branch.
        let fragmentation = (mean_residual / cap) * open_bins_count as f64;
        let huge_item = item_size as f64 > 0.7 * cap;
        let remaining = if total_items > step_index { total_items - step_index } else { 1 };
        let remaining_frac = remaining as f64 / total_items.max(1) as f64;
        let fresh_post = cap - item_size as f64;
        let fresh_is_exact = fresh_post <= 4.0 && fresh_post >= 0.0;

        if fragmentation > 0.55 || (huge_item && open_bins_count > 4) {
            score -= 66.0 + 46.0 * remaining_frac;
        } else if fresh_is_exact {
            score -= 134.0 + 66.0 * remaining_frac;
        } else {
            score += 400.0 - 82.0 * remaining_frac;
            if fitting_bins_count <= 3 && open_bins_count > 2 {
                score -= 30.0 + 18.0 * remaining_frac;
            }
        }

        let fresh_match = (fresh_post - mean_residual).abs() / cap;
        if fresh_match < 0.05 {
            score -= 76.0 * (1.0 - fresh_match / 0.05);
        }
        if remaining_frac < 0.05 && fresh_post > 0.0 && !fresh_is_exact {
            score += 160.0 * (fresh_post / cap);
        }
        if fresh_post > 0.0 && fresh_post <= 22.0 && !fresh_is_exact {
            score -= 26.0 * (1.0 - fresh_post / 22.0);
        }
        if fresh_post > 22.0 && fresh_post <= 40.0 && fragmentation < 0.35 {
            score -= 12.5 * (1.0 - (fresh_post - 22.0) / 18.0);
        }
        if fresh_post > 0.0 && fresh_match < 0.12 && fragmentation < 0.55 {
            score -= 30.0 * (1.0 - fresh_match / 0.12);
        }
        if next_item_size > 0 && fresh_post > 0.0 {
            let fresh_exact_next = (fresh_post as u32) == next_item_size;
            let open_can_next = mean_residual >= next_item_size as f64;
            if fresh_exact_next && !open_can_next && fitting_bins_count <= 2 {
                score -= 52.0 * (1.0 - progress);
            }
            if (fresh_post as u32) < next_item_size && mean_residual > next_item_size as f64 {
                score += 21.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && fresh_post > next_item_size as f64 {
            let chain_post = fresh_post - next_item_size as f64;
            if chain_post <= 4.0 {
                score -= 34.0 * (1.0 - chain_post / 4.0) * (0.5 + 0.5 * (1.0 - progress));
            } else if chain_post <= 10.0 {
                score -= 9.5 * (1.0 - (chain_post - 4.0) / 6.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        if remaining_frac < 0.12 && fresh_post > 0.0 && !fresh_is_exact && mean_residual * open_bins_count as f64 > 3.0 * cap {
            score += 42.0 * (1.0 - remaining_frac / 0.12);
        }
        // Refuse fresh bins late when open slack covers projected demand.
        if remaining_frac < 0.15 && fresh_post > 0.3 * cap {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.35;
            if open_space > est_need {
                score += 55.0 * (1.0 - remaining_frac / 0.15);
            }
        }
        // Mid-stream refusal band.
        if remaining_frac >= 0.15 && remaining_frac < 0.45 && fresh_post > 0.4 * cap && fragmentation > 0.4 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.45;
            if open_space > est_need {
                score += 28.0 * (1.0 - remaining_frac / 0.45);
            }
        }
        // Demand-aware fresh-bin refusal using next-item footprint.
        if remaining_frac >= 0.05 && fresh_post > 0.3 * cap && next_item_size > 0 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (next_item_size as f64) * 0.42;
            if open_space > 1.15 * est_need {
                score += 32.0 * (1.0 - remaining_frac) * (fresh_post / cap - 0.3);
            }
        }
        // Fresh-bin dead-space cap — opening a bin whose leftover cannot hold
        // the next item is pure dead space.
        if fresh_post > 0.35 * cap && next_item_size > 0 && (fresh_post as u32) < next_item_size && fragmentation < 0.4 && remaining_frac > 0.15 {
            score += 17.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        // Tiling-aware fresh-bin bonus: exact multiples of the next item.
        if next_item_size > 1 && fresh_post > 0.0 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 2 && rem == 0 && fragmentation < 0.4 {
                score -= 10.0 * ((reps as f64).min(4.0) - 1.0) * (0.4 + 0.6 * (1.0 - progress));
            }
            // Deep tiling lane — three or more exact repetitions with low
            // fragmentation creates a dedicated tiling bin; deepen the reward.
            if reps >= 3 && rem == 0 && fragmentation < 0.3 {
                score -= 14.0 * ((reps as f64).min(5.0) - 2.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // Fresh-bin residual-magnitude guard.
        if fresh_post > 0.35 * cap && remaining_frac > 0.2 && mean_residual * open_bins_count as f64 > 4.0 * cap && fragmentation < 0.45 {
            score += 20.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        // Single-fit fresh-bin rescue — if no open bin can hold the next
        // item and the fresh bin's leftover would strand it, discourage
        // opening unless the stranded slack is tiny.
        if fitting_bins_count <= 1 && fresh_post > 0.0 && next_item_size > 0 {
            let stranded_here = bin_capacity.saturating_sub(item_size);
            let would_strand = stranded_here < next_item_size;
            if would_strand && stranded_here > 0 && stranded_here <= 8 {
                score -= 32.0 * (1.0 - progress);
            }
        }
        // MUTATION (gen 94): mid-stream fresh-bin reachability guard — when
        // the fresh leftover can only absorb a small fraction of the next
        // item's footprint over many remaining items, discourage the open.
        if fitting_bins_count <= 1 && fresh_post > 0.45 * cap && next_item_size > 0 && remaining_frac > 0.3 {
            let reachable = (next_item_size as f64 / fresh_post).min(1.0);
            if reachable < 0.5 {
                score += 18.0 * (0.5 - reachable) * (1.0 - progress);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // 2-step lookahead: reward when the next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chain: bin closed by next item
        } else if next_item_size < post_residual {
            // next item fits; reward proportional to how much it consumes
            let frac = next_item_size as f64 / post_residual as f64;
            score -= 18.0 * frac;
        } else {
            // next item cannot use this residual; penalize large dead space
            score += 0.25 * (post_residual as f64);
        }
    }

    // Compare against mean residual: prefer bins whose residual is below average
    // (consolidating space) when placing here.
    let dev = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
    score += 6.0 * dev;

    // Last-chance bin: strongly favor using it to avoid waste.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is generally costly,
    // penalize it unless the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        let poor_fit = (item_size as f64) / (bin_capacity as f64) < 0.35;
        let no_lookahead_chain = next_item_size > 0 && post_residual > 0 && next_item_size != post_residual;
        let mut new_bin_penalty = 30.0;
        if poor_fit { new_bin_penalty -= 15.0; }
        if no_lookahead_chain { new_bin_penalty += 5.0; }
        if open_bins_count == 0 { new_bin_penalty = -10.0; }
        score += new_bin_penalty;
        // New bin has perfect lookahead room; slight bonus if item is large.
        score -= 0.1 * (item_size as f64);
    }

    // Progress-based drift: later in the stream, be slightly more conservative
    // about leaving large residuals (fewer chances to fix them).
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += 3.0 * progress * (post_residual as f64) / (bin_capacity as f64);
    }

    score
}

