            score += 22.0 * (fresh_post / cap - 0.4) * (1.0 - progress);
        }
        // MUTATION (gen 94): fresh-bin exact-closure bonus — when the fresh
        // bin's post-residual exactly equals the next item size, opening it
        // sets up a guaranteed zero-dead-space follow-up; reward it strongly
        // when fragmentation is not already high.
        if next_item_size > 0 && (fresh_post as u32) == next_item_size && fragmentation <= 0.3 {
            score -= 18.0 * (0.4 + 0.6 * (1.0 - progress));
        }
        // MUTATION (gen 94): fresh-bin strand guard — refuse fresh bins whose
        // post-residual is large AND cannot host the next item while other
        // open bins can; this dead space is unrecoverable in-stream.
        if next_item_size > 0 && fresh_post > 0.3 * cap && (fresh_post as u32) < next_item_size
            && (mean_residual as u32) >= next_item_size && fitting_bins_count > 1 && remaining_frac > 0.1 {
            score += 14.0 * (fresh_post / cap - 0.3) * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 20.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Penalize creating dead space that nothing typical can use:
    // small post-residual pockets relative to mean residual landscape.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 0.5;
    }

    // Lookahead coupling: reward if next item can use this bin's post-residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // perfect chain
        } else if next_item_size < post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; slight penalty for wasting space now
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Many open bins with high mean residual: prefer consolidating into
    // bins that are already fragmented (below mean residual => emptier).
    if open_bins_count > 2 {
        let dev = mean_residual - bin_residual as f64;
        score += 0.15 * dev; // prefer bins with residual below mean (fuller bins)
    }

    // Time horizon: early in stream, be conservative (favor tight fits less
    // aggressively to keep flexibility); late in stream, squeeze hard.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let urgency = 1.0 + progress;
    score -= urgency * (1.0 - fit_ratio) * 10.0;

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item fits poorly everywhere (large item, small fit_ratio) or when
    // open bins are all nearly full.
    if bin_residual == bin_capacity {
        let avg_open_fill = bin_capacity as f64 - mean_residual;
        let crowdedness = avg_open_fill / bin_capacity as f64;
        // Base new-bin score: its residual is large, so add a handicap that
        // shrinks as existing bins become crowded or item is large.
        let handicap = 20.0 * (1.0 - fit_ratio) * (1.0 - crowdedness);
        score += handicap;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            // fresh bin gives lookahead room; mild bonus
            score -= 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Layered dead-space rewards (lower post_residual = better).
    if post_residual == 0 {
        score -= 980.0;
    } else if post_residual <= 4 {
        score -= 250.0 + 4.2 * (4 - post_residual) as f64;
    } else if post_residual <= 10 {
        score -= 64.0 + 3.6 * (10 - post_residual) as f64;
    } else if post_residual <= 22 {
        score -= 13.5 + 1.5 * (22 - post_residual) as f64;
