pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let mut score = post_residual as f64 * (1.0 + 0.4 * progress);

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: residual too small for the smallest item class.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Harmonic class of post_residual: residues divisible by 10 are more reusable.
    let r = post_residual % 10;
    if r == 0 && post_residual > 0 {
        score -= 8.0;
    } else {
        score += (r as f64) * 0.7;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Lookahead (k=2): reward bins that can also host the next item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0;
        } else {
            // Next item won't fit here: penalize proportional to wasted usable space.
            score += (post_residual.min(next_item_size.saturating_sub(1)) as f64).sqrt() * 3.0;
        }
    }

    // Mild bonus when this bin is below average fullness (balance spreading).
    if (post_residual as f64) > mean_residual {
        score += 2.0;
    }

    // New-bin candidate: only attractive for large items or when no open bin fits.
    if bin_residual == bin_capacity {
        score = 65.0 + item_size as f64 * 0.6;
        if fitting_bins_count == 0 {
            score -= 200.0; // must open a new bin
        }
        if next_item_size > 0 && next_item_size as f64 + item_size as f64 > bin_capacity as f64 {
            score -= 12.0; // next item forces a new bin anyway; start fresh now
        }
        score += progress * 5.0;
    }

    score
}

