        // items are placed, opening a fresh bin with large dead space is
        // almost never recoverable; penalize harder as the stream ends.
        if remaining_frac < 0.1 && fresh_post > 0.2 * cap && !fresh_is_exact {
            score += 45.0 * (fresh_post / cap - 0.2) * (1.0 - remaining_frac / 0.1);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // plausible future item (min item size 1, but realistically small gaps
    // below ~15) are wasted capacity -> heavy penalty.
    if post_residual > 0 {
        if post_residual < 15 {
            score += 60.0 * (1.0 - post_residual as f64 / 15.0);
        } else if post_residual < 30 {
            score += 12.0 * (1.0 - (post_residual as f64 - 15.0) / 15.0);
        }
    } else {
        // Perfect fit: strong reward.
        score -= 80.0;
    }

    // Reward tight fits generally: fraction of bin consumed by this item.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill;

    // Open-bin pressure: when many bins are open, prefer consolidating into
    // existing bins rather than spawning more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 1.5 * open_bins_count as f64 * (0.4 + 0.6 * progress);

    // Deviation from mean residual: bins far below mean residual are the
    // "cramped" ones; using them frees cleaner bins later.
    let dev = bin_residual as f64 - mean_residual;
    score -= 0.35 * dev;

    // Last-chance bin: if this is the only bin that fits, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // strongly favor this placement (chained packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 70.0;
        } else if post_residual > next_item_size {
            let next_gap = post_residual - next_item_size;
            if next_gap < 15 {
                score -= 20.0 * (1.0 - next_gap as f64 / 15.0);
            }
        } else {
            // Next item cannot use the gap -> mild penalty proportional to gap.
            score += 0.2 * (next_item_size - post_residual) as f64;
        }
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Only prefer it when the item is large and no good squeeze exists;
    // otherwise make the fresh bin slightly unattractive.
    if bin_residual == bin_capacity {
        let waste = bin_capacity - item_size;
        if waste < 15 {
            score -= 40.0; // large item into fresh bin is fine
        } else {
            score += 18.0 + 0.2 * waste as f64;
        }
    }

    score
}

