    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Reward when next item also fits into the remaining space (chain placements).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0 + (post_residual - next_item_size) as f64;
    }

    // Penalize dead space: residual too small for any plausible future item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 2.0;
    }

    // Penalize small unusable residuals (dead space below typical item sizes).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Prefer bins whose residual is already below mean (tight bins get filled first).
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // Mild pressure to use open bins when many are already open.
    score += open_bins_count as f64 * 5.0;

    // Slight late-stream conservatism: prefer tight fits as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * progress * 0.3;

    score
}

