            }
        }
        if next_item_size > 0 && fresh_post > 0.4 * cap && (fresh_post as u32) < next_item_size
            && open_capacity > 2.0 * cap && remaining_frac > 0.25 {
            score += 22.0 * (fresh_post / cap - 0.4) * (1.0 - progress);
        }
        if next_item_size > 0 && (fresh_post as u32) == next_item_size && fragmentation <= 0.3 {
            score -= 18.0 * (0.4 + 0.6 * (1.0 - progress));
        }
        if next_item_size > 0 && fresh_post > 0.3 * cap && (fresh_post as u32) < next_item_size
            && (mean_residual as u32) >= next_item_size && fitting_bins_count > 1 && remaining_frac > 0.1 {
            score += 14.0 * (fresh_post / cap - 0.3) * (1.0 - progress);
        }
        // MUTATION (gen 96): fresh-bin tileability bonus — when the fresh
        // bin's post-residual is an exact multiple of the next item size
        // with >= 2 reps, opening creates a dedicated tiling lane that
        // eliminates dead space over the following placements; reward
        // strongest when fragmentation is still low.
        if next_item_size > 1 && (fresh_post as u32) >= next_item_size && fragmentation < 0.45 {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 2 && rem == 0 {
                score -= (6.0 + 4.0 * ((reps as f64).min(4.0) - 1.0)) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on wasted residual, modulated by stream progress.
    let mut score = pr * (1.0 + 2.0 * norm_pr * (1.0 + progress));

    // Smooth non-linear coupling: residual tightness interacts with progress.
    let tightness = (bin_residual as f64 - pr) / cap; // fraction filled by item
    score -= 6.0 * tightness * tightness * (1.0 + progress);

    // Penalize post_residual close to mean_residual (creates similar unusable gaps).
    let diff = pr - mean_residual;
    score += 0.5 * (diff / cap) * (diff / cap) * cap;

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 15.0 * progress;
    }

    // Many open bins: discourage spreading; few open bins: opening new bin is cheap.
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize unless post_residual would be small or fits next item well.
        score += 12.0 + open_pressure * 3.0;
        if next_item_size > 0 {
            let next_fit = if next_item_size as f64 <= pr { 1.0 } else { 0.0 };
            score -= 10.0 * next_fit * (1.0 - pr / cap);
        }
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        let gap = pr as f64 - next_item_size as f64;
