        // stream is mid-flight and slack is not scarce.
        if next_item_size > 0 && fresh_post > 0.0 && mean_residual > 0.0
            && remaining_frac > 0.2 && remaining_frac < 0.85 {
            let dev = (fresh_post - mean_residual).abs() / cap;
            if dev < 0.08 && fragmentation < 0.5 {
                score -= 10.0 * (1.0 - dev / 0.08) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1..=10
    // effective dead zone, calibrated at <=12) are pure waste; penalize them hard.
    if post_residual <= 12 {
        score += 40.0 * (13.0 - post_residual as f64);
    } else if post_residual < 25 {
        // Small gaps unlikely to fit future items: mild penalty.
        score += 8.0;
    } else if post_residual >= 50 {
        // Large usable leftover: reward keeping flexible space.
        score -= 6.0;
    }

    // Reward tight fits (small positive post_residual that is still usable).
    if post_residual >= 13 && post_residual <= 30 {
        score -= 10.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: discourage spreading across many bins; a new empty bin
    // (post_residual = capacity - item, typically large) is naturally favored
    // when open_bins_count is low, but penalized when many bins are already open.
    if bin_residual == bin_capacity {
        score += 10.0 * (open_bins_count as f64).sqrt();
    } else {
        score -= 2.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
        if post_residual == next_item_size {
            score -= 10.0; // perfect two-item packing
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 5.0; // creates a gap the next item cannot use
    }

    // Mean-residual coupling: placing into a bin far below the mean residual
    // (i.e., the fullest bin) balances the pool and is mildly preferred.
    score += 0.3 * (mean_residual - bin_residual as f64).abs();

    // Late-stream tightening: as the stream progresses, be more tolerant of
    // opening bins (less future to plan for) -> reduce new-bin penalty late.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 8.0 * progress;
    }

    score
}

