    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let nx = next_item_size as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr_norm = pr / cap;
    let p2 = progress * progress;
    let p3 = p2 * progress;
    score += pr_norm * pr_norm * (1.0 + 3.0 * p2 + 2.0 * p3) * 10.0;

    // Reward near-perfect fits more strongly later in the stream
    let fit_quality = 1.0 - pr_norm;
    score -= fit_quality * fit_quality * (5.0 + 15.0 * progress);

    // Lookahead coupling: smooth reward when next item fits post-residual
    if nx > 0.0 && nx <= pr {
        let slack = (pr - nx) / cap;
        score -= (1.0 - slack) * (3.0 + 7.0 * progress);
    } else if nx > pr {
        // penalize wasting space the next item could have used
        score += ((nx - pr) / cap) * (4.0 + 6.0 * progress);
    }

    // Last-chance bin: smooth penalty against opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0 + 10.0 * progress;
    }

    // New-bin candidate: smooth bias based on mean residual of open bins
    if bin_residual == bin_capacity {
        let mean_norm = mean_residual / cap;
        score += 2.0 + 8.0 * mean_norm * (1.0 - progress);
    }

    // Mild congestion coupling with number of open bins
    score += (open_bins_count as f64).ln() * pr_norm * 0.5;

    score
}

