        if next_item_size > 0 && fresh_post > next_item_size as f64 && fragmentation < 0.35 && remaining_frac > 0.1 {
            let tail = fresh_post - next_item_size as f64;
            if tail > 0.0 && tail <= 5.0 {
                score -= 18.0 * (1.0 - tail / 5.0) * (0.5 + 0.5 * (1.0 - progress));
