        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: if the next item exactly matches the post_residual,
    // this placement is ideal — heavily reward it.
    if next_item_size > 0 {
        let look_gap = (post_residual as i64 - next_item_size as i64).abs();
        if look_gap == 0 {
            score -= 800.0;
        } else if look_gap <= 5 {
            score -= 150.0;
        } else if (post_residual as f64) >= next_item_size as f64 {
            // next item still fits here afterwards: mild reward
            score -= 30.0;
        } else {
            // dead space relative to next item: penalize proportionally
            score += look_gap as f64 * 0.5;
        }
    }

    // Compare against mean residual: prefer bins with residual close to or
    // below the mean (tighter bins get priority for tight fits).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin before opening a new bin: reward strongly.
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // New-bin candidate (empty bin): penalize so we only open a new bin
    // when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 250.0;
        // But if the current item is large and next item is large too,
        // a fresh bin is more attractive.
        if item_size >= 50 && next_item_size >= 50 {
            score -= 100.0;
        }
    }

    // Late in the stream, prefer closing out bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
