            let would_strand = stranded_here < next_item_size;
            if would_strand && stranded_here > 0 && stranded_here <= 8 {
                score -= 32.0 * (1.0 - progress);
            }
        }
        // MUTATION (gen 101): fresh-bin slack-supply guard — when aggregate
        // open slack is very thin relative to remaining demand, opening a
        // bin is supply, not waste; reward it to avoid late stranding.
        if remaining_frac > 0.25 {
            let open_capacity = mean_residual * open_bins_count as f64;
            let per_item_need = cap * 0.5;
            if open_capacity < per_item_need * open_bins_count.max(1) as f64 * 0.5 {
                score -= 18.0 * (1.0 - progress);
