pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let coupling = prn * prn * (1.0 - progress) + prn * progress * progress;
    score += 8.0 * coupling;

    // Reward tight fits more strongly as stream progresses
    score -= 4.0 * (1.0 - prn) * (0.5 + progress);

    // Penalize dead space relative to mean residual
    score += 0.5 * (pr - mean_residual).max(0.0) * (0.5 + 0.5 * progress);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead: reward residual that can host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 3.0 * (1.0 - ((pr - nxt) / cap));
        } else {
            score += 2.0 * (nxt - pr) / cap;
        }
    }

    // Mild penalty for proliferating open bins early
    score += open_bins_count as f64 * (1.0 - progress) * 0.3;

    // Favor new empty bin only when current fit is terrible
    if bin_residual == bin_capacity {
        score += 12.0 + 20.0 * (1.0 - prn);
        if pr >= 25.0 { score += 30.0; }
    }

    score
}

