pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: capacity fractions
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / c; // fraction of capacity left

    // Exact-fit / near-perfect classes via integer division thresholds
    if post_residual == 0 {
        score -= 1000.0; // perfect fill
    } else if post_residual <= 5 {
        score -= 400.0;
    } else if post_residual <= 10 {
        score -= 150.0;
    } else if post_residual <= 20 {
        score -= 40.0;
    }

    // Harmonic class buckets: classify residual into capacity fractions
    // (1/4, 1/2, 3/4) — reward bins whose residual stays in a "usable" class
    if frac >= 0.5 {
        score += 15.0; // half-empty bins are flexible, mild penalty keeps them for big items
    } else if frac >= 0.25 {
        score -= 10.0; // quarter-to-half residual is a sweet spot
    } else {
        score -= 25.0; // small residual classes are near-dead space, prefer filling them
    }

    // Modulo arithmetic on post_residual: harmonics of common item sizes
    let m10 = post_residual % 10;
    let m20 = post_residual % 20;
    if m10 == 0 {
        score -= 20.0; // residual is a multiple of 10: aligns with typical item granularity
    }
    if m20 == 0 {
        score -= 10.0; // stronger harmonic at 20
    }
    if m10 != 0 && m10 <= 5 {
        score += 12.0; // awkward remainder just above a harmonic
    }

    // Lookahead coupling: can next item fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0; // perfect chain
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            if slack <= 10 {
                score -= 80.0;
            } else {
                score += slack as f64 * 0.3;
            }
        } else {
            // next item cannot fit here; residual becomes dead space
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when current fit is bad
    if bin_residual == bin_capacity {
        // empty bin baseline: moderately attractive unless an open bin fits tightly
        score = 45.0 + 0.2 * (open_bins_count as f64);
        if fitting_bins_count == 0 {
            score -= 30.0; // no open bin fits: must open
        }
    }

    // Stream progression: late in the stream, tighten packing (avoid leftover space)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 10.0;

    // Mean residual coupling: if open bins are collectively loose, prefer filling loose ones
    score -= (mean_residual - pr) * 0.05;

    score
}

