            score -= 44.0 * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: items that leave residuals in
    // "small-item-friendly" classes are preferred.
    let small_class = post_residual % 20; // coarse harmonic class
    score -= (20 - small_class) as f64 * 0.35;

    // Integer-division thresholds: perfect small residuals rewarded.
    if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual <= 20 {
        score -= 12.0;
    } else if post_residual > 40 {
        score += 8.0;
    }

    // Dead space penalty: residual below the minimum item size is pure waste.
    if post_residual < 1 {
        score += 100.0;
    }

    // Lookahead coupling: does post_residual admit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
            // harmonic match: next item fits leaving tiny remainder
            let r2 = post_residual - next_item_size;
            if r2 <= 10 {
                score -= 10.0;
            }
        } else {
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: prefer it only when all open bins fit poorly.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual > 30; // item leaves >30 in fresh bin? no: fresh bin post_residual = cap - item
        if poor_fit || open_bins_count == 0 {
            score -= 40.0;
        } else if fitting_bins_count > 0 {
            // opening new bin while an existing bin fits decently: penalize
            score += 15.0;
        }
    }

    // Progress scaling: tighten packing as stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.25 * progress;

    // Mean residual pull: prefer bins whose residual deviates from mean
    // (consolidate toward fuller bins).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
