            let open_can_next = mean_residual >= next_item_size as f64;
            if !open_can_next && fitting_bins_count <= 2 {
                let chain = (fresh_post as u32) - next_item_size;
                if chain <= next_item_size {
                    score -= 24.0 * (1.0 - chain as f64 / next_item_size as f64) * (1.0 - progress);
                }
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for typical
    // future items (<= 10) are pure waste; punish them disproportionately.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // unusable sliver
        } else if post_residual < 20 {
            score += 25.0; // only fits tiny items
        } else if post_residual < 30 {
            score += 8.0; // marginal utility zone
        } else {
            score -= 10.0; // healthy residual, still reusable
        }
    } else {
        // Perfect fit: strongly reward closing the bin exactly.
        score -= 100.0;
    }

    // Reward tight fits: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio;

    // Lookahead coupling (k=2): if the next item fits into the post-residual,
    // reward; if post-residual is just barely too small for next item, penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
        } else if post_residual > 0 && next_item_size > post_residual && post_residual >= next_item_size - 8 {
            score += 10.0; // near-miss dead space
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones;
    // when few bins are open, opening a new bin is cheap.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.5 + 0.5 * progress);

    // New-bin candidate handling: make the empty bin attractive only when the
    // best existing fit would leave a bad residual. Empty bin has neutral residual.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin, modulated by how fragmented open bins are.
        score = 45.0 + open_bins_count as f64 * 0.3;
        // If mean residual across open bins is small (bins nearly full),
        // opening a new bin is reasonable.
        if mean_residual < 25.0 {
            score -= 20.0;
        }
        // If the next item is large, a fresh bin is valuable.
        if next_item_size >= 60 {
            score -= 10.0;
        }
    }

    // Slight bonus for using bins whose residual is close to item size
    // (minimizes leftover) but only when not the empty-bin candidate.
    if bin_residual != bin_capacity {
        let snugness = (bin_residual - item_size) as f64 / bin_capacity as f64;
        score -= 5.0 * (1.0 - snugness);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Layered dead-space rewards (borrowed structure: graded bonuses for
    // leaving small residuals, scaled by how close to zero they land).
    if post_residual == 0 {
        score -= 980.0;
