        }
        if remaining_frac >= 0.45 && remaining_frac < 0.5 && fresh_post > 0.45 * cap && fragmentation > 0.5 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.55;
            if open_space > est_need {
                score += 22.0 * (1.0 - remaining_frac / 0.5);
            }
        }
        // demand-aware fresh-bin refusal.
        if remaining_frac >= 0.05 && fresh_post > 0.3 * cap && next_item_size > 0 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (next_item_size as f64) * 0.42;
            if open_space > 1.15 * est_need {
                score += 30.0 * (1.0 - remaining_frac) * (fresh_post / cap - 0.3);
            }
        }
        // fresh-bin dead-space cap.
        if fresh_post > 0.35 * cap && next_item_size > 0 && (fresh_post as u32) < next_item_size && fragmentation < 0.4 && remaining_frac > 0.15 {
            score += 16.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        // tileability-aware open.
        if next_item_size > 1 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 3 && rem == 0 && fragmentation < 0.3 {
                score -= 14.0 * ((reps as f64).min(5.0) - 2.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // gen 104 (new): late-stream fresh-bin suppression — when the
        // remaining demand is small and open slack already covers it with a
        // cushion, refuse the fresh bin more firmly so tail bins do not
        // accumulate stranded dead space.
        if remaining_frac < 0.08 && fresh_post > 0.2 * cap {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (next_item_size.max(item_size) as f64) * 0.5;
            if open_space > 1.1 * est_need {
                score += 38.0 * (1.0 - remaining_frac / 0.08) * (fresh_post / cap);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post * 1.0;

    // Strongly reward tight fits (small post residual relative to capacity)
    let tightness = 1.0 - (post / cap);
    score -= tightness * tightness * 12.0;

    // Penalize dead space that is too small to be useful later
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * 2.5;
    }

    // Lookahead: reward bins whose residual can host the next item exactly or well
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let slack = post - nxt;
            score -= 6.0 * (1.0 - slack / cap);
            if (post as u32) == next_item_size {
                score -= 8.0; // perfect two-item closure
            }
        } else {
            // next item cannot fit here; slight penalty proportional to gap
            score += (nxt - post) * 0.15;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else {
        // spread load when many bins fit: prefer emptier bins
        score -= (bin_residual as f64) * 0.02;
    }

    // Global state: prefer filling bins when many are open and mean residual is low
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let crowding = (open_bins_count as f64) / (1.0 + mean_residual / 10.0);
    score -= crowding * 0.05 * (0.5 + progress);

    // Late in the stream, prioritize closing bins tightly
    if progress > 0.7 {
        score += post * 0.3 * progress;
    }

    // New-bin candidate: only attractive if item is large and no good fit exists
    if bin_residual == bin_capacity {
        score += 20.0;
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
        if item_size > bin_capacity / 2 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
