pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Smooth non-linear coupling of post_residual with stream progress:
    // early on, tolerate large residuals (keep bins flexible);
    // later, penalize residual quadratically to force tight packing.
    let progress_weight = 1.0 + 3.0 * progress * progress;
    score += progress_weight * (pr / cap) * pr * 0.02;

    // Reward near-perfect fits with a smooth saturating term.
    let fit_quality = 1.0 - pr / cap;
    score -= 15.0 * fit_quality * fit_quality * fit_quality;

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 6.0 * (1.0 - progress) * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 2.0 * progress;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: penalize mildly early, more when many bins open poorly.
    if bin_residual == bin_capacity {
        score += 5.0 + 2.0 * (mean_residual / cap);
    }

    // Dead-space penalty: residual too small for any plausible item.
    if pr > 0.0 && pr < 10.0 {
        score += 12.0 * (10.0 - pr);
    }

    score
}

