    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Base: strongly prefer tight fits (small post_residual)
    let post_f = post_residual as f64;
    score += 40.0 * (post_f / cap).powi(2);

    // Harmonic class of post_residual: residues divisible by small classes are
    // more reusable by future items. Reward post_residual in "nice" classes.
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 {
            score -= 6.0; // round residue: highly reusable
        } else if pr % 5 == 0 {
            score -= 3.0;
        } else if pr % 2 == 0 {
            score -= 1.0;
        } else {
            score += 2.0; // odd residue less reusable
        }
        // Very small dead space (< 10) is nearly unusable: penalize unless zero
        if pr < 10 && pr > 0 {
            score += 8.0;
        }
        // Mid-range residue sweet spot: 20..=50 tends to fit common item sizes
        if pr >= 20 && pr <= 50 {
            score -= 5.0;
        }
    }

    // Lookahead coupling: reward if next item fits the post_residual exactly or well
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / cap);
            if (pr % next_item_size.max(1)) == 0 {
                score -= 4.0; // harmonic divisibility: perfect future packing
            }
