            // next item cannot use this residue: mild penalty proportional to gap
            score += 3.0 * ((next_item_size - pr) as f64 / cap);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin wastes mean residual of others
    if bin_residual == bin_capacity {
        // Penalize opening a new bin when existing bins are underused,
        // unless current item is large and residuals are small.
        score += 10.0 + 2.0 * mean_residual.min(cap);
        if item_size as f64 > 0.7 * cap {
            score -= 12.0; // large items justify fresh bins
        }
        if open_bins_count == 0 {
            score -= 20.0; // must open first bin
        }
    }

    // Stream progression: late in stream, consolidate more aggressively
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 4.0 * progress * (1.0 - post_f / cap);

    // Prefer bins with residual far from mean (diversity of sizes helps packing)
    score += 0.05 * ((bin_residual as f64) - mean_residual).abs();

    score
}

