        if slack == 0.0 {
            score -= 22.0 * (1.0 - progress);
        }
    }

    // Mean-residual harmony: prefer residuals near the mean, penalize
    // wasteful outliers.
    score += 0.5 * (post_residual as f64 - mean_residual);

    // MUTATION (gen 106): gap-to-next dead-space killer — when the residual
    // is just barely too small for the next item, this placement strands a
    // nearly-usable slot; penalize proportionally to how close it came.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let gap = (next_item_size - post_residual) as f64;
        if gap <= 12.0 {
            let scarcity = 1.0 / fitting_bins_count.max(1) as f64;
            score += (14.0 + 2.2 * (12.0 - gap)) * (0.35 + 0.65 * scarcity) * (0.5 + 0.5 * (1.0 - progress));
        }
