        }
        if next_item_size > 0 && post_residual > next_item_size {
            let after_next = (post_residual - next_item_size) as f64;
            if after_next > 8.0 && after_next <= 16.0 && progress < 0.85 {
                let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
