    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling: penalize small residuals with progress-dependent weight
    let tightness = 1.0 - pr_norm;
    let coupling = tightness * tightness * (0.5 + progress);
    score += 40.0 * coupling * pr_norm;

    // Reward filling bins well, stronger later in the stream
    score -= (item_size as f64 / cap) * (1.0 + progress) * 10.0;

    // Penalize deviation from mean residual (favor balanced bins)
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev * (1.0 - pr_norm);

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let fit_gap = (pr - nxt) / cap;
            score -= 8.0 * (1.0 - fit_gap * fit_gap);
        } else {
            score += 6.0;
        }
    }

    // Slight bias against opening new bins when many are open with room
    if bin_residual == bin_capacity {
        score += 5.0 + open_bins_count as f64 * 0.5;
    }

    score
}

