        if fresh_post > 0.5 * cap && mean_residual < 0.2 * cap && remaining_frac > 0.3 && open_bins_count > 3 {
            score += 24.0 * (fresh_post / cap - 0.5) * 2.0 * (1.0 - progress);
        }
        if fitting_bins_count <= 1 && fresh_post > 0.45 * cap && next_item_size > 0 {
            let reachable = (next_item_size as f64 / fresh_post).min(1.0);
            if reachable < 0.5 {
                score += 18.0 * (0.5 - reachable) * (1.0 - progress);
            }
        }
        if next_item_size > 0 && fresh_post > 0.0 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 2 && fragmentation < 0.5 {
                score -= 7.0 * ((reps as f64).min(4.0) - 1.0) * (0.4 + 0.6 * (1.0 - progress));
                if rem <= 3 {
                    score -= 5.0 * (1.0 - progress);
                }
            }
        }
        if fresh_post > 0.35 * cap && remaining_frac > 0.2 && mean_residual * open_bins_count as f64 > 4.0 * cap && fragmentation < 0.45 {
            score += 20.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        if remaining_frac < 0.15 && fresh_post > 0.3 * cap {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.35;
            if open_space > est_need {
                score += 55.0 * (1.0 - remaining_frac / 0.15);
            }
        }
        if remaining_frac >= 0.15 && remaining_frac < 0.45 && fresh_post > 0.4 * cap && fragmentation > 0.4 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.45;
            if open_space > est_need {
                score += 28.0 * (1.0 - remaining_frac / 0.45);
            }
        }
        if next_item_size > 1 && fresh_post > 0.0 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 2 && rem == 0 && fragmentation < 0.4 {
                score -= 10.0 * ((reps as f64).min(4.0) - 1.0) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        if remaining_frac >= 0.45 && remaining_frac < 0.5 && fresh_post > 0.45 * cap && fragmentation > 0.5 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.55;
            if open_space > est_need {
                score += 22.0 * (1.0 - remaining_frac / 0.5);
            }
        }
        // gen 76: demand-aware fresh-bin refusal.
        if remaining_frac >= 0.05 && fresh_post > 0.3 * cap && next_item_size > 0 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (next_item_size as f64) * 0.42;
            if open_space > 1.15 * est_need {
                score += 30.0 * (1.0 - remaining_frac) * (fresh_post / cap - 0.3);
            }
        }
        // gen 76: fresh-bin dead-space cap.
        if fresh_post > 0.35 * cap && next_item_size > 0 && (fresh_post as u32) < next_item_size && fragmentation < 0.4 && remaining_frac > 0.15 {
            score += 16.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        // gen 81: tileability-aware open.
        if next_item_size > 1 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 3 && rem == 0 && fragmentation < 0.3 {
                score -= 14.0 * ((reps as f64).min(5.0) - 2.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // gen 106: fresh-bin homogenization — when the fresh post-residual
        // lands close to the existing fleet mean residual, the new bin
        // merges into the interchangeable slack pool instead of adding a
        // new residual class; reward that when the pool is already large.
        if fresh_post > 0.0 && mean_residual > 0.0 && open_bins_count > 3 && remaining_frac > 0.1 {
            let fresh_dev = (fresh_post - mean_residual).abs() / cap;
            if fresh_dev < 0.08 {
                score -= 18.0 * (1.0 - fresh_dev / 0.08) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of the post-residual: residues that pair with common
    // item sizes (multiples of 10) are more reusable than odd residues.
    let pr = post_residual;
    let class = match pr {
        0 => 0.0,                    // perfect fit, ideal
        r if r % 10 == 0 => 0.5,     // harmonically reusable
        r if r >= 50 => 1.0,         // large enough for most items
        r if r % 5 == 0 => 2.0,      // semi-harmonic
        _ => 4.0,                    // odd dead-space class
    };
    score += class;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // strongly reward; if next item cannot fit, mild penalty.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.05;
        }
    }

    // Tightness reward: fraction of bin consumed by this item
    let fill = item_size as f64 / cap;
    score -= fill * 40.0;

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 250.0;
    }

    // New-bin candidate (empty bin): post_residual = capacity - item_size.
    // Penalize opening a new bin unless the item is large or no bin fits well.
    if bin_residual == bin_capacity {
        let new_bin_post = post_residual;
        // A new bin is attractive only if it creates a large, harmonically
        // reusable residual and existing bins are crowded.
        if new_bin_post % 10 == 0 {
            score -= 60.0;
        }
        if item_size >= 60 {
            score -= 50.0;
        }
        score += open_bins_count as f64 * 3.0;
        score += mean_residual * 2.5;
        if fitting_bins_count > 0 {
            score += 120.0; // discourage abandoning existing fitting bins
        }
    }

    // Prefer bins whose residual deviates from mean in a useful way
    // (small residual bins should be filled first to avoid waste).
    let dev = post - mean_residual;
    score += dev * 0.2;

    // Late in the stream, be more aggressive about closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_residual - item_size) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
