        }
        if remaining_frac >= 0.45 && remaining_frac < 0.5 && fresh_post > 0.45 * cap && fragmentation > 0.5 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.55;
            if open_space > est_need {
                score += 22.0 * (1.0 - remaining_frac / 0.5);
            }
        }
        // gen 76: demand-aware fresh-bin refusal.
        if remaining_frac >= 0.05 && fresh_post > 0.3 * cap && next_item_size > 0 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (next_item_size as f64) * 0.42;
            if open_space > 1.15 * est_need {
                score += 30.0 * (1.0 - remaining_frac) * (fresh_post / cap - 0.3);
            }
        }
        // gen 76: fresh-bin dead-space cap.
        if fresh_post > 0.35 * cap && next_item_size > 0 && (fresh_post as u32) < next_item_size && fragmentation < 0.4 && remaining_frac > 0.15 {
            score += 16.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        // gen 81: tileability-aware open.
        if next_item_size > 1 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 3 && rem == 0 && fragmentation < 0.3 {
                score -= 14.0 * ((reps as f64).min(5.0) - 2.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // MUTATION (gen 107): open-bin residual-norm alignment — when the
        // fresh bin's leftover matches the fleet mean residual closely, the
        // new bin blends into the existing residual distribution instead of
        // adding variance; deepen the alignment reward slightly and extend
        // its reach so mid-range matches also benefit.
        if fresh_post > 0.0 && mean_residual > 0.0 && remaining_frac > 0.1 {
            let norm_match = (fresh_post - mean_residual).abs() / cap;
            if norm_match < 0.2 {
                score -= 12.0 * (1.0 - norm_match / 0.2) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Reward tight fits.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Open-bin pressure: discourage opening new bins when many are already open.
    if bin_residual == bin_capacity {
        score += 12.0 + 2.0 * open_bins_count as f64;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Mild preference to balance residuals toward the mean across open bins.
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // Slight tightening over the stream to reduce waste late in the run.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
