pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear polynomial coupling: tight fits are rewarded with progress-dependent strength
    let tightness = 1.0 - post / cap;
    let poly = tightness * tightness * (0.5 + 2.0 * progress) + tightness * (1.0 - progress);
    score -= 12.0 * poly;

    // Penalize dead space that is too small to hold a plausible next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            let gap = (nxt - post) / cap;
            score += 8.0 * gap * gap * (1.0 + progress);
        } else {
            // reward bins whose leftover still fits the lookahead item
            score -= 3.0 * (1.0 - post / cap);
        }
    } else {
        // last item: strongly prefer near-zero residual
        score -= 15.0 * tightness * tightness;
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 6.0 + 4.0 * progress;
    }

    // Mild penalty proportional to residual when many bins are open (encourage consolidation)
    score += 0.02 * (open_bins_count as f64) * (post / cap);

    // Mean-residual coupling: prefer bins whose post residual stays near the mean (balanced packing)
    let dev = (post - mean_residual).abs() / cap;
    score += 4.0 * dev * (1.0 - progress);

    // New-bin candidate: penalize so new bins open only when fits are truly poor
    if bin_residual == bin_capacity {
        score += 20.0 + 10.0 * progress;
    }

    score
}

