        // (too small for the next item yet too large to discard) are the
        // dominant source of residual variance; when aggregate open slack is
        // comfortable, penalize placements that strand this band.
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
            && post_residual > 8 && fitting_bins_count > 2 && progress > 0.3 {
            let open_space = mean_residual * open_bins_count as f64;
            if open_space > cap {
                let band = (post_residual as f64 - 8.0) / (next_item_size as f64 - 8.0).max(1.0);
                score += 7.0 * (1.0 - band) * (progress - 0.3);
