        if fresh_post > 0.35 * cap && next_item_size > 0 && (fresh_post as u32) < next_item_size && fragmentation < 0.4 && remaining_frac > 0.15 {
            score += 16.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        // gen 81: tileability-aware open.
        if next_item_size > 1 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 3 && rem == 0 && fragmentation < 0.3 {
                score -= 14.0 * ((reps as f64).min(5.0) - 2.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // MUTATION (gen 110): variance-aware open — when the fresh bin's
        // post-residual is small (near-closed lane) and open slack elsewhere
        // is abundant, reward the open since it consolidates waste into a
        // single bin instead of spreading mid-band residuals across lanes.
        if fresh_post > 0.0 && fresh_post <= 0.25 * cap && remaining_frac > 0.1
            && mean_residual * open_bins_count as f64 > 2.0 * cap {
            score -= 18.0 * (1.0 - fresh_post / (0.25 * cap)) * (0.4 + 0.6 * (1.0 - progress));
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit is highly desirable
    }

    // Reward tight fits proportionally.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fit_ratio;

    // Lookahead: if next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 && post_residual > 0 && next_item_size <= post_residual {
        score -= 20.0;
        if next_item_size == post_residual {
            score -= 15.0;
        }
    }
    // Penalize leaving a gap the next item cannot use.
    if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor new bin less.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score += 0.15 * pressure;

    // New empty bin candidate: baseline competitive score.
    if bin_residual == bin_capacity {
        score = 45.0 + 0.5 * open_bins_count as f64;
        // Open a new bin if all fits are poor (large dead space would result).
        if fitting_bins_count >= 1 && item_size <= 50 {
            score += 10.0; // prefer existing bins for small items
        }
        if mean_residual < item_size as f64 {
            score -= 10.0; // existing bins can't hold much, new bin good
        }
    }

    score
}

