                score += 12.0 * (1.0 - frac) * (0.5 + 0.5 * progress);
            }
        }
        // gen 81: consolidation pull (refined gen 111: begin earlier at
        // progress > 0.4 and add a mild mean-residual proximity term so
        // placements that match the fleet's typical residual are favored,
        // compressing residual spread).
        if post_residual > 0 && fitting_bins_count > 2 && progress > 0.4 {
            let fill = 1.0 - post_residual as f64 / cap;
            score -= 6.0 * fill * (progress - 0.4);
            let harmony = 1.0 - ((post_residual as f64 - mean_residual).abs() / cap).min(1.0);
            score -= 3.0 * harmony * (progress - 0.4);
        }
        // MUTATION (gen 111): variance-sink preference — when several bins
        // fit the item, prefer the one whose post-residual is closest to the
        // next item size from above (smallest non-negative slack), so
        // residuals cluster around reusable magnitudes instead of scattering.
        if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count > 2 {
            let slack = (post_residual - next_item_size) as f64;
