}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Penalize dead space that cannot fit the smallest possible item (size 1 interface).
    if post_residual == 0 {
        // Perfect fit is highly rewarded.
        score -= 25.0;
    }

    // Open-bins pressure: discourage spreading across many bins when tight fits exist.
    score += 0.35 * open_bins_count as f64;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // over opening a new bin (unless dead space is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: only attractive when open bins would waste space.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 12.0 + 1.2 * open_bins_count as f64;
        // Attractive if existing residuals are large/fragmented relative to item.
        if (mean_residual - item_size as f64) < 5.0 && fitting_bins_count > 0 {
            score -= 20.0;
        }
    }

    // Lookahead coupling: reward leaving room for the next item.
    if next_item_size > 0 {
        if post_residual as f64 >= next_item_size as f64 {
            score -= 8.0;
        } else if post_residual > 0 && (post_residual as f64) < next_item_size as f64 {
            score += 6.0;
        }
    }

    // Mean-residual coupling: prefer bins whose residual is below average (tighter bins).
    if bin_residual != bin_capacity && (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    // Mild stream-progression pressure: as stream advances, tighten packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * progress;

    score
}

