pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near match: post_residual close to next_item_size (within 5).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if diff <= 5.0 {
            score -= 25.0 * (1.0 - diff / 6.0);
        }
    }

    // Penalize unusable dead space: post_residual too small for the minimum item (1..100 range).
    // Treat residuals below 10 as dead space (items >= 10 in classic regime, but be safe).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    if post_residual == 0 {
        score -= 15.0; // perfect fill
    }

    // Last-chance bonus: only this bin can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Relative to mean residual: prefer bins tighter than average.
    score += (mean_residual - post_residual as f64) * 0.3;

    // New-bin candidate: penalize opening a new bin unless current residuals are fragmented.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 20.0;
        // If many open bins have small residuals (fragmentation), opening a new bin is fine.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if mean_residual < 25.0 && open_bins_count > 0 {
            score -= 25.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity - 20 {
            score -= 10.0; // next item is large, fresh bin helps
        }
        let _ = progress;
    }

    score
}

