        // whose leftover residual cannot hold the next item creates stranded
        // space; when aggregate open slack is already ample and the fresh
        // post-residual is small-but-unusable, refuse the open more firmly
        // late in the stream where every stranded unit is pure waste.
        if next_item_size > 0 && fresh_post > 0.0 && (fresh_post as u32) < next_item_size
            && open_capacity > 1.5 * cap && remaining_frac < 0.5 {
            score += 12.0 * (1.0 - fresh_post / next_item_size.max(1) as f64)
                * (0.4 + 0.6 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
