            score += 17.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        // Tiling-aware fresh-bin bonus.
        if next_item_size > 1 && fresh_post > 0.0 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 2 && rem == 0 && fragmentation < 0.4 {
                score -= 10.0 * ((reps as f64).min(4.0) - 1.0) * (0.4 + 0.6 * (1.0 - progress));
            }
            if reps >= 3 && rem == 0 && fragmentation < 0.3 {
                score -= 14.0 * ((reps as f64).min(5.0) - 2.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        if fresh_post > 0.35 * cap && remaining_frac > 0.2 && mean_residual * open_bins_count as f64 > 4.0 * cap && fragmentation < 0.45 {
            score += 20.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        if fitting_bins_count <= 1 && fresh_post > 0.0 && next_item_size > 0 {
            let stranded_here = bin_capacity.saturating_sub(item_size);
            let would_strand = stranded_here < next_item_size;
            if would_strand && stranded_here > 0 && stranded_here <= 8 {
                score -= 32.0 * (1.0 - progress);
            }
        }
        // Residual-harmony fresh-bin bonus.
        if fresh_post > 0.0 && fresh_match < 0.2 && fragmentation < 0.5 && remaining_frac > 0.1 {
            score -= 14.0 * (1.0 - fresh_match / 0.2) * (0.5 + 0.5 * (1.0 - progress));
        }
        // MUTATION (gen 113): near-tiling fresh-bin bonus — when the fresh
        // bin's leftover is a near-exact multiple of the next item (rem <= 2),
        // opening creates an almost perfectly tileable lane.
        if next_item_size > 1 && fresh_post > 0.0 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 2 && rem > 0 && rem <= 2 && fragmentation < 0.35 {
                score -= 6.0 * ((reps as f64).min(4.0) - 1.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, non-linearly
    let mut score = (norm_pr.powi(2) * (1.0 + 2.0 * progress)) * cap;

    // Polynomial coupling: dead-space penalty grows non-linearly with progress
    let waste = (norm_pr * (1.0 - norm_pr)).powi(2);
    score -= waste * cap * (0.5 + 1.5 * progress * (1.0 - progress) * 4.0);

    // Last-chance bonus: strong, smooth
    if fitting_bins_count == 1 {
        score -= cap * (1.0 + progress);
    }

    // Lookahead: reward bins whose post-residual can fit next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64 / cap) * (10.0 + 20.0 * progress);
    } else if next_item_size > 0 {
        score += (next_item_size as f64 / cap) * 5.0 * (1.0 - progress);
    }

    // Mild preference for fuller bins among many open bins
    score += (open_bins_count as f64).ln().max(0.0) * (1.0 - norm_pr) * 2.0;

    // Discourage spreading when mean residual is high
    score += (mean_residual / cap - norm_pr).abs() * 8.0;

    score
}

