        if remaining_frac < 0.15 && fresh_post > 0.3 * cap {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.35;
            if open_space > est_need {
                score += 55.0 * (1.0 - remaining_frac / 0.15);
            }
        }
        // Mid-stream refusal band.
        if remaining_frac >= 0.15 && remaining_frac < 0.45 && fresh_post > 0.4 * cap && fragmentation > 0.4 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.45;
            if open_space > est_need {
                score += 28.0 * (1.0 - remaining_frac / 0.45);
            }
        }
        // Demand-aware fresh-bin refusal using next-item footprint.
        if remaining_frac >= 0.05 && fresh_post > 0.3 * cap && next_item_size > 0 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (next_item_size as f64) * 0.42;
            if open_space > 1.15 * est_need {
                score += 32.0 * (1.0 - remaining_frac) * (fresh_post / cap - 0.3);
            }
        }
        // Fresh-bin dead-space cap.
        if fresh_post > 0.35 * cap && next_item_size > 0 && (fresh_post as u32) < next_item_size && fragmentation < 0.4 && remaining_frac > 0.15 {
            score += 17.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        // Tiling-aware fresh-bin bonus.
        if next_item_size > 1 && fresh_post > 0.0 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 2 && rem == 0 && fragmentation < 0.4 {
                score -= 10.0 * ((reps as f64).min(4.0) - 1.0) * (0.4 + 0.6 * (1.0 - progress));
            }
            if reps >= 3 && rem == 0 && fragmentation < 0.3 {
                score -= 14.0 * ((reps as f64).min(5.0) - 2.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // Fresh-bin residual-magnitude guard.
        if fresh_post > 0.35 * cap && remaining_frac > 0.2 && mean_residual * open_bins_count as f64 > 4.0 * cap && fragmentation < 0.45 {
            score += 20.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        // Single-fit fresh-bin rescue.
        if fitting_bins_count <= 1 && fresh_post > 0.0 && next_item_size > 0 {
            let stranded_here = bin_capacity.saturating_sub(item_size);
            let would_strand = stranded_here < next_item_size;
            if would_strand && stranded_here > 0 && stranded_here <= 8 {
                score -= 32.0 * (1.0 - progress);
            }
        }
        // MUTATION (gen 113): residual-harmony fresh-bin bonus.
        if fresh_post > 0.0 && fresh_match < 0.2 && fragmentation < 0.5 && remaining_frac > 0.1 {
            score -= 14.0 * (1.0 - fresh_match / 0.2) * (0.5 + 0.5 * (1.0 - progress));
        }
        // MUTATION (gen 113): near-exact fresh-bin chain — fresh bin whose
        // leftover after the next item is tiny acts as a two-step closer.
        if next_item_size > 0 && fresh_post > next_item_size as f64 {
            let after_next = fresh_post - next_item_size as f64;
            if after_next > 0.0 && after_next <= 8.0 && fragmentation < 0.5 {
                score -= 20.0 * (1.0 - after_next / 8.0) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "reusable" is the leftover space?
    // Residuals that are multiples of common item sizes (or near them) are valuable.
    let pr = post_residual;
    let class_mod = pr % 10; // coarse harmonic class on decimal grid
    score += class_mod as f64 * 0.35; // penalize off-grid leftovers

    // Integer-division thresholds: big leftover vs tiny leftover
    if pr >= bin_capacity / 2 {
        score -= 12.0; // half-full+ leftover: very reusable
    } else if pr >= bin_capacity / 4 {
        score -= 5.0;
    } else if pr <= 5 {
        score += 2.0; // dead space penalty
    }

    // Coupling with lookahead item: perfect fit for next item is gold
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            let waste = pr - next_item_size;
            // harmonic: waste mod 10 low means next item leaves clean residual
            score -= 18.0 - (waste as f64) * 0.5 + ((waste % 10) as f64) * 0.4;
        } else {
            score += 6.0; // next item cannot use this bin's leftover
        }
    } else {
        // last item: just minimize leftover
        score += 0.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize mildly so it's chosen only when open bins fit badly,
    // but attractively when stream is early and mean residual is already fragmented.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score = cap_f * 0.5 + mean_residual * 0.3 - progress * 10.0;
        if fitting_bins_count == 0 {
            score -= 30.0; // nothing fits: new bin is mandatory anyway
        }
    }

    // Fragmentation awareness: prefer bins far from mean residual (best-fit diversification)
    score += ((bin_residual as f64 - mean_residual).abs()) * -0.15;

    // Slight preference for tighter bins overall
    score += (bin_residual as f64 / cap_f) * 3.0;

    score
}

