            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.55;
            if open_space > est_need {
                score += 22.0 * (1.0 - remaining_frac / 0.5);
            }
        }
        // gen 76: demand-aware fresh-bin refusal.
        if remaining_frac >= 0.05 && fresh_post > 0.3 * cap && next_item_size > 0 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (next_item_size as f64) * 0.42;
            if open_space > 1.15 * est_need {
                score += 30.0 * (1.0 - remaining_frac) * (fresh_post / cap - 0.3);
            }
        }
        // gen 76: fresh-bin dead-space cap.
        if fresh_post > 0.35 * cap && next_item_size > 0 && (fresh_post as u32) < next_item_size && fragmentation < 0.4 && remaining_frac > 0.15 {
            score += 16.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        // gen 81: tileability-aware open.
        if next_item_size > 1 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 3 && rem == 0 && fragmentation < 0.3 {
                score -= 14.0 * ((reps as f64).min(5.0) - 2.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // MUTATION (gen 113): fresh-bin mean-residual alignment — opening a bin
        // whose post-residual matches the existing mean open residual keeps
        // the slack pool homogeneous and directly targets the diagnosed
        // residual-variance weakness.
        if fresh_post > 0.0 && fresh_match < 0.04 && fragmentation > 0.2 && remaining_frac > 0.1 {
            score -= 18.0 * (1.0 - fresh_match / 0.04) * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    // A residual gap is "dead" if it is too small for the smallest plausible item (1..100).
    if post_residual > 0 {
        // Penalize gaps that cannot fit the next item (lookahead-aware dead space).
        if next_item_size > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 2.0;
        }
        // Penalize very small absolute gaps (likely unusable for any future item).
        if post_residual < 10 {
            score += 25.0;
        } else if post_residual < 20 {
            score += 12.0;
        }
    } else {
        // Perfect fill: strong reward.
        score -= 50.0;
    }

    // Reward near-exact fits relative to capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 20.0;

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // by penalizing the empty-bin candidate; when few bins are open, new bins are cheaper.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 * 3.0;
        score += pressure + 10.0;
        // Late in the stream, opening a new bin is less costly (fewer future items to fill it).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 15.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Slight preference for bins below mean residual (keeps residuals balanced).
    score -= (mean_residual - bin_residual as f64) * 0.3;

    score
}

