        if next_item_size > 1 && fresh_post > 0.0 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 2 && rem == 0 && fragmentation < 0.4 {
                score -= 10.0 * ((reps as f64).min(4.0) - 1.0) * (0.4 + 0.6 * (1.0 - progress));
            }
            if reps >= 3 && rem == 0 && fragmentation < 0.3 {
                score -= 14.0 * ((reps as f64).min(5.0) - 2.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // Fresh-bin residual-magnitude guard.
        if fresh_post > 0.35 * cap && remaining_frac > 0.2 && mean_residual * open_bins_count as f64 > 4.0 * cap && fragmentation < 0.45 {
            score += 20.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        // Single-fit fresh-bin rescue — discourage opening when the fresh
        // bin's leftover would strand the next item.
        if fitting_bins_count <= 1 && fresh_post > 0.0 && next_item_size > 0 {
            let stranded_here = bin_capacity.saturating_sub(item_size);
            let would_strand = stranded_here < next_item_size;
            if would_strand && stranded_here > 0 && stranded_here <= 8 {
                score -= 32.0 * (1.0 - progress);
            }
        }
        // MUTATION (gen 114): residual-harmony fresh-bin bonus — when the
        // fresh bin's leftover closely matches the mean residual, opening
        // harmonizes the residual distribution and reduces variance.
        if fresh_post > 0.0 && fresh_match < 0.2 && fragmentation < 0.5 && remaining_frac > 0.1 {
            score -= 14.0 * (1.0 - fresh_match / 0.2) * (0.5 + 0.5 * (1.0 - progress));
        }
        // MUTATION (gen 114): three-step tiling lane — opening is favored
        // when the fresh leftover tiles into two further next-item slots,
        // creating a dedicated compaction lane.
        if next_item_size > 1 && fresh_post > 0.0 {
            let fp = fresh_post as u32;
            if fp >= 2 * next_item_size && fp % next_item_size <= 2 && fragmentation < 0.45 {
                score -= 8.0 * (1.0 - progress);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward if next item exactly fills post_residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        if gap == 0.0 {
            // Perfect chain: next item seals this bin completely.
            score -= 60.0;
        } else {
            // Partial chain: reward proportionally to how well next item fits.
            score -= 40.0 * (1.0 - gap / (post_residual as f64));
        }
    } else if next_item_size > post_residual {
        // Next item cannot use leftover space; penalize dead space creation.
        score += 15.0;
    }

    // Reward bins whose residual is near the stream mean (typical-fit bins),
    // penalize outliers that hoard space.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Early in the stream, favor consolidating into few bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.05 * open_bins_count as f64;

    // New-bin candidate: make empty bin attractive only when it would accept
    // the next item too, otherwise discourage opening a new bin.
    if bin_residual == bin_capacity {
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 10.0 + next_item_size as f64 * 0.1;
        }
        score += 8.0;
    }

    score
}

