        // how many bins are competing, since residual variance peaks in
        // the mid-stream when many half-full bins compete for items.
        if post_residual > 0 && fitting_bins_count > 2 && progress > 0.35 {
            let fill = 1.0 - post_residual as f64 / cap;
            let scarcity = 1.0 / (fitting_bins_count as f64);
            score -= 3.0 * fill * (progress - 0.35) * (1.0 + scarcity);
        }
        // MUTATION (gen 114): two-step tileability gradient — when placing
        // here leaves a residual that exactly tiles the next item with
        // repetition, the leftover will be fully consumed by the lookahead
        // chain; deepen the reward proportionally to the repetition count
        // so long tileable lanes beat scattered slack.
        if post_residual > 0 && next_item_size > 1 && post_residual >= next_item_size && progress > 0.3 {
            let reps = post_residual / next_item_size;
            let rem = post_residual % next_item_size;
            if reps >= 2 && rem == 0 {
                let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
                score -= (4.0 + 5.0 * scarcity) * ((reps as f64).min(4.0) - 1.0) * (progress - 0.3);
            }
        }
        // MUTATION (gen 114): residual-band alignment — penalize placements
        // whose post-residual sits in the "orphan band" (unusable by the
        // next item and far from any multiple of it) when aggregate open
        // slack can already absorb the next item; this directly targets
        // the diagnosed dead-space ratio weakness.
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
            && fitting_bins_count > 2 && mean_residual > 0.0 {
            let orphan_gap = (next_item_size - post_residual) as f64;
            if orphan_gap > 12.0 {
