            }
        }
        // gen 76: fresh-bin dead-space cap.
        if fresh_post > 0.35 * cap && next_item_size > 0 && (fresh_post as u32) < next_item_size && fragmentation < 0.4 && remaining_frac > 0.15 {
            score += 16.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        // MUTATION (gen 81): tileability-aware open — when the fresh bin's
        // post-residual is an exact multiple of the next item size with
        // three or more repetitions, opening creates a perfectly tileable
        // bin; deepen the reward when fragmentation is low so the new bin
        // acts as a dedicated tiling lane instead of scattering slack.
        if next_item_size > 1 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 3 && rem == 0 && fragmentation < 0.3 {
                score -= 14.0 * ((reps as f64).min(5.0) - 2.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // MUTATION (gen 114): fresh-bin orphan guard — when the fresh bin's
        // post-residual falls in the orphan band (smaller than the next
        // item but only slightly, i.e. nearly usable), the stranded space
        // is small enough to matter; soften the dead-space cap so
        // near-usable opens are not over-penalized, sharpening the
        // residual-variance reduction direction.
        if fresh_post > 0.35 * cap && next_item_size > 0 && (fresh_post as u32) < next_item_size
            && fragmentation < 0.4 && remaining_frac > 0.15 {
            let near_miss = (next_item_size as f64 - fresh_post) / cap;
            if near_miss > 0.1 {
                score += 16.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
            } else {
                score += 7.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Layered dead-space rewards (lower post_residual = better).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 4 {
        score -= 260.0 + 4.4 * (4 - post_residual) as f64;
    } else if post_residual <= 10 {
        score -= 70.0 + 3.8 * (10 - post_residual) as f64;
    } else if post_residual <= 22 {
        score -= 14.0 + 1.6 * (22 - post_residual) as f64;
    } else if post_residual <= 32 {
        score -= 5.0 + 0.75 * (32 - post_residual) as f64;
    } else if post_residual <= 48 {
        score -= 1.2 + 0.24 * (48 - post_residual) as f64;
    } else {
        score -= 1.2 - 0.015 * (post_residual as f64 - 48.0);
    }

    // Progress-scaled weighting: tighten late in the stream.
    let w = 0.33 + 0.67 * progress * progress;
    score *= w;

    // Lookahead coupling with the next item.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 920.0;
        } else if next_item_size < post_residual {
            let two_step_waste = (post_residual - next_item_size) as f64;
            if two_step_waste <= 8.0 {
                score -= 140.0 - 2.3 * two_step_waste;
            } else {
                score -= 74.0 - 0.6 * two_step_waste;
            }
            if two_step_waste <= 3.0 {
                score -= 50.0;
            }
        } else {
            let miss = (next_item_size - post_residual) as f64;
            score += 0.95 * miss;
            if miss > 26.0 {
                score += 0.55 * (miss - 26.0);
            }
        }
        // Two-step exact-fill of the whole bin.
        let two_step = item_size + next_item_size;
        if two_step == bin_capacity {
            score -= 800.0;
        } else if two_step <= bin_capacity && bin_capacity - two_step <= 10 {
            score -= 200.0;
        }
    }

    // Slack-based scarcity boost when the next item fits here.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
        let boost = 38.0 + 28.0 * scarcity;
        score -= boost * (1.0 - slack / cap) * (0.6 + 0.4 * (1.0 - progress));
        if fitting_bins_count <= 2 {
            score -= 16.0 * (1.0 - slack / cap);
        }
        if slack == 0.0 {
            score -= 22.0 * (1.0 - progress);
        }
    }

    // Mean-residual harmony: prefer residuals near the mean, penalize
    // wasteful outliers.
    score += 0.5 * (post_residual as f64 - mean_residual);

    // MUTATION (gen 105): three-step chain compaction — reward placements
    // whose residual tiles into the next item, so the leftover after the
    // next placement is minimal.
    if post_residual > 0 && next_item_size > 1 && post_residual > next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next % next_item_size == 0 && after_next >= next_item_size {
            score -= 9.0 * (1.0 - progress) * (1.0 / fitting_bins_count.max(1) as f64).sqrt();
        }
    }

    // MUTATION (gen 105): dead-space convergence — penalize placements that
    // leave a residual in the "orphan band".
    if post_residual > 8 && post_residual < 20 && next_item_size > post_residual {
        let open_space = mean_residual * open_bins_count as f64;
        if open_space > cap {
            score += 8.0 * (1.0 - (post_residual as f64 - 8.0) / 12.0) * (0.4 + 0.6 * (1.0 - progress));
        }
    }

    // MUTATION (gen 105): exact-fit scarcity sharpening.
    if next_item_size > 0 && post_residual == next_item_size && fitting_bins_count <= 4 {
        score -= 26.0 / fitting_bins_count.max(1) as f64 * (0.5 + 0.5 * (1.0 - progress));
    }

    // Tiling/divisibility consolidation — residuals that are exact multiples
    // of the next item size tile to zero waste.
    if post_residual > 0 && next_item_size > 1 && next_item_size <= post_residual {
        let reps = post_residual / next_item_size;
        let rem = post_residual % next_item_size;
        if reps >= 1 && rem == 0 {
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
