        // leftover cannot host the next item but open slack can, penalize
        // opening so the next item goes into existing slack instead.
        if next_item_size > 0 && fresh_post > 0.0 && (fresh_post as u32) < next_item_size {
            let slack_total = mean_residual * open_bins_count as f64;
            if slack_total > 2.0 * cap {
                score += 26.0 * (1.0 - progress);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" is the leftover space?
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // capacity fraction remaining

    // Class bins by integer division of post_residual into capacity deciles.
    let decile = (post_residual * 10) / bin_capacity; // 0..=10
    match decile {
        0 => score -= 60.0,           // near-perfect fill: excellent
        1 => score -= 35.0,
        2 => score -= 18.0,
        3 => score -= 8.0,
        4 => score += 0.0,
        5 => score += 6.0,
        6 => score += 14.0,
        7 => score += 24.0,
        8 => score += 36.0,
        9 => score += 50.0,
        _ => score += 70.0,           // almost empty bin used wastefully
    }

    // Modulo-10 class: residuals divisible by 10 pair better with typical sizes.
    let m10 = post_residual % 10;
    if m10 == 0 {
        score -= 10.0;
    } else if m10 >= 7 {
        score += 4.0 + m10 as f64;
    } else {
        score += m10 as f64;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 - slack * 0.15;
        } else {
            // next item cannot use this residual; penalize large unusable leftovers
            score += (next_item_size - post_residual).min(30) as f64 * 0.4;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin gets a mild penalty so we prefer
    // real fits, unless existing residuals are all poor.
    if bin_residual == bin_capacity {
        score += 25.0 - 12.0 * (mean_residual / cap);
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open new bin
        }
    }

    // Progress pressure: late in the stream, consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (frac * 20.0);

    // Reward tight fits relative to item size.
    score -= (item_size as f64 / cap) * 8.0;

    // Slight preference to fill bins when many are open.
    score += open_bins_count as f64 * 0.3;

    score
}

