        if next_item_size > 0 && fresh_post > 0.0 && (fresh_post as u32) < next_item_size {
            let slack_total = mean_residual * open_bins_count as f64;
            if slack_total > 2.0 * cap {
                score += 26.0 * (1.0 - progress);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Base: waste after placement, non-linearly scaled
    let mut score = pr * (1.0 + 0.9 * pr / cap);

    // Smooth polynomial coupling with stream progress: waste matters more later
    let w = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += w * pr * (pr / cap) * 2.5;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0 + 40.0 * w;
    }

    // Tight fit reward (small post residual relative to item)
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * tightness * tightness;

    // Lookahead: reward if next item fits into post_residual, penalize if it leaves a gap just below next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            score -= 12.0 + 8.0 * w;
        } else if pr > 0.0 {
            let gap_ratio = nxt / pr;
            score += 10.0 * (1.0 - gap_ratio).max(0.0) * (pr / cap);
        }
    }

    // Penalize new-bin candidate (empty bin) unless current bin would leave large dead space
    if bin_residual == bin_capacity {
        score += 25.0 + 30.0 * (1.0 - w);
        if next_item_size > 0 && (bin_capacity as f64 - item_size as f64) >= next_item_size as f64 {
            score -= 10.0;
        }
    }

    // Last-chance bonus: only one fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 20.0 * w;
    }

    // Mild preference to balance load across bins: avoid bins far below mean residual
    score += 0.15 * (mean_residual - pr).abs() * (1.0 - w);

    // Slight penalty for many open bins to encourage consolidation early
    score += 0.5 * (open_bins_count as f64).sqrt() * (1.0 - w) * (pr / cap);

    score
}

