pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are excellent: reward small post_residual non-linearly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual <= 20 {
        score -= 8.0;
    }

    // Dead space penalty: residuals that likely can't fit typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly in the post residual, bonus.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if nxt == post {
            score -= 35.0;
        } else if nxt <= post {
            score -= 10.0 * (nxt / post);
        } else {
            // next item won't fit here; mildly penalize large leftover
            score += 5.0 * ((post - nxt) / bin_capacity as f64).abs();
        }
    }

    // New-bin candidate handling: keep it attractive when open bins are crowded,
    // discourage it when open bins have plenty of room.
    if bin_residual == bin_capacity {
        let crowding = mean_residual / bin_capacity as f64;
        score -= 20.0 * crowding;
        score -= 3.0 * open_bins_count as f64;
        // Late in the stream, prefer consolidating into open bins.
        let t = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * t;
    } else {
        // Prefer bins whose residual is close to the item (best-fit flavor).
        let waste_ratio = post_residual as f64 / bin_residual.max(1) as f64;
        score += 15.0 * waste_ratio;
        // Prefer bins tighter than the mean residual (larger items into emptier bins).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    // Mild preference to fill bins that are already substantially used.
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 10.0 * fill * fill;

    // Global balance: many open bins -> push toward packing existing bins harder.
    score += 1.5 * open_bins_count as f64;

    score
}

