        if remaining_frac >= 0.05 && fresh_post > 0.3 * cap && next_item_size > 0 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (next_item_size as f64) * 0.42;
            if open_space > 1.15 * est_need {
                score += 30.0 * (1.0 - remaining_frac) * (fresh_post / cap - 0.3);
            }
        }
        // gen 76: fresh-bin dead-space cap.
        if fresh_post > 0.35 * cap && next_item_size > 0 && (fresh_post as u32) < next_item_size && fragmentation < 0.4 && remaining_frac > 0.15 {
            score += 16.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        // gen 81: tileability-aware open — when the fresh bin's post-residual
        // is an exact multiple of the next item size with three or more
        // repetitions, opening creates a perfectly tileable bin; deepen the
        // reward when fragmentation is low so the new bin acts as a dedicated
        // tiling lane instead of scattering slack. (gen 118: also reward
        // two-rep exact tiling when the open slack is thin, since those bins
        // close with just one more item.)
        if next_item_size > 1 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 3 && rem == 0 && fragmentation < 0.3 {
                score -= 14.0 * ((reps as f64).min(5.0) - 2.0) * (0.5 + 0.5 * (1.0 - progress));
            } else if reps == 2 && rem == 0 && fragmentation > 0.4 {
                score -= 8.0 * (0.5 + 0.5 * (1.0 - progress));
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues modulo 10 / 20 create
    // "classes" of leftover space; small dead space classes are penalized.
    let pr = post_residual;
    let class20 = pr % 20;
    if pr > 0 {
        // Penalize awkward dead-space classes (unfillable by typical items 1..100)
        if class20 == 1 || class20 == 2 {
            score += 6.0;
        } else if class20 <= 5 {
            score += 3.0;
        } else if class20 >= 17 {
            score += 2.5;
        }
        // Reward residual classes that pair well with common item sizes
        if pr % 10 == 0 {
            score -= 2.0;
        }
        if pr % 25 == 0 {
            score -= 1.5;
        }
    } else {
        // Perfect fill: strongly favored
        score -= 30.0;
    }

    // Lookahead coupling: does next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 8.0;
            // Extra reward for tight lookahead fit (harmonic residue match)
            let gap = pr - next_item_size;
            if gap % 10 == 0 {
                score -= 3.0;
            }
            if gap <= 5 {
                score -= 2.0;
            }
        } else {
            // Next item won't fit here; slight penalty proportional to overflow class
            let over = (next_item_size - pr) % 30;
            score += (over as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; cheaper late in the stream
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 40.0 - 10.0 * progress;
        // If many bins already fit the item, opening new is wasteful
        if fitting_bins_count > 2 {
            score += 10.0;
        }
        // If only this bin fits (last chance), opening new is acceptable
        if fitting_bins_count == 1 {
            score -= 8.0;
        }
        // If current item leaves a good harmonic residual in a fresh bin
        let fresh_post = bin_capacity - item_size;
        if fresh_post % 10 == 0 {
            score -= 2.0;
        }
        // Lookahead: if next item is large, a fresh bin may be wise
        if next_item_size > 0 && next_item_size > bin_capacity - item_size {
            score -= 4.0;
        }
    }

    // Mild preference for bins tighter than average (waste-minimizing)
    let tightness = (bin_residual as f64 - mean_residual).max(0.0);
    score += tightness * 0.05;

    // Small diversity term using open bin count to avoid over-concentration
    if open_bins_count > 0 && bin_residual < bin_capacity {
        let frac = (post_residual as f64) / (bin_capacity as f64);
        if frac < 0.05 && post_residual > 0 {
            score += 4.0; // nearly-dead bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
