                score += 30.0 * (1.0 - remaining_frac) * (fresh_post / cap - 0.3);
            }
        }
        // gen 76: fresh-bin dead-space cap.
        if fresh_post > 0.35 * cap && next_item_size > 0 && (fresh_post as u32) < next_item_size && fragmentation < 0.4 && remaining_frac > 0.15 {
            score += 16.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        // gen 81: tileability-aware open.
        if next_item_size > 1 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 3 && rem == 0 && fragmentation < 0.3 {
                score -= 14.0 * ((reps as f64).min(5.0) - 2.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // MUTATION (gen 118): late-stream fresh-bin suppression — when the
        // stream is nearly done and open slack already covers the remaining
        // demand, opening a fresh bin is pure waste; penalize hard so the
        // tail packs into existing bins.
        if remaining_frac < 0.08 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.5;
            if open_space > est_need {
                score += 70.0 * (1.0 - remaining_frac / 0.08);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for typical items are heavily penalized.
    // Items are 1..100, but small gaps (< ~20) are rarely reusable; super-linear penalty.
    let pr = post_residual as f64;
    if post_residual > 0 {
        if post_residual < 10 {
            score += 40.0 + (10.0 - pr) * 4.0; // near-dead space
        } else if post_residual < 25 {
            score += 12.0 + (25.0 - pr) * 0.8; // awkward gap
        }
    } else {
        score -= 25.0; // perfect fill
    }

    // Reward tight fits: fraction of bin consumed by this item.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fit_ratio;

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open.
    if bin_residual == bin_capacity {
        // Candidate for a brand-new bin: only attractive if the stream is early
        // or open-bin count is small; penalize otherwise.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 35.0 + 45.0 * progress + 2.0 * open_bins_count as f64;
        // If the next item could use the leftover of this bin's would-be residual... n/a (empty).
        // Slight relief if mean residual across open bins is tiny (open bins nearly full).
        score -= mean_residual.clamp(0.0, 100.0) * 0.3;
    } else if next_item_size > 0 {
        // Lookahead coupling: if the next item fits exactly into post_residual, reward heavily.
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // next item won't fit here; penalize leaving a gap that next item overshoots
            score += 6.0;
        }
    }

    // Mild preference for bins with below-average residual (concentrate filling).
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
