        // gen 76: usable-residual scarcity bonus.
        if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count == 1 && bin_residual != bin_capacity {
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score -= 14.0 * (1.0 - progress) * (0.6 + 0.4 * tightness);
        }
        // gen 81: dead-space compaction gradient.
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
            && fitting_bins_count > 1 {
            let open_space = mean_residual * open_bins_count as f64;
            if open_space > 2.0 * cap {
                let frac = post_residual as f64 / next_item_size as f64;
                score += 10.0 * (1.0 - frac) * (0.5 + 0.5 * progress);
            }
        }
        // gen 81: consolidation pull.
        if post_residual > 0 && fitting_bins_count > 2 && progress > 0.5 {
            let fill = 1.0 - post_residual as f64 / cap;
            score -= 5.0 * fill * (progress - 0.5);
        }
        // MUTATION (gen 119): residual-variance damping — when this bin's
        // post-residual is far below the mean open residual late in the
        // stream, its leftover space is hard to combine with other bins;
        // penalize the outlier gap so residuals converge toward a common
        // tileable size and dead-space ratio drops.
        if post_residual > 0 && fitting_bins_count > 2 && progress > 0.4 {
            let gap_down = mean_residual - post_residual as f64;
            if gap_down > 0.12 * cap {
                score += 7.5 * ((gap_down - 0.12 * cap) / cap).min(0.3) * (progress - 0.4);
            }
        }
        // MUTATION (gen 119): two-step exact-close reward — when placing
        // here leaves a residual that the NEXT item nearly fills (within a
        // small tail), this bin becomes effectively full in two steps;
        // deepen the existing chain reward for tails under 3.
