            && (mean_residual as u32) >= next_item_size && fitting_bins_count > 1 && remaining_frac > 0.1 {
            score += 14.0 * (fresh_post / cap - 0.3) * (1.0 - progress);
        }
        // gen 102: fresh-bin mid-gap refusal.
        if next_item_size > 0 && fresh_post > 12.0 && fresh_post <= 24.0 && fitting_bins_count > 1 {
            let mid = (fresh_post - 12.0) / 12.0;
            score += 7.0 * mid * (0.35 + 0.65 * progress);
        }
        // gen 102: fresh-bin residual-harmony bonus.
        if fresh_post > 0.0 && fresh_match < 0.08 && remaining_frac > 0.1 {
            score -= 10.0 * (1.0 - fresh_match / 0.08) * (0.4 + 0.6 * (1.0 - progress));
        }
        // MUTATION (gen 110): fresh-bin late exact-closure amplifier.
        if progress > 0.75 && next_item_size > 0 && (fresh_post as u32) >= next_item_size {
            let tail = (fresh_post as u32 - next_item_size) as f64;
            if tail <= 2.0 {
                score -= 20.0 * (1.0 - tail / 2.0) * (progress - 0.75) / 0.25;
            }
        }
        // MUTATION (gen 110): demand-scaled open throttle.
        if remaining_frac < 0.3 && fresh_post > 0.25 * cap {
            let est_need = (remaining as f64) * (item_size as f64) * 0.5;
            if open_capacity > 1.3 * est_need {
                score += 24.0 * (open_capacity / (1.3 * est_need)).min(2.0) * (1.0 - remaining_frac / 0.3);
            }
        }
        // MUTATION (gen 120): two-item fresh-bin pair check — when the fresh
        // post-residual exactly equals the next item size, the new bin will
        // close perfectly on the following step; this is a guaranteed bin
        // saving and deserves a strong reward even at moderate
        // fragmentation, since it converts one open slot into zero waste.
        if next_item_size > 0 && (fresh_post as u32) == next_item_size && fragmentation <= 0.45 {
            score -= 30.0 * (0.4 + 0.6 * (1.0 - progress));
        }
        // MUTATION (gen 120): pairable-lane bonus — when the fresh residual
        // can absorb the next item with a tiny tail (<= 2), the bin behaves
        // like a compaction lane; reward it when aggregate open slack is
        // still thin so we seed lanes before slack accumulates.
        if next_item_size > 0 && (fresh_post as u32) >= next_item_size {
            let tail = (fresh_post as u32 - next_item_size) as f64;
            if tail > 0.0 && tail <= 2.0 && open_capacity < 2.5 * cap {
                score -= 12.0 * (1.0 - tail / 2.0) * (0.4 + 0.6 * progress);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: quantize post_residual into capacity-fraction buckets.
    let q = (bin_capacity as f64) / 4.0; // quarter classes
    let class = (post_residual as f64 / q).floor() as f64;
    score += class * 7.0; // prefer bins leaving residuals in lower harmonic classes

    // Modulo arithmetic on post_residual: residuals that are multiples of common
    // small item sizes are more reusable; penalize "odd" dead space.
    let pr = post_residual;
    if pr > 0 {
        let mut reuse = 0.0;
        for m in [5u32, 10, 20, 25, 50].iter() {
            if pr % m == 0 {
                reuse += 3.0;
            }
        }
        score -= reuse;
    } else {
        // Perfect fit is ideal.
        score -= 60.0;
    }

    // Dead-space penalty: residuals too small for the minimum item size (1..100
    // interface, but conservative floor) are waste.
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // strongly reward this bin (chained harmonic match).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            score -= (pr - next_item_size) as f64 * 0.3;
        } else {
            // Next item won't fit here; slight penalty scaled by overflow.
            score += (next_item_size - pr) as f64 * 0.1;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin is a fresh harmonic slate.
    if bin_residual == bin_capacity {
        // Prefer new bin only when stream is early or open bins are fragmented.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / bin_capacity as f64;
        score += 15.0 * (1.0 - progress) + 20.0 * fragmentation;
        // Penalize new bin heavily if existing bins fit poorly (large post_residual elsewhere).
        if post_residual == bin_capacity {
            score += 5.0;
        }
    }

    // Mild global pressure: many open bins -> prefer consolidating into existing ones.
    score += open_bins_count as f64 * 0.05;

    // Mean residual alignment: bins close to the mean residual are "typical";
    // prefer atypical (small residual) bins to be closed out first.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= dev * 0.05;

    // Integer-division threshold: bins whose residual / item quotient is >= 3
    // can host several future items of this size; reward.
    if item_size > 0 {
        let quot = pr / item_size;
        if quot >= 3 {
            score -= 8.0;
        } else if quot == 2 {
            score -= 4.0;
        }
    }

    // Small progress term to break ties deterministically across the stream.
    score += (step_index % 7) as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    if post_residual == 0 {
        score -= 980.0;
