        if next_item_size > 0 && post_residual == next_item_size && fitting_bins_count > 0 {
            let scarcity = 1.0 / (fitting_bins_count as f64);
            score -= 8.0 * (1.0 + scarcity) * (0.3 + 0.7 * progress);
