}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps below the minimum item size (10) are pure waste.
    if post_residual < 10 {
        score -= 60.0; // perfect closure reward
    } else if post_residual < 20 {
        // small residual: likely dead space unless a tiny item arrives
        score += 25.0;
    } else if post_residual < 35 {
        score += 8.0;
    }

    // Reward tight fits: small post_residual relative to item size.
    score -= 0.5 * item_size as f64;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += 1.5 * open_bins_count as f64;

    // Lookahead: if the next item fits into the post residual, reward it.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 5.0;
    }

    // New-bin candidate: keep it attractive only when open bins have poor fits.
    if bin_residual == bin_capacity {
        // penalize opening new bins mildly; dead-space penalties above can override
        score += 30.0 + 2.0 * open_bins_count as f64;
    }

    // Progress: late in the stream, be more conservative with new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress;

    score
}

