            score += 17.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        // Tiling-aware fresh-bin bonus.
        if next_item_size > 1 && fresh_post > 0.0 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 2 && rem == 0 && fragmentation < 0.4 {
                score -= 10.0 * ((reps as f64).min(4.0) - 1.0) * (0.4 + 0.6 * (1.0 - progress));
            }
            if reps >= 3 && rem == 0 && fragmentation < 0.3 {
                score -= 14.0 * ((reps as f64).min(5.0) - 2.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        if fresh_post > 0.35 * cap && remaining_frac > 0.2 && mean_residual * open_bins_count as f64 > 4.0 * cap && fragmentation < 0.45 {
            score += 20.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        if fitting_bins_count <= 1 && fresh_post > 0.0 && next_item_size > 0 {
            let stranded_here = bin_capacity.saturating_sub(item_size);
            let would_strand = stranded_here < next_item_size;
            if would_strand && stranded_here > 0 && stranded_here <= 8 {
                score -= 32.0 * (1.0 - progress);
            }
        }
        // MUTATION (gen 120): fresh-bin tile-lane bonus — when the fresh
        // bin's post-residual is an exact multiple of the next item size,
        // opening creates a dedicated zero-waste lane; reward scaled by
        // how much open slack exists elsewhere (less slack = more valuable).
        if next_item_size > 1 && fresh_post > 0.0 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if rem == 0 && reps >= 1 {
                let slack_per_bin = mean_residual / cap;
                score -= 8.0 * (reps as f64).min(3.0) * (1.0 - slack_per_bin.min(1.0)) * (1.0 - progress);
            }
        }
        // MUTATION (gen 120): residual-harmony fresh-bin bonus.
        if fresh_post > 0.0 && fresh_match < 0.2 && fragmentation < 0.5 && remaining_frac > 0.1 {
            score -= 14.0 * (1.0 - fresh_match / 0.2) * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if next item fits exactly into post_residual, reward strongly
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item fits, but penalize leftover dead space after both placements
            let after2 = post_residual - next_item_size;
            score -= 100.0 - after2 as f64 * 0.5;
        } else {
            // next item cannot use the residual; penalize proportional to wasted space
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bonus: only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Penalize creating tiny unusable residuals (dead space below min item size)
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }

    // Compare against mean residual: prefer bins tighter than average
    score += (mean_residual - post_residual as f64) * 0.2;

    // New-bin candidate: make it unattractive unless all fits are terrible
    if bin_residual == bin_capacity {
        score += 120.0;
        // if next item is large and current item small, opening fresh bin can be good
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 60.0;
        }
    }

    // Late in stream: consolidation matters more
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 50.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
