}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Non-linear polynomial coupling of post residual with stream progress
    let mut score = x * x * (1.0 + 2.0 * progress) + 0.5 * x * (1.0 - progress);

    // Penalize very small dead space less than mid-range waste (smooth cubic)
    score -= 0.3 * (1.0 - x) * (1.0 - x) * (1.0 - x);

    // Lookahead: reward if next item fits in post residual (smooth interaction)
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let fits = ((pr - next_item_size as f64) / cap).max(0.0);
        score -= 0.6 * fits * (1.0 - progress);
        score += 0.2 * (nx - x).abs() * progress;
    }

    // Last-chance bin: strong smooth reward
    if fitting_bins_count == 1 {
        score -= 1.5 * (1.0 - x);
    }

    // Mild coupling with mean residual and open bins count
    score += 0.1 * (mean_residual / cap - x).abs();
    score += 0.02 * open_bins_count as f64 * x;

    // New-bin candidate: neutral-to-slightly-high baseline unless waste is low
    if bin_residual == bin_capacity {
        score = 0.8 + x;
    }

    score
}

