        if fresh_post > 4.0 && fresh_post <= 8.0 {
            score -= 20.0 * (1.0 - (fresh_post - 4.0) / 5.0) * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: quantize item size into capacity fractions (10 classes of 10)
    let item_class = item_size / 10;
    let next_class = if next_item_size > 0 { next_item_size / 10 } else { 0 };

    // Reward tight fits: post_residual small relative to item size
    if post_residual <= 5 {
        score -= 30.0; // near-perfect fit
    } else if post_residual <= 10 {
        score -= 20.0;
    } else if post_residual <= 20 {
        score -= 8.0;
    }

    // Penalize dead space that cannot plausibly fit the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // chainable: bonus proportional to how well next item also fits tightly
            let next_post = post_residual - next_item_size;
            score -= 6.0 + (next_post as f64).min(20.0) * 0.3;
        } else {
            // dead space: penalize proportionally to how much it falls short
            let gap = (next_item_size - post_residual) as f64;
            score += gap.min(40.0) * 0.5;
        }
    }

    // Modulo-based harmonic pairing: reward bins whose residual matches common small classes
    let pr = post_residual;
    if pr > 0 && pr <= 30 {
        // small residuals pair well with small classes (10-30)
        if item_class <= 3 {
            score -= 4.0;
        }
        // exact harmonic residue: pr % 10 == 0 means clean divisible leftover
        if pr % 10 == 0 {
            score -= 3.0;
        }
    }

    // Penalize mid-range residuals (30..60) that are hard to fill unless next item fits
    if pr > 30 && pr < 60 && next_item_size > 0 && next_item_size > pr {
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: opening fresh is only good when item is large
    // or residuals are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        if item_size >= 60 || (open_bins_count > 0 && fragmentation < 0.15) {
            score -= 10.0; // big items deserve fresh bins
        } else {
            score += 25.0; // discourage wasteful new bins for small items
        }
    }

    // Mild pressure to consolidate as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (mean_residual - post_residual as f64).abs() * 0.05;
    score += progress * 0.0; // placeholder coupling kept neutral

    score
}

