}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to ever hold
    // an item (min size 1..100 unknown, so treat < ~15 as near-dead) are
    // heavily penalized, super-linearly.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 15.0 {
        score += (15.0 - pr) * 8.0;
    }

    // Reward tight fits (perfect fill is ideal).
    if post_residual == 0 {
        score -= 60.0;
    } else if pr < 5.0 {
        score -= 25.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly
    // prefer using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into
    // existing bins; penalize the fresh-bin candidate (residual == capacity).
    if bin_residual == bin_capacity {
        score += 12.0 + 3.0 * open_bins_count as f64;
        // But allow a new bin when next item cannot fit anywhere sensible.
        if next_item_size > 0 && next_item_size > post_residual {
            // keep penalty; new bin still discouraged
        }
    } else {
        score -= 2.0 * open_bins_count as f64;
    }

    // Prefer bins whose residual is below the mean (filling emptier bins
    // leaves tighter bins for future large items).
    score += (pr - mean_residual) * 0.5;

    // Lookahead: if next item fits exactly in post_residual, big bonus.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    }

    // Late in stream: minimize bin count aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.7 && bin_residual < bin_capacity {
        score -= 15.0 * progress;
    }

    score
}

