    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 12.0 * (1.0 / (1.0 + diff / 8.0)); // smooth exact-match bonus
        if post_residual == next_item_size {
            score -= 15.0; // perfect 2-chain
        }
        // Penalize leaving dead space the next item cannot use
        if post_residual < next_item_size && post_residual > 0 {
            score += 0.35 * post_residual as f64;
        }
    } else {
        // Last item: minimize waste directly
        score += 0.2 * post_residual as f64;
    }

    // Tight-fit reward: small post_residual is generally good
    score -= 0.25 * (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64 * item_size as f64;

    // Compare against mean residual: prefer bins tighter than average
    score += 0.15 * (mean_residual - post_residual as f64);

    // Last-chance bin before opening a new bin: strong incentive to use it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are very full
    if bin_residual == bin_capacity {
        score += 18.0 + 2.0 * open_bins_count as f64;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0; // fresh bin can still host a good 2-chain
