pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space that is too small to be useful later.
    let dead_threshold = 10.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 3.0;
    }

    // Reward tight fits: small post residual relative to capacity.
    score -= (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64 * 8.0;

    // Last-chance bin bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits into post_residual, big reward.
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            score -= 12.0 + (post_residual - next_item_size) as f64 * 0.2;
        } else {
            // Next item won't fit here; penalize wasting space that next item could use elsewhere.
            let waste = post_residual as f64 - (bin_residual as f64 - next_item_size as f64).max(0.0);
            score += waste.max(0.0) * 0.15;
        }
    }

    // Time horizon: early in stream, favor consolidating into open bins (prefer small post_residual);
    // late in stream, opening new bins is cheaper so reward new-bin candidates slightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New bin candidate: score = full capacity residual; adjust by progress and mean residual.
        score -= progress * 15.0;
        // If mean residual across open bins is small (fragmented), opening new bin is attractive.
        score -= (mean_residual / bin_capacity as f64).min(1.0) * 20.0;
        // If many bins already open, discourage adding more.
        score += open_bins_count as f64 * 1.5;
    } else {
        // Existing bin: mild penalty proportional to open bins count to balance load.
        score += (open_bins_count as f64).ln().max(0.0) * 0.5;
    }

    // Prefer placing large items into bins where they leave structured residuals
    // (multiples of common small sizes): reward residuals like 0, 10, 20, 30...
    let pr = post_residual;
    if pr % 10 == 0 {
        score -= 3.0;
    }

    // Global fragmentation penalty: if this bin's residual is far below mean residual,
    // it's a poorly utilized bin; penalize choosing it unless it's a tight fit.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score += dev * 0.1;
    }

    score
}

