        }
        if next_item_size > 0 && post_residual > next_item_size + next_item_size / 2
            && fitting_bins_count > 2 && mean_residual > 0.0
            && (mean_residual as u32) >= next_item_size {
            score += 4.5 * ((post_residual - next_item_size) as f64 / cap) * (1.0 - progress);
        }
        // gen 94: two-step tiling lookahead.
        if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count > 1 {
            let tail = post_residual - next_item_size;
            if tail == 0 {
                score -= 6.0 * progress;
            } else if tail <= 8 {
                let scarcity = 1.0 / (fitting_bins_count as f64);
                score -= (5.0 + 5.0 * scarcity) * (1.0 - tail as f64 / 8.0) * (0.3 + 0.7 * progress);
            }
        }
        // gen 94: dead-space strand gradient.
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            let open_space = mean_residual * open_bins_count as f64;
            if open_space > 1.5 * cap {
                let stranded = (next_item_size - post_residual) as f64;
                score += 3.0 * (stranded / cap) * (open_space / cap).min(3.0) * (0.4 + 0.6 * progress);
            }
        }
        // gen 102: mid-gap consolidation.
        if post_residual > 12 && post_residual <= 24 && fitting_bins_count > 1 {
            let mid = (post_residual as f64 - 12.0) / 12.0;
            score += 5.5 * mid * (0.35 + 0.65 * progress);
        }
        // gen 102: two-step exact-closure pair bonus.
        if next_item_size > 0 && post_residual == next_item_size && dead_ratio < 0.06 {
            score -= 9.0 * (0.4 + 0.6 * progress);
        }
        // gen 102: scarcity-weighted near-fit preference.
        if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 2 {
            let tail = (post_residual - next_item_size) as f64;
            score -= 4.5 * (1.0 - tail / cap) * (1.0 - progress);
        }
        // MUTATION (gen 110): residual-harmonic consolidation.
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 1 {
            let down = mean_residual - post_residual as f64;
            if down > 0.0 && down <= 6.0 {
                score -= 7.0 * (1.0 - down / 6.0) * (0.3 + 0.7 * progress);
            }
        }
        // MUTATION (gen 110): late-stream exact-fill amplifier.
        if progress > 0.75 && post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
            let tail = (post_residual - next_item_size) as f64;
            if tail <= 2.0 {
                score -= 12.0 * (1.0 - tail / 2.0) * (progress - 0.75) / 0.25;
            }
        }
        // MUTATION (gen 123): dead-space ratio fine gradient — extend the
        // diagnosed dead-space weakness with a smooth penalty that grows
        // continuously above 0.2 dead ratio, so mid-range wasteful fits
        // (previously untouched between 0.08 and 0.35) are also discouraged
        // when enough alternatives exist.
        if post_residual > 0 && fitting_bins_count > 2 && dead_ratio > 0.2 {
            score += 3.0 * (dead_ratio - 0.2) * (0.4 + 0.6 * (1.0 - progress));
        }
        // MUTATION (gen 123): two-item lookahead closure — when the residual
        // after placing the next item would still hold roughly a second
        // copy of the next item (a double-tile lane), reward strongly so
        // slack is drained in multiples instead of leaving scattered bits.
        if next_item_size > 1 && post_residual >= 2 * next_item_size && fitting_bins_count > 1 {
            let reps = post_residual / next_item_size;
            let rem = post_residual % next_item_size;
