pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no item (>=1) can plausibly use
    // are pure waste; the smaller the gap, the more it is actually usable,
    // but very small gaps (< typical min item) are penalized hard.
    let dead = post_residual as f64;
    if dead > 0.0 && dead < 10.0 {
        score += 60.0 - dead * 4.0; // unusable sliver: strong penalty
    }

    // Tight fit reward: exponential preference for near-perfect packing.
    score -= 40.0 * (-dead / 12.0).exp();

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 55.0;
    }

    // New-bin candidate handling: opening a fresh bin should only win when the
    // item leaves a large residual in this bin (poor fit) or bins are scarce.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 45.0 + 8.0 * open_bins_count as f64;
        if post_residual as f64 >= mean_residual.max(30.0) {
            score -= 20.0; // item would waste lots of an existing bin anyway
        }
    } else {
        // Open-bin pressure: many open bins -> favor filling existing ones.
        score -= (open_bins_count as f64).ln().max(0.0) * 6.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 10.0; // next item won't fit here -> slight penalty
    }

    // Stream progression: late in the stream, be more conservative about new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if is_new_bin {
        score += 25.0 * progress;
    }

    // Mild alignment with mean residual: bins already above average residual
    // are less precious; bins below average are worth filling.
    if !is_new_bin {
        score += (mean_residual - bin_residual as f64) * 0.15;
    }

    score
}

