        }
        // MUTATION (gen 124): residual-variance squeeze — mid/late stream,
        // prefer placements whose post-residual lands close to the next item
        // size so the leftover stays immediately reusable; scale the pull by
        // aggregate open slack so it only acts when slack is abundant.
        if post_residual > 0 && next_item_size > 0 && post_residual > next_item_size && progress > 0.3 {
            let gap = (post_residual - next_item_size) as f64;
            let open_space = mean_residual * open_bins_count as f64;
