            score -= 6.5 * fill * (progress - 0.4);
        }
        // MUTATION (gen 125): residual-band homogenizer — when many bins fit,
        // penalize placements whose post-residual sits in the awkward mid-band
        // (too large to be near-full, too small to tile two more items),
        // pushing the stream toward either tight or tileable residuals.
        if post_residual > 0 && next_item_size > 1 && fitting_bins_count > 1 {
            let twice = 2 * next_item_size;
            if post_residual < twice {
                let band = (twice - post_residual) as f64;
                if band > 4.0 && band < 0.25 * cap {
                    let scarcity = 1.0 / (fitting_bins_count as f64);
                    score += 3.8 * (band / (0.25 * cap)) * scarcity * (0.45 + 0.55 * (1.0 - progress));
                }
            }
        }
        // MUTATION (gen 125): late-stream exact-fit anchor — after 70% of the
        // stream, a placement that leaves a residual the next item exactly
        // fills is nearly free capacity; deepen the reward as scarcity rises.
        if progress > 0.7 && next_item_size > 0 && post_residual == next_item_size {
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            score -= 22.0 * (1.0 + scarcity) * (progress - 0.7) / 0.3;
        }
    } else {
        let fragmentation = (mean_residual / cap) * open_bins_count as f64;
        let huge_item = item_size as f64 > 0.7 * cap;
