        if remaining_frac >= 0.05 && fresh_post > 0.3 * cap && next_item_size > 0 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (next_item_size as f64) * 0.42;
            if open_space > 1.15 * est_need {
                score += 30.0 * (1.0 - remaining_frac) * (fresh_post / cap - 0.3);
            }
        }
        // gen 76: fresh-bin dead-space cap.
        if fresh_post > 0.35 * cap && next_item_size > 0 && (fresh_post as u32) < next_item_size && fragmentation < 0.4 && remaining_frac > 0.15 {
            score += 16.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        // gen 81: tileability-aware open.
        if next_item_size > 1 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 3 && rem == 0 && fragmentation < 0.3 {
                score -= 14.0 * ((reps as f64).min(5.0) - 2.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // MUTATION (gen 125): two-item tileability open — reward opens whose
        // fresh post-residual fits exactly two of the next item (rem == 0,
        // reps == 2) even at moderate fragmentation, since a fresh bin tiled
        // twice beats scattering two poor fits across open bins.
        if next_item_size > 1 && (fresh_post as u32) == 2 * next_item_size && fragmentation < 0.45 {
            score -= 9.0 * (0.5 + 0.5 * (1.0 - progress));
        }
        // MUTATION (gen 125): near-closed-bin open bonus — when the fresh
        // placement leaves a very small post-residual (<= 6), the new bin is
        // effectively sealed; reward this strongly when open slack is ample,
        // converting scattered slack into dense closed bins.
        if fresh_post > 0.0 && fresh_post <= 6.0 && !fresh_is_exact {
            let open_space = mean_residual * open_bins_count as f64;
            if open_space > 1.5 * cap {
                score -= 20.0 * (1.0 - fresh_post / 6.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lies on fine
    // modulo lattices are more reusable, reward them.
    let pr = post_residual;
    if pr > 0 {
        // Divisibility rewards: highly composite-friendly leftovers.
        if pr % 10 == 0 { score -= 6.0; }
        if pr % 5 == 0  { score -= 2.5; }
        if pr % 20 == 0 { score -= 3.0; }
        if pr % 25 == 0 { score -= 3.0; }
        if pr % 50 == 0 { score -= 4.0; }
        // Dead-space penalty: tiny unusable remainders.
        if pr < 10 { score += 18.0; }
        else if pr < 20 { score += 7.0; }
        // Perfect-fit bonus.
        if pr == 0 { score -= 30.0; }
    }

    // Coupling with next item: if the next item fits exactly into
    // post_residual, strongly favor this bin (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            // next item fits: leftover after chain, modulo-harmonic bonus
            let pr2 = pr - next_item_size;
            if pr2 % 10 == 0 { score -= 4.0; }
            if pr2 < 10 { score += 6.0; }
            score -= 3.0;
        } else {
            // next item cannot use this bin's leftover: slight penalty
            score += 4.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: neutral-ish baseline, but prefer it only when
    // existing fits would create heavy dead space.
    if bin_residual == bin_capacity {
        score += 8.0;
        // Early in stream, opening fresh bins is cheap.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Prefer tighter bins overall (small residual relative to mean).
    score += (mean_residual - bin_residual as f64).max(-20.0).min(20.0) * 0.15;

    // Slight pressure against proliferating many open bins.
    score += open_bins_count as f64 * 0.05;

    score
}

