            let open_space = mean_residual * open_bins_count as f64;
            let remaining = total_items.saturating_sub(step_index).max(1) as f64;
            let est_demand = remaining * next_item_size as f64;
            if open_space < 1.2 * est_demand {
                let shortfall = (next_item_size - post_residual) as f64;
                let pressure = (1.2 - open_space / est_demand.max(1.0)).min(1.0);
                score += (4.0 + 8.0 * pressure) * (shortfall / cap).min(0.5) * (0.4 + 0.6 * progress);
            }
        }
        // MUTATION (gen 125): two-step tile check — reward placements whose
        // post-residual can absorb the next item AND still leave a sliver
        // under a small threshold (near-perfect double fill), sharpening the
        // diagnosed residual-variance weakness.
