        }
        // gen 76: fresh-bin dead-space cap.
        if fresh_post > 0.35 * cap && next_item_size > 0 && (fresh_post as u32) < next_item_size && fragmentation < 0.4 && remaining_frac > 0.15 {
            score += 16.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        // gen 81: tileability-aware open.
        if next_item_size > 1 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 3 && rem == 0 && fragmentation < 0.3 {
                score -= 14.0 * ((reps as f64).min(5.0) - 2.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // MUTATION (gen 125): demand-pressure open gate — when aggregate open
        // slack already exceeds projected demand for the next item, refuse
        // fresh bins whose post-residual cannot even hold the next item,
        // scaling the refusal with the shortfall so oversized dead lanes are
        // avoided while genuinely useful opens stay cheap.
        if next_item_size > 0 && fresh_post > 0.0 && (fresh_post as u32) < next_item_size {
            let open_space = mean_residual * open_bins_count as f64;
            let remaining = total_items.saturating_sub(step_index).max(1) as f64;
            let est_demand = remaining * next_item_size as f64;
            if open_space > 0.9 * est_demand {
                let shortfall = next_item_size as f64 - fresh_post;
                score += 12.0 * (shortfall / cap).min(0.4) * (0.5 + 0.5 * (1.0 - remaining_frac));
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (dead-space elimination).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    }

    // Aggressive 2-step lookahead: if the next item fits exactly into the
    // post residual, this is a perfect chaining placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual > next_item_size {
            // Slack left after both placements: penalize proportional waste.
            score -= 0.3 * (post_residual - next_item_size) as f64;
        } else {
            // Next item cannot use the leftover space -> dead space risk.
            score += 0.8 * (next_item_size - post_residual) as f64;
        }
    }

    // Relative-to-mean coupling: bins tighter than the mean are precious;
    // prefer dumping items into loose (large-residual) bins.
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bonus: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual <= 30 {
        score -= 150.0;
    }

    // New-bin candidate: only attractive early in the stream or when the
    // current fit is very poor; otherwise penalize bin proliferation.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 120.0 + 200.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size >= bin_residual {
            score -= 250.0; // fresh bin guarantees fit for the next item too
        }
    }

    // Mild penalty for many open bins to encourage consolidation.
    score += 2.0 * open_bins_count as f64;

    score
}

