    // Global state coupling: prefer bins that are tighter than the mean residual
    // (consume the fullest bins first).
    let diff = mean_residual - bin_residual as f64;
    score += 0.15 * diff;

    // Mild preference for bins whose residual is close to item size (best-fit shaping).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.08 * gap;

    score
}

