pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small non-zero gaps are highly unusable.
    if post_residual > 0 {
        // Dead space severity: gaps below the smallest conceivable item chunk
        // (say < 10) are worthless; gaps just above a small item are fragile.
        if post_residual < 10 {
            score += 60.0; // unusable sliver
        } else if post_residual <= 20 {
            score += 25.0; // very fragile gap
        } else if post_residual <= 35 {
            score += 8.0;  // moderate dead space
        } else {
            score -= 6.0;  // roomy residual is reusable
        }
    } else {
        // Perfect fill: reward strongly.
        score -= 100.0;
    }

    // Tightness reward: relative fill quality of this placement.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 20.0 * tightness;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when no open bin is good
    // (i.e., current bin is a poor fit) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Penalize new bins more as open bins pile up; slight relief early on.
        score += 15.0 + 2.0 * open_bins_count as f64 * (1.0 - 0.5 * progress);
        // If next item is large and this bin would remain nearly full, a fresh
        // bin is actually fine — soften the penalty.
        if next_item_size >= 60 && post_residual < 20 {
            score -= 20.0;
        }
    }

    // Open-bin pressure: prefer consolidating into bins when many are open.
    score += 0.05 * open_bins_count as f64;

    // Prefer bins whose residual deviates favorably from the mean
    // (below-mean residual means this bin is already well-utilized).
    score += 0.1 * (bin_residual as f64 - mean_residual);

    // Lookahead: if the post residual can host the next item, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    score
}

