        let gap = (post_residual as i64 - next_item_size as i64).abs();
        if post_residual >= next_item_size {
            score -= 25.0 * (1.0 - gap as f64 / (bin_capacity as f64)).powi(2);
        } else {
            // Next item won't fit: penalize leaving residual smaller than next item (dead space).
            score += 12.0 * (1.0 - (post_residual as f64) / (next_item_size.max(1) as f64).min(bin_capacity as f64)).abs();
        }
