    // New bin candidate: penalize opening a new bin unless current fit is terrible.
    if bin_residual == bin_capacity {
        score += 30.0;
        // But if lookahead suggests next item pairs well with a fresh bin, soften penalty.
        if next_item_size > 0 && next_item_size + item_size >= bin_capacity {
            score -= 35.0;
        }
    }

    // Late in stream, be more conservative about opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
