        // bin's post-residual is tiny (<= 3), the new bin closes almost
        // perfectly; reward strongly unless aggregate slack is abundant.
        if fresh_post > 0.0 && fresh_post <= 3.0 {
            let open_space = mean_residual * open_bins_count as f64;
            let damp = if open_space > 3.0 * cap { 0.4 } else { 1.0 };
