        if post_residual > 6 && post_residual <= 30 && next_item_size > 0 && next_item_size <= post_residual {
            let reps = post_residual / next_item_size.max(1);
            if reps >= 2 {
                score -= 3.5 * (reps as f64).min(4.0) * (1.0 - progress);
            }
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let after_next = post_residual - next_item_size;
            if after_next > 0 && after_next <= 12 {
                let tail = after_next as f64;
                score -= (14.0 - 0.9 * tail) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        if post_residual > 0 && post_residual < 6 && next_item_size > post_residual {
            score += 6.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let after_next = (post_residual - next_item_size) as f64;
            if after_next > 8.0 && after_next <= 16.0 && progress < 0.85 {
                let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
                score -= (4.0 + 3.0 * scarcity) * (1.0 - (after_next - 8.0) / 8.0) * (1.0 - progress);
            }
        }
        if post_residual > 0 && next_item_size > 0 && fitting_bins_count > 3 {
            let overshoot = post_residual.saturating_sub(next_item_size) as f64;
            if overshoot > 16.0 {
                score += 1.6 * ((overshoot - 16.0) / cap).min(0.25) * (1.0 - progress);
            }
        }
        if fitting_bins_count > 1 && dead_ratio > 0.08 && post_residual > 0 {
            let scarcity = 1.0 / (fitting_bins_count as f64);
            let comp_slack = (mean_residual / cap).min(1.0);
            score += 6.5 * (dead_ratio - 0.08) * scarcity * comp_slack * (0.5 + 0.5 * (1.0 - progress));
            score += 2.2 * (dead / cap) * scarcity * comp_slack * (1.0 - progress);
        }
        if fitting_bins_count > 2 && post_residual > 0 && mean_residual > 0.0 {
            let dev = ((post_residual as f64 - mean_residual).abs() / cap).min(0.4);
            score += 5.0 * dev * (1.0 - progress);
        }
        if post_residual > 0 && post_residual % 10 == 0 && post_residual <= 60 && next_item_size > 0 && next_item_size <= post_residual {
            score -= 4.0 * (1.0 - progress) * (1.0 - post_residual as f64 / 120.0);
        }
        if next_item_size > 0 && post_residual > next_item_size && fitting_bins_count <= 3 {
            let tail = post_residual - next_item_size;
            if tail >= 1 && tail <= 12 {
                score -= 9.0 * (1.0 - tail as f64 / 12.0) * (1.0 - progress);
            }
        }
        if next_item_size > 0 && post_residual == next_item_size && open_bins_count > 5 {
            score -= 14.0 * (0.4 + 0.6 * (1.0 - progress));
        }
        if post_residual >= 16 && post_residual <= 28 && progress < 0.7 && fitting_bins_count > 1 {
            score -= 7.0 * (1.0 - (post_residual - 16) as f64 / 12.0) * (0.5 + 0.5 * progress);
        }
        if next_item_size > 0 && post_residual > next_item_size && fitting_bins_count > 1 {
            let excess = (post_residual - next_item_size) as f64;
            if excess > 12.0 {
                score += 1.8 * ((excess - 12.0) / cap).min(0.3) * (1.0 - progress) * (fitting_bins_count as f64).min(4.0);
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 4 {
            let gap_after = (post_residual - next_item_size) as f64;
            let urgency = (4.0 - fitting_bins_count as f64) / 3.0;
            score -= 10.0 * urgency * (1.0 - gap_after / cap) * (0.5 + 0.5 * (1.0 - progress));
        }
        if post_residual > 0 && mean_residual > 0.0 && open_bins_count > 3 {
            let below = mean_residual - post_residual as f64;
            if below > 0.25 * cap && progress < 0.75 {
                score += 6.0 * (below / cap) * (1.0 - progress);
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 6 {
            let tail = post_residual - next_item_size;
            let urgency = (6.0 - fitting_bins_count as f64) / 5.0;
            if tail == 0 {
                score -= 22.0 * urgency * (1.0 - progress);
            } else if tail <= 2 {
                score -= 9.0 * urgency * (1.0 - tail as f64 / 2.0) * (1.0 - progress);
            }
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size
            && mean_residual > 0.0 && (mean_residual as u32) >= next_item_size && fitting_bins_count > 1 {
            score += 7.0 * (1.0 - progress);
        }
        if post_residual > 0 && next_item_size > 0 && fitting_bins_count > 1 {
            let usable = next_item_size <= post_residual
                || (mean_residual as u32) >= next_item_size;
            if !usable {
                let waste_frac = post_residual as f64 / cap;
                let late = 0.35 + 0.65 * progress;
                score += 9.0 * waste_frac * late;
            }
        }
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 2 {
            let rel = post_residual as f64 / (mean_residual + 1.0);
            if rel < 0.5 {
                score -= 6.0 * (1.0 - rel / 0.5) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        if next_item_size > 0 && post_residual == next_item_size && fitting_bins_count <= 3 {
            score -= 30.0 / fitting_bins_count.max(1) as f64 * (0.5 + 0.5 * (1.0 - progress));
        }
        if next_item_size > 1 && post_residual > 0 && post_residual >= next_item_size {
            let reps = post_residual / next_item_size;
            let rem = post_residual % next_item_size;
            if reps >= 1 && rem == 0 {
                let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
                score -= (5.0 + 6.0 * scarcity) * (reps as f64).min(3.0) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        if post_residual > 0 && next_item_size > 0 && post_residual > next_item_size {
            let after_next = post_residual - next_item_size;
            if after_next > 0 && after_next < 6 && progress > 0.35 {
                score -= 11.0 * (1.0 - after_next as f64 / 6.0) * (progress - 0.35);
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count == 1 {
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score -= 14.0 * (1.0 - progress) * (0.6 + 0.4 * tightness);
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
            && fitting_bins_count > 1 {
            let open_space = mean_residual * open_bins_count as f64;
            if open_space > 2.0 * cap {
                let frac = post_residual as f64 / next_item_size as f64;
                score += 10.0 * (1.0 - frac) * (0.5 + 0.5 * progress);
            }
        }
        if post_residual > 0 && fitting_bins_count > 2 && progress > 0.5 {
            let fill = 1.0 - post_residual as f64 / cap;
            score -= 5.0 * fill * (progress - 0.5);
        }
        if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 4 {
            let proximity = 1.0 - (post_residual - next_item_size) as f64 / 4.0;
            score -= 8.0 * proximity * (0.4 + 0.6 * (1.0 - progress));
        }
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 2 && progress > 0.4 {
            let dev = ((post_residual as f64 - mean_residual).abs() / cap).min(0.5);
            score += 3.6 * dev * (progress - 0.4);
        }
        if post_residual > 0 && (post_residual as f64) > 0.55 * cap
            && next_item_size > 0 && (post_residual as u32) >= next_item_size
            && (post_residual - next_item_size) > 20 && fitting_bins_count > 1 {
            score += 6.0 * (post_residual as f64 / cap - 0.55) * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > next_item_size && fitting_bins_count > 1 {
            let tail = post_residual - next_item_size;
            if tail >= 1 && tail <= 6 {
                let scarcity = 1.0 / (fitting_bins_count as f64);
                score -= (6.0 + 4.0 * scarcity) * (1.0 - tail as f64 / 6.0)
                    * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        if next_item_size > 0 && post_residual > next_item_size + next_item_size / 2
            && fitting_bins_count > 2 && mean_residual > 0.0
            && (mean_residual as u32) >= next_item_size {
            score += 4.5 * ((post_residual - next_item_size) as f64 / cap) * (1.0 - progress);
        }
        // gen 94: two-step tiling lookahead.
        if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count > 1 {
            let tail = post_residual - next_item_size;
            if tail == 0 {
                score -= 6.0 * progress;
            } else if tail <= 8 {
                let scarcity = 1.0 / (fitting_bins_count as f64);
                score -= (5.0 + 5.0 * scarcity) * (1.0 - tail as f64 / 8.0) * (0.3 + 0.7 * progress);
            }
        }
        // gen 94: dead-space strand gradient.
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            let open_space = mean_residual * open_bins_count as f64;
            if open_space > 1.5 * cap {
                let stranded = (next_item_size - post_residual) as f64;
                score += 3.0 * (stranded / cap) * (open_space / cap).min(3.0) * (0.4 + 0.6 * progress);
            }
        }
        // gen 102: mid-gap consolidation.
        if post_residual > 12 && post_residual <= 24 && fitting_bins_count > 1 {
            let mid = (post_residual as f64 - 12.0) / 12.0;
            score += 5.5 * mid * (0.35 + 0.65 * progress);
        }
        // gen 102: two-step exact-closure pair bonus.
        if next_item_size > 0 && post_residual == next_item_size && dead_ratio < 0.06 {
            score -= 9.0 * (0.4 + 0.6 * progress);
        }
        // gen 102: scarcity-weighted near-fit preference.
        if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 2 {
            let tail = (post_residual - next_item_size) as f64;
            score -= 4.5 * (1.0 - tail / cap) * (1.0 - progress);
        }
        // MUTATION (gen 110): residual-harmonic consolidation.
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 1 {
            let down = mean_residual - post_residual as f64;
            if down > 0.0 && down <= 6.0 {
                score -= 7.0 * (1.0 - down / 6.0) * (0.3 + 0.7 * progress);
            }
        }
        // MUTATION (gen 110): late-stream exact-fill amplifier.
        if progress > 0.75 && post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
            let tail = (post_residual - next_item_size) as f64;
            if tail <= 2.0 {
                score -= 12.0 * (1.0 - tail / 2.0) * (progress - 0.75) / 0.25;
            }
        }
        // MUTATION (gen 129): dead-space compaction gradient — when the
        // placement strands a residual far below the next item while the
        // aggregate open slack elsewhere is large, the leftover here is
        // pure dead space; penalize proportionally to shrink residual
        // variance (diagnosed weakness).
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
            && fitting_bins_count > 1 {
            let open_space = mean_residual * open_bins_count as f64;
            if open_space > 2.0 * cap {
                let frac = post_residual as f64 / next_item_size as f64;
                score += 8.0 * (1.0 - frac) * (0.5 + 0.5 * progress);
            }
        }
        // MUTATION (gen 129): consolidation pull toward the mean target —
        // prefer placements that bring this bin's post-residual close to a
        // common compaction target (midway between mean residual and half
        // capacity), tightening late-stream residual spread.
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 1 && progress > 0.25 {
            let target = 0.5 * (mean_residual + 0.5 * cap);
            let dev = ((post_residual as f64 - target).abs() / cap).min(0.5);
            score += 2.6 * dev * (progress - 0.25);
        }
        // MUTATION (gen 129): usable-residual scarcity bonus — when this is
        // the only fitting bin and the post-residual tightly matches the
        // next item, reward the tight reuse strongly.
        if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count == 1 {
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score -= 14.0 * (1.0 - progress) * (0.6 + 0.4 * tightness);
        }
    } else {
        // NEW-BIN CANDIDATE branch.
        let fragmentation = (mean_residual / cap) * open_bins_count as f64;
        let huge_item = item_size as f64 > 0.7 * cap;
        let remaining = if total_items > step_index { total_items - step_index } else { 1 };
        let remaining_frac = remaining as f64 / total_items.max(1) as f64;
        let fresh_post = cap - item_size as f64;
        let fresh_is_exact = fresh_post <= 4.0 && fresh_post >= 0.0;

        if fragmentation > 0.55 || (huge_item && open_bins_count > 4) {
            score -= 66.0 + 46.0 * remaining_frac;
        } else if fresh_is_exact {
            score -= 134.0 + 66.0 * remaining_frac;
        } else {
            score += 400.0 - 82.0 * remaining_frac;
            if fitting_bins_count <= 3 && open_bins_count > 2 {
                score -= 30.0 + 18.0 * remaining_frac;
            }
        }

        let fresh_match = (fresh_post - mean_residual).abs() / cap;
        if fresh_match < 0.05 {
            score -= 76.0 * (1.0 - fresh_match / 0.05);
        }
        if remaining_frac < 0.05 && fresh_post > 0.0 && !fresh_is_exact {
            score += 160.0 * (fresh_post / cap);
        }
        if fresh_post > 0.0 && fresh_post <= 22.0 && !fresh_is_exact {
            score -= 26.0 * (1.0 - fresh_post / 22.0);
        }
        if fresh_post > 22.0 && fresh_post <= 40.0 && fragmentation < 0.35 {
            score -= 12.5 * (1.0 - (fresh_post - 22.0) / 18.0);
        }
        if fresh_post > 0.0 && fresh_match < 0.12 && fragmentation < 0.55 {
            score -= 30.0 * (1.0 - fresh_match / 0.12);
        }
        if next_item_size > 0 && fresh_post > 0.0 {
            let fresh_exact_next = (fresh_post as u32) == next_item_size;
            let open_can_next = mean_residual >= next_item_size as f64;
            if fresh_exact_next && !open_can_next && fitting_bins_count <= 2 {
                score -= 52.0 * (1.0 - progress);
            }
            if (fresh_post as u32) < next_item_size && mean_residual > next_item_size as f64 {
                score += 21.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && fresh_post > next_item_size as f64 {
            let chain_post = fresh_post - next_item_size as f64;
            if chain_post <= 4.0 {
                score -= 34.0 * (1.0 - chain_post / 4.0) * (0.5 + 0.5 * (1.0 - progress));
            } else if chain_post <= 10.0 {
                score -= 9.5 * (1.0 - (chain_post - 4.0) / 6.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        if remaining_frac < 0.12 && fresh_post > 0.0 && !fresh_is_exact && mean_residual * open_bins_count as f64 > 3.0 * cap {
            score += 42.0 * (1.0 - remaining_frac / 0.12);
        }
        if fitting_bins_count == 1 && fresh_post > 0.0 && next_item_size > 0 {
            let stranded_here = bin_capacity.saturating_sub(item_size);
            let would_strand = stranded_here < next_item_size;
            if would_strand && stranded_here > 0 && stranded_here <= 8 {
                score -= 32.0 * (1.0 - progress);
            }
        }
        let open_capacity = mean_residual * open_bins_count as f64;
        if remaining_frac > 0.25 && open_capacity < cap * 0.5 * open_bins_count.max(1) as f64 * 0.5 {
            score -= 18.0 * (1.0 - progress);
        }
        if next_item_size > 0 && fresh_post > next_item_size as f64 {
            let after_next = fresh_post - next_item_size as f64;
            if after_next > 0.0 && after_next <= 8.0 && fragmentation < 0.5 {
                score -= 20.0 * (1.0 - after_next / 8.0) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        if next_item_size > 0 && fresh_post > 0.0 && (fresh_post as u32) < next_item_size {
            let slack_total = mean_residual * open_bins_count as f64;
            if slack_total > 2.0 * cap {
                score += 26.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && (fresh_post as u32) == next_item_size && fragmentation > 0.3 {
            score -= 44.0 * (0.5 + 0.5 * (1.0 - progress));
        }
        if fresh_post > 0.5 * cap && mean_residual < 0.2 * cap && remaining_frac > 0.3 && open_bins_count > 3 {
            score += 24.0 * (fresh_post / cap - 0.5) * 2.0 * (1.0 - progress);
        }
        if fitting_bins_count <= 1 && fresh_post > 0.45 * cap && next_item_size > 0 {
            let reachable = (next_item_size as f64 / fresh_post).min(1.0);
            if reachable < 0.5 {
                score += 18.0 * (0.5 - reachable) * (1.0 - progress);
            }
        }
        if next_item_size > 0 && fresh_post > 0.0 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 2 && fragmentation < 0.5 {
                score -= 7.0 * ((reps as f64).min(4.0) - 1.0) * (0.4 + 0.6 * (1.0 - progress));
                if rem <= 3 {
                    score -= 5.0 * (1.0 - progress);
                }
            }
        }
        if fresh_post > 0.35 * cap && remaining_frac > 0.2 && open_capacity > 4.0 * cap && fragmentation < 0.45 {
            score += 20.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        if remaining_frac < 0.15 && fresh_post > 0.3 * cap {
            let est_need = (remaining as f64) * (item_size as f64) * 0.35;
            if open_capacity > est_need {
                score += 55.0 * (1.0 - remaining_frac / 0.15);
            }
        }
        if remaining_frac >= 0.15 && remaining_frac < 0.45 && fresh_post > 0.4 * cap && fragmentation > 0.4 {
            let est_need = (remaining as f64) * (item_size as f64) * 0.45;
            if open_capacity > est_need {
                score += 28.0 * (1.0 - remaining_frac / 0.45);
            }
        }
        if remaining_frac >= 0.05 && fresh_post > 0.3 * cap && next_item_size > 0 {
            let est_need = (remaining as f64) * (next_item_size as f64) * 0.42;
            if open_capacity > 1.15 * est_need {
                score += 30.0 * (1.0 - remaining_frac) * (fresh_post / cap - 0.3);
            }
        }
        if fresh_post > 0.35 * cap && next_item_size > 0 && (fresh_post as u32) < next_item_size && fragmentation < 0.4 && remaining_frac > 0.15 {
            score += 16.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        if next_item_size > 1 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 3 && rem == 0 && fragmentation < 0.3 {
                score -= 14.0 * ((reps as f64).min(5.0) - 2.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        if next_item_size > 0 && fresh_post > next_item_size as f64 {
            let tail = fresh_post - next_item_size as f64;
            if tail > 0.0 && tail <= 4.0 && fitting_bins_count > 1 {
                score -= 10.0 * (1.0 - tail / 4.0) * (1.0 - progress);
            }
        }
        if next_item_size > 0 && fresh_post > 0.4 * cap && (fresh_post as u32) < next_item_size
            && open_capacity > 2.0 * cap && remaining_frac > 0.25 {
            score += 22.0 * (fresh_post / cap - 0.4) * (1.0 - progress);
        }
        // gen 94: fresh-bin exact-closure bonus.
        if next_item_size > 0 && (fresh_post as u32) == next_item_size && fragmentation <= 0.3 {
            score -= 18.0 * (0.4 + 0.6 * (1.0 - progress));
        }
        // gen 94: fresh-bin strand guard.
        if next_item_size > 0 && fresh_post > 0.3 * cap && (fresh_post as u32) < next_item_size
            && (mean_residual as u32) >= next_item_size && fitting_bins_count > 1 && remaining_frac > 0.1 {
            score += 14.0 * (fresh_post / cap - 0.3) * (1.0 - progress);
        }
        // gen 102: fresh-bin mid-gap refusal.
        if next_item_size > 0 && fresh_post > 12.0 && fresh_post <= 24.0 && fitting_bins_count > 1 {
            let mid = (fresh_post - 12.0) / 12.0;
            score += 7.0 * mid * (0.35 + 0.65 * progress);
        }
        // gen 102: fresh-bin residual-harmony bonus.
        if fresh_post > 0.0 && fresh_match < 0.08 && remaining_frac > 0.1 {
            score -= 10.0 * (1.0 - fresh_match / 0.08) * (0.4 + 0.6 * (1.0 - progress));
        }
        // MUTATION (gen 110): fresh-bin late exact-closure amplifier.
        if progress > 0.75 && next_item_size > 0 && (fresh_post as u32) >= next_item_size {
            let tail = (fresh_post as u32 - next_item_size) as f64;
            if tail <= 2.0 {
                score -= 20.0 * (1.0 - tail / 2.0) * (progress - 0.75) / 0.25;
            }
        }
        // MUTATION (gen 110): demand-scaled open throttle.
        if remaining_frac < 0.3 && fresh_post > 0.25 * cap {
            let est_need = (remaining as f64) * (item_size as f64) * 0.5;
            if open_capacity > 1.3 * est_need {
                score += 24.0 * (open_capacity / (1.3 * est_need)).min(2.0) * (1.0 - remaining_frac / 0.3);
            }
        }
        // MUTATION (gen 129): fresh-bin tiling-lane guard — when the fresh
        // bin's post-residual is an exact multiple of the next item with
        // two or more reps and fragmentation is low, deepen the open reward
        // so the new bin serves as a dedicated tiling lane rather than
        // scattering slack (combats dead-space ratio weakness).
        if next_item_size > 1 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 2 && rem == 0 && fragmentation < 0.35 && remaining_frac > 0.1 {
                score -= 9.0 * ((reps as f64).min(4.0) - 1.0) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: the smaller the post residual relative to capacity, the better.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 25.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Penalize creating dead space that nothing (>= min size 1... practically next item) can use.
    if next_item_size > 0 && post_residual > 0 {
        if (next_item_size as u32) > post_residual {
            score += 12.0; // dead space for the known next item
        } else {
            score -= 8.0; // next item can slot in cleanly
        }
        // Extra reward if post residual exactly matches next item.
        if next_item_size as u32 == post_residual {
            score -= 20.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless the fit elsewhere is terrible.
    if bin_residual == bin_capacity {
        score += 55.0;
        // Early in the stream, new bins are cheap; later, prefer consolidation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * progress;
        // If item is small, keep it out of fresh bins.
        if item_size < 30 {
            score += 20.0;
        }
    }

    // Prefer filling bins whose residual is already below average (they are the "small" ones).
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score -= 0.15 * diff;
    }

    // Slight penalty when many bins are open: encourage consolidation.
    score += 0.5 * open_bins_count as f64;

    // Penalize very large leftovers in existing bins (waste potential).
    if post_residual > 50 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Layered dead-space rewards (lower post_residual = better).
    if post_residual == 0 {
        score -= 250.0;
    } else if post_residual <= 4 {
        score -= 250.0 + 4.2 * (4 - post_residual) as f64;
    } else if post_residual <= 10 {
        score -= 64.0 + 3.6 * (10 - post_residual) as f64;
    } else if post_residual <= 22 {
        score -= 13.5 + 1.5 * (22 - post_residual) as f64;
    } else if post_residual <= 32 {
        score -= 5.0 + 0.7 * (32 - post_residual) as f64;
    } else if post_residual <= 48 {
        score -= 1.2 + 0.22 * (48 - post_residual) as f64;
    } else {
        score -= 1.2 - 0.014 * (post_residual as f64 - 48.0);
    }

    let w = 0.33 + 0.67 * progress * progress;
    score *= w;

    // Lookahead coupling with the next item.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if next_item_size < post_residual {
            let two_step_waste = (post_residual - next_item_size) as f64;
            if two_step_waste <= 8.0 {
                score -= 135.0 - 2.3 * two_step_waste;
            } else {
                score -= 72.0 - 0.58 * two_step_waste;
            }
            if two_step_waste <= 3.0 {
                score -= 48.0;
            }
        } else {
            let miss = (next_item_size - post_residual) as f64;
            score += 0.95 * miss;
            if miss > 26.0 {
                score += 0.55 * (miss - 26.0);
            }
        }
    }

    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
        let boost = 36.0 + 26.0 * scarcity;
        score -= boost * (1.0 - slack / cap) * (0.6 + 0.4 * (1.0 - progress));
        if fitting_bins_count <= 2 {
            score -= 15.0 * (1.0 - slack / cap);
        }
        if slack == 0.0 {
            score -= 20.0 * (1.0 - progress);
        }
    }

    if bin_residual != bin_capacity {
        let dead = (bin_residual - item_size) as f64;
        let dead_ratio = dead / cap;
        if dead_ratio > 0.5 && fitting_bins_count > 1 {
            score += 10.5 * (dead_ratio - 0.5) * (1.0 - progress);
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
            && mean_residual > 0.0 && (mean_residual as u32) >= next_item_size {
            score += 12.0;
        }
        if post_residual > 12 && post_residual < 40 && next_item_size > post_residual {
            let orphan = (post_residual as f64 - 12.0) / 28.0;
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            score += 17.0 * orphan * scarcity * (0.5 + 0.5 * (1.0 - progress));
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let chain = post_residual % next_item_size.max(1);
            if chain == 0 {
                score -= 26.0 * (1.0 - progress);
            } else if chain <= 3 {
                score -= 11.0 * (1.0 - progress);
            }
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            let stranded = (next_item_size - post_residual) as f64;
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            if stranded <= 10.0 {
                score += (8.5 + 1.1 * (10.0 - stranded)) * scarcity * (0.4 + 0.6 * (1.0 - progress));
            } else {
                let proximity = 1.0 - (stranded - 10.0).min(cap) / cap;
                score += 3.2 * proximity * scarcity * (1.0 - progress);
            }
        }
        if dead_ratio > 0.35 && fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score += 7.5 * (dead_ratio - 0.35) * tightness * (1.0 - progress);
        }
        if post_residual > 0 && mean_residual > 0.0 {
            let gap = mean_residual - post_residual as f64;
            if gap > 0.0 && gap < 0.15 * cap && fitting_bins_count > 2 {
                score += 4.8 * (gap / (0.15 * cap)) * (1.0 - progress);
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size.max(1) && fitting_bins_count > 2 {
            score -= 6.5 * (1.0 - progress);
        }
        if post_residual == 0 && bin_residual < bin_capacity {
            score -= 42.0 * (1.0 - bin_residual as f64 / cap) * (1.0 - progress);
        }
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 1 {
            let harmony = (post_residual as f64 - mean_residual).abs() / cap;
            if harmony < 0.08 {
                score -= 9.0 * (1.0 - harmony / 0.08) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        if post_residual > 6 && post_residual <= 30 && next_item_size > 0 && next_item_size <= post_residual {
            let reps = post_residual / next_item_size.max(1);
            if reps >= 2 {
                score -= 3.5 * (reps as f64).min(4.0) * (1.0 - progress);
            }
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let after_next = post_residual - next_item_size;
            if after_next > 0 && after_next <= 12 {
                let tail = after_next as f64;
                score -= (14.0 - 0.9 * tail) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        if post_residual > 0 && post_residual < 6 && next_item_size > post_residual {
            score += 6.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let after_next = (post_residual - next_item_size) as f64;
            if after_next > 8.0 && after_next <= 16.0 && progress < 0.85 {
                let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
                score -= (4.0 + 3.0 * scarcity) * (1.0 - (after_next - 8.0) / 8.0) * (1.0 - progress);
            }
        }
        if post_residual > 0 && next_item_size > 0 && fitting_bins_count > 3 {
            let overshoot = post_residual.saturating_sub(next_item_size) as f64;
            if overshoot > 16.0 {
                score += 1.6 * ((overshoot - 16.0) / cap).min(0.25) * (1.0 - progress);
            }
        }
        if fitting_bins_count > 1 && dead_ratio > 0.08 && post_residual > 0 {
            let scarcity = 1.0 / (fitting_bins_count as f64);
            let comp_slack = (mean_residual / cap).min(1.0);
            score += 6.5 * (dead_ratio - 0.08) * scarcity * comp_slack * (0.5 + 0.5 * (1.0 - progress));
            score += 2.2 * (dead / cap) * scarcity * comp_slack * (1.0 - progress);
        }
        if fitting_bins_count > 2 && post_residual > 0 && mean_residual > 0.0 {
            let dev = ((post_residual as f64 - mean_residual).abs() / cap).min(0.4);
            score += 5.0 * dev * (1.0 - progress);
        }
        if post_residual > 0 && post_residual % 10 == 0 && post_residual <= 60 && next_item_size > 0 && next_item_size <= post_residual {
            score -= 4.0 * (1.0 - progress) * (1.0 - post_residual as f64 / 120.0);
        }
        if next_item_size > 0 && post_residual == next_item_size && fitting_bins_count <= 3 {
            score -= 30.0 / fitting_bins_count.max(1) as f64 * (0.5 + 0.5 * (1.0 - progress));
        }
        if post_residual > 0 && next_item_size > 0 && fitting_bins_count > 1 {
            let usable = next_item_size <= post_residual
                || (mean_residual as u32) >= next_item_size;
            if !usable {
                let waste_frac = post_residual as f64 / cap;
                let late = 0.35 + 0.65 * progress;
                score += 9.0 * waste_frac * late;
            }
        }
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 2 {
            let rel = post_residual as f64 / (mean_residual + 1.0);
            if rel < 0.5 {
                score -= 6.0 * (1.0 - rel / 0.5) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        if post_residual > 0 && next_item_size > 1 && next_item_size <= post_residual {
            let reps = post_residual / next_item_size;
            let rem = post_residual % next_item_size;
            if reps >= 1 && rem == 0 {
                let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
                score -= (5.0 + 6.0 * scarcity) * ((reps as f64).min(3.0)) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 1 && progress > 0.25 {
            let target = 0.5 * (mean_residual + 0.5 * cap);
            let dev = ((post_residual as f64 - target).abs() / cap).min(0.5);
            score += 2.4 * dev * (progress - 0.25);
        }
        // gen 76: near-full chain extension.
        if post_residual > 0 && next_item_size > 0 && post_residual > next_item_size {
            let after_next = post_residual - next_item_size;
            if after_next > 0 && after_next < 6 && progress > 0.35 {
                score -= 11.0 * (1.0 - after_next as f64 / 6.0) * (progress - 0.35);
            }
        }
        // gen 76: usable-residual scarcity bonus.
        if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count == 1 && bin_residual != bin_capacity {
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score -= 14.0 * (1.0 - progress) * (0.6 + 0.4 * tightness);
        }
        // gen 81: dead-space compaction gradient (refined gen 129: widen the
        // open-space trigger to 1.75x cap and sharpen the penalty slope so
        // residual variance shrinks faster mid-stream).
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
            && fitting_bins_count > 1 {
            let open_space = mean_residual * open_bins_count as f64;
            if open_space > 1.75 * cap {
                let frac = post_residual as f64 / next_item_size as f64;
                score += 13.0 * (1.0 - frac) * (0.5 + 0.5 * progress);
            }
        }
        // gen 81: consolidation pull (refined gen 129: also reward bins whose
        // post-residual is an exact small multiple of the next item, since
        // tileable residuals are the main driver of low waste).
        if post_residual > 0 && fitting_bins_count > 2 && progress > 0.45 {
            let fill = 1.0 - post_residual as f64 / cap;
            score -= 6.5 * fill * (progress - 0.45);
        }
        // MUTATION (gen 129): residual-variance dampener — prefer placements
        // whose post-residual sits close to the fleet mean residual, but only
        // when the mean is small enough to be a genuinely compactable target.
        // This directly attacks the diagnosed Sigma_res weakness.
        if post_residual > 0 && mean_residual > 0.0 && open_bins_count > 2 {
            let mean_small = mean_residual < 0.35 * cap;
            if mean_small {
                let dev = (post_residual as f64 - mean_residual).abs() / cap;
                let late = 0.4 + 0.6 * progress;
                score -= 8.0 * (0.35 * cap - mean_residual) / (0.35 * cap) * (1.0 - dev).max(0.0) * late;
            }
        }
        // MUTATION (gen 129): two-step exact-fill lookahead — when placing
        // here leaves exactly enough room for the next item AND the item
        // after that could still fit the remainder, this bin is on a perfect
        // fill trajectory; reward it more when fitting bins are scarce.
        if next_item_size > 0 && post_residual >= next_item_size && post_residual > 0 {
            let after_next = post_residual - next_item_size;
            if after_next > 0 && fitting_bins_count <= 4 {
                let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
                let tight = 1.0 - (after_next as f64 / cap);
                score -= 9.0 * scarcity * tight * (0.5 + 0.5 * (1.0 - progress));
            }
        }
    } else {
        let fragmentation = (mean_residual / cap) * open_bins_count as f64;
        let huge_item = item_size as f64 > 0.7 * cap;
        let remaining = if total_items > step_index { total_items - step_index } else { 1 };
        let remaining_frac = remaining as f64 / total_items.max(1) as f64;
        let fresh_post = cap - item_size as f64;
        let fresh_is_exact = fresh_post <= 4.0 && fresh_post >= 0.0;

        if fragmentation > 0.55 || (huge_item && open_bins_count > 4) {
            score -= 66.0 + 46.0 * remaining_frac;
        } else if fresh_is_exact {
            score -= 134.0 + 66.0 * remaining_frac;
        } else {
            score += 400.0 - 82.0 * remaining_frac;
            if fitting_bins_count <= 3 && open_bins_count > 2 {
                score -= 30.0 + 18.0 * remaining_frac;
            }
        }

        let fresh_match = (fresh_post - mean_residual).abs() / cap;
        if fresh_match < 0.05 {
            score -= 76.0 * (1.0 - fresh_match / 0.05);
        }
        if remaining_frac < 0.05 && fresh_post > 0.0 && !fresh_is_exact {
            score += 160.0 * (fresh_post / cap);
        }
        if fresh_post > 0.0 && fresh_post <= 22.0 && !fresh_is_exact {
            score -= 26.0 * (1.0 - fresh_post / 22.0);
        }
        if fresh_post > 22.0 && fresh_post <= 40.0 && fragmentation < 0.35 {
            score -= 12.5 * (1.0 - (fresh_post - 22.0) / 18.0);
        }
        if fresh_post > 0.0 && fresh_match < 0.12 && fragmentation < 0.55 {
            score -= 30.0 * (1.0 - fresh_match / 0.12);
        }
        if next_item_size > 0 && fresh_post > 0.0 {
            let fresh_exact_next = (fresh_post as u32) == next_item_size;
            let open_can_next = mean_residual >= next_item_size as f64;
            if fresh_exact_next && !open_can_next && fitting_bins_count <= 2 {
                score -= 52.0 * (1.0 - progress);
            }
            if (fresh_post as u32) < next_item_size && mean_residual > next_item_size as f64 {
                score += 21.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && fresh_post > next_item_size as f64 {
            let chain_post = fresh_post - next_item_size as f64;
            if chain_post <= 4.0 {
                score -= 34.0 * (1.0 - chain_post / 4.0) * (0.5 + 0.5 * (1.0 - progress));
            } else if chain_post <= 10.0 {
                score -= 9.5 * (1.0 - (chain_post - 4.0) / 6.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        if remaining_frac < 0.12 && fresh_post > 0.0 && !fresh_is_exact && mean_residual * open_bins_count as f64 > 3.0 * cap {
            score += 42.0 * (1.0 - remaining_frac / 0.12);
        }
        if fitting_bins_count == 1 && fresh_post > 0.0 && next_item_size > 0 {
            let stranded_here = bin_capacity.saturating_sub(item_size);
            let would_strand = stranded_here < next_item_size;
            if would_strand && stranded_here > 0 && stranded_here <= 8 {
                score -= 32.0 * (1.0 - progress);
            }
        }
        let open_capacity = mean_residual * open_bins_count as f64;
        let per_item_need = cap * 0.5;
        if remaining_frac > 0.25 && open_capacity < per_item_need * open_bins_count.max(1) as f64 * 0.5 {
            score -= 18.0 * (1.0 - progress);
        }
        if next_item_size > 0 && fresh_post > next_item_size as f64 {
            let after_next = fresh_post - next_item_size as f64;
            if after_next > 0.0 && after_next <= 8.0 && fragmentation < 0.5 {
                score -= 20.0 * (1.0 - after_next / 8.0) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        if next_item_size > 0 && fresh_post > 0.0 && (fresh_post as u32) < next_item_size {
            let slack_total = mean_residual * open_bins_count as f64;
            if slack_total > 2.0 * cap {
                score += 26.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && (fresh_post as u32) == next_item_size && fragmentation > 0.3 {
            score -= 44.0 * (0.5 + 0.5 * (1.0 - progress));
        }
        if fresh_post > 0.5 * cap && mean_residual < 0.2 * cap && remaining_frac > 0.3 && open_bins_count > 3 {
            score += 24.0 * (fresh_post / cap - 0.5) * 2.0 * (1.0 - progress);
        }
        if fitting_bins_count <= 1 && fresh_post > 0.45 * cap && next_item_size > 0 {
            let reachable = (next_item_size as f64 / fresh_post).min(1.0);
            if reachable < 0.5 {
                score += 18.0 * (0.5 - reachable) * (1.0 - progress);
            }
        }
        if next_item_size > 0 && fresh_post > 0.0 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 2 && fragmentation < 0.5 {
                score -= 7.0 * ((reps as f64).min(4.0) - 1.0) * (0.4 + 0.6 * (1.0 - progress));
                if rem <= 3 {
                    score -= 5.0 * (1.0 - progress);
                }
            }
        }
        if fresh_post > 0.35 * cap && remaining_frac > 0.2 && mean_residual * open_bins_count as f64 > 4.0 * cap && fragmentation < 0.45 {
            score += 20.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        if remaining_frac < 0.15 && fresh_post > 0.3 * cap {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.35;
            if open_space > est_need {
                score += 55.0 * (1.0 - remaining_frac / 0.15);
            }
        }
        if remaining_frac >= 0.15 && remaining_frac < 0.45 && fresh_post > 0.4 * cap && fragmentation > 0.4 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.45;
            if open_space > est_need {
                score += 28.0 * (1.0 - remaining_frac / 0.45);
            }
        }
        if next_item_size > 1 && fresh_post > 0.0 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 2 && rem == 0 && fragmentation < 0.4 {
                score -= 10.0 * ((reps as f64).min(4.0) - 1.0) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        if remaining_frac >= 0.45 && remaining_frac < 0.5 && fresh_post > 0.45 * cap && fragmentation > 0.5 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.55;
            if open_space > est_need {
                score += 22.0 * (1.0 - remaining_frac / 0.5);
            }
        }
        // gen 76: demand-aware fresh-bin refusal.
        if remaining_frac >= 0.05 && fresh_post > 0.3 * cap && next_item_size > 0 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (next_item_size as f64) * 0.42;
            if open_space > 1.15 * est_need {
                score += 30.0 * (1.0 - remaining_frac) * (fresh_post / cap - 0.3);
            }
        }
        // gen 76: fresh-bin dead-space cap.
        if fresh_post > 0.35 * cap && next_item_size > 0 && (fresh_post as u32) < next_item_size && fragmentation < 0.4 && remaining_frac > 0.15 {
            score += 16.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        // gen 81: tileability-aware open.
        if next_item_size > 1 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 3 && rem == 0 && fragmentation < 0.3 {
                score -= 14.0 * ((reps as f64).min(5.0) - 2.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // MUTATION (gen 129): variance-aware open — when the fresh bin's
        // post-residual is close to the fleet mean residual, opening it
        // creates a homogeneous residual pool that later items can tile
        // across many bins; reward this when fragmentation is moderate.
        if fresh_post > 0.0 && mean_residual > 0.0 && open_bins_count > 2 && remaining_frac > 0.1 {
            let dev = (fresh_post - mean_residual).abs() / cap;
            if dev < 0.1 {
                score -= 18.0 * (1.0 - dev / 0.1) * (0.5 + 0.5 * progress);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = norm_pr * (1.0 + 0.9 * progress * progress);
    // Penalize residual that is too small to matter (dead space), reward tight fits
    let tight = 1.0 - (pr / item_size.max(1) as f64).min(1.0);
    score -= 0.35 * tight * (1.0 - progress);
    // Coupling with mean residual: avoid bins far from the mean early on
    score += 0.12 * ((pr - mean_residual) / cap).abs() * (1.0 - progress);
    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 0.8;
    }
    // Lookahead: penalize if post_residual cannot fit next item
    if next_item_size > 0 {
        let fits_next = if pr >= next_item_size as f64 { 1.0 } else { 0.0 };
        score -= 0.25 * fits_next * (1.0 - progress);
    }
    // Mild penalty for opening new bins as stream progresses
    if bin_residual == bin_capacity {
        score += 0.15 + 0.5 * progress;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Layered dead-space rewards (lower post_residual = better).
    if post_residual == 0 {
        score -= 250.0;
    } else if post_residual <= 4 {
        score -= 250.0 + 4.2 * (4 - post_residual) as f64;
    } else if post_residual <= 10 {
        score -= 64.0 + 3.6 * (10 - post_residual) as f64;
    } else if post_residual <= 22 {
        score -= 13.5 + 1.5 * (22 - post_residual) as f64;
    } else if post_residual <= 32 {
        score -= 5.0 + 0.7 * (32 - post_residual) as f64;
    } else if post_residual <= 48 {
        score -= 1.2 + 0.22 * (48 - post_residual) as f64;
    } else {
        score -= 1.2 - 0.014 * (post_residual as f64 - 48.0);
    }

    let w = 0.33 + 0.67 * progress * progress;
    score *= w;

    // Lookahead coupling with the next item.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if next_item_size < post_residual {
            let two_step_waste = (post_residual - next_item_size) as f64;
            if two_step_waste <= 8.0 {
                score -= 135.0 - 2.3 * two_step_waste;
            } else {
                score -= 72.0 - 0.58 * two_step_waste;
            }
            if two_step_waste <= 3.0 {
                score -= 48.0;
            }
        } else {
            let miss = (next_item_size - post_residual) as f64;
            score += 0.95 * miss;
            if miss > 26.0 {
                score += 0.55 * (miss - 26.0);
            }
        }
    }

    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
        let boost = 36.0 + 26.0 * scarcity;
        score -= boost * (1.0 - slack / cap) * (0.6 + 0.4 * (1.0 - progress));
        if fitting_bins_count <= 2 {
            score -= 15.0 * (1.0 - slack / cap);
        }
        if slack == 0.0 {
            score -= 20.0 * (1.0 - progress);
        }
    }

    if bin_residual != bin_capacity {
        let dead = (bin_residual - item_size) as f64;
        let dead_ratio = dead / cap;
        if dead_ratio > 0.5 && fitting_bins_count > 1 {
            score += 10.5 * (dead_ratio - 0.5) * (1.0 - progress);
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
            && mean_residual > 0.0 && (mean_residual as u32) >= next_item_size {
            score += 12.0;
        }
        if post_residual > 12 && post_residual < 40 && next_item_size > post_residual {
            let orphan = (post_residual as f64 - 12.0) / 28.0;
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            score += 17.0 * orphan * scarcity * (0.5 + 0.5 * (1.0 - progress));
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let chain = post_residual % next_item_size.max(1);
            if chain == 0 {
                score -= 26.0 * (1.0 - progress);
            } else if chain <= 3 {
                score -= 11.0 * (1.0 - progress);
            }
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            let stranded = (next_item_size - post_residual) as f64;
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            if stranded <= 10.0 {
                score += (8.5 + 1.1 * (10.0 - stranded)) * scarcity * (0.4 + 0.6 * (1.0 - progress));
            } else {
                let proximity = 1.0 - (stranded - 10.0).min(cap) / cap;
                score += 3.2 * proximity * scarcity * (1.0 - progress);
            }
        }
        if dead_ratio > 0.35 && fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score += 7.5 * (dead_ratio - 0.35) * tightness * (1.0 - progress);
        }
        if post_residual > 0 && mean_residual > 0.0 {
            let gap = mean_residual - post_residual as f64;
            if gap > 0.0 && gap < 0.15 * cap && fitting_bins_count > 2 {
                score += 4.8 * (gap / (0.15 * cap)) * (1.0 - progress);
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size.max(1) && fitting_bins_count > 2 {
            score -= 6.5 * (1.0 - progress);
        }
        if post_residual == 0 && bin_residual < bin_capacity {
            score -= 42.0 * (1.0 - bin_residual as f64 / cap) * (1.0 - progress);
        }
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 1 {
            let harmony = (post_residual as f64 - mean_residual).abs() / cap;
            if harmony < 0.08 {
                score -= 9.0 * (1.0 - harmony / 0.08) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        if post_residual > 6 && post_residual <= 30 && next_item_size > 0 && next_item_size <= post_residual {
            let reps = post_residual / next_item_size.max(1);
            if reps >= 2 {
                score -= 3.5 * (reps as f64).min(4.0) * (1.0 - progress);
            }
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let after_next = post_residual - next_item_size;
            if after_next > 0 && after_next <= 12 {
                let tail = after_next as f64;
                score -= (14.0 - 0.9 * tail) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        if post_residual > 0 && post_residual < 6 && next_item_size > post_residual {
            score += 6.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let after_next = (post_residual - next_item_size) as f64;
            if after_next > 8.0 && after_next <= 16.0 && progress < 0.85 {
                let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
                score -= (4.0 + 3.0 * scarcity) * (1.0 - (after_next - 8.0) / 8.0) * (1.0 - progress);
            }
        }
        if post_residual > 0 && next_item_size > 0 && fitting_bins_count > 3 {
            let overshoot = post_residual.saturating_sub(next_item_size) as f64;
            if overshoot > 16.0 {
                score += 1.6 * ((overshoot - 16.0) / cap).min(0.25) * (1.0 - progress);
            }
        }
        if fitting_bins_count > 1 && dead_ratio > 0.08 && post_residual > 0 {
            let scarcity = 1.0 / (fitting_bins_count as f64);
            let comp_slack = (mean_residual / cap).min(1.0);
            score += 6.5 * (dead_ratio - 0.08) * scarcity * comp_slack * (0.5 + 0.5 * (1.0 - progress));
            score += 2.2 * (dead / cap) * scarcity * comp_slack * (1.0 - progress);
        }
        if fitting_bins_count > 2 && post_residual > 0 && mean_residual > 0.0 {
            let dev = ((post_residual as f64 - mean_residual).abs() / cap).min(0.4);
            score += 5.0 * dev * (1.0 - progress);
        }
        if post_residual > 0 && post_residual % 10 == 0 && post_residual <= 60 && next_item_size > 0 && next_item_size <= post_residual {
            score -= 4.0 * (1.0 - progress) * (1.0 - post_residual as f64 / 120.0);
        }
        if next_item_size > 0 && post_residual == next_item_size && fitting_bins_count <= 3 {
            score -= 30.0 / fitting_bins_count.max(1) as f64 * (0.5 + 0.5 * (1.0 - progress));
        }
        if post_residual > 0 && next_item_size > 0 && fitting_bins_count > 1 {
            let usable = next_item_size <= post_residual
                || (mean_residual as u32) >= next_item_size;
            if !usable {
                let waste_frac = post_residual as f64 / cap;
                let late = 0.35 + 0.65 * progress;
                score += 9.0 * waste_frac * late;
            }
        }
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 2 {
            let rel = post_residual as f64 / (mean_residual + 1.0);
            if rel < 0.5 {
                score -= 6.0 * (1.0 - rel / 0.5) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        if post_residual > 0 && next_item_size > 1 && next_item_size <= post_residual {
            let reps = post_residual / next_item_size;
            let rem = post_residual % next_item_size;
            if reps >= 1 && rem == 0 {
                let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
                score -= (5.0 + 6.0 * scarcity) * ((reps as f64).min(3.0)) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 1 && progress > 0.25 {
            let target = 0.5 * (mean_residual + 0.5 * cap);
            let dev = ((post_residual as f64 - target).abs() / cap).min(0.5);
            score += 2.4 * dev * (progress - 0.25);
        }
        // gen 76: near-full chain extension (refined: widen to after_next < 6
        // and extend earlier into the stream since residual variance is the
        // diagnosed weakness).
        if post_residual > 0 && next_item_size > 0 && post_residual > next_item_size {
            let after_next = post_residual - next_item_size;
            if after_next > 0 && after_next < 6 && progress > 0.35 {
                score -= 11.0 * (1.0 - after_next as f64 / 6.0) * (progress - 0.35);
            }
        }
        // gen 76: usable-residual scarcity bonus (refined: scale with how
        // close the post-residual is to the next item, favoring tight reuse).
        if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count == 1 && bin_residual != bin_capacity {
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score -= 14.0 * (1.0 - progress) * (0.6 + 0.4 * tightness);
        }
        // gen 81: dead-space compaction gradient.
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
            && fitting_bins_count > 1 {
            let open_space = mean_residual * open_bins_count as f64;
            if open_space > 2.0 * cap {
                let frac = post_residual as f64 / next_item_size as f64;
                score += 10.0 * (1.0 - frac) * (0.5 + 0.5 * progress);
            }
        }
        // gen 81: consolidation pull.
        if post_residual > 0 && fitting_bins_count > 2 && progress > 0.5 {
            let fill = 1.0 - post_residual as f64 / cap;
            score -= 5.0 * fill * (progress - 0.5);
        }
        // MUTATION (gen 129): residual-variance squeeze — mid-range leftovers
        // (too big to be dead space, too small to tile reliably) are the main
        // source of Sigma_res; when the next item overshoots them by a small
        // margin and other bins hold slack that could absorb the next item,
        // penalize proportionally to the overshoot so residual spread
        // concentrates toward either near-full or tileable states.
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
            && fitting_bins_count > 2 {
            let overshoot = (next_item_size - post_residual) as f64;
            if overshoot <= 0.12 * cap {
                let open_space = mean_residual * open_bins_count as f64;
                if open_space > 1.5 * cap {
                    let late = 0.4 + 0.6 * progress;
                    score += 8.0 * (1.0 - overshoot / (0.12 * cap)) * late;
                }
            }
        }
        // MUTATION (gen 129): two-step tiling lookahead — when placing the
        // next item here would leave a residual that exactly fits the item
        // after it is unknowable, but a residual that is a small clean
        // multiple of the next item is far more reusable than an awkward
        // one; deepen the existing chain reward for mid-stream bins where
        // the diagnosed weakness (residual variance) is most costly.
        if post_residual > 0 && next_item_size > 1 && post_residual > next_item_size
            && fitting_bins_count > 1 && progress > 0.3 {
            let rem = post_residual % next_item_size;
            if rem > 0 && rem <= 2 {
                score -= 7.0 * (1.0 - rem as f64 / 2.0) * (progress - 0.3);
            }
        }
    } else {
        let fragmentation = (mean_residual / cap) * open_bins_count as f64;
        let huge_item = item_size as f64 > 0.7 * cap;
        let remaining = if total_items > step_index { total_items - step_index } else { 1 };
        let remaining_frac = remaining as f64 / total_items.max(1) as f64;
        let fresh_post = cap - item_size as f64;
        let fresh_is_exact = fresh_post <= 4.0 && fresh_post >= 0.0;

        if fragmentation > 0.55 || (huge_item && open_bins_count > 4) {
            score -= 66.0 + 46.0 * remaining_frac;
        } else if fresh_is_exact {
            score -= 134.0 + 66.0 * remaining_frac;
        } else {
            score += 400.0 - 82.0 * remaining_frac;
            if fitting_bins_count <= 3 && open_bins_count > 2 {
                score -= 30.0 + 18.0 * remaining_frac;
            }
        }

        let fresh_match = (fresh_post - mean_residual).abs() / cap;
        if fresh_match < 0.05 {
            score -= 76.0 * (1.0 - fresh_match / 0.05);
        }
        if remaining_frac < 0.05 && fresh_post > 0.0 && !fresh_is_exact {
            score += 160.0 * (fresh_post / cap);
        }
        if fresh_post > 0.0 && fresh_post <= 22.0 && !fresh_is_exact {
            score -= 26.0 * (1.0 - fresh_post / 22.0);
        }
        if fresh_post > 22.0 && fresh_post <= 40.0 && fragmentation < 0.35 {
            score -= 12.5 * (1.0 - (fresh_post - 22.0) / 18.0);
        }
        if fresh_post > 0.0 && fresh_match < 0.12 && fragmentation < 0.55 {
            score -= 30.0 * (1.0 - fresh_match / 0.12);
        }
        if next_item_size > 0 && fresh_post > 0.0 {
            let fresh_exact_next = (fresh_post as u32) == next_item_size;
            let open_can_next = mean_residual >= next_item_size as f64;
            if fresh_exact_next && !open_can_next && fitting_bins_count <= 2 {
                score -= 52.0 * (1.0 - progress);
            }
            if (fresh_post as u32) < next_item_size && mean_residual > next_item_size as f64 {
                score += 21.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && fresh_post > next_item_size as f64 {
            let chain_post = fresh_post - next_item_size as f64;
            if chain_post <= 4.0 {
                score -= 34.0 * (1.0 - chain_post / 4.0) * (0.5 + 0.5 * (1.0 - progress));
            } else if chain_post <= 10.0 {
                score -= 9.5 * (1.0 - (chain_post - 4.0) / 6.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        if remaining_frac < 0.12 && fresh_post > 0.0 && !fresh_is_exact && mean_residual * open_bins_count as f64 > 3.0 * cap {
            score += 42.0 * (1.0 - remaining_frac / 0.12);
        }
        if fitting_bins_count == 1 && fresh_post > 0.0 && next_item_size > 0 {
            let stranded_here = bin_capacity.saturating_sub(item_size);
            let would_strand = stranded_here < next_item_size;
            if would_strand && stranded_here > 0 && stranded_here <= 8 {
                score -= 32.0 * (1.0 - progress);
            }
        }
        let open_capacity = mean_residual * open_bins_count as f64;
        let per_item_need = cap * 0.5;
        if remaining_frac > 0.25 && open_capacity < per_item_need * open_bins_count.max(1) as f64 * 0.5 {
            score -= 18.0 * (1.0 - progress);
        }
        if next_item_size > 0 && fresh_post > next_item_size as f64 {
            let after_next = fresh_post - next_item_size as f64;
            if after_next > 0.0 && after_next <= 8.0 && fragmentation < 0.5 {
                score -= 20.0 * (1.0 - after_next / 8.0) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        if next_item_size > 0 && fresh_post > 0.0 && (fresh_post as u32) < next_item_size {
            let slack_total = mean_residual * open_bins_count as f64;
            if slack_total > 2.0 * cap {
                score += 26.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && (fresh_post as u32) == next_item_size && fragmentation > 0.3 {
            score -= 44.0 * (0.5 + 0.5 * (1.0 - progress));
        }
        if fresh_post > 0.5 * cap && mean_residual < 0.2 * cap && remaining_frac > 0.3 && open_bins_count > 3 {
            score += 24.0 * (fresh_post / cap - 0.5) * 2.0 * (1.0 - progress);
        }
        if fitting_bins_count <= 1 && fresh_post > 0.45 * cap && next_item_size > 0 {
            let reachable = (next_item_size as f64 / fresh_post).min(1.0);
            if reachable < 0.5 {
                score += 18.0 * (0.5 - reachable) * (1.0 - progress);
            }
        }
        if next_item_size > 0 && fresh_post > 0.0 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 2 && fragmentation < 0.5 {
                score -= 7.0 * ((reps as f64).min(4.0) - 1.0) * (0.4 + 0.6 * (1.0 - progress));
                if rem <= 3 {
                    score -= 5.0 * (1.0 - progress);
                }
            }
        }
        if fresh_post > 0.35 * cap && remaining_frac > 0.2 && mean_residual * open_bins_count as f64 > 4.0 * cap && fragmentation < 0.45 {
            score += 20.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        if remaining_frac < 0.15 && fresh_post > 0.3 * cap {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.35;
            if open_space > est_need {
                score += 55.0 * (1.0 - remaining_frac / 0.15);
            }
        }
        if remaining_frac >= 0.15 && remaining_frac < 0.45 && fresh_post > 0.4 * cap && fragmentation > 0.4 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.45;
            if open_space > est_need {
                score += 28.0 * (1.0 - remaining_frac / 0.45);
            }
        }
        if next_item_size > 1 && fresh_post > 0.0 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 2 && rem == 0 && fragmentation < 0.4 {
                score -= 10.0 * ((reps as f64).min(4.0) - 1.0) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        if remaining_frac >= 0.45 && remaining_frac < 0.5 && fresh_post > 0.45 * cap && fragmentation > 0.5 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.55;
            if open_space > est_need {
                score += 22.0 * (1.0 - remaining_frac / 0.5);
            }
        }
        // gen 76: demand-aware fresh-bin refusal.
        if remaining_frac >= 0.05 && fresh_post > 0.3 * cap && next_item_size > 0 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (next_item_size as f64) * 0.42;
            if open_space > 1.15 * est_need {
                score += 30.0 * (1.0 - remaining_frac) * (fresh_post / cap - 0.3);
            }
        }
        // gen 76: fresh-bin dead-space cap.
        if fresh_post > 0.35 * cap && next_item_size > 0 && (fresh_post as u32) < next_item_size && fragmentation < 0.4 && remaining_frac > 0.15 {
            score += 16.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        // gen 81: tileability-aware open.
        if next_item_size > 1 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 3 && rem == 0 && fragmentation < 0.3 {
                score -= 14.0 * ((reps as f64).min(5.0) - 2.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // MUTATION (gen 129): fresh-bin variance alignment — when the fresh
        // post-residual sits close to the current mean residual of open
        // bins, opening here homogenizes residual spread (lowers Sigma_res)
        // and preserves future tileability; reward mildly, strongest early
        // when the layout is still malleable.
        if fresh_post > 0.0 && !fresh_is_exact && open_bins_count > 2 && remaining_frac > 0.2 {
            let align = 1.0 - fresh_match / 0.2;
            if align > 0.0 && fragmentation < 0.5 {
                score -= 9.0 * align * (1.0 - progress);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Layered dead-space rewards (lower post_residual = better).
    if post_residual == 0 {
        score -= 250.0;
    } else if post_residual <= 4 {
        score -= 250.0 + 4.2 * (4 - post_residual) as f64;
    } else if post_residual <= 10 {
        score -= 64.0 + 3.6 * (10 - post_residual) as f64;
    } else if post_residual <= 22 {
        score -= 13.5 + 1.5 * (22 - post_residual) as f64;
    } else if post_residual <= 32 {
        score -= 5.0 + 0.7 * (32 - post_residual) as f64;
    } else if post_residual <= 48 {
        score -= 1.2 + 0.22 * (48 - post_residual) as f64;
    } else {
        score -= 1.2 - 0.014 * (post_residual as f64 - 48.0);
    }

    let w = 0.33 + 0.67 * progress * progress;
    score *= w;

    // Lookahead coupling with the next item.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if next_item_size < post_residual {
            let two_step_waste = (post_residual - next_item_size) as f64;
            if two_step_waste <= 8.0 {
                score -= 135.0 - 2.3 * two_step_waste;
            } else {
                score -= 72.0 - 0.58 * two_step_waste;
            }
            if two_step_waste <= 3.0 {
                score -= 48.0;
            }
        } else {
            let miss = (next_item_size - post_residual) as f64;
            score += 0.95 * miss;
            if miss > 26.0 {
                score += 0.55 * (miss - 26.0);
            }
        }
    }

    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
        let boost = 36.0 + 26.0 * scarcity;
        score -= boost * (1.0 - slack / cap) * (0.6 + 0.4 * (1.0 - progress));
        if fitting_bins_count <= 2 {
            score -= 15.0 * (1.0 - slack / cap);
        }
        if slack == 0.0 {
            score -= 20.0 * (1.0 - progress);
        }
    }

    if bin_residual != bin_capacity {
        let dead = (bin_residual - item_size) as f64;
        let dead_ratio = dead / cap;
        if dead_ratio > 0.5 && fitting_bins_count > 1 {
            score += 10.5 * (dead_ratio - 0.5) * (1.0 - progress);
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
            && mean_residual > 0.0 && (mean_residual as u32) >= next_item_size {
            score += 12.0;
        }
        if post_residual > 12 && post_residual < 40 && next_item_size > post_residual {
            let orphan = (post_residual as f64 - 12.0) / 28.0;
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            score += 17.0 * orphan * scarcity * (0.5 + 0.5 * (1.0 - progress));
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let chain = post_residual % next_item_size.max(1);
            if chain == 0 {
                score -= 26.0 * (1.0 - progress);
            } else if chain <= 3 {
                score -= 11.0 * (1.0 - progress);
            }
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            let stranded = (next_item_size - post_residual) as f64;
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            if stranded <= 10.0 {
                score += (8.5 + 1.1 * (10.0 - stranded)) * scarcity * (0.4 + 0.6 * (1.0 - progress));
            } else {
                let proximity = 1.0 - (stranded - 10.0).min(cap) / cap;
                score += 3.2 * proximity * scarcity * (1.0 - progress);
            }
        }
        if dead_ratio > 0.35 && fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score += 7.5 * (dead_ratio - 0.35) * tightness * (1.0 - progress);
        }
        if post_residual > 0 && mean_residual > 0.0 {
            let gap = mean_residual - post_residual as f64;
            if gap > 0.0 && gap < 0.15 * cap && fitting_bins_count > 2 {
                score += 4.8 * (gap / (0.15 * cap)) * (1.0 - progress);
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size.max(1) && fitting_bins_count > 2 {
            score -= 6.5 * (1.0 - progress);
        }
        if post_residual == 0 && bin_residual < bin_capacity {
            score -= 42.0 * (1.0 - bin_residual as f64 / cap) * (1.0 - progress);
        }
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 1 {
            let harmony = (post_residual as f64 - mean_residual).abs() / cap;
            if harmony < 0.08 {
                score -= 9.0 * (1.0 - harmony / 0.08) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        if post_residual > 6 && post_residual <= 30 && next_item_size > 0 && next_item_size <= post_residual {
            let reps = post_residual / next_item_size.max(1);
            if reps >= 2 {
                score -= 3.5 * (reps as f64).min(4.0) * (1.0 - progress);
            }
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let after_next = post_residual - next_item_size;
            if after_next > 0 && after_next <= 12 {
                let tail = after_next as f64;
                score -= (14.0 - 0.9 * tail) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        if post_residual > 0 && post_residual < 6 && next_item_size > post_residual {
            score += 6.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let after_next = (post_residual - next_item_size) as f64;
            if after_next > 8.0 && after_next <= 16.0 && progress < 0.85 {
                let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
                score -= (4.0 + 3.0 * scarcity) * (1.0 - (after_next - 8.0) / 8.0) * (1.0 - progress);
            }
        }
        if post_residual > 0 && next_item_size > 0 && fitting_bins_count > 3 {
            let overshoot = post_residual.saturating_sub(next_item_size) as f64;
            if overshoot > 16.0 {
                score += 1.6 * ((overshoot - 16.0) / cap).min(0.25) * (1.0 - progress);
            }
        }
        if fitting_bins_count > 1 && dead_ratio > 0.08 && post_residual > 0 {
            let scarcity = 1.0 / (fitting_bins_count as f64);
            let comp_slack = (mean_residual / cap).min(1.0);
            score += 6.5 * (dead_ratio - 0.08) * scarcity * comp_slack * (0.5 + 0.5 * (1.0 - progress));
            score += 2.2 * (dead / cap) * scarcity * comp_slack * (1.0 - progress);
        }
        if fitting_bins_count > 2 && post_residual > 0 && mean_residual > 0.0 {
            let dev = ((post_residual as f64 - mean_residual).abs() / cap).min(0.4);
            score += 5.0 * dev * (1.0 - progress);
        }
        if post_residual > 0 && post_residual % 10 == 0 && post_residual <= 60 && next_item_size > 0 && next_item_size <= post_residual {
            score -= 4.0 * (1.0 - progress) * (1.0 - post_residual as f64 / 120.0);
        }
        if next_item_size > 0 && post_residual == next_item_size && fitting_bins_count <= 3 {
            score -= 30.0 / fitting_bins_count.max(1) as f64 * (0.5 + 0.5 * (1.0 - progress));
        }
        if post_residual > 0 && next_item_size > 0 && fitting_bins_count > 1 {
            let usable = next_item_size <= post_residual
                || (mean_residual as u32) >= next_item_size;
            if !usable {
                let waste_frac = post_residual as f64 / cap;
                let late = 0.35 + 0.65 * progress;
                score += 9.0 * waste_frac * late;
            }
        }
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 2 {
            let rel = post_residual as f64 / (mean_residual + 1.0);
            if rel < 0.5 {
                score -= 6.0 * (1.0 - rel / 0.5) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        if post_residual > 0 && next_item_size > 1 && next_item_size <= post_residual {
            let reps = post_residual / next_item_size;
            let rem = post_residual % next_item_size;
            if reps >= 1 && rem == 0 {
                let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
                score -= (5.0 + 6.0 * scarcity) * ((reps as f64).min(3.0)) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 1 && progress > 0.25 {
            let target = 0.5 * (mean_residual + 0.5 * cap);
            let dev = ((post_residual as f64 - target).abs() / cap).min(0.5);
            score += 2.4 * dev * (progress - 0.25);
        }
        // gen 76: near-full chain extension.
        if post_residual > 0 && next_item_size > 0 && post_residual > next_item_size {
            let after_next = post_residual - next_item_size;
            if after_next > 0 && after_next < 6 && progress > 0.35 {
                score -= 11.0 * (1.0 - after_next as f64 / 6.0) * (progress - 0.35);
            }
        }
        // gen 76: usable-residual scarcity bonus.
        if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count == 1 && bin_residual != bin_capacity {
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score -= 14.0 * (1.0 - progress) * (0.6 + 0.4 * tightness);
        }
        // gen 81: dead-space compaction gradient.
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
            && fitting_bins_count > 1 {
            let open_space = mean_residual * open_bins_count as f64;
            if open_space > 2.0 * cap {
                let frac = post_residual as f64 / next_item_size as f64;
                score += 10.0 * (1.0 - frac) * (0.5 + 0.5 * progress);
            }
        }
        // gen 81: consolidation pull.
        if post_residual > 0 && fitting_bins_count > 2 && progress > 0.5 {
            let fill = 1.0 - post_residual as f64 / cap;
            score -= 5.0 * fill * (progress - 0.5);
        }
        // MUTATION (gen 130): stranded-residual entropy guard — a placement
        // that strands a residual just barely below the next item's size
        // (1..=5 units short) is the single largest source of residual
        // variance: the gap is too small to matter for other items yet too
        // large to ignore. Penalize the near-miss band proportionally to
        // how close the miss is, weighted by open slack abundance.
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            let miss = (next_item_size - post_residual) as f64;
            if miss <= 5.0 && fitting_bins_count > 1 {
                let open_space = mean_residual * open_bins_count as f64;
                let abundance = (open_space / cap).min(3.0) / 3.0;
                score += (7.0 + 5.0 * (1.0 - miss / 5.0)) * (0.4 + 0.6 * abundance) * (0.3 + 0.7 * progress);
            }
        }
        // MUTATION (gen 130): variance-sink preference — among competing
        // bins, prefer the one whose post-residual lands closest to the
        // fleet mean, so residuals concentrate into a reusable band rather
        // than scattering. Stronger mid-stream where variance accumulates.
        if post_residual > 0 && fitting_bins_count > 2 {
            let dev = (post_residual as f64 - mean_residual).abs() / cap;
            let band = 0.10;
            if dev < band {
                score -= 8.0 * (1.0 - dev / band) * (0.35 + 0.65 * (1.0 - progress));
            }
        }
    } else {
        let fragmentation = (mean_residual / cap) * open_bins_count as f64;
        let huge_item = item_size as f64 > 0.7 * cap;
        let remaining = if total_items > step_index { total_items - step_index } else { 1 };
        let remaining_frac = remaining as f64 / total_items.max(1) as f64;
        let fresh_post = cap - item_size as f64;
        let fresh_is_exact = fresh_post <= 4.0 && fresh_post >= 0.0;

        if fragmentation > 0.55 || (huge_item && open_bins_count > 4) {
            score -= 66.0 + 46.0 * remaining_frac;
        } else if fresh_is_exact {
            score -= 134.0 + 66.0 * remaining_frac;
        } else {
            score += 400.0 - 82.0 * remaining_frac;
            if fitting_bins_count <= 3 && open_bins_count > 2 {
                score -= 30.0 + 18.0 * remaining_frac;
            }
        }

        let fresh_match = (fresh_post - mean_residual).abs() / cap;
        if fresh_match < 0.05 {
            score -= 76.0 * (1.0 - fresh_match / 0.05);
        }
        if remaining_frac < 0.05 && fresh_post > 0.0 && !fresh_is_exact {
            score += 160.0 * (fresh_post / cap);
        }
        if fresh_post > 0.0 && fresh_post <= 22.0 && !fresh_is_exact {
            score -= 26.0 * (1.0 - fresh_post / 22.0);
        }
        if fresh_post > 22.0 && fresh_post <= 40.0 && fragmentation < 0.35 {
            score -= 12.5 * (1.0 - (fresh_post - 22.0) / 18.0);
        }
        if fresh_post > 0.0 && fresh_match < 0.12 && fragmentation < 0.55 {
            score -= 30.0 * (1.0 - fresh_match / 0.12);
        }
        if next_item_size > 0 && fresh_post > 0.0 {
            let fresh_exact_next = (fresh_post as u32) == next_item_size;
            let open_can_next = mean_residual >= next_item_size as f64;
            if fresh_exact_next && !open_can_next && fitting_bins_count <= 2 {
                score -= 52.0 * (1.0 - progress);
            }
            if (fresh_post as u32) < next_item_size && mean_residual > next_item_size as f64 {
                score += 21.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && fresh_post > next_item_size as f64 {
            let chain_post = fresh_post - next_item_size as f64;
            if chain_post <= 4.0 {
                score -= 34.0 * (1.0 - chain_post / 4.0) * (0.5 + 0.5 * (1.0 - progress));
            } else if chain_post <= 10.0 {
                score -= 9.5 * (1.0 - (chain_post - 4.0) / 6.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        if remaining_frac < 0.12 && fresh_post > 0.0 && !fresh_is_exact && mean_residual * open_bins_count as f64 > 3.0 * cap {
            score += 42.0 * (1.0 - remaining_frac / 0.12);
        }
        if fitting_bins_count == 1 && fresh_post > 0.0 && next_item_size > 0 {
            let stranded_here = bin_capacity.saturating_sub(item_size);
            let would_strand = stranded_here < next_item_size;
            if would_strand && stranded_here > 0 && stranded_here <= 8 {
                score -= 32.0 * (1.0 - progress);
            }
        }
        let open_capacity = mean_residual * open_bins_count as f64;
        let per_item_need = cap * 0.5;
        if remaining_frac > 0.25 && open_capacity < per_item_need * open_bins_count.max(1) as f64 * 0.5 {
            score -= 18.0 * (1.0 - progress);
        }
        if next_item_size > 0 && fresh_post > next_item_size as f64 {
            let after_next = fresh_post - next_item_size as f64;
            if after_next > 0.0 && after_next <= 8.0 && fragmentation < 0.5 {
                score -= 20.0 * (1.0 - after_next / 8.0) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        if next_item_size > 0 && fresh_post > 0.0 && (fresh_post as u32) < next_item_size {
            let slack_total = mean_residual * open_bins_count as f64;
            if slack_total > 2.0 * cap {
                score += 26.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && (fresh_post as u32) == next_item_size && fragmentation > 0.3 {
            score -= 44.0 * (0.5 + 0.5 * (1.0 - progress));
        }
        if fresh_post > 0.5 * cap && mean_residual < 0.2 * cap && remaining_frac > 0.3 && open_bins_count > 3 {
            score += 24.0 * (fresh_post / cap - 0.5) * 2.0 * (1.0 - progress);
        }
        if fitting_bins_count <= 1 && fresh_post > 0.45 * cap && next_item_size > 0 {
            let reachable = (next_item_size as f64 / fresh_post).min(1.0);
            if reachable < 0.5 {
                score += 18.0 * (0.5 - reachable) * (1.0 - progress);
            }
        }
        if next_item_size > 0 && fresh_post > 0.0 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 2 && fragmentation < 0.5 {
                score -= 7.0 * ((reps as f64).min(4.0) - 1.0) * (0.4 + 0.6 * (1.0 - progress));
                if rem <= 3 {
                    score -= 5.0 * (1.0 - progress);
                }
            }
        }
        if fresh_post > 0.35 * cap && remaining_frac > 0.2 && mean_residual * open_bins_count as f64 > 4.0 * cap && fragmentation < 0.45 {
            score += 20.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        if remaining_frac < 0.15 && fresh_post > 0.3 * cap {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.35;
            if open_space > est_need {
                score += 55.0 * (1.0 - remaining_frac / 0.15);
            }
        }
        if remaining_frac >= 0.15 && remaining_frac < 0.45 && fresh_post > 0.4 * cap && fragmentation > 0.4 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.45;
            if open_space > est_need {
                score += 28.0 * (1.0 - remaining_frac / 0.45);
            }
        }
        if next_item_size > 1 && fresh_post > 0.0 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 2 && rem == 0 && fragmentation < 0.4 {
                score -= 10.0 * ((reps as f64).min(4.0) - 1.0) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        if remaining_frac >= 0.45 && remaining_frac < 0.5 && fresh_post > 0.45 * cap && fragmentation > 0.5 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.55;
            if open_space > est_need {
                score += 22.0 * (1.0 - remaining_frac / 0.5);
            }
        }
        // gen 76: demand-aware fresh-bin refusal.
        if remaining_frac >= 0.05 && fresh_post > 0.3 * cap && next_item_size > 0 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (next_item_size as f64) * 0.42;
            if open_space > 1.15 * est_need {
                score += 30.0 * (1.0 - remaining_frac) * (fresh_post / cap - 0.3);
            }
        }
        // gen 76: fresh-bin dead-space cap.
        if fresh_post > 0.35 * cap && next_item_size > 0 && (fresh_post as u32) < next_item_size && fragmentation < 0.4 && remaining_frac > 0.15 {
            score += 16.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        // gen 81: tileability-aware open.
        if next_item_size > 1 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 3 && rem == 0 && fragmentation < 0.3 {
                score -= 14.0 * ((reps as f64).min(5.0) - 2.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // MUTATION (gen 130): near-miss fresh-bin guard — refuse opening a
        // bin whose fresh post-residual strands 1..=5 units below the next
        // item when existing open slack can already host the next item;
        // this mirrors the stranded-residual guard on the open-bin side.
        if next_item_size > 0 && fresh_post > 0.0 && (fresh_post as u32) < next_item_size {
            let miss = next_item_size as f64 - fresh_post;
            if miss <= 5.0 && mean_residual >= next_item_size as f64 {
                score += 24.0 * (1.0 - miss / 5.0) * (0.5 + 0.5 * progress);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward small post-residuals superlinearly.
    let pr = post_residual;
    if pr == 0 {
        score -= 1000.0; // perfect fit
    } else if pr <= 5 {
        score -= 120.0;
    } else if pr <= 10 {
        score -= 60.0;
    } else if pr <= 20 {
        score -= 25.0;
    } else {
        // Dead-space penalty grows for large unusable gaps.
        score += (pr as f64) * 0.35;
    }

    // Modulo/harmonic classes: residuals that pair with common item sizes are valuable.
    let harmonic_bonus = |r: u32| -> f64 {
        let mut b = 0.0;
        for k in [10u32, 20, 25, 50, 100] {
            if r % k == 0 && r > 0 {
                b += 8.0;
            }
        }
        b
    };
    score -= harmonic_bonus(pr);

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size <= pr {
        if pr == next_item_size {
            score -= 300.0;
        } else {
            score -= 15.0 + (pr - next_item_size) as f64 * 0.5;
        }
    } else if next_item_size > pr && next_item_size > 0 {
        // Next item won't fit here; penalize wasting this bin's future.
        score += 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate handling: empty bins should only win when open bins are poor.
    if bin_residual == bin_capacity {
        score += 55.0 + open_bins_count as f64 * 2.0;
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 20.0; // big next item: fresh bin may be wise
        }
    }

    // Mild preference for filling fuller bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (bin_capacity - bin_residual) as f64 * 0.1 * (1.0 + progress);

    // Prefer compact bin sets.
    score += open_bins_count as f64 * 0.05;

    // Mean-residual coupling: if this bin is below mean residual (fuller), favor it.
    score -= (mean_residual - bin_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Layered dead-space rewards (lower post_residual = better).
    if post_residual == 0 {
        score -= 250.0;
    } else if post_residual <= 4 {
        score -= 250.0 + 4.2 * (4 - post_residual) as f64;
    } else if post_residual <= 10 {
        score -= 64.0 + 3.6 * (10 - post_residual) as f64;
    } else if post_residual <= 22 {
        score -= 13.5 + 1.5 * (22 - post_residual) as f64;
    } else if post_residual <= 32 {
        score -= 5.0 + 0.7 * (32 - post_residual) as f64;
    } else if post_residual <= 48 {
        score -= 1.2 + 0.22 * (48 - post_residual) as f64;
    } else {
        score -= 1.2 - 0.014 * (post_residual as f64 - 48.0);
    }

    let w = 0.33 + 0.67 * progress * progress;
    score *= w;

    // Lookahead coupling with the next item.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if next_item_size < post_residual {
            let two_step_waste = (post_residual - next_item_size) as f64;
            if two_step_waste <= 8.0 {
                score -= 135.0 - 2.3 * two_step_waste;
            } else {
                score -= 72.0 - 0.58 * two_step_waste;
            }
            if two_step_waste <= 3.0 {
                score -= 48.0;
            }
        } else {
            let miss = (next_item_size - post_residual) as f64;
            score += 0.95 * miss;
            if miss > 26.0 {
                score += 0.55 * (miss - 26.0);
            }
        }
    }

    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
        let boost = 36.0 + 26.0 * scarcity;
        score -= boost * (1.0 - slack / cap) * (0.6 + 0.4 * (1.0 - progress));
        if fitting_bins_count <= 2 {
            score -= 15.0 * (1.0 - slack / cap);
        }
        if slack == 0.0 {
            score -= 20.0 * (1.0 - progress);
        }
    }

    if bin_residual != bin_capacity {
        let dead = (bin_residual - item_size) as f64;
        let dead_ratio = dead / cap;
        if dead_ratio > 0.5 && fitting_bins_count > 1 {
            score += 10.5 * (dead_ratio - 0.5) * (1.0 - progress);
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
            && mean_residual > 0.0 && (mean_residual as u32) >= next_item_size {
            score += 12.0;
        }
        if post_residual > 12 && post_residual < 40 && next_item_size > post_residual {
            let orphan = (post_residual as f64 - 12.0) / 28.0;
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            score += 17.0 * orphan * scarcity * (0.5 + 0.5 * (1.0 - progress));
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let chain = post_residual % next_item_size.max(1);
            if chain == 0 {
                score -= 26.0 * (1.0 - progress);
            } else if chain <= 3 {
                score -= 11.0 * (1.0 - progress);
            }
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            let stranded = (next_item_size - post_residual) as f64;
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            if stranded <= 10.0 {
                score += (8.5 + 1.1 * (10.0 - stranded)) * scarcity * (0.4 + 0.6 * (1.0 - progress));
            } else {
                let proximity = 1.0 - (stranded - 10.0).min(cap) / cap;
                score += 3.2 * proximity * scarcity * (1.0 - progress);
            }
        }
        if dead_ratio > 0.35 && fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score += 7.5 * (dead_ratio - 0.35) * tightness * (1.0 - progress);
        }
        if post_residual > 0 && mean_residual > 0.0 {
            let gap = mean_residual - post_residual as f64;
            if gap > 0.0 && gap < 0.15 * cap && fitting_bins_count > 2 {
                score += 4.8 * (gap / (0.15 * cap)) * (1.0 - progress);
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size.max(1) && fitting_bins_count > 2 {
            score -= 6.5 * (1.0 - progress);
        }
        if post_residual == 0 && bin_residual < bin_capacity {
            score -= 42.0 * (1.0 - bin_residual as f64 / cap) * (1.0 - progress);
        }
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 1 {
            let harmony = (post_residual as f64 - mean_residual).abs() / cap;
            if harmony < 0.08 {
                score -= 9.0 * (1.0 - harmony / 0.08) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        if post_residual > 6 && post_residual <= 30 && next_item_size > 0 && next_item_size <= post_residual {
            let reps = post_residual / next_item_size.max(1);
            if reps >= 2 {
                score -= 3.5 * (reps as f64).min(4.0) * (1.0 - progress);
            }
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let after_next = post_residual - next_item_size;
            if after_next > 0 && after_next <= 12 {
                let tail = after_next as f64;
                score -= (14.0 - 0.9 * tail) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        if post_residual > 0 && post_residual < 6 && next_item_size > post_residual {
            score += 6.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let after_next = (post_residual - next_item_size) as f64;
            if after_next > 8.0 && after_next <= 16.0 && progress < 0.85 {
                let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
                score -= (4.0 + 3.0 * scarcity) * (1.0 - (after_next - 8.0) / 8.0) * (1.0 - progress);
            }
        }
        if post_residual > 0 && next_item_size > 0 && fitting_bins_count > 3 {
            let overshoot = post_residual.saturating_sub(next_item_size) as f64;
            if overshoot > 16.0 {
                score += 1.6 * ((overshoot - 16.0) / cap).min(0.25) * (1.0 - progress);
            }
        }
        if fitting_bins_count > 1 && dead_ratio > 0.08 && post_residual > 0 {
            let scarcity = 1.0 / (fitting_bins_count as f64);
            let comp_slack = (mean_residual / cap).min(1.0);
            score += 6.5 * (dead_ratio - 0.08) * scarcity * comp_slack * (0.5 + 0.5 * (1.0 - progress));
            score += 2.2 * (dead / cap) * scarcity * comp_slack * (1.0 - progress);
        }
        if fitting_bins_count > 2 && post_residual > 0 && mean_residual > 0.0 {
            let dev = ((post_residual as f64 - mean_residual).abs() / cap).min(0.4);
            score += 5.0 * dev * (1.0 - progress);
        }
        if post_residual > 0 && post_residual % 10 == 0 && post_residual <= 60 && next_item_size > 0 && next_item_size <= post_residual {
            score -= 4.0 * (1.0 - progress) * (1.0 - post_residual as f64 / 120.0);
        }
        if next_item_size > 0 && post_residual == next_item_size && fitting_bins_count <= 3 {
            score -= 30.0 / fitting_bins_count.max(1) as f64 * (0.5 + 0.5 * (1.0 - progress));
        }
        if post_residual > 0 && next_item_size > 0 && fitting_bins_count > 1 {
            let usable = next_item_size <= post_residual
                || (mean_residual as u32) >= next_item_size;
            if !usable {
                let waste_frac = post_residual as f64 / cap;
                let late = 0.35 + 0.65 * progress;
                score += 9.0 * waste_frac * late;
            }
        }
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 2 {
            let rel = post_residual as f64 / (mean_residual + 1.0);
            if rel < 0.5 {
                score -= 6.0 * (1.0 - rel / 0.5) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        if post_residual > 0 && next_item_size > 1 && next_item_size <= post_residual {
            let reps = post_residual / next_item_size;
            let rem = post_residual % next_item_size;
            if reps >= 1 && rem == 0 {
                let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
                score -= (5.0 + 6.0 * scarcity) * ((reps as f64).min(3.0)) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 1 && progress > 0.25 {
            let target = 0.5 * (mean_residual + 0.5 * cap);
            let dev = ((post_residual as f64 - target).abs() / cap).min(0.5);
            score += 2.4 * dev * (progress - 0.25);
        }
        // gen 76: near-full chain extension.
        if post_residual > 0 && next_item_size > 0 && post_residual > next_item_size {
            let after_next = post_residual - next_item_size;
            if after_next > 0 && after_next < 6 && progress > 0.35 {
                score -= 11.0 * (1.0 - after_next as f64 / 6.0) * (progress - 0.35);
            }
        }
        // gen 76: usable-residual scarcity bonus.
        if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count == 1 && bin_residual != bin_capacity {
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score -= 14.0 * (1.0 - progress) * (0.6 + 0.4 * tightness);
        }
        // gen 81: dead-space compaction gradient.
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
            && fitting_bins_count > 1 {
            let open_space = mean_residual * open_bins_count as f64;
            if open_space > 2.0 * cap {
                let frac = post_residual as f64 / next_item_size as f64;
                score += 10.0 * (1.0 - frac) * (0.5 + 0.5 * progress);
            }
        }
        // gen 81: consolidation pull (gen 130: strengthened and widened to
        // the whole stream, since residual variance is the diagnosed
        // weakness — bins whose placement leaves a small residual are
        // pulled toward the packer so slack concentrates in fewer bins).
        if post_residual > 0 && fitting_bins_count > 1 {
            let fill = 1.0 - post_residual as f64 / cap;
            let phase = if progress > 0.5 { 1.0 } else { progress * 2.0 };
            score -= 7.0 * fill * phase;
        }
        // MUTATION (gen 130): residual homogenization — penalize bins whose
        // post-residual deviates far from the mean open residual when the
        // aggregate slack is tight, pushing leftover space into a uniform
        // band that future items can actually tile into.
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 1 && progress > 0.3 {
            let open_space = mean_residual * open_bins_count as f64;
            if open_space < 3.0 * cap {
                let dev = ((post_residual as f64 - mean_residual) / cap).abs().min(0.5);
                score += 3.5 * dev * (progress - 0.3);
            }
        }
        // MUTATION (gen 130): near-exact residual bonus — when post-residual
        // is within 2 of the next item size (a one-step full close), deepen
        // the reward so these near-perfect closes are never passed over.
        if next_item_size > 0 && post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            if gap > 0 && gap <= 2 {
                score -= 18.0 * (1.0 - progress);
            }
        }
    } else {
        let fragmentation = (mean_residual / cap) * open_bins_count as f64;
        let huge_item = item_size as f64 > 0.7 * cap;
        let remaining = if total_items > step_index { total_items - step_index } else { 1 };
        let remaining_frac = remaining as f64 / total_items.max(1) as f64;
        let fresh_post = cap - item_size as f64;
        let fresh_is_exact = fresh_post <= 4.0 && fresh_post >= 0.0;

        if fragmentation > 0.55 || (huge_item && open_bins_count > 4) {
            score -= 66.0 + 46.0 * remaining_frac;
        } else if fresh_is_exact {
            score -= 134.0 + 66.0 * remaining_frac;
        } else {
            score += 400.0 - 82.0 * remaining_frac;
            if fitting_bins_count <= 3 && open_bins_count > 2 {
                score -= 30.0 + 18.0 * remaining_frac;
            }
        }

        let fresh_match = (fresh_post - mean_residual).abs() / cap;
        if fresh_match < 0.05 {
            score -= 76.0 * (1.0 - fresh_match / 0.05);
        }
        if remaining_frac < 0.05 && fresh_post > 0.0 && !fresh_is_exact {
            score += 160.0 * (fresh_post / cap);
        }
        if fresh_post > 0.0 && fresh_post <= 22.0 && !fresh_is_exact {
            score -= 26.0 * (1.0 - fresh_post / 22.0);
        }
        if fresh_post > 22.0 && fresh_post <= 40.0 && fragmentation < 0.35 {
            score -= 12.5 * (1.0 - (fresh_post - 22.0) / 18.0);
        }
        if fresh_post > 0.0 && fresh_match < 0.12 && fragmentation < 0.55 {
            score -= 30.0 * (1.0 - fresh_match / 0.12);
        }
        if next_item_size > 0 && fresh_post > 0.0 {
            let fresh_exact_next = (fresh_post as u32) == next_item_size;
            let open_can_next = mean_residual >= next_item_size as f64;
            if fresh_exact_next && !open_can_next && fitting_bins_count <= 2 {
                score -= 52.0 * (1.0 - progress);
            }
            if (fresh_post as u32) < next_item_size && mean_residual > next_item_size as f64 {
                score += 21.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && fresh_post > next_item_size as f64 {
            let chain_post = fresh_post - next_item_size as f64;
            if chain_post <= 4.0 {
                score -= 34.0 * (1.0 - chain_post / 4.0) * (0.5 + 0.5 * (1.0 - progress));
            } else if chain_post <= 10.0 {
                score -= 9.5 * (1.0 - (chain_post - 4.0) / 6.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        if remaining_frac < 0.12 && fresh_post > 0.0 && !fresh_is_exact && mean_residual * open_bins_count as f64 > 3.0 * cap {
            score += 42.0 * (1.0 - remaining_frac / 0.12);
        }
        if fitting_bins_count == 1 && fresh_post > 0.0 && next_item_size > 0 {
            let stranded_here = bin_capacity.saturating_sub(item_size);
            let would_strand = stranded_here < next_item_size;
            if would_strand && stranded_here > 0 && stranded_here <= 8 {
                score -= 32.0 * (1.0 - progress);
            }
        }
        let open_capacity = mean_residual * open_bins_count as f64;
        let per_item_need = cap * 0.5;
        if remaining_frac > 0.25 && open_capacity < per_item_need * open_bins_count.max(1) as f64 * 0.5 {
            score -= 18.0 * (1.0 - progress);
        }
        if next_item_size > 0 && fresh_post > next_item_size as f64 {
            let after_next = fresh_post - next_item_size as f64;
            if after_next > 0.0 && after_next <= 8.0 && fragmentation < 0.5 {
                score -= 20.0 * (1.0 - after_next / 8.0) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        if next_item_size > 0 && fresh_post > 0.0 && (fresh_post as u32) < next_item_size {
            let slack_total = mean_residual * open_bins_count as f64;
            if slack_total > 2.0 * cap {
                score += 26.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && (fresh_post as u32) == next_item_size && fragmentation > 0.3 {
            score -= 44.0 * (0.5 + 0.5 * (1.0 - progress));
        }
        if fresh_post > 0.5 * cap && mean_residual < 0.2 * cap && remaining_frac > 0.3 && open_bins_count > 3 {
            score += 24.0 * (fresh_post / cap - 0.5) * 2.0 * (1.0 - progress);
        }
        if fitting_bins_count <= 1 && fresh_post > 0.45 * cap && next_item_size > 0 {
            let reachable = (next_item_size as f64 / fresh_post).min(1.0);
            if reachable < 0.5 {
                score += 18.0 * (0.5 - reachable) * (1.0 - progress);
            }
        }
        if next_item_size > 0 && fresh_post > 0.0 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 2 && fragmentation < 0.5 {
                score -= 7.0 * ((reps as f64).min(4.0) - 1.0) * (0.4 + 0.6 * (1.0 - progress));
                if rem <= 3 {
                    score -= 5.0 * (1.0 - progress);
                }
            }
        }
        if fresh_post > 0.35 * cap && remaining_frac > 0.2 && mean_residual * open_bins_count as f64 > 4.0 * cap && fragmentation < 0.45 {
            score += 20.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        if remaining_frac < 0.15 && fresh_post > 0.3 * cap {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.35;
            if open_space > est_need {
                score += 55.0 * (1.0 - remaining_frac / 0.15);
            }
        }
        if remaining_frac >= 0.15 && remaining_frac < 0.45 && fresh_post > 0.4 * cap && fragmentation > 0.4 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.45;
            if open_space > est_need {
                score += 28.0 * (1.0 - remaining_frac / 0.45);
            }
        }
        if next_item_size > 1 && fresh_post > 0.0 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 2 && rem == 0 && fragmentation < 0.4 {
                score -= 10.0 * ((reps as f64).min(4.0) - 1.0) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        if remaining_frac >= 0.45 && remaining_frac < 0.5 && fresh_post > 0.45 * cap && fragmentation > 0.5 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.55;
            if open_space > est_need {
                score += 22.0 * (1.0 - remaining_frac / 0.5);
            }
        }
        // gen 76: demand-aware fresh-bin refusal.
        if remaining_frac >= 0.05 && fresh_post > 0.3 * cap && next_item_size > 0 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (next_item_size as f64) * 0.42;
            if open_space > 1.15 * est_need {
                score += 30.0 * (1.0 - remaining_frac) * (fresh_post / cap - 0.3);
            }
        }
        // gen 76: fresh-bin dead-space cap.
        if fresh_post > 0.35 * cap && next_item_size > 0 && (fresh_post as u32) < next_item_size && fragmentation < 0.4 && remaining_frac > 0.15 {
            score += 16.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        // gen 81: tileability-aware open.
        if next_item_size > 1 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 3 && rem == 0 && fragmentation < 0.3 {
                score -= 14.0 * ((reps as f64).min(5.0) - 2.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // MUTATION (gen 130): fresh-bin residual-band matching — opening is
        // rewarded when the fresh post-residual lands in the same band as
        // the mean open residual (deviation < 8% of cap), so the new bin
        // joins the existing residual distribution instead of creating a
        // heterogeneous pocket of unusable slack.
        if fresh_post > 0.0 && mean_residual > 0.0 && fitting_bins_count > 1 && progress > 0.25 {
            let band = (fresh_post - mean_residual).abs() / cap;
            if band < 0.08 {
                score -= 12.0 * (1.0 - band / 0.08) * (progress - 0.25);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        if post_residual <= 10 {
            score += 60.0 * (1.0 - post_residual as f64 / 10.0) + 20.0;
        } else if post_residual < item_size {
            // Gap smaller than current item: likely dead space for the stream.
            score += 12.0 * (1.0 - post_residual as f64 / item_size as f64);
        }
    } else {
        // Perfect fit: strong reward.
        score -= 50.0;
    }

    // Reward tight fits generally (small post_residual relative to item).
    score -= 30.0 * (item_size as f64 / (bin_residual as f64 + 1.0));

    // Open-bin pressure: discourage spreading across many bins, but relax
    // when few bins fit the item (last-chance placements are valuable).
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (1.0 + 0.5 * progress);
    if fitting_bins_count > 1 {
        score += 0.6 * pressure;
    } else {
        score -= 8.0; // last fitting bin: favor using it
    }

    // Coupling with mean residual: prefer bins whose residual is below mean
    // (concentrate fill), penalize dipping into fresher/larger bins.
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Lookahead: if next item fits into the post residual, reward; if the
    // post residual is smaller than next item, penalize slightly.
    if next_item_size > 0 {
        if (post_residual as f64) >= next_item_size as f64 {
            score -= 10.0;
        } else if post_residual > 0 {
            score += 6.0;
        }
    }

    // New-bin candidate handling: empty bin is a fallback; make it attractive
    // only when this bin's fit is poor (large post_residual dead space).
    if bin_residual == bin_capacity {
        // Neutral baseline with mild penalty so poor fits in open bins lose.
        score = bin_capacity as f64 * 0.9
            + 0.4 * open_bins_count as f64
            + if post_residual < 15 { 40.0 } else { 0.0 };
        // Late in the stream, prefer closing out open bins rather than opening.
        score -= 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Layered dead-space rewards (lower post_residual = better).
    if post_residual == 0 {
        score -= 980.0;
    } else if post_residual <= 10 {
        score -= 64.0 + 3.6 * (10 - post_residual) as f64;
    } else if post_residual <= 22 {
        score -= 13.5 + 1.5 * (22 - post_residual) as f64;
    } else if post_residual <= 32 {
        score -= 5.0 + 0.7 * (32 - post_residual) as f64;
    } else if post_residual <= 48 {
        score -= 1.2 + 0.22 * (48 - post_residual) as f64;
    } else {
        score -= 1.2 - 0.014 * (post_residual as f64 - 48.0);
    }

    let w = 0.33 + 0.67 * progress * progress;
    score *= w;

    // Lookahead coupling with the next item.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if next_item_size < post_residual {
            let two_step_waste = (post_residual - next_item_size) as f64;
            if two_step_waste <= 8.0 {
                score -= 135.0 - 2.3 * two_step_waste;
            } else {
                score -= 72.0 - 0.58 * two_step_waste;
            }
            if two_step_waste <= 3.0 {
                score -= 48.0;
            }
        } else {
            let miss = (next_item_size - post_residual) as f64;
            score += 0.95 * miss;
            if miss > 26.0 {
                score += 0.55 * (miss - 26.0);
            }
        }
    }

    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
        let boost = 36.0 + 26.0 * scarcity;
        score -= boost * (1.0 - slack / cap) * (0.6 + 0.4 * (1.0 - progress));
        if fitting_bins_count <= 2 {
            score -= 15.0 * (1.0 - slack / cap);
        }
        if slack == 0.0 {
            score -= 20.0 * (1.0 - progress);
        }
    }

    if bin_residual != bin_capacity {
        let dead = (bin_residual - item_size) as f64;
        let dead_ratio = dead / cap;
        if dead_ratio > 0.5 && fitting_bins_count > 1 {
            score += 10.5 * (dead_ratio - 0.5) * (1.0 - progress);
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
            && mean_residual > 0.0 && (mean_residual as u32) >= next_item_size {
            score += 12.0;
        }
        if post_residual > 12 && post_residual < 40 && next_item_size > post_residual {
            let orphan = (post_residual as f64 - 12.0) / 28.0;
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            score += 17.0 * orphan * scarcity * (0.5 + 0.5 * (1.0 - progress));
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let chain = post_residual % next_item_size.max(1);
            if chain == 0 {
                score -= 26.0 * (1.0 - progress);
            } else if chain <= 3 {
                score -= 11.0 * (1.0 - progress);
            }
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            let stranded = (next_item_size - post_residual) as f64;
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            if stranded <= 10.0 {
                score += (8.5 + 1.1 * (10.0 - stranded)) * scarcity * (0.4 + 0.6 * (1.0 - progress));
            } else {
                let proximity = 1.0 - (stranded - 10.0).min(cap) / cap;
                score += 3.2 * proximity * scarcity * (1.0 - progress);
            }
        }
        if dead_ratio > 0.35 && fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score += 7.5 * (dead_ratio - 0.35) * tightness * (1.0 - progress);
        }
        if post_residual > 0 && mean_residual > 0.0 {
            let gap = mean_residual - post_residual as f64;
            if gap > 0.0 && gap < 0.15 * cap && fitting_bins_count > 2 {
                score += 4.8 * (gap / (0.15 * cap)) * (1.0 - progress);
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size.max(1) && fitting_bins_count > 2 {
            score -= 6.5 * (1.0 - progress);
        }
        if post_residual == 0 && bin_residual < bin_capacity {
            score -= 42.0 * (1.0 - bin_residual as f64 / cap) * (1.0 - progress);
        }
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 1 {
            let harmony = (post_residual as f64 - mean_residual).abs() / cap;
            if harmony < 0.08 {
                score -= 9.0 * (1.0 - harmony / 0.08) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        if post_residual > 6 && post_residual <= 30 && next_item_size > 0 && next_item_size <= post_residual {
            let reps = post_residual / next_item_size.max(1);
            if reps >= 2 {
                score -= 3.5 * (reps as f64).min(4.0) * (1.0 - progress);
            }
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let after_next = post_residual - next_item_size;
            if after_next > 0 && after_next <= 12 {
                let tail = after_next as f64;
                score -= (14.0 - 0.9 * tail) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        if post_residual > 0 && post_residual < 6 && next_item_size > post_residual {
            score += 6.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let after_next = (post_residual - next_item_size) as f64;
            if after_next > 8.0 && after_next <= 16.0 && progress < 0.85 {
                let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
                score -= (4.0 + 3.0 * scarcity) * (1.0 - (after_next - 8.0) / 8.0) * (1.0 - progress);
            }
        }
        if post_residual > 0 && next_item_size > 0 && fitting_bins_count > 3 {
            let overshoot = post_residual.saturating_sub(next_item_size) as f64;
            if overshoot > 16.0 {
                score += 1.6 * ((overshoot - 16.0) / cap).min(0.25) * (1.0 - progress);
            }
        }
        if fitting_bins_count > 1 && dead_ratio > 0.08 && post_residual > 0 {
            let scarcity = 1.0 / (fitting_bins_count as f64);
            let comp_slack = (mean_residual / cap).min(1.0);
            score += 6.5 * (dead_ratio - 0.08) * scarcity * comp_slack * (0.5 + 0.5 * (1.0 - progress));
            score += 2.2 * (dead / cap) * scarcity * comp_slack * (1.0 - progress);
        }
        if fitting_bins_count > 2 && post_residual > 0 && mean_residual > 0.0 {
            let dev = ((post_residual as f64 - mean_residual).abs() / cap).min(0.4);
            score += 5.0 * dev * (1.0 - progress);
        }
        if post_residual > 0 && post_residual % 10 == 0 && post_residual <= 60 && next_item_size > 0 && next_item_size <= post_residual {
            score -= 4.0 * (1.0 - progress) * (1.0 - post_residual as f64 / 120.0);
        }
        if next_item_size > 0 && post_residual == next_item_size && fitting_bins_count <= 3 {
            score -= 30.0 / fitting_bins_count.max(1) as f64 * (0.5 + 0.5 * (1.0 - progress));
        }
        if post_residual > 0 && next_item_size > 0 && fitting_bins_count > 1 {
            let usable = next_item_size <= post_residual
                || (mean_residual as u32) >= next_item_size;
            if !usable {
                let waste_frac = post_residual as f64 / cap;
                let late = 0.35 + 0.65 * progress;
                score += 9.0 * waste_frac * late;
            }
        }
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 2 {
            let rel = post_residual as f64 / (mean_residual + 1.0);
            if rel < 0.5 {
                score -= 6.0 * (1.0 - rel / 0.5) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        if post_residual > 0 && next_item_size > 1 && next_item_size <= post_residual {
            let reps = post_residual / next_item_size;
            let rem = post_residual % next_item_size;
            if reps >= 1 && rem == 0 {
                let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
                score -= (5.0 + 6.0 * scarcity) * ((reps as f64).min(3.0)) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 1 && progress > 0.25 {
            let target = 0.5 * (mean_residual + 0.5 * cap);
            let dev = ((post_residual as f64 - target).abs() / cap).min(0.5);
            score += 2.4 * dev * (progress - 0.25);
        }
        // gen 76: near-full chain extension.
        if post_residual > 0 && next_item_size > 0 && post_residual > next_item_size {
            let after_next = post_residual - next_item_size;
            if after_next > 0 && after_next < 6 && progress > 0.35 {
                score -= 11.0 * (1.0 - after_next as f64 / 6.0) * (progress - 0.35);
            }
        }
        // gen 76: usable-residual scarcity bonus.
        if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count == 1 && bin_residual != bin_capacity {
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score -= 14.0 * (1.0 - progress) * (0.6 + 0.4 * tightness);
        }
        // gen 81: dead-space compaction gradient.
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
            && fitting_bins_count > 1 {
            let open_space = mean_residual * open_bins_count as f64;
            if open_space > 2.0 * cap {
                let frac = post_residual as f64 / next_item_size as f64;
                score += 10.0 * (1.0 - frac) * (0.5 + 0.5 * progress);
            }
        }
        // gen 81/108: consolidation pull.
        if post_residual > 0 && fitting_bins_count > 2 && progress > 0.35 {
            let fill = 1.0 - post_residual as f64 / cap;
            score -= 6.5 * fill * (progress - 0.35);
        }
        // gen 108: residual-band homogenization.
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 1 {
            let rel_dev = (post_residual as f64 - mean_residual) / (mean_residual + 2.0);
            if rel_dev.abs() < 0.25 {
                score -= 7.5 * (1.0 - rel_dev.abs() / 0.25) * (0.3 + 0.7 * progress);
            } else if rel_dev > 0.25 {
                score += 3.0 * ((rel_dev - 0.25).min(1.5)) * (0.4 + 0.6 * progress);
            }
        }
        // gen 108: two-item lookahead pairing.
        if next_item_size > 0 && post_residual > next_item_size && progress > 0.3 {
            let after_next = post_residual - next_item_size;
            if after_next > 0 && after_next <= 100 {
                let viability = 1.0 - after_next as f64 / (mean_residual + 2.0).min(cap);
                if viability > 0.5 {
                    score -= 8.0 * (viability - 0.5) * (progress - 0.3);
                }
            }
        }
        // gen 108: late-stream exact-drain pressure.
        if post_residual > 0 && progress > 0.7 {
            let small = post_residual as f64;
            if small < 0.12 * cap {
                score -= 9.0 * (1.0 - small / (0.12 * cap)) * (progress - 0.7);
            } else if small > 0.25 * cap && small < 0.6 * cap {
                score += 5.0 * ((small - 0.25 * cap) / (0.35 * cap)) * (progress - 0.7);
            }
        }
        // MUTATION (gen 130): mean-residual tiling match — when the
        // post-residual matches the *aggregate* residual scale (mean), the
        // leftover is most likely to be drained by the average future item;
        // reward tight alignment between post_residual and mean_residual
        // scaled by how many bins are competing, sharpening compaction.
        if post_residual > 0 && mean_residual > 1.0 && fitting_bins_count > 1 {
            let match_frac = 1.0 - ((post_residual as f64 - mean_residual).abs() / (mean_residual + 4.0)).min(1.0);
            if match_frac > 0.7 {
                score -= 5.5 * (match_frac - 0.7) / 0.3 * (0.4 + 0.6 * progress);
            }
        }
        // MUTATION (gen 130): dead-space interdiction — when placing here
        // leaves a residual that NO plausible item can drain (post_residual
        // far below next item AND below mean residual), and other bins can
        // still absorb the next item, penalize this placement proportionally
        // to the stranded fraction, tightening residual variance.
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
            && fitting_bins_count > 2 && progress > 0.2 {
            let stranded_frac = post_residual as f64 / next_item_size as f64;
            if stranded_frac < 0.6 {
                score += 8.0 * (0.6 - stranded_frac) / 0.6 * (0.4 + 0.6 * progress);
            }
        }
        // MUTATION (gen 130): scarcity-weighted exactness — when few bins
        // can fit the item, the choice is nearly forced, but among those the
        // one leaving the smallest post-residual should dominate; deepen the
        // small-residual gradient under scarcity.
        if post_residual > 0 && fitting_bins_count <= 3 {
            let scarcity = 1.0 / fitting_bins_count.max(1) as f64;
            score -= 6.0 * scarcity * (1.0 - post_residual as f64 / cap) * (1.0 - progress);
        }
    } else {
        let fragmentation = (mean_residual / cap) * open_bins_count as f64;
        let huge_item = item_size as f64 > 0.7 * cap;
        let remaining = if total_items > step_index { total_items - step_index } else { 1 };
        let remaining_frac = remaining as f64 / total_items.max(1) as f64;
        let fresh_post = cap - item_size as f64;
        let fresh_is_exact = fresh_post <= 4.0 && fresh_post >= 0.0;

        if fragmentation > 0.55 || (huge_item && open_bins_count > 4) {
            score -= 66.0 + 46.0 * remaining_frac;
        } else if fresh_is_exact {
            score -= 134.0 + 66.0 * remaining_frac;
        } else {
            score += 400.0 - 82.0 * remaining_frac;
            if fitting_bins_count <= 3 && open_bins_count > 2 {
                score -= 30.0 + 18.0 * remaining_frac;
            }
        }

        let fresh_match = (fresh_post - mean_residual).abs() / cap;
        if fresh_match < 0.05 {
            score -= 76.0 * (1.0 - fresh_match / 0.05);
        }
        if remaining_frac < 0.05 && fresh_post > 0.0 && !fresh_is_exact {
            score += 160.0 * (fresh_post / cap);
        }
        if fresh_post > 0.0 && fresh_post <= 22.0 && !fresh_is_exact {
            score -= 26.0 * (1.0 - fresh_post / 22.0);
        }
        if fresh_post > 22.0 && fresh_post <= 40.0 && fragmentation < 0.35 {
            score -= 12.5 * (1.0 - (fresh_post - 22.0) / 18.0);
        }
        if fresh_post > 0.0 && fresh_match < 0.12 && fragmentation < 0.55 {
            score -= 30.0 * (1.0 - fresh_match / 0.12);
        }
        if next_item_size > 0 && fresh_post > 0.0 {
            let fresh_exact_next = (fresh_post as u32) == next_item_size;
            let open_can_next = mean_residual >= next_item_size as f64;
            if fresh_exact_next && !open_can_next && fitting_bins_count <= 2 {
                score -= 52.0 * (1.0 - progress);
            }
            if (fresh_post as u32) < next_item_size && mean_residual > next_item_size as f64 {
                score += 21.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && fresh_post > next_item_size as f64 {
            let chain_post = fresh_post - next_item_size as f64;
            if chain_post <= 4.0 {
                score -= 34.0 * (1.0 - chain_post / 4.0) * (0.5 + 0.5 * (1.0 - progress));
            } else if chain_post <= 10.0 {
                score -= 9.5 * (1.0 - (chain_post - 4.0) / 6.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        if remaining_frac < 0.12 && fresh_post > 0.0 && !fresh_is_exact && mean_residual * open_bins_count as f64 > 3.0 * cap {
            score += 42.0 * (1.0 - remaining_frac / 0.12);
        }
        if fitting_bins_count == 1 && fresh_post > 0.0 && next_item_size > 0 {
            let stranded_here = bin_capacity.saturating_sub(item_size);
            let would_strand = stranded_here < next_item_size;
            if would_strand && stranded_here > 0 && stranded_here <= 8 {
                score -= 32.0 * (1.0 - progress);
            }
        }
        let open_capacity = mean_residual * open_bins_count as f64;
        let per_item_need = cap * 0.5;
        if remaining_frac > 0.25 && open_capacity < per_item_need * open_bins_count.max(1) as f64 * 0.5 {
            score -= 18.0 * (1.0 - progress);
        }
        if next_item_size > 0 && fresh_post > next_item_size as f64 {
            let after_next = fresh_post - next_item_size as f64;
            if after_next > 0.0 && after_next <= 8.0 && fragmentation < 0.5 {
                score -= 20.0 * (1.0 - after_next / 8.0) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        if next_item_size > 0 && fresh_post > 0.0 && (fresh_post as u32) < next_item_size {
            let slack_total = mean_residual * open_bins_count as f64;
            if slack_total > 2.0 * cap {
                score += 26.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && (fresh_post as u32) == next_item_size && fragmentation > 0.3 {
            score -= 44.0 * (0.5 + 0.5 * (1.0 - progress));
        }
        if fresh_post > 0.5 * cap && mean_residual < 0.2 * cap && remaining_frac > 0.3 && open_bins_count > 3 {
            score += 24.0 * (fresh_post / cap - 0.5) * 2.0 * (1.0 - progress);
        }
        if fitting_bins_count <= 1 && fresh_post > 0.45 * cap && next_item_size > 0 {
            let reachable = (next_item_size as f64 / fresh_post).min(1.0);
            if reachable < 0.5 {
                score += 18.0 * (0.5 - reachable) * (1.0 - progress);
            }
        }
        if next_item_size > 0 && fresh_post > 0.0 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 2 && fragmentation < 0.5 {
                score -= 7.0 * ((reps as f64).min(4.0) - 1.0) * (0.4 + 0.6 * (1.0 - progress));
                if rem <= 3 {
                    score -= 5.0 * (1.0 - progress);
                }
            }
        }
        if fresh_post > 0.35 * cap && remaining_frac > 0.2 && mean_residual * open_bins_count as f64 > 4.0 * cap && fragmentation < 0.45 {
            score += 20.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        if remaining_frac < 0.15 && fresh_post > 0.3 * cap {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.35;
            if open_space > est_need {
                score += 55.0 * (1.0 - remaining_frac / 0.15);
            }
        }
        if remaining_frac >= 0.15 && remaining_frac < 0.45 && fresh_post > 0.4 * cap && fragmentation > 0.4 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.45;
            if open_space > est_need {
                score += 28.0 * (1.0 - remaining_frac / 0.45);
            }
        }
        if next_item_size > 1 && fresh_post > 0.0 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 2 && rem == 0 && fragmentation < 0.4 {
                score -= 10.0 * ((reps as f64).min(4.0) - 1.0) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        if remaining_frac >= 0.45 && remaining_frac < 0.5 && fresh_post > 0.45 * cap && fragmentation > 0.5 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.55;
            if open_space > est_need {
                score += 22.0 * (1.0 - remaining_frac / 0.5);
            }
        }
        // gen 76: demand-aware fresh-bin refusal.
        if remaining_frac >= 0.05 && fresh_post > 0.3 * cap && next_item_size > 0 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (next_item_size as f64) * 0.42;
            if open_space > 1.15 * est_need {
                score += 30.0 * (1.0 - remaining_frac) * (fresh_post / cap - 0.3);
            }
        }
        // gen 76: fresh-bin dead-space cap.
        if fresh_post > 0.35 * cap && next_item_size > 0 && (fresh_post as u32) < next_item_size && fragmentation < 0.4 && remaining_frac > 0.15 {
            score += 16.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        // gen 81: tileability-aware open.
        if next_item_size > 1 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 3 && rem == 0 && fragmentation < 0.3 {
                score -= 14.0 * ((reps as f64).min(5.0) - 2.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // gen 108: variance-aware open gate.
        if fresh_post > 0.0 && mean_residual > 0.0 && open_bins_count > 2 && remaining_frac > 0.1 {
            let rel_match = ((fresh_post - mean_residual) / (mean_residual + 2.0)).abs();
            if rel_match < 0.2 && fragmentation < 0.5 {
                score -= 11.0 * (1.0 - rel_match / 0.2) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        // gen 108: endgame drain-reserve.
        if remaining_frac < 0.08 && fresh_post > 0.05 * cap && !fresh_is_exact {
            let open_space = mean_residual * open_bins_count as f64;
            if open_space > cap {
                score += 34.0 * (1.0 - remaining_frac / 0.08) * (fresh_post / cap).min(1.0);
            }
        }
        // MUTATION (gen 130): supply-demand fresh gate — open a new bin only
        // when aggregate open slack cannot plausibly cover the remaining
        // stream demand measured in next-item units; otherwise push the
        // fresh-bin score up so existing bins absorb the item.
        if fresh_post > 0.0 && remaining_frac > 0.05 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_demand = (remaining as f64) * (next_item_size.max(1) as f64) * 0.5;
            if open_space > est_demand && fresh_post > 0.25 * cap {
                score += 22.0 * (1.0 - remaining_frac) * (fresh_post / cap - 0.25);
            } else if open_space < 0.6 * est_demand && fragmentation < 0.4 {
                score -= 14.0 * (0.6 - open_space / est_demand.max(1.0)) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // MUTATION (gen 130): mean-aligned fresh residual — a fresh bin whose
        // leftover matches the mean residual of open bins tiles cleanly with
        // the residual population; reward that alignment early/mid-stream.
        if fresh_post > 0.0 && mean_residual > 4.0 && open_bins_count > 1 && remaining_frac > 0.15 {
            let rel = ((fresh_post - mean_residual) / mean_residual).abs();
            if rel < 0.3 {
                score -= 9.0 * (1.0 - rel / 0.3) * (1.0 - progress);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward post_residual that exactly matches next item.
    if next_item_size > 0 {
        let post = post_residual as f64;
        let nxt = next_item_size as f64;
        let diff = (post - nxt).abs();
        // Perfect match for the next item -> strong reward
        if diff <= 1.0 {
            score -= 60.0;
        } else if nxt <= post {
            // Next item fits in the leftover: scale reward by tightness of match
            score -= 25.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Leftover too small for next item: penalize dead space proportionally
            score += 10.0 * (diff / bin_capacity as f64);
        }
    }

    // Penalize very small unusable leftovers (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor)
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // New-bin candidate: neutralize its raw post_residual so it only wins when
    // no open bin offers a good (lookahead-matched) fit.
    if bin_residual == bin_capacity {
        score += 55.0;
        // Late in the stream, opening a new bin is less attractive (waste at end)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Layered dead-space rewards (lower post_residual = better).
    if post_residual == 0 {
        score -= 980.0;
    } else if post_residual <= 4 {
        score -= 250.0 + 4.2 * (4 - post_residual) as f64;
    } else if post_residual <= 10 {
        score -= 64.0 + 3.6 * (10 - post_residual) as f64;
    } else if post_residual <= 22 {
        score -= 13.5 + 1.5 * (22 - post_residual) as f64;
    } else if post_residual <= 32 {
        score -= 5.0 + 0.7 * (32 - post_residual) as f64;
    } else if post_residual <= 48 {
        score -= 1.2 + 0.22 * (48 - post_residual) as f64;
    } else {
        score -= 1.2 - 0.014 * (post_residual as f64 - 48.0);
    }

    let w = 0.33 + 0.67 * progress * progress;
    score *= w;

    // Lookahead coupling with the next item.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if next_item_size < post_residual {
            let two_step_waste = (post_residual - next_item_size) as f64;
            if two_step_waste <= 8.0 {
                score -= 135.0 - 2.3 * two_step_waste;
            } else {
                score -= 72.0 - 0.58 * two_step_waste;
            }
            if two_step_waste <= 3.0 {
                score -= 48.0;
            }
        } else {
            let miss = (next_item_size - post_residual) as f64;
            score += 0.95 * miss;
            if miss > 26.0 {
                score += 0.55 * (miss - 26.0);
            }
        }
    }

    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
        let boost = 36.0 + 26.0 * scarcity;
        score -= boost * (1.0 - slack / cap) * (0.6 + 0.4 * (1.0 - progress));
        if fitting_bins_count <= 2 {
            score -= 15.0 * (1.0 - slack / cap);
        }
        if slack == 0.0 {
            score -= 20.0 * (1.0 - progress);
        }
    }

    if bin_residual != bin_capacity {
        let dead = (bin_residual - item_size) as f64;
        let dead_ratio = dead / cap;
        if dead_ratio > 0.5 && fitting_bins_count > 1 {
            score += 10.5 * (dead_ratio - 0.5) * (1.0 - progress);
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
            && mean_residual > 0.0 && (mean_residual as u32) >= next_item_size {
            score += 12.0;
        }
        if post_residual > 12 && post_residual < 40 && next_item_size > post_residual {
            let orphan = (post_residual as f64 - 12.0) / 28.0;
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            score += 17.0 * orphan * scarcity * (0.5 + 0.5 * (1.0 - progress));
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let chain = post_residual % next_item_size.max(1);
            if chain == 0 {
                score -= 26.0 * (1.0 - progress);
            } else if chain <= 3 {
                score -= 11.0 * (1.0 - progress);
            }
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            let stranded = (next_item_size - post_residual) as f64;
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            if stranded <= 10.0 {
                score += (8.5 + 1.1 * (10.0 - stranded)) * scarcity * (0.4 + 0.6 * (1.0 - progress));
            } else {
                let proximity = 1.0 - (stranded - 10.0).min(cap) / cap;
                score += 3.2 * proximity * scarcity * (1.0 - progress);
            }
        }
        if dead_ratio > 0.35 && fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score += 7.5 * (dead_ratio - 0.35) * tightness * (1.0 - progress);
        }
        if post_residual > 0 && mean_residual > 0.0 {
            let gap = mean_residual - post_residual as f64;
            if gap > 0.0 && gap < 0.15 * cap && fitting_bins_count > 2 {
                score += 4.8 * (gap / (0.15 * cap)) * (1.0 - progress);
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size.max(1) && fitting_bins_count > 2 {
            score -= 6.5 * (1.0 - progress);
        }
        if post_residual == 0 && bin_residual < bin_capacity {
            score -= 42.0 * (1.0 - bin_residual as f64 / cap) * (1.0 - progress);
        }
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 1 {
            let harmony = (post_residual as f64 - mean_residual).abs() / cap;
            if harmony < 0.08 {
                score -= 9.0 * (1.0 - harmony / 0.08) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        if post_residual > 6 && post_residual <= 30 && next_item_size > 0 && next_item_size <= post_residual {
            let reps = post_residual / next_item_size.max(1);
            if reps >= 2 {
                score -= 3.5 * (reps as f64).min(4.0) * (1.0 - progress);
            }
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let after_next = post_residual - next_item_size;
            if after_next > 0 && after_next <= 12 {
                let tail = after_next as f64;
                score -= (14.0 - 0.9 * tail) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        if post_residual > 0 && post_residual < 6 && next_item_size > post_residual {
            score += 6.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let after_next = (post_residual - next_item_size) as f64;
            if after_next > 8.0 && after_next <= 16.0 && progress < 0.85 {
                let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
                score -= (4.0 + 3.0 * scarcity) * (1.0 - (after_next - 8.0) / 8.0) * (1.0 - progress);
            }
        }
        if post_residual > 0 && next_item_size > 0 && fitting_bins_count > 3 {
            let overshoot = post_residual.saturating_sub(next_item_size) as f64;
            if overshoot > 16.0 {
                score += 1.6 * ((overshoot - 16.0) / cap).min(0.25) * (1.0 - progress);
            }
        }
        if fitting_bins_count > 1 && dead_ratio > 0.08 && post_residual > 0 {
            let scarcity = 1.0 / (fitting_bins_count as f64);
            let comp_slack = (mean_residual / cap).min(1.0);
            score += 6.5 * (dead_ratio - 0.08) * scarcity * comp_slack * (0.5 + 0.5 * (1.0 - progress));
            score += 2.2 * (dead / cap) * scarcity * comp_slack * (1.0 - progress);
        }
        if fitting_bins_count > 2 && post_residual > 0 && mean_residual > 0.0 {
            let dev = ((post_residual as f64 - mean_residual).abs() / cap).min(0.4);
            score += 5.0 * dev * (1.0 - progress);
        }
        if post_residual > 0 && post_residual % 10 == 0 && post_residual <= 60 && next_item_size > 0 && next_item_size <= post_residual {
            score -= 4.0 * (1.0 - progress) * (1.0 - post_residual as f64 / 120.0);
        }
        if next_item_size > 0 && post_residual == next_item_size && fitting_bins_count <= 3 {
            score -= 30.0 / fitting_bins_count.max(1) as f64 * (0.5 + 0.5 * (1.0 - progress));
        }
        if post_residual > 0 && next_item_size > 0 && fitting_bins_count > 1 {
            let usable = next_item_size <= post_residual
                || (mean_residual as u32) >= next_item_size;
            if !usable {
                let waste_frac = post_residual as f64 / cap;
                let late = 0.35 + 0.65 * progress;
                score += 9.0 * waste_frac * late;
            }
        }
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 2 {
            let rel = post_residual as f64 / (mean_residual + 1.0);
            if rel < 0.5 {
                score -= 6.0 * (1.0 - rel / 0.5) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        if post_residual > 0 && next_item_size > 1 && next_item_size <= post_residual {
            let reps = post_residual / next_item_size;
            let rem = post_residual % next_item_size;
            if reps >= 1 && rem == 0 {
                let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
                score -= (5.0 + 6.0 * scarcity) * ((reps as f64).min(3.0)) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 1 && progress > 0.25 {
            let target = 0.5 * (mean_residual + 0.5 * cap);
            let dev = ((post_residual as f64 - target).abs() / cap).min(0.5);
            score += 2.4 * dev * (progress - 0.25);
        }
        // gen 76: near-full chain extension (refined: widen to after_next < 6
        // and extend earlier into the stream since residual variance is the
        // diagnosed weakness).
        if post_residual > 0 && next_item_size > 0 && post_residual > next_item_size {
            let after_next = post_residual - next_item_size;
            if after_next > 0 && after_next < 6 && progress > 0.35 {
                score -= 11.0 * (1.0 - after_next as f64 / 6.0) * (progress - 0.35);
            }
        }
        // gen 76: usable-residual scarcity bonus (refined: scale with how
        // close the post-residual is to the next item, favoring tight reuse).
        if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count == 1 && bin_residual != bin_capacity {
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score -= 14.0 * (1.0 - progress) * (0.6 + 0.4 * tightness);
        }
        // gen 81: dead-space compaction gradient — when this placement leaves
        // a residual well below the next item size AND the aggregate open
        // slack elsewhere is large, the leftover here is pure dead space;
        // penalize proportionally so residual variance shrinks.
        // MUTATION (gen 130): widen the trigger band to near-misses
        // (post_residual up to 1.25x next item) and sharpen the gradient
        // with a quadratic dead-space fraction, since residual variance is
        // the diagnosed weakness.
        if post_residual > 0 && next_item_size > 0 && fitting_bins_count > 1 {
            let pr = post_residual as f64;
            let ns = next_item_size as f64;
            let open_space = mean_residual * open_bins_count as f64;
            if open_space > 1.8 * cap {
                if pr < ns {
                    let frac = pr / ns;
                    score += 10.0 * (1.0 - frac) * (0.5 + 0.5 * progress);
                } else if pr < 1.25 * ns {
                    let excess = (pr - ns) / ns;
                    score += 6.0 * excess * (0.5 + 0.5 * progress);
                }
            }
        }
        // gen 81: consolidation pull — prefer the bin whose placement brings
        // it closest to full relative to competing bins.
        // MUTATION (gen 130): start earlier (progress > 0.4) and add a mild
        // quadratic term so near-full placements are favored increasingly
        // late in the stream, tightening residual spread.
        if post_residual > 0 && fitting_bins_count > 2 && progress > 0.4 {
            let fill = 1.0 - post_residual as f64 / cap;
            score -= (4.0 * fill + 6.0 * fill * fill) * (progress - 0.4);
        }
        // MUTATION (gen 130): residual-variance damper — when this bin's
        // post-residual sits close to the mean open residual, reward it so
        // homogeneous leftovers accumulate into tileable chunks instead of
        // scattering into unusable slivers.
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 1 {
            let pr = post_residual as f64;
            let harmony = (pr - mean_residual).abs() / cap;
            if harmony < 0.04 && pr < 0.5 * cap {
                score -= 7.0 * (1.0 - harmony / 0.04) * (0.6 + 0.4 * progress);
            }
        }
    } else {
        let fragmentation = (mean_residual / cap) * open_bins_count as f64;
        let huge_item = item_size as f64 > 0.7 * cap;
        let remaining = if total_items > step_index { total_items - step_index } else { 1 };
        let remaining_frac = remaining as f64 / total_items.max(1) as f64;
        let fresh_post = cap - item_size as f64;
        let fresh_is_exact = fresh_post <= 4.0 && fresh_post >= 0.0;

        if fragmentation > 0.55 || (huge_item && open_bins_count > 4) {
            score -= 66.0 + 46.0 * remaining_frac;
        } else if fresh_is_exact {
            score -= 134.0 + 66.0 * remaining_frac;
        } else {
            score += 400.0 - 82.0 * remaining_frac;
            if fitting_bins_count <= 3 && open_bins_count > 2 {
                score -= 30.0 + 18.0 * remaining_frac;
            }
        }

        let fresh_match = (fresh_post - mean_residual).abs() / cap;
        if fresh_match < 0.05 {
            score -= 76.0 * (1.0 - fresh_match / 0.05);
        }
        if remaining_frac < 0.05 && fresh_post > 0.0 && !fresh_is_exact {
            score += 160.0 * (fresh_post / cap);
        }
        if fresh_post > 0.0 && fresh_post <= 22.0 && !fresh_is_exact {
            score -= 26.0 * (1.0 - fresh_post / 22.0);
        }
        if fresh_post > 22.0 && fresh_post <= 40.0 && fragmentation < 0.35 {
            score -= 12.5 * (1.0 - (fresh_post - 22.0) / 18.0);
        }
        if fresh_post > 0.0 && fresh_match < 0.12 && fragmentation < 0.55 {
            score -= 30.0 * (1.0 - fresh_match / 0.12);
        }
        if next_item_size > 0 && fresh_post > 0.0 {
            let fresh_exact_next = (fresh_post as u32) == next_item_size;
            let open_can_next = mean_residual >= next_item_size as f64;
            if fresh_exact_next && !open_can_next && fitting_bins_count <= 2 {
                score -= 52.0 * (1.0 - progress);
            }
            if (fresh_post as u32) < next_item_size && mean_residual > next_item_size as f64 {
                score += 21.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && fresh_post > next_item_size as f64 {
            let chain_post = fresh_post - next_item_size as f64;
            if chain_post <= 4.0 {
                score -= 34.0 * (1.0 - chain_post / 4.0) * (0.5 + 0.5 * (1.0 - progress));
            } else if chain_post <= 10.0 {
                score -= 9.5 * (1.0 - (chain_post - 4.0) / 6.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        if remaining_frac < 0.12 && fresh_post > 0.0 && !fresh_is_exact && mean_residual * open_bins_count as f64 > 3.0 * cap {
            score += 42.0 * (1.0 - remaining_frac / 0.12);
        }
        if fitting_bins_count == 1 && fresh_post > 0.0 && next_item_size > 0 {
            let stranded_here = bin_capacity.saturating_sub(item_size);
            let would_strand = stranded_here < next_item_size;
            if would_strand && stranded_here > 0 && stranded_here <= 8 {
                score -= 32.0 * (1.0 - progress);
            }
        }
        let open_capacity = mean_residual * open_bins_count as f64;
        let per_item_need = cap * 0.5;
        if remaining_frac > 0.25 && open_capacity < per_item_need * open_bins_count.max(1) as f64 * 0.5 {
            score -= 18.0 * (1.0 - progress);
        }
        if next_item_size > 0 && fresh_post > next_item_size as f64 {
            let after_next = fresh_post - next_item_size as f64;
            if after_next > 0.0 && after_next <= 8.0 && fragmentation < 0.5 {
                score -= 20.0 * (1.0 - after_next / 8.0) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        if next_item_size > 0 && fresh_post > 0.0 && (fresh_post as u32) < next_item_size {
            let slack_total = mean_residual * open_bins_count as f64;
            if slack_total > 2.0 * cap {
                score += 26.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && (fresh_post as u32) == next_item_size && fragmentation > 0.3 {
            score -= 44.0 * (0.5 + 0.5 * (1.0 - progress));
        }
        if fresh_post > 0.5 * cap && mean_residual < 0.2 * cap && remaining_frac > 0.3 && open_bins_count > 3 {
            score += 24.0 * (fresh_post / cap - 0.5) * 2.0 * (1.0 - progress);
        }
        if fitting_bins_count <= 1 && fresh_post > 0.45 * cap && next_item_size > 0 {
            let reachable = (next_item_size as f64 / fresh_post).min(1.0);
            if reachable < 0.5 {
                score += 18.0 * (0.5 - reachable) * (1.0 - progress);
            }
        }
        if next_item_size > 0 && fresh_post > 0.0 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 2 && fragmentation < 0.5 {
                score -= 7.0 * ((reps as f64).min(4.0) - 1.0) * (0.4 + 0.6 * (1.0 - progress));
                if rem <= 3 {
                    score -= 5.0 * (1.0 - progress);
                }
            }
        }
        if fresh_post > 0.35 * cap && remaining_frac > 0.2 && mean_residual * open_bins_count as f64 > 4.0 * cap && fragmentation < 0.45 {
            score += 20.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        if remaining_frac < 0.15 && fresh_post > 0.3 * cap {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.35;
            if open_space > est_need {
                score += 55.0 * (1.0 - remaining_frac / 0.15);
            }
        }
        if remaining_frac >= 0.15 && remaining_frac < 0.45 && fresh_post > 0.4 * cap && fragmentation > 0.4 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.45;
            if open_space > est_need {
                score += 28.0 * (1.0 - remaining_frac / 0.45);
            }
        }
        if next_item_size > 1 && fresh_post > 0.0 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 2 && rem == 0 && fragmentation < 0.4 {
                score -= 10.0 * ((reps as f64).min(4.0) - 1.0) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        if remaining_frac >= 0.45 && remaining_frac < 0.5 && fresh_post > 0.45 * cap && fragmentation > 0.5 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.55;
            if open_space > est_need {
                score += 22.0 * (1.0 - remaining_frac / 0.5);
            }
        }
        // gen 76: demand-aware fresh-bin refusal (cushion 1.15x so useful
        // opens are less suppressed).
        if remaining_frac >= 0.05 && fresh_post > 0.3 * cap && next_item_size > 0 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (next_item_size as f64) * 0.42;
            if open_space > 1.15 * est_need {
                score += 30.0 * (1.0 - remaining_frac) * (fresh_post / cap - 0.3);
            }
        }
        // gen 76: fresh-bin dead-space cap.
        if fresh_post > 0.35 * cap && next_item_size > 0 && (fresh_post as u32) < next_item_size && fragmentation < 0.4 && remaining_frac > 0.15 {
            score += 16.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        // gen 81: tileability-aware open — when the fresh bin's post-residual
        // is an exact multiple of the next item size with three or more
        // repetitions, opening creates a perfectly tileable bin.
        if next_item_size > 1 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 3 && rem == 0 && fragmentation < 0.3 {
                score -= 14.0 * ((reps as f64).min(5.0) - 2.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // MUTATION (gen 130): two-item lookahead open — when the fresh bin's
        // post-residual can host the next item AND the leftover after that
        // is small (<= 10), opening yields a two-step chain with minimal
        // waste; reward it when open slack is scarce so the new bin serves
        // as a continuation lane rather than slack scattering.
        if next_item_size > 0 && (fresh_post as u32) >= next_item_size {
            let chain_post = (fresh_post as u32) - next_item_size;
            if chain_post <= 10 {
                let open_space = mean_residual * open_bins_count as f64;
                if open_space < 1.5 * cap {
                    score -= 12.0 * (1.0 - chain_post as f64 / 10.0) * (0.5 + 0.5 * (1.0 - progress));
                }
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Layered dead-space rewards (lower post_residual = better).
    if post_residual == 0 {
        score -= 980.0;
    } else if post_residual <= 4 {
        score -= 250.0 + 4.2 * (4 - post_residual) as f64;
    } else if post_residual <= 10 {
        score -= 64.0 + 3.6 * (10 - post_residual) as f64;
    } else if post_residual <= 22 {
        score -= 13.5 + 1.5 * (22 - post_residual) as f64;
    } else if post_residual <= 32 {
        score -= 5.0 + 0.7 * (32 - post_residual) as f64;
    } else if post_residual <= 48 {
        score -= 1.2 + 0.22 * (48 - post_residual) as f64;
    } else {
        score -= 1.2 - 0.014 * (post_residual as f64 - 48.0);
    }

    let w = 0.33 + 0.67 * progress * progress;
    score *= w;

    // Lookahead coupling with the next item.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if next_item_size < post_residual {
            let two_step_waste = (post_residual - next_item_size) as f64;
            if two_step_waste <= 8.0 {
                score -= 135.0 - 2.3 * two_step_waste;
            } else {
                score -= 72.0 - 0.58 * two_step_waste;
            }
            if two_step_waste <= 3.0 {
                score -= 48.0;
            }
        } else {
            let miss = (next_item_size - post_residual) as f64;
            score += 0.95 * miss;
            if miss > 26.0 {
                score += 0.55 * (miss - 26.0);
            }
        }
    }

    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
        let boost = 36.0 + 26.0 * scarcity;
        score -= boost * (1.0 - slack / cap) * (0.6 + 0.4 * (1.0 - progress));
        if fitting_bins_count <= 2 {
            score -= 15.0 * (1.0 - slack / cap);
        }
        if slack == 0.0 {
            score -= 20.0 * (1.0 - progress);
        }
    }

    if bin_residual != bin_capacity {
        let dead = (bin_residual - item_size) as f64;
        let dead_ratio = dead / cap;
        if dead_ratio > 0.5 && fitting_bins_count > 1 {
            score += 10.5 * (dead_ratio - 0.5) * (1.0 - progress);
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
            && mean_residual > 0.0 && (mean_residual as u32) >= next_item_size {
            score += 12.0;
        }
        if post_residual > 12 && post_residual < 40 && next_item_size > post_residual {
            let orphan = (post_residual as f64 - 12.0) / 28.0;
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            score += 17.0 * orphan * scarcity * (0.5 + 0.5 * (1.0 - progress));
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let chain = post_residual % next_item_size.max(1);
            if chain == 0 {
                score -= 26.0 * (1.0 - progress);
            } else if chain <= 3 {
                score -= 11.0 * (1.0 - progress);
            }
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            let stranded = (next_item_size - post_residual) as f64;
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            if stranded <= 10.0 {
                score += (8.5 + 1.1 * (10.0 - stranded)) * scarcity * (0.4 + 0.6 * (1.0 - progress));
            } else {
                let proximity = 1.0 - (stranded - 10.0).min(cap) / cap;
                score += 3.2 * proximity * scarcity * (1.0 - progress);
            }
        }
        if dead_ratio > 0.35 && fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score += 7.5 * (dead_ratio - 0.35) * tightness * (1.0 - progress);
        }
        if post_residual > 0 && mean_residual > 0.0 {
            let gap = mean_residual - post_residual as f64;
            if gap > 0.0 && gap < 0.15 * cap && fitting_bins_count > 2 {
                score += 4.8 * (gap / (0.15 * cap)) * (1.0 - progress);
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size.max(1) && fitting_bins_count > 2 {
            score -= 6.5 * (1.0 - progress);
        }
        if post_residual == 0 && bin_residual < bin_capacity {
            score -= 42.0 * (1.0 - bin_residual as f64 / cap) * (1.0 - progress);
        }
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 1 {
            let harmony = (post_residual as f64 - mean_residual).abs() / cap;
            if harmony < 0.08 {
                score -= 9.0 * (1.0 - harmony / 0.08) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        if post_residual > 6 && post_residual <= 30 && next_item_size > 0 && next_item_size <= post_residual {
            let reps = post_residual / next_item_size.max(1);
            if reps >= 2 {
                score -= 3.5 * (reps as f64).min(4.0) * (1.0 - progress);
            }
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let after_next = post_residual - next_item_size;
            if after_next > 0 && after_next <= 12 {
                let tail = after_next as f64;
                score -= (14.0 - 0.9 * tail) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        if post_residual > 0 && post_residual < 6 && next_item_size > post_residual {
            score += 6.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let after_next = (post_residual - next_item_size) as f64;
            if after_next > 8.0 && after_next <= 16.0 && progress < 0.85 {
                let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
                score -= (4.0 + 3.0 * scarcity) * (1.0 - (after_next - 8.0) / 8.0) * (1.0 - progress);
            }
        }
        if post_residual > 0 && next_item_size > 0 && fitting_bins_count > 3 {
            let overshoot = post_residual.saturating_sub(next_item_size) as f64;
            if overshoot > 16.0 {
                score += 1.6 * ((overshoot - 16.0) / cap).min(0.25) * (1.0 - progress);
            }
        }
        if fitting_bins_count > 1 && dead_ratio > 0.08 && post_residual > 0 {
            let scarcity = 1.0 / (fitting_bins_count as f64);
            let comp_slack = (mean_residual / cap).min(1.0);
            score += 6.5 * (dead_ratio - 0.08) * scarcity * comp_slack * (0.5 + 0.5 * (1.0 - progress));
            score += 2.2 * (dead / cap) * scarcity * comp_slack * (1.0 - progress);
        }
        if fitting_bins_count > 2 && post_residual > 0 && mean_residual > 0.0 {
            let dev = ((post_residual as f64 - mean_residual).abs() / cap).min(0.4);
            score += 5.0 * dev * (1.0 - progress);
        }
        if post_residual > 0 && post_residual % 10 == 0 && post_residual <= 60 && next_item_size > 0 && next_item_size <= post_residual {
            score -= 4.0 * (1.0 - progress) * (1.0 - post_residual as f64 / 120.0);
        }
        if next_item_size > 0 && post_residual == next_item_size && fitting_bins_count <= 3 {
            score -= 30.0 / fitting_bins_count.max(1) as f64 * (0.5 + 0.5 * (1.0 - progress));
        }
        if post_residual > 0 && next_item_size > 0 && fitting_bins_count > 1 {
            let usable = next_item_size <= post_residual
                || (mean_residual as u32) >= next_item_size;
            if !usable {
                let waste_frac = post_residual as f64 / cap;
                let late = 0.35 + 0.65 * progress;
                score += 9.0 * waste_frac * late;
            }
        }
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 2 {
            let rel = post_residual as f64 / (mean_residual + 1.0);
            if rel < 0.5 {
                score -= 6.0 * (1.0 - rel / 0.5) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        if post_residual > 0 && next_item_size > 1 && next_item_size <= post_residual {
            let reps = post_residual / next_item_size;
            let rem = post_residual % next_item_size;
            if reps >= 1 && rem == 0 {
                let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
                score -= (5.0 + 6.0 * scarcity) * ((reps as f64).min(3.0)) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 1 && progress > 0.25 {
            let target = 0.5 * (mean_residual + 0.5 * cap);
            let dev = ((post_residual as f64 - target).abs() / cap).min(0.5);
            score += 2.4 * dev * (progress - 0.25);
        }
        // gen 76: near-full chain extension (refined: widen to after_next < 6
        // and extend earlier into the stream since residual variance is the
        // diagnosed weakness).
        if post_residual > 0 && next_item_size > 0 && post_residual > next_item_size {
            let after_next = post_residual - next_item_size;
            if after_next > 0 && after_next < 6 && progress > 0.35 {
                score -= 11.0 * (1.0 - after_next as f64 / 6.0) * (progress - 0.35);
            }
        }
        // gen 76: usable-residual scarcity bonus (refined: scale with how
        // close the post-residual is to the next item, favoring tight reuse).
        if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count == 1 && bin_residual != bin_capacity {
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score -= 14.0 * (1.0 - progress) * (0.6 + 0.4 * tightness);
        }
        // gen 81: dead-space compaction gradient — when this placement leaves
        // a residual well below the next item size AND the aggregate open
        // slack elsewhere is large, the leftover here is pure dead space;
        // penalize proportionally so residual variance shrinks.
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
            && fitting_bins_count > 1 {
            let open_space = mean_residual * open_bins_count as f64;
            if open_space > 2.0 * cap {
                let frac = post_residual as f64 / next_item_size as f64;
                score += 10.0 * (1.0 - frac) * (0.5 + 0.5 * progress);
            }
        }
        // gen 81: consolidation pull — prefer the bin whose placement brings
        // it closest to full relative to competing bins, tightening
        // late-stream residual spread. (gen 131: strengthened and widened to
        // start earlier since residual variance remains the diagnosed
        // weakness.)
        if post_residual > 0 && fitting_bins_count > 2 && progress > 0.4 {
            let fill = 1.0 - post_residual as f64 / cap;
            score -= 7.0 * fill * (progress - 0.4);
        }
        // MUTATION (gen 131): variance-sink penalty — bins whose post
        // residual deviates strongly from the fleet mean create residual
        // spread that future items cannot tile; penalize the squared
        // deviation lightly, gated on abundant open slack so tight fits are
        // never punished.
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 1 && open_bins_count > 2 {
            let dev = (post_residual as f64 - mean_residual) / cap;
            let open_space = mean_residual * open_bins_count as f64;
            if open_space > 1.5 * cap {
                score += 3.5 * dev * dev * (0.4 + 0.6 * progress);
            }
        }
        // MUTATION (gen 131): exact-fill chase for medium residuals — when
        // the post residual is within a hair of the next item, the two-step
        // lookahead already rewards it, but with several fitting bins the
        // best exact match can be diluted; sharpen the bonus by scarcity so
        // near-exact fits win out over merely adequate ones.
        if next_item_size > 0 && post_residual >= next_item_size && post_residual > 0 {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 5.0 && fitting_bins_count > 3 {
                score -= (6.0 - 1.0 * slack) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
    } else {
        let fragmentation = (mean_residual / cap) * open_bins_count as f64;
        let huge_item = item_size as f64 > 0.7 * cap;
        let remaining = if total_items > step_index { total_items - step_index } else { 1 };
        let remaining_frac = remaining as f64 / total_items.max(1) as f64;
        let fresh_post = cap - item_size as f64;
        let fresh_is_exact = fresh_post <= 4.0 && fresh_post >= 0.0;

        if fragmentation > 0.55 || (huge_item && open_bins_count > 4) {
            score -= 66.0 + 46.0 * remaining_frac;
        } else if fresh_is_exact {
            score -= 134.0 + 66.0 * remaining_frac;
        } else {
            score += 400.0 - 82.0 * remaining_frac;
            if fitting_bins_count <= 3 && open_bins_count > 2 {
                score -= 30.0 + 18.0 * remaining_frac;
            }
        }

        let fresh_match = (fresh_post - mean_residual).abs() / cap;
        if fresh_match < 0.05 {
            score -= 76.0 * (1.0 - fresh_match / 0.05);
        }
        if remaining_frac < 0.05 && fresh_post > 0.0 && !fresh_is_exact {
            score += 160.0 * (fresh_post / cap);
        }
        if fresh_post > 0.0 && fresh_post <= 22.0 && !fresh_is_exact {
            score -= 26.0 * (1.0 - fresh_post / 22.0);
        }
        if fresh_post > 22.0 && fresh_post <= 40.0 && fragmentation < 0.35 {
            score -= 12.5 * (1.0 - (fresh_post - 22.0) / 18.0);
        }
        if fresh_post > 0.0 && fresh_match < 0.12 && fragmentation < 0.55 {
            score -= 30.0 * (1.0 - fresh_match / 0.12);
        }
        if next_item_size > 0 && fresh_post > 0.0 {
            let fresh_exact_next = (fresh_post as u32) == next_item_size;
            let open_can_next = mean_residual >= next_item_size as f64;
            if fresh_exact_next && !open_can_next && fitting_bins_count <= 2 {
                score -= 52.0 * (1.0 - progress);
            }
            if (fresh_post as u32) < next_item_size && mean_residual > next_item_size as f64 {
                score += 21.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && fresh_post > next_item_size as f64 {
            let chain_post = fresh_post - next_item_size as f64;
            if chain_post <= 4.0 {
                score -= 34.0 * (1.0 - chain_post / 4.0) * (0.5 + 0.5 * (1.0 - progress));
            } else if chain_post <= 10.0 {
                score -= 9.5 * (1.0 - (chain_post - 4.0) / 6.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        if remaining_frac < 0.12 && fresh_post > 0.0 && !fresh_is_exact && mean_residual * open_bins_count as f64 > 3.0 * cap {
            score += 42.0 * (1.0 - remaining_frac / 0.12);
        }
        if fitting_bins_count == 1 && fresh_post > 0.0 && next_item_size > 0 {
            let stranded_here = bin_capacity.saturating_sub(item_size);
            let would_strand = stranded_here < next_item_size;
            if would_strand && stranded_here > 0 && stranded_here <= 8 {
                score -= 32.0 * (1.0 - progress);
            }
        }
        let open_capacity = mean_residual * open_bins_count as f64;
        let per_item_need = cap * 0.5;
        if remaining_frac > 0.25 && open_capacity < per_item_need * open_bins_count.max(1) as f64 * 0.5 {
            score -= 18.0 * (1.0 - progress);
        }
        if next_item_size > 0 && fresh_post > next_item_size as f64 {
            let after_next = fresh_post - next_item_size as f64;
            if after_next > 0.0 && after_next <= 8.0 && fragmentation < 0.5 {
                score -= 20.0 * (1.0 - after_next / 8.0) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        if next_item_size > 0 && fresh_post > 0.0 && (fresh_post as u32) < next_item_size {
            let slack_total = mean_residual * open_bins_count as f64;
            if slack_total > 2.0 * cap {
                score += 26.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && (fresh_post as u32) == next_item_size && fragmentation > 0.3 {
            score -= 44.0 * (0.5 + 0.5 * (1.0 - progress));
        }
        if fresh_post > 0.5 * cap && mean_residual < 0.2 * cap && remaining_frac > 0.3 && open_bins_count > 3 {
            score += 24.0 * (fresh_post / cap - 0.5) * 2.0 * (1.0 - progress);
        }
        if fitting_bins_count <= 1 && fresh_post > 0.45 * cap && next_item_size > 0 {
            let reachable = (next_item_size as f64 / fresh_post).min(1.0);
            if reachable < 0.5 {
                score += 18.0 * (0.5 - reachable) * (1.0 - progress);
            }
        }
        if next_item_size > 0 && fresh_post > 0.0 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 2 && fragmentation < 0.5 {
                score -= 7.0 * ((reps as f64).min(4.0) - 1.0) * (0.4 + 0.6 * (1.0 - progress));
                if rem <= 3 {
                    score -= 5.0 * (1.0 - progress);
                }
            }
        }
        if fresh_post > 0.35 * cap && remaining_frac > 0.2 && mean_residual * open_bins_count as f64 > 4.0 * cap && fragmentation < 0.45 {
            score += 20.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        if remaining_frac < 0.15 && fresh_post > 0.3 * cap {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.35;
            if open_space > est_need {
                score += 55.0 * (1.0 - remaining_frac / 0.15);
            }
        }
        if remaining_frac >= 0.15 && remaining_frac < 0.45 && fresh_post > 0.4 * cap && fragmentation > 0.4 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.45;
            if open_space > est_need {
                score += 28.0 * (1.0 - remaining_frac / 0.45);
            }
        }
        if next_item_size > 1 && fresh_post > 0.0 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 2 && rem == 0 && fragmentation < 0.4 {
                score -= 10.0 * ((reps as f64).min(4.0) - 1.0) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        if remaining_frac >= 0.45 && remaining_frac < 0.5 && fresh_post > 0.45 * cap && fragmentation > 0.5 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.55;
            if open_space > est_need {
                score += 22.0 * (1.0 - remaining_frac / 0.5);
            }
        }
        // gen 76: demand-aware fresh-bin refusal.
        if remaining_frac >= 0.05 && fresh_post > 0.3 * cap && next_item_size > 0 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (next_item_size as f64) * 0.42;
            if open_space > 1.15 * est_need {
                score += 30.0 * (1.0 - remaining_frac) * (fresh_post / cap - 0.3);
            }
        }
        // gen 76: fresh-bin dead-space cap.
        if fresh_post > 0.35 * cap && next_item_size > 0 && (fresh_post as u32) < next_item_size && fragmentation < 0.4 && remaining_frac > 0.15 {
            score += 16.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        // gen 81: tileability-aware open — when the fresh bin's post-residual
        // is an exact multiple of the next item size with three or more
        // repetitions, opening creates a perfectly tileable bin.
        if next_item_size > 1 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 3 && rem == 0 && fragmentation < 0.3 {
                score -= 14.0 * ((reps as f64).min(5.0) - 2.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // MUTATION (gen 131): mean-matching open bonus — a fresh bin whose
        // post-residual sits close to the fleet's mean residual harmonizes
        // the residual distribution, letting future items tile across all
        // open bins uniformly; reward the closeness when slack is abundant
        // so the open is not starved elsewhere.
        if fresh_post > 0.0 && mean_residual > 0.0 && remaining_frac > 0.1 && open_bins_count > 2 {
            let open_space = mean_residual * open_bins_count as f64;
            if open_space > 1.5 * cap {
                let dev = (fresh_post - mean_residual).abs() / cap;
                if dev < 0.1 {
                    score -= 12.0 * (1.0 - dev / 0.1) * (0.5 + 0.5 * (1.0 - progress));
                }
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post residual) with a non-linear term.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += 40.0 * tightness * tightness;

    // Reward filling bins to near-capacity (post_residual very small).
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly in post residual, big bonus; if it fits, small bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= 5.0;
        } else {
            // Next item cannot fit here: slight penalty for wasted lookahead opportunity.
            score += 3.0;
        }
    }

    // Penalize opening new bins when decent open bins exist.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // A new bin is attractive only if the item is large and fits poorly elsewhere,
        // or if no open bin fits (fitting_bins_count == 0 for the new-bin candidate call).
        score += 15.0 + 0.3 * open_bins_count as f64;
        if item_size >= 50 {
            score -= 8.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Global residual balance: prefer bins whose residual is below the mean (tighter bins),
    // discouraging scattering across many loose bins.
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score -= 2.0;
    } else {
        score += 1.5;
    }

    // Mild penalty for using many bins: encourage reuse of already-open bins.
    score -= 0.05 * open_bins_count as f64;

    // Small time-horizon coupling: early in stream, slightly favor new bins to build
    // a diverse bin pool; late, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 2.0 * (is_new_bin as i32 as f64) * -1.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Layered dead-space rewards (lower post_residual = better).
    if post_residual == 0 {
        score -= 980.0;
    } else if post_residual <= 4 {
        score -= 250.0 + 4.2 * (4 - post_residual) as f64;
    } else if post_residual <= 10 {
        score -= 64.0 + 3.6 * (10 - post_residual) as f64;
    } else if post_residual <= 22 {
        score -= 13.5 + 1.5 * (22 - post_residual) as f64;
    } else if post_residual <= 32 {
        score -= 5.0 + 0.7 * (32 - post_residual) as f64;
    } else if post_residual <= 48 {
        score -= 1.2 + 0.22 * (48 - post_residual) as f64;
    } else {
        score -= 1.2 - 0.014 * (post_residual as f64 - 48.0);
    }

    let w = 0.33 + 0.67 * progress * progress;
    score *= w;

    // Lookahead coupling with the next item.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if next_item_size < post_residual {
            let two_step_waste = (post_residual - next_item_size) as f64;
            if two_step_waste <= 8.0 {
                score -= 135.0 - 2.3 * two_step_waste;
            } else {
                score -= 72.0 - 0.58 * two_step_waste;
            }
            if two_step_waste <= 3.0 {
                score -= 48.0;
            }
        } else {
            let miss = (next_item_size - post_residual) as f64;
            score += 0.95 * miss;
            if miss > 26.0 {
                score += 0.55 * (miss - 26.0);
            }
        }
    }

    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
        let boost = 36.0 + 26.0 * scarcity;
        score -= boost * (1.0 - slack / cap) * (0.6 + 0.4 * (1.0 - progress));
        if fitting_bins_count <= 2 {
            score -= 15.0 * (1.0 - slack / cap);
