        // slack elsewhere is large, the leftover here is pure dead space;
        // penalize proportionally so residual variance shrinks.
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
            && fitting_bins_count > 1 {
            let open_space = mean_residual * open_bins_count as f64;
            if open_space > 2.0 * cap {
                let frac = post_residual as f64 / next_item_size as f64;
                score += 10.0 * (1.0 - frac) * (0.5 + 0.5 * progress);
            }
        }
        // gen 81: consolidation pull — prefer the bin whose placement brings
        // it closest to full relative to competing bins, tightening
        // late-stream residual spread.
        if post_residual > 0 && fitting_bins_count > 2 && progress > 0.5 {
            let fill = 1.0 - post_residual as f64 / cap;
            score -= 5.0 * fill * (progress - 0.5);
        }
        // MUTATION (gen 131): mid-stream variance squeeze — extend the
        // consolidation pull earlier and weight it by how far this bin's
        // post-residual sits from the mean residual, so the chosen bin is
        // the one that both fills deeply and drags the residual pool toward
        // a uniform, reusable size.
        if post_residual > 0 && fitting_bins_count > 2 && progress > 0.3 {
            let fill = 1.0 - post_residual as f64 / cap;
            let dev = (post_residual as f64 - mean_residual).abs() / cap;
            score -= 3.0 * fill * (progress - 0.3) * (1.0 - 0.5 * dev);
        }
        // MUTATION (gen 131): pair-completion gradient — when the post
        // residual is just under the next item, the leftover can never be
        // used by the next item but might pair with the item after; reward
        // placements whose leftover is small in absolute terms (<= 6) since
        // tiny leftovers are the cheapest form of waste.
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
            && post_residual <= 6 {
