        // slivers into chained placements.
        if next_item_size > 0 && post_residual > next_item_size {
            let tail = post_residual - next_item_size;
            if tail >= 1 && tail <= 12 {
                let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
                score -= (6.0 + 5.0 * scarcity) * (1.0 - tail as f64 / 12.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // MUTATION (gen 132): high-dead-space refusal — when the remaining
        // dead space after this placement is large relative to the next
        // item and aggregate open slack already covers the next item,
        // penalize creating one more unusable pocket.
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
            && mean_residual >= next_item_size as f64 && fitting_bins_count > 2 {
