    // MUTATION (gen 127): triple-chain anticipation.
    if post_residual > 0 && next_item_size > 1 && post_residual > next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next % next_item_size == 0 && after_next >= next_item_size {
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            score -= (8.0 + 4.0 * scarcity.sqrt()) * (0.4 + 0.6 * (1.0 - progress));
        }
    }

    // MUTATION (gen 128): dead-space variance squeeze.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0 && fitting_bins_count > 1 {
        let excess = post_residual as f64 - next_item_size as f64;
        if excess > 14.0 && post_residual as f64 > mean_residual {
            let over = ((excess - 14.0) / cap).min(0.3);
            score += 5.5 * over * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    // MUTATION (gen 128): perfect-closure bonus.
    if next_item_size > 0 && post_residual == next_item_size && bin_residual != bin_capacity {
        let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
        score -= 34.0 * scarcity * (0.5 + 0.5 * (1.0 - progress));
    }

    // MUTATION (gen 128): near-miss gradient.
    if next_item_size > 0 && post_residual > next_item_size {
        let waste = (post_residual - next_item_size) as f64;
        if waste <= 2.0 {
            score -= 20.0 * (1.0 - waste / 2.0) * (1.0 - progress);
        }
    }

    // MUTATION (gen 133): two-step closure squeeze — combine fine-grained
    // residual fitting with lookahead: when placing the item here AND the
    // next item afterwards leaves a near-zero tail, prefer this bin
    // proportionally to the scarcity of alternatives (targets the
    // diagnosed dead-space weakness directly).
    if next_item_size > 0 && post_residual > next_item_size && bin_residual != bin_capacity {
        let tail = (post_residual - next_item_size) as f64;
        if tail <= 3.0 {
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            score -= (18.0 + 10.0 * scarcity) * (1.0 - tail / 3.0) * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    // MUTATION (gen 133): oversized-strand penalty — when this placement
    // strands a residual the next item cannot use while aggregate open
    // slack elsewhere could absorb it, penalize harder late in the stream
    // where stranded slack is unrecoverable.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0
        && post_residual < next_item_size && fitting_bins_count > 1
        && mean_residual * open_bins_count as f64 > 1.5 * cap {
        let stranded = (next_item_size - post_residual) as f64;
        score += 4.0 * (stranded / cap).min(0.3) * (0.3 + 0.7 * progress);
    }

    // MUTATION (gen 133): mid-band residual alignment — reward placements
    // whose post-residual sits within a tight band around the next item's
    // size, sharpening the fine-grained fit the parent left coarse in the
    // 4..=10 waste zone.
    if next_item_size > 0 && post_residual > next_item_size {
        let waste = (post_residual - next_item_size) as f64;
        if waste > 2.0 && waste <= 6.0 {
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            score -= (8.0 + 5.0 * scarcity) * (1.0 - (waste - 2.0) / 4.0) * (0.4 + 0.6 * (1.0 - progress));
        }
    }

    if bin_residual == bin_capacity {
        // NEW-BIN CANDIDATE branch.
        let fragmentation = (mean_residual / cap) * open_bins_count as f64;
        let huge_item = item_size as f64 > 0.7 * cap;
        let remaining = if total_items > step_index { total_items - step_index } else { 1 };
        let remaining_frac = remaining as f64 / total_items.max(1) as f64;
        let fresh_post = cap - item_size as f64;
        let fresh_is_exact = fresh_post <= 4.0 && fresh_post >= 0.0;

        if fragmentation > 0.55 || (huge_item && open_bins_count > 4) {
