        }
        // Fresh-bin residual-magnitude guard.
        if fresh_post > 0.35 * cap && remaining_frac > 0.2 && mean_residual * open_bins_count as f64 > 4.0 * cap && fragmentation < 0.45 {
            score += 20.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        // Single-fit fresh-bin rescue.
        if fitting_bins_count <= 1 && fresh_post > 0.0 && next_item_size > 0 {
            let stranded_here = bin_capacity.saturating_sub(item_size);
            let would_strand = stranded_here < next_item_size;
            if would_strand && stranded_here > 0 && stranded_here <= 8 {
                score -= 32.0 * (1.0 - progress);
            }
        }
        // Residual-harmony fresh-bin bonus.
        if fresh_post > 0.0 && fresh_match < 0.2 && fragmentation < 0.5 && remaining_frac > 0.1 {
            score -= 14.0 * (1.0 - fresh_match / 0.2) * (0.5 + 0.5 * (1.0 - progress));
        }
        // MUTATION (gen 127): demand-cushion fresh-bin gate.
        if remaining_frac > 0.1 && fresh_post > 0.45 * cap && next_item_size > 0 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (next_item_size as f64) * 0.5;
            if open_space > 1.3 * est_need {
                score += 24.0 * (1.0 - remaining_frac) * (fresh_post / cap - 0.45);
            }
        }
        // MUTATION (gen 127): tileable-lane fresh bonus.
        if next_item_size > 1 && fresh_post > 0.0 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            let open_space = mean_residual * open_bins_count as f64;
            if reps >= 2 && rem == 0 && open_space < 1.5 * cap {
                score -= 16.0 * ((reps as f64).min(4.0) - 1.0) * (1.0 - progress);
            }
        }
        // MUTATION (gen 128): fresh-bin exact-closure lane.
        if next_item_size > 0 && fresh_post > 0.0 && (fresh_post as u32) == next_item_size {
            score -= 40.0 * (0.5 + 0.5 * (1.0 - progress));
        }
        // MUTATION (gen 128): oversized-fresh refusal.
        if fresh_post > 0.55 * cap && next_item_size > 0 && (fresh_post as u32) < next_item_size
            && mean_residual * open_bins_count as f64 > 2.0 * cap {
            score += 30.0 * (fresh_post / cap - 0.55) * (0.5 + 0.5 * (1.0 - progress));
        }
        // MUTATION (gen 133): fresh-bin near-exact closure — when the fresh
        // bin's leftover is within 3 of the next item size, opening here
        // sets up a near-perfect two-step fill; reward scaled by scarcity
        // so it fires only when alternatives are poor.
        if next_item_size > 0 && fresh_post > 0.0 && (fresh_post as u32) > next_item_size {
            let tail = (fresh_post as u32 - next_item_size) as f64;
            if tail <= 3.0 {
                let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
                score -= (16.0 + 9.0 * scarcity) * (1.0 - tail / 3.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modular structure on capacity fractions
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // residual as capacity fraction

    // Penalize dead space: residuals that are too small to be useful later
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual == 0 {
        // perfect fit: strong reward
        score -= 200.0;
    }

    // Harmonic thresholds: bins whose residual falls on "usable" classes get rewarded
    // usable classes: residual >= 40, or in [20..=39] divisible by 10
    if post_residual >= 40 {
        score -= 25.0;
    } else if post_residual >= 20 {
        if post_residual % 10 == 0 {
            score -= 12.0;
        } else {
            score += 8.0;
        }
    }

    // Modulo coupling with next item: if next item fits the post residual exactly, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size < post_residual {
            let nxt = next_item_size as f64;
            score -= 10.0 * (nxt / (pr + 1.0)); // prefer bins leaving room for next item
            // harmonic class match: next_item and post_residual share residue class mod 10
            if post_residual % 10 == next_item_size % 10 {
                score -= 6.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless residual is very tight
    if bin_residual == bin_capacity {
        // empty bin: neutral-ish baseline; penalize if current item is small and many bins open
        score = cap * 0.5 + 30.0 * (item_size as f64 / cap);
        if open_bins_count > 0 && fitting_bins_count > 0 {
            score += 55.0; // discourage new bin when alternatives exist
        }
        if next_item_size > 0 && next_item_size >= 60 {
            score -= 20.0; // big next item: fresh bin may be valuable
        }
    }

    // Tight-fit reward: item fills most of the bin
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill;

    // Progress coupling: later in stream, be greedier about tight packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 15.0 * progress * (1.0 - frac);

    // Mean residual alignment: prefer bins near mean residual (balance)
    let dev = (pr - mean_residual).abs();
    score += 0.15 * dev;

    score
}

