            }
        }
        // MUTATION (gen 128): fresh-bin exact-closure lane.
        if next_item_size > 0 && fresh_post > 0.0 && (fresh_post as u32) == next_item_size {
            score -= 40.0 * (0.5 + 0.5 * (1.0 - progress));
        }
        // MUTATION (gen 128): oversized-fresh refusal.
        if fresh_post > 0.55 * cap && next_item_size > 0 && (fresh_post as u32) < next_item_size
            && mean_residual * open_bins_count as f64 > 2.0 * cap {
            score += 30.0 * (fresh_post / cap - 0.55) * (0.5 + 0.5 * (1.0 - progress));
        }
        // MUTATION (gen 134): fresh-bin chain-tail bonus — when the fresh
        // bin's leftover after placing the next item is a tiny tail
        // (<= 4), the new bin converts slack into near-perfect fills;
        // reward scaled by remaining stream so early opens are preferred.
        if next_item_size > 1 && fresh_post > next_item_size as f64 {
            let tail = fresh_post - next_item_size as f64;
            if tail > 0.0 && tail <= 4.0 {
                score -= (26.0 + 14.0 * (1.0 - tail / 4.0)) * (0.3 + 0.7 * remaining_frac);
            }
        }
        // MUTATION (gen 134): fresh-bin waste-to-mean alignment — refuse a
        // fresh bin whose leftover is far above the current mean residual
        // when plenty of open slack exists (reduces residual variance).
        if fresh_post > 0.0 && mean_residual > 0.0 && open_bins_count > 2 {
            let over = fresh_post - mean_residual;
            if over > 0.25 * cap && mean_residual * open_bins_count as f64 > 2.0 * cap {
                score += 22.0 * ((over / cap).min(0.5)) * (0.5 + 0.5 * progress);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: prefer it only when no open bin offers a good fit.
    if bin_residual == bin_capacity {
        // Base penalty so a fresh bin is chosen only when existing bins score worse.
        score += bin_capacity as f64 * 0.55;
        // If many bins fit, discourage opening a new one further.
        if fitting_bins_count > 0 {
            score += 40.0 * (fitting_bins_count as f64).min(4.0);
        }
        // Late in the stream, closing out bins is cheaper than opening new ones.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 30.0 * progress;
        return score;
    }

    // --- Aggressive 2-step lookahead matching ---
    let next = next_item_size as f64;
    let post = post_residual as f64;

    if next > 0.0 {
        // Perfect 2-step match: post_residual exactly fits the next item.
        if post == next {
            score -= 60.0;
        } else if post > next {
            // Post residual can still hold the next item: reward tighter leftovers.
            let slack = post - next;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Post residual cannot fit the next item: penalize dead space,
            // worse when the leftover is small and thus hard to reuse.
            let dead = next - post;
            score += 0.8 * dead.min(60.0);
            // Tiny leftovers (< 10) are near-unusable dead space.
            if post < 10.0 {
                score += 15.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    } else if fitting_bins_count > 1 {
        // Among multiple fitting bins, prefer the one closest to being filled.
        score -= 10.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
    }

    // Prefer bins tighter than the mean residual (better packing discipline).
    score -= 0.15 * (mean_residual - post);
    // But penalize bins far looser than mean (fragmented outliers).
    if post as f64 > mean_residual + 20.0 {
        score += 0.3 * (post - mean_residual - 20.0);
    }

    // Reward high fill ratio mildly.
    score -= 0.1 * (item_size as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
