        // deepen the existing fresh_match reward in the mid-stream regime.
        if fresh_post > 0.0 && fresh_match < 0.08 && remaining_frac > 0.2 && remaining_frac < 0.75 && fragmentation < 0.45 {
            score -= 18.0 * (1.0 - fresh_match / 0.08) * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are strongly favored
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Dead-space penalty for small leftovers that few items can use
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 8.0;
        }
        // Pairing bonus: residual exactly matches next item
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // Last-chance bin: strong incentive to use it before opening a new one
    if fitting_bins_count == 1 {
        score -= 35.0;
    } else if fitting_bins_count > 2 {
        // Many alternatives: be pickier, penalize loose fits
        score += 6.0 * (1.0 - fit_ratio);
    }

    // Prefer filling bins with below-average residual (balance avoidance of many half-full bins)
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Time horizon: early in the stream, keep options open (penalize very low post-residual less);
    // late in the stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 15.0 * progress * fit_ratio;

    // Many open bins: discourage spreading; favor new-bin when open bins are fragmented
    if open_bins_count > 8 {
        score += 0.5 * (open_bins_count as f64 - 8.0);
    }

    // New-bin candidate evaluation: attractive when item is large relative to capacity
    // and no tight fit exists is handled by comparison; give new bin a mild default pull
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * (1.0 - item_size as f64 / bin_capacity as f64);
    }

    score
}

