        }
        if remaining_frac >= 0.45 && remaining_frac < 0.5 && fresh_post > 0.45 * cap && fragmentation > 0.5 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.55;
            if open_space > est_need {
                score += 22.0 * (1.0 - remaining_frac / 0.5);
            }
        }
        // gen 76: demand-aware fresh-bin refusal.
        if remaining_frac >= 0.05 && fresh_post > 0.3 * cap && next_item_size > 0 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (next_item_size as f64) * 0.42;
            if open_space > 1.15 * est_need {
                score += 30.0 * (1.0 - remaining_frac) * (fresh_post / cap - 0.3);
            }
        }
        // gen 76: fresh-bin dead-space cap.
        if fresh_post > 0.35 * cap && next_item_size > 0 && (fresh_post as u32) < next_item_size && fragmentation < 0.4 && remaining_frac > 0.15 {
            score += 16.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        // gen 81: tileability-aware open.
        if next_item_size > 1 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 3 && rem == 0 && fragmentation < 0.3 {
                score -= 14.0 * ((reps as f64).min(5.0) - 2.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // MUTATION (gen 135): closure-track open — when the fresh bin's
        // post-residual is within 3 units of the next item, opening creates a
        // bin that closes exactly on the next placement; reward it scaled by
        // remaining stream so early exact matches are not over-weighted.
        if next_item_size > 0 && fresh_post > 0.0 {
            let gap = fresh_post - next_item_size as f64;
            if gap > 0.0 && gap <= 3.0 {
                score -= 22.0 * (1.0 - gap / 3.0) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: the smaller the post_residual relative to capacity, the better.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 0.6 * tightness * (bin_capacity as f64);

    // Exact fit is highly desirable.
    if post_residual == 0 {
        score -= 50.0;
    }

    // 2-step lookahead: reward if the next item fits exactly or well into post_residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let next_tight = 1.0 - ((post_residual - next_item_size) as f64) / (bin_capacity as f64);
            score -= 1.5 * next_tight * (bin_capacity as f64);
            if next_item_size == post_residual {
                score -= 25.0; // perfect 2-chain
            }
        } else {
            // Next item cannot follow here: dead space risk grows with post_residual.
            score += 0.35 * (post_residual as f64);
        }
    } else {
        // Last item: prefer filling an existing bin as tightly as possible.
        score -= 20.0;
    }

    // Penalize bins that are far below the mean residual (wasted space hoarding),
    // unless this is the only fitting bin.
    let dev = (bin_residual as f64) - mean_residual;
    score += 0.15 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is large and
    // no open bin offers a good fit. Empty-bin call has post_residual == bin_capacity.
    if bin_residual == bin_capacity {
        let poor_fit = if next_item_size > 0 {
            (next_item_size as f64) > (post_residual as f64)
        } else {
            false
        };
        let pressure = (item_size as f64) / (bin_capacity as f64);
        // Keep new bins relatively costly; only attractive for big items with lookahead mismatch.
        score += 30.0 - 10.0 * pressure + if poor_fit { 0.0 } else { 12.0 };
        // More open bins => discourage opening yet another one.
        score += 0.5 * (open_bins_count as f64);
    }

    // Mild stream-progression tilt: later in the stream, prefer consolidating.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 4.0 * progress * ((post_residual as f64) / (bin_capacity as f64));

    score
}

