        if fresh_post >= 13.0 && fresh_post <= 24.0 && mean_residual * open_bins_count as f64 > cap {
            score += 14.0 * (1.0 - (fresh_post - 13.0) / 11.0) * (0.5 + 0.5 * (1.0 - progress));
