                    score -= 7.0 * (tail_fit - 0.85) / 0.15 * (0.5 + 0.5 * (1.0 - progress));
                }
            }
        }
        // MUTATION (gen 137): late-stream exact-closure — near the end of the
        // stream, a placement that empties a bin entirely frees an open slot;
        // deepen the reward as remaining items shrink so residual variance
        // cannot linger in half-full bins.
