            && fitting_bins_count > 1 {
            let open_space = mean_residual * open_bins_count as f64;
            if open_space > 2.0 * cap {
                let frac = post_residual as f64 / next_item_size as f64;
                score += 10.0 * (1.0 - frac) * (0.5 + 0.5 * progress);
                if progress > 0.6 && frac < 0.5 {
                    score += 4.0 * (0.5 - frac) * (progress - 0.6);
                }
            }
        }
        // gen 81: consolidation pull (refined: also engage earlier with a
        // gentler slope so residual spread tightens across the whole stream,
        // attacking the diagnosed residual-variance weakness).
        if post_residual > 0 && fitting_bins_count > 2 {
            let fill = 1.0 - post_residual as f64 / cap;
            if progress > 0.5 {
                score -= 5.0 * fill * (progress - 0.5);
            } else if progress > 0.25 {
                score -= 2.0 * fill * (progress - 0.25);
            }
        }
        // MUTATION (gen 137): residual-variance squeeze — when the placement
        // lands the bin's residual close to the fleet mean residual, reward
        // it; residuals far below mean strand space that no future item of
        // typical size can use, so penalize proportional deviation mildly.
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 1 {
            let dev = (post_residual as f64 - mean_residual).abs() / cap;
            if dev < 0.06 {
                score -= 7.0 * (1.0 - dev / 0.06) * (0.5 + 0.5 * (1.0 - progress));
            } else if dev > 0.3 {
                score += 2.8 * ((dev - 0.3) / 0.4).min(1.0) * (0.4 + 0.6 * progress);
            }
        }
        // MUTATION (gen 137): perfect-closure lookahead — if placing the item
        // here leaves exactly the next item's size, the next step closes this
        // bin completely; deepen the reward when few bins fit the next item.
        if next_item_size > 0 && post_residual == next_item_size && fitting_bins_count > 3 {
