        // remain and the fresh leftover exceeds what the next item can use,
        // refuse firmly since stranded slack can no longer be recovered.
        if remaining_frac < 0.08 && fresh_post > 0.0 && next_item_size > 0
            && (fresh_post as u32) > next_item_size {
            score += 36.0 * (1.0 - remaining_frac / 0.08) * (fresh_post / cap);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit), normalized.
    score = post_residual as f64 * 1.0;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 / (1.0 + diff);
        // Perfect chain: next item exactly fills this bin afterwards.
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize leaving a dead space smaller than the minimum item size (1..100 unknown range,
        // use post_residual relative to lookahead).
        if post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: just minimize waste.
        score += 10.0;
    }

    // Relative to mean residual: bins with residual below mean are scarcer; slight reward
    // for packing into them, penalty for using roomy bins when mean is low.
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: make an empty bin unattractive unless the fit is bad
    // or the item is large relative to residual of open bins.
    if bin_residual == bin_capacity {
        // Empty-bin baseline: slightly worse than a decent tight fit.
        score += 15.0;
        // But if item is huge, opening a fresh bin is fine (avoid splitting).
        if item_size >= bin_capacity * 3 / 4 {
            score -= 35.0;
        }
        // Early stream: opening bins cheaply builds a portfolio of residuals.
        if total_items > 0 && (step_index as f64) / (total_items as f64) < 0.25 {
            score -= 8.0;
        }
    }

    // Mild penalty for wasting large residuals on small items (create usable space, not crumbs).
    if post_residual > 40 {
        score += 0.15 * (post_residual - 40) as f64;
    }

    // Prefer densifying when many bins are open.
    score += 0.05 * open_bins_count as f64;

    score
}

