    let mut score = post_residual as f64;

    // Penalize small but nonzero post-residuals (unusable dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Reward perfect or near-perfect fits.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // Next item cannot use the leftover space: penalize proportionally.
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bonus: this is the only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Prefer filling bins that are already relatively full.
    let fullness = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fullness * 6.0;

    // Mild penalty when this bin's residual deviates far below the mean residual
    // (keeps a diverse pool of residuals for future items).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Late in the stream: be more conservative, prefer new bins over tight squeezes.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 3.0;

    // Many open bins: discourage opening yet another bin, encourage consolidation.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus scaling with open bin count.
        score += 5.0 + open_bins_count as f64 * 1.5;
        // A new bin is attractive if the item is large and fits poorly elsewhere.
        score -= item_size as f64 * 0.05;
    } else {
        // Slight reward for using existing bins when many are open.
        score -= open_bins_count.min(20) as f64 * 0.3;
    }

    score
}

