        if post_residual > 0 && fitting_bins_count > 2 && progress > 0.4 {
            let fill = 1.0 - post_residual as f64 / cap;
            let scarcity = (3.0_f64.min(fitting_bins_count as f64) - 1.0) / 2.0;
            score -= 6.0 * fill * (progress - 0.4) * (0.7 + 0.3 * scarcity);
        }
        // MUTATION (gen 140): residual-homogenization term — when this bin's
        // post-residual lands close to the mean open residual, the leftover
        // is more likely to be consumed by future items of typical size;
        // reward such harmonization, especially mid-to-late stream where
        // variance compounding dominates waste.
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 1 && progress > 0.3 {
            let dev = (post_residual as f64 - mean_residual).abs() / cap;
            if dev < 0.12 {
                let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
                score -= 8.5 * (1.0 - dev / 0.12) * (0.5 + 0.5 * progress) * (0.6 + 0.4 * scarcity);
            }
        }
        // MUTATION (gen 140): two-step exact-chain lookahead — if placing the
        // next item here would leave a residual that exactly matches the
        // next item size again (a repeatable chain), the bin becomes a
        // self-consuming lane; deepen the existing chain reward for the
        // tightest case where post_residual is 2x the next item.
