            if open_space > 2.0 * cap {
                let frac = post_residual as f64 / next_item_size as f64;
                score += 10.0 * (1.0 - frac) * (0.5 + 0.5 * progress);
            }
        }
        // MUTATION (gen 81): consolidation pull — prefer the bin whose
        // placement brings it closest to full relative to competing bins,
        // tightening late-stream residual spread.
        if post_residual > 0 && fitting_bins_count > 2 && progress > 0.5 {
            let fill = 1.0 - post_residual as f64 / cap;
            score -= 5.0 * fill * (progress - 0.5);
        }
        // MUTATION (gen 141): residual-variance homogenizer — the diagnosed
        // weakness is residual spread. When the post-residual deviates from
        // the mean open residual, nudge the score toward bins that land
        // near the fleet-wide residual, with weight ramping mid-stream so
        // early exact fits are not disturbed.
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 1 && progress > 0.2 {
            let dev = (post_residual as f64 - mean_residual).abs() / cap;
            if dev > 0.06 {
                score += 3.2 * (dev - 0.06) * (progress - 0.2);
