        // after placing the next item still fits a fraction of itself, the
        // bin supports a chain of future items; reward tight chains more
        // when open slack is scarce so we squeeze the last drops of space.
        if next_item_size > 1 && post_residual > next_item_size {
            let after_next = post_residual - next_item_size;
            if after_next >= next_item_size {
                let chain_reps = after_next / next_item_size;
                let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
