}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += 12.0 * tightness * tightness;

    // Penalize exact-fit waste asymmetry: bonus when item nearly fills bin.
    if post_residual < 10 {
        score -= 8.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // New-bin candidate handling: empty bins get a baseline penalty that
    // shrinks when no good option exists (large post_residual elsewhere)
    // or when many items remain (future flexibility is valuable).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        let mut new_bin_penalty = 20.0;
        // If existing bins would leave big dead space, opening a new bin is fine.
        if post_residual as f64 > mean_residual + 10.0 {
            new_bin_penalty -= 10.0;
        }
        // Early in the stream, prefer new bins to build diverse residuals.
        new_bin_penalty -= 8.0 * (1.0 - progress);
        // Lookahead: if next item is large, a fresh bin is attractive.
        if next_item_size > 60 {
            new_bin_penalty -= 6.0;
        }
        score += new_bin_penalty;
    }

    // Lookahead coupling: placing item here should leave space compatible
    // with the next item. Penalize when post_residual is just barely too
    // small for the next item (wasted opportunity).
    if next_item_size > 0 && post_residual > 0 {
        if (post_residual as u64) < (next_item_size as u64) {
            let gap = (next_item_size as f64 - post_residual as f64);
            if gap < 25.0 {
                score += 5.0 * (1.0 - gap / 25.0);
            }
        } else {
            // Reward bins whose post-residual can host the next item.
            score -= 3.0;
        }
    }

    // Global state: many open bins with high mean residual -> prefer
    // consolidating into bins below the mean (reduce fragmentation).
    if open_bins_count > 4 {
        let dev = (bin_residual as f64 - mean_residual);
        if dev < 0.0 {
            score += 0.05 * dev.abs() * (open_bins_count as f64).ln();
        }
    }

    // Late in the stream, avoid leaving tiny unusable residuals.
    if progress > 0.7 && post_residual > 0 && post_residual < 20 {
        score += 6.0 * progress;
    }

    score
}

