    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let base = pr / cap;

    // Smooth non-linear coupling: polynomial in post_residual scaled by progress
    let mut score = pr as f64;

    // Penalize large post-residual more as stream progresses (waste matters later)
    score += 40.0 * base * base * (0.5 + progress);

    // Reward tight fits (small post_residual) with a smooth bump
    score -= 25.0 * (1.0 - base) * (1.0 - base) * (0.3 + 0.7 * progress);

    // Lookahead coupling: favor bins whose post-residual can host next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let slack = (pr - nx) / cap;
            score -= 15.0 * (1.0 - slack) * (0.4 + 0.6 * progress);
        } else {
            let gap = (nx - pr) / cap;
            score += 20.0 * gap * gap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - base);
    }

    // Mild pressure toward consolidating into fewer bins when many are open
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * base;

    // Divergence from mean residual: prefer bins with residuals near the mean (balance)
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev * (1.0 - progress);

    // New-bin candidate: penalize mildly so only clearly bad fits open new bins
    if bin_residual == bin_capacity {
        score += 12.0 + 10.0 * progress;
    }

    score
}

