        // bin's leftover can be exactly closed by the next item, opening is
        // dead-space-free; but if open slack elsewhere already exceeds the
        // projected demand, suppress the open so slack doesn't accumulate.
        if next_item_size > 0 && fresh_post > 0.0 {
            let open_space = mean_residual * open_bins_count as f64;
            if (fresh_post as u32) >= next_item_size && open_space < 2.0 * cap {
                score -= 12.0 * (1.0 - progress);
            } else if (fresh_post as u32) < next_item_size && open_space > 2.5 * cap {
                score += 15.0 * (fresh_post / cap) * (0.4 + 0.6 * progress);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity-fraction bucket it lands in.
    // Classes: 0 (perfect/zero), 1 (tiny dead space <=10), 2 (<=25), 3 (<=50), 4 (>50).
    let pr = post_residual as u32;
    let class = if pr == 0 { 0u32 }
        else if pr <= 10 { 1 }
        else if pr <= 25 { 2 }
        else if pr <= 50 { 3 }
        else { 4 };

    // Reward low classes steeply (super-linear penalty for dead space).
    score -= (4 - class) as f64 * 18.0;

    // Modulo arithmetic on post_residual: residuals divisible by common item sizes
    // (multiples of 10, 5, 25) are more likely reusable by future items.
    let div10 = pr % 10 == 0;
    let div5 = pr % 5 == 0;
    let div25 = pr % 25 == 0;
    if div25 { score -= 12.0; }
    else if div10 { score -= 8.0; }
    else if div5 { score -= 4.0; }
    else { score += 5.0; } // odd residual: likely dead space

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr { score -= 40.0; }
        else if next_item_size < pr {
            let gap = pr - next_item_size;
            if gap <= 10 { score -= 20.0; }
            else if gap <= 25 { score -= 8.0; }
            else { score += gap as f64 * 0.25; }
        } else {
            // next item won't fit here: residual must survive longer waves; penalize mid residuals
            score += 6.0 + (pr as f64 - mean_residual).abs() * 0.1;
        }
    } else {
        // last item: prefer zero residual above all
        score -= (cap - pr as f64) * 0.5;
    }

    // Last-chance bin: strongly favor using the only fitting bin before opening a new one.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (i.e., this call is the fresh empty bin itself).
    if bin_residual == bin_capacity {
        // Base penalty so new bins are opened only when justified.
        score += 30.0;
        // More open bins -> prefer consolidating rather than spawning.
        score += open_bins_count as f64 * 2.0;
        // Late in the stream, opening new bins is less costly (fewer future items to waste).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 15.0;
        // If mean residual across open bins is small, consolidation is hopeless; new bin is fine.
        if mean_residual < item_size as f64 { score -= 20.0; }
    }

    // Mild preference for tight fills relative to bin capacity.
    score += (1.0 - (item_size as f64 / cap)) * 3.0;

    score
}

