                score -= 12.0 * (1.0 - progress) * (0.5 + 0.5 * (1.0 - fragmentation));
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: tiny unusable gaps (<10) are worthless; larger gaps are more usable.
    if post_residual < 10 {
        score += 60.0; // severe dead space
    } else {
        // Usability-weighted residual: prefer post_residuals that are large OR near-zero.
        let pr = post_residual as f64;
        let usable = (pr / bin_capacity as f64).powi(2);
        score += 25.0 * usable;
    }

    // Reward tight fits (small post_residual) more aggressively.
    score -= 40.0 * (1.0 - (post_residual as f64 / bin_capacity as f64)).powi(2) * (item_size as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is poor.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        let bad_fit = (post_residual as f64 / bin_capacity as f64) > 0.5;
        score += 45.0 * (1.0 - pressure) + if bad_fit { 20.0 } else { 0.0 };
        // Lookahead: if next item would fit in the new bin's full space, mildly encourage opening.
        if next_item_size > 0 && (next_item_size as f64) <= (bin_capacity as f64) {
            score -= 5.0;
        }
    }

    // Lookahead: if next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size < post_residual {
            score -= 10.0;
        } else {
            score += 8.0; // next item won't fit here; dead space likely
        }
    }

    // Open-bin pressure: discourage spreading across many bins when residuals are high.
    score += 2.0 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);

    // Slight preference for using existing bins as the stream progresses.
    score += 5.0 * (step_index as f64 / total_items.max(1) as f64);

    score
}

