    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-perfect match: next item fits with small dead space left after.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - gap / bin_capacity as f64);
    }
    // Penalize blocking the next item (next item won't fit in this bin).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        let gap = (next_item_size - post_residual) as f64;
        score += 10.0 * (gap / bin_capacity as f64);
    }

    // Reward tight fits (small dead space relative to capacity).
    score -= 15.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Compare against mean residual: prefer bins with residual below mean (tighter bins).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Mild exploration pressure: later in the stream, prefer compacting existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 5.0 * progress;

    // Slight penalty for opening a new bin when many bins are open.
    if bin_residual == bin_capacity {
        score += 3.0 + 0.05 * open_bins_count as f64;
    }

    score
}

