            }
        }
        // MUTATION (gen 142): micro-residual lookahead — when the post
        // residual is small (<= 10) but not exactly the next item, the
        // stranded hole is nearly worthless; penalize it so mid-tier
        // placements do not win over bins that would leave a drainable
        // larger residual. This sharpens the small-residual gradient
        // mid-stream where the diagnosed dead-space waste concentrates.
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
            && post_residual <= 10 && fitting_bins_count > 1 {
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            score += (14.0 - 0.8 * post_residual as f64) * scarcity * (0.5 + 0.5 * progress);
        }
        // MUTATION (gen 142): drain-competitiveness — if this bin's
        // post-residual is the tightest fit for the next item among all
        // fitting bins (few fitting bins means scarcity of exact fits),
        // reward landing the next item exactly; combining fine-grained
        // residual fitting with lookahead anticipation per lineage guidance.
