        }
        // gen 76: fresh-bin dead-space cap.
        if fresh_post > 0.35 * cap && next_item_size > 0 && (fresh_post as u32) < next_item_size && fragmentation < 0.4 && remaining_frac > 0.15 {
            score += 16.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        // gen 81: tileability-aware open.
        if next_item_size > 1 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 3 && rem == 0 && fragmentation < 0.3 {
                score -= 14.0 * ((reps as f64).min(5.0) - 2.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // gen 108: variance-aware open gate.
        if fresh_post > 0.0 && mean_residual > 0.0 && open_bins_count > 2 && remaining_frac > 0.1 {
            let rel_match = ((fresh_post - mean_residual) / (mean_residual + 2.0)).abs();
            if rel_match < 0.2 && fragmentation < 0.5 {
                score -= 11.0 * (1.0 - rel_match / 0.2) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        // gen 108: endgame drain-reserve.
        if remaining_frac < 0.08 && fresh_post > 0.05 * cap && !fresh_is_exact {
            let open_space = mean_residual * open_bins_count as f64;
            if open_space > cap {
                score += 34.0 * (1.0 - remaining_frac / 0.08) * (fresh_post / cap).min(1.0);
            }
        }
        // MUTATION (gen 142): micro-residual open bonus — when opening a
        // fresh bin leaves a residual <= 10 that the next item can almost
        // drain (within 4), that open is a near-zero-waste two-step chain;
        // reward it so dead-space waste is converted into exact fills.
        if fresh_post > 0.0 && (fresh_post as u32) <= 10 && next_item_size > 0
            && next_item_size <= fresh_post as u32 && fragmentation < 0.5 {
            let gap = fresh_post as f64 - next_item_size as f64;
            score -= 18.0 * (1.0 - gap / 10.0) * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) with a nonlinear bonus.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - progress);
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Penalize blocking the next item.
        score += 6.0 * (1.0 - (post_residual as f64) / (next_item_size as f64).max(1.0)).min(1.0);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Prefer bins with residual below mean residual (consolidate fullness).
    let dev = (bin_residual as f64) - mean_residual;
    score += 0.15 * dev;

    // Mild penalty on opening new bins when many bins are open and fit exists.
    if bin_residual == bin_capacity {
        score += 8.0 + 2.0 * (open_bins_count as f64).sqrt();
        // But allow new-bin opening late in stream if residual is very small.
        if progress > 0.8 && post_residual == 0 {
            score -= 15.0;
        }
    }

    // Exact fit reward.
    if post_residual == 0 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
