            }
        }
        // Fresh-bin dead-space cap.
        if fresh_post > 0.35 * cap && next_item_size > 0 && (fresh_post as u32) < next_item_size && fragmentation < 0.4 && remaining_frac > 0.15 {
            score += 17.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        // Tiling-aware fresh-bin bonus.
        if next_item_size > 1 && fresh_post > 0.0 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 2 && rem == 0 && fragmentation < 0.4 {
                score -= 10.0 * ((reps as f64).min(4.0) - 1.0) * (0.4 + 0.6 * (1.0 - progress));
            }
            if reps >= 3 && rem == 0 && fragmentation < 0.3 {
                score -= 14.0 * ((reps as f64).min(5.0) - 2.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // Fresh-bin residual-magnitude guard.
        if fresh_post > 0.35 * cap && remaining_frac > 0.2 && mean_residual * open_bins_count as f64 > 4.0 * cap && fragmentation < 0.45 {
            score += 20.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        // Single-fit fresh-bin rescue.
        if fitting_bins_count <= 1 && fresh_post > 0.0 && next_item_size > 0 {
            let stranded_here = bin_capacity.saturating_sub(item_size);
            let would_strand = stranded_here < next_item_size;
            if would_strand && stranded_here > 0 && stranded_here <= 8 {
                score -= 32.0 * (1.0 - progress);
            }
        }
        // Residual-harmony fresh-bin bonus.
        if fresh_post > 0.0 && fresh_match < 0.2 && fragmentation < 0.5 && remaining_frac > 0.1 {
            score -= 14.0 * (1.0 - fresh_match / 0.2) * (0.5 + 0.5 * (1.0 - progress));
        }
        // MUTATION (gen 127): demand-cushion fresh-bin gate.
        if remaining_frac > 0.1 && fresh_post > 0.45 * cap && next_item_size > 0 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (next_item_size as f64) * 0.5;
            if open_space > 1.3 * est_need {
                score += 24.0 * (1.0 - remaining_frac) * (fresh_post / cap - 0.45);
            }
        }
        // MUTATION (gen 127): tileable-lane fresh bonus.
        if next_item_size > 1 && fresh_post > 0.0 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            let open_space = mean_residual * open_bins_count as f64;
            if reps >= 2 && rem == 0 && open_space < 1.5 * cap {
                score -= 16.0 * ((reps as f64).min(4.0) - 1.0) * (1.0 - progress);
            }
        }
        // MUTATION (gen 128): fresh-bin exact-closure lane.
        if next_item_size > 0 && fresh_post > 0.0 && (fresh_post as u32) == next_item_size {
            score -= 40.0 * (0.5 + 0.5 * (1.0 - progress));
        }
        // MUTATION (gen 128): oversized-fresh refusal.
        if fresh_post > 0.55 * cap && next_item_size > 0 && (fresh_post as u32) < next_item_size
            && mean_residual * open_bins_count as f64 > 2.0 * cap {
            score += 30.0 * (fresh_post / cap - 0.55) * (0.5 + 0.5 * (1.0 - progress));
        }
        // MUTATION (gen 143): fresh-bin two-step tileability — when the
        // fresh bin's post-residual minus the next item is either zero or an
        // exact small tail, opening here seeds a near-perfect chain; reward
        // when fragmentation is moderate so slack isn't scattered.
        if next_item_size > 0 && fresh_post > next_item_size as f64 && fragmentation < 0.5 {
            let chain = fresh_post - next_item_size as f64;
            if chain <= 6.0 {
                let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
                score -= (12.0 + 8.0 * scarcity) * (1.0 - chain / 6.0) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let br = bin_residual as f64;
    let it = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Smooth non-linear polynomial coupling of post_residual with progress
    let p2 = progress * progress;
    let p3 = p2 * progress;

    // Base: prefer low post_residual, with progress-scaled curvature
    let mut score = pr * (1.0 + 0.8 * p2 + 0.6 * p3);

    // Penalize large dead space quadratically, scaled by fill fraction
    let fill = it / cap;
    score += 0.35 * pr * pr / cap * (1.0 - fill);

    // Reward tight fits (small post_residual relative to item)
    let tightness = 1.0 - pr / br.max(1.0);
    score -= 4.0 * tightness * tightness * (0.5 + 0.5 * p2);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0 + 8.0 * progress;
    }

    // Lookahead: reward residual that can fit next item exactly or well
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let gap = (post_residual as u32 - next_item_size) as f64;
        score -= 2.5 * (1.0 - gap / cap) * (1.0 - progress * 0.5);
    } else if next_item_size > 0 {
        // Penalize residuals that strand the next item
        score += 1.5 * (next_item_size as f64 / cap) * (0.5 + progress);
    }

    // Mildly discourage spreading across too many open bins early
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: encourage only when existing bins are crowded
    if bin_residual == bin_capacity {
        let crowded = mean_residual / cap;
        score = 12.0 * (1.0 - crowded) + 6.0 * (1.0 - progress) - 4.0 * crowded * p2;
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
