        if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count == 1 && bin_residual != bin_capacity {
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score -= 14.0 * (1.0 - progress) * (0.6 + 0.4 * tightness);
        }
        // gen 81: dead-space compaction gradient (refined gen 143: lower the
        // open-space trigger to 1.6x cap and strengthen the gradient so
        // stranded slivers are penalized earlier and harder).
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
            && fitting_bins_count > 1 {
            let open_space = mean_residual * open_bins_count as f64;
            if open_space > 1.6 * cap {
                let frac = post_residual as f64 / next_item_size as f64;
                score += 13.0 * (1.0 - frac) * (0.4 + 0.6 * progress);
            }
        }
        // gen 81: consolidation pull (refined gen 143: start earlier at
        // progress > 0.35 and scale with how close to full this bin lands,
        // tightening residual spread across the whole back half).
        if post_residual > 0 && fitting_bins_count > 2 && progress > 0.35 {
            let fill = 1.0 - post_residual as f64 / cap;
            score -= 6.5 * fill * (progress - 0.35);
        }
        // MUTATION (gen 143): variance clamp — placements that leave a
        // post-residual far above the current mean residual fragment the
        // slack distribution; penalize proportionally to the deviation so
        // residuals stay in a tight, reusable band.
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 1 {
            let dev = (post_residual as f64 - mean_residual) / cap;
            if dev > 0.12 {
                let scarcity = 1.0 / (fitting_bins_count as f64);
                score += 8.0 * (dev - 0.12).min(0.3) * scarcity * (0.5 + 0.5 * progress);
