        // into combinable fragments instead of an odd-sized orphan.
        if fresh_post > 0.0 && mean_residual > 0.0 && remaining_frac > 0.1 {
            let align = (fresh_post - mean_residual).abs() / cap;
            if align < 0.08 {
                score -= 11.0 * (1.0 - align / 0.08) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base: post-residual, with a steep penalty for small unusable gaps.
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no future item (min size ~1..10)
    // can plausibly use are heavily penalized.
    let dead_threshold = 9u32;
    if post_residual > 0 && post_residual <= dead_threshold {
        score += 60.0 * (dead_threshold as f64 - post_residual as f64 + 1.0);
    }

    // Penalize gaps smaller than the lookahead item (unusable for next item).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0 + (next_item_size as f64 - post_residual as f64);
    }

    // Reward perfect and near-perfect fits.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Tight fit relative to residual: small waste fraction rewarded.
    if bin_residual > 0 {
        let waste_frac = post_residual as f64 / bin_residual as f64;
        score += 30.0 * waste_frac - 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 55.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins; discourage opening new bins.
    let pressure = (open_bins_count as f64).ln().max(1.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize, scaled by open-bin pressure and
        // stream progression (later in stream, keep bins consolidated).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 35.0 + 10.0 * pressure + 20.0 * progress;
    } else {
        score -= 5.0 * pressure;
    }

    // Prefer bins below mean residual (more room left) slightly.
    score += 0.1 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
