pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual)
    score += 0.5 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Aggressive 2-step lookahead: if next item fits into post_residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0 * (next_item_size as f64 / post_residual as f64).min(1.0);
    } else if next_item_size > post_residual {
        // Next item can't follow into this bin: penalize wasted pairing opportunity
        score += 5.0;
    }

    // Prefer bins with residuals below mean (tighter bins first)
    score -= 3.0 * (mean_residual - bin_residual as f64) / bin_capacity as f64;

    // Last-chance bin bonus: avoid opening new bins unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when good existing fits exist, especially early
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 + 20.0 * (1.0 - progress);
        if fitting_bins_count > 0 {
            score += 30.0;
        }
    }

    score
}

