pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: prefer bins where the item fills a large fraction of residual.
    let residual = bin_residual as f64;
    let tightness = item_size as f64 / residual.max(1.0);
    score -= 30.0 * tightness * tightness;

    // Penalize small post-residuals that become dead space, unless near-perfect fit.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 4.0;
        }
        // Bonus if post-residual + next item would nearly fill the bin later.
        if next_item_size as f64 >= post_residual as f64 * 0.9 && post_residual >= next_item_size {
            score -= 8.0;
        }
    } else {
        // Last item: prefer filling bins as tightly as possible.
        score -= 10.0 * tightness;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Many open bins: discourage spreading, prefer already-open bins over new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin = (bin_residual == bin_capacity) as f64;
    score += new_bin * (15.0 + 25.0 * progress + 2.0 * open_bins_count as f64);

    // Global residual pressure: high mean residual means space is abundant; be pickier.
    score += (mean_residual / bin_capacity as f64) * 8.0 * (1.0 - tightness);

    // Early stream: allow slightly looser fits to build useful partial bins.
    score -= 5.0 * (1.0 - progress) * tightness;

    score
}

