pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into capacity fractions
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let class: f64 = if post_residual == 0 {
        -6.0 // perfect fill: strongly reward
    } else if post_residual < eighth {
        -4.0 // tiny dead space
    } else if post_residual < quarter {
        -1.5
    } else if post_residual < bin_capacity / 2 {
        0.5
    } else if post_residual < 3 * quarter {
        1.5
    } else {
        2.5 // mostly empty bin: wasteful placement
    };
    score += class * 3.0;

    // Modulo arithmetic on post_residual: leftovers divisible into common small sizes
    // are reusable by typical items (sizes 10..80 often hit multiples of 5/10).
    let reuse_bonus: f64 = if post_residual >= 10 {
        if post_residual % 10 == 0 {
            4.0
        } else if post_residual % 5 == 0 {
            2.0
        } else {
            0.0
        }
    } else { 0.0 };
    score -= reuse_bonus;

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size <= post_residual {
            // next item fits: residual class reusable
            score -= 3.0 + (post_residual - next_item_size) as f64 * 0.05;
        } else {
            // next item cannot use this residual: penalize proportionally
            let waste = (next_item_size - post_residual) as f64;
            score += waste * 0.10;
        }
        // integer-division threshold: next item fits in half of the residual
        if next_item_size <= post_residual / 2 {
            score -= 2.0;
        }
    }

    // Last-chance bin: strongly favor to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }
    // Many fitting bins: mild penalty to prefer tighter competition resolution
    if fitting_bins_count > 2 {
        score += 0.5 * (fitting_bins_count as f64 - 2.0).min(3.0);
    }

    // New-bin candidate handling: keep it neutral-mid so only genuinely bad fits
    // (large residual, no lookahead synergy) trigger opening a new bin.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = cap * 0.55 - 6.0 * progress;
        if next_item_size > 0 && next_item_size > bin_capacity / 2 {
            score -= 2.0; // big next item pairs well with fresh bin
        }
        if fitting_bins_count == 0 {
            score -= 20.0; // no alternative: must open
        }
        return score;
    }

    // Tight-fit reward: item fills most of the residual
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if fill_ratio > 0.9 {
        score -= 10.0;
    } else if fill_ratio > 0.75 {
        score -= 5.0;
    }

    // Mean residual coupling: placing into a bin far below mean residual reduces spread
    let dev = mean_residual - pr;
    score += 0.15 * dev;

    // Late-stream consolidation: prefer filling existing bins as stream ends
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 3.0 * progress;

    score
}

