        let dead_ratio = dead / cap;
        if dead_ratio > 0.5 && fitting_bins_count > 1 {
            score += 10.5 * (dead_ratio - 0.5) * (1.0 - progress);
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
            && mean_residual > 0.0 && (mean_residual as u32) >= next_item_size {
            score += 12.0;
        }
        if post_residual > 12 && post_residual < 40 && next_item_size > post_residual {
            let orphan = (post_residual as f64 - 12.0) / 28.0;
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            score += 17.0 * orphan * scarcity * (0.5 + 0.5 * (1.0 - progress));
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let chain = post_residual % next_item_size.max(1);
            if chain == 0 {
                score -= 26.0 * (1.0 - progress);
            } else if chain <= 3 {
                score -= 11.0 * (1.0 - progress);
            }
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            let stranded = (next_item_size - post_residual) as f64;
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            if stranded <= 10.0 {
                score += (8.5 + 1.1 * (10.0 - stranded)) * scarcity * (0.4 + 0.6 * (1.0 - progress));
            } else {
                let proximity = 1.0 - (stranded - 10.0).min(cap) / cap;
                score += 3.2 * proximity * scarcity * (1.0 - progress);
            }
        }
        if dead_ratio > 0.35 && fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score += 7.5 * (dead_ratio - 0.35) * tightness * (1.0 - progress);
        }
        if post_residual > 0 && mean_residual > 0.0 {
            let gap = mean_residual - post_residual as f64;
            if gap > 0.0 && gap < 0.15 * cap && fitting_bins_count > 2 {
                score += 4.8 * (gap / (0.15 * cap)) * (1.0 - progress);
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size.max(1) && fitting_bins_count > 2 {
            score -= 6.5 * (1.0 - progress);
        }
        if post_residual == 0 && bin_residual < bin_capacity {
            score -= 42.0 * (1.0 - bin_residual as f64 / cap) * (1.0 - progress);
        }
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 1 {
            let harmony = (post_residual as f64 - mean_residual).abs() / cap;
            if harmony < 0.08 {
                score -= 9.0 * (1.0 - harmony / 0.08) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        if post_residual > 6 && post_residual <= 30 && next_item_size > 0 && next_item_size <= post_residual {
            let reps = post_residual / next_item_size.max(1);
            if reps >= 2 {
                score -= 3.5 * (reps as f64).min(4.0) * (1.0 - progress);
            }
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let after_next = post_residual - next_item_size;
            if after_next > 0 && after_next <= 12 {
                let tail = after_next as f64;
                score -= (14.0 - 0.9 * tail) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        if post_residual > 0 && post_residual < 6 && next_item_size > post_residual {
            score += 6.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let after_next = (post_residual - next_item_size) as f64;
            if after_next > 8.0 && after_next <= 16.0 && progress < 0.85 {
                let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
                score -= (4.0 + 3.0 * scarcity) * (1.0 - (after_next - 8.0) / 8.0) * (1.0 - progress);
            }
        }
        if post_residual > 0 && next_item_size > 0 && fitting_bins_count > 3 {
            let overshoot = post_residual.saturating_sub(next_item_size) as f64;
            if overshoot > 16.0 {
                score += 1.6 * ((overshoot - 16.0) / cap).min(0.25) * (1.0 - progress);
            }
        }
        if fitting_bins_count > 1 && dead_ratio > 0.08 && post_residual > 0 {
            let scarcity = 1.0 / (fitting_bins_count as f64);
            let comp_slack = (mean_residual / cap).min(1.0);
            score += 6.5 * (dead_ratio - 0.08) * scarcity * comp_slack * (0.5 + 0.5 * (1.0 - progress));
            score += 2.2 * (dead / cap) * scarcity * comp_slack * (1.0 - progress);
        }
        if fitting_bins_count > 2 && post_residual > 0 && mean_residual > 0.0 {
            let dev = ((post_residual as f64 - mean_residual).abs() / cap).min(0.4);
            score += 5.0 * dev * (1.0 - progress);
        }
        if post_residual > 0 && post_residual % 10 == 0 && post_residual <= 60 && next_item_size > 0 && next_item_size <= post_residual {
            score -= 4.0 * (1.0 - progress) * (1.0 - post_residual as f64 / 120.0);
        }
        if next_item_size > 0 && post_residual == next_item_size && fitting_bins_count <= 3 {
            score -= 30.0 / fitting_bins_count.max(1) as f64 * (0.5 + 0.5 * (1.0 - progress));
        }
        if post_residual > 0 && next_item_size > 0 && fitting_bins_count > 1 {
            let usable = next_item_size <= post_residual
                || (mean_residual as u32) >= next_item_size;
            if !usable {
                let waste_frac = post_residual as f64 / cap;
                let late = 0.35 + 0.65 * progress;
                score += 9.0 * waste_frac * late;
            }
        }
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 2 {
            let rel = post_residual as f64 / (mean_residual + 1.0);
            if rel < 0.5 {
                score -= 6.0 * (1.0 - rel / 0.5) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        if post_residual > 0 && next_item_size > 1 && next_item_size <= post_residual {
            let reps = post_residual / next_item_size;
            let rem = post_residual % next_item_size;
            if reps >= 1 && rem == 0 {
                let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
                score -= (5.0 + 6.0 * scarcity) * ((reps as f64).min(3.0)) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 1 && progress > 0.25 {
            let target = 0.5 * (mean_residual + 0.5 * cap);
            let dev = ((post_residual as f64 - target).abs() / cap).min(0.5);
            score += 2.4 * dev * (progress - 0.25);
        }
        // gen 76: near-full chain extension.
        if post_residual > 0 && next_item_size > 0 && post_residual > next_item_size {
            let after_next = post_residual - next_item_size;
            if after_next > 0 && after_next < 6 && progress > 0.35 {
                score -= 11.0 * (1.0 - after_next as f64 / 6.0) * (progress - 0.35);
            }
        }
        // gen 76: usable-residual scarcity bonus.
        if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count == 1 && bin_residual != bin_capacity {
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score -= 14.0 * (1.0 - progress) * (0.6 + 0.4 * tightness);
        }
        // gen 81: dead-space compaction gradient (refined gen 145: lower the
        // open-space trigger to 1.6x cap and sharpen the gradient so more
        // stranded slivers are punished when aggregate slack is plentiful).
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
            && fitting_bins_count > 1 {
            let open_space = mean_residual * open_bins_count as f64;
            if open_space > 1.6 * cap {
                let frac = post_residual as f64 / next_item_size as f64;
                score += 12.5 * (1.0 - frac) * (0.4 + 0.6 * progress);
            }
        }
        // gen 81: consolidation pull (refined gen 145: start earlier at
        // progress > 0.4 and scale with residual size to squeeze the
        // mid/late-stream residual spread that dominates the variance).
        if post_residual > 0 && fitting_bins_count > 2 && progress > 0.4 {
            let fill = 1.0 - post_residual as f64 / cap;
            score -= 6.5 * fill * (progress - 0.4);
        }
        // MUTATION (gen 145): residual-variance damper — penalize placements
        // whose post-residual deviates far from the fleet's mean residual
        // when the bin is already deep into its capacity; this keeps open
        // bins homogeneous so future items fit somewhere without a new bin.
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 1 && progress > 0.3 {
            let dev = (post_residual as f64 - mean_residual).abs() / cap;
            if dev > 0.12 {
                score += 3.8 * (dev - 0.12) * (progress - 0.3) * (1.0 + 0.5 * (post_residual as f64 / cap));
            }
        }
        // MUTATION (gen 145): two-item exact tiling lookahead — when the
        // post-residual can hold the next item twice with zero remainder,
        // reward strongly since the bin closes perfectly in two steps.
        if next_item_size > 1 && post_residual >= 2 * next_item_size
            && post_residual % (2 * next_item_size) == 0 {
            score -= 10.0 * (1.0 - progress) * (1.0 - (post_residual as f64) / (2.0 * cap));
        }
    } else {
        let fragmentation = (mean_residual / cap) * open_bins_count as f64;
        let huge_item = item_size as f64 > 0.7 * cap;
        let remaining = if total_items > step_index { total_items - step_index } else { 1 };
        let remaining_frac = remaining as f64 / total_items.max(1) as f64;
        let fresh_post = cap - item_size as f64;
        let fresh_is_exact = fresh_post <= 4.0 && fresh_post >= 0.0;

        if fragmentation > 0.55 || (huge_item && open_bins_count > 4) {
            score -= 66.0 + 46.0 * remaining_frac;
        } else if fresh_is_exact {
            score -= 134.0 + 66.0 * remaining_frac;
        } else {
            score += 400.0 - 82.0 * remaining_frac;
            if fitting_bins_count <= 3 && open_bins_count > 2 {
                score -= 30.0 + 18.0 * remaining_frac;
            }
        }

        let fresh_match = (fresh_post - mean_residual).abs() / cap;
        if fresh_match < 0.05 {
            score -= 76.0 * (1.0 - fresh_match / 0.05);
        }
        if remaining_frac < 0.05 && fresh_post > 0.0 && !fresh_is_exact {
            score += 160.0 * (fresh_post / cap);
        }
        if fresh_post > 0.0 && fresh_post <= 22.0 && !fresh_is_exact {
            score -= 26.0 * (1.0 - fresh_post / 22.0);
        }
        if fresh_post > 22.0 && fresh_post <= 40.0 && fragmentation < 0.35 {
            score -= 12.5 * (1.0 - (fresh_post - 22.0) / 18.0);
        }
        if fresh_post > 0.0 && fresh_match < 0.12 && fragmentation < 0.55 {
            score -= 30.0 * (1.0 - fresh_match / 0.12);
        }
        if next_item_size > 0 && fresh_post > 0.0 {
            let fresh_exact_next = (fresh_post as u32) == next_item_size;
            let open_can_next = mean_residual >= next_item_size as f64;
            if fresh_exact_next && !open_can_next && fitting_bins_count <= 2 {
                score -= 52.0 * (1.0 - progress);
            }
            if (fresh_post as u32) < next_item_size && mean_residual > next_item_size as f64 {
                score += 21.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && fresh_post > next_item_size as f64 {
            let chain_post = fresh_post - next_item_size as f64;
            if chain_post <= 4.0 {
                score -= 34.0 * (1.0 - chain_post / 4.0) * (0.5 + 0.5 * (1.0 - progress));
            } else if chain_post <= 10.0 {
                score -= 9.5 * (1.0 - (chain_post - 4.0) / 6.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        if remaining_frac < 0.12 && fresh_post > 0.0 && !fresh_is_exact && mean_residual * open_bins_count as f64 > 3.0 * cap {
            score += 42.0 * (1.0 - remaining_frac / 0.12);
        }
        if fitting_bins_count == 1 && fresh_post > 0.0 && next_item_size > 0 {
            let stranded_here = bin_capacity.saturating_sub(item_size);
            let would_strand = stranded_here < next_item_size;
            if would_strand && stranded_here > 0 && stranded_here <= 8 {
                score -= 32.0 * (1.0 - progress);
            }
        }
        let open_capacity = mean_residual * open_bins_count as f64;
        let per_item_need = cap * 0.5;
        if remaining_frac > 0.25 && open_capacity < per_item_need * open_bins_count.max(1) as f64 * 0.5 {
            score -= 18.0 * (1.0 - progress);
        }
        if next_item_size > 0 && fresh_post > next_item_size as f64 {
            let after_next = fresh_post - next_item_size as f64;
            if after_next > 0.0 && after_next <= 8.0 && fragmentation < 0.5 {
                score -= 20.0 * (1.0 - after_next / 8.0) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        if next_item_size > 0 && fresh_post > 0.0 && (fresh_post as u32) < next_item_size {
            let slack_total = mean_residual * open_bins_count as f64;
            if slack_total > 2.0 * cap {
                score += 26.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && (fresh_post as u32) == next_item_size && fragmentation > 0.3 {
            score -= 44.0 * (0.5 + 0.5 * (1.0 - progress));
        }
        if fresh_post > 0.5 * cap && mean_residual < 0.2 * cap && remaining_frac > 0.3 && open_bins_count > 3 {
            score += 24.0 * (fresh_post / cap - 0.5) * 2.0 * (1.0 - progress);
        }
        if fitting_bins_count <= 1 && fresh_post > 0.45 * cap && next_item_size > 0 {
            let reachable = (next_item_size as f64 / fresh_post).min(1.0);
            if reachable < 0.5 {
                score += 18.0 * (0.5 - reachable) * (1.0 - progress);
            }
        }
        if next_item_size > 0 && fresh_post > 0.0 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 2 && fragmentation < 0.5 {
                score -= 7.0 * ((reps as f64).min(4.0) - 1.0) * (0.4 + 0.6 * (1.0 - progress));
                if rem <= 3 {
                    score -= 5.0 * (1.0 - progress);
                }
            }
        }
        if fresh_post > 0.35 * cap && remaining_frac > 0.2 && mean_residual * open_bins_count as f64 > 4.0 * cap && fragmentation < 0.45 {
            score += 20.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        if remaining_frac < 0.15 && fresh_post > 0.3 * cap {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.35;
            if open_space > est_need {
                score += 55.0 * (1.0 - remaining_frac / 0.15);
            }
        }
        if remaining_frac >= 0.15 && remaining_frac < 0.45 && fresh_post > 0.4 * cap && fragmentation > 0.4 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.45;
            if open_space > est_need {
                score += 28.0 * (1.0 - remaining_frac / 0.45);
            }
        }
        if next_item_size > 1 && fresh_post > 0.0 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 2 && rem == 0 && fragmentation < 0.4 {
                score -= 10.0 * ((reps as f64).min(4.0) - 1.0) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        if remaining_frac >= 0.45 && remaining_frac < 0.5 && fresh_post > 0.45 * cap && fragmentation > 0.5 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.55;
            if open_space > est_need {
                score += 22.0 * (1.0 - remaining_frac / 0.5);
            }
        }
        // gen 76: demand-aware fresh-bin refusal.
        if remaining_frac >= 0.05 && fresh_post > 0.3 * cap && next_item_size > 0 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (next_item_size as f64) * 0.42;
            if open_space > 1.15 * est_need {
                score += 30.0 * (1.0 - remaining_frac) * (fresh_post / cap - 0.3);
            }
        }
        // gen 76: fresh-bin dead-space cap.
        if fresh_post > 0.35 * cap && next_item_size > 0 && (fresh_post as u32) < next_item_size && fragmentation < 0.4 && remaining_frac > 0.15 {
            score += 16.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        // gen 81: tileability-aware open.
        if next_item_size > 1 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 3 && rem == 0 && fragmentation < 0.3 {
                score -= 14.0 * ((reps as f64).min(5.0) - 2.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // MUTATION (gen 145): homogeneity-aware open — a fresh bin whose
        // post-residual sits close to the fleet's mean residual integrates
        // into the existing slack pool instead of creating an outlier
        // residual that later items cannot use; reward that alignment.
        if mean_residual > 0.0 && fresh_post > 0.0 && remaining_frac > 0.1 && fragmentation < 0.5 {
            let dev = (fresh_post - mean_residual).abs() / cap;
            if dev < 0.18 {
                score -= 8.0 * (1.0 - dev / 0.18) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in [1,9] are "unusable" gaps
    // (min item size is 10) -> heavy penalty pushing oracle away from such bins.
    if post_residual > 0 && post_residual < 10 {
        score += 500.0;
    }
    // Perfect fit is ideal
    if post_residual == 0 {
        score -= 300.0;
    }

    // Reward leaving residual that exactly fits the lookahead item (k=2 lookahead)
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 120.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Mild reward when post residual can still host next item
        score -= 15.0;
    } else if next_item_size > 0 {
        // Post residual too small for next item: penalize proportionally
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 250.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer tight fits.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / 10.0);
    score += pressure * 2.0;

    // Penalize bins whose residual deviates far below the mean residual
    // (already very full bins are fine; very empty bins chosen early waste capacity)
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score += dev * 0.8;
    }

    // Early stream: be more conservative, prefer filling existing bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 30.0;

    // New-bin candidate handling: empty bin should only win when no open bin
    // gives a decent fit. Make the empty-bin score moderately high.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score = -100.0; // forced: no alternative
        } else {
            // Competing with open bins: penalize unless open fits are terrible.
            // If any open bin leaves a perfect/near-perfect fit, new bin loses.
            score += 400.0;
            if next_item_size > 0 {
                score -= (bin_capacity - next_item_size) as f64 * 0.3;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Layered dead-space rewards (lower post_residual = better).
    if post_residual == 0 {
        score -= 980.0;
    } else if post_residual <= 4 {
        score -= 250.0 + 4.2 * (4 - post_residual) as f64;
    } else if post_residual <= 10 {
        score -= 64.0 + 3.6 * (10 - post_residual) as f64;
    } else if post_residual <= 22 {
        score -= 13.5 + 1.5 * (22 - post_residual) as f64;
    } else if post_residual <= 32 {
        score -= 5.0 + 0.7 * (32 - post_residual) as f64;
    } else if post_residual <= 48 {
        score -= 1.2 + 0.22 * (48 - post_residual) as f64;
    } else {
        score -= 1.2 - 0.014 * (post_residual as f64 - 48.0);
    }

    let w = 0.33 + 0.67 * progress * progress;
    score *= w;

    // Lookahead coupling with the next item.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if next_item_size < post_residual {
            let two_step_waste = (post_residual - next_item_size) as f64;
            if two_step_waste <= 8.0 {
                score -= 135.0 - 2.3 * two_step_waste;
            } else {
                score -= 72.0 - 0.58 * two_step_waste;
            }
            if two_step_waste <= 3.0 {
                score -= 48.0;
            }
        } else {
            let miss = (next_item_size - post_residual) as f64;
            score += 0.95 * miss;
            if miss > 26.0 {
                score += 0.55 * (miss - 26.0);
            }
        }
    }

    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
        let boost = 36.0 + 26.0 * scarcity;
        score -= boost * (1.0 - slack / cap) * (0.6 + 0.4 * (1.0 - progress));
        if fitting_bins_count <= 2 {
            score -= 15.0 * (1.0 - slack / cap);
        }
        if slack == 0.0 {
            score -= 20.0 * (1.0 - progress);
        }
    }

    if bin_residual != bin_capacity {
        let dead = (bin_residual - item_size) as f64;
        let dead_ratio = dead / cap;
        if dead_ratio > 0.5 && fitting_bins_count > 1 {
            score += 10.5 * (dead_ratio - 0.5) * (1.0 - progress);
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
            && mean_residual > 0.0 && (mean_residual as u32) >= next_item_size {
            score += 12.0;
        }
        if post_residual > 12 && post_residual < 40 && next_item_size > post_residual {
            let orphan = (post_residual as f64 - 12.0) / 28.0;
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            score += 17.0 * orphan * scarcity * (0.5 + 0.5 * (1.0 - progress));
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let chain = post_residual % next_item_size.max(1);
            if chain == 0 {
                score -= 26.0 * (1.0 - progress);
            } else if chain <= 3 {
                score -= 11.0 * (1.0 - progress);
            }
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            let stranded = (next_item_size - post_residual) as f64;
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            if stranded <= 10.0 {
                score += (8.5 + 1.1 * (10.0 - stranded)) * scarcity * (0.4 + 0.6 * (1.0 - progress));
            } else {
                let proximity = 1.0 - (stranded - 10.0).min(cap) / cap;
                score += 3.2 * proximity * scarcity * (1.0 - progress);
            }
        }
        if dead_ratio > 0.35 && fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score += 7.5 * (dead_ratio - 0.35) * tightness * (1.0 - progress);
        }
        if post_residual > 0 && mean_residual > 0.0 {
            let gap = mean_residual - post_residual as f64;
            if gap > 0.0 && gap < 0.15 * cap && fitting_bins_count > 2 {
                score += 4.8 * (gap / (0.15 * cap)) * (1.0 - progress);
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size.max(1) && fitting_bins_count > 2 {
            score -= 6.5 * (1.0 - progress);
        }
        if post_residual == 0 && bin_residual < bin_capacity {
            score -= 42.0 * (1.0 - bin_residual as f64 / cap) * (1.0 - progress);
        }
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 1 {
            let harmony = (post_residual as f64 - mean_residual).abs() / cap;
            if harmony < 0.08 {
                score -= 9.0 * (1.0 - harmony / 0.08) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        if post_residual > 6 && post_residual <= 30 && next_item_size > 0 && next_item_size <= post_residual {
            let reps = post_residual / next_item_size.max(1);
            if reps >= 2 {
                score -= 3.5 * (reps as f64).min(4.0) * (1.0 - progress);
            }
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let after_next = post_residual - next_item_size;
            if after_next > 0 && after_next <= 12 {
                let tail = after_next as f64;
                score -= (14.0 - 0.9 * tail) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        if post_residual > 0 && post_residual < 6 && next_item_size > post_residual {
            score += 6.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let after_next = (post_residual - next_item_size) as f64;
            if after_next > 8.0 && after_next <= 16.0 && progress < 0.85 {
                let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
                score -= (4.0 + 3.0 * scarcity) * (1.0 - (after_next - 8.0) / 8.0) * (1.0 - progress);
            }
        }
        if post_residual > 0 && next_item_size > 0 && fitting_bins_count > 3 {
            let overshoot = post_residual.saturating_sub(next_item_size) as f64;
            if overshoot > 16.0 {
                score += 1.6 * ((overshoot - 16.0) / cap).min(0.25) * (1.0 - progress);
            }
        }
        if fitting_bins_count > 1 && dead_ratio > 0.08 && post_residual > 0 {
            let scarcity = 1.0 / (fitting_bins_count as f64);
            let comp_slack = (mean_residual / cap).min(1.0);
            score += 6.5 * (dead_ratio - 0.08) * scarcity * comp_slack * (0.5 + 0.5 * (1.0 - progress));
            score += 2.2 * (dead / cap) * scarcity * comp_slack * (1.0 - progress);
        }
        if fitting_bins_count > 2 && post_residual > 0 && mean_residual > 0.0 {
            let dev = ((post_residual as f64 - mean_residual).abs() / cap).min(0.4);
            score += 5.0 * dev * (1.0 - progress);
        }
        if post_residual > 0 && post_residual % 10 == 0 && post_residual <= 60 && next_item_size > 0 && next_item_size <= post_residual {
            score -= 4.0 * (1.0 - progress) * (1.0 - post_residual as f64 / 120.0);
        }
        if next_item_size > 0 && post_residual == next_item_size && fitting_bins_count <= 3 {
            score -= 30.0 / fitting_bins_count.max(1) as f64 * (0.5 + 0.5 * (1.0 - progress));
        }
        if post_residual > 0 && next_item_size > 0 && fitting_bins_count > 1 {
            let usable = next_item_size <= post_residual
                || (mean_residual as u32) >= next_item_size;
            if !usable {
                let waste_frac = post_residual as f64 / cap;
                let late = 0.35 + 0.65 * progress;
                score += 9.0 * waste_frac * late;
            }
        }
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 2 {
            let rel = post_residual as f64 / (mean_residual + 1.0);
            if rel < 0.5 {
                score -= 6.0 * (1.0 - rel / 0.5) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        if post_residual > 0 && next_item_size > 1 && next_item_size <= post_residual {
            let reps = post_residual / next_item_size;
            let rem = post_residual % next_item_size;
            if reps >= 1 && rem == 0 {
                let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
                score -= (5.0 + 6.0 * scarcity) * ((reps as f64).min(3.0)) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 1 && progress > 0.25 {
            let target = 0.5 * (mean_residual + 0.5 * cap);
            let dev = ((post_residual as f64 - target).abs() / cap).min(0.5);
            score += 2.4 * dev * (progress - 0.25);
        }
        // gen 76: near-full chain extension.
        if post_residual > 0 && next_item_size > 0 && post_residual > next_item_size {
            let after_next = post_residual - next_item_size;
            if after_next > 0 && after_next < 6 && progress > 0.35 {
                score -= 11.0 * (1.0 - after_next as f64 / 6.0) * (progress - 0.35);
            }
        }
        // gen 76: usable-residual scarcity bonus.
        if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count == 1 && bin_residual != bin_capacity {
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score -= 14.0 * (1.0 - progress) * (0.6 + 0.4 * tightness);
        }
        // gen 81: dead-space compaction gradient (gen 145: widen the slack
        // trigger and scale with how much of the next item is stranded).
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
            && fitting_bins_count > 1 {
            let open_space = mean_residual * open_bins_count as f64;
            if open_space > 1.7 * cap {
                let frac = post_residual as f64 / next_item_size as f64;
                score += 11.5 * (1.0 - frac) * (0.5 + 0.5 * progress);
            }
        }
        // gen 81: consolidation pull (gen 145: start earlier and strengthen
        // the late-stream fill preference to shrink residual variance).
        if post_residual > 0 && fitting_bins_count > 2 && progress > 0.4 {
            let fill = 1.0 - post_residual as f64 / cap;
            score -= 6.5 * fill * (progress - 0.4);
        }
        // MUTATION (gen 145): mean-residual gravitation — among competing
        // bins, prefer the one whose post-residual sits closest to the
        // fleet mean so residual mass pools into reusable chunks instead
        // of scattering into unreachable slivers.
        if post_residual > 0 && fitting_bins_count > 2 {
            let dev = ((post_residual as f64 - mean_residual).abs() / cap).min(0.3);
            score -= 3.5 * (0.3 - dev) * (0.4 + 0.6 * (1.0 - progress));
        }
        // MUTATION (gen 145): late-stream near-exact bonus — when few items
        // remain and this placement leaves a residual that a remaining small
        // item could still fill, reward strongly to squeeze the final bins.
        if post_residual > 0 && next_item_size > 0 && progress > 0.8 {
            if post_residual >= next_item_size && post_residual - next_item_size <= 2 {
                score -= 18.0 * (progress - 0.8);
            }
        }
    } else {
        let fragmentation = (mean_residual / cap) * open_bins_count as f64;
        let huge_item = item_size as f64 > 0.7 * cap;
        let remaining = if total_items > step_index { total_items - step_index } else { 1 };
        let remaining_frac = remaining as f64 / total_items.max(1) as f64;
        let fresh_post = cap - item_size as f64;
        let fresh_is_exact = fresh_post <= 4.0 && fresh_post >= 0.0;

        if fragmentation > 0.55 || (huge_item && open_bins_count > 4) {
            score -= 66.0 + 46.0 * remaining_frac;
        } else if fresh_is_exact {
            score -= 134.0 + 66.0 * remaining_frac;
        } else {
            score += 400.0 - 82.0 * remaining_frac;
            if fitting_bins_count <= 3 && open_bins_count > 2 {
                score -= 30.0 + 18.0 * remaining_frac;
            }
        }

        let fresh_match = (fresh_post - mean_residual).abs() / cap;
        if fresh_match < 0.05 {
            score -= 76.0 * (1.0 - fresh_match / 0.05);
        }
        if remaining_frac < 0.05 && fresh_post > 0.0 && !fresh_is_exact {
            score += 160.0 * (fresh_post / cap);
        }
        if fresh_post > 0.0 && fresh_post <= 22.0 && !fresh_is_exact {
            score -= 26.0 * (1.0 - fresh_post / 22.0);
        }
        if fresh_post > 22.0 && fresh_post <= 40.0 && fragmentation < 0.35 {
            score -= 12.5 * (1.0 - (fresh_post - 22.0) / 18.0);
        }
        if fresh_post > 0.0 && fresh_match < 0.12 && fragmentation < 0.55 {
            score -= 30.0 * (1.0 - fresh_match / 0.12);
        }
        if next_item_size > 0 && fresh_post > 0.0 {
            let fresh_exact_next = (fresh_post as u32) == next_item_size;
            let open_can_next = mean_residual >= next_item_size as f64;
            if fresh_exact_next && !open_can_next && fitting_bins_count <= 2 {
                score -= 52.0 * (1.0 - progress);
            }
            if (fresh_post as u32) < next_item_size && mean_residual > next_item_size as f64 {
                score += 21.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && fresh_post > next_item_size as f64 {
            let chain_post = fresh_post - next_item_size as f64;
            if chain_post <= 4.0 {
                score -= 34.0 * (1.0 - chain_post / 4.0) * (0.5 + 0.5 * (1.0 - progress));
            } else if chain_post <= 10.0 {
                score -= 9.5 * (1.0 - (chain_post - 4.0) / 6.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        if remaining_frac < 0.12 && fresh_post > 0.0 && !fresh_is_exact && mean_residual * open_bins_count as f64 > 3.0 * cap {
            score += 42.0 * (1.0 - remaining_frac / 0.12);
        }
        if fitting_bins_count == 1 && fresh_post > 0.0 && next_item_size > 0 {
            let stranded_here = bin_capacity.saturating_sub(item_size);
            let would_strand = stranded_here < next_item_size;
            if would_strand && stranded_here > 0 && stranded_here <= 8 {
                score -= 32.0 * (1.0 - progress);
            }
        }
        let open_capacity = mean_residual * open_bins_count as f64;
        let per_item_need = cap * 0.5;
        if remaining_frac > 0.25 && open_capacity < per_item_need * open_bins_count.max(1) as f64 * 0.5 {
            score -= 18.0 * (1.0 - progress);
        }
        if next_item_size > 0 && fresh_post > next_item_size as f64 {
            let after_next = fresh_post - next_item_size as f64;
            if after_next > 0.0 && after_next <= 8.0 && fragmentation < 0.5 {
                score -= 20.0 * (1.0 - after_next / 8.0) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        if next_item_size > 0 && fresh_post > 0.0 && (fresh_post as u32) < next_item_size {
            let slack_total = mean_residual * open_bins_count as f64;
            if slack_total > 2.0 * cap {
                score += 26.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && (fresh_post as u32) == next_item_size && fragmentation > 0.3 {
            score -= 44.0 * (0.5 + 0.5 * (1.0 - progress));
        }
        if fresh_post > 0.5 * cap && mean_residual < 0.2 * cap && remaining_frac > 0.3 && open_bins_count > 3 {
            score += 24.0 * (fresh_post / cap - 0.5) * 2.0 * (1.0 - progress);
        }
        if fitting_bins_count <= 1 && fresh_post > 0.45 * cap && next_item_size > 0 {
            let reachable = (next_item_size as f64 / fresh_post).min(1.0);
            if reachable < 0.5 {
                score += 18.0 * (0.5 - reachable) * (1.0 - progress);
            }
        }
        if next_item_size > 0 && fresh_post > 0.0 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 2 && fragmentation < 0.5 {
                score -= 7.0 * ((reps as f64).min(4.0) - 1.0) * (0.4 + 0.6 * (1.0 - progress));
                if rem <= 3 {
                    score -= 5.0 * (1.0 - progress);
                }
            }
        }
        if fresh_post > 0.35 * cap && remaining_frac > 0.2 && mean_residual * open_bins_count as f64 > 4.0 * cap && fragmentation < 0.45 {
            score += 20.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        if remaining_frac < 0.15 && fresh_post > 0.3 * cap {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.35;
            if open_space > est_need {
                score += 55.0 * (1.0 - remaining_frac / 0.15);
            }
        }
        if remaining_frac >= 0.15 && remaining_frac < 0.45 && fresh_post > 0.4 * cap && fragmentation > 0.4 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.45;
            if open_space > est_need {
                score += 28.0 * (1.0 - remaining_frac / 0.45);
            }
        }
        if next_item_size > 1 && fresh_post > 0.0 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 2 && rem == 0 && fragmentation < 0.4 {
                score -= 10.0 * ((reps as f64).min(4.0) - 1.0) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        if remaining_frac >= 0.45 && remaining_frac < 0.5 && fresh_post > 0.45 * cap && fragmentation > 0.5 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.55;
            if open_space > est_need {
                score += 22.0 * (1.0 - remaining_frac / 0.5);
            }
        }
        // gen 76: demand-aware fresh-bin refusal.
        if remaining_frac >= 0.05 && fresh_post > 0.3 * cap && next_item_size > 0 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (next_item_size as f64) * 0.42;
            if open_space > 1.15 * est_need {
                score += 30.0 * (1.0 - remaining_frac) * (fresh_post / cap - 0.3);
            }
        }
        // gen 76: fresh-bin dead-space cap.
        if fresh_post > 0.35 * cap && next_item_size > 0 && (fresh_post as u32) < next_item_size && fragmentation < 0.4 && remaining_frac > 0.15 {
            score += 16.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        // gen 81: tileability-aware open.
        if next_item_size > 1 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 3 && rem == 0 && fragmentation < 0.3 {
                score -= 14.0 * ((reps as f64).min(5.0) - 2.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // MUTATION (gen 145): mean-matched fresh opens — when the fresh
        // bin's post-residual closely matches the fleet mean residual,
        // opening keeps the residual distribution homogeneous and lets
        // future items tile across all bins uniformly.
        if fresh_post > 0.0 && open_bins_count > 2 && remaining_frac > 0.1 && fragmentation < 0.5 {
            let dev = (fresh_post - mean_residual).abs() / cap;
            if dev < 0.1 {
                score -= 22.0 * (1.0 - dev / 0.1) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-exact fits: post_residual close to 0 is great.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 500.0 * (10.0 - post_residual as f64) / 10.0;
    }

    // Aggressive 2-step lookahead: if next item exactly fills post_residual, strongly favor.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // Favor bins where next item leaves little slack again.
            score -= 200.0 * (1.0 - slack / bin_capacity as f64);
            if slack < 10.0 {
                score -= 100.0 * (10.0 - slack) / 10.0;
            }
        } else {
            // Next item won't fit here; penalize proportionally to wasted potential.
            let waste = (next_item_size - post_residual) as f64;
            score += 50.0 * (waste / 100.0);
        }
    }

    // Penalize bins with residuals far from mean (fragmentation avoidance).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: penalize mildly so it's chosen only when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 150.0;
        // If next item is large, a fresh bin is more attractive.
        if next_item_size > 50 {
            score -= 100.0;
        }
    }

    // Prefer filling more-open-bins states to keep bin count low.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Layered dead-space rewards (lower post_residual = better).
    if post_residual == 0 {
        score -= 980.0;
    } else if post_residual <= 4 {
        score -= 250.0 + 4.2 * (4 - post_residual) as f64;
    } else if post_residual <= 10 {
        score -= 64.0 + 3.6 * (10 - post_residual) as f64;
    } else if post_residual <= 22 {
        score -= 13.5 + 1.5 * (22 - post_residual) as f64;
    } else if post_residual <= 32 {
        score -= 5.0 + 0.7 * (32 - post_residual) as f64;
    } else if post_residual <= 48 {
        score -= 1.2 + 0.22 * (48 - post_residual) as f64;
    } else {
        score -= 1.2 - 0.014 * (post_residual as f64 - 48.0);
    }

    let w = 0.33 + 0.67 * progress * progress;
    score *= w;

    // Lookahead coupling with the next item.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if next_item_size < post_residual {
            let two_step_waste = (post_residual - next_item_size) as f64;
            if two_step_waste <= 8.0 {
                score -= 135.0 - 2.3 * two_step_waste;
            } else {
                score -= 72.0 - 0.58 * two_step_waste;
            }
            if two_step_waste <= 3.0 {
                score -= 48.0;
            }
        } else {
            let miss = (next_item_size - post_residual) as f64;
            score += 0.95 * miss;
            if miss > 26.0 {
                score += 0.55 * (miss - 26.0);
            }
        }
    }

    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
        let boost = 36.0 + 26.0 * scarcity;
        score -= boost * (1.0 - slack / cap) * (0.6 + 0.4 * (1.0 - progress));
        if fitting_bins_count <= 2 {
            score -= 15.0 * (1.0 - slack / cap);
        }
        if slack == 0.0 {
            score -= 20.0 * (1.0 - progress);
        }
    }

    if bin_residual != bin_capacity {
        let dead = (bin_residual - item_size) as f64;
        let dead_ratio = dead / cap;
        if dead_ratio > 0.5 && fitting_bins_count > 1 {
            score += 10.5 * (dead_ratio - 0.5) * (1.0 - progress);
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
            && mean_residual > 0.0 && (mean_residual as u32) >= next_item_size {
            score += 12.0;
        }
        if post_residual > 12 && post_residual < 40 && next_item_size > post_residual {
            let orphan = (post_residual as f64 - 12.0) / 28.0;
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            score += 17.0 * orphan * scarcity * (0.5 + 0.5 * (1.0 - progress));
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let chain = post_residual % next_item_size.max(1);
            if chain == 0 {
                score -= 26.0 * (1.0 - progress);
            } else if chain <= 3 {
                score -= 11.0 * (1.0 - progress);
            }
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            let stranded = (next_item_size - post_residual) as f64;
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            if stranded <= 10.0 {
                score += (8.5 + 1.1 * (10.0 - stranded)) * scarcity * (0.4 + 0.6 * (1.0 - progress));
            } else {
                let proximity = 1.0 - (stranded - 10.0).min(cap) / cap;
                score += 3.2 * proximity * scarcity * (1.0 - progress);
            }
        }
        if dead_ratio > 0.35 && fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score += 7.5 * (dead_ratio - 0.35) * tightness * (1.0 - progress);
        }
        if post_residual > 0 && mean_residual > 0.0 {
            let gap = mean_residual - post_residual as f64;
            if gap > 0.0 && gap < 0.15 * cap && fitting_bins_count > 2 {
                score += 4.8 * (gap / (0.15 * cap)) * (1.0 - progress);
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size.max(1) && fitting_bins_count > 2 {
            score -= 6.5 * (1.0 - progress);
        }
        if post_residual == 0 && bin_residual < bin_capacity {
            score -= 42.0 * (1.0 - bin_residual as f64 / cap) * (1.0 - progress);
        }
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 1 {
            let harmony = (post_residual as f64 - mean_residual).abs() / cap;
            if harmony < 0.08 {
                score -= 9.0 * (1.0 - harmony / 0.08) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        if post_residual > 6 && post_residual <= 30 && next_item_size > 0 && next_item_size <= post_residual {
            let reps = post_residual / next_item_size.max(1);
            if reps >= 2 {
                score -= 3.5 * (reps as f64).min(4.0) * (1.0 - progress);
            }
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let after_next = post_residual - next_item_size;
            if after_next > 0 && after_next <= 12 {
                let tail = after_next as f64;
                score -= (14.0 - 0.9 * tail) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        if post_residual > 0 && post_residual < 6 && next_item_size > post_residual {
            score += 6.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let after_next = (post_residual - next_item_size) as f64;
            if after_next > 8.0 && after_next <= 16.0 && progress < 0.85 {
                let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
                score -= (4.0 + 3.0 * scarcity) * (1.0 - (after_next - 8.0) / 8.0) * (1.0 - progress);
            }
        }
        if post_residual > 0 && next_item_size > 0 && fitting_bins_count > 3 {
            let overshoot = post_residual.saturating_sub(next_item_size) as f64;
            if overshoot > 16.0 {
                score += 1.6 * ((overshoot - 16.0) / cap).min(0.25) * (1.0 - progress);
            }
        }
        if fitting_bins_count > 1 && dead_ratio > 0.08 && post_residual > 0 {
            let scarcity = 1.0 / (fitting_bins_count as f64);
            let comp_slack = (mean_residual / cap).min(1.0);
            score += 6.5 * (dead_ratio - 0.08) * scarcity * comp_slack * (0.5 + 0.5 * (1.0 - progress));
            score += 2.2 * (dead / cap) * scarcity * comp_slack * (1.0 - progress);
        }
        if fitting_bins_count > 2 && post_residual > 0 && mean_residual > 0.0 {
            let dev = ((post_residual as f64 - mean_residual).abs() / cap).min(0.4);
            score += 5.0 * dev * (1.0 - progress);
        }
        if post_residual > 0 && post_residual % 10 == 0 && post_residual <= 60 && next_item_size > 0 && next_item_size <= post_residual {
            score -= 4.0 * (1.0 - progress) * (1.0 - post_residual as f64 / 120.0);
        }
        if next_item_size > 0 && post_residual == next_item_size && fitting_bins_count <= 3 {
            score -= 30.0 / fitting_bins_count.max(1) as f64 * (0.5 + 0.5 * (1.0 - progress));
        }
        if post_residual > 0 && next_item_size > 0 && fitting_bins_count > 1 {
            let usable = next_item_size <= post_residual
                || (mean_residual as u32) >= next_item_size;
            if !usable {
                let waste_frac = post_residual as f64 / cap;
                let late = 0.35 + 0.65 * progress;
                score += 9.0 * waste_frac * late;
            }
        }
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 2 {
            let rel = post_residual as f64 / (mean_residual + 1.0);
            if rel < 0.5 {
                score -= 6.0 * (1.0 - rel / 0.5) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        if post_residual > 0 && next_item_size > 1 && next_item_size <= post_residual {
            let reps = post_residual / next_item_size;
            let rem = post_residual % next_item_size;
            if reps >= 1 && rem == 0 {
                let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
                score -= (5.0 + 6.0 * scarcity) * ((reps as f64).min(3.0)) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 1 && progress > 0.25 {
            let target = 0.5 * (mean_residual + 0.5 * cap);
            let dev = ((post_residual as f64 - target).abs() / cap).min(0.5);
            score += 2.4 * dev * (progress - 0.25);
        }
        // gen 76: near-full chain extension (refined: widen to after_next < 6
        // and extend earlier into the stream since residual variance is the
        // diagnosed weakness).
        if post_residual > 0 && next_item_size > 0 && post_residual > next_item_size {
            let after_next = post_residual - next_item_size;
            if after_next > 0 && after_next < 6 && progress > 0.35 {
                score -= 11.0 * (1.0 - after_next as f64 / 6.0) * (progress - 0.35);
            }
        }
        // gen 76: usable-residual scarcity bonus (refined: scale with how
        // close the post-residual is to the next item, favoring tight reuse).
        if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count == 1 && bin_residual != bin_capacity {
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score -= 14.0 * (1.0 - progress) * (0.6 + 0.4 * tightness);
        }
        // gen 81: dead-space compaction gradient — when this placement leaves
        // a residual well below the next item size AND the aggregate open
        // slack elsewhere is large, the leftover here is pure dead space;
        // penalize proportionally so residual variance shrinks. (gen 145:
        // deepen the penalty and lower the slack gate so mid-stream dead
        // space is also punished.)
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
            && fitting_bins_count > 1 {
            let open_space = mean_residual * open_bins_count as f64;
            if open_space > 1.5 * cap {
                let frac = post_residual as f64 / next_item_size as f64;
                score += 13.0 * (1.0 - frac) * (0.4 + 0.6 * progress);
            }
        }
        // gen 81: consolidation pull — prefer the bin whose placement brings
        // it closest to full relative to competing bins, tightening
        // late-stream residual spread. (gen 145: start earlier at 0.4 and
        // scale with scarcity so crowded streams consolidate faster.)
        if post_residual > 0 && fitting_bins_count > 2 && progress > 0.4 {
            let fill = 1.0 - post_residual as f64 / cap;
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            score -= (5.0 + 8.0 * scarcity) * fill * (progress - 0.4);
        }
        // MUTATION (gen 145): residual-harmonic pairing — when the placement
        // leaves a residual that the NEXT item can tile exactly (zero
        // remainder), the leftover is guaranteed recoverable, not dead
        // space; deepen the reward proportionally to how many repeats fit,
        // directly attacking residual variance.
        if post_residual > 0 && next_item_size > 1 && post_residual >= next_item_size {
            let reps = post_residual / next_item_size;
            let rem = post_residual % next_item_size;
            if rem == 0 && reps >= 1 && fitting_bins_count > 1 {
                let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
                score -= (9.0 + 7.0 * scarcity) * (reps as f64).min(3.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // MUTATION (gen 145): variance-squeeze — when the mean residual is
        // small (stream near saturation), any placement leaving a residual
        // far above the mean is the dominant source of wasted bins; penalize
        // the deviation quadratically late in the stream so remaining slack
        // concentrates into few bins instead of spreading.
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 2 && progress > 0.55 {
            let dev = post_residual as f64 - mean_residual;
            if dev > 0.0 {
                let dn = (dev / cap).min(0.6);
                score += 22.0 * dn * dn * (progress - 0.55);
            }
        }
    } else {
        let fragmentation = (mean_residual / cap) * open_bins_count as f64;
        let huge_item = item_size as f64 > 0.7 * cap;
        let remaining = if total_items > step_index { total_items - step_index } else { 1 };
        let remaining_frac = remaining as f64 / total_items.max(1) as f64;
        let fresh_post = cap - item_size as f64;
        let fresh_is_exact = fresh_post <= 4.0 && fresh_post >= 0.0;

        if fragmentation > 0.55 || (huge_item && open_bins_count > 4) {
            score -= 66.0 + 46.0 * remaining_frac;
        } else if fresh_is_exact {
            score -= 134.0 + 66.0 * remaining_frac;
        } else {
            score += 400.0 - 82.0 * remaining_frac;
            if fitting_bins_count <= 3 && open_bins_count > 2 {
                score -= 30.0 + 18.0 * remaining_frac;
            }
        }

        let fresh_match = (fresh_post - mean_residual).abs() / cap;
        if fresh_match < 0.05 {
            score -= 76.0 * (1.0 - fresh_match / 0.05);
        }
        if remaining_frac < 0.05 && fresh_post > 0.0 && !fresh_is_exact {
            score += 160.0 * (fresh_post / cap);
        }
        if fresh_post > 0.0 && fresh_post <= 22.0 && !fresh_is_exact {
            score -= 26.0 * (1.0 - fresh_post / 22.0);
        }
        if fresh_post > 22.0 && fresh_post <= 40.0 && fragmentation < 0.35 {
            score -= 12.5 * (1.0 - (fresh_post - 22.0) / 18.0);
        }
        if fresh_post > 0.0 && fresh_match < 0.12 && fragmentation < 0.55 {
            score -= 30.0 * (1.0 - fresh_match / 0.12);
        }
        if next_item_size > 0 && fresh_post > 0.0 {
            let fresh_exact_next = (fresh_post as u32) == next_item_size;
            let open_can_next = mean_residual >= next_item_size as f64;
            if fresh_exact_next && !open_can_next && fitting_bins_count <= 2 {
                score -= 52.0 * (1.0 - progress);
            }
            if (fresh_post as u32) < next_item_size && mean_residual > next_item_size as f64 {
                score += 21.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && fresh_post > next_item_size as f64 {
            let chain_post = fresh_post - next_item_size as f64;
            if chain_post <= 4.0 {
                score -= 34.0 * (1.0 - chain_post / 4.0) * (0.5 + 0.5 * (1.0 - progress));
            } else if chain_post <= 10.0 {
                score -= 9.5 * (1.0 - (chain_post - 4.0) / 6.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        if remaining_frac < 0.12 && fresh_post > 0.0 && !fresh_is_exact && mean_residual * open_bins_count as f64 > 3.0 * cap {
            score += 42.0 * (1.0 - remaining_frac / 0.12);
        }
        if fitting_bins_count == 1 && fresh_post > 0.0 && next_item_size > 0 {
            let stranded_here = bin_capacity.saturating_sub(item_size);
            let would_strand = stranded_here < next_item_size;
            if would_strand && stranded_here > 0 && stranded_here <= 8 {
                score -= 32.0 * (1.0 - progress);
            }
        }
        let open_capacity = mean_residual * open_bins_count as f64;
        let per_item_need = cap * 0.5;
        if remaining_frac > 0.25 && open_capacity < per_item_need * open_bins_count.max(1) as f64 * 0.5 {
            score -= 18.0 * (1.0 - progress);
        }
        if next_item_size > 0 && fresh_post > next_item_size as f64 {
            let after_next = fresh_post - next_item_size as f64;
            if after_next > 0.0 && after_next <= 8.0 && fragmentation < 0.5 {
                score -= 20.0 * (1.0 - after_next / 8.0) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        if next_item_size > 0 && fresh_post > 0.0 && (fresh_post as u32) < next_item_size {
            let slack_total = mean_residual * open_bins_count as f64;
            if slack_total > 2.0 * cap {
                score += 26.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && (fresh_post as u32) == next_item_size && fragmentation > 0.3 {
            score -= 44.0 * (0.5 + 0.5 * (1.0 - progress));
        }
        if fresh_post > 0.5 * cap && mean_residual < 0.2 * cap && remaining_frac > 0.3 && open_bins_count > 3 {
            score += 24.0 * (fresh_post / cap - 0.5) * 2.0 * (1.0 - progress);
        }
        if fitting_bins_count <= 1 && fresh_post > 0.45 * cap && next_item_size > 0 {
            let reachable = (next_item_size as f64 / fresh_post).min(1.0);
            if reachable < 0.5 {
                score += 18.0 * (0.5 - reachable) * (1.0 - progress);
            }
        }
        if next_item_size > 0 && fresh_post > 0.0 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 2 && fragmentation < 0.5 {
                score -= 7.0 * ((reps as f64).min(4.0) - 1.0) * (0.4 + 0.6 * (1.0 - progress));
                if rem <= 3 {
                    score -= 5.0 * (1.0 - progress);
                }
            }
        }
        if fresh_post > 0.35 * cap && remaining_frac > 0.2 && mean_residual * open_bins_count as f64 > 4.0 * cap && fragmentation < 0.45 {
            score += 20.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        if remaining_frac < 0.15 && fresh_post > 0.3 * cap {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.35;
            if open_space > est_need {
                score += 55.0 * (1.0 - remaining_frac / 0.15);
            }
        }
        if remaining_frac >= 0.15 && remaining_frac < 0.45 && fresh_post > 0.4 * cap && fragmentation > 0.4 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.45;
            if open_space > est_need {
                score += 28.0 * (1.0 - remaining_frac / 0.45);
            }
        }
        if next_item_size > 1 && fresh_post > 0.0 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 2 && rem == 0 && fragmentation < 0.4 {
                score -= 10.0 * ((reps as f64).min(4.0) - 1.0) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        if remaining_frac >= 0.45 && remaining_frac < 0.5 && fresh_post > 0.45 * cap && fragmentation > 0.5 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.55;
            if open_space > est_need {
                score += 22.0 * (1.0 - remaining_frac / 0.5);
            }
        }
        // gen 76: demand-aware fresh-bin refusal (refined: tighten the slack
        // cushion from 1.25x to 1.15x so useful opens are less suppressed).
        if remaining_frac >= 0.05 && fresh_post > 0.3 * cap && next_item_size > 0 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (next_item_size as f64) * 0.42;
            if open_space > 1.15 * est_need {
                score += 30.0 * (1.0 - remaining_frac) * (fresh_post / cap - 0.3);
            }
        }
        // gen 76: fresh-bin dead-space cap.
        if fresh_post > 0.35 * cap && next_item_size > 0 && (fresh_post as u32) < next_item_size && fragmentation < 0.4 && remaining_frac > 0.15 {
            score += 16.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        // gen 81: tileability-aware open — when the fresh bin's post-residual
        // is an exact multiple of the next item size with three or more
        // repetitions, opening creates a perfectly tileable bin; deepen the
        // reward when fragmentation is low so the new bin acts as a
        // dedicated tiling lane instead of scattering slack.
        if next_item_size > 1 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 3 && rem == 0 && fragmentation < 0.3 {
                score -= 14.0 * ((reps as f64).min(5.0) - 2.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // MUTATION (gen 145): endgame fresh-bin gate — near the stream's end,
        // opening a new bin with a large leftover residual is almost always
        // wasted capacity; raise the refusal so the last items consolidate
        // into existing slack instead of spawning near-empty bins.
        if remaining_frac < 0.08 && fresh_post > 0.25 * cap && open_bins_count > 1 {
            let open_space = mean_residual * open_bins_count as f64;
            if open_space > 0.8 * cap {
                score += 34.0 * (1.0 - remaining_frac / 0.08) * (fresh_post / cap - 0.25);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Layered dead-space rewards (lower post_residual = better).
    if post_residual == 0 {
        score -= 980.0;
    } else if post_residual <= 4 {
        score -= 250.0 + 4.2 * (4 - post_residual) as f64;
    } else if post_residual <= 10 {
        score -= 64.0 + 3.6 * (10 - post_residual) as f64;
    } else if post_residual <= 22 {
        score -= 13.5 + 1.5 * (22 - post_residual) as f64;
    } else if post_residual <= 32 {
        score -= 5.0 + 0.7 * (32 - post_residual) as f64;
    } else if post_residual <= 48 {
        score -= 1.2 + 0.22 * (48 - post_residual) as f64;
    } else {
        score -= 1.2 - 0.014 * (post_residual as f64 - 48.0);
    }

    let w = 0.33 + 0.67 * progress * progress;
    score *= w;

    // Lookahead coupling with the next item.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if next_item_size < post_residual {
            let two_step_waste = (post_residual - next_item_size) as f64;
            if two_step_waste <= 8.0 {
                score -= 135.0 - 2.3 * two_step_waste;
            } else {
                score -= 72.0 - 0.58 * two_step_waste;
            }
            if two_step_waste <= 3.0 {
                score -= 48.0;
            }
        } else {
            let miss = (next_item_size - post_residual) as f64;
            score += 0.95 * miss;
            if miss > 26.0 {
                score += 0.55 * (miss - 26.0);
            }
        }
    }

    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
        let boost = 36.0 + 26.0 * scarcity;
        score -= boost * (1.0 - slack / cap) * (0.6 + 0.4 * (1.0 - progress));
        if fitting_bins_count <= 2 {
            score -= 15.0 * (1.0 - slack / cap);
        }
        if slack == 0.0 {
            score -= 20.0 * (1.0 - progress);
        }
    }

    if bin_residual != bin_capacity {
        let dead = (bin_residual - item_size) as f64;
        let dead_ratio = dead / cap;
        if dead_ratio > 0.5 && fitting_bins_count > 1 {
            score += 10.5 * (dead_ratio - 0.5) * (1.0 - progress);
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
            && mean_residual > 0.0 && (mean_residual as u32) >= next_item_size {
            score += 12.0;
        }
        if post_residual > 12 && post_residual < 40 && next_item_size > post_residual {
            let orphan = (post_residual as f64 - 12.0) / 28.0;
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            score += 17.0 * orphan * scarcity * (0.5 + 0.5 * (1.0 - progress));
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let chain = post_residual % next_item_size.max(1);
            if chain == 0 {
                score -= 26.0 * (1.0 - progress);
            } else if chain <= 3 {
                score -= 11.0 * (1.0 - progress);
            }
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            let stranded = (next_item_size - post_residual) as f64;
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            if stranded <= 10.0 {
                score += (8.5 + 1.1 * (10.0 - stranded)) * scarcity * (0.4 + 0.6 * (1.0 - progress));
            } else {
                let proximity = 1.0 - (stranded - 10.0).min(cap) / cap;
                score += 3.2 * proximity * scarcity * (1.0 - progress);
            }
        }
        if dead_ratio > 0.35 && fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score += 7.5 * (dead_ratio - 0.35) * tightness * (1.0 - progress);
        }
        if post_residual > 0 && mean_residual > 0.0 {
            let gap = mean_residual - post_residual as f64;
            if gap > 0.0 && gap < 0.15 * cap && fitting_bins_count > 2 {
                score += 4.8 * (gap / (0.15 * cap)) * (1.0 - progress);
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size.max(1) && fitting_bins_count > 2 {
            score -= 6.5 * (1.0 - progress);
        }
        if post_residual == 0 && bin_residual < bin_capacity {
            score -= 42.0 * (1.0 - bin_residual as f64 / cap) * (1.0 - progress);
        }
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 1 {
            let harmony = (post_residual as f64 - mean_residual).abs() / cap;
            if harmony < 0.08 {
                score -= 9.0 * (1.0 - harmony / 0.08) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        if post_residual > 6 && post_residual <= 30 && next_item_size > 0 && next_item_size <= post_residual {
            let reps = post_residual / next_item_size.max(1);
            if reps >= 2 {
                score -= 3.5 * (reps as f64).min(4.0) * (1.0 - progress);
            }
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let after_next = post_residual - next_item_size;
            if after_next > 0 && after_next <= 12 {
                let tail = after_next as f64;
                score -= (14.0 - 0.9 * tail) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        if post_residual > 0 && post_residual < 6 && next_item_size > post_residual {
            score += 6.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let after_next = (post_residual - next_item_size) as f64;
            if after_next > 8.0 && after_next <= 16.0 && progress < 0.85 {
                let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
                score -= (4.0 + 3.0 * scarcity) * (1.0 - (after_next - 8.0) / 8.0) * (1.0 - progress);
            }
        }
        if post_residual > 0 && next_item_size > 0 && fitting_bins_count > 3 {
            let overshoot = post_residual.saturating_sub(next_item_size) as f64;
            if overshoot > 16.0 {
                score += 1.6 * ((overshoot - 16.0) / cap).min(0.25) * (1.0 - progress);
            }
        }
        if fitting_bins_count > 1 && dead_ratio > 0.08 && post_residual > 0 {
            let scarcity = 1.0 / (fitting_bins_count as f64);
            let comp_slack = (mean_residual / cap).min(1.0);
            score += 6.5 * (dead_ratio - 0.08) * scarcity * comp_slack * (0.5 + 0.5 * (1.0 - progress));
            score += 2.2 * (dead / cap) * scarcity * comp_slack * (1.0 - progress);
        }
        if fitting_bins_count > 2 && post_residual > 0 && mean_residual > 0.0 {
            let dev = ((post_residual as f64 - mean_residual).abs() / cap).min(0.4);
            score += 5.0 * dev * (1.0 - progress);
        }
        if post_residual > 0 && post_residual % 10 == 0 && post_residual <= 60 && next_item_size > 0 && next_item_size <= post_residual {
            score -= 4.0 * (1.0 - progress) * (1.0 - post_residual as f64 / 120.0);
        }
        if next_item_size > 0 && post_residual == next_item_size && fitting_bins_count <= 3 {
            score -= 30.0 / fitting_bins_count.max(1) as f64 * (0.5 + 0.5 * (1.0 - progress));
        }
        if post_residual > 0 && next_item_size > 0 && fitting_bins_count > 1 {
            let usable = next_item_size <= post_residual
                || (mean_residual as u32) >= next_item_size;
            if !usable {
                let waste_frac = post_residual as f64 / cap;
                let late = 0.35 + 0.65 * progress;
                score += 9.0 * waste_frac * late;
            }
        }
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 2 {
            let rel = post_residual as f64 / (mean_residual + 1.0);
            if rel < 0.5 {
                score -= 6.0 * (1.0 - rel / 0.5) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        if post_residual > 0 && next_item_size > 1 && next_item_size <= post_residual {
            let reps = post_residual / next_item_size;
            let rem = post_residual % next_item_size;
            if reps >= 1 && rem == 0 {
                let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
                score -= (5.0 + 6.0 * scarcity) * ((reps as f64).min(3.0)) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 1 && progress > 0.25 {
            let target = 0.5 * (mean_residual + 0.5 * cap);
            let dev = ((post_residual as f64 - target).abs() / cap).min(0.5);
            score += 2.4 * dev * (progress - 0.25);
        }
        // gen 76: near-full chain extension.
        if post_residual > 0 && next_item_size > 0 && post_residual > next_item_size {
            let after_next = post_residual - next_item_size;
            if after_next > 0 && after_next < 6 && progress > 0.35 {
                score -= 11.0 * (1.0 - after_next as f64 / 6.0) * (progress - 0.35);
            }
        }
        // gen 76: usable-residual scarcity bonus.
        if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count == 1 && bin_residual != bin_capacity {
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score -= 14.0 * (1.0 - progress) * (0.6 + 0.4 * tightness);
        }
        // gen 81: dead-space compaction gradient (gen 146: sharpen the
        // fraction coupling so near-miss leftovers are punished harder
        // while usable small leftovers keep their edge).
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
            && fitting_bins_count > 1 {
            let open_space = mean_residual * open_bins_count as f64;
            if open_space > 2.0 * cap {
                let frac = post_residual as f64 / next_item_size as f64;
                score += 12.5 * (1.0 - frac) * (1.0 - frac) * (0.4 + 0.6 * progress);
            }
        }
        // gen 81: consolidation pull (gen 146: extend earlier and scale
        // with scarcity so residual spread tightens mid-stream too).
        if post_residual > 0 && fitting_bins_count > 2 && progress > 0.4 {
            let fill = 1.0 - post_residual as f64 / cap;
            let scarcity = 1.0 / (fitting_bins_count as f64);
            score -= (5.0 + 6.0 * scarcity) * fill * (progress - 0.4);
        }
        // MUTATION (gen 146): residual-variance homogenizer — when this
        // placement's post-residual deviates strongly from the fleet mean
        // residual in the LATE stream, the outlier is hard to reuse; add a
        // quadratic deviation penalty so bins converge on a common,
        // tileable residual level, directly attacking the diagnosed
        // residual-variance weakness.
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 1 && progress > 0.5 {
            let dev = (post_residual as f64 - mean_residual) / cap;
            if dev.abs() > 0.06 {
                let excess = dev.abs() - 0.06;
                score += 9.0 * excess * excess * cap * (progress - 0.5);
            }
        }
        // MUTATION (gen 146): two-item lookahead tiling — when the next
        // item fills this bin exactly AND the following residual would be
        // an exact multiple of the mean fleet residual (a shared lane),
        // grant a deep reward so interchangeable bins stay interchangeable.
        if post_residual > 0 && next_item_size > 0 && post_residual == next_item_size
            && mean_residual > 0.0 && (mean_residual as u32) > 0 {
            let lane = post_residual % (mean_residual as u32).max(1);
            if lane <= 2 {
                score -= 16.0 * (1.0 - progress);
            }
        }
    } else {
        let fragmentation = (mean_residual / cap) * open_bins_count as f64;
        let huge_item = item_size as f64 > 0.7 * cap;
        let remaining = if total_items > step_index { total_items - step_index } else { 1 };
        let remaining_frac = remaining as f64 / total_items.max(1) as f64;
        let fresh_post = cap - item_size as f64;
        let fresh_is_exact = fresh_post <= 4.0 && fresh_post >= 0.0;

        if fragmentation > 0.55 || (huge_item && open_bins_count > 4) {
            score -= 66.0 + 46.0 * remaining_frac;
        } else if fresh_is_exact {
            score -= 134.0 + 66.0 * remaining_frac;
        } else {
            score += 400.0 - 82.0 * remaining_frac;
            if fitting_bins_count <= 3 && open_bins_count > 2 {
                score -= 30.0 + 18.0 * remaining_frac;
            }
        }

        let fresh_match = (fresh_post - mean_residual).abs() / cap;
        if fresh_match < 0.05 {
            score -= 76.0 * (1.0 - fresh_match / 0.05);
        }
        if remaining_frac < 0.05 && fresh_post > 0.0 && !fresh_is_exact {
            score += 160.0 * (fresh_post / cap);
        }
        if fresh_post > 0.0 && fresh_post <= 22.0 && !fresh_is_exact {
            score -= 26.0 * (1.0 - fresh_post / 22.0);
        }
        if fresh_post > 22.0 && fresh_post <= 40.0 && fragmentation < 0.35 {
            score -= 12.5 * (1.0 - (fresh_post - 22.0) / 18.0);
        }
        if fresh_post > 0.0 && fresh_match < 0.12 && fragmentation < 0.55 {
            score -= 30.0 * (1.0 - fresh_match / 0.12);
        }
        if next_item_size > 0 && fresh_post > 0.0 {
            let fresh_exact_next = (fresh_post as u32) == next_item_size;
            let open_can_next = mean_residual >= next_item_size as f64;
            if fresh_exact_next && !open_can_next && fitting_bins_count <= 2 {
                score -= 52.0 * (1.0 - progress);
            }
            if (fresh_post as u32) < next_item_size && mean_residual > next_item_size as f64 {
                score += 21.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && fresh_post > next_item_size as f64 {
            let chain_post = fresh_post - next_item_size as f64;
            if chain_post <= 4.0 {
                score -= 34.0 * (1.0 - chain_post / 4.0) * (0.5 + 0.5 * (1.0 - progress));
            } else if chain_post <= 10.0 {
                score -= 9.5 * (1.0 - (chain_post - 4.0) / 6.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        if remaining_frac < 0.12 && fresh_post > 0.0 && !fresh_is_exact && mean_residual * open_bins_count as f64 > 3.0 * cap {
            score += 42.0 * (1.0 - remaining_frac / 0.12);
        }
        if fitting_bins_count == 1 && fresh_post > 0.0 && next_item_size > 0 {
            let stranded_here = bin_capacity.saturating_sub(item_size);
            let would_strand = stranded_here < next_item_size;
            if would_strand && stranded_here > 0 && stranded_here <= 8 {
                score -= 32.0 * (1.0 - progress);
            }
        }
        let open_capacity = mean_residual * open_bins_count as f64;
        let per_item_need = cap * 0.5;
        if remaining_frac > 0.25 && open_capacity < per_item_need * open_bins_count.max(1) as f64 * 0.5 {
            score -= 18.0 * (1.0 - progress);
        }
        if next_item_size > 0 && fresh_post > next_item_size as f64 {
            let after_next = fresh_post - next_item_size as f64;
            if after_next > 0.0 && after_next <= 8.0 && fragmentation < 0.5 {
                score -= 20.0 * (1.0 - after_next / 8.0) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        if next_item_size > 0 && fresh_post > 0.0 && (fresh_post as u32) < next_item_size {
            let slack_total = mean_residual * open_bins_count as f64;
            if slack_total > 2.0 * cap {
                score += 26.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && (fresh_post as u32) == next_item_size && fragmentation > 0.3 {
            score -= 44.0 * (0.5 + 0.5 * (1.0 - progress));
        }
        if fresh_post > 0.5 * cap && mean_residual < 0.2 * cap && remaining_frac > 0.3 && open_bins_count > 3 {
            score += 24.0 * (fresh_post / cap - 0.5) * 2.0 * (1.0 - progress);
        }
        if fitting_bins_count <= 1 && fresh_post > 0.45 * cap && next_item_size > 0 {
            let reachable = (next_item_size as f64 / fresh_post).min(1.0);
            if reachable < 0.5 {
                score += 18.0 * (0.5 - reachable) * (1.0 - progress);
            }
        }
        if next_item_size > 0 && fresh_post > 0.0 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 2 && fragmentation < 0.5 {
                score -= 7.0 * ((reps as f64).min(4.0) - 1.0) * (0.4 + 0.6 * (1.0 - progress));
                if rem <= 3 {
                    score -= 5.0 * (1.0 - progress);
                }
            }
        }
        if fresh_post > 0.35 * cap && remaining_frac > 0.2 && mean_residual * open_bins_count as f64 > 4.0 * cap && fragmentation < 0.45 {
            score += 20.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        if remaining_frac < 0.15 && fresh_post > 0.3 * cap {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.35;
            if open_space > est_need {
                score += 55.0 * (1.0 - remaining_frac / 0.15);
            }
        }
        if remaining_frac >= 0.15 && remaining_frac < 0.45 && fresh_post > 0.4 * cap && fragmentation > 0.4 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.45;
            if open_space > est_need {
                score += 28.0 * (1.0 - remaining_frac / 0.45);
            }
        }
        if next_item_size > 1 && fresh_post > 0.0 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 2 && rem == 0 && fragmentation < 0.4 {
                score -= 10.0 * ((reps as f64).min(4.0) - 1.0) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        if remaining_frac >= 0.45 && remaining_frac < 0.5 && fresh_post > 0.45 * cap && fragmentation > 0.5 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.55;
            if open_space > est_need {
                score += 22.0 * (1.0 - remaining_frac / 0.5);
            }
        }
        // gen 76: demand-aware fresh-bin refusal.
        if remaining_frac >= 0.05 && fresh_post > 0.3 * cap && next_item_size > 0 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (next_item_size as f64) * 0.42;
            if open_space > 1.15 * est_need {
                score += 30.0 * (1.0 - remaining_frac) * (fresh_post / cap - 0.3);
            }
        }
        // gen 76: fresh-bin dead-space cap.
        if fresh_post > 0.35 * cap && next_item_size > 0 && (fresh_post as u32) < next_item_size && fragmentation < 0.4 && remaining_frac > 0.15 {
            score += 16.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        // gen 81: tileability-aware open.
        if next_item_size > 1 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 3 && rem == 0 && fragmentation < 0.3 {
                score -= 14.0 * ((reps as f64).min(5.0) - 2.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // MUTATION (gen 146): fresh-bin lane alignment — when the new bin's
        // post-residual lands within a small band of the fleet mean
        // residual, the fresh bin joins the shared residual level instead
        // of creating a new outlier class; reward this alignment so the
        // open-bin residual distribution stays unimodal and reusable.
        if fresh_post > 0.0 && mean_residual > 0.0 && open_bins_count > 1 && remaining_frac > 0.1 {
            let align = (fresh_post - mean_residual).abs() / cap;
            if align < 0.08 {
                score -= 20.0 * (1.0 - align / 0.08) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual close to 0 is good, but penalize
    // leaving a tiny unusable sliver relative to possible next item.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            // Dead space that cannot hold the next item: penalize
            let dead = post_residual as f64 / next_item_size as f64;
            score += 6.0 * dead;
        } else if next_item_size <= post_residual {
            // This bin can also host the next item: strong reward
            score -= 8.0;
        }
        // Perfect next-item fill
        if next_item_size == post_residual {
            score -= 12.0;
        }
    } else {
        // Last item: minimize waste, prefer fullest packing
        score -= 5.0;
    }

    // Exact fit reward
    if post_residual == 0 {
        score -= 20.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless
    // current fit is poor.
    if bin_residual == bin_capacity {
        // Empty bin baseline: neutral-ish, slightly penalized so we only
        // open when fits in open bins are bad.
        score += 10.0;
        // Early in stream, more bins can help; later, prefer consolidation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 4.0; // fresh bin leaves room for lookahead
        }
    }

    // Global state coupling: many open bins with high mean residual
    // suggests consolidation pressure.
    if open_bins_count > 2 {
        let consolidation = (mean_residual / bin_capacity as f64) * (open_bins_count as f64).ln();
        // Reward placing into bins with large residuals (use up fat bins)
        score -= 2.0 * consolidation * (bin_residual as f64 / bin_capacity as f64);
    }

    // Penalize creating residuals in the awkward zone (1..10 unusable slivers)
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Mild preference for bins whose residual is close to item size
    // (best-fit flavor), scaled non-linearly.
    let fit_gap = (bin_residual - item_size) as f64;
    score += 0.05 * fit_gap * fit_gap / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Layered dead-space rewards (lower post_residual = better).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 4 {
        score -= 250.0 + 4.2 * (4 - post_residual) as f64;
    } else if post_residual <= 10 {
        score -= 64.0 + 3.6 * (10 - post_residual) as f64;
    } else if post_residual <= 22 {
        score -= 13.5 + 1.5 * (22 - post_residual) as f64;
    } else if post_residual <= 32 {
        score -= 5.0 + 0.7 * (32 - post_residual) as f64;
    } else if post_residual <= 48 {
        score -= 1.2 + 0.22 * (48 - post_residual) as f64;
    } else {
        score -= 1.2 - 0.014 * (post_residual as f64 - 48.0);
    }

    let w = 0.33 + 0.67 * progress * progress;
    score *= w;

    // Lookahead coupling with the next item.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if next_item_size < post_residual {
            let two_step_waste = (post_residual - next_item_size) as f64;
            if two_step_waste <= 8.0 {
                score -= 135.0 - 2.3 * two_step_waste;
            } else {
                score -= 72.0 - 0.58 * two_step_waste;
            }
            if two_step_waste <= 3.0 {
                score -= 48.0;
            }
        } else {
            let miss = (next_item_size - post_residual) as f64;
            score += 0.95 * miss;
            if miss > 26.0 {
                score += 0.55 * (miss - 26.0);
            }
        }
    }

    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
        let boost = 36.0 + 26.0 * scarcity;
        score -= boost * (1.0 - slack / cap) * (0.6 + 0.4 * (1.0 - progress));
        if fitting_bins_count <= 2 {
            score -= 15.0 * (1.0 - slack / cap);
        }
        if slack == 0.0 {
            score -= 20.0 * (1.0 - progress);
        }
    }

    if bin_residual != bin_capacity {
        let dead = (bin_residual - item_size) as f64;
        let dead_ratio = dead / cap;
        if dead_ratio > 0.5 && fitting_bins_count > 1 {
            score += 10.5 * (dead_ratio - 0.5) * (1.0 - progress);
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
            && mean_residual > 0.0 && (mean_residual as u32) >= next_item_size {
            score += 12.0;
        }
        if post_residual > 12 && post_residual < 40 && next_item_size > post_residual {
            let orphan = (post_residual as f64 - 12.0) / 28.0;
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            score += 17.0 * orphan * scarcity * (0.5 + 0.5 * (1.0 - progress));
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let chain = post_residual % next_item_size.max(1);
            if chain == 0 {
                score -= 26.0 * (1.0 - progress);
            } else if chain <= 3 {
                score -= 11.0 * (1.0 - progress);
            }
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            let stranded = (next_item_size - post_residual) as f64;
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            if stranded <= 10.0 {
                score += (8.5 + 1.1 * (10.0 - stranded)) * scarcity * (0.4 + 0.6 * (1.0 - progress));
            } else {
                let proximity = 1.0 - (stranded - 10.0).min(cap) / cap;
                score += 3.2 * proximity * scarcity * (1.0 - progress);
            }
        }
        if dead_ratio > 0.35 && fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score += 7.5 * (dead_ratio - 0.35) * tightness * (1.0 - progress);
        }
        if post_residual > 0 && mean_residual > 0.0 {
            let gap = mean_residual - post_residual as f64;
            if gap > 0.0 && gap < 0.15 * cap && fitting_bins_count > 2 {
                score += 4.8 * (gap / (0.15 * cap)) * (1.0 - progress);
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size.max(1) && fitting_bins_count > 2 {
            score -= 6.5 * (1.0 - progress);
        }
        if post_residual == 0 && bin_residual < bin_capacity {
            score -= 42.0 * (1.0 - bin_residual as f64 / cap) * (1.0 - progress);
        }
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 1 {
            let harmony = (post_residual as f64 - mean_residual).abs() / cap;
            if harmony < 0.08 {
                score -= 9.0 * (1.0 - harmony / 0.08) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        if post_residual > 6 && post_residual <= 30 && next_item_size > 0 && next_item_size <= post_residual {
            let reps = post_residual / next_item_size.max(1);
            if reps >= 2 {
                score -= 3.5 * (reps as f64).min(4.0) * (1.0 - progress);
            }
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let after_next = post_residual - next_item_size;
