    }

    // MUTATION (gen 150): wide-open drain — when aggregate open slack is
    // very large, penalize leaving any residual above the next item size so
    // the worst dead-space bins get drained first (targets the diagnosed
    // dead-space ratio weakness).
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0 && fitting_bins_count > 2 {
        let open_space = mean_residual * open_bins_count as f64;
        if open_space > 3.0 * cap && post_residual > next_item_size {
