            score += 8.0 * excess.min(0.4) * (0.4 + 0.6 * progress);
        }
    }

    // MUTATION (gen 150): scarcity-weighted exact-fit deepening — when few
    // bins can fit the item and the placement nearly closes the bin
    // (residual <= 3), reward strongly regardless of progress phase.
    if fitting_bins_count <= 2 && post_residual > 0 && post_residual <= 3 {
        score -= 26.0 * (1.0 - post_residual as f64 / 3.0) * (0.5 + 0.5 * (1.0 - progress));
    }

