            }
        }
        if fresh_post > 0.0 && fresh_match < 0.2 && fragmentation < 0.5 && remaining_frac > 0.1 {
            score -= 14.0 * (1.0 - fresh_match / 0.2) * (0.5 + 0.5 * (1.0 - progress));
        }
        if remaining_frac > 0.1 && fresh_post > 0.45 * cap && next_item_size > 0 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (next_item_size as f64) * 0.5;
            if open_space > 1.3 * est_need {
                score += 24.0 * (1.0 - remaining_frac) * (fresh_post / cap - 0.45);
            }
        }
        if next_item_size > 1 && fresh_post > 0.0 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            let open_space = mean_residual * open_bins_count as f64;
            if reps >= 2 && rem == 0 && open_space < 1.5 * cap {
                score -= 16.0 * ((reps as f64).min(4.0) - 1.0) * (1.0 - progress);
            }
        }
        if next_item_size > 0 && fresh_post > 0.0 && (fresh_post as u32) == next_item_size {
            score -= 40.0 * (0.5 + 0.5 * (1.0 - progress));
        }
        if fresh_post > 0.55 * cap && next_item_size > 0 && (fresh_post as u32) < next_item_size
            && mean_residual * open_bins_count as f64 > 2.0 * cap {
            score += 30.0 * (fresh_post / cap - 0.55) * (0.5 + 0.5 * (1.0 - progress));
        }
        // MUTATION (gen 150): tileable fresh lane — when the fresh bin's
        // leftover is an exact multiple of the next item AND the next item
        // cannot fit any open bin, opening here creates a dedicated tiling
        // lane; reward it (combines lookahead with open decision).
        if next_item_size > 1 && fresh_post > 0.0 && (fresh_post as u32) % next_item_size == 0
            && (fresh_post as u32) >= next_item_size
            && mean_residual < next_item_size as f64 && fitting_bins_count <= 2 {
            score -= 22.0 * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residues divisible by common item sizes
    // (10, 20, 25, 50) are more reusable, so reward them.
    let pr = post_residual;
    let harmonic_bonus = if pr == 0 {
        -60.0 // perfect fit is best
    } else if pr % 10 == 0 {
        -12.0
    } else if pr % 5 == 0 {
        -6.0
    } else {
        8.0
    };
    score += harmonic_bonus;

    // Integer-division thresholds: leftover in [0..=10] is nearly perfect;
    // leftover in (50..100) is a "half bin" — very reusable.
    if pr <= 10 {
        score -= 25.0;
    } else if pr > 50 {
        score -= 15.0;
    } else if pr > 30 {
        score -= 5.0;
    } else {
        score += 10.0; // dead zone: awkward mid-size remainder
    }

    // Capacity fraction coupling: how much of the bin the item consumes
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= fill_frac * 20.0; // reward filling bins densely

    // Lookahead: if the next item fits exactly in the post residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr && pr % next_item_size == 0 {
            score -= 20.0; // next item tiles the leftover exactly
        } else if next_item_size <= pr {
            score -= 8.0;
        } else {
            // next item won't fit here; penalize leaving large unusable gaps
            score += (pr as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a bin should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        // neutral baseline slightly above a good fit; drop when many bins already open poorly
        score += 55.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // nothing fits: must open new bin
        }
    }

    // Stream progression: later in the stream, prefer consolidating into fewer bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0 * (open_bins_count as f64).ln().max(0.0) * 0.5;

    // Mean-residual coupling: if this bin is far above mean residual, it's a laggard; use it.
    score += (bin_residual as f64 - mean_residual) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
