        if post_residual > 0 && next_item_size > 1 && post_residual >= next_item_size {
            let after_next = post_residual - next_item_size;
            if after_next >= next_item_size {
                let tiles = (after_next / next_item_size) as f64;
                let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
                score -= (6.0 + 5.0 * scarcity) * tiles.min(3.0) * (0.5 + 0.5 * (1.0 - progress));
            } else if after_next > 0 && after_next <= 2 {
