            }
        }
        // gen 147: residual-parity pairing.
        if post_residual > 0 && next_item_size > 0 && mean_residual > 0.0 && fitting_bins_count > 2 {
            let projected = post_residual as f64;
            let dev = (projected - mean_residual).abs();
            if dev <= 6.0 {
                score -= 5.0 * (1.0 - dev / 6.0) * (0.3 + 0.7 * progress);
            }
        }
        // MUTATION (gen 150): exact-fill anticipation — when the next item
        // exactly matches the post-residual, the scarcity of such lanes
        // matters: reward more strongly when few bins can host the next
        // item, since wasting the only perfect lane is the costliest error.
        if next_item_size > 0 && post_residual == next_item_size {
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            score -= 40.0 * scarcity * (0.5 + 0.5 * (1.0 - progress));
        }
        // MUTATION (gen 150): dead-space tightening gradient — combine the
        // dead-space ratio with the projected post-residual: a placement
        // that both strands dead space and leaves a residual smaller than
        // the next item is a double loss; penalize proportionally so
        // residual variance shrinks.
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
            && dead_ratio > 0.3 && fitting_bins_count > 1 {
            let stranded = (next_item_size - post_residual) as f64;
            score += 9.0 * (dead_ratio - 0.3) * (stranded / cap).min(1.0) * (0.4 + 0.6 * progress);
        }
        // MUTATION (gen 150): late-stream exact-closure bonus — near the
        // end of the stream, bins that close exactly (post_residual == 0)
        // free the fleet from carrying residual; deepen the reward with
