            let est_need = (remaining as f64) * (item_size as f64) * 0.55;
            if open_space > est_need {
                score += 22.0 * (1.0 - remaining_frac / 0.5);
            }
        }
        // gen 76: demand-aware fresh-bin refusal.
        if remaining_frac >= 0.05 && fresh_post > 0.3 * cap && next_item_size > 0 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (next_item_size as f64) * 0.42;
            if open_space > 1.15 * est_need {
                score += 30.0 * (1.0 - remaining_frac) * (fresh_post / cap - 0.3);
            }
        }
        // gen 76: fresh-bin dead-space cap.
        if fresh_post > 0.35 * cap && next_item_size > 0 && (fresh_post as u32) < next_item_size && fragmentation < 0.4 && remaining_frac > 0.15 {
            score += 16.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        // gen 81: tileability-aware open.
        if next_item_size > 1 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 3 && rem == 0 && fragmentation < 0.3 {
                score -= 14.0 * ((reps as f64).min(5.0) - 2.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // gen 138: lane-diversity open.
        if next_item_size > 0 && fresh_post > 0.0 && fragmentation > 0.45 && remaining_frac > 0.2 {
            let dup = ((fresh_post - mean_residual).abs() / cap) < 0.08;
            if !dup && (fresh_post as u32) >= next_item_size {
                score -= 9.0 * (1.0 - progress) * (0.4 + 0.6 * (fragmentation - 0.45) / 0.55);
            }
        }
        // gen 142: tileable-lane open preference.
        if next_item_size > 1 && remaining_frac > 0.1 && fragmentation < 0.5 {
            let open_can_tile = mean_residual >= next_item_size as f64
                && (mean_residual as u32) % next_item_size == 0;
            if (fresh_post as u32) % next_item_size == 0 && (fresh_post as u32) >= 2 * next_item_size && !open_can_tile {
                score -= 12.0 * (1.0 - progress) * (0.5 + 0.5 * (1.0 - fragmentation));
            }
        }
        // gen 147: slack-aware fresh-bin gate.
        if remaining_frac > 0.08 && fresh_post > 0.0 && next_item_size > 0 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (next_item_size as f64) * 0.5;
            if open_space > 1.3 * est_need && (fresh_post as u32) > next_item_size {
                let surplus = ((open_space - est_need) / (4.0 * cap)).min(1.0);
                score += 18.0 * surplus * (fresh_post / cap) * (1.0 - remaining_frac / 0.08).abs().min(1.0);
            }
        }
        // MUTATION (gen 150): exact-lane fresh gate — when the fresh bin's
        // post-residual exactly matches the next item size and no open bin
        // can host the next item, opening creates a perfect lane; reward
        // this strongly since it prevents future waste.
        if next_item_size > 0 && (fresh_post as u32) == next_item_size && !open_bins_can_fit(mean_residual, open_bins_count, next_item_size) {
            score -= 20.0 * (1.0 - progress);
        }
    }

    score
}

// MUTATION (gen 150): helper — checks whether any open bin could host the
// next item based on the mean residual (aggregate signal, no per-bin data
// available in this scope; a conservative proxy).
fn open_bins_can_fit(mean_residual: f64, open_bins_count: usize, next_item_size: u32) -> bool {
    mean_residual * open_bins_count as f64 >= next_item_size as f64
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that likely cannot host any future
    // item (items >= 1, but realistically >= 10 in typical streams) are pure waste.
    // Penalize small post_residuals super-linearly.
    if post_residual > 0 {
        let gap = post_residual as f64;
        // A gap is "dead" if it's too small for the next item or generally tiny.
        if next_item_size > 0 && post_residual < next_item_size {
            score += 60.0 + (next_item_size - post_residual) as f64 * 1.5;
        }
        if gap <= 12.0 {
            // Nearly unusable sliver: heavy penalty, worse the tighter the fit.
            score += (12.0 - gap) * 8.0;
        } else if gap <= 25.0 {
            score += (25.0 - gap) * 2.0;
        }
    } else {
        // Perfect fill: strong reward.
        score -= 120.0;
    }

    // Reward tight fits (small waste relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 40.0;

    // Last-chance pressure: if this is the only fitting bin, avoid forcing a
    // new bin unless the fit is genuinely bad.
    if fitting_bins_count == 1 && post_residual > 0 {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones;
    // with few open bins, opening a new bin is cheaper.
    let pressure = (open_bins_count as f64).ln().max(0.0) * 6.0;
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // Lookahead: if next item fits exactly in the post-residual, reward this bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 80.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Make it attractive only when the current fit is poor and bins are scarce.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 <= 10.0 && post_residual > 0;
        if poor_fit && open_bins_count > 0 {
            score -= 30.0; // allow escaping a dead-space fit
        } else {
            score += 35.0; // generally prefer reusing open bins
        }
    }

    // Mild stream-progress term: later in the stream, consolidation matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64 / bin_capacity as f64) * 10.0;

    // Mean-residual coupling: when average residual is high, avoid adding to it.
    score += (mean_residual - post_residual as f64).max(0.0) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Layered dead-space rewards (lower post_residual = better).
