        // directly attacking residual variance.
        if next_item_size > 0 && post_residual >= 2 * next_item_size && post_residual > 0 {
            let chain_len = (post_residual / next_item_size) as f64;
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            score -= (2.8 + 5.5 * scarcity) * (chain_len - 1.0).min(4.0) * (0.45 + 0.55 * (1.0 - progress));
