    if bin_residual != bin_capacity && next_item_size > 1 && post_residual > next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next > 0 && after_next % next_item_size == 0 && after_next / next_item_size >= 2 {
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            score -= (12.0 + 8.0 * scarcity) * (0.5 + 0.5 * (1.0 - progress));
        }
    }

