pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let br = bin_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: post residual, normalized
    let mut score = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let pn = pr / cap; // normalized post residual in [0,1]
    let poly = pn * pn * (1.0 - progress) + pn * pn * pn * progress;
    score += 2.0 * poly;

    // Reward tight fits: low post residual gets a smooth cubic discount
    let tight = (1.0 - pn).powi(3);
    score -= 1.5 * tight;

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 3.0;
    }

    // Penalty when residual after placement can't fit the lookahead item
    if next_item_size > 0 && (post_residual as u32) < next_item_size {
        let gap = (next_item_size as f64 - pr) / cap;
        score += 0.8 * gap * gap;
    } else if next_item_size > 0 {
        // Reward bins whose leftover exactly accommodates lookahead
        let diff = (pr - next_item_size as f64) / cap;
        score -= 0.5 * (1.0 - diff).max(0.0);
    }

    // Discourage opening new bins early; allow it late when residuals are fragmented
    let new_bin = (bin_residual as u32 == bin_capacity) as f64;
    let fragmentation = (mean_residual - br).abs() / cap;
    score += new_bin * (0.6 - 0.8 * progress + 0.3 * fragmentation);

    // Mild preference for bins deviating from mean residual (consolidation)
    score += 0.2 * fragmentation * (1.0 - progress);

    score
}

