            && fitting_bins_count > 1 {
            let open_space = mean_residual * open_bins_count as f64;
            if open_space > 1.5 * cap {
                let frac = post_residual as f64 / next_item_size as f64;
                score += 12.0 * (1.0 - frac) * (0.4 + 0.6 * progress);
            }
        }
        // gen 81: consolidation pull (refined gen 151: extend earlier into the
        // stream and strengthen with scarcity so residual variance shrinks
        // while tight bins are still favored when alternatives are few).
        if post_residual > 0 && fitting_bins_count > 2 && progress > 0.4 {
            let fill = 1.0 - post_residual as f64 / cap;
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            score -= (5.0 + 8.0 * scarcity) * fill * (progress - 0.4);
        }
        // MUTATION (gen 151): residual-band harmonizer — when the placement
        // leaves a residual close to the fleet mean, slack across bins stays
        // mutually usable (any future item fits many bins); reward that
        // agreement proportionally, strongest mid-stream where consolidation
        // decisions compound.
        if post_residual > 0 && mean_residual > 0.0 && open_bins_count > 2 {
            let rel_dev = ((post_residual as f64 - mean_residual) / mean_residual).abs();
            if rel_dev < 0.15 {
