pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: buckets by capacity fraction (integer division)
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class A: post_residual in [0, cap/8) — near-perfect fit, strong reward
    if post_residual * 8 < bin_capacity {
        score -= 25.0;
    }
    // Class B: post_residual in [cap/8, cap/4) — good fit
    else if post_residual * 4 < bin_capacity {
        score -= 12.0;
    }
    // Class C: post_residual in [cap/2, cap] — large residual left, penalize lightly
    else if post_residual * 2 >= bin_capacity {
        score += 10.0;
    }

    // Modulo arithmetic: post_residual divisible by small harmonics (5,10) => more reusable
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    } else if post_residual % 5 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // Lookahead coupling: does next_item_size fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chain fit
        } else if next_item_size < post_residual {
            // next fits: reward proportionally to how well it fills
            let fill_ratio = next_item_size as f64 / pr.max(1.0);
            score -= 15.0 * fill_ratio;
            // harmonic class of leftover after next item
            let second_left = post_residual - next_item_size;
            if second_left * 4 < bin_capacity {
                score -= 8.0;
            }
        } else {
            // next item cannot use this residual: penalize large wasted residual
            score += 5.0 + 0.1 * pr;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a bin unless residuals elsewhere are hopeless
    if bin_residual == bin_capacity {
        score += 55.0;
        // early stream: new bins cheaper to open
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * (1.0 - progress);
        // if many open bins with large mean residual, discourage new bin further
        score += 0.15 * mean_residual;
        // if next item is huge, opening fresh bin may be wise
        if next_item_size as f64 > 0.6 * cap {
            score -= 15.0;
        }
    }

    // Dead-space penalty: residual too small for any plausible item (min size 1)
    if post_residual == 0 {
        score -= 50.0; // perfect fill
    } else if post_residual < 4 {
        score -= 20.0; // effectively dead but bin nearly full
    }

    // Coupling with mean residual: prefer bins whose residual is below mean (tighter bins)
    score += 0.05 * (mean_residual - pr);

    // Open bins pressure: many open bins -> prefer filling existing ones
    score += 0.5 * open_bins_count as f64;

    score
}

