            }
        }
        // MUTATION (gen 127): tileable-lane fresh bonus.
        if next_item_size > 1 && fresh_post > 0.0 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            let open_space = mean_residual * open_bins_count as f64;
            if reps >= 2 && rem == 0 && open_space < 1.5 * cap {
                score -= 16.0 * ((reps as f64).min(4.0) - 1.0) * (1.0 - progress);
            }
        }
        // MUTATION (gen 128): fresh-bin exact-closure lane.
        if next_item_size > 0 && fresh_post > 0.0 && (fresh_post as u32) == next_item_size {
            score -= 40.0 * (0.5 + 0.5 * (1.0 - progress));
        }
        // MUTATION (gen 128): oversized-fresh refusal.
        if fresh_post > 0.55 * cap && next_item_size > 0 && (fresh_post as u32) < next_item_size
            && mean_residual * open_bins_count as f64 > 2.0 * cap {
            score += 30.0 * (fresh_post / cap - 0.55) * (0.5 + 0.5 * (1.0 - progress));
        }
        // MUTATION (gen 153): fresh-bin chain-exact lane.
        if next_item_size > 0 && fresh_post > next_item_size as f64 {
            let chain_post = fresh_post - next_item_size as f64;
            if chain_post > 0.0 && chain_post <= 4.0 && fragmentation < 0.5 {
                let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
                score -= (12.0 + 8.0 * scarcity) * (1.0 - chain_post / 4.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // MUTATION (gen 154): fresh-bin wide-chain lane — when the fresh
        // leftover minus the next item is a moderate tail (8..=14), opening
        // still beats scattering slack across fragmented open bins provided
        // aggregate slack is thin; reward moderately to preserve two-step
        // compaction without over-opening.
        if next_item_size > 0 && fresh_post > next_item_size as f64 {
            let chain_post = fresh_post - next_item_size as f64;
            let open_space = mean_residual * open_bins_count as f64;
            if chain_post > 8.0 && chain_post <= 14.0 && open_space < 2.0 * cap && remaining_frac > 0.1 {
                score -= 7.0 * (1.0 - (chain_post - 8.0) / 6.0) * (1.0 - progress);
            }
        }
        // MUTATION (gen 154): two-step exact fresh closure — opening a bin
        // that item + next item fill completely guarantees zero waste over
        // two steps; deepen the reward when open slack cannot do the same.
        if next_item_size > 0 && item_size + next_item_size == bin_capacity {
            let open_can_two = mean_residual >= (item_size + next_item_size) as f64;
            if !open_can_two {
                score -= 48.0 * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // MUTATION (gen 154): late fresh-bin hard refusal — when the stream
        // is nearly done and aggregate open slack exceeds the expected
        // remaining demand, opening any new bin is pure waste.
        if remaining_frac < 0.08 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * ((item_size as f64 + next_item_size as f64) * 0.5);
            if open_space > est_need {
                score += 90.0 * (1.0 - remaining_frac / 0.08);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward residuals that exactly match the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect two-item pairing
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // penalize leftover dead space after hypothetically fitting next item
            score += 0.5 * slack;
            // bonus if next item still fits with small slack
            if slack <= 15.0 {
                score -= 25.0 - 1.2 * slack;
            }
        } else {
            // next item won't fit: residual becomes pure dead space
            let gap = (next_item_size - post_residual) as f64;
            score += 0.3 * gap;
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than the average residual
    let mean_diff = post_residual as f64 - mean_residual;
    score += 0.25 * mean_diff;

    // Penalize near-empty-but-not-empty residuals (awkward mid-range dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 20.0; // tiny slivers are worthless
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: keep it neutral-ish; only attractive when current bins are poor fits
    if bin_residual == bin_capacity {
        score += 15.0 + 0.1 * open_bins_count as f64;
        // but if next item is large and current post_residual can't host it, new bin less bad
        if next_item_size > post_residual {
            score -= 10.0;
        }
    }

    // Late-stream tightening: as stream progresses, be greedier about tight fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - (post_residual as f64 / bin_capacity as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
