    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let norm_pr = pr / cap;
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * (1.0 - progress) * (1.0 - progress);
    score += 25.0 * poly;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (10.0 + 20.0 * progress);

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += (nx - pr) * (0.5 + progress);
        } else {
            score -= 3.0 * (1.0 - ((pr - nx) / cap).min(1.0));
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 * (1.0 - norm_pr);
    }

    // Mild penalty when many bins are open and this placement wastes space
    score += 0.02 * open_bins_count as f64 * norm_pr * (1.0 + progress);

    // Encourage keeping residuals near common next-item sizes
    if next_item_size > 0 && pr >= next_item_size as f64 {
        score -= 5.0 * (1.0 - ((pr - next_item_size as f64) / 20.0).min(1.0)) * (1.0 - progress);
