            score -= 8.0 * (1.0 - progress);
        } else if chain <= 3 {
            score -= 3.5 * (1.0 - progress);
        }
    }

    // Overshoot squeeze.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0 && fitting_bins_count > 3 {
        let overshoot = post_residual.saturating_sub(next_item_size) as f64;
        if overshoot > 16.0 {
            score += 1.8 * ((overshoot - 16.0) / cap).min(0.25) * (1.0 - progress);
        }
    }

    // Exact-closure scarcity lane.
    if next_item_size > 0 && post_residual == next_item_size && bin_residual != bin_capacity && fitting_bins_count <= 3 {
        score -= 12.0 / fitting_bins_count.max(1) as f64 * (0.5 + 0.5 * (1.0 - progress));
    }

    // MUTATION (gen 155): variance-collapse lane — among fitting bins, prefer
    // the placement whose post-residual lands closest to a shared target
    // (blend of mean residual and the next item's needs) so leftover slack
    // across bins becomes homogeneous and re-usable by later items.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0 && fitting_bins_count > 2 && progress > 0.2 {
        let target = if next_item_size as f64 > mean_residual { next_item_size as f64 } else { mean_residual };
        let dev = (post_residual as f64 - target).abs() / cap;
        if dev < 0.12 {
            score -= 6.0 * (1.0 - dev / 0.12) * (progress - 0.2);
        }
    }

    // MUTATION (gen 155): two-step exact packing — when this item plus the
    // next item exactly fills the bin's remaining space, reward strongly
    // with scarcity weighting; this directly reduces residual variance by
    // closing bins in pairs instead of leaving mid-range tails.
    if next_item_size > 0 && bin_residual >= item_size {
        let two_step_left = bin_residual - item_size - next_item_size;
        if two_step_left == 0 {
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            score -= 26.0 * (1.0 + scarcity) * (0.5 + 0.5 * (1.0 - progress));
        } else if two_step_left <= 3 {
            score -= 9.0 * (1.0 - two_step_left as f64 / 3.0) * (1.0 - progress);
        }
    }

    // MUTATION (gen 155): late-stream zero-waste lane — in the final third,
    // any placement that does not leave a residual usable by the next item
    // is penalized more sharply, since leftover slack can no longer be
    // amortized over many future items.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0
        && post_residual < next_item_size && progress > 0.66 {
        let waste_frac = post_residual as f64 / cap;
        score += 14.0 * waste_frac * (progress - 0.66) * (1.0 + 1.0 / fitting_bins_count.max(1) as f64);
    }

    if bin_residual == bin_capacity {
        // NEW-BIN CANDIDATE branch.
        let fragmentation = (mean_residual / cap) * open_bins_count as f64;
        let huge_item = item_size as f64 > 0.7 * cap;
        let remaining = if total_items > step_index { total_items - step_index } else { 1 };
        let remaining_frac = remaining as f64 / total_items.max(1) as f64;
        let fresh_post = cap - item_size as f64;
        let fresh_is_exact = fresh_post <= 4.0 && fresh_post >= 0.0;

        if fragmentation > 0.55 || (huge_item && open_bins_count > 4) {
            score -= 66.0 + 46.0 * remaining_frac;
        } else if fresh_is_exact {
            score -= 134.0 + 66.0 * remaining_frac;
        } else {
            score += 400.0 - 82.0 * remaining_frac;
            if fitting_bins_count <= 3 && open_bins_count > 2 {
                score -= 30.0 + 18.0 * remaining_frac;
            }
        }

        let fresh_match = (fresh_post - mean_residual).abs() / cap;
        if fresh_match < 0.05 {
            score -= 76.0 * (1.0 - fresh_match / 0.05);
        }
        if remaining_frac < 0.05 && fresh_post > 0.0 && !fresh_is_exact {
            score += 160.0 * (fresh_post / cap);
        }
        if fresh_post > 0.0 && fresh_post <= 22.0 && !fresh_is_exact {
            score -= 26.0 * (1.0 - fresh_post / 22.0);
        }
        if fresh_post > 22.0 && fresh_post <= 40.0 && fragmentation < 0.35 {
            score -= 12.5 * (1.0 - (fresh_post - 22.0) / 18.0);
        }
        if fresh_post > 0.0 && fresh_match < 0.12 && fragmentation < 0.55 {
            score -= 30.0 * (1.0 - fresh_match / 0.12);
        }
        if next_item_size > 0 && fresh_post > 0.0 {
            let fresh_exact_next = (fresh_post as u32) == next_item_size;
            let open_can_next = mean_residual >= next_item_size as f64;
            if fresh_exact_next && !open_can_next && fitting_bins_count <= 2 {
                score -= 52.0 * (1.0 - progress);
            }
            if (fresh_post as u32) < next_item_size && mean_residual > next_item_size as f64 {
                score += 21.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && fresh_post > next_item_size as f64 {
            let chain_post = fresh_post - next_item_size as f64;
            if chain_post <= 4.0 {
                score -= 34.0 * (1.0 - chain_post / 4.0) * (0.5 + 0.5 * (1.0 - progress));
            } else if chain_post <= 10.0 {
                score -= 9.5 * (1.0 - (chain_post - 4.0) / 6.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        if remaining_frac < 0.12 && fresh_post > 0.0 && !fresh_is_exact && mean_residual * open_bins_count as f64 > 3.0 * cap {
            score += 42.0 * (1.0 - remaining_frac / 0.12);
        }
        // Refuse fresh bins late when open slack covers projected demand.
        if remaining_frac < 0.15 && fresh_post > 0.3 * cap {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.35;
            if open_space > est_need {
                score += 55.0 * (1.0 - remaining_frac / 0.15);
            }
        }
        // Mid-stream refusal band.
        if remaining_frac >= 0.15 && remaining_frac < 0.45 && fresh_post > 0.4 * cap && fragmentation > 0.4 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.45;
            if open_space > est_need {
                score += 28.0 * (1.0 - remaining_frac / 0.45);
            }
        }
        // Demand-aware fresh-bin refusal.
        if remaining_frac >= 0.05 && fresh_post > 0.3 * cap && next_item_size > 0 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (next_item_size as f64) * 0.42;
            if open_space > 1.15 * est_need {
                score += 32.0 * (1.0 - remaining_frac) * (fresh_post / cap - 0.3);
            }
        }
        // Fresh-bin dead-space cap.
        if fresh_post > 0.35 * cap && next_item_size > 0 && (fresh_post as u32) < next_item_size && fragmentation < 0.4 && remaining_frac > 0.15 {
            score += 17.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        // Tiling-aware fresh-bin bonus.
        if next_item_size > 1 && fresh_post > 0.0 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 2 && rem == 0 && fragmentation < 0.4 {
                score -= 10.0 * ((reps as f64).min(4.0) - 1.0) * (0.4 + 0.6 * (1.0 - progress));
            }
            if reps >= 3 && rem == 0 && fragmentation < 0.3 {
                score -= 14.0 * ((reps as f64).min(5.0) - 2.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // Fresh-bin residual-magnitude guard.
        if fresh_post > 0.35 * cap && remaining_frac > 0.2 && mean_residual * open_bins_count as f64 > 4.0 * cap && fragmentation < 0.45 {
            score += 20.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        // Single-fit fresh-bin rescue.
        if fitting_bins_count <= 1 && fresh_post > 0.0 && next_item_size > 0 {
            let stranded_here = bin_capacity.saturating_sub(item_size);
            let would_strand = stranded_here < next_item_size;
            if would_strand && stranded_here > 0 && stranded_here <= 8 {
                score -= 32.0 * (1.0 - progress);
            }
        }
        // Residual-harmony fresh-bin bonus.
        if fresh_post > 0.0 && fresh_match < 0.2 && fragmentation < 0.5 && remaining_frac > 0.1 {
            score -= 14.0 * (1.0 - fresh_match / 0.2) * (0.5 + 0.5 * (1.0 - progress));
        }
        // Demand-cushion fresh-bin gate.
        if remaining_frac > 0.1 && fresh_post > 0.45 * cap && next_item_size > 0 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (next_item_size as f64) * 0.5;
            if open_space > 1.3 * est_need {
                score += 24.0 * (1.0 - remaining_frac) * (fresh_post / cap - 0.45);
            }
        }
        // Tileable-lane fresh bonus.
        if next_item_size > 1 && fresh_post > 0.0 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            let open_space = mean_residual * open_bins_count as f64;
            if reps >= 2 && rem == 0 && open_space < 1.5 * cap {
                score -= 16.0 * ((reps as f64).min(4.0) - 1.0) * (1.0 - progress);
            }
        }
        // Fresh-bin exact-closure lane.
        if next_item_size > 0 && fresh_post > 0.0 && (fresh_post as u32) == next_item_size {
            score -= 40.0 * (0.5 + 0.5 * (1.0 - progress));
        }
        // Oversized-fresh refusal.
        if fresh_post > 0.55 * cap && next_item_size > 0 && (fresh_post as u32) < next_item_size
            && mean_residual * open_bins_count as f64 > 2.0 * cap {
            score += 30.0 * (fresh_post / cap - 0.55) * (0.5 + 0.5 * (1.0 - progress));
        }
        // Fresh-bin chain-exact lane.
        if next_item_size > 0 && fresh_post > next_item_size as f64 {
            let chain_post = fresh_post - next_item_size as f64;
            if chain_post > 0.0 && chain_post <= 4.0 && fragmentation < 0.5 {
                let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
                score -= (12.0 + 8.0 * scarcity) * (1.0 - chain_post / 4.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // Fresh-bin wide-chain lane.
        if next_item_size > 0 && fresh_post > next_item_size as f64 {
            let chain_post = fresh_post - next_item_size as f64;
            let open_space = mean_residual * open_bins_count as f64;
            if chain_post > 8.0 && chain_post <= 14.0 && open_space < 2.0 * cap && remaining_frac > 0.1 {
                score -= 7.0 * (1.0 - (chain_post - 8.0) / 6.0) * (1.0 - progress);
            }
        }
        // MUTATION (gen 155): fresh-bin pair-closure — opening a bin whose
        // leftover exactly accommodates the next item creates a guaranteed
        // two-item closure; reward when open bins cannot offer the same.
        if next_item_size > 0 && fresh_post > 0.0 && (fresh_post as u32) >= next_item_size {
            let two_left = (fresh_post as u32) - next_item_size;
            if two_left == 0 && mean_residual < next_item_size as f64 {
                score -= 22.0 * (0.5 + 0.5 * (1.0 - progress));
            } else if two_left <= 3 && mean_residual < next_item_size as f64 && remaining_frac > 0.1 {
                score -= 8.0 * (1.0 - two_left as f64 / 3.0) * (1.0 - progress);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are the worst outcome.
    let pr = post_residual as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - pr * 3.0; // tiny gap: heavily penalized
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit: strong reward
    }

    // Reward tight fits relative to the item size (waste ratio).
    score -= (item_size as f64 / bin_capacity as f64) * 12.0;

    // Lookahead: if next item fits exactly in the post residual, reward this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // next item cannot use this gap: penalize proportional gap size
            score += (post_residual as f64) * 0.5;
        }
    }

    // Last-chance bonus: only bin that fits -> avoid opening a new bin unless fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += (open_bins_count as f64) * 1.5;

    // Mean residual coupling: prefer bins below mean residual (tighter bins first).
    score += (mean_residual - bin_residual as f64) * 0.6;

    // New-bin candidate: only attractive when the item is large and no good fit exists.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        let poor_options = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score = 100.0 - large_item * 30.0 - poor_options * 60.0
            + (open_bins_count as f64) * 4.0;
        // late in stream, prefer closing out bins rather than opening new ones
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
