        }
        if remaining_frac >= 0.45 && remaining_frac < 0.5 && fresh_post > 0.45 * cap && fragmentation > 0.5 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.55;
            if open_space > est_need {
                score += 22.0 * (1.0 - remaining_frac / 0.5);
            }
        }
        // demand-aware fresh-bin refusal.
        if remaining_frac >= 0.05 && fresh_post > 0.3 * cap && next_item_size > 0 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (next_item_size as f64) * 0.42;
            if open_space > 1.15 * est_need {
                score += 30.0 * (1.0 - remaining_frac) * (fresh_post / cap - 0.3);
            }
        }
        // fresh-bin dead-space cap.
        if fresh_post > 0.35 * cap && next_item_size > 0 && (fresh_post as u32) < next_item_size && fragmentation < 0.4 && remaining_frac > 0.15 {
            score += 16.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        // gen 81 mutation, refined (gen 156): tileability-aware open —
        // loosen the fragmentation gate slightly so more exact-multiple
        // lanes can be opened when the stream is long.
        if next_item_size > 1 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 3 && rem == 0 && fragmentation < 0.35 {
                score -= 14.0 * ((reps as f64).min(5.0) - 2.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // NEW (gen 156): fresh-bin residual-harmony open — when the fresh
        // bin's post-residual closely matches the fleet mean residual, the
        // new bin blends into the existing slack distribution instead of
        // adding variance; reward modestly when many bins are open.
        if fresh_post > 0.0 && open_bins_count > 3 && mean_residual > 0.0 {
            let harmony = (fresh_post - mean_residual).abs() / cap;
            if harmony < 0.06 && remaining_frac > 0.2 {
                score -= 12.0 * (1.0 - harmony / 0.06) * (1.0 - progress);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Tight fits are excellent: reward small post residuals nonlinearly.
    let tightness = 1.0 - post / cap;
    score -= 60.0 * tightness * tightness;

    // Penalize leaving a dead gap that cannot fit the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt && post > 0.0 {
            score += 8.0 + 0.35 * post;
        } else if post >= nxt {
            // reward keeping room for the lookahead item
            score -= 6.0 * (1.0 - (nxt / (post + 1.0)));
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a bin when good fits exist,
    // unless open bins are nearly full / fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_fragment = mean_residual / cap;
        score += 18.0 * (1.0 - progress);
        if avg_fragment > item_size as f64 / cap {
            score += 12.0;
        }
        if open_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Prefer filling bins that are already relatively full (best-fit flavor).
    let fill = 1.0 - bin_residual as f64 / cap;
    score -= 10.0 * fill * fill;

    // Mild penalty for spreading across many open bins late in the stream.
    score += 0.4 * open_bins_count as f64 * (step_index as f64 / (total_items.max(1) as f64));

    // Reward exact-ish usage relative to mean residual state.
    score -= 3.0 * ((mean_residual - post).abs() / cap);

    score
}

