    let mut score = post_residual as f64;

    // Normalized stream progress in [0,1]
    let progress = if total_items > 1 {
        step_index as f64 / (total_items as f64 - 1.0)
    } else {
        0.0
    };

    // Smooth non-linear coupling: post_residual weighted by progress polynomial.
    // Early stream: prefer tight fits (penalize residual more); late stream: residual matters less.
    let progress_poly = 0.5 + 0.5 * progress * progress; // smooth ramp 0.5 -> 1.0
    score += 0.35 * progress_poly * (post_residual as f64 / bin_capacity as f64) * (post_residual as f64 / bin_capacity as f64);

    // Reward filling a bin nearly exactly (small post_residual) with a smooth kernel.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness * tightness;

    // Lookahead coupling: if next item fits the post-residual, reward this placement smoothly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 4.0 * (1.0 - slack) * (1.0 + progress);
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize wasted residual smoothly.
        let waste = post_residual as f64 / bin_capacity as f64;
        score += 3.0 * waste * waste;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 8.0 + 4.0 * progress;
    }

    // Mild penalty when many bins are open and this bin is far from mean residual (imbalance).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.05 * dev * (1.0 - progress);

    // New-bin candidate: prefer it only when no open bin gives a good fit.
    if bin_residual == bin_capacity {
        // Opening a new bin keeps full capacity; make it attractive only if this placement
        // would leave a large dead residual in an existing bin.
        let dead = post_residual as f64 / bin_capacity as f64;
        score = 20.0 * dead * dead - 5.0 * (1.0 - dead);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
