            let fill = 1.0 - post_residual as f64 / cap;
            score -= 6.5 * fill * (progress - 0.4);
        }
        // MUTATION (gen 156): residual-variance damper — when this bin's
        // post-residual deviates strongly from the fleet mean residual while
        // the next item cannot use the leftover, penalize the outlier so
        // open residuals stay homogeneous and pairable.
