        if fresh_post > 0.35 * cap && next_item_size > 0 && (fresh_post as u32) < next_item_size && fragmentation < 0.4 && remaining_frac > 0.15 {
            score += 16.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        // gen 81: tileability-aware open.
        if next_item_size > 1 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 3 && rem == 0 && fragmentation < 0.3 {
                score -= 14.0 * ((reps as f64).min(5.0) - 2.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // MUTATION (gen 156): pairable fresh-bin open — when the fresh
        // post-residual matches the fleet mean residual within a tight band,
        // the new bin's leftover is directly pairable with existing slack;
        // deepen the reward slightly to consolidate homogeneous residuals.
        if fresh_post > 0.0 && mean_residual > 0.0 && fragmentation < 0.45 && remaining_frac > 0.1 {
            let dev = (fresh_post - mean_residual).abs() / cap;
            if dev < 0.03 {
                score -= 9.0 * (1.0 - dev / 0.03) * (1.0 - progress);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits (residual 0) strongly rewarded.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Modulo arithmetic on post_residual: residuals that are "harmonically
    // compatible" with common item sizes (multiples of 10, 20, 25) are reusable.
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 { score -= 12.0; }
        if pr % 20 == 0 { score -= 6.0; }
        if pr % 25 == 0 { score -= 5.0; }
        // Odd tiny remainders are dead space; penalize via integer-division class.
        if pr < 10 { score += 15.0; }
    }

    // Lookahead coupling: does the next item fit exactly in post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportionally to tightness of that fit.
            let tight = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score -= 20.0 * tight;
        } else {
            // Next item cannot use this residual: penalize small residuals more.
            score += 8.0 * ((post_residual as f64) / cap);
        }
    }

    // Last-chance bin logic: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Mean-residual coupling: prefer bins whose residual is below the mean
    // (use up the fuller bins first, keep roomy bins flexible).
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    // New-bin candidate: only attractive late in the stream or when the item
    // is large relative to typical residuals; otherwise discourage opening bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let size_pull = item_size as f64 / cap;
        score = 40.0 + 30.0 * size_pull - 20.0 * progress - 2.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 10.0; // pairing potential in a fresh bin
        }
    }

    score
}

