        if fresh_post > 0.0 && mean_residual > 0.0 && open_bins_count > 2 && remaining_frac > 0.1 {
            let align = (fresh_post - mean_residual).abs() / cap;
            if align < 0.06 {
                score -= 18.0 * (1.0 - align / 0.06) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into new space.
    score += 0.6 * open_bins_count as f64;

    // Lookahead: if next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        if gap < 10.0 {
            score -= 30.0;
        } else {
            score -= 10.0 * (1.0 - gap / bin_capacity as f64);
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use the leftover: leftover is likely dead space.
        score += 15.0;
    }

    // Mild preference to keep residuals near the mean (balance bins).
    score += 0.1 * (post_residual as f64 - mean_residual).abs();

    // Early in the stream, be slightly more willing to open bins for good structure.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if it yields a great future structure
        // and existing fits are poor.
        score = 45.0 + 20.0 * progress - 8.0 * open_bins_count as f64;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 25.0; // pairing potential with next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
