        let two_step = item_size + next_item_size;
        if bin_residual != bin_capacity && two_step == bin_residual {
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            score -= (26.0 + 30.0 * scarcity) * (0.4 + 0.6 * (1.0 - progress));
        }
