    // Residual-harmony deepening.
    if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 1 {
        let harmony = (post_residual as f64 - mean_residual).abs() / cap;
        if harmony < 0.06 {
            let scarcity = 1.0 / (fitting_bins_count as f64);
            score -= (7.0 + 5.0 * scarcity) * (1.0 - harmony / 0.06) * (0.5 + 0.5 * (1.0 - progress));
