        if fitting_bins_count <= 2 && fresh_post > 0.0 && fresh_post <= 10.0 && remaining_frac > 0.1 {
            score -= (18.0 + 12.0 * (1.0 - fresh_post / 10.0)) * (0.5 + 0.5 * (1.0 - progress));
