    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: residual close to zero is good.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize dead space that cannot fit the next item (lookahead coupling).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0 + 0.25 * (next_item_size - post_residual) as f64;
    }
    // Reward residual that exactly accommodates the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Global pressure: many open bins with low mean residual -> consolidate.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual);
    score -= 2.0 * pressure;

    // Time horizon: early in stream, prefer filling existing bins; later, allow spreading.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 6.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Penalize leaving residuals that are hard to fill (awkward small gaps).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 30.0 } else {
            (mean_residual - item_size as f64).max(0.0) * 0.3
        };
        score = 60.0 - desperation - 20.0 * progress;
    }

    score
}

