            if dev > 0.12 {
                score += 8.0 * (dev - 0.12) * (progress - 0.3) * (1.0 / fitting_bins_count.max(1) as f64).sqrt();
            }
        }
        // MUTATION (gen 158): exact-fill lookahead — when post_residual is
        // small but nonzero and the next item cannot fit anywhere else
        // (fitting_bins_count == 1), the leftover is stranded; penalize hard
        // so the item goes where the residual dies completely instead.
