            }
        }
        // gen 76: demand-aware fresh-bin refusal.
        if remaining_frac >= 0.05 && fresh_post > 0.3 * cap && next_item_size > 0 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (next_item_size as f64) * 0.42;
            if open_space > 1.15 * est_need {
                score += 30.0 * (1.0 - remaining_frac) * (fresh_post / cap - 0.3);
            }
        }
        // gen 76: fresh-bin dead-space cap.
        if fresh_post > 0.35 * cap && next_item_size > 0 && (fresh_post as u32) < next_item_size && fragmentation < 0.4 && remaining_frac > 0.15 {
            score += 16.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        // gen 81: tileability-aware open.
        if next_item_size > 1 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 3 && rem == 0 && fragmentation < 0.3 {
                score -= 14.0 * ((reps as f64).min(5.0) - 2.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // MUTATION (gen 158): band-matching open — when the fresh bin's
        // post-residual lands close to the current fleet mean residual, the
        // new bin harmonizes with the existing residual band instead of
        // widening variance; reward this modestly when fragmentation is low.
        if fresh_post > 0.0 && mean_residual > 0.0 && open_bins_count > 2 && fragmentation < 0.45 {
            let band = (fresh_post - mean_residual).abs() / cap;
            if band < 0.1 {
                score -= 9.0 * (1.0 - band / 0.1) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth coupling with stream progress: waste tolerance rises mid-stream, tightens near end
    let progress_shape = 0.5 * (1.0 - (std::f64::consts::PI * progress).cos());
    score -= 12.0 * progress_shape * norm_pr;

    // Reward tight fits via smooth polynomial of fill fraction
    let fill = (cap - pr) / cap;
    score -= 20.0 * fill * fill * fill;

    // Penalize residual that cannot fit the lookahead item (smooth gate)
    if next_item_size > 0 {
        let fits_next = if pr >= next_item_size as f64 { 1.0 } else { 0.0 };
        let gap = (pr - next_item_size as f64).abs() / cap;
        score += (1.0 - fits_next) * (6.0 + 30.0 * gap * gap);
        score -= fits_next * 4.0 * (1.0 - gap);
    }

    // Last-chance bonus when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_pr);
    }

    // Mild penalty when many bins are open and residual is large (fragmentation)
    score += 0.05 * open_bins_count as f64 * norm_pr * norm_pr;

    // Deviation from mean residual: prefer bins whose leftover tracks fleet average
    score += 0.1 * (pr - mean_residual).abs();

    // New-bin candidate: penalize opening a fresh bin unless current bin is nearly empty
    if bin_residual == bin_capacity {
        score += 8.0 + 10.0 * progress;
    }

    score
}

