        // item, damp the open reward to avoid redundant lanes.
        if next_item_size > 0 && fresh_post > 0.0 && remaining_frac > 0.05 {
            let open_can_next = mean_residual >= next_item_size as f64;
            if (fresh_post as u32) == next_item_size && !open_can_next {
                score -= 24.0 * (1.0 - progress);
            } else if (fresh_post as u32) < next_item_size && open_can_next {
                score += 10.0 * (1.0 - progress) * (fresh_post / cap);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residuals in "harmonic" classes
    // (multiples of 10, then 25, then 50) are more reusable than odd scraps.
    let post = post_residual as u32;
    let class_bonus: f64 = if post == 0 {
        -40.0 // perfect closure
    } else if post % 50 == 0 {
        -25.0
    } else if post % 25 == 0 {
        -15.0
    } else if post % 10 == 0 {
        -8.0
    } else {
        0.0
    };
    score += class_bonus;

    // Dead-space penalty: leftovers too small for the smallest plausible item (1..100 range)
    if post > 0 && post < 10 {
        score += 30.0 + (10 - post) as f64 * 2.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin; if next item can't fit, mildly penalize.
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 35.0;
        } else if next_item_size <= post {
            // harmonic threshold classes for the future gap
            let future = post - next_item_size;
            if future % 10 == 0 {
                score -= 12.0;
            } else if future % 25 == 0 {
                score -= 18.0;
            }
            score += future as f64 * 0.1;
        } else {
            score += 6.0;
        }
    }

    // Last-chance logic: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: bin_residual == bin_capacity (empty bin).
    if bin_residual == bin_capacity {
        // Prefer reusing open bins unless their residual is poorly harmonized.
        // Penalize new bin slightly; escalate when many bins are open (avoid bin sprawl).
        let sprawl = (open_bins_count as f64).ln().max(0.0);
        score += 25.0 + sprawl * 8.0;
        // But if the item is large relative to mean residual, a fresh bin may be wise.
        if item_size as f64 > mean_residual {
            score -= 15.0;
        }
    }

    // Progress-aware tightness reward: early in the stream, keep bins flexible;
    // later, prioritize closing bins tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * (bin_capacity - post_residual as u32) as f64 * 0.15;

    // Mild attraction to bins whose residual is near the item (tight fit)
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.05;

    // Deviation from mean residual: prefer bins that reduce residual variance
    score += (post_residual as f64 - mean_residual).abs() * 0.03;

    score
}

