            score += 10.5 * (dead_ratio - 0.5) * (1.0 - progress);
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
            && mean_residual > 0.0 && (mean_residual as u32) >= next_item_size {
            score += 12.0;
        }
        if post_residual > 12 && post_residual < 40 && next_item_size > post_residual {
            let orphan = (post_residual as f64 - 12.0) / 28.0;
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            score += 17.0 * orphan * scarcity * (0.5 + 0.5 * (1.0 - progress));
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let chain = post_residual % next_item_size.max(1);
            if chain == 0 {
                score -= 26.0 * (1.0 - progress);
            } else if chain <= 3 {
                score -= 11.0 * (1.0 - progress);
            }
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            let stranded = (next_item_size - post_residual) as f64;
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            if stranded <= 10.0 {
                score += (8.5 + 1.1 * (10.0 - stranded)) * scarcity * (0.4 + 0.6 * (1.0 - progress));
            } else {
                let proximity = 1.0 - (stranded - 10.0).min(cap) / cap;
                score += 3.2 * proximity * scarcity * (1.0 - progress);
            }
        }
        if dead_ratio > 0.35 && fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score += 7.5 * (dead_ratio - 0.35) * tightness * (1.0 - progress);
        }
        if post_residual > 0 && mean_residual > 0.0 {
            let gap = mean_residual - post_residual as f64;
            if gap > 0.0 && gap < 0.15 * cap && fitting_bins_count > 2 {
                score += 4.8 * (gap / (0.15 * cap)) * (1.0 - progress);
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size.max(1) && fitting_bins_count > 2 {
            score -= 6.5 * (1.0 - progress);
        }
        if post_residual == 0 && bin_residual < bin_capacity {
            score -= 42.0 * (1.0 - bin_residual as f64 / cap) * (1.0 - progress);
        }
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 1 {
            let harmony = (post_residual as f64 - mean_residual).abs() / cap;
            if harmony < 0.08 {
                score -= 9.0 * (1.0 - harmony / 0.08) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        if post_residual > 6 && post_residual <= 30 && next_item_size > 0 && next_item_size <= post_residual {
            let reps = post_residual / next_item_size.max(1);
            if reps >= 2 {
                score -= 3.5 * (reps as f64).min(4.0) * (1.0 - progress);
            }
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let after_next = post_residual - next_item_size;
            if after_next > 0 && after_next <= 12 {
                let tail = after_next as f64;
                score -= (14.0 - 0.9 * tail) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        if post_residual > 0 && post_residual < 6 && next_item_size > post_residual {
            score += 6.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let after_next = (post_residual - next_item_size) as f64;
            if after_next > 8.0 && after_next <= 16.0 && progress < 0.85 {
                let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
                score -= (4.0 + 3.0 * scarcity) * (1.0 - (after_next - 8.0) / 8.0) * (1.0 - progress);
            }
        }
        if post_residual > 0 && next_item_size > 0 && fitting_bins_count > 3 {
            let overshoot = post_residual.saturating_sub(next_item_size) as f64;
            if overshoot > 16.0 {
                score += 1.6 * ((overshoot - 16.0) / cap).min(0.25) * (1.0 - progress);
            }
        }
        if fitting_bins_count > 1 && dead_ratio > 0.08 && post_residual > 0 {
            let scarcity = 1.0 / (fitting_bins_count as f64);
            let comp_slack = (mean_residual / cap).min(1.0);
            score += 6.5 * (dead_ratio - 0.08) * scarcity * comp_slack * (0.5 + 0.5 * (1.0 - progress));
            score += 2.2 * (dead / cap) * scarcity * comp_slack * (1.0 - progress);
        }
        if fitting_bins_count > 2 && post_residual > 0 && mean_residual > 0.0 {
            let dev = ((post_residual as f64 - mean_residual).abs() / cap).min(0.4);
            score += 5.0 * dev * (1.0 - progress);
        }
        if post_residual > 0 && post_residual % 10 == 0 && post_residual <= 60 && next_item_size > 0 && next_item_size <= post_residual {
            score -= 4.0 * (1.0 - progress) * (1.0 - post_residual as f64 / 120.0);
        }
        if next_item_size > 0 && post_residual == next_item_size && fitting_bins_count <= 3 {
            score -= 30.0 / fitting_bins_count.max(1) as f64 * (0.5 + 0.5 * (1.0 - progress));
        }
        if post_residual > 0 && next_item_size > 0 && fitting_bins_count > 1 {
            let usable = next_item_size <= post_residual
                || (mean_residual as u32) >= next_item_size;
            if !usable {
                let waste_frac = post_residual as f64 / cap;
                let late = 0.35 + 0.65 * progress;
                score += 9.0 * waste_frac * late;
            }
        }
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 2 {
            let rel = post_residual as f64 / (mean_residual + 1.0);
            if rel < 0.5 {
                score -= 6.0 * (1.0 - rel / 0.5) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        if post_residual > 0 && next_item_size > 1 && next_item_size <= post_residual {
            let reps = post_residual / next_item_size;
            let rem = post_residual % next_item_size;
            if reps >= 1 && rem == 0 {
                let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
                score -= (5.0 + 6.0 * scarcity) * ((reps as f64).min(3.0)) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 1 && progress > 0.25 {
            let target = 0.5 * (mean_residual + 0.5 * cap);
            let dev = ((post_residual as f64 - target).abs() / cap).min(0.5);
            score += 2.4 * dev * (progress - 0.25);
        }
        // gen 76: near-full chain extension.
        if post_residual > 0 && next_item_size > 0 && post_residual > next_item_size {
            let after_next = post_residual - next_item_size;
            if after_next > 0 && after_next < 6 && progress > 0.35 {
                score -= 11.0 * (1.0 - after_next as f64 / 6.0) * (progress - 0.35);
            }
        }
        // gen 76: usable-residual scarcity bonus.
        if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count == 1 && bin_residual != bin_capacity {
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score -= 14.0 * (1.0 - progress) * (0.6 + 0.4 * tightness);
        }
        // gen 81: dead-space compaction gradient.
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
            && fitting_bins_count > 1 {
            let open_space = mean_residual * open_bins_count as f64;
            if open_space > 1.6 * cap {
                let frac = post_residual as f64 / next_item_size as f64;
                score += 12.0 * (1.0 - frac) * (0.35 + 0.65 * progress);
            }
        }
        // gen 81: consolidation pull.
        if post_residual > 0 && fitting_bins_count > 2 && progress > 0.4 {
            let fill = 1.0 - post_residual as f64 / cap;
            score -= 5.5 * fill * (progress - 0.4);
        }
        // gen 138: residual homogenization.
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 3 {
            let dev = (post_residual as f64 - mean_residual).abs() / cap;
            if dev < 0.06 {
                score -= 7.0 * (1.0 - dev / 0.06) * progress;
            } else if dev > 0.3 {
                score += 3.0 * ((dev - 0.3) / 0.4).min(1.0) * progress;
            }
        }
        // gen 138: near-exact residual chase.
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
            && next_item_size - post_residual <= 3 && progress > 0.3 {
            score -= 5.0 * (1.0 - progress) * (1.0 - (next_item_size - post_residual) as f64 / 3.0);
        }
        // gen 142: two-step tiling lookahead.
        if post_residual > 0 && next_item_size > 1 && post_residual >= next_item_size {
            let after_next = post_residual - next_item_size;
            if after_next >= next_item_size {
                let tiles = (after_next / next_item_size) as f64;
                let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
                score -= (6.0 + 5.0 * scarcity) * tiles.min(3.0) * (0.5 + 0.5 * (1.0 - progress));
            } else if after_next > 0 && after_next <= 2 {
                score -= 8.0 * (1.0 - after_next as f64 / 2.0) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        // gen 142: mean-residual absorption gradient.
        if post_residual > 0 && next_item_size > 0 && mean_residual > 0.0
            && (mean_residual as u32) < next_item_size && fitting_bins_count > 1 {
            if post_residual >= next_item_size {
                score -= 7.5 * (1.0 - progress);
            } else if next_item_size - post_residual <= 5 {
                score += 5.0 * (1.0 - (next_item_size - post_residual) as f64 / 5.0) * (0.3 + 0.7 * progress);
            }
        }
        // gen 147: dead-space budget coupling.
        if post_residual > 0 && fitting_bins_count > 1 {
            let open_space = mean_residual * open_bins_count as f64;
            let slack_tight = (2.5 * cap - open_space).max(0.0) / (2.5 * cap);
            if dead_ratio > 0.45 {
                score += 14.0 * (dead_ratio - 0.45) * slack_tight * (0.4 + 0.6 * progress);
            } else if dead_ratio < 0.2 && slack_tight > 0.5 {
                score -= 4.5 * (0.2 - dead_ratio) * slack_tight * (1.0 - progress);
            }
        }
        // gen 147: residual-parity pairing.
        if post_residual > 0 && next_item_size > 0 && mean_residual > 0.0 && fitting_bins_count > 2 {
            let projected = post_residual as f64;
            let dev = (projected - mean_residual).abs();
            if dev <= 6.0 {
                score -= 5.0 * (1.0 - dev / 6.0) * (0.3 + 0.7 * progress);
            }
        }
        // MUTATION (gen 158): dead-space absorption gate — combine fine-grained
        // post-residual fitting with the fleet's aggregate slack. When this
        // placement strands a residual that no plausible upcoming item can
        // use (post_residual well below next_item_size) AND the fleet-wide
        // slack is already tight, the stranded lane is a real loss; penalize
        // proportionally so compaction prefers bins that keep residuals
        // usable. Conversely, reward placements whose post-residual lands in
        // the small-hole band (<= next_item_size + 2) when slack is tight,
        // since those holes are immediately absorbable next step.
        if post_residual > 0 && next_item_size > 0 && fitting_bins_count > 1 {
            let open_space = mean_residual * open_bins_count as f64;
            let slack_tight = ((2.0 * cap - open_space).max(0.0)) / (2.0 * cap);
            let hole = post_residual as f64 / next_item_size as f64;
            if hole < 0.85 && slack_tight > 0.4 {
                score += 9.0 * (0.85 - hole) * slack_tight * (0.35 + 0.65 * progress);
            } else if post_residual >= next_item_size && (post_residual - next_item_size) as f64 <= 2.0 {
                score -= 6.5 * slack_tight * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        // MUTATION (gen 158): near-exact residual chase extension — widen the
        // near-exact window to <= 6 and let scarcity of fitting bins amplify
        // the pull toward the bin that the next item almost fills exactly.
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            let miss = (next_item_size - post_residual) as f64;
            if miss <= 6.0 {
                let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
                score -= (4.0 + 3.0 * scarcity) * (1.0 - miss / 6.0) * (0.45 + 0.55 * (1.0 - progress));
            }
        }
    } else {
        let fragmentation = (mean_residual / cap) * open_bins_count as f64;
        let huge_item = item_size as f64 > 0.7 * cap;
        let remaining = if total_items > step_index { total_items - step_index } else { 1 };
        let remaining_frac = remaining as f64 / total_items.max(1) as f64;
        let fresh_post = cap - item_size as f64;
        let fresh_is_exact = fresh_post <= 4.0 && fresh_post >= 0.0;

        if fragmentation > 0.55 || (huge_item && open_bins_count > 4) {
            score -= 66.0 + 46.0 * remaining_frac;
        } else if fresh_is_exact {
            score -= 134.0 + 66.0 * remaining_frac;
        } else {
            score += 400.0 - 82.0 * remaining_frac;
            if fitting_bins_count <= 3 && open_bins_count > 2 {
                score -= 30.0 + 18.0 * remaining_frac;
            }
        }

        let fresh_match = (fresh_post - mean_residual).abs() / cap;
        if fresh_match < 0.05 {
            score -= 76.0 * (1.0 - fresh_match / 0.05);
        }
        if remaining_frac < 0.05 && fresh_post > 0.0 && !fresh_is_exact {
            score += 160.0 * (fresh_post / cap);
        }
        if fresh_post > 0.0 && fresh_post <= 22.0 && !fresh_is_exact {
            score -= 26.0 * (1.0 - fresh_post / 22.0);
        }
        if fresh_post > 22.0 && fresh_post <= 40.0 && fragmentation < 0.35 {
            score -= 12.5 * (1.0 - (fresh_post - 22.0) / 18.0);
        }
        if fresh_post > 0.0 && fresh_match < 0.12 && fragmentation < 0.55 {
            score -= 30.0 * (1.0 - fresh_match / 0.12);
        }
        if next_item_size > 0 && fresh_post > 0.0 {
            let fresh_exact_next = (fresh_post as u32) == next_item_size;
            let open_can_next = mean_residual >= next_item_size as f64;
            if fresh_exact_next && !open_can_next && fitting_bins_count <= 2 {
                score -= 52.0 * (1.0 - progress);
            }
            if (fresh_post as u32) < next_item_size && mean_residual > next_item_size as f64 {
                score += 21.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && fresh_post > next_item_size as f64 {
            let chain_post = fresh_post - next_item_size as f64;
            if chain_post <= 4.0 {
                score -= 34.0 * (1.0 - chain_post / 4.0) * (0.5 + 0.5 * (1.0 - progress));
            } else if chain_post <= 10.0 {
                score -= 9.5 * (1.0 - (chain_post - 4.0) / 6.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        if remaining_frac < 0.12 && fresh_post > 0.0 && !fresh_is_exact && mean_residual * open_bins_count as f64 > 3.0 * cap {
            score += 42.0 * (1.0 - remaining_frac / 0.12);
        }
        if fitting_bins_count == 1 && fresh_post > 0.0 && next_item_size > 0 {
            let stranded_here = bin_capacity.saturating_sub(item_size);
            let would_strand = stranded_here < next_item_size;
            if would_strand && stranded_here > 0 && stranded_here <= 8 {
                score -= 32.0 * (1.0 - progress);
            }
        }
        let open_capacity = mean_residual * open_bins_count as f64;
        let per_item_need = cap * 0.5;
        if remaining_frac > 0.25 && open_capacity < per_item_need * open_bins_count.max(1) as f64 * 0.5 {
            score -= 18.0 * (1.0 - progress);
        }
        if next_item_size > 0 && fresh_post > next_item_size as f64 {
            let after_next = fresh_post - next_item_size as f64;
            if after_next > 0.0 && after_next <= 8.0 && fragmentation < 0.5 {
                score -= 20.0 * (1.0 - after_next / 8.0) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        if next_item_size > 0 && fresh_post > 0.0 && (fresh_post as u32) < next_item_size {
            let slack_total = mean_residual * open_bins_count as f64;
            if slack_total > 2.0 * cap {
                score += 26.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && (fresh_post as u32) == next_item_size && fragmentation > 0.3 {
            score -= 44.0 * (0.5 + 0.5 * (1.0 - progress));
        }
        if fresh_post > 0.5 * cap && mean_residual < 0.2 * cap && remaining_frac > 0.3 && open_bins_count > 3 {
            score += 24.0 * (fresh_post / cap - 0.5) * 2.0 * (1.0 - progress);
        }
        if fitting_bins_count <= 1 && fresh_post > 0.45 * cap && next_item_size > 0 {
            let reachable = (next_item_size as f64 / fresh_post).min(1.0);
            if reachable < 0.5 {
                score += 18.0 * (0.5 - reachable) * (1.0 - progress);
            }
        }
        if next_item_size > 0 && fresh_post > 0.0 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 2 && fragmentation < 0.5 {
                score -= 7.0 * ((reps as f64).min(4.0) - 1.0) * (0.4 + 0.6 * (1.0 - progress));
                if rem <= 3 {
                    score -= 5.0 * (1.0 - progress);
                }
            }
        }
        if fresh_post > 0.35 * cap && remaining_frac > 0.2 && mean_residual * open_bins_count as f64 > 4.0 * cap && fragmentation < 0.45 {
            score += 20.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        if remaining_frac < 0.15 && fresh_post > 0.3 * cap {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.35;
            if open_space > est_need {
                score += 55.0 * (1.0 - remaining_frac / 0.15);
            }
        }
        if remaining_frac >= 0.15 && remaining_frac < 0.45 && fresh_post > 0.4 * cap && fragmentation > 0.4 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.45;
            if open_space > est_need {
                score += 28.0 * (1.0 - remaining_frac / 0.45);
            }
        }
        if next_item_size > 1 && fresh_post > 0.0 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 2 && rem == 0 && fragmentation < 0.4 {
                score -= 10.0 * ((reps as f64).min(4.0) - 1.0) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        if remaining_frac >= 0.45 && remaining_frac < 0.5 && fresh_post > 0.45 * cap && fragmentation > 0.5 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.55;
            if open_space > est_need {
                score += 22.0 * (1.0 - remaining_frac / 0.5);
            }
        }
        // gen 76: demand-aware fresh-bin refusal.
        if remaining_frac >= 0.05 && fresh_post > 0.3 * cap && next_item_size > 0 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (next_item_size as f64) * 0.42;
            if open_space > 1.15 * est_need {
                score += 30.0 * (1.0 - remaining_frac) * (fresh_post / cap - 0.3);
            }
        }
        // gen 76: fresh-bin dead-space cap.
        if fresh_post > 0.35 * cap && next_item_size > 0 && (fresh_post as u32) < next_item_size && fragmentation < 0.4 && remaining_frac > 0.15 {
            score += 16.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        // gen 81: tileability-aware open.
        if next_item_size > 1 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 3 && rem == 0 && fragmentation < 0.3 {
                score -= 14.0 * ((reps as f64).min(5.0) - 2.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // gen 138: lane-diversity open.
        if next_item_size > 0 && fresh_post > 0.0 && fragmentation > 0.45 && remaining_frac > 0.2 {
            let dup = ((fresh_post - mean_residual).abs() / cap) < 0.08;
            if !dup && (fresh_post as u32) >= next_item_size {
                score -= 9.0 * (1.0 - progress) * (0.4 + 0.6 * (fragmentation - 0.45) / 0.55);
            }
        }
        // gen 142: tileable-lane open preference.
        if next_item_size > 1 && remaining_frac > 0.1 && fragmentation < 0.5 {
            let open_can_tile = mean_residual >= next_item_size as f64
                && (mean_residual as u32) % next_item_size == 0;
            if (fresh_post as u32) % next_item_size == 0 && (fresh_post as u32) >= 2 * next_item_size && !open_can_tile {
                score -= 12.0 * (1.0 - progress) * (0.5 + 0.5 * (1.0 - fragmentation));
            }
        }
        // gen 147: slack-aware fresh-bin gate.
        if remaining_frac > 0.08 && fresh_post > 0.0 && next_item_size > 0 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (next_item_size as f64) * 0.5;
            if open_space > 1.3 * est_need && (fresh_post as u32) > next_item_size {
                let surplus = ((open_space - est_need) / (4.0 * cap)).min(1.0);
                score += 18.0 * surplus * (fresh_post / cap) * (1.0 - remaining_frac / 0.08).abs().min(1.0);
            }
        }
        // MUTATION (gen 158): dead-space-aware fresh open — when aggregate
        // slack is tight (open_space below remaining demand), opening a bin
        // whose post-residual is small (high fill) is exactly what compaction
        // needs; deepen the existing exact-fill reward with a slack-tight
        // gradient so fresh opens are judged by how little dead space they
        // create relative to the fleet's remaining need.
        if remaining_frac > 0.1 && fresh_post > 0.0 && next_item_size > 0 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (next_item_size as f64) * 0.45;
            if open_space < est_need && fresh_post < 0.25 * cap {
                let tight = 1.0 - open_space / est_need.max(1.0);
                score -= 22.0 * tight * (1.0 - fresh_post / (0.25 * cap)) * (0.5 + 0.5 * progress);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead = if post_residual > 0 && post_residual < 10 { 1.0 } else { 0.0 };
    score += dead * 60.0;

    // Nonlinear penalty on medium dead zones (hard to fill later).
    if post_residual > 0 && post_residual < 25 {
        score += (25.0 - post_residual as f64) * 1.5;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits relative to residual.
    score -= (item_size as f64 / bin_residual.max(1) as f64) * 15.0;

    // Open bins pressure: when many bins are open, prefer filling existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.6 + 0.4 * progress);

    // Mean residual coupling: prefer bins below mean residual (tighter bins first).
    score += (mean_residual - post_residual as f64).max(0.0) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item cannot use the leftover, penalize leaving awkward residue.
    if next_item_size > post_residual && post_residual > 0 {
        score += 8.0;
    }

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        score += 20.0 + open_bins_count as f64 * -1.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Layered dead-space rewards (lower post_residual = better).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 4 {
        score -= 265.0 + 4.4 * (4 - post_residual) as f64;
    } else if post_residual <= 10 {
        score -= 72.0 + 3.9 * (10 - post_residual) as f64;
    } else if post_residual <= 22 {
        score -= 14.0 + 1.6 * (22 - post_residual) as f64;
    } else if post_residual <= 32 {
        score -= 5.0 + 0.75 * (32 - post_residual) as f64;
    } else if post_residual <= 48 {
        score -= 1.2 + 0.24 * (48 - post_residual) as f64;
    } else {
        score -= 1.2 - 0.015 * (post_residual as f64 - 48.0);
    }

    // Progress-scaled weighting.
    let w = 0.33 + 0.67 * progress * progress;
    score *= w;

    // Lookahead coupling with the next item.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 920.0;
        } else if next_item_size < post_residual {
            let two_step_waste = (post_residual - next_item_size) as f64;
            if two_step_waste <= 8.0 {
                score -= 140.0 - 2.3 * two_step_waste;
            } else {
                score -= 74.0 - 0.6 * two_step_waste;
            }
            if two_step_waste <= 3.0 {
                score -= 50.0;
            }
        } else {
            let miss = (next_item_size - post_residual) as f64;
            score += 0.95 * miss;
            if miss > 26.0 {
                score += 0.55 * (miss - 26.0);
            }
        }
        let two_step = item_size + next_item_size;
        if two_step == bin_capacity {
            score -= 800.0;
        } else if two_step <= bin_capacity && bin_capacity - two_step <= 10 {
            score -= 200.0;
        }
    }

    // Slack-based scarcity boost when the next item fits here.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
        let boost = 38.0 + 28.0 * scarcity;
        score -= boost * (1.0 - slack / cap) * (0.6 + 0.4 * (1.0 - progress));
        if fitting_bins_count <= 2 {
            score -= 16.0 * (1.0 - slack / cap);
        }
        if slack == 0.0 {
            score -= 22.0 * (1.0 - progress);
        }
    }

    // Mean-residual harmony.
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Tiling/divisibility consolidation.
    if post_residual > 0 && next_item_size > 1 && next_item_size <= post_residual {
        let reps = post_residual / next_item_size;
        let rem = post_residual % next_item_size;
        if reps >= 1 && rem == 0 {
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            score -= (5.5 + 6.5 * scarcity) * (reps as f64).min(3.0) * (0.4 + 0.6 * (1.0 - progress));
        }
    }

    // Fill-level momentum.
    if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 2 {
        let rel = post_residual as f64 / (mean_residual + 1.0);
        if rel < 0.5 {
            score -= 6.5 * (1.0 - rel / 0.5) * (0.4 + 0.6 * (1.0 - progress));
        }
    }

    // Dead-ratio gradient scaled by aggregate open slack.
    if bin_residual != bin_capacity && fitting_bins_count > 1 && post_residual > 0 {
        let dead = (bin_residual - item_size) as f64;
        let dead_ratio = dead / cap;
        let scarcity = 1.0 / (fitting_bins_count as f64);
        let comp_slack = (mean_residual / cap).min(1.0);
        if dead_ratio > 0.08 {
            score += 6.5 * (dead_ratio - 0.08) * scarcity * comp_slack * (0.5 + 0.5 * (1.0 - progress));
            score += 2.2 * (dead / cap) * scarcity * comp_slack * (1.0 - progress);
        }
        if dead_ratio > 0.5 {
            score += 10.5 * (dead_ratio - 0.5) * (1.0 - progress);
        }
        if next_item_size > 0 {
            let usable = next_item_size <= post_residual || (mean_residual as u32) >= next_item_size;
            if !usable {
                score += 9.5 * (post_residual as f64 / cap) * (0.35 + 0.65 * progress);
            }
        }
    }

    // Last chance bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 160.0;
    }

    // Unique-fit lookahead bonus.
    if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count == 1 && bin_residual != bin_capacity {
        let tightness = 1.0 - (post_residual - next_item_size) as f64 / cap;
        score -= 15.0 * (1.0 - progress) * (0.6 + 0.4 * tightness);
    }

    // Penalize creating small unusable dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 120.0;
    }

    score -= (1.0 - progress) * 20.0;
    score += 0.1 * open_bins_count as f64 * (post_residual as f64 / cap);

    // Near-full chain extension.
    if post_residual > 0 && next_item_size > 0 && post_residual > next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next > 0 && after_next < 6 && progress > 0.35 {
            score -= 11.0 * (1.0 - after_next as f64 / 6.0) * (progress - 0.35);
        }
        if after_next > 0 && after_next <= 12 {
            let tail = after_next as f64;
            score -= (14.0 - 0.9 * tail) * (0.5 + 0.5 * (1.0 - progress));
        }
        if after_next > 8 && after_next <= 16 && progress < 0.85 {
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            score -= (4.0 + 3.0 * scarcity) * (1.0 - (after_next as f64 - 8.0) / 8.0) * (1.0 - progress);
        }
        if after_next > 0 && next_item_size > 1 && after_next % next_item_size == 0 && after_next >= next_item_size {
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            score -= (8.0 + 4.0 * scarcity.sqrt()) * (0.4 + 0.6 * (1.0 - progress));
        }
    }

    // Consolidation pull.
    if post_residual > 0 && fitting_bins_count > 2 && progress > 0.5 {
        let fill = 1.0 - post_residual as f64 / cap;
        score -= 5.0 * fill * (progress - 0.5);
    }

    // Orphaned mid-range residual penalty.
    if post_residual > 12 && post_residual < 40 && next_item_size > post_residual {
        let orphan = (post_residual as f64 - 12.0) / 28.0;
        let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
        score += 17.0 * orphan * scarcity * (0.5 + 0.5 * (1.0 - progress));
    }

    // Stranded-slack gradient.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0
        && post_residual < next_item_size && fitting_bins_count > 1 {
        let stranded = (next_item_size - post_residual) as f64;
        let open_space = mean_residual * open_bins_count as f64;
        if open_space > cap {
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            score += (6.0 + 0.8 * stranded.min(30.0)) * scarcity * (0.4 + 0.6 * progress);
        }
    }

    // Residual-harmony deepening.
    if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 1 {
        let harmony = (post_residual as f64 - mean_residual).abs() / cap;
        if harmony < 0.06 {
            let scarcity = 1.0 / (fitting_bins_count as f64);
            score -= (7.0 + 5.0 * scarcity) * (1.0 - harmony / 0.06) * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    // Dead-space variance squeeze.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0 && fitting_bins_count > 1 {
        let excess = post_residual as f64 - next_item_size as f64;
        if excess > 14.0 && post_residual as f64 > mean_residual {
            let over = ((excess - 14.0) / cap).min(0.3);
            score += 5.5 * over * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    // Perfect-closure bonus.
    if next_item_size > 0 && post_residual == next_item_size && bin_residual != bin_capacity {
        let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
        score -= 34.0 * scarcity * (0.5 + 0.5 * (1.0 - progress));
    }

    // Near-miss gradient sharpened with scarcity.
    if next_item_size > 0 && post_residual > next_item_size {
        let waste = (post_residual - next_item_size) as f64;
        if waste <= 2.0 {
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            score -= (20.0 + 10.0 * scarcity) * (1.0 - waste / 2.0) * (1.0 - progress);
        }
    }

    // Chain divisibility bonus.
    if bin_residual != bin_capacity && next_item_size > 1 && post_residual > next_item_size {
        let chain = post_residual % next_item_size;
        if chain == 0 {
            score -= 8.0 * (1.0 - progress);
        } else if chain <= 3 {
            score -= 3.5 * (1.0 - progress);
        }
    }

    // Overshoot squeeze.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0 && fitting_bins_count > 3 {
        let overshoot = post_residual.saturating_sub(next_item_size) as f64;
        if overshoot > 16.0 {
            score += 1.8 * ((overshoot - 16.0) / cap).min(0.25) * (1.0 - progress);
        }
    }

    // Exact-closure scarcity lane.
    if next_item_size > 0 && post_residual == next_item_size && bin_residual != bin_capacity && fitting_bins_count <= 3 {
        score -= 12.0 / fitting_bins_count.max(1) as f64 * (0.5 + 0.5 * (1.0 - progress));
    }

    // MUTATION (gen 158): dead-space compaction gradient — when this placement
    // strands a residual well below the next item size while aggregate open
    // slack is abundant, the leftover is pure waste; penalize proportionally
    // to shrink residual variance and consolidate slack into fewer bins.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0
        && post_residual < next_item_size && fitting_bins_count > 1 {
        let open_space = mean_residual * open_bins_count as f64;
        if open_space > 2.0 * cap {
            let frac = post_residual as f64 / next_item_size as f64;
            score += 10.0 * (1.0 - frac) * (0.5 + 0.5 * progress);
        }
    }

    // MUTATION (gen 158): tight-reuse lookahead lane — when the post-residual
    // can host the next item with almost no slack and more than two bins
    // compete, reward the near-perfect two-step closure so residual spread
    // collapses into full bins.
    if next_item_size > 0 && post_residual >= next_item_size
        && post_residual < 2 * next_item_size.max(1) && fitting_bins_count > 2 {
        score -= 6.5 * (1.0 - progress);
    }

    // MUTATION (gen 158): residual-divergence penalty — late in the stream,
    // placements that deviate from the target fill level (midway between the
    // mean residual and half capacity) scatter slack; pull them back toward
    // the consolidation target.
    if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 1 && progress > 0.25 {
        let target = 0.5 * (mean_residual + 0.5 * cap);
        let dev = ((post_residual as f64 - target).abs() / cap).min(0.5);
        score += 2.4 * dev * (progress - 0.25);
    }

    // MUTATION (gen 158): dead-space deviation squeeze — with three or more
    // competing bins, reward keeping the post-residual close to the mean
    // residual so aggregate slack stays uniform and reusable.
    if bin_residual != bin_capacity && fitting_bins_count > 2 && post_residual > 0 && mean_residual > 0.0 {
        let dev = ((post_residual as f64 - mean_residual).abs() / cap).min(0.4);
        score += 5.0 * dev * (1.0 - progress);
    }

    if bin_residual == bin_capacity {
        // NEW-BIN CANDIDATE branch.
        let fragmentation = (mean_residual / cap) * open_bins_count as f64;
        let huge_item = item_size as f64 > 0.7 * cap;
        let remaining = if total_items > step_index { total_items - step_index } else { 1 };
        let remaining_frac = remaining as f64 / total_items.max(1) as f64;
        let fresh_post = cap - item_size as f64;
        let fresh_is_exact = fresh_post <= 4.0 && fresh_post >= 0.0;

        if fragmentation > 0.55 || (huge_item && open_bins_count > 4) {
            score -= 66.0 + 46.0 * remaining_frac;
        } else if fresh_is_exact {
            score -= 134.0 + 66.0 * remaining_frac;
        } else {
            score += 400.0 - 82.0 * remaining_frac;
            if fitting_bins_count <= 3 && open_bins_count > 2 {
                score -= 30.0 + 18.0 * remaining_frac;
            }
        }

        let fresh_match = (fresh_post - mean_residual).abs() / cap;
        if fresh_match < 0.05 {
            score -= 76.0 * (1.0 - fresh_match / 0.05);
        }
        if remaining_frac < 0.05 && fresh_post > 0.0 && !fresh_is_exact {
            score += 160.0 * (fresh_post / cap);
        }
        if fresh_post > 0.0 && fresh_post <= 22.0 && !fresh_is_exact {
            score -= 26.0 * (1.0 - fresh_post / 22.0);
        }
        if fresh_post > 22.0 && fresh_post <= 40.0 && fragmentation < 0.35 {
            score -= 12.5 * (1.0 - (fresh_post - 22.0) / 18.0);
        }
        if fresh_post > 0.0 && fresh_match < 0.12 && fragmentation < 0.55 {
            score -= 30.0 * (1.0 - fresh_match / 0.12);
        }
        if next_item_size > 0 && fresh_post > 0.0 {
            let fresh_exact_next = (fresh_post as u32) == next_item_size;
            let open_can_next = mean_residual >= next_item_size as f64;
            if fresh_exact_next && !open_can_next && fitting_bins_count <= 2 {
                score -= 52.0 * (1.0 - progress);
            }
            if (fresh_post as u32) < next_item_size && mean_residual > next_item_size as f64 {
                score += 21.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && fresh_post > next_item_size as f64 {
            let chain_post = fresh_post - next_item_size as f64;
            if chain_post <= 4.0 {
                score -= 34.0 * (1.0 - chain_post / 4.0) * (0.5 + 0.5 * (1.0 - progress));
            } else if chain_post <= 10.0 {
                score -= 9.5 * (1.0 - (chain_post - 4.0) / 6.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        if remaining_frac < 0.12 && fresh_post > 0.0 && !fresh_is_exact && mean_residual * open_bins_count as f64 > 3.0 * cap {
            score += 42.0 * (1.0 - remaining_frac / 0.12);
        }
        // Refuse fresh bins late when open slack covers projected demand.
        if remaining_frac < 0.15 && fresh_post > 0.3 * cap {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.35;
            if open_space > est_need {
                score += 55.0 * (1.0 - remaining_frac / 0.15);
            }
        }
        // Mid-stream refusal band.
        if remaining_frac >= 0.15 && remaining_frac < 0.45 && fresh_post > 0.4 * cap && fragmentation > 0.4 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.45;
            if open_space > est_need {
                score += 28.0 * (1.0 - remaining_frac / 0.45);
            }
        }
        // Demand-aware fresh-bin refusal.
        if remaining_frac >= 0.05 && fresh_post > 0.3 * cap && next_item_size > 0 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (next_item_size as f64) * 0.42;
            if open_space > 1.15 * est_need {
                score += 32.0 * (1.0 - remaining_frac) * (fresh_post / cap - 0.3);
            }
        }
        // Fresh-bin dead-space cap.
        if fresh_post > 0.35 * cap && next_item_size > 0 && (fresh_post as u32) < next_item_size && fragmentation < 0.4 && remaining_frac > 0.15 {
            score += 17.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        // Tiling-aware fresh-bin bonus.
        if next_item_size > 1 && fresh_post > 0.0 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 2 && rem == 0 && fragmentation < 0.4 {
                score -= 10.0 * ((reps as f64).min(4.0) - 1.0) * (0.4 + 0.6 * (1.0 - progress));
            }
            if reps >= 3 && rem == 0 && fragmentation < 0.3 {
                score -= 14.0 * ((reps as f64).min(5.0) - 2.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // Fresh-bin residual-magnitude guard.
        if fresh_post > 0.35 * cap && remaining_frac > 0.2 && mean_residual * open_bins_count as f64 > 4.0 * cap && fragmentation < 0.45 {
            score += 20.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        // Single-fit fresh-bin rescue.
        if fitting_bins_count <= 1 && fresh_post > 0.0 && next_item_size > 0 {
            let stranded_here = bin_capacity.saturating_sub(item_size);
            let would_strand = stranded_here < next_item_size;
            if would_strand && stranded_here > 0 && stranded_here <= 8 {
                score -= 32.0 * (1.0 - progress);
            }
        }
        // Residual-harmony fresh-bin bonus.
        if fresh_post > 0.0 && fresh_match < 0.2 && fragmentation < 0.5 && remaining_frac > 0.1 {
            score -= 14.0 * (1.0 - fresh_match / 0.2) * (0.5 + 0.5 * (1.0 - progress));
        }
        // Demand-cushion fresh-bin gate.
        if remaining_frac > 0.1 && fresh_post > 0.45 * cap && next_item_size > 0 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (next_item_size as f64) * 0.5;
            if open_space > 1.3 * est_need {
                score += 24.0 * (1.0 - remaining_frac) * (fresh_post / cap - 0.45);
            }
        }
        // Tileable-lane fresh bonus.
        if next_item_size > 1 && fresh_post > 0.0 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            let open_space = mean_residual * open_bins_count as f64;
            if reps >= 2 && rem == 0 && open_space < 1.5 * cap {
                score -= 16.0 * ((reps as f64).min(4.0) - 1.0) * (1.0 - progress);
            }
        }
        // Fresh-bin exact-closure lane.
        if next_item_size > 0 && fresh_post > 0.0 && (fresh_post as u32) == next_item_size {
            score -= 40.0 * (0.5 + 0.5 * (1.0 - progress));
        }
        // Oversized-fresh refusal.
        if fresh_post > 0.55 * cap && next_item_size > 0 && (fresh_post as u32) < next_item_size
            && mean_residual * open_bins_count as f64 > 2.0 * cap {
            score += 30.0 * (fresh_post / cap - 0.55) * (0.5 + 0.5 * (1.0 - progress));
        }
        // Fresh-bin chain-exact lane.
        if next_item_size > 0 && fresh_post > next_item_size as f64 {
            let chain_post = fresh_post - next_item_size as f64;
            if chain_post > 0.0 && chain_post <= 4.0 && fragmentation < 0.5 {
                let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
                score -= (12.0 + 8.0 * scarcity) * (1.0 - chain_post / 4.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // Fresh-bin wide-chain lane.
        if next_item_size > 0 && fresh_post > next_item_size as f64 {
            let chain_post = fresh_post - next_item_size as f64;
            let open_space = mean_residual * open_bins_count as f64;
            if chain_post > 8.0 && chain_post <= 14.0 && open_space < 2.0 * cap && remaining_frac > 0.1 {
                score -= 7.0 * (1.0 - (chain_post - 8.0) / 6.0) * (1.0 - progress);
            }
        }
        // MUTATION (gen 158): fresh-bin near-tile remainder lane — when the
        // fresh post-residual tiles the next item with only a tiny remainder
        // (<= 3) and aggregate slack is thin, opening creates a near-perfect
        // tiling lane; reward moderately so the new bin absorbs repeated
        // next-item placements instead of scattering slack.
        if next_item_size > 1 && fresh_post > 0.0 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            let open_space = mean_residual * open_bins_count as f64;
            if reps >= 2 && rem <= 3 && open_space < 2.0 * cap {
                score -= 6.0 * ((reps as f64).min(4.0) - 1.0) * (1.0 - rem as f64 / 3.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // MUTATION (gen 158): fresh-bin overflow guard — when the fresh
        // leftover cannot host the next item but open bins can, and demand
        // cushion is thin, penalize the open so slack stays where it can be
        // reused rather than locking a large dead tail in a new bin.
        if next_item_size > 0 && fresh_post > 0.0 && (fresh_post as u32) < next_item_size
            && mean_residual >= next_item_size as f64 && remaining_frac > 0.2 {
            let open_space = mean_residual * open_bins_count as f64;
            if open_space < 1.2 * cap {
                score += 14.0 * (fresh_post / cap) * (1.0 - progress);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Layered dead-space rewards (lower post_residual = better).
    if post_residual == 0 {
        score -= 250.0;
    } else if post_residual <= 4 {
        score -= 250.0 + 4.2 * (4 - post_residual) as f64;
    } else if post_residual <= 10 {
        score -= 64.0 + 3.6 * (10 - post_residual) as f64;
    } else if post_residual <= 22 {
        score -= 13.5 + 1.5 * (22 - post_residual) as f64;
    } else if post_residual <= 32 {
        score -= 5.0 + 0.7 * (32 - post_residual) as f64;
    } else if post_residual <= 48 {
        score -= 1.2 + 0.22 * (48 - post_residual) as f64;
    } else {
        score -= 1.2 - 0.014 * (post_residual as f64 - 48.0);
    }

    let w = 0.33 + 0.67 * progress * progress;
    score *= w;

    // Lookahead coupling with the next item.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if next_item_size < post_residual {
            let two_step_waste = (post_residual - next_item_size) as f64;
            if two_step_waste <= 8.0 {
                score -= 135.0 - 2.3 * two_step_waste;
            } else {
                score -= 72.0 - 0.58 * two_step_waste;
            }
            if two_step_waste <= 3.0 {
                score -= 48.0;
            }
        } else {
            let miss = (next_item_size - post_residual) as f64;
            score += 0.95 * miss;
            if miss > 26.0 {
                score += 0.55 * (miss - 26.0);
            }
        }
    }

    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
        let boost = 36.0 + 26.0 * scarcity;
        score -= boost * (1.0 - slack / cap) * (0.6 + 0.4 * (1.0 - progress));
        if fitting_bins_count <= 2 {
            score -= 15.0 * (1.0 - slack / cap);
        }
        if slack == 0.0 {
            score -= 20.0 * (1.0 - progress);
        }
    }

    if bin_residual != bin_capacity {
        let dead = (bin_residual - item_size) as f64;
        let dead_ratio = dead / cap;
        if dead_ratio > 0.5 && fitting_bins_count > 1 {
            score += 10.5 * (dead_ratio - 0.5) * (1.0 - progress);
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
            && mean_residual > 0.0 && (mean_residual as u32) >= next_item_size {
            score += 12.0;
        }
        if post_residual > 12 && post_residual < 40 && next_item_size > post_residual {
            let orphan = (post_residual as f64 - 12.0) / 28.0;
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            score += 17.0 * orphan * scarcity * (0.5 + 0.5 * (1.0 - progress));
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let chain = post_residual % next_item_size.max(1);
            if chain == 0 {
                score -= 26.0 * (1.0 - progress);
            } else if chain <= 3 {
                score -= 11.0 * (1.0 - progress);
            }
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            let stranded = (next_item_size - post_residual) as f64;
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            if stranded <= 10.0 {
                score += (8.5 + 1.1 * (10.0 - stranded)) * scarcity * (0.4 + 0.6 * (1.0 - progress));
            } else {
                let proximity = 1.0 - (stranded - 10.0).min(cap) / cap;
                score += 3.2 * proximity * scarcity * (1.0 - progress);
            }
        }
        if dead_ratio > 0.35 && fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score += 7.5 * (dead_ratio - 0.35) * tightness * (1.0 - progress);
        }
        if post_residual > 0 && mean_residual > 0.0 {
            let gap = mean_residual - post_residual as f64;
            if gap > 0.0 && gap < 0.15 * cap && fitting_bins_count > 2 {
                score += 4.8 * (gap / (0.15 * cap)) * (1.0 - progress);
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size.max(1) && fitting_bins_count > 2 {
            score -= 6.5 * (1.0 - progress);
        }
        if post_residual == 0 && bin_residual < bin_capacity {
            score -= 42.0 * (1.0 - bin_residual as f64 / cap) * (1.0 - progress);
        }
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 1 {
            let harmony = (post_residual as f64 - mean_residual).abs() / cap;
            if harmony < 0.08 {
                score -= 9.0 * (1.0 - harmony / 0.08) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        if post_residual > 6 && post_residual <= 30 && next_item_size > 0 && next_item_size <= post_residual {
            let reps = post_residual / next_item_size.max(1);
            if reps >= 2 {
                score -= 3.5 * (reps as f64).min(4.0) * (1.0 - progress);
            }
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let after_next = post_residual - next_item_size;
            if after_next > 0 && after_next <= 12 {
                let tail = after_next as f64;
                score -= (14.0 - 0.9 * tail) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        if post_residual > 0 && post_residual < 6 && next_item_size > post_residual {
            score += 6.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let after_next = (post_residual - next_item_size) as f64;
            if after_next > 8.0 && after_next <= 16.0 && progress < 0.85 {
                let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
                score -= (4.0 + 3.0 * scarcity) * (1.0 - (after_next - 8.0) / 8.0) * (1.0 - progress);
            }
        }
        if post_residual > 0 && next_item_size > 0 && fitting_bins_count > 3 {
            let overshoot = post_residual.saturating_sub(next_item_size) as f64;
            if overshoot > 16.0 {
                score += 1.6 * ((overshoot - 16.0) / cap).min(0.25) * (1.0 - progress);
