        }
        // gen 110: demand-scaled open throttle.
        if remaining_frac < 0.3 && fresh_post > 0.25 * cap {
            let est_need = (remaining as f64) * (item_size as f64) * 0.5;
            if open_capacity > 1.3 * est_need {
                score += 24.0 * (open_capacity / (1.3 * est_need)).min(2.0) * (1.0 - remaining_frac / 0.3);
            }
        }
        // MUTATION (gen 159): fresh-bin two-step chain reward — when the fresh
        // bin's post-residual decomposes into next_item plus a tiny tail
        // (<= 5), opening it sets up two consecutive cheap closures; deepen
        // the existing chain bonus for this narrow band.
        if next_item_size > 0 && fresh_post > next_item_size as f64 {
            let tail2 = fresh_post - next_item_size as f64;
            if tail2 > 0.0 && tail2 <= 5.0 && fragmentation < 0.45 {
                score -= 16.0 * (1.0 - tail2 / 5.0) * (0.35 + 0.65 * progress);
            }
        }
        // MUTATION (gen 159): surplus-slack refusal hardening — when the
        // aggregate open slack already exceeds remaining demand by a wide
        // margin, refuse new bins more firmly unless the fresh bin is an
        // exact closer, directly attacking the wasted-bin gap.
        if remaining_frac < 0.4 && fresh_post > 0.2 * cap && !fresh_is_exact {
            let est_need = (remaining as f64) * (item_size as f64) * 0.55;
            if open_capacity > 1.6 * est_need {
                score += 18.0 * (open_capacity / (1.6 * est_need)).min(2.5)
                    * (1.0 - remaining_frac / 0.4);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;
    let mean_r = mean_residual / cap;

    // Base: post residual, weighted by progress (later => residual matters more)
    let mut score = pr * (0.6 + 0.8 * progress);

    // Smooth quadratic coupling: penalize mid-range residuals (dead space),
    // reward near-zero and large residuals less mildly.
    let quad = norm_pr * (norm_pr - 0.5) * (1.0 - norm_pr);
    score += 40.0 * quad;

    // Interaction: small post-residual that still fits the next item is valuable
    if next_item_size > 0 && post_residual >= next_item_size {
        let fit_quality = 1.0 - (norm_pr - norm_next).abs();
        score -= 12.0 * fit_quality * (1.0 - progress);
    }
    // Penalize post-residual that blocks the next item (smoothly)
    if next_item_size > post_residual as u32 && post_residual > 0 {
        let gap = (next_item_size as f64 - pr) / cap;
        score += 15.0 * gap * gap;
    }

    // Last-chance bonus: strongly favor this bin if it's the only fitting one
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_item);
    }

    // Penalize bins whose residual deviates from the mean (keep diversity)
    score += 6.0 * (norm_pr - mean_r).abs() * (norm_pr - mean_r).abs() * cap;

    // Tight fit reward: item almost fills the bin
    score -= 10.0 * norm_item * norm_item * (1.0 - norm_pr);

    // New-bin candidate: mildly discouraged unless residuals are large
    if bin_residual == bin_capacity {
        score += 8.0 - 10.0 * mean_r;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
