            }
        }
        // gen 76: usable-residual scarcity bonus.
        if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count == 1 && bin_residual != bin_capacity {
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score -= 14.0 * (1.0 - progress) * (0.6 + 0.4 * tightness);
        }
        // gen 81: dead-space compaction gradient.
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
            && fitting_bins_count > 1 {
            let open_space = mean_residual * open_bins_count as f64;
            if open_space > 2.0 * cap {
                let frac = post_residual as f64 / next_item_size as f64;
                score += 10.0 * (1.0 - frac) * (0.5 + 0.5 * progress);
            }
        }
        // gen 81: consolidation pull.
        if post_residual > 0 && fitting_bins_count > 2 && progress > 0.5 {
            let fill = 1.0 - post_residual as f64 / cap;
            score -= 5.0 * fill * (progress - 0.5);
        }
        // MUTATION (gen 160): variance-collapse gradient — diagnosed weakness is
        // residual spread. Reward placements that pull this bin's post-residual
        // toward the global mean residual (harmonic consolidation), scaling with
        // how many bins could otherwise fit the item (competition makes the
        // choice meaningful) and strengthening late in the stream where the
        // remaining items can no longer absorb scattered slack.
        if post_residual > 0 && fitting_bins_count > 1 && mean_residual > 0.0 {
            let dev = (post_residual as f64 - mean_residual).abs() / cap;
            let strength = 0.3 + 0.7 * progress;
            score += 3.4 * dev * strength / (fitting_bins_count as f64).sqrt();
        }
        // MUTATION (gen 160): near-closed-bin finisher — when the placement
        // leaves a residual small enough that it is very likely to become
        // dead space (below the median-ish item size), but the bin is already
        // more than 80% full, treat the leftover as nearly worthless and
        // reward closing it out; this targets the last few wasted bins that
        // sit at 80-95% fill with unusable slivers.
