        // gen 76: usable-residual scarcity bonus.
        if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count == 1 && bin_residual != bin_capacity {
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score -= 14.0 * (1.0 - progress) * (0.6 + 0.4 * tightness);
        }
        // gen 81: dead-space compaction gradient (refined gen 160: widen the
        // open-space trigger to 1.75x cap and steepen the gradient so residual
        // variance shrinks further in mid-stream).
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
            && fitting_bins_count > 1 {
            let open_space = mean_residual * open_bins_count as f64;
            if open_space > 1.75 * cap {
                let frac = post_residual as f64 / next_item_size as f64;
                score += 13.0 * (1.0 - frac) * (0.5 + 0.5 * progress);
            }
        }
        // gen 81: consolidation pull (refined gen 160: start earlier at 0.4
        // progress and scale with scarcity to close residual spread sooner).
        if post_residual > 0 && fitting_bins_count > 2 && progress > 0.4 {
            let fill = 1.0 - post_residual as f64 / cap;
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            score -= (4.0 + 4.0 * scarcity) * fill * (progress - 0.4);
        }
        // MUTATION (gen 160): residual-parity pairing — when this placement
        // leaves a post-residual that exactly complements the mean open
        // residual (they could jointly absorb two future items), reward it
        // mildly to drive residual mass toward reusable sizes and cut
        // dead-space ratio late in the stream.
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 1 && progress > 0.3 {
            let pair = post_residual as f64 + mean_residual;
            if pair <= cap && pair + 6.0 >= cap {
