        if post_residual > 0 && next_item_size > 1 && next_item_size <= post_residual {
            let reps = post_residual / next_item_size;
            let rem = post_residual % next_item_size;
            if reps >= 1 && rem == 0 {
                let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
                score -= (5.0 + 6.0 * scarcity) * ((reps as f64).min(3.0)) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 1 && progress > 0.25 {
            let target = 0.5 * (mean_residual + 0.5 * cap);
            let dev = ((post_residual as f64 - target).abs() / cap).min(0.5);
            score += 2.4 * dev * (progress - 0.25);
        }
        if post_residual > 0 && next_item_size > 0 && post_residual > next_item_size {
            let after_next = post_residual - next_item_size;
            if after_next > 0 && after_next < 6 && progress > 0.35 {
                score -= 11.0 * (1.0 - after_next as f64 / 6.0) * (progress - 0.35);
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count == 1 && bin_residual != bin_capacity {
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score -= 14.0 * (1.0 - progress) * (0.6 + 0.4 * tightness);
        }
        // gen 81: dead-space compaction gradient.
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
            && fitting_bins_count > 1 {
            let open_space = mean_residual * open_bins_count as f64;
            if open_space > 2.0 * cap {
                let frac = post_residual as f64 / next_item_size as f64;
                score += 10.0 * (1.0 - frac) * (0.5 + 0.5 * progress);
            }
        }
        // gen 81: consolidation pull.
        if post_residual > 0 && fitting_bins_count > 2 && progress > 0.5 {
            let fill = 1.0 - post_residual as f64 / cap;
            score -= 5.0 * fill * (progress - 0.5);
        }
        // MUTATION (gen 161): residual-homogenization gradient — diagnose the
        // residual-variance weakness directly: when the placement leaves a
        // post-residual far from the fleet mean while the fleet is already
        // tightly clustered, penalize the outlier placement so residuals
        // converge, freeing large chunks for later items instead of dust.
        if post_residual > 0 && fitting_bins_count > 2 && mean_residual > 0.0 && progress > 0.2 {
            let pr = post_residual as f64;
            let spread = (pr - mean_residual).abs();
            let fleet_tight = if pr > mean_residual {
                spread / (mean_residual + 1.0)
            } else {
                spread / (pr + 1.0)
            };
            if fleet_tight > 0.45 {
                let excess = (fleet_tight - 0.45).min(1.0);
                let late_w = 0.4 + 0.6 * progress;
                score += 7.5 * excess * late_w * (1.0 - spread / cap).min(1.0);
            } else if fleet_tight < 0.12 {
                // Reward placements that keep residuals in the dominant
                // cluster — these pair well with future medium items.
                score -= 4.5 * (1.0 - fleet_tight / 0.12) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // MUTATION (gen 161): two-step exact-closure lookahead — when the
        // next item would leave a residual exactly matching the item after
        // it (approximated by mean residual), the placement chains into a
        // full close; reward proportional to how late in the stream we are,
        // since closures compound at the tail where the 29 wasted bins sit.
        if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size && progress > 0.55 {
            let after_next = post_residual - next_item_size;
            let predicted = mean_residual as u32;
            if predicted > 0 && after_next >= predicted && after_next < predicted + 3 {
                score -= 8.0 * (1.0 - (after_next - predicted) as f64 / 3.0) * (progress - 0.55);
            }
