    if bin_residual != bin_capacity && post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 2 && progress > 0.3 {
        let dev = (post_residual as f64 - mean_residual).abs() / cap;
        if dev < 0.12 {
