        if next_item_size > 1 && fresh_post > 0.0 && (fresh_post as u32) >= next_item_size && remaining_frac > 0.08 {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 2 && rem == 0 && mean_residual < next_item_size as f64 {
                score -= 11.0 * ((reps as f64).min(4.0) - 1.0) * remaining_frac * (1.0 - progress);
            }
