        }
        // MUTATION (gen 162): two-step recoverable open — when the fresh bin
        // alone cannot hold the next item but fresh_post plus mean open
        // residual can, the new lane is still recoverable; soften the refusal
        // so useful opens are not over-suppressed.
        if remaining_frac > 0.1 && next_item_size > 0 && (fresh_post as u32) < next_item_size
            && fresh_post + mean_residual >= next_item_size as f64 {
            score -= 10.0 * (1.0 - progress) * (1.0 - remaining_frac.min(1.0));
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
