pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual nonlinearly.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tight * tight;

    // Perfect fill is extremely desirable.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item exactly fits the leftover space, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here: mild penalty proportional to wasted-looking residual.
            let overflow = (next_item_size - post_residual) as f64;
            score += 0.15 * overflow;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when current bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of consuming fresh capacity.
        score += 30.0;
        // If existing bins are fragmented (high mean residual vs item), new bin is fine.
        let frag = mean_residual - item_size as f64;
        if frag > 0.0 {
            score -= 0.5 * frag;
        }
        // Late in the stream, prefer keeping things compact.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
        // Many open bins: discourage opening yet another.
        score += 3.0 * open_bins_count as f64;
    }

