        if fresh_post > 0.0 && mean_residual > 1.0 && remaining_frac > 0.08 {
            let band = ((fresh_post - mean_residual).abs() / (mean_residual + 1.0)).min(1.0);
            if band < 0.4 {
                score -= 9.0 * (1.0 - band / 0.4) * (1.0 - progress);
