}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Base: post residual, shaped non-linearly
    let mut score = pr * (1.0 + 0.35 * x * x);

    // Smooth polynomial coupling of residual with stream progress:
    // late in the stream, large residuals (wasted space) hurt more
    score += 8.0 * x * x * (0.5 + progress);

    // Reward tight fits (small post residual) with smooth decay
    score -= 10.0 * (-2.0 * x).exp();

    // Penalize creating residual that cannot fit the lookahead item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).max(0.0);
        let usable = if pr >= nx { 1.0 } else { 0.5 * (pr / nx.max(1.0)) };
        score += 0.35 * gap * usable;
        // bonus if post residual exactly accommodates next item
        score -= 3.0 * (-((pr - nx) * (pr - nx)) / 18.0).exp();
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 6.0 + 4.0 * progress;
    }

    // Many open bins: mildly discourage spreading, encourage filling
    score += 0.05 * open_bins_count as f64 * x;

    // Mean residual coupling: prefer bins deviating below mean residual (tighter bins)
    score += 0.15 * (mean_residual - pr);

    // New-bin candidate: make it attractive only when no open bin fits well
    if bin_residual == bin_capacity {
        let poor_fit = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score = cap - 2.0 - 8.0 * poor_fit - 3.0 * progress;
    }

    score
}

