}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how well it matches typical item sizes (1..=100)
    // Residuals that are exact multiples of common sizes are more reusable.
    let pr = post_residual;
    let mut reuse_bonus = 0.0f64;
    for d in [10u32, 20, 25, 50, 100, 80, 40].iter() {
        if *d != 0 && pr >= *d && pr % *d == 0 {
            reuse_bonus += 4.0;
        }
    }
    // Fractional fill level classes: post_residual in the lowest decile = very tight fit
    let fill = 1.0 - (pr as f64 / bin_capacity as f64);
    let decile = (fill * 10.0) as u32;
    score -= match decile {
        9 => 12.0,
        8 => 8.0,
        7 => 5.0,
        6 => 3.0,
        _ => 0.0,
    };

    // Integer division threshold: small post_residual (< smallest plausible item) is dead space
    if pr > 0 && pr < 10 {
        score += 15.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
        } else if next_item_size <= pr {
            score -= 6.0;
            // harmonic class match between next item and residual
            if pr % next_item_size == 0 {
                score -= 6.0;
            }
        } else {
            // next item won't fit here; penalize large leftover more
            score += (pr as f64) * 0.05;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Prefer tighter bins relative to mean residual
    score += (mean_residual - bin_residual as f64) * 0.1;

    // Late in stream: consolidate, avoid opening new bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // new-bin candidate: base cost plus penalty growing with open bins and progress
        score = bin_capacity as f64 + open_bins_count as f64 * 3.0 + progress * 40.0 - reuse_bonus;
    } else {
        score -= reuse_bonus;
    }

    score
}

