        }
        // MUTATION (gen 163): fresh-bin strandedness gate — opening a bin
        // whose fresh post-residual falls just short of the next item
        // creates an immediately dead lane; when open slack elsewhere can
        // already absorb the next item, refuse such opens more firmly.
        if fresh_post > 0.0 && next_item_size > 0 && (fresh_post as u32) < next_item_size
            && mean_residual >= next_item_size as f64 && remaining_frac > 0.05 {
            score += 12.0 * (1.0 - fresh_post / next_item_size.max(1) as f64) * (0.4 + 0.6 * (1.0 - progress));
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps after placement.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Penalize large wasted residuals less than tiny ones but still costly.
    if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor new bin only if fit is bad.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * 2.0;

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
    }
    // If next item cannot fit into post_residual, the leftover is dead space; penalize.
    if next_item_size > post_residual && post_residual > 0 {
        score += 10.0;
    }

    // New-bin candidate: keep it moderately attractive when current fit is poor.
    if bin_residual == bin_capacity {
        score -= 5.0;
        if post_residual < 10 {
            score -= 30.0; // opening fresh bin beats creating dead space
        }
    }

    // Progress-aware mild adjustment: later in stream, prefer tighter packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0;

    // Mean residual coupling: if this bin is much tighter than average, prefer it.
    score -= (mean_residual - bin_residual as f64) * 0.3;

    score
}

