        // gen 164 refinement: widen the trigger to open_space > 1.75x cap and
        // steepen the penalty ramp since the parent still strands ~29 bins.
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
            && fitting_bins_count > 1 {
