            let fill = 1.0 - post_residual as f64 / cap;
            score -= 5.5 * fill * (progress - 0.4);
        }
        // MUTATION (gen 164): residual-variance dampener — when this
        // placement's post-residual lands close to the mean open residual,
        // the stream keeps a homogeneous pool of reusable slack; reward
        // homogeneity mildly so bins stay interchangeable for future items.
