            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (next_item_size as f64) * 0.42;
            if open_space > 1.15 * est_need {
                score += 30.0 * (1.0 - remaining_frac) * (fresh_post / cap - 0.3);
            }
        }
        // gen 76: fresh-bin dead-space cap.
        if fresh_post > 0.35 * cap && next_item_size > 0 && (fresh_post as u32) < next_item_size && fragmentation < 0.4 && remaining_frac > 0.15 {
            score += 16.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        // MUTATION (gen 81): tileability-aware open — when the fresh bin's
        // post-residual is an exact multiple of the next item size with
        // three or more repetitions, opening creates a perfectly tileable
        // bin; deepen the reward when fragmentation is low so the new bin
        // acts as a dedicated tiling lane instead of scattering slack.
        if next_item_size > 1 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 3 && rem == 0 && fragmentation < 0.3 {
                score -= 14.0 * ((reps as f64).min(5.0) - 2.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // MUTATION (gen 164): homogeneous-pool open — when the fresh bin's
        // post-residual sits near the current mean residual, opening keeps
        // the open-bin slack pool uniform and interchangeable; reward this
        // mildly when fragmentation is moderate so slack doesn't polarize
        // into full bins plus stranded crumbs.
        if fresh_post > 0.0 && mean_residual > 0.0 && fragmentation > 0.25 && fragmentation < 0.6 {
            let homogeneity = (fresh_post - mean_residual).abs() / cap;
            if homogeneity < 0.08 {
                score -= 12.0 * (1.0 - homogeneity / 0.08) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post * post / cap;

    // Reward tight fits: subtract for small post_residual (smooth quadratic coupling)
    let tightness = 1.0 - post / cap;
    score -= 12.0 * tightness * tightness;

    // Non-linear interaction of post_residual with stream progress
    let prog_term = progress * (1.0 - progress) * 4.0; // peaks mid-stream
    score -= prog_term * (cap - post) * 0.15;

    // Penalize bins whose residual deviates from mean residual (smooth)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 6.0 * dev * dev;

    // Last-chance bin: strong reward if it fits
    if fitting_bins_count == 1 && post_residual <= bin_residual {
        score -= 8.0 + 0.05 * item_size as f64;
    }

    // Lookahead: penalize if next item won't fit in post_residual
    if next_item_size > 0 && next_item_size > post_residual {
        score += 3.0;
    } else if next_item_size > 0 {
        score -= 0.02 * next_item_size as f64 * (1.0 - post / cap);
    }

    // Mild penalty for many open bins to encourage consolidation
    score += 0.01 * open_bins_count as f64 * (1.0 - tightness);

    // New-bin candidate: make it slightly less attractive unless post_residual is large
    if bin_residual == bin_capacity {
        score += 5.0 * (1.0 - item_size as f64 / cap);
    }

    score
}

