        }
        if post_residual > 0 && next_item_size > 0 && fitting_bins_count > 1 {
            let usable = next_item_size <= post_residual
                || (mean_residual as u32) >= next_item_size;
            if !usable {
                let waste_frac = post_residual as f64 / cap;
                let late = 0.35 + 0.65 * progress;
                score += 9.0 * waste_frac * late;
            }
        }
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 2 {
            let rel = post_residual as f64 / (mean_residual + 1.0);
            if rel < 0.5 {
                score -= 6.0 * (1.0 - rel / 0.5) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        if post_residual > 0 && next_item_size > 1 && next_item_size <= post_residual {
            let reps = post_residual / next_item_size;
            let rem = post_residual % next_item_size;
            if reps >= 1 && rem == 0 {
                let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
                score -= (5.0 + 6.0 * scarcity) * ((reps as f64).min(3.0)) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 1 && progress > 0.25 {
            let target = 0.5 * (mean_residual + 0.5 * cap);
            let dev = ((post_residual as f64 - target).abs() / cap).min(0.5);
            score += 2.4 * dev * (progress - 0.25);
        }
        // near-full chain extension (widened window, earlier activation).
        if post_residual > 0 && next_item_size > 0 && post_residual > next_item_size {
            let after_next = post_residual - next_item_size;
            if after_next > 0 && after_next < 6 && progress > 0.35 {
                score -= 11.0 * (1.0 - after_next as f64 / 6.0) * (progress - 0.35);
            }
        }
        // usable-residual scarcity bonus for tight single-bin reuse.
        if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count == 1 && bin_residual != bin_capacity {
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score -= 14.0 * (1.0 - progress) * (0.6 + 0.4 * tightness);
        }
        // MUTATION (gen 165): dead-space compaction gradient — reinforced
        // version of the gen-81 term. When the leftover residual cannot host
        // the next item and aggregate open slack is plentiful, this residual
        // is pure dead space; penalize proportionally, with a sharper
        // gradient for very small leftovers (high residual-variance source).
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
            && fitting_bins_count > 1 {
            let open_space = mean_residual * open_bins_count as f64;
            if open_space > 1.75 * cap {
                let frac = post_residual as f64 / next_item_size as f64;
                let sharp = 1.0 + 1.5 * (1.0 - frac);
                score += 12.0 * sharp * (1.0 - frac) * (0.5 + 0.5 * progress);
            }
        }
        // MUTATION (gen 165): consolidation pull — deepened and extended
        // earlier (progress > 0.4). Prefers the bin whose placement brings
        // it closest to full relative to competing bins, tightening the
        // late-stream residual spread (the diagnosed weakness).
        if post_residual > 0 && fitting_bins_count > 2 && progress > 0.4 {
            let fill = 1.0 - post_residual as f64 / cap;
            score -= 7.5 * fill * (progress - 0.4);
        }
        // MUTATION (gen 165): residual-variance damper — when this bin's
        // post-residual lands close to the mean open residual, reward the
        // placement so open-bin residuals cluster together and future items
        // find more compatible landing spots.
        if post_residual > 0 && mean_residual > 0.0 && open_bins_count > 2 && progress > 0.3 {
            let dev = (post_residual as f64 - mean_residual).abs() / cap;
            if dev < 0.06 {
                score -= 8.0 * (1.0 - dev / 0.06) * (progress - 0.3);
            }
        }
        // MUTATION (gen 165): near-exact two-step tiling — when post_residual
        // leaves room for the next item plus a small universal tail (<= 5),
        // the bin can absorb the next item AND likely another small item;
        // deepen the reward scaled by fitting scarcity.
        if next_item_size > 0 && post_residual > next_item_size {
            let tail = post_residual - next_item_size;
            if tail > 0 && tail <= 5 {
