}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in the "unusable gap" zone
    // (small leftover that few future items can fill) is heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 8.0;
    } else {
        // Larger leftovers are usable; gently reward them.
        score -= 4.0;
    }

    // Reward tight fits (post_residual near zero but not a dead gap).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 12.0 * fill_ratio;

    // Open-bins pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading out.
    score += 0.6 * open_bins_count as f64;

    // Pull score toward the mean residual: prefer bins whose residual is
    // close to average (keeps residuals uniform, easier to pair-fill later).
    score += 0.15 * (bin_residual as f64 - mean_residual).abs();

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual,
    // reward this placement strongly (perfect pairing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 6.0;
        }
        // If next item cannot use the leftover and leftover is small, penalize.
        else if next_item_size > post_residual && post_residual < 15 {
            score += 15.0;
        }
    }

    // Early in the stream, be slightly more willing to open bins for good
    // future flexibility; late in the stream, pack tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (1.0 - progress);

    // New-bin candidate: make an empty bin mildly attractive only when the
    // item is large (would leave a big usable gap anyway) or no tight option
    // exists; otherwise the penalties above keep it from winning.
    if bin_residual == bin_capacity {
        score += 10.0 - 8.0 * fill_ratio;
    }

    score
}

