        // 3+ reps creates a perfectly tileable bin; deepened reward when
        // fragmentation is low so the new bin acts as a dedicated tiling lane.
        if next_item_size > 1 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 3 && rem == 0 && fragmentation < 0.3 {
                score -= 16.0 * ((reps as f64).min(5.0) - 2.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // MUTATION (gen 165): residual-harmony open — when the fresh bin's
        // post-residual closely matches the current mean open residual, the
        // new bin joins a uniform gap pool instead of adding variance; reward
        // mildly so consolidation-friendly opens are preferred.
        if fresh_post > 0.0 && mean_residual > 0.0 && open_bins_count > 1 {
            let harmony = 1.0 - (fresh_post - mean_residual).abs() / cap;
            if harmony > 0.88 && fragmentation < 0.5 && remaining_frac > 0.1 {
                score -= 12.0 * (harmony - 0.88) / 0.12 * (0.5 + 0.5 * (1.0 - progress));
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space relative to mean residual across open bins.
    let post = post_residual as f64;
    score += 0.5 * (post - mean_residual).max(0.0);

    // Perfect fit reward: nearly full bin is excellent.
    if post_residual <= 2 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // 2-step lookahead: reward if the NEXT item exactly/fully uses the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // chain fit: perfect two-item packing
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // reward tight chain fits, penalize large leftover slack after next item
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
            if slack > 20.0 {
                score += 0.3 * (slack - 20.0); // dead space created for the step after next
            }
        } else {
            // next item cannot follow into this bin: mild penalty unless this is a new bin
            if bin_residual != bin_capacity {
                score += 5.0;
            }
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
        if post_residual <= 15 {
            score -= 10.0;
        }
    }

    // New-bin candidate: make it attractive only when open bins would leave big dead space
    // or stream is early (exploration to build good bins).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let dead_space_if_used_here = post; // == bin_capacity - item_size
        // prefer new bin when the alternative fits leave large residuals
        if dead_space_if_used_here > 40.0 || open_bins_count == 0 {
            score -= 8.0 + 15.0 * (1.0 - progress);
        } else {
            score += 10.0 + 20.0 * progress; // late stream: consolidate into open bins
        }
    }

    // Mild consolidation pressure: fewer open bins relative to items -> favor reuse.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
