        if dead_ratio > 0.35 && fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score += 7.5 * (dead_ratio - 0.35) * tightness * (1.0 - progress);
        }
        if post_residual > 0 && mean_residual > 0.0 {
            let gap = mean_residual - post_residual as f64;
