        // penalize any non-exact open more sharply to squeeze the last bins.
        if remaining_frac < 0.08 && fresh_post > 0.0 && !fresh_is_exact {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (next_item_size.max(1) as f64) * 0.5;
            if open_space > est_need {
                score += 24.0 * (1.0 - remaining_frac / 0.08) * (fresh_post / cap);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize small unusable dead space (waste < typical small item).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward if next item fits into post_residual (chaining placements).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0;
            // Perfect chain: next item exactly fills leftover.
            if next_item_size == post_residual {
                score -= 20.0;
            }
        } else {
            // Next item won't fit here; penalize leaving awkward gaps.
            let gap_waste = (post_residual as f64) / (next_item_size as f64);
            if gap_waste > 0.5 {
                score += 10.0 * gap_waste;
            }
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Many open bins: discourage opening new ones, encourage consolidation.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus penalty scaling with open bins.
        score += 15.0 + 6.0 * (open_bins_count as f64);
        // Early in stream, new bins are cheaper (exploration); late stream, avoid them.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
        // If mean residual across open bins is large, opening a new bin is wasteful.
        score += 0.3 * mean_residual;
    } else {
        // Fitting into an existing bin with residual above mean is slightly favored.
        score += 0.1 * (mean_residual - bin_residual as f64);
    }

    // Prefer filling bins that are already mostly used (fragmentation control).
    let fill_ratio = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
