            }
        }
        // gen 76: demand-aware fresh-bin refusal.
        if remaining_frac >= 0.05 && fresh_post > 0.3 * cap && next_item_size > 0 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (next_item_size as f64) * 0.42;
            if open_space > 1.15 * est_need {
                score += 30.0 * (1.0 - remaining_frac) * (fresh_post / cap - 0.3);
            }
        }
        // gen 76: fresh-bin dead-space cap.
        if fresh_post > 0.35 * cap && next_item_size > 0 && (fresh_post as u32) < next_item_size && fragmentation < 0.4 && remaining_frac > 0.15 {
            score += 16.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        // gen 81: tileability-aware open.
        if next_item_size > 1 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 3 && rem == 0 && fragmentation < 0.3 {
                score -= 14.0 * ((reps as f64).min(5.0) - 2.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // MUTATION (gen 166): mean-aligned fresh opens — when the fresh bin's
        // post-residual sits close to the current mean residual, opening it
        // adds another tileable lane of the dominant remainder size; reward
        // mildly so the residual distribution stays compact.
        if fresh_post > 0.0 && mean_residual > 0.0 && open_bins_count > 3 && remaining_frac > 0.1 {
            let align = (fresh_post - mean_residual).abs() / cap;
            if align < 0.06 {
                score -= 12.0 * (1.0 - align / 0.06) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fit = item_size as f64 / cap;

    // Base: prefer small post residual, with smooth non-linear shaping
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Polynomial coupling of post_residual with stream progress:
    // late in the stream, tight fits matter more
    let progress_coupling = norm_pr * (1.0 - progress) * (1.0 - progress)
        - 0.3 * norm_pr * progress * progress;
    score += 40.0 * progress_coupling;

    // Reward using a near-full bin (low dead space) more strongly as stream advances
    score -= 30.0 * fit * fit * progress;

    // Penalize leaving residuals that are too small to be useful later
    let usefulness = (norm_pr * (1.0 - norm_pr) * 4.0).min(1.0); // peaks at half-full residual
    score -= 10.0 * usefulness * (1.0 - progress);

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_pr);
    }

    // Lookahead: if next item fits the post residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 15.0 * (1.0 - progress);
    } else if next_item_size > 0 {
        score += 5.0 * progress;
    }

    // Mild penalty when many bins are open and this placement wastes capacity
    score += 0.1 * open_bins_count as f64 * norm_pr;

    // Discourage opening new bins when a reasonable fit exists
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress) + 10.0 * (1.0 - fit);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
