            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 2 && rem == 0 && fragmentation < 0.4 {
                score -= 10.0 * ((reps as f64).min(4.0) - 1.0) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        if remaining_frac >= 0.45 && remaining_frac < 0.5 && fresh_post > 0.45 * cap && fragmentation > 0.5 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.55;
            if open_space > est_need {
                score += 22.0 * (1.0 - remaining_frac / 0.5);
            }
        }
        // gen 76: demand-aware fresh-bin refusal.
        if remaining_frac >= 0.05 && fresh_post > 0.3 * cap && next_item_size > 0 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (next_item_size as f64) * 0.42;
            if open_space > 1.15 * est_need {
                score += 30.0 * (1.0 - remaining_frac) * (fresh_post / cap - 0.3);
            }
        }
        // gen 76: fresh-bin dead-space cap.
        if fresh_post > 0.35 * cap && next_item_size > 0 && (fresh_post as u32) < next_item_size && fragmentation < 0.4 && remaining_frac > 0.15 {
            score += 16.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        // gen 81: tileability-aware open.
        if next_item_size > 1 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 3 && rem == 0 && fragmentation < 0.3 {
                score -= 14.0 * ((reps as f64).min(5.0) - 2.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // gen 138: lane-diversity open.
        if next_item_size > 0 && fresh_post > 0.0 && fragmentation > 0.45 && remaining_frac > 0.2 {
            let dup = ((fresh_post - mean_residual).abs() / cap) < 0.08;
            if !dup && (fresh_post as u32) >= next_item_size {
                score -= 9.0 * (1.0 - progress) * (0.4 + 0.6 * (fragmentation - 0.45) / 0.55);
            }
        }
        // gen 142: tileable-lane open preference.
        if next_item_size > 1 && remaining_frac > 0.1 && fragmentation < 0.5 {
            let open_can_tile = mean_residual >= next_item_size as f64
                && (mean_residual as u32) % next_item_size == 0;
            if (fresh_post as u32) % next_item_size == 0 && (fresh_post as u32) >= 2 * next_item_size && !open_can_tile {
                score -= 12.0 * (1.0 - progress) * (0.5 + 0.5 * (1.0 - fragmentation));
            }
        }
        // gen 147: slack-aware fresh-bin gate.
        if remaining_frac > 0.08 && fresh_post > 0.0 && next_item_size > 0 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (next_item_size as f64) * 0.5;
            if open_space > 1.3 * est_need && (fresh_post as u32) > next_item_size {
                let surplus = ((open_space - est_need) / (4.0 * cap)).min(1.0);
                score += 18.0 * surplus * (fresh_post / cap) * (1.0 - remaining_frac / 0.08).abs().min(1.0);
            }
        }
        // MUTATION (gen 166): tiny-residual open preference — when the fresh
        // bin would leave a residual of at most 8 (nearly a perfect close),
        // deepen the open reward since such lanes close almost immediately
        // and never contribute to residual variance.
        if fresh_post > 0.0 && fresh_post <= 8.0 && !fresh_is_exact {
            score -= 18.0 * (1.0 - fresh_post / 8.0) * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: post_residual mod 10 defines
    // "waste residue" classes. Residues divisible by 10 are reusable by
    // the widest range of future items; odd/prime-ish residues are dead.
    let residue_class = (post_residual % 10) as f64;
    score += residue_class * 0.8;

    // Bonus for post_residual landing on common item-size multiples
    // (harmonic divisors of capacity): 0, 10, 20, 25, 50 etc.
    if post_residual == 0 {
        score -= 30.0; // perfect fit
    } else if post_residual % 25 == 0 {
        score -= 12.0;
    } else if post_residual % 10 == 0 {
        score -= 8.0;
    } else if post_residual % 5 == 0 {
        score -= 3.0;
    } else {
        score += 6.0; // non-harmonic leftover
    }

    // Lookahead coupling: if next item fits exactly in post_residual,
    // strongly reward this bin (chained harmonic fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let next_left = post_residual - next_item_size;
            score -= 10.0 - ((next_left % 10) as f64) * 0.5;
        } else {
            // next item cannot use this bin's leftover; penalize by
            // how far off the next item is from the residue class
            let gap = next_item_size - post_residual;
            score += (gap % 10) as f64 * 0.4 + 2.0;
        }
    }

    // Integer-division threshold on post_residual: large leftovers are
    // flexible, tiny ones (1..10) are nearly dead space.
    let half = bin_capacity / 2;
    if post_residual >= half {
        score -= 6.0;
    } else if post_residual < 10 {
        score += 10.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the waste is severe.
    if fitting_bins_count == 1 && post_residual >= 10 {
        score -= 8.0;
    }

    // Prefer filling bins when many are open (consolidation pressure),
    // scaled by stream progression.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (open_bins_count as f64).ln() * (2.0 + 3.0 * progress);

    // Mean-residual coupling: placing into a bin below mean residual
    // balances the pool; above mean penalizes slightly.
    score += (mean_residual - bin_residual as f64) * 0.05;

    // New-bin candidate: only attractive when current leftovers cannot
    // accommodate the item harmonically.
    if bin_residual == bin_capacity {
        let bad_fit = if next_item_size > 0 && next_item_size <= post_residual { 0.0 } else { 1.0 };
        score = bin_capacity as f64 * 0.9 - 10.0 * bad_fit + (open_bins_count as f64) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
