        if next_item_size > 0 && fresh_post > 0.0 && fragmentation < 0.45 {
            let open_space = mean_residual * open_bins_count as f64;
            if (fresh_post as u32) == next_item_size {
                score -= 12.0 * (1.0 - progress);
            } else if (fresh_post as u32) > next_item_size {
                let tail = fresh_post - next_item_size as f64;
                if tail <= 2.0 && open_space < 1.2 * cap {
                    score -= 10.0 * (1.0 - tail / 2.0) * (1.0 - progress);
                }
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
