            }
        }
        // MUTATION (gen 167): dual-step exactness lane — reward placements
        // where both the immediate fit and the two-step remainder are tight,
        // combining fine-grained residual fitting with lookahead.
        if next_item_size > 0 && post_residual > next_item_size && bin_residual != bin_capacity {
            let after_next = (post_residual - next_item_size) as f64;
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            if after_next <= 2.0 {
                score -= (18.0 + 9.0 * scarcity) * (1.0 - after_next / 2.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // MUTATION (gen 167): thin-slack variance squeeze — when aggregate
        // open slack is thin, penalize bins whose post-residual exceeds the
        // field mean, pulling residuals toward a common tight floor.
