            let open_space = mean_residual * open_bins_count as f64;
            if open_space < 1.5 * cap && (post_residual as f64) > mean_residual {
                score += 3.0 * ((post_residual as f64 - mean_residual) / cap) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
    } else {
