        }
        // gen 94: fresh-bin exact-closure bonus.
        if next_item_size > 0 && (fresh_post as u32) == next_item_size && fragmentation <= 0.3 {
            score -= 18.0 * (0.4 + 0.6 * (1.0 - progress));
        }
        // gen 94: fresh-bin strand guard.
        if next_item_size > 0 && fresh_post > 0.3 * cap && (fresh_post as u32) < next_item_size
