            score += 14.0 * (fresh_post / cap - 0.3) * (1.0 - progress);
        }
        // gen 102: fresh-bin mid-gap refusal.
        if next_item_size > 0 && fresh_post > 12.0 && fresh_post <= 24.0 && fitting_bins_count > 1 {
            let mid = (fresh_post - 12.0) / 12.0;
            score += 7.0 * mid * (0.35 + 0.65 * progress);
        }
        // gen 102: fresh-bin residual-harmony bonus.
        if fresh_post > 0.0 && fresh_match < 0.08 && remaining_frac > 0.1 {
            score -= 10.0 * (1.0 - fresh_match / 0.08) * (0.4 + 0.6 * (1.0 - progress));
        }
        // gen 110: fresh-bin late exact-closure amplifier.
        if progress > 0.75 && next_item_size > 0 && (fresh_post as u32) >= next_item_size {
            let tail = (fresh_post as u32 - next_item_size) as f64;
            if tail <= 2.0 {
                score -= 20.0 * (1.0 - tail / 2.0) * (progress - 0.75) / 0.25;
            }
        }
        // gen 110: demand-scaled open throttle.
        if remaining_frac < 0.3 && fresh_post > 0.25 * cap {
            let est_need = (remaining as f64) * (item_size as f64) * 0.5;
            if open_capacity > 1.3 * est_need {
                score += 24.0 * (open_capacity / (1.3 * est_need)).min(2.0) * (1.0 - remaining_frac / 0.3);
            }
        }
        // MUTATION (gen 167): fresh-bin two-step exactness — when the fresh
        // leftover exactly equals the next item, or leaves a tiny tail while
        // aggregate slack cannot host the next item, opening a dedicated
        // tiling lane beats scattering into open bins.
        if next_item_size > 0 && fresh_post > 0.0 && fragmentation < 0.45 {
            let open_space = mean_residual * open_bins_count as f64;
            if (fresh_post as u32) == next_item_size {
                score -= 12.0 * (1.0 - progress);
            } else if (fresh_post as u32) > next_item_size {
                let tail = fresh_post - next_item_size as f64;
                if tail <= 2.0 && open_space < 1.2 * cap {
                    score -= 10.0 * (1.0 - tail / 2.0) * (1.0 - progress);
                }
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
