                }
            }
        }
        // MUTATION (gen 167): fresh-bin residual variance squeeze.
        if fresh_post > 0.0 && !fresh_is_exact && open_bins_count > 2 && mean_residual > 1.0 {
            let dev = (fresh_post - mean_residual).abs() / cap;
            if dev < 0.18 && remaining_frac > 0.1 {
                score -= 8.0 * (1.0 - dev / 0.18) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        // MUTATION (gen 169): fresh-bin mid-tail quadratic pull — mirror the
        // open-bin gradient so a fresh bin whose tail is 3..8 is mildly
        // preferred when it still tiles the next item, keeping the exact
        // lane dominant but rewarding near-tileable opens.
        if next_item_size > 0 && fresh_post > next_item_size as f64 && fragmentation < 0.4 {
            let tail = fresh_post - next_item_size as f64;
            if tail > 3.0 && tail <= 8.0 {
                let open_space = mean_residual * open_bins_count as f64;
                if open_space < 2.0 * cap {
                    score -= 5.0 * (1.0 - (tail - 3.0) / 5.0) * (1.0 - (tail - 3.0) / 5.0)
                        * (0.5 + 0.5 * (1.0 - progress));
                }
            }
        }
        // MUTATION (gen 169): late-stream fresh-bin refusal hardening — when
        // the stream is nearly exhausted, opening a bin that cannot even
        // hold the next item is almost pure waste.
        if remaining_frac < 0.1 && next_item_size > 0 && (fresh_post as u32) < next_item_size {
            score += 40.0 * (1.0 - remaining_frac / 0.1);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
