        if next_item_size > 0 && fresh_post > 0.0 && (fresh_post as u32) < next_item_size {
            let miss = (next_item_size as f64 - fresh_post);
            if miss <= 5.0 {
                let open_space = mean_residual * open_bins_count as f64;
                let slack_pressure = (1.6 * cap - open_space).max(0.0) / (1.6 * cap);
                score += 11.0 * (1.0 - miss / 5.0) * slack_pressure * (0.4 + 0.6 * progress);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
