        }
        // gen 110: demand-scaled open throttle.
        if remaining_frac < 0.3 && fresh_post > 0.25 * cap {
            let est_need = (remaining as f64) * (item_size as f64) * 0.5;
            if open_capacity > 1.3 * est_need {
                score += 24.0 * (open_capacity / (1.3 * est_need)).min(2.0) * (1.0 - remaining_frac / 0.3);
            }
        }
        // MUTATION (gen 170): fresh-bin two-step exactness — widen the tiny
        // tail reward to tail <= 3 and strengthen it when aggregate slack is
        // thin, so fresh bins seed lanes that close exactly in two steps.
        if next_item_size > 0 && fresh_post > 0.0 && fragmentation < 0.45 {
            if (fresh_post as u32) == next_item_size {
                score -= 12.0 * (1.0 - progress);
            } else if (fresh_post as u32) > next_item_size {
                let tail = fresh_post - next_item_size as f64;
                if tail <= 3.0 && open_capacity < 1.4 * cap {
                    score -= 13.0 * (1.0 - tail / 3.0) * (1.0 - progress);
                }
            }
        }
        // MUTATION (gen 170): fresh-bin residual variance squeeze — when
        // opening is unavoidable, prefer a fresh post-residual close to the
        // field's mean residual so leftovers stay homogeneous and reusable.
        if fresh_post > 0.0 && !fresh_is_exact && open_bins_count > 2 && mean_residual > 1.0 {
            let dev = (fresh_post - mean_residual).abs() / cap;
            if dev < 0.18 && remaining_frac > 0.1 {
                score -= 8.0 * (1.0 - dev / 0.18) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
