        }
        // Supply-demand fresh gate.
        if fresh_post > 0.0 && remaining_frac > 0.05 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_demand = (remaining as f64) * (next_item_size.max(1) as f64) * 0.5;
            if open_space > est_demand && fresh_post > 0.25 * cap {
                score += 22.0 * (1.0 - remaining_frac) * (fresh_post / cap - 0.25);
            } else if open_space < 0.6 * est_demand && fragmentation < 0.4 {
                score -= 14.0 * (0.6 - open_space / est_demand.max(1.0)) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // Mean-aligned fresh residual.
        if fresh_post > 0.0 && mean_residual > 4.0 && open_bins_count > 1 && remaining_frac > 0.15 {
            let rel = ((fresh_post - mean_residual) / mean_residual).abs();
            if rel < 0.3 {
                score -= 9.0 * (1.0 - rel / 0.3) * (1.0 - progress);
            }
        }
        // MUTATION (gen 170): fresh-bin two-step exactness — reward openings
        // whose leftover exactly matches, or leaves a tiny tail after, the
        // next item, especially when aggregate slack is thin.
        if next_item_size > 0 && fresh_post > 0.0 && fragmentation < 0.45 {
            let open_space = mean_residual * open_bins_count as f64;
            if (fresh_post as u32) == next_item_size {
                score -= 12.0 * (1.0 - progress);
            } else if (fresh_post as u32) > next_item_size {
                let tail = fresh_post - next_item_size as f64;
                if tail <= 3.0 && open_space < 1.4 * cap {
                    score -= 13.0 * (1.0 - tail / 3.0) * (1.0 - progress);
                }
            }
        }
        // MUTATION (gen 170): fresh-bin residual variance squeeze — when
        // opening is unavoidable, prefer a fresh post-residual close to the
        // field's mean residual so leftovers stay homogeneous and reusable.
        if fresh_post > 0.0 && !fresh_is_exact && open_bins_count > 2 && mean_residual > 1.0 {
            let dev = (fresh_post - mean_residual).abs() / cap;
            if dev < 0.18 && remaining_frac > 0.1 {
                score -= 8.0 * (1.0 - dev / 0.18) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Layered dead-space rewards (lower post_residual = better).
    if post_residual == 0 {
        score -= 980.0;
    } else if post_residual <= 4 {
        score -= 250.0 + 4.2 * (4 - post_residual) as f64;
    } else if post_residual <= 10 {
        score -= 64.0 + 3.6 * (10 - post_residual) as f64;
    } else if post_residual <= 22 {
        score -= 13.5 + 1.5 * (22 - post_residual) as f64;
    } else if post_residual <= 32 {
        score -= 5.0 + 0.7 * (32 - post_residual) as f64;
    } else if post_residual <= 48 {
        score -= 1.2 + 0.22 * (48 - post_residual) as f64;
    } else {
        score -= 1.2 - 0.014 * (post_residual as f64 - 48.0);
    }

    let w = 0.33 + 0.67 * progress * progress;
    score *= w;

    // Lookahead coupling with the next item.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if next_item_size < post_residual {
            let two_step_waste = (post_residual - next_item_size) as f64;
            if two_step_waste <= 8.0 {
                score -= 135.0 - 2.3 * two_step_waste;
            } else {
                score -= 72.0 - 0.58 * two_step_waste;
            }
            if two_step_waste <= 3.0 {
                score -= 48.0;
            }
        } else {
            let miss = (next_item_size - post_residual) as f64;
            score += 0.95 * miss;
            if miss > 26.0 {
                score += 0.55 * (miss - 26.0);
            }
        }
    }

    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
        let boost = 36.0 + 26.0 * scarcity;
        score -= boost * (1.0 - slack / cap) * (0.6 + 0.4 * (1.0 - progress));
        if fitting_bins_count <= 2 {
            score -= 15.0 * (1.0 - slack / cap);
