            }
        }
        if next_item_size > 0 && fresh_post > next_item_size as f64 {
            let chain_post = fresh_post - next_item_size as f64;
            if chain_post <= 4.0 {
                score -= 34.0 * (1.0 - chain_post / 4.0) * (0.5 + 0.5 * (1.0 - progress));
            } else if chain_post <= 10.0 {
                score -= 9.5 * (1.0 - (chain_post - 4.0) / 6.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        if remaining_frac < 0.12 && fresh_post > 0.0 && !fresh_is_exact && mean_residual * open_bins_count as f64 > 3.0 * cap {
            score += 42.0 * (1.0 - remaining_frac / 0.12);
        }
        if fitting_bins_count == 1 && fresh_post > 0.0 && next_item_size > 0 {
            let stranded_here = bin_capacity.saturating_sub(item_size);
            let would_strand = stranded_here < next_item_size;
            if would_strand && stranded_here > 0 && stranded_here <= 8 {
                score -= 32.0 * (1.0 - progress);
            }
        }
        let open_capacity = mean_residual * open_bins_count as f64;
        let per_item_need = cap * 0.5;
        if remaining_frac > 0.25 && open_capacity < per_item_need * open_bins_count.max(1) as f64 * 0.5 {
            score -= 18.0 * (1.0 - progress);
        }
        if next_item_size > 0 && fresh_post > next_item_size as f64 {
            let after_next = fresh_post - next_item_size as f64;
            if after_next > 0.0 && after_next <= 8.0 && fragmentation < 0.5 {
                score -= 20.0 * (1.0 - after_next / 8.0) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        if next_item_size > 0 && fresh_post > 0.0 && (fresh_post as u32) < next_item_size {
            let slack_total = mean_residual * open_bins_count as f64;
            if slack_total > 2.0 * cap {
                score += 26.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && (fresh_post as u32) == next_item_size && fragmentation > 0.3 {
            score -= 44.0 * (0.5 + 0.5 * (1.0 - progress));
        }
        if fresh_post > 0.5 * cap && mean_residual < 0.2 * cap && remaining_frac > 0.3 && open_bins_count > 3 {
            score += 24.0 * (fresh_post / cap - 0.5) * 2.0 * (1.0 - progress);
        }
        if fitting_bins_count <= 1 && fresh_post > 0.45 * cap && next_item_size > 0 {
            let reachable = (next_item_size as f64 / fresh_post).min(1.0);
            if reachable < 0.5 {
                score += 18.0 * (0.5 - reachable) * (1.0 - progress);
            }
        }
        if next_item_size > 0 && fresh_post > 0.0 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 2 && fragmentation < 0.5 {
                score -= 7.0 * ((reps as f64).min(4.0) - 1.0) * (0.4 + 0.6 * (1.0 - progress));
                if rem <= 3 {
                    score -= 5.0 * (1.0 - progress);
                }
            }
        }
        if fresh_post > 0.35 * cap && remaining_frac > 0.2 && mean_residual * open_bins_count as f64 > 4.0 * cap && fragmentation < 0.45 {
            score += 20.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        if remaining_frac < 0.15 && fresh_post > 0.3 * cap {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.35;
            if open_space > est_need {
                score += 55.0 * (1.0 - remaining_frac / 0.15);
            }
        }
        if remaining_frac >= 0.15 && remaining_frac < 0.45 && fresh_post > 0.4 * cap && fragmentation > 0.4 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.45;
            if open_space > est_need {
                score += 28.0 * (1.0 - remaining_frac / 0.45);
            }
        }
        if next_item_size > 1 && fresh_post > 0.0 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 2 && rem == 0 && fragmentation < 0.4 {
                score -= 10.0 * ((reps as f64).min(4.0) - 1.0) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        if remaining_frac >= 0.45 && remaining_frac < 0.5 && fresh_post > 0.45 * cap && fragmentation > 0.5 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (item_size as f64) * 0.55;
            if open_space > est_need {
                score += 22.0 * (1.0 - remaining_frac / 0.5);
            }
        }
        // Demand-aware fresh-bin refusal.
        if remaining_frac >= 0.05 && fresh_post > 0.3 * cap && next_item_size > 0 {
            let open_space = mean_residual * open_bins_count as f64;
            let est_need = (remaining as f64) * (next_item_size as f64) * 0.42;
            if open_space > 1.15 * est_need {
                score += 30.0 * (1.0 - remaining_frac) * (fresh_post / cap - 0.3);
            }
        }
        // Fresh-bin dead-space cap.
        if fresh_post > 0.35 * cap && next_item_size > 0 && (fresh_post as u32) < next_item_size && fragmentation < 0.4 && remaining_frac > 0.15 {
            score += 16.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        // Tileability-aware open.
        if next_item_size > 1 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 3 && rem == 0 && fragmentation < 0.3 {
                score -= 14.0 * ((reps as f64).min(5.0) - 2.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // MUTATION (gen 167): fresh-bin two-step exactness — keep the exact
        // lane and extend the tiny-tail reward to tail <= 3 with a slightly
        // stronger coefficient when aggregate slack is thin.
        if next_item_size > 0 && fresh_post > 0.0 && fragmentation < 0.45 {
            let open_space = mean_residual * open_bins_count as f64;
            if (fresh_post as u32) == next_item_size {
                score -= 12.0 * (1.0 - progress);
            } else if (fresh_post as u32) > next_item_size {
                let tail = fresh_post - next_item_size as f64;
                if tail <= 3.0 && open_space < 1.4 * cap {
                    score -= 13.0 * (1.0 - tail / 3.0) * (1.0 - progress);
                }
            }
        }
        // MUTATION (gen 167): fresh-bin residual variance squeeze — when
        // opening is unavoidable, prefer a fresh post-residual close to the
        // field's mean residual so leftovers stay homogeneous and reusable.
        if fresh_post > 0.0 && !fresh_is_exact && open_bins_count > 2 && mean_residual > 1.0 {
            let dev = (fresh_post - mean_residual).abs() / cap;
            if dev < 0.18 && remaining_frac > 0.1 {
                score -= 8.0 * (1.0 - dev / 0.18) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        // MUTATION (gen 171): mean-anchored fresh-bin alignment — deepen the
        // homogeneity pull: when aggregate slack is thin, a fresh bin whose
        // post-residual matches the field mean lets open bins absorb future
        // items uniformly; reward it proportionally to slack pressure.
        if fresh_post > 0.0 && !fresh_is_exact && open_bins_count > 1 && mean_residual > 1.0 {
            let open_space = mean_residual * open_bins_count as f64;
            if open_space < 2.0 * cap {
                let dev = (fresh_post - mean_residual).abs() / cap;
                if dev < 0.10 {
                    let pressure = 1.0 - open_space / (2.0 * cap);
                    score -= 11.0 * (1.0 - dev / 0.10) * pressure * (0.4 + 0.6 * (1.0 - progress));
                }
            }
        }
        // MUTATION (gen 171): two-step tiling open — when the fresh
        // post-residual minus the next item leaves a tail within 2 of the
        // mean residual, a three-step chain is plausible; reward it when
        // fragmentation is low so new bins become multi-item carriers.
        if next_item_size > 0 && fresh_post > next_item_size as f64 && fragmentation < 0.4 && mean_residual > 1.0 {
            let tail = fresh_post - next_item_size as f64;
            let dev = (tail - mean_residual).abs();
            if dev <= 2.0 {
                score -= 10.0 * (1.0 - dev / 2.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact / near-exact fits (post_residual near 0).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0 + (5.0 - post_residual as f64) * 20.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect 2-step chain: post_residual == next_item_size is ideal.
            let slack = (post_residual as f64 - next_item_size as f64).abs();
            score -= 150.0 - slack.min(60.0);
        } else {
            // Dead space the next item cannot use.
            let unusable = post_residual as f64;
            score += unusable * 0.8 * (unusable / bin_capacity as f64);
        }
    }

    // Penalize leaving residuals that are hard to fill (below typical small item).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // Contextual scaling: late in stream, waste matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.5 * progress;

    // Prefer bins tighter than the mean residual (fill crowded bins first).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // New-bin candidate: only attractive when current fits are poor.
    if bin_residual == bin_capacity {
        // Base penalty so a new bin is chosen only when open-bin scores are high.
        score += 90.0;
        // More attractive early (bins will be reused later) and when many items remain.
        score -= 60.0 * (1.0 - progress);
        // If next item is large, a fresh bin is more flexible.
        if next_item_size >= 50 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
