    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: prefer tight fits (low post residual), with smooth polynomial shaping
    let mut score = x * x * (3.0 - 2.0 * x) * 60.0 + pr * 0.5;

    // Non-linear coupling of post_residual with stream progress:
    // early on, tolerate slack (keep bins flexible); late, demand tightness.
    let progress_coupling = (1.0 - progress) * (pr * pr / cap) * 0.15
        - progress * (pr * pr / cap) * 0.25;
    score += progress_coupling;

    // Penalize dead space that cannot fit the lookahead item (smooth interaction)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            let gap = (nx - pr) / cap;
