pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" is the leftover space
    // Class 0: post_residual == 0 (perfect fit) -> strong reward
    // Class 1: post_residual small (<= 10) -> mild reward
    // Class 2: post_residual in awkward band (11..=30) -> mild penalty
    // Class 3: post_residual large -> handled by base score already
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 6.0;
    } else if post_residual <= 30 {
        score += 4.0;
    }

    // Modulo-10 residue class of post_residual: leftovers that are multiples
    // of 10 pair well with common item sizes (10..80 range multiples)
    let pr_mod = post_residual % 10;
    if pr_mod == 0 && post_residual > 0 {
        score -= 3.0;
    } else if pr_mod != 0 {
        score += 1.5;
    }

    // Lookahead harmony: does next_item_size fit exactly or well in post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0; // chain perfect fit
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 10.0 {
                score -= 8.0; // next item nearly fills leftover
            } else {
                score -= 2.0;
            }
        } else {
            // next item cannot use this bin's leftover: penalize dead space
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // to avoid opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 7.0 + 0.15 * (post_residual as f64);
    }

    // New-bin candidate handling: an empty bin has huge post_residual,
    // which already scores high; add a fixed handicap so it only wins
    // when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 12.0;
        // Early in the stream, opening bins is cheaper; late, consolidate.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
    }

    // Discourage spreading across too many open bins when mean residual
    // is already low (bins are nearly full on average).
    let mean_gap = (mean_residual - post_residual as f64).abs();
    score += 0.05 * mean_gap;

    // Integer-division threshold: reward leaving space in coarse buckets
    // that many item classes can still use (>= 40 = half capacity).
    if post_residual >= 40 {
        score -= 4.0;
    } else if post_residual >= 20 {
        score -= 1.0;
    }

    score
}

