pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Mid-range gaps (10..30) are moderately wasteful.
    else if post_residual >= 10 && post_residual < 30 {
        score += 8.0 * (1.0 - (post_residual as f64 - 10.0) / 20.0);
    }

    // Reward tight fits (small post_residual relative to item size).
    score -= 30.0 * (item_size as f64 / bin_capacity as f64) * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Lookahead: if the next item can fit in the post residual, reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
        // Extra reward if next item nearly fills the gap (good chain fit).
        let gap_use = next_item_size as f64 / post_residual as f64;
        score -= 8.0 * gap_use;
    }
    // Penalize if next item cannot use the leftover gap at all.
    if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bins pressure: many open bins -> encourage consolidation into existing bins.
    score -= (open_bins_count as f64).ln().max(0.0) * 3.0;

    // Mean residual coupling: if this bin's residual is far below mean, it's a good filler target.
    score -= 2.0 * (mean_residual - post_residual as f64).max(0.0) / bin_capacity as f64 * 10.0;

    // New-bin candidate handling: brand-new empty bin has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Only attractive when no existing bin fits well (large dead space elsewhere)
        // or the item is huge and would leave a very small gap in existing bins.
        let new_bin_score = bin_capacity as f64 - item_size as f64;
        // Slight default penalty so existing decent fits win.
        score = new_bin_score + 15.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        } else {
            // Open a new bin if placing in an existing bin would leave a tiny dead gap.
            if post_residual > 0 && post_residual < 10 {
                score -= 60.0;
            }
            // Or if item is large and few bins are open (keep big slots free).
            if item_size >= 60 && open_bins_count <= 2 {
                score -= 20.0;
            }
        }
    }

    score
}

