pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits perfectly in post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0; // perfect two-item chain fill
        } else if post_residual > next_item_size {
            score -= 12.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item cannot fit here: penalize proportional to wasted potential
            score += 8.0 * (1.0 - (post_residual as f64 / next_item_size as f64).min(1.0));
        }
    } else {
        // Last item: prefer tightest fill
        score -= 15.0;
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Penalize large dead space that nothing (min size 1..100 context) can use
    if post_residual > 0 && post_residual < item_size {
        score += 5.0;
    }

    // Perfect closure bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    // Late in the stream: consolidate more aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: discourage opening a new bin unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 10.0 + 0.3 * mean_residual;
    }

    score
}

