        }
        // MUTATION (gen 110): late-stream exact-fill amplifier.
        if progress > 0.75 && post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
            let tail = (post_residual - next_item_size) as f64;
            if tail <= 2.0 {
                score -= 12.0 * (1.0 - tail / 2.0) * (progress - 0.75) / 0.25;
