        // MUTATION (gen 174, borrowed gen 167): dual-step exactness lane —
        // deepen and widen the tiny-tail reward so placements leaving a
        // two-step remainder of <= 3 are strongly preferred.
        if next_item_size > 0 && post_residual > next_item_size {
            let after_next = (post_residual - next_item_size) as f64;
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            if after_next <= 3.0 {
                score -= (21.0 + 10.0 * scarcity) * (1.0 - after_next / 3.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // MUTATION (gen 174, borrowed gen 167): thin-slack spread squeeze —
        // when aggregate open slack is thin, pull post-residuals toward the
        // mean so leftover space stays homogeneous and reusable.
        if post_residual > 0 && fitting_bins_count > 1 {
            let open_space = mean_residual * open_bins_count as f64;
            if open_space < 1.8 * cap && (post_residual as f64) > mean_residual {
                let spread = (post_residual as f64 - mean_residual) / cap;
                score += 3.6 * spread * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        // MUTATION (gen 174): awkward-band refusal — penalize post-residuals
        // in the 5..12 band when the next item cannot use them and slack is
        // abundant elsewhere; diagnosed weakness is dead-space ratio.
        if post_residual > 4 && post_residual < 12 && next_item_size > post_residual
            && mean_residual * open_bins_count as f64 > 1.5 * cap {
            score += 7.5 * (1.0 - (post_residual as f64 - 4.0) / 8.0) * (0.5 + 0.5 * (1.0 - progress));
        }
        // MUTATION (gen 174): late-stream consolidation pull — in the final
        // third, prefer bins whose post-residual is small regardless of the
        // next item, to drain residual variance before the stream ends.
        if progress > 0.66 && post_residual > 0 {
            let pull = (post_residual as f64 / cap).min(1.0);
            score += 4.0 * pull * (progress - 0.66) / 0.34;
        }
    } else {
        // NEW-BIN CANDIDATE branch.
        let fragmentation = (mean_residual / cap) * open_bins_count as f64;
        let huge_item = item_size as f64 > 0.7 * cap;
        let remaining = if total_items > step_index { total_items - step_index } else { 1 };
        let remaining_frac = remaining as f64 / total_items.max(1) as f64;
        let fresh_post = cap - item_size as f64;
        let fresh_is_exact = fresh_post <= 4.0 && fresh_post >= 0.0;

        if fragmentation > 0.55 || (huge_item && open_bins_count > 4) {
            score -= 66.0 + 46.0 * remaining_frac;
        } else if fresh_is_exact {
            score -= 134.0 + 66.0 * remaining_frac;
        } else {
            score += 400.0 - 82.0 * remaining_frac;
            if fitting_bins_count <= 3 && open_bins_count > 2 {
                score -= 30.0 + 18.0 * remaining_frac;
            }
        }

        let fresh_match = (fresh_post - mean_residual).abs() / cap;
        if fresh_match < 0.05 {
            score -= 76.0 * (1.0 - fresh_match / 0.05);
        }
        if remaining_frac < 0.05 && fresh_post > 0.0 && !fresh_is_exact {
            score += 160.0 * (fresh_post / cap);
        }
        if fresh_post > 0.0 && fresh_post <= 22.0 && !fresh_is_exact {
            score -= 26.0 * (1.0 - fresh_post / 22.0);
        }
        if fresh_post > 22.0 && fresh_post <= 40.0 && fragmentation < 0.35 {
            score -= 12.5 * (1.0 - (fresh_post - 22.0) / 18.0);
        }
        if fresh_post > 0.0 && fresh_match < 0.12 && fragmentation < 0.55 {
            score -= 30.0 * (1.0 - fresh_match / 0.12);
        }
        if next_item_size > 0 && fresh_post > 0.0 {
            let fresh_exact_next = (fresh_post as u32) == next_item_size;
            let open_can_next = mean_residual >= next_item_size as f64;
            if fresh_exact_next && !open_can_next && fitting_bins_count <= 2 {
                score -= 52.0 * (1.0 - progress);
            }
            if (fresh_post as u32) < next_item_size && mean_residual > next_item_size as f64 {
                score += 21.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && fresh_post > next_item_size as f64 {
            let chain_post = fresh_post - next_item_size as f64;
            if chain_post <= 4.0 {
                score -= 34.0 * (1.0 - chain_post / 4.0) * (0.5 + 0.5 * (1.0 - progress));
            } else if chain_post <= 10.0 {
                score -= 9.5 * (1.0 - (chain_post - 4.0) / 6.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        if remaining_frac < 0.12 && fresh_post > 0.0 && !fresh_is_exact && mean_residual * open_bins_count as f64 > 3.0 * cap {
            score += 42.0 * (1.0 - remaining_frac / 0.12);
        }
        if fitting_bins_count == 1 && fresh_post > 0.0 && next_item_size > 0 {
            let stranded_here = bin_capacity.saturating_sub(item_size);
            let would_strand = stranded_here < next_item_size;
            if would_strand && stranded_here > 0 && stranded_here <= 8 {
                score -= 32.0 * (1.0 - progress);
            }
        }
        let open_capacity = mean_residual * open_bins_count as f64;
        if remaining_frac > 0.25 && open_capacity < cap * 0.5 * open_bins_count.max(1) as f64 * 0.5 {
            score -= 18.0 * (1.0 - progress);
        }
        if next_item_size > 0 && fresh_post > next_item_size as f64 {
            let after_next = fresh_post - next_item_size as f64;
            if after_next > 0.0 && after_next <= 8.0 && fragmentation < 0.5 {
                score -= 20.0 * (1.0 - after_next / 8.0) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        if next_item_size > 0 && fresh_post > 0.0 && (fresh_post as u32) < next_item_size {
            let slack_total = mean_residual * open_bins_count as f64;
            if slack_total > 2.0 * cap {
                score += 26.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && (fresh_post as u32) == next_item_size && fragmentation > 0.3 {
            score -= 44.0 * (0.5 + 0.5 * (1.0 - progress));
        }
        if fresh_post > 0.5 * cap && mean_residual < 0.2 * cap && remaining_frac > 0.3 && open_bins_count > 3 {
            score += 24.0 * (fresh_post / cap - 0.5) * 2.0 * (1.0 - progress);
        }
        if fitting_bins_count <= 1 && fresh_post > 0.45 * cap && next_item_size > 0 {
            let reachable = (next_item_size as f64 / fresh_post).min(1.0);
            if reachable < 0.5 {
                score += 18.0 * (0.5 - reachable) * (1.0 - progress);
            }
        }
        if next_item_size > 0 && fresh_post > 0.0 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 2 && fragmentation < 0.5 {
                score -= 7.0 * ((reps as f64).min(4.0) - 1.0) * (0.4 + 0.6 * (1.0 - progress));
                if rem <= 3 {
                    score -= 5.0 * (1.0 - progress);
                }
            }
        }
        if fresh_post > 0.35 * cap && remaining_frac > 0.2 && open_capacity > 4.0 * cap && fragmentation < 0.45 {
            score += 20.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        if remaining_frac < 0.15 && fresh_post > 0.3 * cap {
            let est_need = (remaining as f64) * (item_size as f64) * 0.35;
            if open_capacity > est_need {
                score += 55.0 * (1.0 - remaining_frac / 0.15);
            }
        }
        if remaining_frac >= 0.15 && remaining_frac < 0.45 && fresh_post > 0.4 * cap && fragmentation > 0.4 {
            let est_need = (remaining as f64) * (item_size as f64) * 0.45;
            if open_capacity > est_need {
                score += 28.0 * (1.0 - remaining_frac / 0.45);
            }
        }
        if remaining_frac >= 0.05 && fresh_post > 0.3 * cap && next_item_size > 0 {
            let est_need = (remaining as f64) * (next_item_size as f64) * 0.42;
            if open_capacity > 1.15 * est_need {
                score += 30.0 * (1.0 - remaining_frac) * (fresh_post / cap - 0.3);
            }
        }
        if fresh_post > 0.35 * cap && next_item_size > 0 && (fresh_post as u32) < next_item_size && fragmentation < 0.4 && remaining_frac > 0.15 {
            score += 16.0 * (fresh_post / cap - 0.35) * (1.0 - progress);
        }
        if next_item_size > 1 && (fresh_post as u32) >= next_item_size {
            let reps = (fresh_post as u32) / next_item_size;
            let rem = (fresh_post as u32) % next_item_size;
            if reps >= 3 && rem == 0 && fragmentation < 0.3 {
                score -= 14.0 * ((reps as f64).min(5.0) - 2.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        if next_item_size > 0 && fresh_post > next_item_size as f64 {
            let tail = fresh_post - next_item_size as f64;
            if tail > 0.0 && tail <= 4.0 && fitting_bins_count > 1 {
                score -= 10.0 * (1.0 - tail / 4.0) * (1.0 - progress);
            }
        }
        if next_item_size > 0 && fresh_post > 0.4 * cap && (fresh_post as u32) < next_item_size
            && open_capacity > 2.0 * cap && remaining_frac > 0.25 {
            score += 22.0 * (fresh_post / cap - 0.4) * (1.0 - progress);
        }
        // gen 94: fresh-bin exact-closure bonus.
        if next_item_size > 0 && (fresh_post as u32) == next_item_size && fragmentation <= 0.3 {
            score -= 18.0 * (0.4 + 0.6 * (1.0 - progress));
        }
        // gen 94: fresh-bin strand guard.
        if next_item_size > 0 && fresh_post > 0.3 * cap && (fresh_post as u32) < next_item_size
            && (mean_residual as u32) >= next_item_size && fitting_bins_count > 1 && remaining_frac > 0.1 {
            score += 14.0 * (fresh_post / cap - 0.3) * (1.0 - progress);
        }
        // gen 102: fresh-bin mid-gap refusal.
        if next_item_size > 0 && fresh_post > 12.0 && fresh_post <= 24.0 && fitting_bins_count > 1 {
            let mid = (fresh_post - 12.0) / 12.0;
            score += 7.0 * mid * (0.35 + 0.65 * progress);
        }
        // gen 102: fresh-bin residual-harmony bonus.
        if fresh_post > 0.0 && fresh_match < 0.08 && remaining_frac > 0.1 {
            score -= 10.0 * (1.0 - fresh_match / 0.08) * (0.4 + 0.6 * (1.0 - progress));
        }
        // MUTATION (gen 110): fresh-bin late exact-closure amplifier.
        if progress > 0.75 && next_item_size > 0 && (fresh_post as u32) >= next_item_size {
            let tail = (fresh_post as u32 - next_item_size) as f64;
            if tail <= 2.0 {
                score -= 20.0 * (1.0 - tail / 2.0) * (progress - 0.75) / 0.25;
            }
        }
        // MUTATION (gen 110): demand-scaled open throttle.
        if remaining_frac < 0.3 && fresh_post > 0.25 * cap {
            let est_need = (remaining as f64) * (item_size as f64) * 0.5;
            if open_capacity > 1.3 * est_need {
                score += 24.0 * (open_capacity / (1.3 * est_need)).min(2.0) * (1.0 - remaining_frac / 0.3);
            }
        }
        // MUTATION (gen 174, borrowed gen 167): fresh-bin two-step exactness —
        // widen the tiny-tail reward to tail <= 3 and strengthen when slack
        // is thin, so opened bins seed tileable lanes.
        if next_item_size > 0 && fresh_post > 0.0 && fragmentation < 0.45 {
            let open_space = mean_residual * open_bins_count as f64;
            if (fresh_post as u32) == next_item_size {
                score -= 12.0 * (1.0 - progress);
            } else if (fresh_post as u32) > next_item_size {
                let tail = fresh_post - next_item_size as f64;
                if tail <= 3.0 && open_space < 1.4 * cap {
                    score -= 13.0 * (1.0 - tail / 3.0) * (1.0 - progress);
                }
            }
        }
        // MUTATION (gen 174, borrowed gen 167): fresh-bin residual variance
        // squeeze — prefer fresh post-residuals close to the field's mean so
        // leftovers stay homogeneous and reusable.
        if fresh_post > 0.0 && !fresh_is_exact && open_bins_count > 2 && mean_residual > 1.0 {
            let dev = (fresh_post - mean_residual).abs() / cap;
            if dev < 0.18 && remaining_frac > 0.1 {
                score -= 8.0 * (1.0 - dev / 0.18) * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        // MUTATION (gen 174): fresh-bin awkward-band guard — refuse opening
        // bins whose fresh post-residual lands in the low-utility 5..12 band
        // when plenty of usable open slack remains.
        if fresh_post > 4.0 && fresh_post < 12.0 && next_item_size > 0
            && (fresh_post as u32) < next_item_size
            && open_capacity > 1.5 * cap && remaining_frac > 0.1 {
            score += 9.0 * (1.0 - (fresh_post - 4.0) / 8.0) * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits via post_residual (already in score).

    // Harmonic class of post_residual: dead-space buckets.
    // Residuals that are "usable" (>= typical small item) are less penalized.
    let pr = post_residual;
    if pr == 0 {
        score -= 30.0; // perfect closure
    } else if pr < 10 {
        score += 25.0; // tiny dead space, unusable
    } else {
        // modulo-10 class: residuals divisible by 10 align with item grid
        if pr % 10 == 0 {
            score -= 6.0;
        }
        // integer-division harmonic classes: pr / 10 gives usable slots
        let slots = pr / 10;
        score -= slots as f64 * 2.0;
    }

    // Lookahead coupling: does post_residual fit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // exact or near-exact match with lookahead is gold
            let gap = post_residual - next_item_size;
            if gap == 0 {
                score -= 20.0;
            } else if gap < 10 {
                score -= 8.0;
            } else {
                score -= 4.0;
            }
        } else {
            // bin becomes dead for the next item
            score += 8.0;
        }
    } else {
        // last item: closing bins is free win
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins
    // offer poor fits. Penalize the fresh bin mildly, more when many bins fit.
    if bin_residual == bin_capacity {
        score += 20.0 + 5.0 * (fitting_bins_count as f64).min(6.0);
        // late in stream, opening new bins is cheaper (fewer future regrets)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    // Spread control: prefer bins below mean residual (consolidation)
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Prefer bins among many open ones (keeps open count low)
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Layered dead-space rewards (lower post_residual = better).
    if post_residual == 0 {
        score -= 980.0;
    } else if post_residual <= 4 {
        score -= 250.0 + 4.2 * (4 - post_residual) as f64;
    } else if post_residual <= 10 {
        score -= 64.0 + 3.6 * (10 - post_residual) as f64;
    } else if post_residual <= 22 {
        score -= 13.5 + 1.5 * (22 - post_residual) as f64;
    } else if post_residual <= 32 {
        score -= 5.0 + 0.7 * (32 - post_residual) as f64;
    } else if post_residual <= 48 {
        score -= 1.2 + 0.22 * (48 - post_residual) as f64;
    } else {
        score -= 1.2 - 0.014 * (post_residual as f64 - 48.0);
    }

    let w = 0.33 + 0.67 * progress * progress;
    score *= w;

    // Lookahead coupling with the next item.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if next_item_size < post_residual {
            let two_step_waste = (post_residual - next_item_size) as f64;
            if two_step_waste <= 8.0 {
                score -= 135.0 - 2.3 * two_step_waste;
            } else {
                score -= 72.0 - 0.58 * two_step_waste;
            }
            if two_step_waste <= 3.0 {
                score -= 48.0;
            }
