    let progress_penalty = norm_pr * norm_pr * (1.0 + 2.0 * progress);
    score += progress_penalty;

    // Smooth tight-fit reward: quadratic decay of reward as post_residual grows
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (item_size as f64 / cap);

    // Lookahead: reward if next item fits the post-residual, penalize otherwise
