pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo 10: residuals divisible by 10
    // (or by 25) are "harmonic" and pair well with typical item sizes.
    let post = post_residual;
    if post > 0 {
        let class = post % 10;
        let harmonic = (class == 0) as i32
            + (post % 25 == 0) as i32
            + (post % 20 == 0) as i32;
        score -= 6.0 * harmonic as f64;

        // Dead-space penalty: tiny unusable residuals.
        if post < 10 {
            score += 25.0; // nearly dead space
        } else if post <= 15 {
            score += 8.0;
        }

        // Non-linear coupling: reward residuals that can host the next item.
        if next_item_size > 0 {
            if post >= next_item_size {
                score -= 5.0;
                // harmonic chain: post - next also leaves a nice residual
                let chain = post - next_item_size;
                if chain % 10 == 0 { score -= 4.0; }
            } else {
                score += (next_item_size - post) as f64 * 0.35;
            }
        }
    } else {
        // Perfect fill: strong reward.
        score -= 30.0;
    }

    // Integer-division threshold on item_size vs residual: tight fits rewarded.
    let ratio = item_size as f64 / bin_residual as f64;
    if ratio > 0.85 {
        score -= 12.0;
    } else if ratio > 0.6 {
        score -= 5.0;
    } else if ratio < 0.25 {
        score += 4.0; // dumping small items into big residual is wasteful
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when existing residuals are poor
    // and the item is large.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 40.0
            + 20.0 * (1.0 - pressure)
            - 15.0 * (item_size as f64 / bin_capacity as f64)
            - 10.0 * progress;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 5.0; // large next item: fresh bin useful
        }
    }

    // Mild tie-break toward bins below mean residual (consolidating space).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

