}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item
    // (1..=100 range, min item = 1) are pure waste. Penalize tiny gaps hard.
    if post_residual < 1 {
        score += 1000.0; // impossible, shouldn't happen, but guard
    }
    if post_residual > 0 && post_residual < 10 {
        // unusable dead space under typical minimum item size
        score += 40.0 + (10 - post_residual) as f64 * 6.0;
    } else if post_residual < 20 {
        // near-dead zone: only very small items can use it
        score += 12.0;
    }

    // Reward tight fits: fraction of bin consumed by this placement.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_frac;

    // Reward exact / near-exact closure of the bin.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 {
        score -= 45.0;
    } else if fitting_bins_count > 1 {
        // with multiple options, mildly prefer keeping options open
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Open-bin pressure: when many bins are open, discourage spreading;
    // penalize placements that leave awkward residuals relative to the mean.
    let open_pressure = open_bins_count as f64;
    score += 0.15 * open_pressure * (post_residual as f64 / bin_capacity as f64);

    // If next item fits exactly in the post residual, reward this placement
    // (chained fit). If next item cannot fit post residual but could fit
    // elsewhere, mild penalty for blocking.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size < post_residual {
            score -= 10.0;
        } else {
            score += 8.0;
        }
    }

    // Mean-residual coupling: placing into a bin far below mean residual
    // (i.e., using a nearly-full bin) is good; using a very empty bin wastes it.
    let dev = mean_residual - post_residual as f64;
    score += 0.05 * dev;

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Prefer new bin only when existing fits are terrible:
        // add a moderate opening cost so it's chosen only if open-bin
        // placements carry heavy dead-space penalties.
        score += 55.0;
        // Late in the stream, opening new bins is cheaper (fewer future regrets).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * progress;
    }

    score
}

