        }
        // MUTATION (gen 178): dual-step exactness lane — widened to tail <= 4
        // and slightly deepened so that placements leaving a tiny two-step
        // remainder are preferred more strongly, compressing dead space.
        if next_item_size > 0 && post_residual > next_item_size && bin_residual != bin_capacity {
            let after_next = (post_residual - next_item_size) as f64;
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            if after_next <= 4.0 {
                score -= (23.0 + 11.0 * scarcity) * (1.0 - after_next / 4.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // MUTATION (gen 178): mean-residual pull toward tight reuse — widen
        // the thin-slack trigger to 2.0x cap and scale the penalty by the
        // residual spread to squeeze residual variance harder.
        if post_residual > 0 && fitting_bins_count > 1 {
