    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.25 * next_item_size as f64;
    } else if next_item_size > 0 {
        // Dead space relative to the next item: penalize unusable gap.
        score += 0.35 * (next_item_size.saturating_sub(post_residual)) as f64;
    }

    // Compare post_residual against mean residual across open bins:
    // leaving more than average residual wastes capacity.
    if post_residual as f64 > mean_residual {
        score += 0.2 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.15 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless nothing decent exists.
    if bin_residual == bin_capacity {
        score += 35.0
            - 5.0 * (open_bins_count as f64).ln().max(0.0)
            + 0.1 * item_size as f64;
