    // Last-chance bin bonus: strongly favor when only one fitting bin exists
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - prn);
    }

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0 * (1.0 - (next_item_size as f64 / pr).abs());
