pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: bins whose leftover falls into "usable"
    // classes (multiples of small sizes) are rewarded.
    let pr = post_residual;
    if pr > 0 {
        let class_bonus = if pr % 10 == 0 {
            8.0
        } else if pr % 5 == 0 {
            4.0
        } else if pr % 4 == 0 {
            2.5
        } else if pr % 3 == 0 {
            1.0
        } else {
            0.0
        };
        score -= class_bonus;

        // Dead-space penalty: tiny unusable remainders are bad unless exact.
        if pr < 10 && pr % 10 != 0 {
            score += (10 - pr) as f64 * 1.5;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 25.0;
    }

    // Integer-division threshold on post_residual: leftover in [10, 30] is a
    // "sweet zone" for typical small items; large leftover wastes capacity.
    let sweet = pr / 10; // 0..=10
    match sweet {
        1 | 2 | 3 => score -= 6.0,
        0 => score += 3.0, // near-full bin is fine but no flexibility
        _ => score += (sweet as f64 - 3.0) * 1.2, // big leftover penalty
    }

    // Lookahead coupling: if next item fits the post-residual exactly or well,
    // reward this placement (chaining).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 15.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / cap);
            // Harmonic class of the chain remainder
            let chain = pr - next_item_size;
            if chain % 5 == 0 { score -= 2.0; }
        } else {
            // Next item won't fit here; mildly penalize leaving a stranded gap.
            score += (next_item_size - pr) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only prefer opening a new bin when existing
    // bins are crowded or this is a huge item early in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowding = mean_residual / cap;
        let big_item = item_size as f64 > 0.7 * cap;
        let new_bin_bonus = if big_item && crowding < 0.25 {
            -12.0
        } else if crowding < 0.15 && progress < 0.5 {
            -5.0
        } else {
            12.0 + open_bins_count as f64 * 0.3
        };
        score += new_bin_bonus;
    }

    // Mild global regularization: prefer filling bins with below-average residual
    // (keeps residual distribution tight).
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.05;

    // Late-stream squeeze: waste matters more near the end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.25 * progress;

    score
}

