pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest plausible item (<= 20) are "dead space" -> heavy penalty.
    if post_residual > 0 && post_residual < 20 {
        score += 40.0;
    } else if post_residual >= 20 && post_residual < 35 {
        // Moderately awkward gap: partial penalty proportional to awkwardness.
        score += (35.0 - post_residual as f64) * 1.5;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 15.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage proliferation of bins unless placement is good.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 1.2 * (0.5 + 0.5 * progress);

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post residual blocks the next item: mild penalty scaled by how close it is.
        score += 6.0;
    }

    // New-bin candidate handling: only attractive when existing bins are poor fits
    // (many open bins with large mean residual spread, or item is large).
    if bin_residual == bin_capacity {
        let base = 55.0;
        // Opening a new bin is better late in the stream with many fragmented bins.
        let penalty = base
            + open_bins_count as f64 * 2.0
            + mean_residual * 0.3;
        // If item is large and unlikely to fit elsewhere nicely, ease new-bin cost.
        let ease = if item_size > 60 { 25.0 } else { 0.0 };
        score += penalty - ease;
    }

    score
}

