    let dev = bin_residual as f64 - mean_residual;
    if dev > 0.0 {
        score += 0.15 * dev;
    } else {
        score -= 0.05 * dev.abs();
    }

    // Open-bin pressure: discourage spreading across too many bins.
    score += 0.5 * open_bins_count as f64;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // reward this placement strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual - next_item_size < 10 {
            // next item leaves another dead gap -> penalize
            score += 10.0;
        } else {
            score -= 5.0;
        }
    }

    // New-bin candidate handling: an empty bin should only win when no open
    // bin offers a good fit. Make the empty bin moderately unattractive so
    // only genuinely poor fits in existing bins trigger opening a new one.
    if bin_residual == bin_capacity {
