pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual is good).
    score += 0.5 * (post_residual as f64 / bin_capacity as f64).powi(3) * 100.0;

    // Lookahead: if the next item fits in the post residual, reward this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Post residual too small for the next item: penalize dead space.
            score += 8.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // With many fitting bins, prefer tighter fits even more.
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate logic: only attractive when existing fits are poor
    // (large post_residual waste) or the item would leave a tiny unusable gap.
    if bin_residual == bin_capacity {
        let gap_threshold = 10.0;
        let waste = post_residual as f64;
        if fitting_bins_count == 0 {
            // No open bin fits: opening is mandatory.
            score -= 100.0;
        } else if waste < gap_threshold {
            // Existing bins would leave a near-dead gap; prefer a fresh bin.
            score -= 30.0;
        } else {
            // Keep new bins closed when reasonable fits exist.
            score += 40.0 + 0.3 * open_bins_count as f64;
        }
    }

    // Time-horizon coupling: early in the stream, be more willing to spread items
    // across bins (open more); late in the stream, consolidate tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual deviates from the mean in a useful way:
    // bins with residual larger than mean can absorb odd items later.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // Mild preference for keeping the number of open bins manageable.
    score += 0.2 * open_bins_count as f64;

    // Penalize leaving residuals that are awkward (small but nonzero).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

