    // residual dead-space ratio weakness is squeezed from both ends.
    if bin_residual != bin_capacity && post_residual > 0 {
        let dead_frac = post_residual as f64 / cap;
        if dead_frac > 0.06 && dead_frac <= 0.14 {
            let open_space = mean_residual * open_bins_count as f64;
            let abundance = (open_space / (3.0 * cap)).min(1.0);
            let grad = (dead_frac - 0.06) / 0.08;
