pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual (integer division thresholds) ---
    let post = post_residual as i64;
    let cap = bin_capacity as f64;

    // Dead-space classes: post_residual in [1..=9] is nearly unusable (min item ~1),
    // [10..=19] usable only by tiny items. Penalize by class.
    let dead_class = match post_residual {
        0 => -3.0,             // perfect fit -> strongly reward
        1..=9 => 6.0,          // near-dead space
        10..=19 => 3.0,        // semi-dead
        20..=29 => 1.0,
        30..=49 => 0.0,
        50..=69 => -1.0,       // roomy enough for medium items
        _ => -2.0,             // still half-full: versatile
    };
    score += dead_class;

    // Modulo-10 harmonic bonus: residuals that are multiples of 10 align with
    // typical item sizes drawn from a 10-granularity grid.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 2.0;
    }
    // Exact half-capacity residual is a "harmonic" sweet spot.
    if post_residual * 2 == bin_capacity {
        score -= 1.5;
    }

    // --- Lookahead coupling: does next_item_size fit the post_residual? ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Chain fit: reward, scaled by how snugly next item nests.
            let snug = 1.0 - (post_residual - next_item_size as i64) as f64 / cap;
            score -= 2.0 + 3.0 * snug;
        } else {
            // Next item won't fit here after placement -> mild penalty,
            // stronger if this residual is in a dead class.
            score += (next_item_size - post_residual as u32) as f64 * 0.05;
        }
    } else {
        // Last item: prefer tightest fit overall; post_residual base already does this.
        score -= 1.0;
    }

    // --- Last-chance bin: if this is the only fitting bin, avoid opening a new bin ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 4.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing bins fit poorly
        // (large post_residual would be wasted) or few bins are open.
        let waste_pressure = (post_residual as f64 / cap) * 5.0;
        let scarcity = if open_bins_count < 4 { 3.0 } else { 0.0 };
        score += 8.0 - waste_pressure - scarcity;
    }

    // --- Fraction-of-capacity coupling on item size ---
    let frac = item_size as f64 / cap;
    // Large items (>0.6 of capacity) should go into the fullest possible bin.
    if frac > 0.6 {
        score -= 2.0 * frac;
    }

    // Stream progression: early on, be conservative with bin openings.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 3.0 * (1.0 - progress);
    }

    // Mean-residual context: if this bin is far below mean residual (i.e. it is
    // the emptiest), mildly deprioritize it so fuller bins get used first.
    let dev = mean_residual - bin_residual as f64;
    score += 0.05 * dev;

    score
}

