    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // for any future item (min item size assumed ~1, but practical dead zone
    // emerges from distribution) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - (post_residual as f64) * 4.0; // small gaps are worst
    }

    // Perfect fit is maximally rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // over opening a new bin, scaled by how well it fits.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless the item is large
    // or many bins already exist and fits are poor.
    if bin_residual == bin_capacity {
        score += 15.0;
        // If the next item is large, reserving a fresh bin can be good.
        if next_item_size > 0 && (next_item_size as f64) > 0.7 * (bin_capacity as f64) {
            score -= 10.0;
        }
        // Early in the stream, opening bins is cheaper.
        score -= 10.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
    }

    // Open-bin pressure: when many bins are open, tighten packing by
    // preferring bins whose residual is close to the item size.
    if open_bins_count > 3 {
        score += (mean_residual - post_residual as f64).abs() * 0.3;
        score += open_bins_count as f64 * 0.5;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // strongly favor this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here anyway; slight reward for larger post_residual
        score -= (post_residual as f64) * 0.05;
    }

    score
}

