pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: post residual, with smooth polynomial coupling to stream progress.
    // Early on, prefer tight fits (penalize large post_residual); later, dead space
    // matters less, so the effective weight on pr_norm shrinks smoothly.
    let mut score = pr_norm * (1.0 - 0.5 * progress * progress) * cap;

    // Quadratic dead-space penalty: residuals that are too small to hold typical
    // future items become waste. Coupled with progress via smooth term.
    let dead = pr_norm * pr_norm;
    score += 30.0 * dead * (1.0 - progress);

    // Last-chance bonus: strongly favor the only fitting bin to avoid opening a bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress);
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 12.0 * (nx / cap);
        } else {
            // smooth penalty for leaving space the next item can't use
            score += 8.0 * (1.0 - pr / nx.max(1.0)) * (nx / cap);
