    }

    // Mild penalty when bin residual deviates from mean residual (balance pressure),
    // with smooth non-linear saturation.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev.abs() / (1.0 + dev.abs());

    // Encourage filling bins when many bins are open.
    score += 3.0 * (open_bins_count as f64) / (1.0 + open_bins_count as f64) * pr_norm;

    // New-bin candidate: neutral-ish baseline so it's chosen only when placements
    // in open bins score poorly.
    if bin_residual == bin_capacity {
        score += 10.0 + 15.0 * progress;
    }

    score
}

