pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that can never fit even the
    // smallest item (1..10) are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 4.0;
    }
    // Small-but-usable residuals are risky dead space too: penalize mildly.
    else if post_residual > 0 && post_residual < 25 {
        score += (25 - post_residual) as f64 * 1.5;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / (bin_residual as f64).max(1.0);
    score -= tightness * 15.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless the
    // fit is excellent; encourage consolidating into existing bins.
    score += open_bins_count as f64 * 1.2;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits the post-residual well, reward this
    // placement; if it would be blocked, penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= (post_residual - next_item_size).min(20) as f64 * 0.8;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 8.0;
        }
    }

    // New-bin candidate: only attractive when existing bins are crowded
    // (high mean residual) or this bin is a poor host.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = mean_residual / bin_capacity as f64;
        // Base penalty keeps new bins as a fallback; reduced when bins are
        // nearly full or many bins are open and fragmented.
        score += 55.0 - crowding * 30.0 - (open_bins_count as f64).min(20.0) * 0.5 - progress * 5.0;
