pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: fit that leaves small residue is good.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 0.6 * tightness * (item_size as f64);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let leftover_after_next = post_residual - next_item_size;
            score -= 0.35 * (next_item_size as f64);
            if leftover_after_next == 0 {
                score -= 25.0;
            }
        } else {
            // Post residual too small for lookahead item: penalize dead space.
            score += 0.25 * (post_residual as f64);
        }
    }

    // Last chance: this is the only fitting bin -> strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Spread pressure: prefer bins below mean residual (keeps bins balanced-ish),
    // but penalize bins far above mean (fragmentation).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.08 * dev;

    // Time horizon: early on, be more willing to open new bins (exploit future),
    // late in stream, squeeze everything into open bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty so it's only chosen when fits are poor.
        let mut new_bin_score = bin_capacity as f64 + 30.0;
        // Late in stream, opening new bins is more acceptable (residuals are small).
        new_bin_score -= 25.0 * progress;
        // If many open bins, opening yet another adds management cost.
        new_bin_score += 0.5 * open_bins_count as f64;
        // If this bin is a new bin but the item is huge, prefer it over wasting space.
        if (item_size as f64) > 0.75 * (bin_capacity as f64) {
            new_bin_score -= 10.0;
        }
        score = new_bin_score;
    } else {
        // Existing bin: slight discount late in stream to consolidate.
        score -= 5.0 * progress;
    }

    score
}

