pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: reward residuals that belong to
    // "usable" classes (divisible into common small item sizes).
    let pr = post_residual;
    if pr > 0 {
        // Class 1: perfectly divisible residuals (dead-space-free for small items)
        if pr % 10 == 0 {
            score -= 8.0;
        } else if pr % 5 == 0 {
            score -= 4.0;
        }
        // Class 2: residuals in the awkward 1..=9 band are nearly dead space
        if pr < 10 {
            score += 20.0;
        }
        // Class 3: quantize post-residual into capacity-fraction bands
        let frac = pr as f64 / bin_capacity as f64;
        if frac > 0.5 {
            score -= 6.0;
        } else if frac > 0.25 {
            score -= 2.0;
        } else {
            score += 3.0;
        }
    } else {
        // Perfect fill: strongly reward
        score -= 50.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // this is an excellent placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
        let slack = post_residual - next_item_size;
        if slack % 10 == 0 {
            score -= 4.0;
        }
        if slack < 10 {
            score += 6.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post-residual too small for the next item: penalize dead space creation
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // item fits poorly everywhere else. The empty-bin call has post_residual ==
    // bin_residual == bin_capacity, which the bands above already score as
    // frac=1.0 (-6). Add extra penalty scaled by how well the item would fit.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        // Tight items (near full bins) justify a new bin; loose items do not.
        if tightness > 0.9 {
            score -= 10.0;
        } else {
            score += 25.0 * (1.0 - tightness);
        }
    }

    // Mean-residual pressure: when open bins are already quite full on average,
    // prefer spreading load (mild new-bin encouragement).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if mean_residual < 15.0 && bin_residual == bin_capacity {
        score -= 5.0 * progress;
    }

    // Small bonus for using older/busier bins to keep open bin count low
    score += open_bins_count as f64 * 0.05;

    score
}

