pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post_residual), with non-linear penalty on waste.
    let mut score = pr + 60.0 * norm_pr * norm_pr;

    // Smooth polynomial coupling of waste with stream progress:
    // early on, waste is cheaper; late in the stream, punish residual dead space harder.
    let prog_term = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += 45.0 * prog_term * norm_pr * (1.0 - norm_pr);

    // Penalize bins whose residual deviates badly from the mean residual (non-linear).
    let dev = pr - mean_residual;
    score += 0.015 * dev * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 80.0 + 30.0 * prog_term;
    } else {
        // mild preference for less crowded choice among many fitting bins
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead coupling: reward leaving a residual that still fits the next item,
    // with a smooth quadratic decay of the reward as leftover shrinks toward zero.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let slack = pr - nx;
            let fit_quality = 1.0 - (slack / cap) * (slack / cap);
            score -= 35.0 * fit_quality;
        } else {
            // residual cannot host next item: smooth penalty scaled by how far off
            let gap = (nx - pr) / cap;
            score += 25.0 * gap;
        }
    }

    // Slight incentive to consolidate into existing bins as the stream matures.
    score += (open_bins_count as f64).ln().max(0.0) * (1.0 + 3.0 * prog_term);

    // New-bin candidate handling: an empty bin gets a neutral-high score unless
    // no open bin fits well; make empty-bin score depend smoothly on item size.
    if bin_residual == bin_capacity {
        let tight = item_size as f64 / cap;
        score = cap * (1.0 - prog_term * 0.4) + 40.0 * tight * (1.0 - tight);
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

