pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the resulting residual: classify dead space into
    // "usable" buckets (multiples of common item sizes) vs "waste".
    let harmonic_bonus = |r: u32| -> f64 {
        let mut bonus = 0.0;
        for m in [10u32, 20, 25, 50] {
            if r % m == 0 && r > 0 {
                bonus += 6.0 * (r as f64 / m as f64).min(4.0);
            }
        }
        if r % 5 == 0 && r > 0 { bonus += 2.0; }
        bonus
