    score -= harmonic_bonus(post_residual);

    // Penalize tiny unusable residuals (< 10 cannot hold any item)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Lookahead: reward residuals that can still host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.1 * next_item_size as f64;
    } else if next_item_size > 0 && next_item_size <= bin_residual && post_residual < next_item_size {
        // We consume the only space that could host the next item
        score += 10.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New empty bin candidate: penalize mildly so we prefer existing bins,
    // but allow opening when current bin fit is very poor (large waste class)
    if bin_residual == bin_capacity {
        score += 12.0;
        // If item is large relative to capacity, opening fresh is fine
        if item_size > bin_capacity / 2 {
