pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: prefer tight fits (small post_residual already captured by base term).

    // 2-step lookahead: strongly reward bins where the NEXT item also fits
    // into the resulting residual (perfect chain packing).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward proportional to how well next item consumes post_residual
            let slack_after_next = post_residual - next_item_size;
            score -= 40.0 + 0.5 * slack_after_next as f64;
        } else {
            // Next item won't fit here: penalize large dead space
            let gap = next_item_size - post_residual;
            score += 0.6 * gap as f64;
        }
    }

    // Penalize post_residuals that fall into the "unusable" zone:
    // too small for typical items (1..100 unknown, use conservative small threshold)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Relative-to-mean coupling: bins tighter than the mean are better targets.
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Discourage opening new bins when reasonable open bins exist,
    // but allow it when open bins are all crowded (mean residual low).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = mean_residual / bin_capacity as f64;
        // New bin is attractive only if existing bins are very full
        score += 15.0 * crowding - 10.0 * (1.0 - crowding) + 5.0 * progress;
    }

    // Mild preference for filling fuller bins when many bins are open
    score += 0.1 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);

    score
}

