    let mut score = post_residual as f64;

    // Tight fit reward: quadratic penalty on wasted space.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Harmonic class: post_residual divisible by common size classes (10/20/25/50)
    // means leftover is reusable by typical items -> reward.
    if post_residual >= 10 && (post_residual % 10 == 0 || post_residual % 25 == 0) {
        score -= 8.0;
    }
    if post_residual > 0 && post_residual < 10 {
        // Dead space: unusable for items >= 10 (or >= 1 under new range) -> penalize
        score += 25.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
        if post_residual - next_item_size < 10 {
            score -= 10.0; // chain completes into near-perfect fit
        }
    } else if next_item_size > 0 {
        // Next item cannot use the leftover -> leftover likely wasted.
        score += (next_item_size as f64).min(post_residual.max(1) as f64) * 0.0;
        score += 6.0;
    }

    // Last chance: only this bin fits the item -> strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // current bin fits are poor and the item is large.
    if bin_residual == bin_capacity {
        // Base penalty so new bins are not opened frivolously.
        score += 55.0;
        // Large items pack better in a fresh bin.
        score -= (item_size as f64 / bin_capacity as f64) * 30.0;
        // If existing bins are mostly full (low mean residual), fresh bin is fine.
        if mean_residual < item_size as f64 {
            score -= 25.0;
        }
        // Late in the stream, avoid opening bins unless necessary.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 15.0;
        // If many bins fit the item, discourage new bin.
        score += (fitting_bins_count as f64) * 10.0;
    }

    // Prefer filling already-open bins when many are open (bin count control).
    score += open_bins_count as f64 * 0.5;

    // Slight preference for bins with residual close to mean (balanced packing).
    score -= 2.0 * (-( (bin_residual as f64 - mean_residual).abs() ) / 50.0).exp();

    score
}

