    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Penalize dead space more strongly as it approaches unusable sizes.
    let pr = post_residual as f64;
    if pr > 0.0 {
        score += (pr / cap).powi(3) * cap * 0.8;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.15 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // post-residual wasted relative to next item
        score += 4.0;
    }

    // Last-chance bonus: only this bin fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Crowding penalty: prefer bins tighter than average.
    score += (bin_residual as f64 - mean_residual) * 0.35;

    // Time horizon: early on, be liberal about opening new bins; late, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses.
        score += 8.0 + 30.0 * progress;
        // But if no open bin fits well, allow new bin early.
        if fitting_bins_count == 0 {
            score -= 20.0 * (1.0 - progress);
